export interface Character {
  id: string;
  name: string;
  defaultDescription: string;
  imageSrc: string | null; // Local object URL
  rpgColor: string; // Hex color for the sprite on the map
}

export interface SceneCharacterConfig {
  characterId: string;
  roleInScene: string; // Specific behavior/goal for this scene
}

export interface Scene {
  id: string;
  name: string;
  backgroundSrc: string | null; // Local object URL
  description: string; // The scenario setup
  goal: string; // The win condition to move to next scene
  characters: SceneCharacterConfig[];
}

export interface ChatMessage {
  sender: 'user' | 'model' | 'system';
  characterId?: string; // If model, which character?
  text: string;
  timestamp: number;
}

export interface GameState {
  currentSceneIndex: number; // Used inside VN Mode
  history: ChatMessage[];
  isProcessing: boolean;
  gameOver: boolean;
}

export interface AIResponse {
  characterResponses: {
    characterId: string;
    text: string;
  }[];
  sceneGoalReached: boolean;
  sceneTransitionReason?: string;
}

export interface RPGState {
  playerX: number;
  playerY: number;
  completedSceneIds: string[];
}

export interface GameSaveData {
  rpgState: RPGState;
  vnState: GameState | null; // Null if saved while on map
  timestamp: number;
}

import React, { useState } from 'react';
import { Plus, Trash2, Image as ImageIcon, User, Target, Save, PlayCircle, RotateCcw } from 'lucide-react';
import { Character, Scene, SceneCharacterConfig } from '../types';
import { Button } from './ui/Button';

interface EditorProps {
  characters: Character[];
  scenes: Scene[];
  onUpdateCharacters: (chars: Character[]) => void;
  onUpdateScenes: (scenes: Scene[]) => void;
  onPlay: () => void;
  onSaveProject: () => void;
  hasSaveGame: boolean;
  onContinueGame: () => void;
}

export const Editor: React.FC<EditorProps> = ({
  characters,
  scenes,
  onUpdateCharacters,
  onUpdateScenes,
  onPlay,
  onSaveProject,
  hasSaveGame,
  onContinueGame
}) => {
  const [activeTab, setActiveTab] = useState<'chars' | 'scenes'>('chars');

  // --- Character Handlers ---
  const addCharacter = () => {
    const newChar: Character = {
      id: crypto.randomUUID(),
      name: 'New Character',
      defaultDescription: 'A friendly helper.',
      imageSrc: null,
      rpgColor: '#ef4444', // Default Red
    };
    onUpdateCharacters([...characters, newChar]);
  };

  const updateCharacter = (id: string, updates: Partial<Character>) => {
    onUpdateCharacters(characters.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const handleCharImageUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCharacter(id, { imageSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  // --- Scene Handlers ---
  const addScene = () => {
    const newScene: Scene = {
      id: crypto.randomUUID(),
      name: `Scene ${scenes.length + 1}`,
      backgroundSrc: null,
      description: 'You are in a quiet room.',
      goal: 'Say hello.',
      characters: [],
    };
    onUpdateScenes([...scenes, newScene]);
  };

  const updateScene = (id: string, updates: Partial<Scene>) => {
    onUpdateScenes(scenes.map(s => s.id === id ? { ...s, ...updates } : s));
  };

  const handleBgUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleCharInScene = (sceneId: string, charId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const exists = scene.characters.find(c => c.characterId === charId);
    let newChars: SceneCharacterConfig[];

    if (exists) {
      newChars = scene.characters.filter(c => c.characterId !== charId);
    } else {
      newChars = [...scene.characters, { characterId: charId, roleInScene: 'Default behavior' }];
    }
    updateScene(sceneId, { characters: newChars });
  };

  const updateSceneCharRole = (sceneId: string, charId: string, role: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;
    const newChars = scene.characters.map(c => c.characterId === charId ? { ...c, roleInScene: role } : c);
    updateScene(sceneId, { characters: newChars });
  };

  return (
    <div className="flex flex-col h-full max-w-6xl mx-auto p-4 md:p-8">
      <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
        <h1 className="text-3xl font-bold text-indigo-400">VN Creator Studio</h1>

        <div className="flex gap-3">
          <Button onClick={onSaveProject} variant="secondary" title="Save Characters & Scenarios">
            <Save size={18} /> Save Project
          </Button>

          {hasSaveGame && (
            <Button onClick={onContinueGame} className="bg-yellow-600 hover:bg-yellow-500">
              <RotateCcw size={18} /> Continue Game
            </Button>
          )}

          <Button onClick={onPlay} className="bg-green-600 hover:bg-green-500 px-6">
            <PlayCircle size={18} /> New Game
          </Button>
        </div>
      </div>

      <div className="flex gap-4 mb-6 border-b border-gray-700 pb-1">
        <button
          onClick={() => setActiveTab('chars')}
          className={`px-4 py-2 font-medium ${activeTab === 'chars' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}
        >
          Characters
        </button>
        <button
          onClick={() => setActiveTab('scenes')}
          className={`px-4 py-2 font-medium ${activeTab === 'scenes' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}
        >
          Scenarios
        </button>
      </div>

      <div className="flex-1 overflow-y-auto pr-2">
        {activeTab === 'chars' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {characters.map(char => (
                <div key={char.id} className="bg-gray-800 p-4 rounded-xl border border-gray-700 flex gap-4">
                  <div className="w-24 h-32 bg-gray-900 rounded-lg flex-shrink-0 border border-gray-600 overflow-hidden relative group">
                    {char.imageSrc ? (
                      <img src={char.imageSrc} alt={char.name} className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center text-gray-600">
                        <User size={32} />
                      </div>
                    )}
                    <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity text-xs font-bold">
                      UPLOAD
                      <input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e)} />
                    </label>
                  </div>
                  <div className="flex-1 space-y-3">
                    <input
                      className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-1 focus:border-indigo-500 outline-none"
                      value={char.name}
                      onChange={(e) => updateCharacter(char.id, { name: e.target.value })}
                      placeholder="Character Name"
                    />
                     <div className="flex items-center gap-2">
                        <label className="text-xs text-gray-400">Map Sprite Color:</label>
                        <input 
                            type="color" 
                            value={char.rpgColor}
                            onChange={(e) => updateCharacter(char.id, { rpgColor: e.target.value })}
                            className="w-8 h-8 rounded bg-transparent cursor-pointer border-0"
                        />
                     </div>
                    <textarea
                      className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-1 h-20 text-sm focus:border-indigo-500 outline-none resize-none"
                      value={char.defaultDescription}
                      onChange={(e) => updateCharacter(char.id, { defaultDescription: e.target.value })}
                      placeholder="Core Persona/Description..."
                    />
                  </div>
                  <button onClick={() => onUpdateCharacters(characters.filter(c => c.id !== char.id))} className="text-gray-500 hover:text-red-500 h-fit">
                    <Trash2 size={18} />
                  </button>
                </div>
              ))}
            </div>
            <Button onClick={addCharacter} variant="secondary" className="w-full py-4 border-dashed">
              <Plus size={20} /> Add Character
            </Button>
          </div>
        )}

        {activeTab === 'scenes' && (
          <div className="space-y-8">
            {scenes.map((scene, idx) => (
              <div key={scene.id} className="bg-gray-800 p-6 rounded-xl border border-gray-700 space-y-4">
                <div className="flex justify-between items-start">
                  <div className="flex items-center gap-4">
                    <div className="bg-gray-900 px-3 py-1 rounded text-xs font-bold text-indigo-400">SCENE {idx + 1}</div>
                    <input
                       className="bg-transparent text-xl font-bold outline-none placeholder-gray-600"
                       value={scene.name}
                       onChange={(e) => updateScene(scene.id, { name: e.target.value })}
                       placeholder="Scene Name"
                    />
                  </div>
                  <button onClick={() => onUpdateScenes(scenes.filter(s => s.id !== scene.id))} className="text-gray-500 hover:text-red-500">
                    <Trash2 size={18} />
                  </button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                  {/* Visuals & Goal */}
                  <div className="space-y-4">
                    <div className="w-full h-40 bg-gray-900 rounded-lg border border-gray-600 overflow-hidden relative group">
                       {scene.backgroundSrc ? (
                          <img src={scene.backgroundSrc} alt="bg" className="w-full h-full object-cover opacity-60" />
                       ) : (
                         <div className="w-full h-full flex items-center justify-center text-gray-500 gap-2">
                           <ImageIcon size={24} /> No Background
                         </div>
                       )}
                       <label className="absolute inset-0 flex items-center justify-center cursor-pointer">
                          <span className="bg-black/60 px-4 py-2 rounded hover:bg-black/80 transition text-sm">Change Background</span>
                          <input type="file" accept="image/*" className="hidden" onChange={(e) => handleBgUpload(scene.id, e)} />
                       </label>
                    </div>

                    <div>
                      <label className="flex items-center gap-2 text-xs font-bold text-green-400 mb-1">
                        <Target size={14} /> WIN CONDITION (Scenario Goal)
                      </label>
                      <textarea
                        className="w-full bg-gray-900 border border-green-900/50 text-green-100 rounded px-3 py-2 text-sm focus:border-green-500 outline-none resize-none"
                        value={scene.goal}
                        onChange={(e) => updateScene(scene.id, { goal: e.target.value })}
                        placeholder="e.g. Convince the guard to let you pass..."
                        rows={3}
                      />
                    </div>
                  </div>

                  {/* Narrative Setup */}
                  <div className="space-y-2 lg:col-span-2">
                     <label className="block text-xs font-bold text-gray-400">SCENARIO DESCRIPTION (For AI)</label>
                     <textarea
                        className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-2 text-sm focus:border-indigo-500 outline-none resize-none"
                        value={scene.description}
                        onChange={(e) => updateScene(scene.id, { description: e.target.value })}
                        placeholder="Describe the setting, the mood, and what is happening..."
                        rows={3}
                      />

                      <label className="block text-xs font-bold text-gray-400 mt-4">PARTICIPATING CHARACTERS</label>
                      <div className="bg-gray-900 rounded-lg p-3 border border-gray-700 min-h-[100px]">
                         <div className="flex gap-2 flex-wrap mb-3">
                           {characters.map(char => {
                             const isActive = scene.characters.some(c => c.characterId === char.id);
                             return (
                               <button
                                 key={char.id}
                                 onClick={() => toggleCharInScene(scene.id, char.id)}
                                 className={`text-xs px-3 py-1 rounded-full border transition ${isActive ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-gray-800 border-gray-600 text-gray-400 hover:border-gray-400'}`}
                               >
                                 {char.name}
                               </button>
                             )
                           })}
                           {characters.length === 0 && <span className="text-xs text-gray-600 italic">No characters created yet.</span>}
                         </div>

                         {/* Per-Scene Character Logic */}
                         <div className="space-y-3">
                           {scene.characters.map(sc => {
                             const char = characters.find(c => c.id === sc.characterId);
                             if (!char) return null;
                             return (
                               <div key={sc.characterId} className="flex items-center gap-3 bg-gray-800 p-2 rounded border border-gray-700">
                                 <div className="w-8 h-8 rounded-full bg-gray-700 overflow-hidden flex-shrink-0" style={{ backgroundColor: char.rpgColor }}>
                                   {char.imageSrc && <img src={char.imageSrc} className="w-full h-full object-cover" />}
                                 </div>
                                 <div className="flex-1">
                                    <div className="text-xs font-bold text-indigo-300">{char.name} Role</div>
                                    <input 
                                      className="w-full bg-transparent border-b border-gray-600 text-xs py-1 focus:border-indigo-400 outline-none"
                                      placeholder="What does this character want in this scene?"
                                      value={sc.roleInScene}
                                      onChange={(e) => updateSceneCharRole(scene.id, sc.characterId, e.target.value)}
                                    />
                                 </div>
                               </div>
                             )
                           })}
                         </div>
                      </div>
                  </div>
                </div>
              </div>
            ))}
            <Button onClick={addScene} variant="secondary" className="w-full py-4 border-dashed">
              <Plus size={20} /> Add Scenario
            </Button>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Character, RPGState } from '../types';
import { Save } from 'lucide-react';

interface RPGWorldProps {
  characters: Character[];
  onTriggerScene: (characterId: string) => void;
  initialState?: RPGState;
  onSave: (state: RPGState) => void;
  onExit: () => void;
}

const TILE_SIZE = 48;
const MAP_WIDTH = 20;
const MAP_HEIGHT = 15;

export const RPGWorld: React.FC<RPGWorldProps> = ({ 
  characters, 
  onTriggerScene, 
  initialState, 
  onSave,
  onExit
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [player, setPlayer] = useState({ x: initialState?.playerX ?? 10, y: initialState?.playerY ?? 7 });
  const [nearbyChar, setNearbyChar] = useState<Character | null>(null);

  // Deterministic spawn points based on char ID hash
  const getCharPosition = (charId: string, index: number) => {
    // Simple hashing to place them somewhat randomly but consistently
    const hash = charId.split('').reduce((acc, c) => acc + c.charCodeAt(0), 0);
    const x = (hash * 7 + index * 5) % (MAP_WIDTH - 2) + 1;
    const y = (hash * 13 + index * 3) % (MAP_HEIGHT - 2) + 1;
    return { x, y };
  };

  const charPositions = useRef(
    characters.map((c, i) => ({ 
      ...c, 
      pos: getCharPosition(c.id, i) 
    }))
  ).current;

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      let dx = 0;
      let dy = 0;

      if (e.key === 'ArrowUp' || e.key === 'w') dy = -1;
      if (e.key === 'ArrowDown' || e.key === 's') dy = 1;
      if (e.key === 'ArrowLeft' || e.key === 'a') dx = -1;
      if (e.key === 'ArrowRight' || e.key === 'd') dx = 1;

      if (dx !== 0 || dy !== 0) {
        setPlayer(p => {
          const nx = Math.max(0, Math.min(MAP_WIDTH - 1, p.x + dx));
          const ny = Math.max(0, Math.min(MAP_HEIGHT - 1, p.y + dy));

          // Simple collision check against NPCs
          const hitNPC = charPositions.find(c => c.pos.x === nx && c.pos.y === ny);
          if (hitNPC) return p;

          return { x: nx, y: ny };
        });
      }

      if (e.code === 'Space' || e.key === 'Enter') {
        if (nearbyChar) {
          onTriggerScene(nearbyChar.id);
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [nearbyChar, charPositions, onTriggerScene]);

  // Check proximity
  useEffect(() => {
    const found = charPositions.find(c => {
      const dist = Math.abs(c.pos.x - player.x) + Math.abs(c.pos.y - player.y);
      return dist <= 1;
    });
    setNearbyChar(found || null);
  }, [player, charPositions]);

  // Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Draw Background
    ctx.fillStyle = '#111827'; // Dark gray bg
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw Grid / Floor
    for (let y = 0; y < MAP_HEIGHT; y++) {
      for (let x = 0; x < MAP_WIDTH; x++) {
        ctx.fillStyle = (x + y) % 2 === 0 ? '#1f2937' : '#374151'; // Checkerboard
        ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
      }
    }

    // Draw NPCs
    charPositions.forEach(c => {
      const cx = c.pos.x * TILE_SIZE;
      const cy = c.pos.y * TILE_SIZE;

      // Shadow
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.beginPath();
      ctx.ellipse(cx + TILE_SIZE/2, cy + TILE_SIZE - 5, TILE_SIZE/3, 5, 0, 0, Math.PI * 2);
      ctx.fill();

      // Body
      ctx.fillStyle = c.rpgColor || '#ef4444';
      ctx.fillRect(cx + 4, cy + 4, TILE_SIZE - 8, TILE_SIZE - 8);

      // "Face" (simple eyes)
      ctx.fillStyle = 'white';
      ctx.fillRect(cx + 12, cy + 12, 8, 8);
      ctx.fillRect(cx + 28, cy + 12, 8, 8);
      ctx.fillStyle = 'black';
      ctx.fillRect(cx + 14, cy + 14, 4, 4);
      ctx.fillRect(cx + 30, cy + 14, 4, 4);

      // Name Tag
      ctx.fillStyle = 'white';
      ctx.font = '10px monospace';
      ctx.textAlign = 'center';
      ctx.fillText(c.name, cx + TILE_SIZE/2, cy - 5);
    });

    // Draw Player
    const px = player.x * TILE_SIZE;
    const py = player.y * TILE_SIZE;

    ctx.fillStyle = '#6366f1'; // Indigo player
    ctx.fillRect(px + 8, py + 8, TILE_SIZE - 16, TILE_SIZE - 16);
    // Player Eyes
    ctx.fillStyle = 'white';
    ctx.fillRect(px + 14, py + 16, 6, 6);
    ctx.fillRect(px + 28, py + 16, 6, 6);

  }, [player, charPositions]);

  const handleManualSave = () => {
    onSave({
      playerX: player.x,
      playerY: player.y,
      completedSceneIds: initialState?.completedSceneIds || []
    });
  };

  return (
    <div className="relative w-full h-full bg-gray-950 flex flex-col items-center justify-center p-4">
      <div className="absolute top-4 left-4 flex gap-4 text-white z-10">
        <h1 className="text-2xl font-bold text-indigo-400 pixel-font">WORLD MAP</h1>
      </div>

      <div className="relative border-4 border-gray-700 rounded-lg shadow-2xl overflow-hidden bg-black">
        <canvas 
          ref={canvasRef}
          width={MAP_WIDTH * TILE_SIZE}
          height={MAP_HEIGHT * TILE_SIZE}
          className="block"
        />

        {nearbyChar && (
          <div className="absolute bottom-4 left-1/2 -translate-x-1/2 bg-black/80 text-white px-6 py-3 rounded-lg border border-white/20 animate-bounce">
            <span className="text-yellow-400 font-bold">SPACE</span> to talk to {nearbyChar.name}
          </div>
        )}
      </div>

      <div className="absolute bottom-8 right-8 flex gap-2">
         <button onClick={handleManualSave} className="bg-gray-800 p-3 rounded-full hover:bg-gray-700 border border-gray-600">
           <Save className="text-white" size={24} />
         </button>
         <button onClick={onExit} className="bg-red-900/80 px-6 py-2 rounded font-bold hover:bg-red-800 border border-red-700 text-red-100">
           EXIT TO MENU
         </button>
      </div>

      <div className="absolute top-8 right-8 bg-black/50 p-4 rounded text-xs text-gray-400">
        <p>Arrows / WASD to Move</p>
        <p>SPACE to Interact</p>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Editor } from './components/Editor';
import { Player } from './components/Player';
import { RPGWorld } from './components/RPGWorld';
import { Character, Scene, GameSaveData, RPGState } from './types';

// Default Data for quick start
const DEFAULT_CHARS: Character[] = [
  { 
    id: '1', 
    name: 'Aiko', 
    defaultDescription: 'A cheerful and curious android girl who loves learning about humans.', 
    imageSrc: null,
    rpgColor: '#f472b6' // Pink
  },
  { 
    id: '2', 
    name: 'Kael', 
    defaultDescription: 'A grumpy but skilled mechanic who fixes robots.', 
    imageSrc: null,
    rpgColor: '#60a5fa' // Blue
  }
];

const DEFAULT_SCENES: Scene[] = [
  {
    id: 's1',
    name: 'The Workshop',
    backgroundSrc: null,
    description: 'A cluttered workshop filled with robot parts. Kael is working on a workbench. Aiko is watching closely.',
    goal: 'Convince Kael to fix your broken radio.',
    characters: [
      { characterId: '1', roleInScene: 'Curious onlooker, wants to help but is clumsy.' },
      { characterId: '2', roleInScene: 'Busy, easily annoyed, does not want to be disturbed.' }
    ]
  }
];

const PROJECT_STORAGE_KEY = 'vn_creator_project';
const GAME_SAVE_KEY = 'vn_creator_savegame';

const App: React.FC = () => {
  const [mode, setMode] = useState<'edit' | 'rpg' | 'vn'>('edit');

  // Data State
  const [characters, setCharacters] = useState<Character[]>(DEFAULT_CHARS);
  const [scenes, setScenes] = useState<Scene[]>(DEFAULT_SCENES);

  // Game Play State
  const [rpgState, setRpgState] = useState<RPGState>({ playerX: 10, playerY: 7, completedSceneIds: [] });
  const [activeSceneIndex, setActiveSceneIndex] = useState<number>(-1);
  const [vnHistory, setVnHistory] = useState<any[]>([]); // Temp holder for history if we save mid-VN

  const [hasSaveGame, setHasSaveGame] = useState(false);

  // Check for save game on mount
  useEffect(() => {
    const savedGame = localStorage.getItem(GAME_SAVE_KEY);
    if (savedGame) {
      setHasSaveGame(true);
    }

    // Auto-load project if exists
    const savedProject = localStorage.getItem(PROJECT_STORAGE_KEY);
    if (savedProject) {
      try {
        const { characters: savedChars, scenes: savedScenes } = JSON.parse(savedProject);
        if (savedChars) setCharacters(savedChars);
        if (savedScenes) setScenes(savedScenes);
      } catch (e) {
        console.error("Failed to load project", e);
      }
    }
  }, []);

  const handleSaveProject = () => {
    const data = { characters, scenes };
    localStorage.setItem(PROJECT_STORAGE_KEY, JSON.stringify(data));
    alert("Project Settings (Characters & Scenes) saved successfully!");
  };

  const handleStartNewGame = () => {
    setRpgState({ playerX: 10, playerY: 7, completedSceneIds: [] });
    setVnHistory([]);
    setActiveSceneIndex(-1);
    setMode('rpg');
  };

  const handleContinueGame = () => {
    const savedGame = localStorage.getItem(GAME_SAVE_KEY);
    if (savedGame) {
      try {
        const parsed: GameSaveData = JSON.parse(savedGame);
        setRpgState(parsed.rpgState);

        // If we saved *inside* a VN scene
        if (parsed.vnState) {
          setActiveSceneIndex(parsed.vnState.currentSceneIndex);
          setVnHistory(parsed.vnState.history);
          setMode('vn');
        } else {
          setMode('rpg');
        }
      } catch (e) {
        console.error("Corrupt save file");
        handleStartNewGame();
      }
    }
  };

  const handleSaveGame = (currentVnState?: { index: number, history: any[] }) => {
    const saveData: GameSaveData = {
      rpgState: rpgState,
      vnState: currentVnState ? {
        currentSceneIndex: currentVnState.index,
        history: currentVnState.history,
        isProcessing: false,
        gameOver: false
      } : null,
      timestamp: Date.now()
    };
    localStorage.setItem(GAME_SAVE_KEY, JSON.stringify(saveData));
    setHasSaveGame(true);

    if(!currentVnState) {
       alert("Game Saved!");
    }
  };

  // --- Transitions ---

  const handleInteractWithChar = (charId: string) => {
    // Find the first scene this character is in that hasn't been completed
    // Or just the first one if all are done (replayability)
    const availableScenes = scenes.filter(s => s.characters.some(c => c.characterId === charId));

    // Simple logic: Find first scene index in the global list that matches
    const sceneToPlay = availableScenes.find(s => !rpgState.completedSceneIds.includes(s.id)) || availableScenes[0];

    if (sceneToPlay) {
      const realIndex = scenes.findIndex(s => s.id === sceneToPlay.id);
      setActiveSceneIndex(realIndex);
      setVnHistory([]); // Clear history for new scene
      setMode('vn');
    } else {
      alert("This character has nothing more to say right now.");
    }
  };

  const handleSceneComplete = (sceneIndex: number) => {
    const scene = scenes[sceneIndex];
    if (scene) {
        setRpgState(prev => ({
            ...prev,
            completedSceneIds: [...prev.completedSceneIds, scene.id]
        }));
    }
    setMode('rpg');
  };

  return (
    <div className="min-h-screen bg-gray-900 text-gray-100 font-sans selection:bg-indigo-500 selection:text-white">
      {mode === 'edit' && (
        <Editor 
          characters={characters}
          scenes={scenes}
          onUpdateCharacters={setCharacters}
          onUpdateScenes={setScenes}
          onPlay={handleStartNewGame}
          onSaveProject={handleSaveProject}
          hasSaveGame={hasSaveGame}
          onContinueGame={handleContinueGame}
        />
      )}

      {mode === 'rpg' && (
        <RPGWorld 
          characters={characters}
          initialState={rpgState}
          onTriggerScene={handleInteractWithChar}
          onSave={(updatedRpgState) => {
             setRpgState(updatedRpgState);
             // We need to pass the updated state immediately to save because setState is async
             const saveData: GameSaveData = {
                rpgState: updatedRpgState,
                vnState: null,
                timestamp: Date.now()
             };
             localStorage.setItem(GAME_SAVE_KEY, JSON.stringify(saveData));
             setHasSaveGame(true);
             alert("Game Saved!");
          }}
          onExit={() => setMode('edit')}
        />
      )}

      {mode === 'vn' && activeSceneIndex >= 0 && (
        <Player 
          scenes={scenes}
          characters={characters}
          // Construct a temp initial state for the Player component
          initialState={{
            currentSceneIndex: activeSceneIndex,
            history: vnHistory,
            timestamp: 0,
            rpgState: rpgState, // Pass through, though Player doesn't use it directly usually
            vnState: null
          }}
          onExit={() => {
             // Just go back to map if exiting manually
             setMode('rpg');
          }}
        />
      )}
    </div>
  );
};

