import React, { useState, useEffect, useRef } from 'react';
import { Scene, Character, ChatMessage, GameState, GameSaveData } from '../types';
import { generateGameTurn } from '../services/geminiService';
import { Button } from './ui/Button';
import { ArrowRight, RefreshCw, Send, Save, X, Map } from 'lucide-react';

interface PlayerProps {
  scenes: Scene[];
  characters: Character[];
  initialState: any; // Using any loosely here because we are mixing save data types
  onExit: () => void; // Returns to Map
}

export const Player: React.FC<PlayerProps> = ({ scenes, characters, initialState, onExit }) => {
  const [state, setState] = useState<GameState>({
    currentSceneIndex: initialState?.currentSceneIndex || 0,
    history: initialState?.history || [],
    isProcessing: false,
    gameOver: false,
  });
  const [userInput, setUserInput] = useState('');
  const [transitionMsg, setTransitionMsg] = useState<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  const currentScene = scenes[state.currentSceneIndex];
  const activeCharacters = currentScene?.characters
    .map(sc => characters.find(c => c.id === sc.characterId))
    .filter((c): c is Character => !!c) || [];

  // Auto-scroll chat
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [state.history]);

  // Initial greeting from System/Narrator when scene starts (only if history is empty)
  useEffect(() => {
    if (!currentScene || state.history.length > 0) return;
    setState(prev => ({
      ...prev,
      history: [{
        sender: 'system',
        text: currentScene.description,
        timestamp: Date.now(),
      }]
    }));
    setTransitionMsg(null);
  }, [state.currentSceneIndex, currentScene]);

  const handleSendMessage = async () => {
    if (!userInput.trim() || state.isProcessing || !currentScene) return;

    const newMessage: ChatMessage = {
      sender: 'user',
      text: userInput,
      timestamp: Date.now(),
    };

    // Optimistic update
    setState(prev => ({
      ...prev,
      history: [...prev.history, newMessage],
      isProcessing: true,
    }));
    setUserInput('');

    try {
      const aiResponse = await generateGameTurn(
        newMessage.text,
        state.history, // send previous history
        currentScene,
        characters
      );

      const newMessages: ChatMessage[] = aiResponse.characterResponses.map(resp => ({
        sender: 'model',
        characterId: resp.characterId,
        text: resp.text,
        timestamp: Date.now(),
      }));

      setState(prev => ({
        ...prev,
        history: [...prev.history, ...newMessages],
        isProcessing: false,
      }));

      if (aiResponse.sceneGoalReached) {
        handleSceneSuccess(aiResponse.sceneTransitionReason);
      }

    } catch (error) {
      console.error("Turn error", error);
      setState(prev => ({ ...prev, isProcessing: false }));
    }
  };

  const handleSceneSuccess = (reason?: string) => {
    setTransitionMsg(reason || "Objective Completed!");

    // Instead of auto-advancing index, we notify user and then exit to map
    setTimeout(() => {
        onExit(); // Go back to RPG Map
    }, 4000);
  };

  const handleSaveGame = () => {
    // We need to save the FULL state including RPG state which is handled by parent,
    // but here we just want to save the VN progress. 
    // Ideally, we callback to App to save.
    // For now, let's just show a message that they should save on the map, 
    // OR implement a callback prop onSave(vnState).
    // Given the previous prompt's structure, let's do a simple save to local storage just for VN continuity if refreshed.

    const saveData: GameSaveData = {
       ...initialState, // Keep RPG state
       vnState: {
           currentSceneIndex: state.currentSceneIndex,
           history: state.history,
           isProcessing: false,
           gameOver: false
       },
       timestamp: Date.now()
    };

    localStorage.setItem('vn_creator_savegame', JSON.stringify(saveData));

    const btn = document.getElementById('save-btn');
    if (btn) {
      const originalText = btn.innerHTML;
      btn.innerHTML = 'Saved!';
      setTimeout(() => btn.innerHTML = originalText, 1500);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  if (!currentScene) {
    return <div className="flex items-center justify-center h-full">Scene Data Error. <button onClick={onExit}>Back</button></div>;
  }

  return (
    <div className="relative w-full h-full bg-black overflow-hidden">
      {/* Background Layer */}
      <div className="absolute inset-0 z-0">
        {currentScene.backgroundSrc ? (
          <img src={currentScene.backgroundSrc} alt="bg" className="w-full h-full object-cover" />
        ) : (
          <div className="w-full h-full bg-gradient-to-b from-gray-800 to-gray-900" />
        )}
        <div className="absolute inset-0 bg-black/30" />
      </div>

      {/* Character Layer - Positioned above the chat box */}
      <div className="absolute bottom-[36vh] left-0 right-0 z-10 flex justify-center items-end px-10 h-[60vh] pointer-events-none">
        {activeCharacters.map((char, idx) => (
          <div 
             key={char.id} 
             className="relative transition-transform duration-500 transform"
             style={{ 
                zIndex: 10 + idx, 
                marginLeft: idx > 0 ? '-50px' : '0',
                filter: state.isProcessing ? 'brightness(0.7)' : 'brightness(1)' 
             }}
          >
            {char.imageSrc ? (
              <img 
                src={char.imageSrc} 
                alt={char.name} 
                className="max-h-[60vh] w-auto object-contain drop-shadow-2xl"
              />
            ) : (
               // Placeholder Shape
               <div className="w-64 h-96 rounded-t-full border-4 border-white/20 flex items-center justify-center text-white font-bold text-2xl shadow-2xl" style={{ backgroundColor: char.rpgColor || '#4b5563' }}>
                 {char.name[0]}
               </div>
            )}
            <div className="absolute bottom-4 left-0 right-0 text-center">
               <span className="bg-black/60 text-white px-2 py-1 rounded text-sm backdrop-blur-sm">{char.name}</span>
            </div>
          </div>
        ))}
      </div>

      {/* Transition Overlay */}
      {transitionMsg && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/90 animate-in fade-in duration-500">
           <div className="text-center space-y-4 p-8 max-w-2xl">
             <h2 className="text-3xl font-bold text-green-400">SCENARIO COMPLETE</h2>
             <p className="text-xl text-white">{transitionMsg}</p>
             <p className="text-sm text-gray-500 animate-pulse">Returning to Map...</p>
           </div>
        </div>
      )}

      {/* UI Layer - Chat Box */}
      <div className="absolute bottom-0 left-0 right-0 z-20 p-4 md:p-8 bg-gradient-to-t from-black via-black/90 to-transparent pt-24">
        <div className="max-w-4xl mx-auto bg-black/80 border border-gray-700 rounded-xl backdrop-blur-md shadow-2xl overflow-hidden flex flex-col h-[35vh]">

          {/* Chat History */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4">
            {state.history.map((msg, i) => {
              const char = characters.find(c => c.id === msg.characterId);
              const isUser = msg.sender === 'user';
              const isSystem = msg.sender === 'system';

              if (isSystem) return (
                <div key={i} className="text-center text-yellow-500 italic text-sm my-4 px-8">
                  {msg.text}
                </div>
              );

              return (
                <div key={i} className={`flex flex-col ${isUser ? 'items-end' : 'items-start'}`}>
                   <div className="text-xs text-gray-400 mb-1 px-1">
                     {isUser ? 'You' : (char?.name || 'Unknown')}
                   </div>
                   <div className={`px-4 py-2 rounded-lg max-w-[85%] leading-relaxed ${
                     isUser 
                       ? 'bg-indigo-600 text-white rounded-br-none' 
                       : 'bg-gray-800 text-gray-100 rounded-bl-none border border-gray-700'
                   }`}>
                     {msg.text}
                   </div>
                </div>
              );
            })}
            {state.isProcessing && (
              <div className="flex items-center gap-2 text-gray-500 text-sm px-4">
                <RefreshCw className="animate-spin" size={14} /> AI is thinking...
              </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-4 border-t border-gray-700 bg-gray-900/50 flex gap-3">
             <button 
               id="save-btn"
               onClick={handleSaveGame} 
               className="bg-gray-700 hover:bg-gray-600 text-gray-300 p-3 rounded-lg transition-colors flex items-center justify-center"
               title="Save Current Progress"
             >
               <Save size={20} />
             </button>

             <input
               type="text"
               className="flex-1 bg-gray-800 border border-gray-600 rounded-lg px-4 py-3 text-white focus:border-indigo-500 outline-none transition-colors"
               placeholder="What do you say/do?"
               value={userInput}
               onChange={(e) => setUserInput(e.target.value)}
               onKeyDown={handleKeyDown}
               autoFocus
               disabled={state.isProcessing}
             />
             <button 
                onClick={handleSendMessage}
                disabled={!userInput.trim() || state.isProcessing}
                className="bg-indigo-600 hover:bg-indigo-500 disabled:bg-gray-700 disabled:cursor-not-allowed text-white p-3 rounded-lg transition-colors"
             >
               <Send size={20} />
             </button>
             <button onClick={onExit} className="border border-indigo-900/50 text-indigo-400 hover:bg-indigo-900/20 p-3 rounded-lg transition-colors flex gap-2 items-center" title="Return to Map">
               <Map size={20} />
             </button>
          </div>

        </div>

        {/* Current Goal Display */}
        <div className="absolute top-4 right-4 md:right-12 bg-black/60 backdrop-blur text-xs text-green-400 px-3 py-1 rounded border border-green-900">
          Objective: {currentScene.goal}
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Character, RPGState } from '../types';
import { Save, LogOut } from 'lucide-react';

interface RPGWorldProps {
  characters: Character[];
  onTriggerScene: (characterId: string) => void;
  initialState?: RPGState;
  onSave: (state: RPGState) => void;
  onExit: () => void;
}

const TILE_SIZE = 48;
const MAP_WIDTH = 24;
const MAP_HEIGHT = 18;

// --- Pixel Art Drawing Helpers ---

const drawPixelRect = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string) => {
  ctx.fillStyle = color;
  ctx.fillRect(Math.floor(x), Math.floor(y), Math.floor(w), Math.floor(h));
};

// Procedural Grass Tile with noise
const drawGrassTile = (ctx: CanvasRenderingContext2D, x: number, y: number, seed: number) => {
  const baseX = x * TILE_SIZE;
  const baseY = y * TILE_SIZE;

  // Base Grass
  drawPixelRect(ctx, baseX, baseY, TILE_SIZE, TILE_SIZE, '#4ade80'); // bright green base

  // Add texture details based on pseudorandom seed
  const rand = (n: number) => Math.sin(seed * n) * 10000 - Math.floor(Math.sin(seed * n) * 10000);

  // Darker tufts
  for(let i=0; i<3; i++) {
      const ox = Math.floor(rand(i + 1) * (TILE_SIZE - 4));
      const oy = Math.floor(rand(i + 2) * (TILE_SIZE - 4));
      drawPixelRect(ctx, baseX + ox, baseY + oy, 4, 4, '#22c55e');
  }

  // Flowers occasionally
  if (rand(99) > 0.90) {
     const fx = Math.floor(rand(10) * (TILE_SIZE - 6));
     const fy = Math.floor(rand(11) * (TILE_SIZE - 6));
     drawPixelRect(ctx, baseX + fx, baseY + fy, 4, 4, rand(5) > 0.5 ? '#f472b6' : '#facc15'); // pink or yellow
     drawPixelRect(ctx, baseX + fx + 1, baseY + fy + 1, 2, 2, '#ffffff');
  }
};

const drawDirtPath = (ctx: CanvasRenderingContext2D, x: number, y: number) => {
  const baseX = x * TILE_SIZE;
  const baseY = y * TILE_SIZE;
  drawPixelRect(ctx, baseX, baseY, TILE_SIZE, TILE_SIZE, '#d6bcfa'); // light path color (magical stone look or dirt)
  drawPixelRect(ctx, baseX + 2, baseY + 2, TILE_SIZE - 4, TILE_SIZE - 4, '#e9d8fd'); // lighter center

  // Pebbles
  drawPixelRect(ctx, baseX + 10, baseY + 10, 4, 4, '#b794f4');
  drawPixelRect(ctx, baseX + 30, baseY + 25, 3, 3, '#b794f4');
};

const drawHouse = (ctx: CanvasRenderingContext2D, x: number, y: number) => {
  const baseX = x * TILE_SIZE;
  const baseY = y * TILE_SIZE;

  // Shadow
  drawPixelRect(ctx, baseX + 4, baseY + TILE_SIZE - 10, TILE_SIZE * 1.5, 20, 'rgba(0,0,0,0.3)');

  // Main Wall structure (spanning 1.5 tiles wide)
  const houseW = TILE_SIZE * 1.4;
  const houseH = TILE_SIZE * 1.2;
  const houseX = baseX;
  const houseY = baseY - (TILE_SIZE * 0.5); // Shift up to look like it's standing on the tile

  // Walls
  drawPixelRect(ctx, houseX, houseY, houseW, houseH, '#fde68a'); // cream walls
  drawPixelRect(ctx, houseX, houseY + houseH - 4, houseW, 4, '#d97706'); // baseboard

  // Door
  drawPixelRect(ctx, houseX + houseW/2 - 10, houseY + houseH - 24, 20, 24, '#78350f'); // brown door
  drawPixelRect(ctx, houseX + houseW/2 - 10 + 2, houseY + houseH - 24 + 2, 16, 20, '#92400e'); // door highlight
  drawPixelRect(ctx, houseX + houseW/2 + 2, houseY + houseH - 14, 2, 2, '#fbbf24'); // knob

  // Roof
  const roofH = 30;
  drawPixelRect(ctx, houseX - 4, houseY - roofH, houseW + 8, roofH, '#b91c1c'); // red roof
  drawPixelRect(ctx, houseX, houseY - roofH + 4, houseW, roofH - 8, '#991b1b'); // roof detail

  // Window
  drawPixelRect(ctx, houseX + 8, houseY + 16, 16, 16, '#60a5fa'); // blue glass
  drawPixelRect(ctx, houseX + 8, houseY + 22, 16, 2, '#1e3a8a'); // frame horizontal
  drawPixelRect(ctx, houseX + 15, houseY + 16, 2, 16, '#1e3a8a'); // frame vertical
};

const drawCharacterSprite = (
  ctx: CanvasRenderingContext2D, 
  x: number, 
  y: number, 
  color: string, 
  isPlayer: boolean, 
  tick: number,
  dir: number // 0=down, 1=up, 2=left, 3=right (simplified)
) => {
  const baseX = x * TILE_SIZE + (TILE_SIZE - 24) / 2; // Center in tile
  const baseY = y * TILE_SIZE + (TILE_SIZE - 32) / 2;

  // Bobbing animation
  const bob = Math.floor(Math.sin(tick / 10) * 2);
  const spriteY = baseY + bob;

  // Shadow
  ctx.fillStyle = 'rgba(0,0,0,0.4)';
  ctx.beginPath();
  ctx.ellipse(baseX + 12, baseY + 30, 10, 4, 0, 0, Math.PI * 2);
  ctx.fill();

  // Body/Clothes
  drawPixelRect(ctx, baseX + 4, spriteY + 14, 16, 14, color); 

  // Head
  drawPixelRect(ctx, baseX + 2, spriteY, 20, 16, '#fecaca'); // Skin tone
  drawPixelRect(ctx, baseX + 2, spriteY, 20, 6, isPlayer ? '#4338ca' : '#78350f'); // Hair (Player blue, NPC brown)

  // Eyes
  drawPixelRect(ctx, baseX + 6, spriteY + 8, 2, 4, '#000');
  drawPixelRect(ctx, baseX + 16, spriteY + 8, 2, 4, '#000');

  // Legs (simple animation)
  const legOffset = Math.floor(Math.sin(tick / 5) * 3);
  drawPixelRect(ctx, baseX + 6, spriteY + 28, 4, 6 - (isPlayer && (dir===2 || dir===3) ? legOffset : 0), '#1f2937');
  drawPixelRect(ctx, baseX + 14, spriteY + 28, 4, 6 + (isPlayer && (dir===2 || dir===3) ? legOffset : 0), '#1f2937');
};


export const RPGWorld: React.FC<RPGWorldProps> = ({ 
  characters, 
  onTriggerScene, 
  initialState, 
  onSave,
  onExit
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [player, setPlayer] = useState({ x: initialState?.playerX ?? 12, y: initialState?.playerY ?? 10 });
  const [nearbyChar, setNearbyChar] = useState<Character | null>(null);
  const [tick, setTick] = useState(0);
  const [lastDir, setLastDir] = useState(0);

  // Place characters in "Houses" layout
  const getCharPosition = (charId: string, index: number) => {
    // Distribute houses around the map center
    const cx = MAP_WIDTH / 2;
    const cy = MAP_HEIGHT / 2;
    const angle = (index / characters.length) * Math.PI * 2;
    const radius = 6;

    const x = Math.floor(cx + Math.cos(angle) * radius);
    const y = Math.floor(cy + Math.sin(angle) * radius);
    return { x, y };
  };

  const charPositions = useRef(
    characters.map((c, i) => ({ 
      ...c, 
      pos: getCharPosition(c.id, i) 
    }))
  ).current;

  // Animation Loop
  useEffect(() => {
    const interval = setInterval(() => {
      setTick(t => t + 1);
    }, 50);
    return () => clearInterval(interval);
  }, []);

  // Movement Logic
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      let dx = 0;
      let dy = 0;
      let newDir = lastDir;

      if (e.key === 'ArrowUp' || e.key === 'w') { dy = -1; newDir = 1; }
      if (e.key === 'ArrowDown' || e.key === 's') { dy = 1; newDir = 0; }
      if (e.key === 'ArrowLeft' || e.key === 'a') { dx = -1; newDir = 2; }
      if (e.key === 'ArrowRight' || e.key === 'd') { dx = 1; newDir = 3; }

      setLastDir(newDir);

      if (dx !== 0 || dy !== 0) {
        setPlayer(p => {
          const nx = Math.max(0, Math.min(MAP_WIDTH - 1, p.x + dx));
          const ny = Math.max(0, Math.min(MAP_HEIGHT - 1, p.y + dy));

          // Collision: Cannot walk on Houses (located at charY - 1 typically)
          // Simple collision against NPC standing spots
          const hitNPC = charPositions.find(c => c.pos.x === nx && c.pos.y === ny);
          if (hitNPC) return p;

          // Collision against House structure (assuming house is 1 tile above char)
          const hitHouse = charPositions.find(c => c.pos.x === nx && c.pos.y - 1 === ny);
          if (hitHouse) return p;

          return { x: nx, y: ny };
        });
      }

      if (e.code === 'Space' || e.key === 'Enter') {
        if (nearbyChar) {
          onTriggerScene(nearbyChar.id);
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [nearbyChar, charPositions, onTriggerScene, lastDir]);

  // Proximity Check
  useEffect(() => {
    const found = charPositions.find(c => {
      const dist = Math.abs(c.pos.x - player.x) + Math.abs(c.pos.y - player.y);
      return dist <= 1;
    });
    setNearbyChar(found || null);
  }, [player, charPositions]);

  // Main Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear
    ctx.fillStyle = '#111827';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 1. Draw Ground Layer
    for (let y = 0; y < MAP_HEIGHT; y++) {
      for (let x = 0; x < MAP_WIDTH; x++) {
        const seed = x * y + x; // simple seed

        // Draw path if near center or connecting houses
        // Simple logic: a cross in the middle and paths to houses
        const isPath = (x === Math.floor(MAP_WIDTH/2) || y === Math.floor(MAP_HEIGHT/2)) 
                       || charPositions.some(c => Math.abs(c.pos.x - x) < 2 && Math.abs(c.pos.y - y) < 2);

        if (isPath && !(x === 0 || x === MAP_WIDTH-1 || y === 0 || y === MAP_HEIGHT-1)) {
            drawDirtPath(ctx, x, y);
        } else {
            drawGrassTile(ctx, x, y, seed);
        }
      }
    }

    // 2. Draw Objects (Houses) - Ordered by Y for pseudo-depth
    // We separate drawing logic to ensure things "in front" obscure things "behind"
    const renderQueue = [];

    // Add Houses to queue (They sit at charPos.y - 1)
    charPositions.forEach(c => {
        renderQueue.push({ type: 'house', y: c.pos.y - 1, x: c.pos.x });
    });

    // Add NPCs
    charPositions.forEach(c => {
        renderQueue.push({ type: 'npc', y: c.pos.y, x: c.pos.x, data: c });
    });

    // Add Player
    renderQueue.push({ type: 'player', y: player.y, x: player.x });

    // Sort by Y, then X
    renderQueue.sort((a, b) => a.y - b.y || a.x - b.x);

    // Execute Render
    renderQueue.forEach(item => {
        if (item.type === 'house') {
            drawHouse(ctx, item.x, item.y);
        } else if (item.type === 'npc') {
            const c = item.data as Character;
            drawCharacterSprite(ctx, c.pos.x, c.pos.y, c.rpgColor, false, tick, 0);

            // Name Tag
            ctx.fillStyle = 'rgba(0,0,0,0.6)';
            ctx.fillStyle = 'white';
            ctx.font = 'bold 10px sans-serif';
            ctx.textAlign = 'center';
            ctx.strokeStyle = 'black';
            ctx.lineWidth = 2;
            ctx.strokeText(c.name, item.x * TILE_SIZE + TILE_SIZE/2, item.y * TILE_SIZE - 6);
            ctx.fillText(c.name, item.x * TILE_SIZE + TILE_SIZE/2, item.y * TILE_SIZE - 6);
        } else if (item.type === 'player') {
            drawCharacterSprite(ctx, item.x, item.y, '#6366f1', true, tick, lastDir);

            // Player Arrow Indicator if needed
            ctx.fillStyle = '#facc15';
            ctx.beginPath();
            const px = item.x * TILE_SIZE + TILE_SIZE/2;
            const py = item.y * TILE_SIZE - 10;
            ctx.moveTo(px, py);
            ctx.lineTo(px - 4, py - 6);
            ctx.lineTo(px + 4, py - 6);
            ctx.fill();
        }
    });

  }, [player, charPositions, tick, lastDir]);

  const handleManualSave = () => {
    onSave({
      playerX: player.x,
      playerY: player.y,
      completedSceneIds: initialState?.completedSceneIds || []
    });
  };

  return (
    <div className="relative w-full h-full bg-gray-950 flex flex-col items-center justify-center p-4 overflow-hidden">
      {/* HUD */}
      <div className="absolute top-4 left-4 flex gap-4 z-10 bg-gray-900/80 p-3 rounded-xl border border-gray-700 backdrop-blur-sm">
        <div>
          <h1 className="text-xl font-bold text-indigo-400 leading-none">PIXEL VILLAGE</h1>
          <span className="text-xs text-gray-400">Population: {characters.length}</span>
        </div>
      </div>

      <div className="relative rounded-xl shadow-2xl overflow-hidden border-[8px] border-gray-800 bg-black max-w-full max-h-full">
        <canvas 
          ref={canvasRef}
          width={MAP_WIDTH * TILE_SIZE}
          height={MAP_HEIGHT * TILE_SIZE}
          className="block max-w-full max-h-full object-contain pixel-art-scaling"
          style={{ imageRendering: 'pixelated' }}
        />

        {nearbyChar && (
          <div className="absolute bottom-12 left-1/2 -translate-x-1/2 bg-white text-black px-6 py-3 rounded-full border-4 border-indigo-500 animate-bounce shadow-lg z-20 flex flex-col items-center">
            <span className="text-xs font-bold text-gray-500 uppercase tracking-widest">Talk to</span>
            <span className="text-lg font-black">{nearbyChar.name}</span>
            <div className="text-[10px] text-gray-400 mt-1">(Press SPACE)</div>
          </div>
        )}
      </div>

      <div className="absolute bottom-8 right-8 flex gap-3 z-10">
         <button onClick={handleManualSave} className="bg-indigo-600 p-3 rounded-full hover:bg-indigo-500 text-white shadow-lg transition transform hover:scale-105" title="Save Game">
           <Save size={24} />
         </button>
         <button onClick={onExit} className="bg-gray-800 p-3 rounded-full hover:bg-red-900/80 text-white border border-gray-600 shadow-lg transition transform hover:scale-105" title="Exit to Editor">
           <LogOut size={24} />
         </button>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { Character, RPGState } from '../types';
import { Save, LogOut } from 'lucide-react';

interface RPGWorldProps {
  characters: Character[];
  onTriggerScene: (characterId: string) => void;
  initialState?: RPGState;
  onSave: (state: RPGState) => void;
  onExit: () => void;
}

const TILE_SIZE = 48;
const MAP_WIDTH = 24;
const MAP_HEIGHT = 18;

// --- Pixel Art Drawing Helpers ---

const drawPixelRect = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string) => {
  ctx.fillStyle = color;
  ctx.fillRect(Math.floor(x), Math.floor(y), Math.floor(w), Math.floor(h));
};

// Procedural Grass Tile with noise
const drawGrassTile = (ctx: CanvasRenderingContext2D, x: number, y: number, seed: number) => {
  const baseX = x * TILE_SIZE;
  const baseY = y * TILE_SIZE;

  // Base Grass
  drawPixelRect(ctx, baseX, baseY, TILE_SIZE, TILE_SIZE, '#4ade80'); // bright green base

  // Add texture details based on pseudorandom seed
  const rand = (n: number) => Math.sin(seed * n) * 10000 - Math.floor(Math.sin(seed * n) * 10000);

  // Darker tufts
  for(let i=0; i<3; i++) {
      const ox = Math.floor(rand(i + 1) * (TILE_SIZE - 4));
      const oy = Math.floor(rand(i + 2) * (TILE_SIZE - 4));
      drawPixelRect(ctx, baseX + ox, baseY + oy, 4, 4, '#22c55e');
  }

  // Flowers occasionally
  if (rand(99) > 0.90) {
     const fx = Math.floor(rand(10) * (TILE_SIZE - 6));
     const fy = Math.floor(rand(11) * (TILE_SIZE - 6));
     drawPixelRect(ctx, baseX + fx, baseY + fy, 4, 4, rand(5) > 0.5 ? '#f472b6' : '#facc15'); // pink or yellow
     drawPixelRect(ctx, baseX + fx + 1, baseY + fy + 1, 2, 2, '#ffffff');
  }
};

const drawDirtPath = (ctx: CanvasRenderingContext2D, x: number, y: number) => {
  const baseX = x * TILE_SIZE;
  const baseY = y * TILE_SIZE;
  drawPixelRect(ctx, baseX, baseY, TILE_SIZE, TILE_SIZE, '#d6bcfa'); // light path color (magical stone look or dirt)
  drawPixelRect(ctx, baseX + 2, baseY + 2, TILE_SIZE - 4, TILE_SIZE - 4, '#e9d8fd'); // lighter center

  // Pebbles
  drawPixelRect(ctx, baseX + 10, baseY + 10, 4, 4, '#b794f4');
  drawPixelRect(ctx, baseX + 30, baseY + 25, 3, 3, '#b794f4');
};

const drawHouse = (ctx: CanvasRenderingContext2D, x: number, y: number) => {
  const baseX = x * TILE_SIZE;
  const baseY = y * TILE_SIZE;

  // Shadow
  drawPixelRect(ctx, baseX + 4, baseY + TILE_SIZE - 10, TILE_SIZE * 1.5, 20, 'rgba(0,0,0,0.3)');

  // Main Wall structure (spanning 1.5 tiles wide)
  const houseW = TILE_SIZE * 1.4;
  const houseH = TILE_SIZE * 1.2;
  const houseX = baseX;
  const houseY = baseY - (TILE_SIZE * 0.5); // Shift up to look like it's standing on the tile

  // Walls
  drawPixelRect(ctx, houseX, houseY, houseW, houseH, '#fde68a'); // cream walls
  drawPixelRect(ctx, houseX, houseY + houseH - 4, houseW, 4, '#d97706'); // baseboard

  // Door
  drawPixelRect(ctx, houseX + houseW/2 - 10, houseY + houseH - 24, 20, 24, '#78350f'); // brown door
  drawPixelRect(ctx, houseX + houseW/2 - 10 + 2, houseY + houseH - 24 + 2, 16, 20, '#92400e'); // door highlight
  drawPixelRect(ctx, houseX + houseW/2 + 2, houseY + houseH - 14, 2, 2, '#fbbf24'); // knob

  // Roof
  const roofH = 30;
  drawPixelRect(ctx, houseX - 4, houseY - roofH, houseW + 8, roofH, '#b91c1c'); // red roof
  drawPixelRect(ctx, houseX, houseY - roofH + 4, houseW, roofH - 8, '#991b1b'); // roof detail

  // Window
  drawPixelRect(ctx, houseX + 8, houseY + 16, 16, 16, '#60a5fa'); // blue glass
  drawPixelRect(ctx, houseX + 8, houseY + 22, 16, 2, '#1e3a8a'); // frame horizontal
  drawPixelRect(ctx, houseX + 15, houseY + 16, 2, 16, '#1e3a8a'); // frame vertical
};

const drawCharacterSprite = (
  ctx: CanvasRenderingContext2D, 
  x: number, 
  y: number, 
  color: string, 
  isPlayer: boolean, 
  tick: number, 
  dir: number // 0=down, 1=up, 2=left, 3=right (simplified)
) => {
  const baseX = x * TILE_SIZE + (TILE_SIZE - 24) / 2; // Center in tile
  const baseY = y * TILE_SIZE + (TILE_SIZE - 32) / 2;

  // Bobbing animation
  const bob = Math.floor(Math.sin(tick / 10) * 2);
  const spriteY = baseY + bob;

  // Shadow
  ctx.fillStyle = 'rgba(0,0,0,0.4)';
  ctx.beginPath();
  ctx.ellipse(baseX + 12, baseY + 30, 10, 4, 0, 0, Math.PI * 2);
  ctx.fill();

  // Body/Clothes
  drawPixelRect(ctx, baseX + 4, spriteY + 14, 16, 14, color); 

  // Head
  drawPixelRect(ctx, baseX + 2, spriteY, 20, 16, '#fecaca'); // Skin tone
  drawPixelRect(ctx, baseX + 2, spriteY, 20, 6, isPlayer ? '#4338ca' : '#78350f'); // Hair (Player blue, NPC brown)

  // Eyes
  drawPixelRect(ctx, baseX + 6, spriteY + 8, 2, 4, '#000');
  drawPixelRect(ctx, baseX + 16, spriteY + 8, 2, 4, '#000');

  // Legs (simple animation)
  const legOffset = Math.floor(Math.sin(tick / 5) * 3);
  drawPixelRect(ctx, baseX + 6, spriteY + 28, 4, 6 - (isPlayer && (dir===2 || dir===3) ? legOffset : 0), '#1f2937');
  drawPixelRect(ctx, baseX + 14, spriteY + 28, 4, 6 + (isPlayer && (dir===2 || dir===3) ? legOffset : 0), '#1f2937');
};

interface CharacterWithPos extends Character {
  pos: { x: number; y: number };
}

export const RPGWorld: React.FC<RPGWorldProps> = ({ 
  characters, 
  onTriggerScene, 
  initialState, 
  onSave,
  onExit
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [player, setPlayer] = useState({ x: initialState?.playerX ?? 12, y: initialState?.playerY ?? 10 });
  const [nearbyChar, setNearbyChar] = useState<Character | null>(null);
  const [tick, setTick] = useState(0);
  const [lastDir, setLastDir] = useState(0);

  // Place characters in "Houses" layout
  const getCharPosition = (charId: string, index: number) => {
    // Distribute houses around the map center
    const cx = MAP_WIDTH / 2;
    const cy = MAP_HEIGHT / 2;
    const angle = (index / characters.length) * Math.PI * 2;
    const radius = 6;

    const x = Math.floor(cx + Math.cos(angle) * radius);
    const y = Math.floor(cy + Math.sin(angle) * radius);
    return { x, y };
  };

  const charPositions = useMemo<CharacterWithPos[]>(() => 
    characters.map((c, i) => ({ 
      ...c, 
      pos: getCharPosition(c.id, i) 
    })),
  [characters]);

  // Animation Loop
  useEffect(() => {
    const interval = setInterval(() => {
      setTick(t => t + 1);
    }, 50);
    return () => clearInterval(interval);
  }, []);

  // Movement Logic
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      let dx = 0;
      let dy = 0;
      let newDir = lastDir;

      if (e.key === 'ArrowUp' || e.key === 'w') { dy = -1; newDir = 1; }
      if (e.key === 'ArrowDown' || e.key === 's') { dy = 1; newDir = 0; }
      if (e.key === 'ArrowLeft' || e.key === 'a') { dx = -1; newDir = 2; }
      if (e.key === 'ArrowRight' || e.key === 'd') { dx = 1; newDir = 3; }

      setLastDir(newDir);

      if (dx !== 0 || dy !== 0) {
        setPlayer(p => {
          const nx = Math.max(0, Math.min(MAP_WIDTH - 1, p.x + dx));
          const ny = Math.max(0, Math.min(MAP_HEIGHT - 1, p.y + dy));

          // Collision: Cannot walk on Houses (located at charY - 1 typically)
          // Simple collision against NPC standing spots
          const hitNPC = charPositions.find(c => c.pos.x === nx && c.pos.y === ny);
          if (hitNPC) return p;

          // Collision against House structure (assuming house is 1 tile above char)
          const hitHouse = charPositions.find(c => c.pos.x === nx && c.pos.y - 1 === ny);
          if (hitHouse) return p;

          return { x: nx, y: ny };
        });
      }

      if (e.code === 'Space' || e.key === 'Enter') {
        if (nearbyChar) {
          onTriggerScene(nearbyChar.id);
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [nearbyChar, charPositions, onTriggerScene, lastDir]);

  // Proximity Check
  useEffect(() => {
    const found = charPositions.find(c => {
      const dist = Math.abs(c.pos.x - player.x) + Math.abs(c.pos.y - player.y);
      return dist <= 1;
    });
    setNearbyChar(found || null);
  }, [player, charPositions]);

  // Main Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear
    ctx.fillStyle = '#111827';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 1. Draw Ground Layer
    for (let y = 0; y < MAP_HEIGHT; y++) {
      for (let x = 0; x < MAP_WIDTH; x++) {
        const seed = x * y + x; // simple seed

        // Draw path if near center or connecting houses
        // Simple logic: a cross in the middle and paths to houses
        const isPath = (x === Math.floor(MAP_WIDTH/2) || y === Math.floor(MAP_HEIGHT/2)) 
                       || charPositions.some(c => Math.abs(c.pos.x - x) < 2 && Math.abs(c.pos.y - y) < 2);

        if (isPath && !(x === 0 || x === MAP_WIDTH-1 || y === 0 || y === MAP_HEIGHT-1)) {
            drawDirtPath(ctx, x, y);
        } else {
            drawGrassTile(ctx, x, y, seed);
        }
      }
    }

    // 2. Draw Objects (Houses) - Ordered by Y for pseudo-depth
    // We separate drawing logic to ensure things "in front" obscure things "behind"
    const renderQueue: any[] = [];

    // Add Houses to queue (They sit at charPos.y - 1)
    charPositions.forEach(c => {
        renderQueue.push({ type: 'house', y: c.pos.y - 1, x: c.pos.x });
    });

    // Add NPCs
    charPositions.forEach(c => {
        renderQueue.push({ type: 'npc', y: c.pos.y, x: c.pos.x, data: c });
    });

    // Add Player
    renderQueue.push({ type: 'player', y: player.y, x: player.x });

    // Sort by Y, then X
    renderQueue.sort((a, b) => a.y - b.y || a.x - b.x);

    // Execute Render
    renderQueue.forEach(item => {
        if (item.type === 'house') {
            drawHouse(ctx, item.x, item.y);
        } else if (item.type === 'npc') {
            const c = item.data as Character;
            // Use item.x and item.y as they are derived from c.pos but already extracted
            drawCharacterSprite(ctx, item.x, item.y, c.rpgColor, false, tick, 0);

            // Name Tag
            ctx.fillStyle = 'rgba(0,0,0,0.6)';
            ctx.fillStyle = 'white';
            ctx.font = 'bold 10px sans-serif';
            ctx.textAlign = 'center';
            ctx.strokeStyle = 'black';
            ctx.lineWidth = 2;
            const tx = item.x * TILE_SIZE + TILE_SIZE/2;
            const ty = item.y * TILE_SIZE - 6;
            ctx.strokeText(c.name, tx, ty);
            ctx.fillText(c.name, tx, ty);
        } else if (item.type === 'player') {
            drawCharacterSprite(ctx, item.x, item.y, '#6366f1', true, tick, lastDir);

            // Player Arrow Indicator if needed
            ctx.fillStyle = '#facc15';
            ctx.beginPath();
            const px = item.x * TILE_SIZE + TILE_SIZE/2;
            const py = item.y * TILE_SIZE - 10;
            ctx.moveTo(px, py);
            ctx.lineTo(px - 4, py - 6);
            ctx.lineTo(px + 4, py - 6);
            ctx.fill();
        }
    });

  }, [player, charPositions, tick, lastDir]);

  const handleManualSave = () => {
    onSave({
      playerX: player.x,
      playerY: player.y,
      completedSceneIds: initialState?.completedSceneIds || []
    });
  };

  return (
    <div className="relative w-full h-full bg-gray-950 flex flex-col items-center justify-center p-4 overflow-hidden">
      {/* HUD */}
      <div className="absolute top-4 left-4 flex gap-4 z-10 bg-gray-900/80 p-3 rounded-xl border border-gray-700 backdrop-blur-sm">
        <div>
          <h1 className="text-xl font-bold text-indigo-400 leading-none">PIXEL VILLAGE</h1>
          <span className="text-xs text-gray-400">Population: {characters.length}</span>
        </div>
      </div>

      <div className="relative rounded-xl shadow-2xl overflow-hidden border-[8px] border-gray-800 bg-black max-w-full max-h-full">
        <canvas 
          ref={canvasRef}
          width={MAP_WIDTH * TILE_SIZE}
          height={MAP_HEIGHT * TILE_SIZE}
          className="block max-w-full max-h-full object-contain pixel-art-scaling"
          style={{ imageRendering: 'pixelated' }}
        />

        {nearbyChar && (
          <div className="absolute bottom-12 left-1/2 -translate-x-1/2 bg-white text-black px-6 py-3 rounded-full border-4 border-indigo-500 animate-bounce shadow-lg z-20 flex flex-col items-center">
            <span className="text-xs font-bold text-gray-500 uppercase tracking-widest">Talk to</span>
            <span className="text-lg font-black">{nearbyChar.name}</span>
            <div className="text-[10px] text-gray-400 mt-1">(Press SPACE)</div>
          </div>
        )}
      </div>

      <div className="absolute bottom-8 right-8 flex gap-3 z-10">
         <button onClick={handleManualSave} className="bg-indigo-600 p-3 rounded-full hover:bg-indigo-500 text-white shadow-lg transition transform hover:scale-105" title="Save Game">
           <Save size={24} />
         </button>
         <button onClick={onExit} className="bg-gray-800 p-3 rounded-full hover:bg-red-900/80 text-white border border-gray-600 shadow-lg transition transform hover:scale-105" title="Exit to Editor">
           <LogOut size={24} />
         </button>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { Character, RPGState } from '../types';
import { Save, LogOut } from 'lucide-react';

interface RPGWorldProps {
  characters: Character[];
  onTriggerScene: (characterId: string) => void;
  initialState?: RPGState;
  onSave: (state: RPGState) => void;
  onExit: () => void;
}

const TILE_SIZE = 48;
const MAP_WIDTH = 24;
const MAP_HEIGHT = 18;

// --- Advanced Pixel Art Helpers ---

const drawRect = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string) => {
  ctx.fillStyle = color;
  ctx.fillRect(Math.floor(x), Math.floor(y), Math.floor(w), Math.floor(h));
};

const drawCircle = (ctx: CanvasRenderingContext2D, x: number, y: number, r: number, color: string) => {
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fill();
};

// --- Procedural Assets ---

const drawTexturedGrass = (ctx: CanvasRenderingContext2D, x: number, y: number, seed: number) => {
  const baseX = x * TILE_SIZE;
  const baseY = y * TILE_SIZE;

  // Base Layer with slight variation
  const rand = (n: number) => Math.sin(seed * n) * 10000 - Math.floor(Math.sin(seed * n) * 10000);
  const variant = rand(1) > 0.5 ? '#4ade80' : '#22c55e'; // Two tones of green

  // Checkboard pattern for "grass texture"
  ctx.fillStyle = '#4ade80'; 
  ctx.fillRect(baseX, baseY, TILE_SIZE, TILE_SIZE);

  // Noise
  for(let i=0; i<4; i++) {
     const ox = Math.floor(rand(i + 10) * TILE_SIZE);
     const oy = Math.floor(rand(i + 20) * TILE_SIZE);
     const w = Math.floor(rand(i + 30) * 4) + 2;
     drawRect(ctx, baseX + ox, baseY + oy, w, 2, '#3b82f615'); // very subtle blueish shadow for depth
     drawRect(ctx, baseX + ox, baseY + oy - 1, w, 2, '#22c55e'); // grass blade
  }

  // Flowers (rare)
  if (rand(99) > 0.95) {
     const fx = baseX + Math.floor(rand(100) * (TILE_SIZE - 6));
     const fy = baseY + Math.floor(rand(101) * (TILE_SIZE - 6));
     const color = rand(55) > 0.5 ? '#f472b6' : '#facc15';
     drawRect(ctx, fx, fy + 2, 1, 3, '#166534'); // stem
     drawCircle(ctx, fx, fy, 2, color); // bloom
     drawCircle(ctx, fx, fy, 1, 'white');
  }
};

const drawOrganicPath = (ctx: CanvasRenderingContext2D, x: number, y: number, neighbors: {n: boolean, s: boolean, e: boolean, w: boolean}) => {
  const baseX = x * TILE_SIZE;
  const baseY = y * TILE_SIZE;

  // Base dirt
  drawRect(ctx, baseX, baseY, TILE_SIZE, TILE_SIZE, '#d6bcfa'); // Magic stone path base

  // Add "erosion" to corners if no neighbor
  const cornerSize = 8;
  if (!neighbors.w) drawRect(ctx, baseX, baseY, 4, TILE_SIZE, '#4ade80'); // grass encroach left
  if (!neighbors.e) drawRect(ctx, baseX + TILE_SIZE - 4, baseY, 4, TILE_SIZE, '#4ade80'); // grass encroach right
  if (!neighbors.n) drawRect(ctx, baseX, baseY, TILE_SIZE, 4, '#4ade80'); // grass encroach top
  if (!neighbors.s) drawRect(ctx, baseX, baseY + TILE_SIZE - 4, TILE_SIZE, 4, '#4ade80'); // grass encroach bottom

  // Cobblestones
  ctx.fillStyle = '#c084fc'; // Darker purple stones
  for(let i = 0; i < 5; i++) {
     drawRect(ctx, baseX + 5 + i*8, baseY + 5 + (i%2)*10, 6, 4, 'rgba(0,0,0,0.1)'); // shadow
     drawRect(ctx, baseX + 5 + i*8, baseY + 4 + (i%2)*10, 6, 4, '#e9d8fd'); // stone
  }
};

const drawTree = (ctx: CanvasRenderingContext2D, x: number, y: number) => {
  const baseX = x * TILE_SIZE + TILE_SIZE/2;
  const baseY = y * TILE_SIZE + TILE_SIZE - 8; // Tree base position

  // Shadow
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.beginPath();
  ctx.ellipse(baseX, baseY, 16, 6, 0, 0, Math.PI * 2);
  ctx.fill();

  // Trunk
  drawRect(ctx, baseX - 6, baseY - 24, 12, 26, '#451a03'); // Dark wood
  drawRect(ctx, baseX - 4, baseY - 24, 4, 24, '#78350f'); // Highlight wood

  // Leaves (Cluster of circles)
  const leafColor = '#15803d';
  const leafHighlight = '#22c55e';

  const clusters = [
    {x: 0, y: -45, r: 20},
    {x: -12, y: -35, r: 16},
    {x: 12, y: -35, r: 16},
    {x: 0, y: -25, r: 18},
  ];

  clusters.forEach(c => {
    drawCircle(ctx, baseX + c.x, baseY + c.y + 2, c.r, 'rgba(0,0,0,0.2)'); // Self shadow
    drawCircle(ctx, baseX + c.x, baseY + c.y, c.r, leafColor);
    drawCircle(ctx, baseX + c.x - 2, baseY + c.y - 2, c.r - 4, leafHighlight);
  });
};

const drawFence = (ctx: CanvasRenderingContext2D, x: number, y: number, horizontal: boolean) => {
  const baseX = x * TILE_SIZE;
  const baseY = y * TILE_SIZE;

  // Shadow
  if (horizontal) {
    drawRect(ctx, baseX, baseY + TILE_SIZE/2 + 8, TILE_SIZE, 4, 'rgba(0,0,0,0.2)');
  } else {
    drawRect(ctx, baseX + TILE_SIZE/2 + 2, baseY, 4, TILE_SIZE, 'rgba(0,0,0,0.2)');
  }

  const woodDark = '#78350f';
  const woodLight = '#92400e';

  // Posts
  const drawPost = (px: number, py: number) => {
    drawRect(ctx, px, py - 16, 6, 24, woodDark);
    drawRect(ctx, px + 1, py - 16 + 1, 4, 22, woodLight);
    drawRect(ctx, px, py - 16, 6, 1, '#fbbf24'); // Top cap
  };

  if (horizontal) {
    drawRect(ctx, baseX, baseY + TILE_SIZE/2 - 8, TILE_SIZE, 4, woodDark); // Rail
    drawPost(baseX + 2, baseY + TILE_SIZE/2 + 8);
    drawPost(baseX + TILE_SIZE - 8, baseY + TILE_SIZE/2 + 8);
  } else {
    drawRect(ctx, baseX + TILE_SIZE/2 - 3, baseY, 4, TILE_SIZE, woodDark); // Rail
    drawPost(baseX + TILE_SIZE/2 - 3, baseY + TILE_SIZE/2);
  }
};

const drawDetailedHouse = (ctx: CanvasRenderingContext2D, x: number, y: number, colorHash: number) => {
  const baseX = x * TILE_SIZE;
  const baseY = y * TILE_SIZE;

  // House Dimensions
  const w = TILE_SIZE * 1.8;
  const h = TILE_SIZE * 1.5;
  const hx = baseX - (w - TILE_SIZE)/2;
  const hy = baseY - TILE_SIZE * 0.5;

  // Shadow
  ctx.fillStyle = 'rgba(0,0,0,0.4)';
  ctx.fillRect(hx + 4, hy + h - 8, w, 12);

  // Walls
  const wallColor = colorHash % 2 === 0 ? '#fef3c7' : '#e5e7eb'; // Cream or Grey
  drawRect(ctx, hx, hy, w, h, '#78350f'); // Dark frame
  drawRect(ctx, hx + 2, hy + 2, w - 4, h - 4, wallColor);

  // Beams
  drawRect(ctx, hx + 2, hy + h/2, w - 4, 4, '#78350f'); // Cross beam
  drawRect(ctx, hx + w/2 - 2, hy + 2, 4, h/2 - 2, '#78350f'); // Vertical beam top

  // Roof (A-Frame)
  const roofH = 40;
  const roofColor = colorHash % 3 === 0 ? '#991b1b' : (colorHash % 3 === 1 ? '#1e40af' : '#3f6212'); // Red, Blue, Green

  ctx.fillStyle = roofColor;
  ctx.beginPath();
  ctx.moveTo(hx - 8, hy); // Bottom Left
  ctx.lineTo(hx + w/2, hy - roofH); // Top
  ctx.lineTo(hx + w + 8, hy); // Bottom Right
  ctx.fill();

  // Roof Shingles details
  ctx.strokeStyle = 'rgba(0,0,0,0.2)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  for(let i=0; i<6; i++) {
     const yLevel = hy - (roofH * (i/6));
     const xSpread = (w + 16) * (1 - i/6);
     const xStart = hx + w/2 - xSpread/2;
     ctx.moveTo(xStart, yLevel);
     ctx.lineTo(xStart + xSpread, yLevel);
  }
  ctx.stroke();

  // Chimney
  drawRect(ctx, hx + w - 20, hy - roofH + 10, 10, 20, '#57534e');
  drawRect(ctx, hx + w - 22, hy - roofH + 8, 14, 4, '#44403c'); // Cap

  // Door
  const doorW = 24;
  const doorH = 32;
  const doorX = hx + w/2 - doorW/2;
  const doorY = hy + h - doorH;

  drawRect(ctx, doorX, doorY, doorW, doorH, '#451a03');
  drawRect(ctx, doorX + 2, doorY + 2, doorW - 4, doorH - 4, '#92400e');
  drawCircle(ctx, doorX + 4, doorY + doorH/2, 2, '#fbbf24'); // Knob

  // Windows
  const winW = 16;
  const winH = 20;
  drawRect(ctx, hx + 10, hy + h/2 + 8, winW, winH, '#7dd3fc'); // Left
  drawRect(ctx, hx + w - 10 - winW, hy + h/2 + 8, winW, winH, '#7dd3fc'); // Right

  // Flower Box
  drawRect(ctx, hx + 10 - 2, hy + h/2 + 8 + winH, winW + 4, 6, '#78350f');
  drawCircle(ctx, hx + 10 + 4, hy + h/2 + 8 + winH, 3, '#f472b6');
  drawCircle(ctx, hx + 10 + 10, hy + h/2 + 8 + winH, 3, '#facc15');

};

const drawCharacterSprite = (
  ctx: CanvasRenderingContext2D, 
  x: number, 
  y: number, 
  color: string, 
  isPlayer: boolean, 
  tick: number, 
  dir: number
) => {
  // Lerp position could be added here for smoothness, but sticking to grid-snap visuals for now
  const baseX = x * TILE_SIZE + (TILE_SIZE - 28) / 2;
  const baseY = y * TILE_SIZE + (TILE_SIZE - 40) / 2;

  // Bobbing
  const bob = Math.floor(Math.sin(tick / 8) * 2);
  const sy = baseY + bob - 10; // Lift up slightly to look grounded

  // Shadow
  ctx.fillStyle = 'rgba(0,0,0,0.4)';
  ctx.beginPath();
  ctx.ellipse(baseX + 14, baseY + 32, 10, 4, 0, 0, Math.PI * 2);
  ctx.fill();

  // --- Body ---
  // Outline
  const outlineColor = 'rgba(0,0,0,0.5)';

  // Hair/Helmet Base
  drawRect(ctx, baseX + 2, sy, 24, 10, isPlayer ? '#1e3a8a' : '#3f3f46'); 

  // Face
  drawRect(ctx, baseX + 4, sy + 8, 20, 14, '#ffedd5'); 

  // Eyes (Blink logic)
  if (Math.sin(tick / 5) > 0.95) { // Blink
     drawRect(ctx, baseX + 8, sy + 14, 4, 2, '#451a03');
     drawRect(ctx, baseX + 18, sy + 14, 4, 2, '#451a03');
  } else {
     drawRect(ctx, baseX + 8, sy + 12, 4, 4, '#000');
     drawRect(ctx, baseX + 18, sy + 12, 4, 4, '#000');
     // Eye sparkle
     drawRect(ctx, baseX + 9, sy + 13, 1, 1, '#fff');
  }

  // Outfit
  drawRect(ctx, baseX + 4, sy + 22, 20, 14, color); // Main shirt
  drawRect(ctx, baseX + 10, sy + 24, 8, 12, 'rgba(255,255,255,0.3)'); // Detail

  // Legs / Walking
  const legOffset = isPlayer && (dir===2 || dir===3) ? Math.floor(Math.sin(tick / 3) * 4) : 0;
  drawRect(ctx, baseX + 6, sy + 36 + legOffset, 6, 8, '#1f2937');
  drawRect(ctx, baseX + 16, sy + 36 - legOffset, 6, 8, '#1f2937');
};

const drawSmoke = (ctx: CanvasRenderingContext2D, x: number, y: number, tick: number) => {
   const t = (tick % 100) / 100;
   const oy = t * 30;
   const alpha = 1 - t;

   ctx.fillStyle = `rgba(200, 200, 200, ${alpha})`;
   drawCircle(ctx, x + Math.sin(t*10)*5, y - oy, 4 + t*4, `rgba(229, 231, 235, ${alpha})`);
};


interface CharacterWithPos extends Character {
  pos: { x: number; y: number };
}

interface RenderItem {
    type: 'ground' | 'path' | 'house' | 'tree' | 'fence' | 'npc' | 'player';
    x: number;
    y: number;
    zIndex: number;
    data?: any;
}

export const RPGWorld: React.FC<RPGWorldProps> = ({ 
  characters, 
  onTriggerScene, 
  initialState, 
  onSave,
  onExit
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [player, setPlayer] = useState({ x: initialState?.playerX ?? 12, y: initialState?.playerY ?? 10 });
  const [nearbyChar, setNearbyChar] = useState<Character | null>(null);
  const [tick, setTick] = useState(0);
  const [lastDir, setLastDir] = useState(0);

  // Calculate fixed positions once
  const charPositions = useMemo<CharacterWithPos[]>(() => 
    characters.map((c, i) => {
        // Distribute houses in a circle
        const cx = MAP_WIDTH / 2;
        const cy = MAP_HEIGHT / 2;
        const angle = (i / characters.length) * Math.PI * 2;
        const radius = 5;
        return { 
          ...c, 
          pos: { 
              x: Math.floor(cx + Math.cos(angle) * radius), 
              y: Math.floor(cy + Math.sin(angle) * radius) 
          } 
        };
    }),
  [characters]);

  // Static Map Objects (Trees, Fences)
  const staticObjects = useMemo(() => {
     const objs: RenderItem[] = [];

     // Trees boundary
     for(let i=0; i<MAP_WIDTH; i+=2) {
         objs.push({type: 'tree', x: i, y: 0, zIndex: 0});
         objs.push({type: 'tree', x: i, y: MAP_HEIGHT-1, zIndex: (MAP_HEIGHT-1)*TILE_SIZE});
     }
     for(let i=0; i<MAP_HEIGHT; i+=2) {
         objs.push({type: 'tree', x: 0, y: i, zIndex: i*TILE_SIZE});
         objs.push({type: 'tree', x: MAP_WIDTH-1, y: i, zIndex: i*TILE_SIZE});
     }

     // Random trees inside
     const seedRand = (s:number) => Math.sin(s)*10000 - Math.floor(Math.sin(s)*10000);
     for(let y=2; y<MAP_HEIGHT-2; y++) {
         for(let x=2; x<MAP_WIDTH-2; x++) {
             if(seedRand(x*y) > 0.96) {
                objs.push({type: 'tree', x, y, zIndex: y*TILE_SIZE});
             }
         }
     }

     // Fences
     // Simple fence around the village center?
     // Let's just place a few decorative fences
     objs.push({type: 'fence', x: 8, y: 12, zIndex: 12*TILE_SIZE, data: {h: true}});
     objs.push({type: 'fence', x: 9, y: 12, zIndex: 12*TILE_SIZE, data: {h: true}});
     objs.push({type: 'fence', x: 10, y: 12, zIndex: 12*TILE_SIZE, data: {h: true}});

     return objs;
  }, []);

  // Animation Loop
  useEffect(() => {
    const interval = setInterval(() => setTick(t => t + 1), 50);
    return () => clearInterval(interval);
  }, []);

  // Input & Movement
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      let dx = 0; let dy = 0; let newDir = lastDir;

      if (e.key === 'ArrowUp' || e.key === 'w') { dy = -1; newDir = 1; }
      if (e.key === 'ArrowDown' || e.key === 's') { dy = 1; newDir = 0; }
      if (e.key === 'ArrowLeft' || e.key === 'a') { dx = -1; newDir = 2; }
      if (e.key === 'ArrowRight' || e.key === 'd') { dx = 1; newDir = 3; }

      setLastDir(newDir);

      if (dx !== 0 || dy !== 0) {
        setPlayer(p => {
          const nx = Math.max(0, Math.min(MAP_WIDTH - 1, p.x + dx));
          const ny = Math.max(0, Math.min(MAP_HEIGHT - 1, p.y + dy));

          // Collision Logic
          // 1. House collision (house is at y-1 relative to char spawn)
          const hitHouse = charPositions.some(c => c.pos.x === nx && c.pos.y - 1 === ny);
          // 2. NPC collision
          const hitNPC = charPositions.some(c => c.pos.x === nx && c.pos.y === ny);
          // 3. Tree collision (simple check against static list)
          const hitTree = staticObjects.some(o => o.type === 'tree' && o.x === nx && o.y === ny);

          if (hitHouse || hitNPC || hitTree) return p;

          return { x: nx, y: ny };
        });
      }

      if (e.code === 'Space' || e.key === 'Enter') {
        if (nearbyChar) onTriggerScene(nearbyChar.id);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [nearbyChar, charPositions, onTriggerScene, lastDir, staticObjects]);

  // Proximity
  useEffect(() => {
    const found = charPositions.find(c => {
      const dist = Math.abs(c.pos.x - player.x) + Math.abs(c.pos.y - player.y);
      return dist <= 1;
    });
    setNearbyChar(found || null);
  }, [player, charPositions]);

  // --- RENDER ---
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Fill Background
    ctx.fillStyle = '#111827';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // --- Layer 1: Ground & Paths ---
    for (let y = 0; y < MAP_HEIGHT; y++) {
      for (let x = 0; x < MAP_WIDTH; x++) {
        const seed = x * y + x;
        // Path logic: center cross + lines to houses
        const isPath = (x === Math.floor(MAP_WIDTH/2) || y === Math.floor(MAP_HEIGHT/2)) 
                       || charPositions.some(c => Math.abs(c.pos.x - x) < 2 && Math.abs(c.pos.y - y) < 2);

        if (isPath && x > 1 && x < MAP_WIDTH-2 && y > 1 && y < MAP_HEIGHT-2) {
            // Determine neighbors for organic edges
            const neighbors = {
                n: (x === Math.floor(MAP_WIDTH/2) || y-1 === Math.floor(MAP_HEIGHT/2)) || charPositions.some(c => Math.abs(c.pos.x - x) < 2 && Math.abs(c.pos.y - (y-1)) < 2),
                s: (x === Math.floor(MAP_WIDTH/2) || y+1 === Math.floor(MAP_HEIGHT/2)) || charPositions.some(c => Math.abs(c.pos.x - x) < 2 && Math.abs(c.pos.y - (y+1)) < 2),
                w: (x-1 === Math.floor(MAP_WIDTH/2) || y === Math.floor(MAP_HEIGHT/2)) || charPositions.some(c => Math.abs(c.pos.x - (x-1)) < 2 && Math.abs(c.pos.y - y) < 2),
                e: (x+1 === Math.floor(MAP_WIDTH/2) || y === Math.floor(MAP_HEIGHT/2)) || charPositions.some(c => Math.abs(c.pos.x - (x+1)) < 2 && Math.abs(c.pos.y - y) < 2),
            };
            drawOrganicPath(ctx, x, y, neighbors);
        } else {
            drawTexturedGrass(ctx, x, y, seed);
        }
      }
    }

    // --- Layer 2: Sorting Render Queue ---
    const renderQueue: RenderItem[] = [];

    // Static Objects
    staticObjects.forEach(o => {
        // Recalc zIndex based on type
        let z = o.y * TILE_SIZE;
        if(o.type === 'tree') z += TILE_SIZE - 2; // base of tree
        renderQueue.push({...o, zIndex: z});
    });

    // Houses
    charPositions.forEach((c, i) => {
        renderQueue.push({ type: 'house', x: c.pos.x, y: c.pos.y - 1, zIndex: (c.pos.y - 1) * TILE_SIZE + TILE_SIZE - 10, data: {hash: i} });
    });

    // NPCs
    charPositions.forEach(c => {
        renderQueue.push({ type: 'npc', x: c.pos.x, y: c.pos.y, zIndex: c.pos.y * TILE_SIZE + TILE_SIZE/2, data: c });
    });

    // Player
    renderQueue.push({ type: 'player', x: player.x, y: player.y, zIndex: player.y * TILE_SIZE + TILE_SIZE/2 });

    // Sort by Y (zIndex) to handle occlusion
    renderQueue.sort((a, b) => a.zIndex - b.zIndex);

    // Draw Loop
    renderQueue.forEach(item => {
        if (item.type === 'house') {
            drawDetailedHouse(ctx, item.x, item.y, item.data.hash);
            // Draw smoke occasionally
            drawSmoke(ctx, item.x * TILE_SIZE + TILE_SIZE * 1.8 - 15, item.y * TILE_SIZE - 40, tick + item.data.hash * 50);
        } else if (item.type === 'tree') {
            drawTree(ctx, item.x, item.y);
        } else if (item.type === 'fence') {
            drawFence(ctx, item.x, item.y, item.data.h);
        } else if (item.type === 'npc') {
            const c = item.data as Character;
            drawCharacterSprite(ctx, item.x, item.y, c.rpgColor, false, tick + (c.id.charCodeAt(0)), 0);

            // Name Tag
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.fillRect(item.x * TILE_SIZE, item.y * TILE_SIZE - 12, TILE_SIZE, 10);
            ctx.fillStyle = 'white';
            ctx.font = 'bold 8px sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText(c.name.substring(0, 10), item.x * TILE_SIZE + TILE_SIZE/2, item.y * TILE_SIZE - 4);

        } else if (item.type === 'player') {
            drawCharacterSprite(ctx, item.x, item.y, '#6366f1', true, tick, lastDir);

            // Arrow
            ctx.fillStyle = '#facc15';
            ctx.beginPath();
            const px = item.x * TILE_SIZE + TILE_SIZE/2;
            const py = item.y * TILE_SIZE - 16;
            ctx.moveTo(px, py);
            ctx.lineTo(px - 4, py - 6);
            ctx.lineTo(px + 4, py - 6);
            ctx.fill();
        }
    });

    // Vignette
    const grad = ctx.createRadialGradient(canvas.width/2, canvas.height/2, canvas.height/3, canvas.width/2, canvas.height/2, canvas.height);
    grad.addColorStop(0, 'rgba(0,0,0,0)');
    grad.addColorStop(1, 'rgba(0,0,0,0.4)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

  }, [player, charPositions, tick, lastDir, staticObjects]);

  const handleManualSave = () => {
    onSave({
      playerX: player.x,
      playerY: player.y,
      completedSceneIds: initialState?.completedSceneIds || []
    });
  };

  return (
    <div className="relative w-full h-full bg-gray-950 flex flex-col items-center justify-center p-4 overflow-hidden">
      {/* HUD */}
      <div className="absolute top-4 left-4 flex gap-4 z-10 bg-gray-900/80 p-3 rounded-xl border border-gray-700 backdrop-blur-sm shadow-xl">
        <div>
          <h1 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-purple-400 leading-none" style={{fontFamily: 'monospace'}}>PIXEL VILLAGE</h1>
          <span className="text-xs text-gray-400 font-mono">POP: {characters.length}</span>
        </div>
      </div>

      <div className="relative rounded-xl shadow-2xl overflow-hidden border-[8px] border-gray-800 bg-black">
        <canvas 
          ref={canvasRef}
          width={MAP_WIDTH * TILE_SIZE}
          height={MAP_HEIGHT * TILE_SIZE}
          className="block max-w-full max-h-[80vh] object-contain"
          style={{ imageRendering: 'pixelated' }}
        />

        {nearbyChar && (
          <div className="absolute bottom-12 left-1/2 -translate-x-1/2 bg-white text-black px-6 py-3 rounded-xl border-4 border-indigo-500 animate-bounce shadow-xl z-20 flex flex-col items-center min-w-[150px]">
            <span className="text-xs font-bold text-indigo-600 uppercase tracking-widest">Talk to</span>
            <span className="text-xl font-black">{nearbyChar.name}</span>
            <div className="text-[10px] text-gray-400 mt-1 font-mono">[SPACE]</div>
          </div>
        )}
      </div>

      <div className="absolute bottom-8 right-8 flex gap-3 z-10">
         <button onClick={handleManualSave} className="bg-indigo-600 p-4 rounded-full hover:bg-indigo-500 text-white shadow-lg transition transform hover:scale-110 border-2 border-indigo-400" title="Save Game">
           <Save size={24} />
         </button>
         <button onClick={onExit} className="bg-gray-800 p-4 rounded-full hover:bg-red-900/80 text-white border-2 border-gray-600 shadow-lg transition transform hover:scale-110" title="Exit to Editor">
           <LogOut size={24} />
         </button>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { Character, RPGState } from '../types';
import { Save, LogOut } from 'lucide-react';

interface RPGWorldProps {
  characters: Character[];
  onTriggerScene: (characterId: string) => void;
  initialState?: RPGState;
  onSave: (state: RPGState) => void;
  onExit: () => void;
}

const TILE_SIZE = 48;
const MAP_WIDTH = 24;
const MAP_HEIGHT = 18;

// --- Advanced Pixel Art Helpers ---

// Lighten or darken a hex color
const adjustColor = (color: string, amount: number) => {
  return '#' + color.replace(/^#/, '').replace(/../g, color => ('0' + Math.min(255, Math.max(0, parseInt(color, 16) + amount)).toString(16)).substr(-2));
}

const drawRect = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string) => {
  ctx.fillStyle = color;
  ctx.fillRect(Math.floor(x), Math.floor(y), Math.floor(w), Math.floor(h));
};

const drawCircle = (ctx: CanvasRenderingContext2D, x: number, y: number, r: number, color: string) => {
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fill();
};

// --- Procedural Assets ---

const drawTexturedGrass = (ctx: CanvasRenderingContext2D, x: number, y: number, seed: number) => {
  const baseX = x * TILE_SIZE;
  const baseY = y * TILE_SIZE;

  // Base Layer with slight variation
  const rand = (n: number) => Math.sin(seed * n) * 10000 - Math.floor(Math.sin(seed * n) * 10000);

  // Checkboard pattern for "grass texture"
  ctx.fillStyle = '#4ade80'; 
  ctx.fillRect(baseX, baseY, TILE_SIZE, TILE_SIZE);

  // Noise
  for(let i=0; i<4; i++) {
     const ox = Math.floor(rand(i + 10) * TILE_SIZE);
     const oy = Math.floor(rand(i + 20) * TILE_SIZE);
     const w = Math.floor(rand(i + 30) * 4) + 2;
     drawRect(ctx, baseX + ox, baseY + oy, w, 2, '#3b82f615'); // very subtle blueish shadow for depth
     drawRect(ctx, baseX + ox, baseY + oy - 1, w, 2, '#22c55e'); // grass blade
  }

  // Flowers (rare)
  if (rand(99) > 0.95) {
     const fx = baseX + Math.floor(rand(100) * (TILE_SIZE - 6));
     const fy = baseY + Math.floor(rand(101) * (TILE_SIZE - 6));
     const color = rand(55) > 0.5 ? '#f472b6' : '#facc15';
     drawRect(ctx, fx, fy + 2, 1, 3, '#166534'); // stem
     drawCircle(ctx, fx, fy, 2, color); // bloom
     drawCircle(ctx, fx, fy, 1, 'white');
  }
};

const drawOrganicPath = (ctx: CanvasRenderingContext2D, x: number, y: number, neighbors: {n: boolean, s: boolean, e: boolean, w: boolean}) => {
  const baseX = x * TILE_SIZE;
  const baseY = y * TILE_SIZE;

  // Base dirt
  drawRect(ctx, baseX, baseY, TILE_SIZE, TILE_SIZE, '#d6bcfa'); // Magic stone path base

  // Add "erosion" to corners if no neighbor
  if (!neighbors.w) drawRect(ctx, baseX, baseY, 4, TILE_SIZE, '#4ade80'); // grass encroach left
  if (!neighbors.e) drawRect(ctx, baseX + TILE_SIZE - 4, baseY, 4, TILE_SIZE, '#4ade80'); // grass encroach right
  if (!neighbors.n) drawRect(ctx, baseX, baseY, TILE_SIZE, 4, '#4ade80'); // grass encroach top
  if (!neighbors.s) drawRect(ctx, baseX, baseY + TILE_SIZE - 4, TILE_SIZE, 4, '#4ade80'); // grass encroach bottom

  // Cobblestones
  ctx.fillStyle = '#c084fc'; // Darker purple stones
  for(let i = 0; i < 5; i++) {
     drawRect(ctx, baseX + 5 + i*8, baseY + 5 + (i%2)*10, 6, 4, 'rgba(0,0,0,0.1)'); // shadow
     drawRect(ctx, baseX + 5 + i*8, baseY + 4 + (i%2)*10, 6, 4, '#e9d8fd'); // stone
  }
};

const drawTree = (ctx: CanvasRenderingContext2D, x: number, y: number) => {
  const baseX = x * TILE_SIZE + TILE_SIZE/2;
  const baseY = y * TILE_SIZE + TILE_SIZE - 8; // Tree base position

  // Shadow
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.beginPath();
  ctx.ellipse(baseX, baseY, 16, 6, 0, 0, Math.PI * 2);
  ctx.fill();

  // Trunk
  drawRect(ctx, baseX - 6, baseY - 24, 12, 26, '#451a03'); // Dark wood
  drawRect(ctx, baseX - 4, baseY - 24, 4, 24, '#78350f'); // Highlight wood

  // Leaves (Cluster of circles)
  const leafColor = '#15803d';
  const leafHighlight = '#22c55e';

  const clusters = [
    {x: 0, y: -45, r: 20},
    {x: -12, y: -35, r: 16},
    {x: 12, y: -35, r: 16},
    {x: 0, y: -25, r: 18},
  ];

  clusters.forEach(c => {
    drawCircle(ctx, baseX + c.x, baseY + c.y + 2, c.r, 'rgba(0,0,0,0.2)'); // Self shadow
    drawCircle(ctx, baseX + c.x, baseY + c.y, c.r, leafColor);
    drawCircle(ctx, baseX + c.x - 2, baseY + c.y - 2, c.r - 4, leafHighlight);
  });
};

const drawFence = (ctx: CanvasRenderingContext2D, x: number, y: number, horizontal: boolean) => {
  const baseX = x * TILE_SIZE;
  const baseY = y * TILE_SIZE;

  // Shadow
  if (horizontal) {
    drawRect(ctx, baseX, baseY + TILE_SIZE/2 + 8, TILE_SIZE, 4, 'rgba(0,0,0,0.2)');
  } else {
    drawRect(ctx, baseX + TILE_SIZE/2 + 2, baseY, 4, TILE_SIZE, 'rgba(0,0,0,0.2)');
  }

  const woodDark = '#78350f';
  const woodLight = '#92400e';

  // Posts
  const drawPost = (px: number, py: number) => {
    drawRect(ctx, px, py - 16, 6, 24, woodDark);
    drawRect(ctx, px + 1, py - 16 + 1, 4, 22, woodLight);
    drawRect(ctx, px, py - 16, 6, 1, '#fbbf24'); // Top cap
  };

  if (horizontal) {
    drawRect(ctx, baseX, baseY + TILE_SIZE/2 - 8, TILE_SIZE, 4, woodDark); // Rail
    drawPost(baseX + 2, baseY + TILE_SIZE/2 + 8);
    drawPost(baseX + TILE_SIZE - 8, baseY + TILE_SIZE/2 + 8);
  } else {
    drawRect(ctx, baseX + TILE_SIZE/2 - 3, baseY, 4, TILE_SIZE, woodDark); // Rail
    drawPost(baseX + TILE_SIZE/2 - 3, baseY + TILE_SIZE/2);
  }
};

const drawDetailedHouse = (ctx: CanvasRenderingContext2D, x: number, y: number, colorHash: number) => {
  const baseX = x * TILE_SIZE;
  const baseY = y * TILE_SIZE;

  // House Dimensions
  const w = TILE_SIZE * 1.8;
  const h = TILE_SIZE * 1.5;
  const hx = baseX - (w - TILE_SIZE)/2;
  const hy = baseY - TILE_SIZE * 0.5;

  // Shadow
  ctx.fillStyle = 'rgba(0,0,0,0.4)';
  ctx.fillRect(hx + 4, hy + h - 8, w, 12);

  // Walls
  const wallColor = colorHash % 2 === 0 ? '#fef3c7' : '#e5e7eb'; // Cream or Grey
  drawRect(ctx, hx, hy, w, h, '#78350f'); // Dark frame
  drawRect(ctx, hx + 2, hy + 2, w - 4, h - 4, wallColor);

  // Beams
  drawRect(ctx, hx + 2, hy + h/2, w - 4, 4, '#78350f'); // Cross beam
  drawRect(ctx, hx + w/2 - 2, hy + 2, 4, h/2 - 2, '#78350f'); // Vertical beam top

  // Roof (A-Frame)
  const roofH = 40;
  const roofColor = colorHash % 3 === 0 ? '#991b1b' : (colorHash % 3 === 1 ? '#1e40af' : '#3f6212'); // Red, Blue, Green

  ctx.fillStyle = roofColor;
  ctx.beginPath();
  ctx.moveTo(hx - 8, hy); // Bottom Left
  ctx.lineTo(hx + w/2, hy - roofH); // Top
  ctx.lineTo(hx + w + 8, hy); // Bottom Right
  ctx.fill();

  // Roof Shingles details
  ctx.strokeStyle = 'rgba(0,0,0,0.2)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  for(let i=0; i<6; i++) {
     const yLevel = hy - (roofH * (i/6));
     const xSpread = (w + 16) * (1 - i/6);
     const xStart = hx + w/2 - xSpread/2;
     ctx.moveTo(xStart, yLevel);
     ctx.lineTo(xStart + xSpread, yLevel);
  }
  ctx.stroke();

  // Chimney
  drawRect(ctx, hx + w - 20, hy - roofH + 10, 10, 20, '#57534e');
  drawRect(ctx, hx + w - 22, hy - roofH + 8, 14, 4, '#44403c'); // Cap

  // Door
  const doorW = 24;
  const doorH = 32;
  const doorX = hx + w/2 - doorW/2;
  const doorY = hy + h - doorH;

  drawRect(ctx, doorX, doorY, doorW, doorH, '#451a03');
  drawRect(ctx, doorX + 2, doorY + 2, doorW - 4, doorH - 4, '#92400e');
  drawCircle(ctx, doorX + 4, doorY + doorH/2, 2, '#fbbf24'); // Knob

  // Windows
  const winW = 16;
  const winH = 20;
  drawRect(ctx, hx + 10, hy + h/2 + 8, winW, winH, '#7dd3fc'); // Left
  drawRect(ctx, hx + w - 10 - winW, hy + h/2 + 8, winW, winH, '#7dd3fc'); // Right

  // Flower Box
  drawRect(ctx, hx + 10 - 2, hy + h/2 + 8 + winH, winW + 4, 6, '#78350f');
  drawCircle(ctx, hx + 10 + 4, hy + h/2 + 8 + winH, 3, '#f472b6');
  drawCircle(ctx, hx + 10 + 10, hy + h/2 + 8 + winH, 3, '#facc15');

};

const drawSmoke = (ctx: CanvasRenderingContext2D, x: number, y: number, tick: number) => {
   const t = (tick % 100) / 100;
   const oy = t * 30;
   const alpha = 1 - t;

   ctx.fillStyle = `rgba(200, 200, 200, ${alpha})`;
   drawCircle(ctx, x + Math.sin(t*10)*5, y - oy, 4 + t*4, `rgba(229, 231, 235, ${alpha})`);
};

// --- ENHANCED CHARACTER RENDERER ---

const drawCharacterSprite = (
  ctx: CanvasRenderingContext2D, 
  x: number, 
  y: number, 
  color: string, 
  isPlayer: boolean, 
  tick: number, 
  dir: number // 0=Down, 1=Up, 2=Left, 3=Right
) => {
  // Center in tile
  const centerX = x * TILE_SIZE + TILE_SIZE / 2;
  const centerY = y * TILE_SIZE + TILE_SIZE - 8; // Feet position

  // Palette
  const bodyColor = color;
  const bodyDark = adjustColor(color, -40);
  const skinColor = '#ffedd5';
  const skinShadow = '#fdba74';
  const hairColor = isPlayer ? '#1e3a8a' : '#573018'; // Dark Blue or Brown
  const hairLight = adjustColor(hairColor, 60);
  const shoesColor = '#1f2937';

  // Animation State
  const isMoving = (tick % 20) !== 0; // Simplified assumption for rendering, ideally driven by state
  // We use tick as a walking frame counter if needed, but here we just assume subtle idle/move
  const walkCycle = Math.abs(Math.sin(tick / 2)); // 0 to 1
  const bounce = Math.abs(Math.sin(tick / 8)) * 2;

  // Directions
  const isFront = dir === 0;
  const isBack = dir === 1;
  const isSide = dir === 2 || dir === 3;
  const isLeft = dir === 2;

  // --- 1. SHADOW ---
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.beginPath();
  ctx.ellipse(centerX, centerY, 10, 4, 0, 0, Math.PI * 2);
  ctx.fill();

  // Apply vertical bounce to everything above shadow
  const py = centerY - bounce;

  // --- 2. LEGS ---
  const legW = 5;
  const legH = 10;
  const legSep = 3;

  if (isSide) {
      // Walking animation side
      const leftLegOff = Math.sin(tick/3) * 4;
      const rightLegOff = Math.sin(tick/3 + Math.PI) * 4;
      drawRect(ctx, centerX - 2 + leftLegOff, py - legH, legW, legH, shoesColor);
      drawRect(ctx, centerX - 2 + rightLegOff, py - legH, legW, legH, shoesColor);
  } else {
      drawRect(ctx, centerX - legSep - legW/2, py - legH, legW, legH, shoesColor); // Left
      drawRect(ctx, centerX + legSep - legW/2, py - legH, legW, legH, shoesColor); // Right
  }

  // --- 3. BODY ---
  const bodyW = 16;
  const bodyH = 14;
  const bodyY = py - legH - bodyH + 2; // +2 overlap legs

  drawRect(ctx, centerX - bodyW/2, bodyY, bodyW, bodyH, bodyColor);

  // Belt/Detail
  drawRect(ctx, centerX - bodyW/2, bodyY + bodyH - 4, bodyW, 2, 'rgba(0,0,0,0.2)');

  // Collar
  if (isFront) {
    drawRect(ctx, centerX - 2, bodyY, 4, 4, '#fff');
    drawRect(ctx, centerX - 1, bodyY+1, 2, 4, bodyDark); // Tie/Opening
  }

  // --- 4. ARMS ---
  const armW = 4;
  const armH = 10;
  const armSwing = Math.sin(tick / 3) * 6;

  if (isSide) {
      // One arm visible, swinging
      const swingX = isLeft ? armSwing : -armSwing;
      drawRect(ctx, centerX - 2 + swingX, bodyY + 2, armW, armH, bodyDark);
      drawRect(ctx, centerX - 2 + swingX, bodyY + 2 + armH - 2, armW, 2, skinColor); // Hand
  } else {
      // Static arms at side
      drawRect(ctx, centerX - bodyW/2 - armW + 1, bodyY + 1, armW, armH, bodyDark); // Left
      drawRect(ctx, centerX - bodyW/2 - armW + 1, bodyY + armH - 1, armW, 2, skinColor); // Left Hand

      drawRect(ctx, centerX + bodyW/2 - 1, bodyY + 1, armW, armH, bodyDark); // Right
      drawRect(ctx, centerX + bodyW/2 - 1, bodyY + armH - 1, armW, 2, skinColor); // Right Hand
  }

  // --- 5. HEAD ---
  const headSize = 20;
  const headY = bodyY - headSize + 4; // Neck overlap

  // Face Shape
  if (!isBack) {
      drawRect(ctx, centerX - headSize/2, headY, headSize, headSize, skinColor);
      // Cheek shadow
      drawRect(ctx, centerX - headSize/2, headY + headSize - 2, headSize, 2, skinShadow);
  }

  // --- 6. FACE FEATURES ---
  if (isFront) {
      // Eyes (Blink)
      if (Math.sin(tick/10) > 0.95) {
          drawRect(ctx, centerX - 5, headY + 10, 3, 1, '#451a03');
          drawRect(ctx, centerX + 2, headY + 10, 3, 1, '#451a03');
      } else {
          drawRect(ctx, centerX - 6, headY + 8, 4, 4, '#1f2937'); // Left Eye
          drawRect(ctx, centerX + 2, headY + 8, 4, 4, '#1f2937'); // Right Eye
          drawRect(ctx, centerX - 5, headY + 9, 1, 1, '#fff'); // Glint
          drawRect(ctx, centerX + 3, headY + 9, 1, 1, '#fff'); // Glint
      }
      // Mouth (tiny)
      drawRect(ctx, centerX - 1, headY + 15, 2, 1, '#d97706');
  } else if (isSide) {
      // Profile Eye
      const eyeX = isLeft ? centerX - 6 : centerX + 4;
      drawRect(ctx, eyeX, headY + 8, 3, 4, '#1f2937');
  }

  // --- 7. HAIR ---
  // Hair Helmet Base
  const hairY = headY - 4;
  const hairH = headSize + 6;

  if (isBack) {
      // Full back hair
      drawRect(ctx, centerX - headSize/2 - 2, hairY, headSize + 4, hairH, hairColor);
      drawRect(ctx, centerX - headSize/2 + 4, hairY + 4, headSize - 8, 4, hairLight); // Highlight
  } else if (isFront) {
      // Top
      drawRect(ctx, centerX - headSize/2 - 2, hairY, headSize + 4, 8, hairColor);
      // Highlight strip
      drawRect(ctx, centerX - headSize/2 + 2, hairY + 2, headSize - 4, 2, hairLight);

      // Bangs / Sides
      drawRect(ctx, centerX - headSize/2 - 2, hairY, 4, hairH - 4, hairColor); // Left sideburn
      drawRect(ctx, centerX + headSize/2 - 2, hairY, 4, hairH - 4, hairColor); // Right sideburn

      // Forehead bangs
      drawRect(ctx, centerX - headSize/2, hairY + 6, 6, 4, hairColor);
      drawRect(ctx, centerX + headSize/2 - 6, hairY + 6, 6, 4, hairColor);
  } else if (isSide) {
      const shift = isLeft ? -2 : 2;
      drawRect(ctx, centerX - headSize/2 + shift, hairY, headSize, 8, hairColor);
      drawRect(ctx, centerX - headSize/2 + shift + (isLeft?-2:10), hairY, 4, hairH, hairColor); // Back of head hair
  }

};


interface CharacterWithPos extends Character {
  pos: { x: number; y: number };
}

interface RenderItem {
    type: 'ground' | 'path' | 'house' | 'tree' | 'fence' | 'npc' | 'player';
    x: number;
    y: number;
    zIndex: number;
    data?: any;
}

export const RPGWorld: React.FC<RPGWorldProps> = ({ 
  characters, 
  onTriggerScene, 
  initialState, 
  onSave,
  onExit
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [player, setPlayer] = useState({ x: initialState?.playerX ?? 12, y: initialState?.playerY ?? 10 });
  const [nearbyChar, setNearbyChar] = useState<Character | null>(null);
  const [tick, setTick] = useState(0);
  const [lastDir, setLastDir] = useState(0);

  // Calculate fixed positions once
  const charPositions = useMemo<CharacterWithPos[]>(() => 
    characters.map((c, i) => {
        // Distribute houses in a circle
        const cx = MAP_WIDTH / 2;
        const cy = MAP_HEIGHT / 2;
        const angle = (i / characters.length) * Math.PI * 2;
        const radius = 5;
        return { 
          ...c, 
          pos: { 
              x: Math.floor(cx + Math.cos(angle) * radius), 
              y: Math.floor(cy + Math.sin(angle) * radius) 
          } 
        };
    }),
  [characters]);

  // Static Map Objects (Trees, Fences)
  const staticObjects = useMemo(() => {
     const objs: RenderItem[] = [];

     // Trees boundary
     for(let i=0; i<MAP_WIDTH; i+=2) {
         objs.push({type: 'tree', x: i, y: 0, zIndex: 0});
         objs.push({type: 'tree', x: i, y: MAP_HEIGHT-1, zIndex: (MAP_HEIGHT-1)*TILE_SIZE});
     }
     for(let i=0; i<MAP_HEIGHT; i+=2) {
         objs.push({type: 'tree', x: 0, y: i, zIndex: i*TILE_SIZE});
         objs.push({type: 'tree', x: MAP_WIDTH-1, y: i, zIndex: i*TILE_SIZE});
     }

     // Random trees inside
     const seedRand = (s:number) => Math.sin(s)*10000 - Math.floor(Math.sin(s)*10000);
     for(let y=2; y<MAP_HEIGHT-2; y++) {
         for(let x=2; x<MAP_WIDTH-2; x++) {
             if(seedRand(x*y) > 0.96) {
                objs.push({type: 'tree', x, y, zIndex: y*TILE_SIZE});
             }
         }
     }

     // Fences
     // Simple fence around the village center?
     // Let's just place a few decorative fences
     objs.push({type: 'fence', x: 8, y: 12, zIndex: 12*TILE_SIZE, data: {h: true}});
     objs.push({type: 'fence', x: 9, y: 12, zIndex: 12*TILE_SIZE, data: {h: true}});
     objs.push({type: 'fence', x: 10, y: 12, zIndex: 12*TILE_SIZE, data: {h: true}});

     return objs;
  }, []);

  // Animation Loop
  useEffect(() => {
    const interval = setInterval(() => setTick(t => t + 1), 50);
    return () => clearInterval(interval);
  }, []);

  // Input & Movement
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      let dx = 0; let dy = 0; let newDir = lastDir;

      if (e.key === 'ArrowUp' || e.key === 'w') { dy = -1; newDir = 1; }
      if (e.key === 'ArrowDown' || e.key === 's') { dy = 1; newDir = 0; }
      if (e.key === 'ArrowLeft' || e.key === 'a') { dx = -1; newDir = 2; }
      if (e.key === 'ArrowRight' || e.key === 'd') { dx = 1; newDir = 3; }

      setLastDir(newDir);

      if (dx !== 0 || dy !== 0) {
        setPlayer(p => {
          const nx = Math.max(0, Math.min(MAP_WIDTH - 1, p.x + dx));
          const ny = Math.max(0, Math.min(MAP_HEIGHT - 1, p.y + dy));

          // Collision Logic
          // 1. House collision (house is at y-1 relative to char spawn)
          const hitHouse = charPositions.some(c => c.pos.x === nx && c.pos.y - 1 === ny);
          // 2. NPC collision
          const hitNPC = charPositions.some(c => c.pos.x === nx && c.pos.y === ny);
          // 3. Tree collision (simple check against static list)
          const hitTree = staticObjects.some(o => o.type === 'tree' && o.x === nx && o.y === ny);

          if (hitHouse || hitNPC || hitTree) return p;

          return { x: nx, y: ny };
        });
      }

      if (e.code === 'Space' || e.key === 'Enter') {
        if (nearbyChar) onTriggerScene(nearbyChar.id);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [nearbyChar, charPositions, onTriggerScene, lastDir, staticObjects]);

  // Proximity
  useEffect(() => {
    const found = charPositions.find(c => {
      const dist = Math.abs(c.pos.x - player.x) + Math.abs(c.pos.y - player.y);
      return dist <= 1;
    });
    setNearbyChar(found || null);
  }, [player, charPositions]);

  // --- RENDER ---
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Fill Background
    ctx.fillStyle = '#111827';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // --- Layer 1: Ground & Paths ---
    for (let y = 0; y < MAP_HEIGHT; y++) {
      for (let x = 0; x < MAP_WIDTH; x++) {
        const seed = x * y + x;
        // Path logic: center cross + lines to houses
        const isPath = (x === Math.floor(MAP_WIDTH/2) || y === Math.floor(MAP_HEIGHT/2)) 
                       || charPositions.some(c => Math.abs(c.pos.x - x) < 2 && Math.abs(c.pos.y - y) < 2);

        if (isPath && x > 1 && x < MAP_WIDTH-2 && y > 1 && y < MAP_HEIGHT-2) {
            // Determine neighbors for organic edges
            const neighbors = {
                n: (x === Math.floor(MAP_WIDTH/2) || y-1 === Math.floor(MAP_HEIGHT/2)) || charPositions.some(c => Math.abs(c.pos.x - x) < 2 && Math.abs(c.pos.y - (y-1)) < 2),
                s: (x === Math.floor(MAP_WIDTH/2) || y+1 === Math.floor(MAP_HEIGHT/2)) || charPositions.some(c => Math.abs(c.pos.x - x) < 2 && Math.abs(c.pos.y - (y+1)) < 2),
                w: (x-1 === Math.floor(MAP_WIDTH/2) || y === Math.floor(MAP_HEIGHT/2)) || charPositions.some(c => Math.abs(c.pos.x - (x-1)) < 2 && Math.abs(c.pos.y - y) < 2),
                e: (x+1 === Math.floor(MAP_WIDTH/2) || y === Math.floor(MAP_HEIGHT/2)) || charPositions.some(c => Math.abs(c.pos.x - (x+1)) < 2 && Math.abs(c.pos.y - y) < 2),
            };
            drawOrganicPath(ctx, x, y, neighbors);
        } else {
            drawTexturedGrass(ctx, x, y, seed);
        }
      }
    }

    // --- Layer 2: Sorting Render Queue ---
    const renderQueue: RenderItem[] = [];

    // Static Objects
    staticObjects.forEach(o => {
        // Recalc zIndex based on type
        let z = o.y * TILE_SIZE;
        if(o.type === 'tree') z += TILE_SIZE - 2; // base of tree
        renderQueue.push({...o, zIndex: z});
    });

    // Houses
    charPositions.forEach((c, i) => {
        renderQueue.push({ type: 'house', x: c.pos.x, y: c.pos.y - 1, zIndex: (c.pos.y - 1) * TILE_SIZE + TILE_SIZE - 10, data: {hash: i} });
    });

    // NPCs
    charPositions.forEach(c => {
        renderQueue.push({ type: 'npc', x: c.pos.x, y: c.pos.y, zIndex: c.pos.y * TILE_SIZE + TILE_SIZE/2, data: c });
    });

    // Player
    renderQueue.push({ type: 'player', x: player.x, y: player.y, zIndex: player.y * TILE_SIZE + TILE_SIZE/2 });

    // Sort by Y (zIndex) to handle occlusion
    renderQueue.sort((a, b) => a.zIndex - b.zIndex);

    // Draw Loop
    renderQueue.forEach(item => {
        if (item.type === 'house') {
            drawDetailedHouse(ctx, item.x, item.y, item.data.hash);
            // Draw smoke occasionally
            drawSmoke(ctx, item.x * TILE_SIZE + TILE_SIZE * 1.8 - 15, item.y * TILE_SIZE - 40, tick + item.data.hash * 50);
        } else if (item.type === 'tree') {
            drawTree(ctx, item.x, item.y);
        } else if (item.type === 'fence') {
            drawFence(ctx, item.x, item.y, item.data.h);
        } else if (item.type === 'npc') {
            const c = item.data as Character;
            // NPCs face down (0) by default for now
            drawCharacterSprite(ctx, item.x, item.y, c.rpgColor, false, tick + (c.id.charCodeAt(0)), 0);

            // Name Tag
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.fillRect(item.x * TILE_SIZE, item.y * TILE_SIZE - 12, TILE_SIZE, 10);
            ctx.fillStyle = 'white';
            ctx.font = 'bold 8px sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText(c.name.substring(0, 10), item.x * TILE_SIZE + TILE_SIZE/2, item.y * TILE_SIZE - 4);

        } else if (item.type === 'player') {
            drawCharacterSprite(ctx, item.x, item.y, '#6366f1', true, tick, lastDir);

            // Arrow
            ctx.fillStyle = '#facc15';
            ctx.beginPath();
            const px = item.x * TILE_SIZE + TILE_SIZE/2;
            const py = item.y * TILE_SIZE - 16;
            ctx.moveTo(px, py);
            ctx.lineTo(px - 4, py - 6);
            ctx.lineTo(px + 4, py - 6);
            ctx.fill();
        }
    });

    // Vignette
    const grad = ctx.createRadialGradient(canvas.width/2, canvas.height/2, canvas.height/3, canvas.width/2, canvas.height/2, canvas.height);
    grad.addColorStop(0, 'rgba(0,0,0,0)');
    grad.addColorStop(1, 'rgba(0,0,0,0.4)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

  }, [player, charPositions, tick, lastDir, staticObjects]);

  const handleManualSave = () => {
    onSave({
      playerX: player.x,
      playerY: player.y,
      completedSceneIds: initialState?.completedSceneIds || []
    });
  };

  return (
    <div className="relative w-full h-full bg-gray-950 flex flex-col items-center justify-center p-4 overflow-hidden">
      {/* HUD */}
      <div className="absolute top-4 left-4 flex gap-4 z-10 bg-gray-900/80 p-3 rounded-xl border border-gray-700 backdrop-blur-sm shadow-xl">
        <div>
          <h1 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-purple-400 leading-none" style={{fontFamily: 'monospace'}}>PIXEL VILLAGE</h1>
          <span className="text-xs text-gray-400 font-mono">POP: {characters.length}</span>
        </div>
      </div>

      <div className="relative rounded-xl shadow-2xl overflow-hidden border-[8px] border-gray-800 bg-black">
        <canvas 
          ref={canvasRef}
          width={MAP_WIDTH * TILE_SIZE}
          height={MAP_HEIGHT * TILE_SIZE}
          className="block max-w-full max-h-[80vh] object-contain"
          style={{ imageRendering: 'pixelated' }}
        />

        {nearbyChar && (
          <div className="absolute bottom-12 left-1/2 -translate-x-1/2 bg-white text-black px-6 py-3 rounded-xl border-4 border-indigo-500 animate-bounce shadow-xl z-20 flex flex-col items-center min-w-[150px]">
            <span className="text-xs font-bold text-indigo-600 uppercase tracking-widest">Talk to</span>
            <span className="text-xl font-black">{nearbyChar.name}</span>
            <div className="text-[10px] text-gray-400 mt-1 font-mono">[SPACE]</div>
          </div>
        )}
      </div>

      <div className="absolute bottom-8 right-8 flex gap-3 z-10">
         <button onClick={handleManualSave} className="bg-indigo-600 p-4 rounded-full hover:bg-indigo-500 text-white shadow-lg transition transform hover:scale-110 border-2 border-indigo-400" title="Save Game">
           <Save size={24} />
         </button>
         <button onClick={onExit} className="bg-gray-800 p-4 rounded-full hover:bg-red-900/80 text-white border-2 border-gray-600 shadow-lg transition transform hover:scale-110" title="Exit to Editor">
           <LogOut size={24} />
         </button>
      </div>
    </div>
  );
};

export interface Character {
  id: string;
  name: string;
  defaultDescription: string;
  imageSrc: string | null; // Local object URL
  rpgColor: string; // Hex color for the sprite on the map
}

export interface SceneCharacterConfig {
  characterId: string;
  roleInScene: string; // Specific behavior/goal for this scene
}

export interface Scene {
  id: string;
  name: string;
  backgroundSrc: string | null; // Local object URL
  description: string; // The scenario setup
  goal: string; // The win condition to move to next scene
  characters: SceneCharacterConfig[];
}

export interface MapSpot {
  id: string;
  characterId: string;
  x: number; // Percentage 0-100
  y: number; // Percentage 0-100
}

export interface WorldMapConfig {
  backgroundSrc: string | null;
  spots: MapSpot[];
}

export interface ChatMessage {
  sender: 'user' | 'model' | 'system';
  characterId?: string; // If model, which character?
  text: string;
  timestamp: number;
}

export interface GameState {
  currentSceneIndex: number; // Used inside VN Mode
  history: ChatMessage[];
  isProcessing: boolean;
  gameOver: boolean;
}

export interface AIResponse {
  characterResponses: {
    characterId: string;
    text: string;
  }[];
  sceneGoalReached: boolean;
  sceneTransitionReason?: string;
}

export interface RPGState {
  playerX: number; // Now percentage based or pixel based? Let's stick to percentage for the image map to be responsive
  playerY: number;
  completedSceneIds: string[];
}

export interface GameSaveData {
  rpgState: RPGState;
  vnState: GameState | null; // Null if saved while on map
  timestamp: number;
}

import React, { useState, useEffect } from 'react';
import { Editor } from './components/Editor';
import { Player } from './components/Player';
import { RPGWorld } from './components/RPGWorld';
import { Character, Scene, GameSaveData, RPGState, WorldMapConfig } from './types';

// Default Data for quick start
const DEFAULT_CHARS: Character[] = [
  { 
    id: '1', 
    name: 'Aiko', 
    defaultDescription: 'A cheerful and curious android girl who loves learning about humans.', 
    imageSrc: null,
    rpgColor: '#f472b6' // Pink
  },
  { 
    id: '2', 
    name: 'Kael', 
    defaultDescription: 'A grumpy but skilled mechanic who fixes robots.', 
    imageSrc: null,
    rpgColor: '#60a5fa' // Blue
  }
];

const DEFAULT_SCENES: Scene[] = [
  {
    id: 's1',
    name: 'The Workshop',
    backgroundSrc: null,
    description: 'A cluttered workshop filled with robot parts. Kael is working on a workbench. Aiko is watching closely.',
    goal: 'Convince Kael to fix your broken radio.',
    characters: [
      { characterId: '1', roleInScene: 'Curious onlooker, wants to help but is clumsy.' },
      { characterId: '2', roleInScene: 'Busy, easily annoyed, does not want to be disturbed.' }
    ]
  }
];

const DEFAULT_MAP: WorldMapConfig = {
  backgroundSrc: null,
  spots: [
    { id: 'spot1', characterId: '1', x: 40, y: 50 },
    { id: 'spot2', characterId: '2', x: 60, y: 30 }
  ]
};

const PROJECT_STORAGE_KEY = 'vn_creator_project';
const GAME_SAVE_KEY = 'vn_creator_savegame';

const App: React.FC = () => {
  const [mode, setMode] = useState<'edit' | 'rpg' | 'vn'>('edit');

  // Data State
  const [characters, setCharacters] = useState<Character[]>(DEFAULT_CHARS);
  const [scenes, setScenes] = useState<Scene[]>(DEFAULT_SCENES);
  const [mapConfig, setMapConfig] = useState<WorldMapConfig>(DEFAULT_MAP);

  // Game Play State
  const [rpgState, setRpgState] = useState<RPGState>({ playerX: 50, playerY: 90, completedSceneIds: [] });
  const [activeSceneIndex, setActiveSceneIndex] = useState<number>(-1);
  const [vnHistory, setVnHistory] = useState<any[]>([]); // Temp holder for history if we save mid-VN

  const [hasSaveGame, setHasSaveGame] = useState(false);

  // Check for save game on mount
  useEffect(() => {
    const savedGame = localStorage.getItem(GAME_SAVE_KEY);
    if (savedGame) {
      setHasSaveGame(true);
    }

    // Auto-load project if exists
    const savedProject = localStorage.getItem(PROJECT_STORAGE_KEY);
    if (savedProject) {
      try {
        const { characters: savedChars, scenes: savedScenes, mapConfig: savedMap } = JSON.parse(savedProject);
        if (savedChars) setCharacters(savedChars);
        if (savedScenes) setScenes(savedScenes);
        if (savedMap) setMapConfig(savedMap);
      } catch (e) {
        console.error("Failed to load project", e);
      }
    }
  }, []);

  const handleSaveProject = () => {
    const data = { characters, scenes, mapConfig };
    localStorage.setItem(PROJECT_STORAGE_KEY, JSON.stringify(data));
    alert("Project Settings (Characters, Scenes & Map) saved successfully!");
  };

  const handleStartNewGame = () => {
    setRpgState({ playerX: 50, playerY: 90, completedSceneIds: [] });
    setVnHistory([]);
    setActiveSceneIndex(-1);
    setMode('rpg');
  };

  const handleContinueGame = () => {
    const savedGame = localStorage.getItem(GAME_SAVE_KEY);
    if (savedGame) {
      try {
        const parsed: GameSaveData = JSON.parse(savedGame);
        setRpgState(parsed.rpgState);

        // If we saved *inside* a VN scene
        if (parsed.vnState) {
          setActiveSceneIndex(parsed.vnState.currentSceneIndex);
          setVnHistory(parsed.vnState.history);
          setMode('vn');
        } else {
          setMode('rpg');
        }
      } catch (e) {
        console.error("Corrupt save file");
        handleStartNewGame();
      }
    }
  };

  const handleSaveGame = (currentVnState?: { index: number, history: any[] }) => {
    const saveData: GameSaveData = {
      rpgState: rpgState,
      vnState: currentVnState ? {
        currentSceneIndex: currentVnState.index,
        history: currentVnState.history,
        isProcessing: false,
        gameOver: false
      } : null,
      timestamp: Date.now()
    };
    localStorage.setItem(GAME_SAVE_KEY, JSON.stringify(saveData));
    setHasSaveGame(true);

    if(!currentVnState) {
       alert("Game Saved!");
    }
  };

  // --- Transitions ---

  const handleInteractWithChar = (charId: string) => {
    // Find the first scene this character is in that hasn't been completed
    // Or just the first one if all are done (replayability)
    const availableScenes = scenes.filter(s => s.characters.some(c => c.characterId === charId));

    // Simple logic: Find first scene index in the global list that matches
    const sceneToPlay = availableScenes.find(s => !rpgState.completedSceneIds.includes(s.id)) || availableScenes[0];

    if (sceneToPlay) {
      const realIndex = scenes.findIndex(s => s.id === sceneToPlay.id);
      setActiveSceneIndex(realIndex);
      setVnHistory([]); // Clear history for new scene
      setMode('vn');
    } else {
      alert("This character has nothing more to say right now.");
    }
  };

  const handleSceneComplete = (sceneIndex: number) => {
    const scene = scenes[sceneIndex];
    if (scene) {
        setRpgState(prev => ({
            ...prev,
            completedSceneIds: [...prev.completedSceneIds, scene.id]
        }));
    }
    setMode('rpg');
  };

  return (
    <div className="min-h-screen bg-gray-900 text-gray-100 font-sans selection:bg-indigo-500 selection:text-white">
      {mode === 'edit' && (
        <Editor 
          characters={characters}
          scenes={scenes}
          mapConfig={mapConfig}
          onUpdateCharacters={setCharacters}
          onUpdateScenes={setScenes}
          onUpdateMap={setMapConfig}
          onPlay={handleStartNewGame}
          onSaveProject={handleSaveProject}
          hasSaveGame={hasSaveGame}
          onContinueGame={handleContinueGame}
        />
      )}

      {mode === 'rpg' && (
        <RPGWorld 
          characters={characters}
          mapConfig={mapConfig}
          initialState={rpgState}
          onTriggerScene={handleInteractWithChar}
          onSave={(updatedRpgState) => {
             setRpgState(updatedRpgState);
             // We need to pass the updated state immediately to save because setState is async
             const saveData: GameSaveData = {
                rpgState: updatedRpgState,
                vnState: null,
                timestamp: Date.now()
             };
             localStorage.setItem(GAME_SAVE_KEY, JSON.stringify(saveData));
             setHasSaveGame(true);
             alert("Game Saved!");
          }}
          onExit={() => setMode('edit')}
        />
      )}

      {mode === 'vn' && activeSceneIndex >= 0 && (
        <Player 
          scenes={scenes}
          characters={characters}
          // Construct a temp initial state for the Player component
          initialState={{
            currentSceneIndex: activeSceneIndex,
            history: vnHistory,
            timestamp: 0,
            rpgState: rpgState, // Pass through, though Player doesn't use it directly usually
            vnState: null
          }}
          onExit={() => {
             // Just go back to map if exiting manually
             setMode('rpg');
          }}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Plus, Trash2, Image as ImageIcon, User, Target, Save, PlayCircle, RotateCcw, Map as MapIcon, MousePointerClick } from 'lucide-react';
import { Character, Scene, SceneCharacterConfig, WorldMapConfig } from '../types';
import { Button } from './ui/Button';

interface EditorProps {
  characters: Character[];
  scenes: Scene[];
  mapConfig: WorldMapConfig;
  onUpdateCharacters: (chars: Character[]) => void;
  onUpdateScenes: (scenes: Scene[]) => void;
  onUpdateMap: (config: WorldMapConfig) => void;
  onPlay: () => void;
  onSaveProject: () => void;
  hasSaveGame: boolean;
  onContinueGame: () => void;
}

export const Editor: React.FC<EditorProps> = ({
  characters,
  scenes,
  mapConfig,
  onUpdateCharacters,
  onUpdateScenes,
  onUpdateMap,
  onPlay,
  onSaveProject,
  hasSaveGame,
  onContinueGame
}) => {
  const [activeTab, setActiveTab] = useState<'chars' | 'scenes' | 'map'>('chars');
  const [selectedCharForMap, setSelectedCharForMap] = useState<string>('');
  const mapContainerRef = useRef<HTMLDivElement>(null);

  // --- Character Handlers ---
  const addCharacter = () => {
    const newChar: Character = {
      id: crypto.randomUUID(),
      name: 'New Character',
      defaultDescription: 'A friendly helper.',
      imageSrc: null,
      rpgColor: '#ef4444', // Default Red
    };
    onUpdateCharacters([...characters, newChar]);
  };

  const updateCharacter = (id: string, updates: Partial<Character>) => {
    onUpdateCharacters(characters.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const handleCharImageUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCharacter(id, { imageSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  // --- Scene Handlers ---
  const addScene = () => {
    const newScene: Scene = {
      id: crypto.randomUUID(),
      name: `Scene ${scenes.length + 1}`,
      backgroundSrc: null,
      description: 'You are in a quiet room.',
      goal: 'Say hello.',
      characters: [],
    };
    onUpdateScenes([...scenes, newScene]);
  };

  const updateScene = (id: string, updates: Partial<Scene>) => {
    onUpdateScenes(scenes.map(s => s.id === id ? { ...s, ...updates } : s));
  };

  const handleBgUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleCharInScene = (sceneId: string, charId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const exists = scene.characters.find(c => c.characterId === charId);
    let newChars: SceneCharacterConfig[];

    if (exists) {
      newChars = scene.characters.filter(c => c.characterId !== charId);
    } else {
      newChars = [...scene.characters, { characterId: charId, roleInScene: 'Default behavior' }];
    }
    updateScene(sceneId, { characters: newChars });
  };

  const updateSceneCharRole = (sceneId: string, charId: string, role: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;
    const newChars = scene.characters.map(c => c.characterId === charId ? { ...c, roleInScene: role } : c);
    updateScene(sceneId, { characters: newChars });
  };

  // --- Map Handlers ---
  const handleMapBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        onUpdateMap({ ...mapConfig, backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const handleMapClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!selectedCharForMap || !mapContainerRef.current) return;

    // Check if clicked on an existing pin (to avoid placing one on top)
    if ((e.target as HTMLElement).closest('.map-pin')) return;

    const rect = mapContainerRef.current.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;

    const newSpot = {
      id: crypto.randomUUID(),
      characterId: selectedCharForMap,
      x, 
      y
    };

    onUpdateMap({
      ...mapConfig,
      spots: [...mapConfig.spots, newSpot]
    });

    // Optional: Reset selection to allow quick placement of same char or require re-select?
    // Let's keep it selected for multiple placements of same char type if needed, or easier workflow.
  };

  const removeSpot = (spotId: string) => {
    onUpdateMap({
      ...mapConfig,
      spots: mapConfig.spots.filter(s => s.id !== spotId)
    });
  };

  return (
    <div className="flex flex-col h-full max-w-6xl mx-auto p-4 md:p-8">
      <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
        <h1 className="text-3xl font-bold text-indigo-400">VN Creator Studio</h1>

        <div className="flex gap-3">
          <Button onClick={onSaveProject} variant="secondary" title="Save Characters & Scenarios">
            <Save size={18} /> Save Project
          </Button>

          {hasSaveGame && (
            <Button onClick={onContinueGame} className="bg-yellow-600 hover:bg-yellow-500">
              <RotateCcw size={18} /> Continue Game
            </Button>
          )}

          <Button onClick={onPlay} className="bg-green-600 hover:bg-green-500 px-6">
            <PlayCircle size={18} /> New Game
          </Button>
        </div>
      </div>

      <div className="flex gap-4 mb-6 border-b border-gray-700 pb-1">
        <button
          onClick={() => setActiveTab('chars')}
          className={`px-4 py-2 font-medium ${activeTab === 'chars' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}
        >
          Characters
        </button>
        <button
          onClick={() => setActiveTab('scenes')}
          className={`px-4 py-2 font-medium ${activeTab === 'scenes' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}
        >
          Scenarios
        </button>
        <button
          onClick={() => setActiveTab('map')}
          className={`px-4 py-2 font-medium ${activeTab === 'map' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}
        >
          World Map
        </button>
      </div>

      <div className="flex-1 overflow-y-auto pr-2">
        {activeTab === 'chars' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {characters.map(char => (
                <div key={char.id} className="bg-gray-800 p-4 rounded-xl border border-gray-700 flex gap-4">
                  <div className="w-24 h-32 bg-gray-900 rounded-lg flex-shrink-0 border border-gray-600 overflow-hidden relative group">
                    {char.imageSrc ? (
                      <img src={char.imageSrc} alt={char.name} className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center text-gray-600">
                        <User size={32} />
                      </div>
                    )}
                    <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity text-xs font-bold">
                      UPLOAD
                      <input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e)} />
                    </label>
                  </div>
                  <div className="flex-1 space-y-3">
                    <input
