                    />

                    {/* Map Sprite Uploader (Replaces Color Picker) */}
                    <div className="flex items-center gap-3">
                       <div className="w-12 h-12 bg-gray-900 rounded border border-gray-600 overflow-hidden relative group shrink-0">
                         {char.mapSpriteSrc ? (
                           <img src={char.mapSpriteSrc} alt="Sprite" className="w-full h-full object-contain" />
                         ) : (
                           <div className="w-full h-full flex items-center justify-center text-gray-600" title="Map Sprite">
                             <MapIcon size={16} />
                           </div>
                         )}
                         <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity">
                            <FileUp size={16} className="text-white"/>
                            <input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e, 'mapSpriteSrc')} />
                         </label>
                       </div>
                       <div className="text-xs text-gray-400">
                         <span className="font-bold block text-gray-300">Map Sprite</span>
                         <span className="text-[10px]">Icon used on the world map.</span>
                       </div>
                    </div>

                    <textarea
                      className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-1 h-20 text-sm focus:border-indigo-500 outline-none resize-none"
                      value={char.defaultDescription}
