import React, { useEffect, useRef, useState } from 'react';
import { Character, RPGState, WorldMapConfig } from '../types';
import { Save, LogOut } from 'lucide-react';

interface RPGWorldProps {
  characters: Character[];
  mapConfig: WorldMapConfig;
  onTriggerScene: (characterId: string) => void;
  initialState?: RPGState;
  onSave: (state: RPGState) => void;
  onExit: () => void;
}

export const RPGWorld: React.FC<RPGWorldProps> = ({ 
  characters, 
  mapConfig,
  onTriggerScene, 
  initialState, 
  onSave,
  onExit
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [hoveredCharId, setHoveredCharId] = useState<string | null>(null);
  const [canvasDims, setCanvasDims] = useState({ width: 1000, height: 750 });

  // Cache for loaded sprite images to avoid reloading every frame
  const spritesRef = useRef<Record<string, HTMLImageElement>>({});
  const [spritesLoaded, setSpritesLoaded] = useState(false);

  // Preload Sprites
  useEffect(() => {
    let active = true;
    const loadSprites = async () => {
        const promises = characters.map(c => {
            if (!c.mapSpriteSrc) return Promise.resolve();
            return new Promise<void>((resolve) => {
                const img = new Image();
                img.src = c.mapSpriteSrc!;
                img.onload = () => {
                    if(active) spritesRef.current[c.id] = img;
                    resolve();
                };
                img.onerror = () => resolve(); // Resolve anyway to not block
            });
        });

        await Promise.all(promises);
        if (active) setSpritesLoaded(true);
    };
    loadSprites();
    return () => { active = false; };
  }, [characters]);

  // Adjust canvas dimensions to match background image aspect ratio
  useEffect(() => {
    if (mapConfig.backgroundSrc) {
        const img = new Image();
        img.src = mapConfig.backgroundSrc;
        img.onload = () => {
            setCanvasDims(prev => {
                // Only update if dimensions differ to avoid loop
                if (prev.width !== img.naturalWidth || prev.height !== img.naturalHeight) {
                    return { width: img.naturalWidth, height: img.naturalHeight };
                }
                return prev;
            });
        };
    } else {
        // Default 4:3 resolution if no map
        setCanvasDims({ width: 1000, height: 750 });
    }
  }, [mapConfig.backgroundSrc]);

  // Helper: Convert screen coordinates to Percentage (0-100)
  const getMousePosInPercent = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };

    const rect = canvas.getBoundingClientRect();
    // Calculate scale if canvas display size differs from internal resolution
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;
    return { x, y };
  };

  const checkHit = (xPct: number, yPct: number) => {
    // Hit radius in percentage. Slightly larger for easier clicking.
    const THRESHOLD = 4; 

    return mapConfig.spots.find(spot => {
       const dx = spot.x - xPct;
       const dy = spot.y - yPct;
       return Math.sqrt(dx*dx + dy*dy) < THRESHOLD;
    });
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const { x, y } = getMousePosInPercent(e);
    const hit = checkHit(x, y);

    if (hit) {
      if (hoveredCharId !== hit.characterId) {
        setHoveredCharId(hit.characterId);
      }
    } else {
      if (hoveredCharId !== null) {
        setHoveredCharId(null);
      }
    }
  };

  const handleClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const { x, y } = getMousePosInPercent(e);
    const hit = checkHit(x, y);
    if (hit) {
      onTriggerScene(hit.characterId);
    }
  };

  // Render Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const bgImage = new Image();
    if (mapConfig.backgroundSrc) {
       bgImage.src = mapConfig.backgroundSrc;
    }

    const render = () => {
       // Draw Background
       if (mapConfig.backgroundSrc && bgImage.complete) {
           ctx.drawImage(bgImage, 0, 0, canvas.width, canvas.height);
       } else if (mapConfig.backgroundSrc) {
           // Wait for load
       } else {
           // Fallback grid
           ctx.fillStyle = '#111827';
           ctx.fillRect(0,0, canvas.width, canvas.height);
           ctx.strokeStyle = '#374151';
           ctx.lineWidth = 1;
           for(let i=0; i<canvas.width; i+=40) {
               ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, canvas.height); ctx.stroke();
           }
           for(let i=0; i<canvas.height; i+=40) {
               ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(canvas.width, i); ctx.stroke();
           }
       }

       // Helper: Percent to Pixels
       const toPx = (pct: number, dim: number) => (pct / 100) * dim;

       // Draw Spots (Characters)
       mapConfig.spots.forEach(spot => {
          const char = characters.find(c => c.id === spot.characterId);
          if (!char) return;

          const cx = toPx(spot.x, canvas.width);
          const cy = toPx(spot.y, canvas.height);
          const isHovered = hoveredCharId === char.id;

          const spriteImg = spritesRef.current[char.id];

          if (spriteImg) {
              // Draw Sprite Image
              // Size: 50x50 pixels, centered (scaled slightly relative to canvas size if needed, 
              // but fixed px size is safer to avoid tiny sprites on huge maps)
              // We'll stick to fixed pixel size for UI consistency, maybe scaled slightly by map width if map is HUGE.
              // Let's use a base scale factor.
              const baseScale = Math.max(canvas.width / 1000, 0.5); // Adapt size roughly to resolution
              const size = (isHovered ? 70 : 60) * baseScale; 

              ctx.save();
              if (isHovered) {
                  ctx.shadowColor = 'white';
                  ctx.shadowBlur = 15;
              } else {
                  ctx.shadowColor = 'black';
                  ctx.shadowBlur = 5;
              }

              // Draw image centered
              ctx.drawImage(spriteImg, cx - size/2, cy - size/2, size, size);
              ctx.restore();

          } else {
              // Fallback: Colored Circle
              const cx = toPx(spot.x, canvas.width);
              const cy = toPx(spot.y, canvas.height);

              // Shadow
              ctx.fillStyle = 'rgba(0,0,0,0.5)';
              ctx.beginPath();
              ctx.ellipse(cx, cy + 12, 10, 4, 0, 0, Math.PI * 2);
              ctx.fill();

              // Highlight Glow if hovered
              if (isHovered) {
                ctx.save();
                ctx.shadowColor = 'white';
                ctx.shadowBlur = 15;
                ctx.fillStyle = 'white';
                ctx.beginPath();
                ctx.arc(cx, cy, 12, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
              }

              // Sprite Pin
              ctx.fillStyle = char.rpgColor;
              ctx.beginPath();
              ctx.arc(cx, cy, 10, 0, Math.PI * 2);
              ctx.fill();

              ctx.lineWidth = 3;
              ctx.strokeStyle = isHovered ? 'white' : 'rgba(255,255,255,0.8)';
              ctx.stroke();
          }

          // Name Tag (Only on hover)
          if (isHovered) {
             ctx.save();
             // Reset transform for text to ensure it's readable and not skewed if we had transforms (we don't here)
             ctx.fillStyle = 'rgba(0,0,0,0.8)';
             ctx.font = 'bold 14px sans-serif';
             const textW = ctx.measureText(char.name).width;
             const tagY = cy - ((spriteImg ? 40 : 28) * (Math.max(canvas.width/1000, 0.5))); // Adjust tag height based on sprite size

             ctx.fillRect(cx - textW/2 - 6, tagY - 14, textW + 12, 20);

             ctx.fillStyle = 'white';
             ctx.textAlign = 'center';
             ctx.fillText(char.name, cx, tagY);
             ctx.restore();
          }
       });
    };

    if (bgImage.complete || !mapConfig.backgroundSrc) {
       render();
    } else {
       bgImage.onload = render;
    }

  }, [mapConfig, characters, hoveredCharId, spritesLoaded, canvasDims]);

  const handleManualSave = () => {
    onSave({
      completedSceneIds: initialState?.completedSceneIds || []
    });
  };

  return (
    <div className="relative w-full h-full bg-gray-950 flex flex-col items-center justify-center p-4">
      {/* HUD */}
      <div className="absolute top-4 left-4 z-10 bg-gray-900/80 p-3 rounded-xl border border-gray-700 backdrop-blur-sm shadow-xl">
        <h1 className="text-xl font-bold text-indigo-400">WORLD MAP</h1>
        <p className="text-xs text-gray-400 mt-1">Select a location to explore</p>
      </div>

      <div className="relative rounded-xl shadow-2xl overflow-hidden border-[4px] border-gray-800 bg-black max-w-full max-h-full flex items-center justify-center">
        <canvas 
          ref={canvasRef}
          width={canvasDims.width} 
          height={canvasDims.height}
          className="block max-w-full max-h-[80vh] w-auto h-auto object-contain transition-cursor duration-150"
          style={{ cursor: hoveredCharId ? 'pointer' : 'default' }}
          onClick={handleClick}
          onMouseMove={handleMouseMove}
          onMouseLeave={() => setHoveredCharId(null)}
        />
      </div>

      <div className="absolute bottom-8 right-8 flex gap-3 z-10">
         <button onClick={handleManualSave} className="bg-indigo-600 p-3 rounded-full hover:bg-indigo-500 text-white shadow-lg transition transform hover:scale-105" title="Save Game">
           <Save size={24} />
         </button>
         <button onClick={onExit} className="bg-gray-800 p-3 rounded-full hover:bg-red-900/80 text-white border border-gray-600 shadow-lg transition transform hover:scale-105" title="Exit to Editor">
           <LogOut size={24} />
         </button>
      </div>
    </div>
  );
};

