                       </div>
                    </div>

                    <textarea
                      className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-1 h-20 text-sm focus:border-indigo-500 outline-none resize-none transition-all"
                      value={char.defaultDescription}
                      onChange={(e) => updateCharacter(char.id, { defaultDescription: e.target.value })}
