                  </div>
                  <button onClick={() => onUpdateCharacters(characters.filter(c => c.id !== char.id))} className="text-gray-500 hover:text-red-500 h-fit transition-colors p-1">
                    <Trash2 size={18} />
                  </button>
                </div>
              ))}
            </div>
            <Button onClick={addCharacter} variant="secondary" className="w-full py-4 border-dashed opacity-70 hover:opacity-100">
              <Plus size={20} /> Add Character
            </Button>
          </div>
        )}

        {activeTab === 'scenes' && (
          <div className="space-y-8">
            {scenes.map((scene, idx) => (
              <div key={scene.id} className="bg-gray-800 p-6 rounded-xl border border-gray-700 space-y-4 shadow-lg">
                <div className="flex justify-between items-start">
                  <div className="flex items-center gap-4">
                    <div className="bg-gray-900 px-3 py-1 rounded text-xs font-bold text-indigo-400 border border-gray-700">SCENE {idx + 1}</div>
                    <input
                       className="bg-transparent text-xl font-bold outline-none placeholder-gray-600 focus:text-white transition-colors"
                       value={scene.name}
                       onChange={(e) => updateScene(scene.id, { name: e.target.value })}
                       placeholder="Scene Name"
                    />
                  </div>
                  <button onClick={() => onUpdateScenes(scenes.filter(s => s.id !== scene.id))} className="text-gray-500 hover:text-red-500 transition-colors p-1">
                    <Trash2 size={18} />
                  </button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                  {/* Visuals & Goal */}
                  <div className="space-y-4">
                    <div className="w-full h-40 bg-gray-900 rounded-lg border border-gray-600 overflow-hidden relative group shadow-inner">
                       {scene.backgroundSrc ? (
                          <img src={scene.backgroundSrc} alt="bg" className="w-full h-full object-cover opacity-80" />
                       ) : (
                         <div className="w-full h-full flex items-center justify-center text-gray-500 gap-2">
                           <ImageIcon size={24} /> No Background
                         </div>
                       )}
                       <label className="absolute inset-0 flex items-center justify-center cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity bg-black/40">
                          <span className="bg-black/80 px-4 py-2 rounded hover:bg-black text-sm border border-gray-600">Change Background</span>
                          <input type="file" accept="image/*" className="hidden" onChange={(e) => handleBgUpload(scene.id, e)} />
