import React, { useState, useEffect, useRef } from 'react';
import { Scene, Character, ChatMessage, GameState, GameSaveData } from '../types';
import { generateGameTurn } from '../services/geminiService';
import { Button } from './ui/Button';
import { ArrowLeft, RefreshCw, Send, Save, Map } from 'lucide-react';

interface PlayerProps {
  scenes: Scene[];
  characters: Character[];
  initialState: any; // Using any loosely here because we are mixing save data types
  onExit: () => void; // Returns to Map
  onSave: (vnState: any) => Promise<boolean>;
}

export const Player: React.FC<PlayerProps> = ({ scenes, characters, initialState, onExit, onSave }) => {
  const [state, setState] = useState<GameState>({
    currentSceneIndex: initialState?.currentSceneIndex || 0,
    history: initialState?.history || [],
    isProcessing: false,
    gameOver: false,
  });
  const [userInput, setUserInput] = useState('');
  const [transitionMsg, setTransitionMsg] = useState<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const [isSaving, setIsSaving] = useState(false);

  const currentScene = scenes[state.currentSceneIndex];
  const activeCharacters = currentScene?.characters
    .map(sc => characters.find(c => c.id === sc.characterId))
    .filter((c): c is Character => !!c) || [];

  // Auto-scroll chat
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [state.history]);

  // Initial greeting from System/Narrator when scene starts (only if history is empty)
  useEffect(() => {
    if (!currentScene || state.history.length > 0) return;
    setState(prev => ({
      ...prev,
      history: [{
        sender: 'system',
        text: currentScene.description,
        timestamp: Date.now(),
      }]
    }));
    setTransitionMsg(null);
  }, [state.currentSceneIndex, currentScene]);

  const handleSendMessage = async () => {
    if (!userInput.trim() || state.isProcessing || !currentScene) return;

    const newMessage: ChatMessage = {
      sender: 'user',
      text: userInput,
      timestamp: Date.now(),
    };

    // Optimistic update
    setState(prev => ({
      ...prev,
      history: [...prev.history, newMessage],
      isProcessing: true,
    }));
    setUserInput('');

    try {
      const aiResponse = await generateGameTurn(
        newMessage.text,
        state.history, // send previous history
        currentScene,
        characters
      );

      const newMessages: ChatMessage[] = aiResponse.characterResponses.map(resp => ({
        sender: 'model',
        characterId: resp.characterId,
        text: resp.text,
        timestamp: Date.now(),
      }));

      setState(prev => ({
        ...prev,
        history: [...prev.history, ...newMessages],
        isProcessing: false,
      }));

      if (aiResponse.sceneGoalReached) {
        handleSceneSuccess(aiResponse.sceneTransitionReason);
      }

    } catch (error) {
      console.error("Turn error", error);
      setState(prev => ({ ...prev, isProcessing: false }));
    }
  };

  const handleSceneSuccess = (reason?: string) => {
    setTransitionMsg(reason || "Objective Completed!");

    // Instead of auto-advancing index, we notify user and then exit to map
    setTimeout(() => {
        onExit(); // Go back to RPG Map
    }, 4000);
  };

  const handleSaveGame = async () => {
    if (isSaving) return;
    setIsSaving(true);

    const vnState = {
       currentSceneIndex: state.currentSceneIndex,
       history: state.history,
       isProcessing: false,
       gameOver: false
    };

    const btn = document.getElementById('save-btn');
    if (btn) btn.innerHTML = '...';

    await onSave(vnState);

    if (btn) {
      btn.innerHTML = 'Saved!';
      setTimeout(() => btn.innerHTML = '', 2000); 
      // Reset button icon is tricky with innerHTML, better to let react handle it but for quick feedback:
      setTimeout(() => setIsSaving(false), 1500);
    } else {
        setIsSaving(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  if (!currentScene) {
    return <div className="flex items-center justify-center h-full">Scene Data Error. <button onClick={onExit}>Back</button></div>;
  }

  return (
    <div className="relative w-full h-full bg-black overflow-hidden">
      {/* Top Left Navigation - Back to Map */}
      <div className="absolute top-4 left-4 z-50">
        <button 
           onClick={onExit}
           className="flex items-center gap-2 bg-black/50 hover:bg-black/70 text-white px-4 py-2 rounded-full backdrop-blur-md border border-white/10 transition-all hover:scale-105 shadow-lg group"
        >
           <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" />
           <span className="font-semibold text-sm">Back to Map</span>
        </button>
      </div>

      {/* Background Layer */}
      <div className="absolute inset-0 z-0">
        {currentScene.backgroundSrc ? (
          <img src={currentScene.backgroundSrc} alt="bg" className="w-full h-full object-cover" />
        ) : (
          <div className="w-full h-full bg-gradient-to-b from-gray-800 to-gray-900" />
        )}
        <div className="absolute inset-0 bg-black/30" />
      </div>

      {/* Character Layer - Positioned above the chat box */}
      <div className="absolute bottom-[36vh] left-0 right-0 z-10 flex justify-center items-end px-10 h-[60vh] pointer-events-none">
        {activeCharacters.map((char, idx) => (
          <div 
             key={char.id} 
             className="relative transition-transform duration-500 transform"
             style={{ 
                zIndex: 10 + idx, 
                marginLeft: idx > 0 ? '-50px' : '0',
                filter: state.isProcessing ? 'brightness(0.7)' : 'brightness(1)' 
             }}
          >
            {char.imageSrc ? (
              <img 
                src={char.imageSrc} 
                alt={char.name} 
                className="max-h-[60vh] w-auto object-contain drop-shadow-2xl"
              />
            ) : (
               // Placeholder Shape
               <div className="w-64 h-96 rounded-t-full border-4 border-white/20 flex items-center justify-center text-white font-bold text-2xl shadow-2xl" style={{ backgroundColor: char.rpgColor || '#4b5563' }}>
                 {char.name[0]}
               </div>
            )}
            <div className="absolute bottom-4 left-0 right-0 text-center">
               <span className="bg-black/60 text-white px-2 py-1 rounded text-sm backdrop-blur-sm">{char.name}</span>
            </div>
          </div>
        ))}
      </div>

      {/* Transition Overlay */}
      {transitionMsg && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/90 animate-in fade-in duration-500">
           <div className="text-center space-y-4 p-8 max-w-2xl">
             <h2 className="text-3xl font-bold text-green-400">SCENARIO COMPLETE</h2>
             <p className="text-xl text-white">{transitionMsg}</p>
             <p className="text-sm text-gray-500 animate-pulse">Returning to Map...</p>
           </div>
        </div>
      )}

      {/* UI Layer - Chat Box */}
      <div className="absolute bottom-0 left-0 right-0 z-20 p-4 md:p-8 bg-gradient-to-t from-black via-black/90 to-transparent pt-24">
        <div className="max-w-4xl mx-auto bg-black/80 border border-gray-700 rounded-xl backdrop-blur-md shadow-2xl overflow-hidden flex flex-col h-[35vh]">

          {/* Chat History */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4">
            {state.history.map((msg, i) => {
              const char = characters.find(c => c.id === msg.characterId);
              const isUser = msg.sender === 'user';
              const isSystem = msg.sender === 'system';

              if (isSystem) return (
                <div key={i} className="text-center text-yellow-500 italic text-sm my-4 px-8">
                  {msg.text}
                </div>
              );

              return (
                <div key={i} className={`flex flex-col ${isUser ? 'items-end' : 'items-start'}`}>
                   <div className="text-xs text-gray-400 mb-1 px-1">
                     {isUser ? 'You' : (char?.name || 'Unknown')}
                   </div>
                   <div className={`px-4 py-2 rounded-lg max-w-[85%] leading-relaxed ${
                     isUser 
                       ? 'bg-indigo-600 text-white rounded-br-none' 
                       : 'bg-gray-800 text-gray-100 rounded-bl-none border border-gray-700'
                   }`}>
                     {msg.text}
                   </div>
                </div>
              );
            })}
            {state.isProcessing && (
              <div className="flex items-center gap-2 text-gray-500 text-sm px-4">
                <RefreshCw className="animate-spin" size={14} /> AI is thinking...
              </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-4 border-t border-gray-700 bg-gray-900/50 flex gap-3">
             <button 
               id="save-btn"
               onClick={handleSaveGame} 
               disabled={isSaving}
               className="bg-gray-700 hover:bg-gray-600 disabled:opacity-50 text-gray-300 p-3 rounded-lg transition-colors flex items-center justify-center min-w-[50px]"
               title="Save Current Progress"
             >
               {!isSaving && <Save size={20} />}
             </button>

             <input
               type="text"
               className="flex-1 bg-gray-800 border border-gray-600 rounded-lg px-4 py-3 text-white focus:border-indigo-500 outline-none transition-colors"
               placeholder="What do you say/do?"
               value={userInput}
               onChange={(e) => setUserInput(e.target.value)}
               onKeyDown={handleKeyDown}
               autoFocus
               disabled={state.isProcessing}
             />
             <button 
                onClick={handleSendMessage}
                disabled={!userInput.trim() || state.isProcessing}
                className="bg-indigo-600 hover:bg-indigo-500 disabled:bg-gray-700 disabled:cursor-not-allowed text-white p-3 rounded-lg transition-colors"
             >
               <Send size={20} />
             </button>
             {/* Small backup map button kept in layout but duplicate of top-left */}
             <button onClick={onExit} className="border border-indigo-900/50 text-indigo-400 hover:bg-indigo-900/20 p-3 rounded-lg transition-colors flex gap-2 items-center" title="Return to Map">
               <Map size={20} />
             </button>
          </div>

        </div>

        {/* Current Goal Display */}
        <div className="absolute top-4 right-4 md:right-12 bg-black/60 backdrop-blur text-xs text-green-400 px-3 py-1 rounded border border-green-900">
          Objective: {currentScene.goal}
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Character, RPGState, WorldMap } from '../types';
import { Save, LogOut, ZoomIn, ZoomOut, Maximize } from 'lucide-react';

interface RPGWorldProps {
  characters: Character[];
  mapConfig: WorldMap; // The CURRENT map
  maps: WorldMap[]; // For referencing target map names
  onInteraction: (type: 'scene'|'transition', id: string) => void;
  initialState?: RPGState;
  onSave: (state: RPGState) => void;
  onExit: () => void;
}

export const RPGWorld: React.FC<RPGWorldProps> = ({ 
  characters, 
  mapConfig,
  maps,
  onInteraction, 
  initialState, 
  onSave,
  onExit
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const [hoveredSpotId, setHoveredSpotId] = useState<string | null>(null);
  const [canvasDims, setCanvasDims] = useState({ width: 1000, height: 750 });

  // Camera / Viewport State
  const [zoom, setZoom] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });

  // Cache for loaded sprite images
  const spritesRef = useRef<Record<string, HTMLImageElement>>({});
  const [spritesLoaded, setSpritesLoaded] = useState(false);

  // Preload Sprites
  useEffect(() => {
    let active = true;
    const loadSprites = async () => {
        const promises = characters.map(c => {
            if (!c.mapSpriteSrc) return Promise.resolve();
            return new Promise<void>((resolve) => {
                const img = new Image();
                img.src = c.mapSpriteSrc!;
                img.onload = () => {
                    if(active) spritesRef.current[c.id] = img;
                    resolve();
                };
                img.onerror = () => resolve(); 
            });
        });

        await Promise.all(promises);
        if (active) setSpritesLoaded(true);
    };
    loadSprites();
    return () => { active = false; };
  }, [characters]);

  // Adjust canvas dimensions to match background image
  useEffect(() => {
    if (mapConfig.backgroundSrc) {
        const img = new Image();
        img.src = mapConfig.backgroundSrc;
        img.onload = () => {
            setCanvasDims(prev => {
                if (prev.width !== img.naturalWidth || prev.height !== img.naturalHeight) {
                    // Reset view when map changes
                    setZoom(1); 
                    setOffset({ x: 0, y: 0 });
                    return { width: img.naturalWidth, height: img.naturalHeight };
                }
                return prev;
            });
        };
    } else {
        setCanvasDims({ width: 1000, height: 750 });
    }
  }, [mapConfig.backgroundSrc]);

  // --- Coordinate Systems ---

  const getRawMousePos = (e: React.MouseEvent | React.WheelEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    return {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top
    };
  };

  const getMousePosInWorldPercent = (rawX: number, rawY: number) => {
     const worldX = (rawX - offset.x) / zoom;
     const worldY = (rawY - offset.y) / zoom;
     return {
       x: (worldX / canvasDims.width) * 100,
       y: (worldY / canvasDims.height) * 100
     };
  };

  const checkHit = (xPct: number, yPct: number) => {
    // 4% radius in World Space for easier clicking
    const THRESHOLD = 4; 

    return mapConfig.spots.find(spot => {
       const dx = spot.x - xPct;
       const dy = spot.y - yPct;
       return Math.sqrt(dx*dx + dy*dy) < THRESHOLD;
    });
  };

  // --- Interaction Handlers ---

  const handleWheel = (e: React.WheelEvent<HTMLCanvasElement>) => {
    e.preventDefault();
    const zoomSensitivity = 0.001;
    const delta = -e.deltaY * zoomSensitivity;
    const newZoom = Math.min(Math.max(zoom + delta, 0.1), 5); 

    if (newZoom === zoom) return;

    const mouse = getRawMousePos(e);
    const worldX = (mouse.x - offset.x) / zoom;
    const worldY = (mouse.y - offset.y) / zoom;

    const newOffsetX = mouse.x - worldX * newZoom;
    const newOffsetY = mouse.y - worldY * newZoom;

    setZoom(newZoom);
    setOffset({ x: newOffsetX, y: newOffsetY });
  };

  const handleMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (e.button === 0) {
      setIsDragging(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (isDragging) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return; 
    }

    const raw = getRawMousePos(e);
    const worldPct = getMousePosInWorldPercent(raw.x, raw.y);
    const hit = checkHit(worldPct.x, worldPct.y);

    if (hit) {
      if (hoveredSpotId !== hit.id) setHoveredSpotId(hit.id);
    } else {
      if (hoveredSpotId !== null) setHoveredSpotId(null);
    }
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const handleClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (isDragging) return;

    const raw = getRawMousePos(e);
    const worldPct = getMousePosInWorldPercent(raw.x, raw.y);
    const hit = checkHit(worldPct.x, worldPct.y);
    if (hit) {
      if (hit.type === 'scene' && hit.characterId) {
          onInteraction('scene', hit.characterId);
      } else if (hit.type === 'transition' && hit.targetMapId) {
          onInteraction('transition', hit.targetMapId);
      }
    }
  };

  // --- Rendering ---

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.save();

    ctx.fillStyle = '#0f172a'; 
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.translate(offset.x, offset.y);
    ctx.scale(zoom, zoom);

    // Draw World
    const bgImage = new Image();
    if (mapConfig.backgroundSrc) {
       bgImage.src = mapConfig.backgroundSrc;
    }

    const drawScene = () => {
        // Background
        if (mapConfig.backgroundSrc && bgImage.complete) {
            ctx.drawImage(bgImage, 0, 0, canvasDims.width, canvasDims.height);
        } else {
            // Fallback Grid
            ctx.fillStyle = '#1e293b';
            ctx.fillRect(0, 0, canvasDims.width, canvasDims.height);
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 2;
            ctx.strokeRect(0, 0, canvasDims.width, canvasDims.height);
        }

        const toPx = (pct: number, dim: number) => (pct / 100) * dim;

        // Render Spots
        mapConfig.spots.forEach(spot => {
          const cx = toPx(spot.x, canvasDims.width);
          const cy = toPx(spot.y, canvasDims.height);
          const isHovered = hoveredSpotId === spot.id;

          if (spot.type === 'scene' && spot.characterId) {
              const char = characters.find(c => c.id === spot.characterId);
              if (!char) return;

              const spriteImg = spritesRef.current[char.id];
              let renderedHeight = 0;

              if (spriteImg) {
                  const ratio = spriteImg.naturalWidth / spriteImg.naturalHeight || 1;
                  const baseScale = Math.max(canvasDims.width / 1000, 0.5); 
                  const targetHeight = (isHovered ? 80 : 70) * baseScale;

                  const drawHeight = targetHeight;
                  const drawWidth = targetHeight * ratio;
                  renderedHeight = drawHeight;

                  ctx.save();
                  ctx.shadowColor = isHovered ? 'white' : 'black';
                  ctx.shadowBlur = isHovered ? 15 : 5;

                  ctx.drawImage(spriteImg, cx - drawWidth/2, cy - drawHeight/2, drawWidth, drawHeight);
                  ctx.restore();
              } else {
                  // Fallback Circle
                  renderedHeight = 24;
                  ctx.fillStyle = char.rpgColor;
                  ctx.beginPath();
                  ctx.arc(cx, cy, isHovered ? 12 : 10, 0, Math.PI * 2);
                  ctx.fill();
                  ctx.lineWidth = 2;
                  ctx.strokeStyle = 'white';
                  ctx.stroke();
              }

              // Name Tag (Scene Spots)
              if (isHovered) {
                ctx.save();
                const textScale = Math.max(1 / zoom, 0.5); 
                ctx.translate(cx, cy - (renderedHeight / 2) - 14 * textScale);
                ctx.scale(textScale, textScale);

                ctx.fillStyle = 'rgba(0,0,0,0.8)';
                ctx.font = 'bold 16px sans-serif';
                const textW = ctx.measureText(char.name).width;

                ctx.fillRect(-textW/2 - 8, -20, textW + 16, 28);
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.fillText(char.name, 0, 0);
                ctx.restore();
              }

          } else if (spot.type === 'transition') {
              // Visible Waypoint Marker
              const radius = 16;
              const pulseColor = 'rgba(52, 211, 153, 0.6)';

              // Pulse Effect (Visible on hover or always subtle)
              if (isHovered) {
                  const time = Date.now() / 300;
                  const pulse = Math.sin(time) * 4 + radius + 4;
                  ctx.beginPath();
                  ctx.arc(cx, cy, pulse, 0, Math.PI * 2);
                  ctx.strokeStyle = pulseColor;
                  ctx.lineWidth = 2;
                  ctx.stroke();
              }

              // Main Marker Body (Emerald Green)
              ctx.beginPath();
              ctx.arc(cx, cy, radius, 0, Math.PI * 2);
              ctx.fillStyle = 'rgba(16, 185, 129, 0.9)'; // Emerald-500
              ctx.fill();

              // Border
              ctx.strokeStyle = '#6ee7b7'; // Emerald-300
              ctx.lineWidth = 2;
              ctx.stroke();

              // Inner Dot
              ctx.beginPath();
              ctx.arc(cx, cy, 6, 0, Math.PI * 2);
              ctx.fillStyle = '#ffffff';
              ctx.fill();

              // Label (Only on Hover)
              if (isHovered) {
                  ctx.save();

                  // Label
                  const targetMapName = maps.find(m => m.id === spot.targetMapId)?.name || 'Unknown Area';
                  const text = `Travel to ${targetMapName}`;

                  const textScale = Math.max(1 / zoom, 0.5); 
                  ctx.translate(cx, cy - 30 * textScale);
                  ctx.scale(textScale, textScale);

                  ctx.fillStyle = 'rgba(0,0,0,0.8)';
                  ctx.font = 'bold 14px sans-serif';
                  const textW = ctx.measureText(text).width;

                  ctx.fillRect(-textW/2 - 8, -18, textW + 16, 26);
                  ctx.fillStyle = '#6ee7b7'; // Emerald color text
                  ctx.textAlign = 'center';
                  ctx.fillText(text, 0, 0);

                  ctx.restore();
              }
          }
        });
    }

    if (bgImage.complete || !mapConfig.backgroundSrc) {
        drawScene();
    } else {
        bgImage.onload = drawScene;
    }

    ctx.restore();

  }, [mapConfig, characters, hoveredSpotId, spritesLoaded, canvasDims, zoom, offset]);

  const handleManualSave = () => {
    onSave({ 
        currentMapId: mapConfig.id,
        completedSceneIds: initialState?.completedSceneIds || [] 
    });
  };

  const handleZoomIn = () => setZoom(z => Math.min(z + 0.2, 5));
  const handleZoomOut = () => setZoom(z => Math.max(z - 0.2, 0.1));
  const handleResetView = () => {
      setZoom(1);
      setOffset({ x: 0, y: 0 });
  };

  return (
    <div className="relative w-full h-full bg-gray-950 flex flex-col overflow-hidden">
      {/* HUD */}
      <div className="absolute top-4 left-4 z-10 pointer-events-none">
          <div className="bg-gray-900/80 p-3 rounded-xl border border-gray-700 backdrop-blur-sm shadow-xl pointer-events-auto">
            <h1 className="text-xl font-bold text-indigo-400">{mapConfig.name.toUpperCase()}</h1>
            <p className="text-xs text-gray-400 mt-1">Drag to Pan • Wheel to Zoom</p>
          </div>
      </div>

      {/* Main Canvas Container */}
      <div 
        ref={containerRef}
        className="flex-1 w-full h-full relative overflow-hidden bg-[#0f172a] cursor-grab active:cursor-grabbing"
      >
        <canvas 
          ref={canvasRef}
          width={canvasRef.current?.parentElement?.clientWidth || 1000} 
          height={canvasRef.current?.parentElement?.clientHeight || 750}
          className="block w-full h-full"
          onWheel={handleWheel}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
          onClick={handleClick}
          style={{ touchAction: 'none', cursor: hoveredSpotId ? 'pointer' : 'default' }}
        />
      </div>

      {/* Bottom Controls */}
      <div className="absolute bottom-8 right-8 flex gap-3 z-10">
         <div className="bg-gray-800 rounded-full border border-gray-600 flex overflow-hidden shadow-lg mr-4">
            <button onClick={handleZoomOut} className="p-3 hover:bg-gray-700 text-white transition border-r border-gray-600">
                <ZoomOut size={20} />
            </button>
            <button onClick={handleResetView} className="p-3 hover:bg-gray-700 text-white transition border-r border-gray-600" title="Reset View">
                <Maximize size={20} />
            </button>
            <button onClick={handleZoomIn} className="p-3 hover:bg-gray-700 text-white transition">
                <ZoomIn size={20} />
            </button>
         </div>

         <button onClick={handleManualSave} className="bg-indigo-600 p-3 rounded-full hover:bg-indigo-500 text-white shadow-lg transition transform hover:scale-105" title="Save Game">
           <Save size={24} />
         </button>
         <button onClick={onExit} className="bg-gray-800 p-3 rounded-full hover:bg-red-900/80 text-white border border-gray-600 shadow-lg transition transform hover:scale-105" title="Exit to Editor">
           <LogOut size={24} />
         </button>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Character, RPGState, WorldMap } from '../types';
