        />
      </div>

      {/* Bottom Controls */}
      <div className="absolute bottom-8 right-8 flex gap-3 z-10">
         <div className="bg-gray-800 rounded-full border border-gray-600 flex overflow-hidden shadow-lg mr-4">
            <button onClick={handleZoomOut} className="p-3 hover:bg-gray-700 text-white transition border-r border-gray-600">
                <ZoomOut size={20} />
            </button>
            <button onClick={handleResetView} className="p-3 hover:bg-gray-700 text-white transition border-r border-gray-600" title="Reset View">
                <Maximize size={20} />
            </button>
            <button onClick={handleZoomIn} className="p-3 hover:bg-gray-700 text-white transition">
                <ZoomIn size={20} />
            </button>
         </div>

         <button onClick={handleManualSave} className="bg-indigo-600 p-3 rounded-full hover:bg-indigo-500 text-white shadow-lg transition transform hover:scale-105" title="Save Game">
           <Save size={24} />
         </button>
         <button onClick={onExit} className="bg-gray-800 p-3 rounded-full hover:bg-red-900/80 text-white border border-gray-600 shadow-lg transition transform hover:scale-105" title="Exit to Editor">
           <LogOut size={24} />
         </button>
      </div>
    </div>
  );
};

export interface Character {
  id: string;
  name: string;
  defaultDescription: string;
  imageSrc: string | null; // Portrait for VN (Large)
  mapSpriteSrc: string | null; // Sprite for Map (Small/Icon)
  rpgColor: string; // Fallback Hex color
}

export interface SceneCharacterConfig {
  characterId: string;
  roleInScene: string; // Specific behavior/goal for this scene
}

export interface UnlockReward {
  type: 'scene' | 'transition';
  targetId: string; // Scene ID or Target Map ID
}

export interface Scene {
  id: string;
  name: string;
  backgroundSrc: string | null; // Local object URL
  description: string; // The scenario setup
  goal: string; // The win condition to move to next scene
  characters: SceneCharacterConfig[];
  unlocks?: UnlockReward[]; // New: List of things unlocked when this scene is won
}

export interface MapSpot {
  id: string;
  x: number; // Percentage 0-100
  y: number; // Percentage 0-100
  type: 'scene' | 'transition';

  // If type === 'scene'
  characterId?: string;

  // If type === 'transition'
  targetMapId?: string;
}

export interface WorldMap {
  id: string;
  name: string;
  backgroundSrc: string | null;
  spots: MapSpot[];
}

export interface ChatMessage {
  sender: 'user' | 'model' | 'system';
  characterId?: string; // If model, which character?
  text: string;
  timestamp: number;
}

export interface GameState {
  currentSceneIndex: number; // Used inside VN Mode
  history: ChatMessage[];
  isProcessing: boolean;
  gameOver: boolean;
}

export interface AIResponse {
  characterResponses: {
    characterId: string;
    text: string;
  }[];
  sceneGoalReached: boolean;
  sceneTransitionReason?: string;
}

export interface RPGState {
  currentMapId: string;
  completedSceneIds: string[];
  unlockedIds: string[]; // New: IDs of Scenes or Maps that have been unlocked
}

export interface GameSaveData {
  rpgState: RPGState;
  vnState: GameState | null; // Null if saved while on map
  timestamp: number;
}

import React, { useState, useEffect } from 'react';
import { Editor } from './components/Editor';
import { Player } from './components/Player';
import { RPGWorld } from './components/RPGWorld';
import { Character, Scene, GameSaveData, RPGState, WorldMap } from './types';
import { getItem, setItem } from './utils/db';

// Default Data for quick start
const DEFAULT_CHARS: Character[] = [
  { 
    id: '1', 
    name: 'Aiko', 
    defaultDescription: 'A cheerful and curious android girl who loves learning about humans.', 
    imageSrc: null,
    mapSpriteSrc: null,
    rpgColor: '#f472b6' // Pink
  },
  { 
    id: '2', 
    name: 'Kael', 
    defaultDescription: 'A grumpy but skilled mechanic who fixes robots.', 
    imageSrc: null,
    mapSpriteSrc: null,
    rpgColor: '#60a5fa' // Blue
  }
];

const DEFAULT_SCENES: Scene[] = [
  {
    id: 's1',
    name: 'The Workshop',
    backgroundSrc: null,
    description: 'A cluttered workshop filled with robot parts. Kael is working on a workbench. Aiko is watching closely.',
    goal: 'Convince Kael to fix your broken radio.',
    characters: [
      { characterId: '1', roleInScene: 'Curious onlooker, wants to help but is clumsy.' },
      { characterId: '2', roleInScene: 'Busy, easily annoyed, does not want to be disturbed.' }
    ],
    unlocks: []
  }
];

const DEFAULT_MAPS: WorldMap[] = [
  {
    id: 'map1',
    name: 'Main City',
    backgroundSrc: null,
    spots: [
      { id: 'spot1', type: 'scene', characterId: '1', x: 40, y: 50 },
      { id: 'spot2', type: 'scene', characterId: '2', x: 60, y: 30 }
    ]
  }
];

const PROJECT_STORAGE_KEY = 'vn_creator_project';
const GAME_SAVE_KEY = 'vn_creator_savegame';

const App: React.FC = () => {
  const [mode, setMode] = useState<'edit' | 'rpg' | 'vn'>('edit');

  // Data State
  const [characters, setCharacters] = useState<Character[]>(DEFAULT_CHARS);
  const [scenes, setScenes] = useState<Scene[]>(DEFAULT_SCENES);
  const [maps, setMaps] = useState<WorldMap[]>(DEFAULT_MAPS);

  // Game Play State
  const [rpgState, setRpgState] = useState<RPGState>({ 
    currentMapId: 'map1', 
    completedSceneIds: [],
    unlockedIds: [] 
  });

  const [activeSceneIndex, setActiveSceneIndex] = useState<number>(-1);
  const [vnHistory, setVnHistory] = useState<any[]>([]); 

  const [hasSaveGame, setHasSaveGame] = useState(false);

  // Check for save game on mount and migrate from LocalStorage if needed
  useEffect(() => {
    const initLoad = async () => {
        // 1. Check for Save Game
        const savedGame = await getItem<GameSaveData>(GAME_SAVE_KEY);
        if (savedGame) {
            setHasSaveGame(true);
        } else {
            // Check legacy local storage for save game
            const lsSave = localStorage.getItem(GAME_SAVE_KEY);
            if (lsSave) {
                setHasSaveGame(true);
            }
        }

        // 2. Load Project Data (Try IndexedDB first)
        let data: any = await getItem(PROJECT_STORAGE_KEY);

        // 3. Fallback/Migrate from LocalStorage if IDB is empty
        if (!data) {
            const lsProject = localStorage.getItem(PROJECT_STORAGE_KEY);
            if (lsProject) {
                try {
                    data = JSON.parse(lsProject);
                    // Migrate to IDB to fix quota issues in future
                    await setItem(PROJECT_STORAGE_KEY, data);
                    // Clear LS to free up immediate space
                    localStorage.removeItem(PROJECT_STORAGE_KEY);
                    console.log("Migrated project from LocalStorage to IndexedDB");
                } catch (e) {
                    console.error("Failed to parse legacy local storage", e);
                }
            }
        }

        // Apply Data
        if (data) {
            if (data.characters) setCharacters(data.characters);
            if (data.scenes) setScenes(data.scenes);

            // Migration check: if old data had 'mapConfig' (single object), convert to array
            if (data.mapConfig && !data.maps) {
                setMaps([{ ...data.mapConfig, id: 'map1', name: 'Default Map' }]);
            } else if (data.maps) {
                setMaps(data.maps);
            }
        }
    };
    initLoad();
  }, []);

  // 1. Quick Save to Browser Storage (IndexedDB)
  const handleQuickSave = async () => {
    const data = { characters, scenes, maps };
    await setItem(PROJECT_STORAGE_KEY, data);
    return true;
  };

  // 2. Export to File (Download)
  const handleExportProject = () => {
    const data = { characters, scenes, maps };
    const jsonString = JSON.stringify(data, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const href = URL.createObjectURL(blob);

    const link = document.createElement('a');
    link.href = href;
    link.download = `vn-project-${new Date().toISOString().slice(0,10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(href);
  };

  // 3. Import from File (Upload)
  const handleImportProject = (file: File) => {
    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const content = e.target?.result as string;
        const data = JSON.parse(content);

        if (data.characters) setCharacters(data.characters);
        if (data.scenes) setScenes(data.scenes);
        if (data.maps) setMaps(data.maps);
        else if (data.mapConfig) setMaps([{ ...data.mapConfig, id: 'map1', name: 'Default Map' }]);

        // Save to DB immediately
        await setItem(PROJECT_STORAGE_KEY, data);
        alert("Project loaded successfully!");
      } catch (error) {
        console.error("Import failed", error);
        alert("Failed to load project file. Invalid JSON.");
      }
    };
    reader.readAsText(file);
  };

  const handleStartNewGame = () => {
    setRpgState({ currentMapId: maps[0].id, completedSceneIds: [], unlockedIds: [] });
    setVnHistory([]);
    setActiveSceneIndex(-1);
    setMode('rpg');
  };

  const handleContinueGame = async () => {
    // Try IDB first
    let savedGame = await getItem<GameSaveData>(GAME_SAVE_KEY);

    // Fallback to LS
    if (!savedGame) {
        const lsSave = localStorage.getItem(GAME_SAVE_KEY);
        if (lsSave) {
            try {
                savedGame = JSON.parse(lsSave);
            } catch(e) {}
        }
    }

    if (savedGame) {
      try {
        // Ensure map ID exists, fallback to first if deleted
        const safeMapId = maps.find(m => m.id === savedGame!.rpgState.currentMapId) ? savedGame!.rpgState.currentMapId : maps[0].id;

        setRpgState({ 
            ...savedGame.rpgState, 
            currentMapId: safeMapId,
            unlockedIds: savedGame.rpgState.unlockedIds || [] // Default for migration
        });

        if (savedGame.vnState) {
          setActiveSceneIndex(savedGame.vnState.currentSceneIndex);
          setVnHistory(savedGame.vnState.history);
          setMode('vn');
        } else {
          setMode('rpg');
        }
      } catch (e) {
        console.error("Corrupt save file");
        handleStartNewGame();
      }
    }
  };

  const handleSaveGameInternal = async (updatedRpgState: RPGState, vnState: any | null) => {
      const saveData: GameSaveData = {
        rpgState: updatedRpgState,
        vnState: vnState,
        timestamp: Date.now()
      };
      await setItem(GAME_SAVE_KEY, saveData);
      setHasSaveGame(true);
      return true;
  };

  const handleInteraction = (type: 'scene'|'transition', id: string) => {
      if (type === 'transition') {
          // Change Map
          if (maps.find(m => m.id === id)) {
              setRpgState(prev => ({ ...prev, currentMapId: id }));
          }
      } else {
          // Trigger Scene
          const charId = id;
          const availableScenes = scenes.filter(s => s.characters.some(c => c.characterId === charId));
          // Logic: Find first AVAILABLE scene that is NOT completed
          // A scene is available if:
          // 1. It is NOT unlocked by another scene (default available)
          // 2. OR it IS in unlockedIds

          const playableScene = availableScenes.find(s => {
              const isCompleted = rpgState.completedSceneIds.includes(s.id);
              if (isCompleted) return false;

              // Check if it's locked by dependency
              const isLockedByOthers = scenes.some(other => other.unlocks?.some(u => u.type === 'scene' && u.targetId === s.id));
              const isUnlocked = rpgState.unlockedIds.includes(s.id);

              return !isLockedByOthers || isUnlocked;
          });

          if (playableScene) {
            const realIndex = scenes.findIndex(s => s.id === playableScene.id);
            setActiveSceneIndex(realIndex);
            setVnHistory([]); 
            setMode('vn');
          } else {
            alert("No available scenarios for this character right now.");
          }
      }
  };

  const handleSceneFinish = async (completed: boolean) => {
      if (completed) {
          const finishedScene = scenes[activeSceneIndex];
          const newCompletedIds = [...rpgState.completedSceneIds, finishedScene.id];

          // Process Unlocks
          const newUnlockedIds = [...rpgState.unlockedIds];
          if (finishedScene.unlocks) {
              finishedScene.unlocks.forEach(reward => {
                  if (!newUnlockedIds.includes(reward.targetId)) {
                      newUnlockedIds.push(reward.targetId);
                  }
              });
          }

          const newState = { 
              ...rpgState, 
              completedSceneIds: newCompletedIds,
              unlockedIds: newUnlockedIds
          };

          setRpgState(newState);
          await handleSaveGameInternal(newState, null);
      }
      setMode('rpg');
  };

  const activeMap = maps.find(m => m.id === rpgState.currentMapId) || maps[0];

  return (
    <div className="min-h-screen bg-gray-900 text-gray-100 font-sans selection:bg-indigo-500 selection:text-white">
      {mode === 'edit' && (
        <Editor 
          characters={characters}
          scenes={scenes}
          maps={maps}
          onUpdateCharacters={setCharacters}
          onUpdateScenes={setScenes}
          onUpdateMaps={setMaps}
          onPlay={handleStartNewGame}
          onQuickSave={handleQuickSave}
          onExportProject={handleExportProject}
          onImportProject={handleImportProject}
          hasSaveGame={hasSaveGame}
          onContinueGame={handleContinueGame}
        />
      )}

      {mode === 'rpg' && (
        <RPGWorld 
          characters={characters}
          mapConfig={activeMap}
          maps={maps}
          scenes={scenes}
          initialState={rpgState}
          onInteraction={handleInteraction}
          onSave={async (updatedRpgState) => {
             setRpgState(updatedRpgState);
             await handleSaveGameInternal(updatedRpgState, null);
             alert("Game Saved!");
          }}
          onExit={() => setMode('edit')}
        />
      )}

      {mode === 'vn' && activeSceneIndex >= 0 && (
        <Player 
          scenes={scenes}
          characters={characters}
          initialState={{
            currentSceneIndex: activeSceneIndex,
            history: vnHistory,
            timestamp: 0,
            rpgState: rpgState, 
            vnState: null
          }}
          onExit={handleSceneFinish}
          onSave={async (vnState) => {
             await handleSaveGameInternal(rpgState, vnState);
             return true;
          }}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Scene, Character, ChatMessage, GameState, GameSaveData } from '../types';
import { generateGameTurn } from '../services/geminiService';
import { Button } from './ui/Button';
import { ArrowLeft, RefreshCw, Send, Save, Map } from 'lucide-react';

interface PlayerProps {
  scenes: Scene[];
  characters: Character[];
  initialState: any; // Using any loosely here because we are mixing save data types
  onExit: (success: boolean) => void; // Returns to Map, with success flag
  onSave: (vnState: any) => Promise<boolean>;
}

export const Player: React.FC<PlayerProps> = ({ scenes, characters, initialState, onExit, onSave }) => {
  const [state, setState] = useState<GameState>({
    currentSceneIndex: initialState?.currentSceneIndex || 0,
    history: initialState?.history || [],
    isProcessing: false,
    gameOver: false,
  });
  const [userInput, setUserInput] = useState('');
  const [transitionMsg, setTransitionMsg] = useState<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const [isSaving, setIsSaving] = useState(false);

  const currentScene = scenes[state.currentSceneIndex];
  const activeCharacters = currentScene?.characters
    .map(sc => characters.find(c => c.id === sc.characterId))
    .filter((c): c is Character => !!c) || [];

  // Auto-scroll chat
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [state.history]);

  // Initial greeting from System/Narrator when scene starts (only if history is empty)
  useEffect(() => {
    if (!currentScene || state.history.length > 0) return;
    setState(prev => ({
      ...prev,
      history: [{
        sender: 'system',
        text: currentScene.description,
        timestamp: Date.now(),
      }]
    }));
    setTransitionMsg(null);
  }, [state.currentSceneIndex, currentScene]);

  const handleSendMessage = async () => {
    if (!userInput.trim() || state.isProcessing || !currentScene) return;

    const newMessage: ChatMessage = {
      sender: 'user',
      text: userInput,
      timestamp: Date.now(),
    };

    // Optimistic update
    setState(prev => ({
      ...prev,
      history: [...prev.history, newMessage],
      isProcessing: true,
    }));
    setUserInput('');

    try {
      const aiResponse = await generateGameTurn(
        newMessage.text,
        state.history, // send previous history
        currentScene,
        characters
      );

      const newMessages: ChatMessage[] = aiResponse.characterResponses.map(resp => ({
        sender: 'model',
        characterId: resp.characterId,
        text: resp.text,
        timestamp: Date.now(),
      }));

      setState(prev => ({
        ...prev,
        history: [...prev.history, ...newMessages],
        isProcessing: false,
      }));

      if (aiResponse.sceneGoalReached) {
        handleSceneSuccess(aiResponse.sceneTransitionReason);
      }

    } catch (error) {
      console.error("Turn error", error);
      setState(prev => ({ ...prev, isProcessing: false }));
    }
  };

  const handleSceneSuccess = (reason?: string) => {
    setTransitionMsg(reason || "Objective Completed!");

    // Instead of auto-advancing index, we notify user and then exit to map
    setTimeout(() => {
        onExit(true); // Go back to RPG Map, SIGNAL SUCCESS
    }, 4000);
  };

  const handleSaveGame = async () => {
    if (isSaving) return;
    setIsSaving(true);

    const vnState = {
       currentSceneIndex: state.currentSceneIndex,
       history: state.history,
       isProcessing: false,
       gameOver: false
    };

    const btn = document.getElementById('save-btn');
    if (btn) btn.innerHTML = '...';

    await onSave(vnState);

    if (btn) {
      btn.innerHTML = 'Saved!';
      setTimeout(() => btn.innerHTML = '', 2000); 
      // Reset button icon is tricky with innerHTML, better to let react handle it but for quick feedback:
      setTimeout(() => setIsSaving(false), 1500);
    } else {
        setIsSaving(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  if (!currentScene) {
    return <div className="flex items-center justify-center h-full">Scene Data Error. <button onClick={() => onExit(false)}>Back</button></div>;
  }

  return (
    <div className="relative w-full h-full bg-black overflow-hidden">
      {/* Top Left Navigation - Back to Map */}
      <div className="absolute top-4 left-4 z-50">
        <button 
           onClick={() => onExit(false)}
           className="flex items-center gap-2 bg-black/50 hover:bg-black/70 text-white px-4 py-2 rounded-full backdrop-blur-md border border-white/10 transition-all hover:scale-105 shadow-lg group"
        >
           <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" />
           <span className="font-semibold text-sm">Back to Map</span>
        </button>
      </div>

      {/* Background Layer */}
      <div className="absolute inset-0 z-0">
        {currentScene.backgroundSrc ? (
          <img src={currentScene.backgroundSrc} alt="bg" className="w-full h-full object-cover" />
        ) : (
          <div className="w-full h-full bg-gradient-to-b from-gray-800 to-gray-900" />
        )}
        <div className="absolute inset-0 bg-black/30" />
      </div>

      {/* Character Layer - Positioned above the chat box */}
      <div className="absolute bottom-[36vh] left-0 right-0 z-10 flex justify-center items-end px-10 h-[60vh] pointer-events-none">
        {activeCharacters.map((char, idx) => (
          <div 
             key={char.id} 
             className="relative transition-transform duration-500 transform"
             style={{ 
                zIndex: 10 + idx, 
                marginLeft: idx > 0 ? '-50px' : '0',
                filter: state.isProcessing ? 'brightness(0.7)' : 'brightness(1)' 
             }}
          >
            {char.imageSrc ? (
              <img 
                src={char.imageSrc} 
                alt={char.name} 
                className="max-h-[60vh] w-auto object-contain drop-shadow-2xl"
              />
            ) : (
               // Placeholder Shape
               <div className="w-64 h-96 rounded-t-full border-4 border-white/20 flex items-center justify-center text-white font-bold text-2xl shadow-2xl" style={{ backgroundColor: char.rpgColor || '#4b5563' }}>
                 {char.name[0]}
               </div>
            )}
            <div className="absolute bottom-4 left-0 right-0 text-center">
               <span className="bg-black/60 text-white px-2 py-1 rounded text-sm backdrop-blur-sm">{char.name}</span>
            </div>
          </div>
        ))}
      </div>

      {/* Transition Overlay */}
      {transitionMsg && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/90 animate-in fade-in duration-500">
           <div className="text-center space-y-4 p-8 max-w-2xl">
             <h2 className="text-3xl font-bold text-green-400">SCENARIO COMPLETE</h2>
             <p className="text-xl text-white">{transitionMsg}</p>
             <p className="text-sm text-gray-500 animate-pulse">Returning to Map...</p>
           </div>
        </div>
      )}

      {/* UI Layer - Chat Box */}
      <div className="absolute bottom-0 left-0 right-0 z-20 p-4 md:p-8 bg-gradient-to-t from-black via-black/90 to-transparent pt-24">
        <div className="max-w-4xl mx-auto bg-black/80 border border-gray-700 rounded-xl backdrop-blur-md shadow-2xl overflow-hidden flex flex-col h-[35vh]">

          {/* Chat History */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4">
            {state.history.map((msg, i) => {
              const char = characters.find(c => c.id === msg.characterId);
              const isUser = msg.sender === 'user';
              const isSystem = msg.sender === 'system';

              if (isSystem) return (
                <div key={i} className="text-center text-yellow-500 italic text-sm my-4 px-8">
                  {msg.text}
                </div>
              );

              return (
                <div key={i} className={`flex flex-col ${isUser ? 'items-end' : 'items-start'}`}>
                   <div className="text-xs text-gray-400 mb-1 px-1">
                     {isUser ? 'You' : (char?.name || 'Unknown')}
                   </div>
                   <div className={`px-4 py-2 rounded-lg max-w-[85%] leading-relaxed ${
                     isUser 
                       ? 'bg-indigo-600 text-white rounded-br-none' 
                       : 'bg-gray-800 text-gray-100 rounded-bl-none border border-gray-700'
                   }`}>
                     {msg.text}
                   </div>
                </div>
              );
            })}
            {state.isProcessing && (
              <div className="flex items-center gap-2 text-gray-500 text-sm px-4">
                <RefreshCw className="animate-spin" size={14} /> AI is thinking...
              </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-4 border-t border-gray-700 bg-gray-900/50 flex gap-3">
             <button 
               id="save-btn"
               onClick={handleSaveGame} 
               disabled={isSaving}
               className="bg-gray-700 hover:bg-gray-600 disabled:opacity-50 text-gray-300 p-3 rounded-lg transition-colors flex items-center justify-center min-w-[50px]"
               title="Save Current Progress"
             >
               {!isSaving && <Save size={20} />}
             </button>

             <input
               type="text"
               className="flex-1 bg-gray-800 border border-gray-600 rounded-lg px-4 py-3 text-white focus:border-indigo-500 outline-none transition-colors"
               placeholder="What do you say/do?"
               value={userInput}
               onChange={(e) => setUserInput(e.target.value)}
               onKeyDown={handleKeyDown}
               autoFocus
               disabled={state.isProcessing}
             />
             <button 
                onClick={handleSendMessage}
                disabled={!userInput.trim() || state.isProcessing}
                className="bg-indigo-600 hover:bg-indigo-500 disabled:bg-gray-700 disabled:cursor-not-allowed text-white p-3 rounded-lg transition-colors"
             >
               <Send size={20} />
             </button>
             {/* Small backup map button kept in layout but duplicate of top-left */}
             <button onClick={() => onExit(false)} className="border border-indigo-900/50 text-indigo-400 hover:bg-indigo-900/20 p-3 rounded-lg transition-colors flex gap-2 items-center" title="Return to Map">
               <Map size={20} />
             </button>
          </div>

        </div>

        {/* Current Goal Display */}
        <div className="absolute top-4 right-4 md:right-12 bg-black/60 backdrop-blur text-xs text-green-400 px-3 py-1 rounded border border-green-900">
          Objective: {currentScene.goal}
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Character, RPGState, WorldMap, Scene } from '../types';
import { Save, LogOut, ZoomIn, ZoomOut, Maximize } from 'lucide-react';

interface RPGWorldProps {
  characters: Character[];
  mapConfig: WorldMap; // The CURRENT map
  maps: WorldMap[]; // For referencing target map names
  scenes: Scene[]; // Needed to check dependencies
  onInteraction: (type: 'scene'|'transition', id: string) => void;
  initialState?: RPGState;
  onSave: (state: RPGState) => void;
  onExit: () => void;
}

export const RPGWorld: React.FC<RPGWorldProps> = ({ 
  characters, 
  mapConfig,
  maps,
  scenes,
  onInteraction, 
  initialState, 
  onSave,
  onExit
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const [hoveredSpotId, setHoveredSpotId] = useState<string | null>(null);
  const [canvasDims, setCanvasDims] = useState({ width: 1000, height: 750 });

  // Camera / Viewport State
  const [zoom, setZoom] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });

  // Cache for loaded sprite images
  const spritesRef = useRef<Record<string, HTMLImageElement>>({});
  const [spritesLoaded, setSpritesLoaded] = useState(false);

  // Preload Sprites
  useEffect(() => {
    let active = true;
    const loadSprites = async () => {
        const promises = characters.map(c => {
            if (!c.mapSpriteSrc) return Promise.resolve();
            return new Promise<void>((resolve) => {
                const img = new Image();
                img.src = c.mapSpriteSrc!;
                img.onload = () => {
                    if(active) spritesRef.current[c.id] = img;
                    resolve();
                };
                img.onerror = () => resolve(); 
            });
        });

        await Promise.all(promises);
        if (active) setSpritesLoaded(true);
    };
    loadSprites();
    return () => { active = false; };
  }, [characters]);

  // Adjust canvas dimensions to match background image AND fit to screen
  useEffect(() => {
    const applyFit = (w: number, h: number) => {
        setCanvasDims({ width: w, height: h });

        if (containerRef.current) {
            const { clientWidth, clientHeight } = containerRef.current;
            // Fit to screen with 5% padding
            const scale = Math.min(clientWidth / w, clientHeight / h) * 0.95;
            const newX = (clientWidth - w * scale) / 2;
            const newY = (clientHeight - h * scale) / 2;

            setZoom(scale);
            setOffset({ x: newX, y: newY });
        }
    };

    if (mapConfig.backgroundSrc) {
        const img = new Image();
        img.src = mapConfig.backgroundSrc;
        img.onload = () => {
            applyFit(img.naturalWidth, img.naturalHeight);
        };
    } else {
        applyFit(1000, 750);
    }
  }, [mapConfig.id, mapConfig.backgroundSrc]); // Run when map ID changes

  // --- Visibility Logic ---
  // A spot is visible if:
  // 1. It is a Transition: It must NOT be locked by another scene, OR it must be in unlockedIds.
  // 2. It is a Scene (Character): The character must have AT LEAST ONE scene available that is (Unlocked OR Not Locked) AND Not Completed.

  const visibleSpots = mapConfig.spots.filter(spot => {
      if (spot.type === 'transition') {
          const targetMapId = spot.targetMapId;
          if (!targetMapId) return false;

          // Is this transition locked by any scene?
          const isLockedByDependency = scenes.some(s => s.unlocks?.some(u => u.type === 'transition' && u.targetId === targetMapId));
          // Is it explicitly unlocked?
          const isUnlocked = initialState?.unlockedIds.includes(targetMapId);

          // Show if: Not Locked OR Unlocked
          return !isLockedByDependency || isUnlocked;

      } else if (spot.type === 'scene') {
          const charId = spot.characterId;
          if (!charId) return false;

          // Find scenes for this character
          const charScenes = scenes.filter(s => s.characters.some(c => c.characterId === charId));

          // Check if ANY scene is available to play
          const hasPlayableScene = charScenes.some(s => {
             const isCompleted = initialState?.completedSceneIds.includes(s.id);
             if (isCompleted) return false; // Already done

             const isLockedByDependency = scenes.some(other => other.unlocks?.some(u => u.type === 'scene' && u.targetId === s.id));
             const isUnlocked = initialState?.unlockedIds.includes(s.id);

             return !isLockedByDependency || isUnlocked;
          });

          return hasPlayableScene;
      }
      return true;
  });

  // --- Coordinate Systems ---

  const getRawMousePos = (e: React.MouseEvent | React.WheelEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    return {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top
    };
  };

  const getMousePosInWorldPercent = (rawX: number, rawY: number) => {
     const worldX = (rawX - offset.x) / zoom;
     const worldY = (rawY - offset.y) / zoom;
     return {
       x: (worldX / canvasDims.width) * 100,
       y: (worldY / canvasDims.height) * 100
     };
  };

  const checkHit = (xPct: number, yPct: number) => {
    // 4% radius in World Space for easier clicking
    const THRESHOLD = 4; 

    return visibleSpots.find(spot => {
       const dx = spot.x - xPct;
       const dy = spot.y - yPct;
       return Math.sqrt(dx*dx + dy*dy) < THRESHOLD;
    });
  };

  // --- Interaction Handlers ---

  const handleWheel = (e: React.WheelEvent<HTMLCanvasElement>) => {
    e.preventDefault();
    const zoomSensitivity = 0.001;
    const delta = -e.deltaY * zoomSensitivity;
    const newZoom = Math.min(Math.max(zoom + delta, 0.1), 5); 

    if (newZoom === zoom) return;

    const mouse = getRawMousePos(e);
    const worldX = (mouse.x - offset.x) / zoom;
    const worldY = (mouse.y - offset.y) / zoom;

    const newOffsetX = mouse.x - worldX * newZoom;
    const newOffsetY = mouse.y - worldY * newZoom;

    setZoom(newZoom);
    setOffset({ x: newOffsetX, y: newOffsetY });
  };

  const handleMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (e.button === 0) {
      setIsDragging(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (isDragging) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return; 
    }

    const raw = getRawMousePos(e);
    const worldPct = getMousePosInWorldPercent(raw.x, raw.y);
    const hit = checkHit(worldPct.x, worldPct.y);

    if (hit) {
      if (hoveredSpotId !== hit.id) setHoveredSpotId(hit.id);
    } else {
      if (hoveredSpotId !== null) setHoveredSpotId(null);
    }
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const handleClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (isDragging) return;

    const raw = getRawMousePos(e);
    const worldPct = getMousePosInWorldPercent(raw.x, raw.y);
    const hit = checkHit(worldPct.x, worldPct.y);
    if (hit) {
      if (hit.type === 'scene' && hit.characterId) {
          onInteraction('scene', hit.characterId);
      } else if (hit.type === 'transition' && hit.targetMapId) {
          onInteraction('transition', hit.targetMapId);
      }
    }
  };

  // --- Rendering ---

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.save();

    ctx.fillStyle = '#0f172a'; 
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.translate(offset.x, offset.y);
    ctx.scale(zoom, zoom);

    // Draw World
    const bgImage = new Image();
    if (mapConfig.backgroundSrc) {
       bgImage.src = mapConfig.backgroundSrc;
    }

    const drawScene = () => {
        // Background
        if (mapConfig.backgroundSrc && bgImage.complete) {
            ctx.drawImage(bgImage, 0, 0, canvasDims.width, canvasDims.height);
        } else {
            // Fallback Grid
            ctx.fillStyle = '#1e293b';
            ctx.fillRect(0, 0, canvasDims.width, canvasDims.height);
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 2;
            ctx.strokeRect(0, 0, canvasDims.width, canvasDims.height);
        }

        const toPx = (pct: number, dim: number) => (pct / 100) * dim;

        // Render Spots
        visibleSpots.forEach(spot => {
          const cx = toPx(spot.x, canvasDims.width);
          const cy = toPx(spot.y, canvasDims.height);
          const isHovered = hoveredSpotId === spot.id;

          if (spot.type === 'scene' && spot.characterId) {
              const char = characters.find(c => c.id === spot.characterId);
              if (!char) return;

              const spriteImg = spritesRef.current[char.id];
              let renderedHeight = 0;

              if (spriteImg) {
                  const ratio = spriteImg.naturalWidth / spriteImg.naturalHeight || 1;
                  const baseScale = Math.max(canvasDims.width / 1000, 0.5); 
                  const targetHeight = (isHovered ? 80 : 70) * baseScale;

                  const drawHeight = targetHeight;
                  const drawWidth = targetHeight * ratio;
                  renderedHeight = drawHeight;

                  ctx.save();
                  ctx.shadowColor = isHovered ? 'white' : 'black';
                  ctx.shadowBlur = isHovered ? 15 : 5;

                  ctx.drawImage(spriteImg, cx - drawWidth/2, cy - drawHeight/2, drawWidth, drawHeight);
                  ctx.restore();
              } else {
                  // Fallback Circle
                  renderedHeight = 24;
                  ctx.fillStyle = char.rpgColor;
                  ctx.beginPath();
                  ctx.arc(cx, cy, isHovered ? 12 : 10, 0, Math.PI * 2);
                  ctx.fill();
                  ctx.lineWidth = 2;
                  ctx.strokeStyle = 'white';
                  ctx.stroke();
              }

              // Name Tag (Scene Spots)
              if (isHovered) {
                ctx.save();
                const textScale = Math.max(1 / zoom, 0.5); 
                ctx.translate(cx, cy - (renderedHeight / 2) - 14 * textScale);
                ctx.scale(textScale, textScale);

                ctx.fillStyle = 'rgba(0,0,0,0.8)';
                ctx.font = 'bold 16px sans-serif';
                const textW = ctx.measureText(char.name).width;

                ctx.fillRect(-textW/2 - 8, -20, textW + 16, 28);
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.fillText(char.name, 0, 0);
                ctx.restore();
              }

          } else if (spot.type === 'transition') {
              // Visible Waypoint Marker
              const radius = 16;
              const pulseColor = 'rgba(52, 211, 153, 0.6)';

              // Pulse Effect (Visible on hover or always subtle)
              if (isHovered) {
                  const time = Date.now() / 300;
                  const pulse = Math.sin(time) * 4 + radius + 4;
                  ctx.beginPath();
                  ctx.arc(cx, cy, pulse, 0, Math.PI * 2);
                  ctx.strokeStyle = pulseColor;
                  ctx.lineWidth = 2;
                  ctx.stroke();
              }

              // Main Marker Body (Emerald Green)
              ctx.beginPath();
              ctx.arc(cx, cy, radius, 0, Math.PI * 2);
              ctx.fillStyle = 'rgba(16, 185, 129, 0.9)'; // Emerald-500
              ctx.fill();

              // Border
              ctx.strokeStyle = '#6ee7b7'; // Emerald-300
              ctx.lineWidth = 2;
              ctx.stroke();

              // Inner Dot
              ctx.beginPath();
              ctx.arc(cx, cy, 6, 0, Math.PI * 2);
              ctx.fillStyle = '#ffffff';
              ctx.fill();

              // Label (Only on Hover)
              if (isHovered) {
                  ctx.save();

                  // Label
                  const targetMapName = maps.find(m => m.id === spot.targetMapId)?.name || 'Unknown Area';
                  const text = `Travel to ${targetMapName}`;

                  const textScale = Math.max(1 / zoom, 0.5); 
                  ctx.translate(cx, cy - 30 * textScale);
                  ctx.scale(textScale, textScale);

                  ctx.fillStyle = 'rgba(0,0,0,0.8)';
                  ctx.font = 'bold 14px sans-serif';
                  const textW = ctx.measureText(text).width;

                  ctx.fillRect(-textW/2 - 8, -18, textW + 16, 26);
                  ctx.fillStyle = '#6ee7b7'; // Emerald color text
                  ctx.textAlign = 'center';
                  ctx.fillText(text, 0, 0);

                  ctx.restore();
              }
          }
        });
    }

    if (bgImage.complete || !mapConfig.backgroundSrc) {
        drawScene();
    } else {
        bgImage.onload = drawScene;
    }

    ctx.restore();

  }, [mapConfig, characters, hoveredSpotId, spritesLoaded, canvasDims, zoom, offset, visibleSpots]);

  const handleManualSave = () => {
    onSave({ 
        currentMapId: mapConfig.id,
        completedSceneIds: initialState?.completedSceneIds || [],
        unlockedIds: initialState?.unlockedIds || [] 
    });
  };

  const handleZoomIn = () => setZoom(z => Math.min(z + 0.2, 5));
  const handleZoomOut = () => setZoom(z => Math.max(z - 0.2, 0.1));
  const handleResetView = () => {
        if (containerRef.current) {
            const { clientWidth, clientHeight } = containerRef.current;
            const w = canvasDims.width;
            const h = canvasDims.height;
            // Fit to screen with padding
            const scale = Math.min(clientWidth / w, clientHeight / h) * 0.95;
            const newX = (clientWidth - w * scale) / 2;
            const newY = (clientHeight - h * scale) / 2;

            setZoom(scale);
            setOffset({ x: newX, y: newY });
        }
  };

  return (
    <div className="relative w-full h-full bg-gray-950 flex flex-col overflow-hidden">
      {/* HUD */}
      <div className="absolute top-4 left-4 z-10 pointer-events-none">
          <div className="bg-gray-900/80 p-3 rounded-xl border border-gray-700 backdrop-blur-sm shadow-xl pointer-events-auto">
            <h1 className="text-xl font-bold text-indigo-400">{mapConfig.name.toUpperCase()}</h1>
            <p className="text-xs text-gray-400 mt-1">Drag to Pan • Wheel to Zoom</p>
          </div>
      </div>

      {/* Main Canvas Container */}
      <div 
        ref={containerRef}
        className="flex-1 w-full h-full relative overflow-hidden bg-[#0f172a] cursor-grab active:cursor-grabbing"
      >
        <canvas 
          ref={canvasRef}
          width={canvasRef.current?.parentElement?.clientWidth || 1000} 
          height={canvasRef.current?.parentElement?.clientHeight || 750}
          className="block w-full h-full"
          onWheel={handleWheel}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
          onClick={handleClick}
          style={{ touchAction: 'none', cursor: hoveredSpotId ? 'pointer' : 'default' }}
        />
      </div>

      {/* Bottom Controls */}
      <div className="absolute bottom-8 right-8 flex gap-3 z-10">
         <div className="bg-gray-800 rounded-full border border-gray-600 flex overflow-hidden shadow-lg mr-4">
            <button onClick={handleZoomOut} className="p-3 hover:bg-gray-700 text-white transition border-r border-gray-600">
                <ZoomOut size={20} />
            </button>
            <button onClick={handleResetView} className="p-3 hover:bg-gray-700 text-white transition border-r border-gray-600" title="Reset View">
                <Maximize size={20} />
            </button>
            <button onClick={handleZoomIn} className="p-3 hover:bg-gray-700 text-white transition">
                <ZoomIn size={20} />
            </button>
         </div>

         <button onClick={handleManualSave} className="bg-indigo-600 p-3 rounded-full hover:bg-indigo-500 text-white shadow-lg transition transform hover:scale-105" title="Save Game">
           <Save size={24} />
         </button>
         <button onClick={onExit} className="bg-gray-800 p-3 rounded-full hover:bg-red-900/80 text-white border border-gray-600 shadow-lg transition transform hover:scale-105" title="Exit to Editor">
           <LogOut size={24} />
         </button>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Plus, Trash2, Image as ImageIcon, User, Target, Save, PlayCircle, RotateCcw, Map as MapIcon, MousePointerClick, FileUp, Download, Upload, Check, Waypoints, Globe, Lock, Unlock } from 'lucide-react';
import { Character, Scene, SceneCharacterConfig, WorldMap, MapSpot, UnlockReward } from '../types';
import { Button } from './ui/Button';

interface EditorProps {
  characters: Character[];
  scenes: Scene[];
  maps: WorldMap[];
  onUpdateCharacters: (chars: Character[]) => void;
  onUpdateScenes: (scenes: Scene[]) => void;
  onUpdateMaps: (maps: WorldMap[]) => void;
  onPlay: () => void;
  onQuickSave: () => Promise<boolean>;
  onExportProject: () => void;
  onImportProject: (file: File) => void;
  hasSaveGame: boolean;
  onContinueGame: () => void;
}

export const Editor: React.FC<EditorProps> = ({
  characters,
  scenes,
  maps,
  onUpdateCharacters,
  onUpdateScenes,
  onUpdateMaps,
  onPlay,
  onQuickSave,
  onExportProject,
  onImportProject,
  hasSaveGame,
  onContinueGame
}) => {
  const [activeTab, setActiveTab] = useState<'chars' | 'scenes' | 'map'>('chars');

  // Map Editor State
  const [activeMapId, setActiveMapId] = useState<string>(maps[0]?.id || '');
  const [selectedTool, setSelectedTool] = useState<{type: 'scene'|'transition', id: string} | null>(null);

  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const importInputRef = useRef<HTMLInputElement>(null);

  // --- Character Handlers ---
  const addCharacter = () => {
    const newChar: Character = {
      id: crypto.randomUUID(),
      name: 'New Character',
      defaultDescription: 'A friendly helper.',
      imageSrc: null,
      mapSpriteSrc: null,
      rpgColor: '#ef4444', 
    };
    onUpdateCharacters([...characters, newChar]);
  };

  const updateCharacter = (id: string, updates: Partial<Character>) => {
    onUpdateCharacters(characters.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const handleCharImageUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>, field: 'imageSrc' | 'mapSpriteSrc') => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCharacter(id, { [field]: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  // --- Scene Handlers ---
  const addScene = () => {
    const newScene: Scene = {
      id: crypto.randomUUID(),
      name: `Scene ${scenes.length + 1}`,
      backgroundSrc: null,
      description: 'You are in a quiet room.',
      goal: 'Say hello.',
      characters: [],
      unlocks: []
    };
    onUpdateScenes([...scenes, newScene]);
  };

  const updateScene = (id: string, updates: Partial<Scene>) => {
    onUpdateScenes(scenes.map(s => s.id === id ? { ...s, ...updates } : s));
  };

  const toggleUnlock = (sceneId: string, type: 'scene' | 'transition', targetId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const currentUnlocks = scene.unlocks || [];
    const exists = currentUnlocks.some(u => u.type === type && u.targetId === targetId);

    let newUnlocks;
    if (exists) {
        newUnlocks = currentUnlocks.filter(u => !(u.type === type && u.targetId === targetId));
    } else {
        newUnlocks = [...currentUnlocks, { type, targetId }];
    }
    updateScene(sceneId, { unlocks: newUnlocks });
  };

  const handleBgUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleCharInScene = (sceneId: string, charId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const exists = scene.characters.find(c => c.characterId === charId);
    let newChars: SceneCharacterConfig[];

    if (exists) {
      newChars = scene.characters.filter(c => c.characterId !== charId);
    } else {
      newChars = [...scene.characters, { characterId: charId, roleInScene: 'Default behavior' }];
    }
    updateScene(sceneId, { characters: newChars });
  };

  const updateSceneCharRole = (sceneId: string, charId: string, role: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;
    const newChars = scene.characters.map(c => c.characterId === charId ? { ...c, roleInScene: role } : c);
    updateScene(sceneId, { characters: newChars });
  };

  // --- Map Handlers ---

  const getCurrentMap = () => maps.find(m => m.id === activeMapId);

  const addMap = () => {
      const newMap: WorldMap = {
          id: crypto.randomUUID(),
          name: `Map ${maps.length + 1}`,
          backgroundSrc: null,
          spots: []
      };
      const newMaps = [...maps, newMap];
      onUpdateMaps(newMaps);
      setActiveMapId(newMap.id);
  };

  const deleteMap = (id: string) => {
      if (maps.length <= 1) {
          alert("You must have at least one map.");
          return;
      }
      const newMaps = maps.filter(m => m.id !== id);
      onUpdateMaps(newMaps);
      if (activeMapId === id) setActiveMapId(newMaps[0].id);
  };

  const updateCurrentMap = (updates: Partial<WorldMap>) => {
      onUpdateMaps(maps.map(m => m.id === activeMapId ? { ...m, ...updates } : m));
  };

  const handleMapBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCurrentMap({ backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const handleMapClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!selectedTool || !mapContainerRef.current) return;

    // Check if clicked on an existing pin
    if ((e.target as HTMLElement).closest('.map-pin')) return;

    const rect = mapContainerRef.current.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;

    const currentMap = getCurrentMap();
    if (!currentMap) return;

    const newSpot: MapSpot = {
      id: crypto.randomUUID(),
      type: selectedTool.type,
      x, 
      y,
      // Only one of these will be set depending on type
      characterId: selectedTool.type === 'scene' ? selectedTool.id : undefined,
      targetMapId: selectedTool.type === 'transition' ? selectedTool.id : undefined,
    };

    updateCurrentMap({ spots: [...currentMap.spots, newSpot] });
  };

  const removeSpot = (spotId: string) => {
    const currentMap = getCurrentMap();
    if(!currentMap) return;
    updateCurrentMap({
      spots: currentMap.spots.filter(s => s.id !== spotId)
    });
  };

  // --- Toolbar Handlers ---

  const handleQuickSaveClick = async () => {
    setSaveStatus('saving');
    await onQuickSave();
    setSaveStatus('saved');
    setTimeout(() => setSaveStatus('idle'), 2000);
  };

  const handleImportClick = () => {
    importInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if(e.target.files && e.target.files[0]) {
        onImportProject(e.target.files[0]);
    }
    if(e.target.value) e.target.value = ''; 
  };

  const currentMap = getCurrentMap();

  return (
    <div className="flex flex-col h-full max-w-6xl mx-auto p-4 md:p-8">
      {/* Header / Toolbar */}
      <div className="flex flex-col xl:flex-row justify-between items-center mb-8 gap-6">
        <div>
           <h1 className="text-3xl font-bold text-indigo-400">VN Creator Studio</h1>
           <p className="text-gray-400 text-sm mt-1">Design your world, characters, and stories.</p>
        </div>

        <div className="flex flex-wrap gap-3 items-center justify-center">
          {/* File Operations */}
          <div className="flex gap-2 mr-2 bg-gray-800 p-1 rounded-lg border border-gray-700">
             <input type="file" ref={importInputRef} className="hidden" accept=".json" onChange={handleFileChange} />

             <button onClick={handleImportClick} className="flex items-center gap-2 px-3 py-2 text-sm text-gray-300 hover:text-white hover:bg-gray-700 rounded transition" title="Load .json file">
               <Upload size={16} /> Load Project
             </button>

             <div className="w-[1px] bg-gray-600 my-1"></div>

             <button onClick={onExportProject} className="flex items-center gap-2 px-3 py-2 text-sm text-gray-300 hover:text-white hover:bg-gray-700 rounded transition" title="Download .json file">
               <Download size={16} /> Export Project
             </button>
          </div>

          <Button 
            onClick={handleQuickSaveClick} 
            variant="secondary" 
            title="Saves to Browser Storage"
            className="min-w-[140px]"
            disabled={saveStatus === 'saving'}
          >
            {saveStatus === 'saved' ? <><Check size={18} className="text-green-400"/> Saved!</> : (saveStatus === 'saving' ? 'Saving...' : <><Save size={18} /> Quick Save</>)}
          </Button>

          <div className="h-8 w-[1px] bg-gray-700 mx-2 hidden md:block"></div>

          {hasSaveGame && (
            <Button onClick={onContinueGame} className="bg-yellow-600 hover:bg-yellow-500">
              <RotateCcw size={18} /> Continue
            </Button>
          )}

          <Button onClick={onPlay} className="bg-green-600 hover:bg-green-500 px-6 font-bold shadow-green-900/20">
            <PlayCircle size={18} /> PLAY GAME
          </Button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex gap-4 mb-6 border-b border-gray-700 pb-1">
        <button
          onClick={() => setActiveTab('chars')}
          className={`px-4 py-2 font-medium transition-colors ${activeTab === 'chars' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}
        >
          Characters
        </button>
        <button
          onClick={() => setActiveTab('scenes')}
          className={`px-4 py-2 font-medium transition-colors ${activeTab === 'scenes' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}
        >
          Scenarios
        </button>
        <button
          onClick={() => setActiveTab('map')}
          className={`px-4 py-2 font-medium transition-colors ${activeTab === 'map' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}
        >
          World Map
        </button>
      </div>

      <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
        {activeTab === 'chars' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {characters.map(char => (
                <div key={char.id} className="bg-gray-800 p-4 rounded-xl border border-gray-700 flex gap-4 shadow-lg hover:border-gray-600 transition-colors">

                  {/* Portrait (Left) */}
                  <div className="w-24 h-32 bg-gray-900 rounded-lg flex-shrink-0 border border-gray-600 overflow-hidden relative group">
                    {char.imageSrc ? (
                      <img src={char.imageSrc} alt={char.name} className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full flex flex-col items-center justify-center text-gray-600 gap-1">
                        <User size={24} />
                        <span className="text-[10px] text-center px-1">Portrait</span>
                      </div>
                    )}
                    <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity text-xs font-bold">
                      UPLOAD
                      <input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e, 'imageSrc')} />
                    </label>
                  </div>

                  <div className="flex-1 space-y-3">
                    <input
                      className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-1 focus:border-indigo-500 outline-none transition-all"
                      value={char.name}
                      onChange={(e) => updateCharacter(char.id, { name: e.target.value })}
                      placeholder="Character Name"
                    />

                    {/* Map Sprite Uploader */}
                    <div className="flex items-center gap-3">
                       <div className="w-12 h-12 bg-gray-900 rounded border border-gray-600 overflow-hidden relative group shrink-0">
                         {char.mapSpriteSrc ? (
                           <img src={char.mapSpriteSrc} alt="Sprite" className="w-full h-full object-contain" />
                         ) : (
                           <div className="w-full h-full flex items-center justify-center text-gray-600" title="Map Sprite">
                             <MapIcon size={16} />
                           </div>
                         )}
                         <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity">
                            <FileUp size={16} className="text-white"/>
                            <input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e, 'mapSpriteSrc')} />
                         </label>
                       </div>
                       <div className="text-xs text-gray-400">
                         <span className="font-bold block text-gray-300">Map Sprite</span>
                         <span className="text-[10px]">Icon used on the world map.</span>
                       </div>
                    </div>

                    <textarea
                      className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-1 h-20 text-sm focus:border-indigo-500 outline-none resize-none transition-all"
                      value={char.defaultDescription}
                      onChange={(e) => updateCharacter(char.id, { defaultDescription: e.target.value })}
                      placeholder="Core Persona/Description..."
                    />
                  </div>
                  <button onClick={() => onUpdateCharacters(characters.filter(c => c.id !== char.id))} className="text-gray-500 hover:text-red-500 h-fit transition-colors p-1">
                    <Trash2 size={18} />
                  </button>
                </div>
              ))}
            </div>
            <Button onClick={addCharacter} variant="secondary" className="w-full py-4 border-dashed opacity-70 hover:opacity-100">
              <Plus size={20} /> Add Character
            </Button>
          </div>
        )}

        {activeTab === 'scenes' && (
          <div className="space-y-8">
            {scenes.map((scene, idx) => (
              <div key={scene.id} className="bg-gray-800 p-6 rounded-xl border border-gray-700 space-y-4 shadow-lg">
                <div className="flex justify-between items-start">
                  <div className="flex items-center gap-4">
                    <div className="bg-gray-900 px-3 py-1 rounded text-xs font-bold text-indigo-400 border border-gray-700">SCENE {idx + 1}</div>
                    <input
                       className="bg-transparent text-xl font-bold outline-none placeholder-gray-600 focus:text-white transition-colors"
                       value={scene.name}
                       onChange={(e) => updateScene(scene.id, { name: e.target.value })}
                       placeholder="Scene Name"
                    />
                  </div>
                  <button onClick={() => onUpdateScenes(scenes.filter(s => s.id !== scene.id))} className="text-gray-500 hover:text-red-500 transition-colors p-1">
                    <Trash2 size={18} />
                  </button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                  {/* Visuals & Goal */}
                  <div className="space-y-4">
                    <div className="w-full h-40 bg-gray-900 rounded-lg border border-gray-600 overflow-hidden relative group shadow-inner">
                       {scene.backgroundSrc ? (
                          <img src={scene.backgroundSrc} alt="bg" className="w-full h-full object-cover opacity-80" />
                       ) : (
                         <div className="w-full h-full flex items-center justify-center text-gray-500 gap-2">
                           <ImageIcon size={24} /> No Background
                         </div>
                       )}
                       <label className="absolute inset-0 flex items-center justify-center cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity bg-black/40">
                          <span className="bg-black/80 px-4 py-2 rounded hover:bg-black text-sm border border-gray-600">Change Background</span>
                          <input type="file" accept="image/*" className="hidden" onChange={(e) => handleBgUpload(scene.id, e)} />
                       </label>
                    </div>

                    <div>
                      <label className="flex items-center gap-2 text-xs font-bold text-green-400 mb-1">
                        <Target size={14} /> WIN CONDITION (Scenario Goal)
                      </label>
                      <textarea
                        className="w-full bg-gray-900 border border-green-900/50 text-green-100 rounded px-3 py-2 text-sm focus:border-green-500 outline-none resize-none transition-all shadow-inner"
                        value={scene.goal}
                        onChange={(e) => updateScene(scene.id, { goal: e.target.value })}
                        placeholder="e.g. Convince the guard to let you pass..."
                        rows={3}
                      />
                    </div>

                    {/* Rewards / Unlocks Configuration */}
                    <div className="bg-gray-900/50 p-3 rounded-lg border border-gray-700">
                        <label className="flex items-center gap-2 text-xs font-bold text-yellow-500 mb-2">
                            <Unlock size={14} /> UNLOCKS ON COMPLETION
                        </label>
                        <p className="text-[10px] text-gray-500 mb-2">Select Scenarios or Maps that become available after this.</p>

                        <div className="space-y-2 max-h-32 overflow-y-auto custom-scrollbar">
                            {/* Other Scenes */}
                            {scenes.filter(s => s.id !== scene.id).map(otherScene => {
                                const isUnlocked = scene.unlocks?.some(u => u.type === 'scene' && u.targetId === otherScene.id);
                                return (
                                    <button 
                                        key={otherScene.id} 
                                        onClick={() => toggleUnlock(scene.id, 'scene', otherScene.id)}
                                        className={`w-full flex items-center gap-2 text-xs p-1.5 rounded border ${isUnlocked ? 'bg-yellow-900/30 border-yellow-600 text-yellow-100' : 'bg-gray-800 border-gray-700 text-gray-400 hover:border-gray-500'}`}
                                    >
                                        {isUnlocked ? <Unlock size={10} /> : <Lock size={10} />}
                                        <span className="truncate">Scene: {otherScene.name}</span>
                                    </button>
                                );
                            })}

                            {/* Maps */}
                            {maps.map(m => {
                                const isUnlocked = scene.unlocks?.some(u => u.type === 'transition' && u.targetId === m.id);
                                return (
                                    <button 
                                        key={m.id} 
                                        onClick={() => toggleUnlock(scene.id, 'transition', m.id)}
                                        className={`w-full flex items-center gap-2 text-xs p-1.5 rounded border ${isUnlocked ? 'bg-emerald-900/30 border-emerald-600 text-emerald-100' : 'bg-gray-800 border-gray-700 text-gray-400 hover:border-gray-500'}`}
                                    >
                                        {isUnlocked ? <Globe size={10} /> : <Lock size={10} />}
                                        <span className="truncate">Travel to: {m.name}</span>
                                    </button>
                                );
                            })}

                            {(scenes.length <= 1 && maps.length === 0) && <span className="text-xs text-gray-600 italic">Create more content to add unlocks.</span>}
                        </div>
                    </div>
                  </div>

                  {/* Narrative Setup */}
                  <div className="space-y-2 lg:col-span-2">
                     <label className="block text-xs font-bold text-gray-400">SCENARIO DESCRIPTION (For AI)</label>
                     <textarea
                        className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-2 text-sm focus:border-indigo-500 outline-none resize-none transition-all"
                        value={scene.description}
                        onChange={(e) => updateScene(scene.id, { description: e.target.value })}
                        placeholder="Describe the setting, the mood, and what is happening..."
                        rows={3}
                      />

                      <label className="block text-xs font-bold text-gray-400 mt-4">PARTICIPATING CHARACTERS</label>
                      <div className="bg-gray-900 rounded-lg p-3 border border-gray-700 min-h-[100px] shadow-inner">
                         <div className="flex gap-2 flex-wrap mb-3">
                           {characters.map(char => {
                             const isActive = scene.characters.some(c => c.characterId === char.id);
                             return (
                               <button
                                 key={char.id}
                                 onClick={() => toggleCharInScene(scene.id, char.id)}
                                 className={`text-xs px-3 py-1 rounded-full border transition-all ${isActive ? 'bg-indigo-600 border-indigo-400 text-white shadow-md' : 'bg-gray-800 border-gray-600 text-gray-400 hover:border-gray-400 hover:text-gray-300'}`}
                               >
                                 {char.name}
                               </button>
                             )
                           })}
                           {characters.length === 0 && <span className="text-xs text-gray-600 italic">No characters created yet.</span>}
                         </div>

                         {/* Per-Scene Character Logic */}
                         <div className="space-y-3">
                           {scene.characters.map(sc => {
                             const char = characters.find(c => c.id === sc.characterId);
                             if (!char) return null;
                             return (
                               <div key={sc.characterId} className="flex items-center gap-3 bg-gray-800 p-2 rounded border border-gray-700">
                                 <div className="w-8 h-8 rounded-full bg-gray-700 overflow-hidden flex-shrink-0 border border-gray-600" style={{ backgroundColor: char.rpgColor }}>
                                   {char.imageSrc && <img src={char.imageSrc} className="w-full h-full object-cover" />}
                                 </div>
                                 <div className="flex-1">
                                    <div className="text-xs font-bold text-indigo-300">{char.name} Role</div>
                                    <input 
                                      className="w-full bg-transparent border-b border-gray-600 text-xs py-1 focus:border-indigo-400 outline-none transition-colors"
                                      placeholder="What does this character want in this scene?"
                                      value={sc.roleInScene}
                                      onChange={(e) => updateSceneCharRole(scene.id, sc.characterId, e.target.value)}
                                    />
                                 </div>
                               </div>
                             )
                           })}
                           {scene.characters.length === 0 && <div className="text-xs text-gray-500 text-center py-4">Select characters above to assign roles.</div>}
                         </div>
                      </div>
                  </div>
                </div>
              </div>
            ))}
            <Button onClick={addScene} variant="secondary" className="w-full py-4 border-dashed opacity-70 hover:opacity-100">
              <Plus size={20} /> Add Scenario
            </Button>
          </div>
        )}

        {activeTab === 'map' && (
          <div className="flex flex-col lg:flex-row gap-6 h-full">
            {/* Sidebar Controls */}
            <div className="w-full lg:w-64 flex flex-col gap-6">

              {/* Map Switcher */}
              <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 shadow-lg space-y-3">
                  <div className="flex items-center justify-between mb-2">
                     <h3 className="font-bold text-gray-300 flex items-center gap-2"><Globe size={16}/> Maps</h3>
                     <button onClick={addMap} className="text-indigo-400 hover:text-white p-1 rounded bg-indigo-900/30 hover:bg-indigo-600 transition">
                         <Plus size={14} />
                     </button>
                  </div>

                  <div className="space-y-2 max-h-32 overflow-y-auto custom-scrollbar">
                     {maps.map(m => (
                         <div key={m.id} className={`flex items-center justify-between p-2 rounded cursor-pointer border ${m.id === activeMapId ? 'bg-indigo-900/50 border-indigo-500' : 'bg-gray-900 border-gray-800 hover:border-gray-600'}`} onClick={() => setActiveMapId(m.id)}>
                             <span className="text-xs truncate max-w-[120px]">{m.name}</span>
                             {maps.length > 1 && (
                                 <button onClick={(e) => { e.stopPropagation(); deleteMap(m.id); }} className="text-gray-600 hover:text-red-400">
                                     <Trash2 size={12} />
                                 </button>
                             )}
                         </div>
                     ))}
                  </div>

                  {currentMap && (
                      <div className="pt-2 border-t border-gray-700">
                         <input 
                            className="w-full bg-gray-900 border border-gray-600 rounded px-2 py-1 text-xs text-gray-200 outline-none focus:border-indigo-500"
                            value={currentMap.name}
                            onChange={(e) => updateCurrentMap({ name: e.target.value })}
                            placeholder="Map Name"
                         />
                      </div>
                  )}
              </div>

              {/* Map Background Config */}
              {currentMap && (
                  <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 shadow-lg">
                    <h3 className="font-bold text-gray-300 mb-3 flex items-center gap-2 text-sm"><MapIcon size={14}/> Background</h3>
                    <label className="block w-full cursor-pointer bg-gray-900 border border-gray-600 hover:border-gray-400 hover:bg-gray-800 text-center py-4 rounded-lg border-dashed transition-all group">
                    <span className="text-xs text-gray-400 group-hover:text-white">Change Image</span>
                    <input type="file" accept="image/*" className="hidden" onChange={handleMapBgUpload} />
                    </label>
                </div>
              )}

              {/* Tools: Characters & Transitions */}
              <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 flex-1 shadow-lg flex flex-col min-h-[300px]">
                 <h3 className="font-bold text-gray-300 mb-3 flex items-center gap-2 text-sm"><User size={14}/> Place Items</h3>
                 <p className="text-xs text-gray-500 mb-4">Select an item, then click on the map to place.</p>

                 <div className="space-y-4 overflow-y-auto custom-scrollbar flex-1">
                    {/* Characters */}
                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2">Scene Triggers</div>
                        <div className="space-y-1">
                            {characters.map(char => (
                            <button 
                                key={char.id}
                                onClick={() => setSelectedTool(selectedTool?.id === char.id ? null : { type: 'scene', id: char.id })}
                                className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === char.id && selectedTool.type === 'scene' ? 'bg-indigo-600/20 border-indigo-500 ring-1 ring-indigo-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}
                            >
                                <div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 overflow-hidden flex items-center justify-center flex-shrink-0">
                                    {char.mapSpriteSrc ? <img src={char.mapSpriteSrc} className="w-full h-full object-contain" /> : <div className="w-full h-full" style={{backgroundColor: char.rpgColor}} />}
                                </div>
                                <span className="text-xs font-medium truncate">{char.name}</span>
                                {selectedTool?.id === char.id && selectedTool.type === 'scene' && <MousePointerClick size={12} className="ml-auto text-indigo-400"/>}
                            </button>
                            ))}
                        </div>
                    </div>

                    {/* Transitions */}
                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2">Map Transitions</div>
                        <div className="space-y-1">
                            {maps.filter(m => m.id !== activeMapId).map(targetMap => (
                                <button
                                    key={targetMap.id}
                                    onClick={() => setSelectedTool(selectedTool?.id === targetMap.id ? null : { type: 'transition', id: targetMap.id })}
                                    className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === targetMap.id && selectedTool.type === 'transition' ? 'bg-emerald-600/20 border-emerald-500 ring-1 ring-emerald-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}
                                >
                                    <div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 flex items-center justify-center flex-shrink-0 text-emerald-500">
                                        <Waypoints size={14} />
                                    </div>
                                    <span className="text-xs font-medium truncate">To: {targetMap.name}</span>
                                    {selectedTool?.id === targetMap.id && selectedTool.type === 'transition' && <MousePointerClick size={12} className="ml-auto text-emerald-400"/>}
                                </button>
                            ))}
                            {maps.length <= 1 && <div className="text-xs text-gray-600 italic px-2">Create another map to link to.</div>}
                        </div>
                    </div>
                 </div>
              </div>
            </div>

            {/* Map Canvas */}
            <div className="flex-1 bg-gray-900 rounded-xl border-[4px] border-gray-800 shadow-2xl overflow-hidden relative group">
                {currentMap && currentMap.backgroundSrc ? (
                   <div 
                      ref={mapContainerRef}
                      onClick={handleMapClick}
                      className="relative w-full h-full cursor-crosshair"
                   >
                      <img 
                        src={currentMap.backgroundSrc} 
                        alt="World Map" 
                        className="w-full h-full object-contain bg-black select-none pointer-events-none" 
                      />

                      {/* Render Spots */}
                      {currentMap.spots.map(spot => {
                         if (spot.type === 'scene') {
                             const char = characters.find(c => c.id === spot.characterId);
                             if(!char) return null;
                             return (
                                <div 
                                  key={spot.id}
                                  className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin"
                                  style={{ left: `${spot.x}%`, top: `${spot.y}%` }}
                                >
                                   {/* Sprite Render */}
                                   {char.mapSpriteSrc ? (
                                       <div className="w-12 h-12 relative drop-shadow-lg transition hover:scale-110">
                                           <img src={char.mapSpriteSrc} alt={char.name} className="w-full h-full object-contain" />
                                       </div>
                                   ) : (
                                       <div className="w-4 h-4 rounded-full border border-white shadow-sm mb-1" style={{ backgroundColor: char.rpgColor }} />
                                   )}

                                   <span className="bg-black/70 text-[10px] px-2 rounded text-white whitespace-nowrap mt-1 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none backdrop-blur-sm">{char.name}</span>
                                   <button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110">
                                     <Trash2 size={12} />
                                   </button>
                                </div>
                             )
                         } else {
                             // Transition Spot
                             const target = maps.find(m => m.id === spot.targetMapId);
                             return (
                                <div 
                                  key={spot.id}
                                  className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin"
                                  style={{ left: `${spot.x}%`, top: `${spot.y}%` }}
                                >
                                   {/* Transition Icon (Visible in Editor) */}
                                   <div className="w-8 h-8 rounded-full bg-emerald-500/50 border-2 border-emerald-400 flex items-center justify-center shadow-lg hover:scale-110 transition">
                                       <Waypoints size={16} className="text-white" />
                                   </div>

                                   <span className="bg-emerald-900/90 text-[10px] px-2 rounded text-emerald-100 whitespace-nowrap mt-1 opacity-100 transition-opacity pointer-events-none backdrop-blur-sm border border-emerald-700">Go to: {target?.name || 'Unknown'}</span>
                                   <button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110">
                                     <Trash2 size={12} />
                                   </button>
                                </div>
                             )
                         }
                      })}
                   </div>
                ) : (
                  <div className="w-full h-full flex flex-col items-center justify-center text-gray-600 gap-4">
                    {currentMap ? (
                        <>
                            <MapIcon size={48} opacity={0.5} />
                            <p>Upload a background for {currentMap.name}.</p>
                        </>
                    ) : (
                        <p>No map selected.</p>
                    )}
                  </div>
                )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export interface Character {
  id: string;
  name: string;
  defaultDescription: string;
  imageSrc: string | null; // Portrait for VN (Large)
  mapSpriteSrc: string | null; // Sprite for Map (Small/Icon)
  rpgColor: string; // Fallback Hex color
}

export interface SceneCharacterConfig {
  characterId: string;
  roleInScene: string; // Specific behavior/goal for this scene
}

export interface UnlockReward {
  type: 'scene' | 'transition';
  targetId: string; // Scene ID or Target Map ID
}

export interface Scene {
  id: string;
  name: string;
  backgroundSrc: string | null; // Local object URL
  description: string; // The scenario setup
  goal: string; // The win condition to move to next scene
  characters: SceneCharacterConfig[];
  unlocks?: UnlockReward[]; // New: List of things unlocked when this scene is won
}

export interface MapSpot {
  id: string;
  x: number; // Percentage 0-100
  y: number; // Percentage 0-100
  type: 'scene' | 'transition';

  // If type === 'scene'
  characterId?: string;

  // If type === 'transition'
  targetMapId?: string;
}

export interface WorldMap {
  id: string;
  name: string;
  backgroundSrc: string | null;
  spots: MapSpot[];
}

export interface ChatMessage {
  sender: 'user' | 'model' | 'system';
  characterId?: string; // If model, which character?
  text: string;
  timestamp: number;
}

export interface GameState {
  currentSceneIndex: number; // Used inside VN Mode
  history: ChatMessage[];
  isProcessing: boolean;
  gameOver: boolean;
}

export interface AIResponse {
  characterResponses: {
    characterId: string;
    text: string;
  }[];
  sceneGoalReached: boolean;
  sceneTransitionReason?: string;
}

export interface RPGState {
  currentMapId: string;
  completedSceneIds: string[];
  unlockedIds: string[]; // IDs of Scenes or Maps that have been unlocked
  ongoingScenes: Record<string, ChatMessage[]>; // New: Stores history for incomplete scenes { sceneId: history[] }
}

export interface GameSaveData {
  rpgState: RPGState;
  vnState: GameState | null; // Null if saved while on map
  timestamp: number;
}

import React, { useState, useEffect } from 'react';
import { Editor } from './components/Editor';
import { Player } from './components/Player';
import { RPGWorld } from './components/RPGWorld';
import { Character, Scene, GameSaveData, RPGState, WorldMap, ChatMessage } from './types';
import { getItem, setItem } from './utils/db';

// Default Data for quick start
const DEFAULT_CHARS: Character[] = [
  { 
    id: '1', 
    name: 'Aiko', 
    defaultDescription: 'A cheerful and curious android girl who loves learning about humans.', 
    imageSrc: null,
    mapSpriteSrc: null,
    rpgColor: '#f472b6' // Pink
  },
  { 
    id: '2', 
    name: 'Kael', 
    defaultDescription: 'A grumpy but skilled mechanic who fixes robots.', 
    imageSrc: null,
    mapSpriteSrc: null,
    rpgColor: '#60a5fa' // Blue
  }
];

const DEFAULT_SCENES: Scene[] = [
  {
    id: 's1',
    name: 'The Workshop',
    backgroundSrc: null,
    description: 'A cluttered workshop filled with robot parts. Kael is working on a workbench. Aiko is watching closely.',
    goal: 'Convince Kael to fix your broken radio.',
    characters: [
      { characterId: '1', roleInScene: 'Curious onlooker, wants to help but is clumsy.' },
      { characterId: '2', roleInScene: 'Busy, easily annoyed, does not want to be disturbed.' }
    ],
    unlocks: []
  }
];

const DEFAULT_MAPS: WorldMap[] = [
  {
    id: 'map1',
    name: 'Main City',
    backgroundSrc: null,
    spots: [
      { id: 'spot1', type: 'scene', characterId: '1', x: 40, y: 50 },
      { id: 'spot2', type: 'scene', characterId: '2', x: 60, y: 30 }
    ]
  }
];

const PROJECT_STORAGE_KEY = 'vn_creator_project';
const GAME_SAVE_KEY = 'vn_creator_savegame';

const App: React.FC = () => {
  const [mode, setMode] = useState<'edit' | 'rpg' | 'vn'>('edit');

  // Data State
  const [characters, setCharacters] = useState<Character[]>(DEFAULT_CHARS);
  const [scenes, setScenes] = useState<Scene[]>(DEFAULT_SCENES);
  const [maps, setMaps] = useState<WorldMap[]>(DEFAULT_MAPS);

  // Game Play State
  const [rpgState, setRpgState] = useState<RPGState>({ 
    currentMapId: 'map1', 
    completedSceneIds: [],
    unlockedIds: [],
    ongoingScenes: {}
  });

  const [activeSceneIndex, setActiveSceneIndex] = useState<number>(-1);
  const [vnHistory, setVnHistory] = useState<ChatMessage[]>([]); 

  const [hasSaveGame, setHasSaveGame] = useState(false);

  // Check for save game on mount and migrate from LocalStorage if needed
  useEffect(() => {
    const initLoad = async () => {
        // 1. Check for Save Game
        const savedGame = await getItem<GameSaveData>(GAME_SAVE_KEY);
        if (savedGame) {
            setHasSaveGame(true);
        } else {
            // Check legacy local storage for save game
            const lsSave = localStorage.getItem(GAME_SAVE_KEY);
            if (lsSave) {
                setHasSaveGame(true);
            }
        }

        // 2. Load Project Data (Try IndexedDB first)
        let data: any = await getItem(PROJECT_STORAGE_KEY);

        // 3. Fallback/Migrate from LocalStorage if IDB is empty
        if (!data) {
            const lsProject = localStorage.getItem(PROJECT_STORAGE_KEY);
            if (lsProject) {
                try {
                    data = JSON.parse(lsProject);
                    // Migrate to IDB to fix quota issues in future
                    await setItem(PROJECT_STORAGE_KEY, data);
                    // Clear LS to free up immediate space
                    localStorage.removeItem(PROJECT_STORAGE_KEY);
                    console.log("Migrated project from LocalStorage to IndexedDB");
                } catch (e) {
                    console.error("Failed to parse legacy local storage", e);
                }
            }
        }

        // Apply Data
        if (data) {
            if (data.characters) setCharacters(data.characters);
            if (data.scenes) setScenes(data.scenes);

            // Migration check: if old data had 'mapConfig' (single object), convert to array
            if (data.mapConfig && !data.maps) {
                setMaps([{ ...data.mapConfig, id: 'map1', name: 'Default Map' }]);
            } else if (data.maps) {
                setMaps(data.maps);
            }
        }
    };
    initLoad();
  }, []);

  // 1. Quick Save to Browser Storage (IndexedDB)
  const handleQuickSave = async () => {
    const data = { characters, scenes, maps };
    await setItem(PROJECT_STORAGE_KEY, data);
    return true;
  };

  // 2. Export to File (Download)
  const handleExportProject = () => {
    const data = { characters, scenes, maps };
    const jsonString = JSON.stringify(data, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const href = URL.createObjectURL(blob);

    const link = document.createElement('a');
    link.href = href;
    link.download = `vn-project-${new Date().toISOString().slice(0,10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(href);
  };

  // 3. Import from File (Upload)
  const handleImportProject = (file: File) => {
    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const content = e.target?.result as string;
        const data = JSON.parse(content);

        if (data.characters) setCharacters(data.characters);
        if (data.scenes) setScenes(data.scenes);
        if (data.maps) setMaps(data.maps);
        else if (data.mapConfig) setMaps([{ ...data.mapConfig, id: 'map1', name: 'Default Map' }]);

        // Save to DB immediately
        await setItem(PROJECT_STORAGE_KEY, data);
        alert("Project loaded successfully!");
      } catch (error) {
        console.error("Import failed", error);
        alert("Failed to load project file. Invalid JSON.");
      }
    };
    reader.readAsText(file);
  };

  const handleStartNewGame = () => {
    setRpgState({ 
        currentMapId: maps[0].id, 
        completedSceneIds: [], 
        unlockedIds: [],
        ongoingScenes: {} 
    });
    setVnHistory([]);
    setActiveSceneIndex(-1);
    setMode('rpg');
  };

  const handleContinueGame = async () => {
    // Try IDB first
    let savedGame = await getItem<GameSaveData>(GAME_SAVE_KEY);

    // Fallback to LS
    if (!savedGame) {
        const lsSave = localStorage.getItem(GAME_SAVE_KEY);
        if (lsSave) {
            try {
                savedGame = JSON.parse(lsSave);
            } catch(e) {}
        }
    }

    if (savedGame) {
      try {
        // Ensure map ID exists, fallback to first if deleted
        const safeMapId = maps.find(m => m.id === savedGame!.rpgState.currentMapId) ? savedGame!.rpgState.currentMapId : maps[0].id;

        setRpgState({ 
            ...savedGame.rpgState, 
            currentMapId: safeMapId,
            unlockedIds: savedGame.rpgState.unlockedIds || [], // Default for migration
            ongoingScenes: savedGame.rpgState.ongoingScenes || {} // Default for migration
        });

        if (savedGame.vnState) {
          setActiveSceneIndex(savedGame.vnState.currentSceneIndex);
          setVnHistory(savedGame.vnState.history);
          setMode('vn');
        } else {
          setMode('rpg');
        }
      } catch (e) {
        console.error("Corrupt save file");
        handleStartNewGame();
      }
    }
  };

  const handleSaveGameInternal = async (updatedRpgState: RPGState, vnState: any | null) => {
      const saveData: GameSaveData = {
        rpgState: updatedRpgState,
        vnState: vnState,
        timestamp: Date.now()
      };
      await setItem(GAME_SAVE_KEY, saveData);
      setHasSaveGame(true);
      return true;
  };

  const handleInteraction = (type: 'scene'|'transition', id: string) => {
      if (type === 'transition') {
          // Change Map
          if (maps.find(m => m.id === id)) {
              setRpgState(prev => ({ ...prev, currentMapId: id }));
          }
      } else {
          // Trigger Scene
          const charId = id;
          const availableScenes = scenes.filter(s => s.characters.some(c => c.characterId === charId));

          const playableScene = availableScenes.find(s => {
              const isCompleted = rpgState.completedSceneIds.includes(s.id);
              if (isCompleted) return false;

              // Check if it's locked by dependency
              const isLockedByOthers = scenes.some(other => other.unlocks?.some(u => u.type === 'scene' && u.targetId === s.id));
              const isUnlocked = rpgState.unlockedIds.includes(s.id);

              return !isLockedByOthers || isUnlocked;
          });

          if (playableScene) {
            const realIndex = scenes.findIndex(s => s.id === playableScene.id);
            setActiveSceneIndex(realIndex);

            // Resume history if exists, else start fresh
            const existingHistory = rpgState.ongoingScenes?.[playableScene.id] || [];
            setVnHistory(existingHistory);

            setMode('vn');
          } else {
            alert("No available scenarios for this character right now.");
          }
      }
  };

  const handleSceneExit = async (completed: boolean, history: ChatMessage[]) => {
      const activeScene = scenes[activeSceneIndex];
      const sceneId = activeScene.id;

      let newState = { ...rpgState };

      if (completed) {
          // 1. Mark as completed
          const newCompletedIds = [...rpgState.completedSceneIds, sceneId];

          // 2. Remove from ongoing scenes (clean up)
          const { [sceneId]: _, ...remainingScenes } = newState.ongoingScenes || {};

          // 3. Process Unlocks
          const newUnlockedIds = [...rpgState.unlockedIds];
          if (activeScene.unlocks) {
              activeScene.unlocks.forEach(reward => {
                  if (!newUnlockedIds.includes(reward.targetId)) {
                      newUnlockedIds.push(reward.targetId);
                  }
              });
          }

          newState = { 
              ...newState, 
              completedSceneIds: newCompletedIds,
              unlockedIds: newUnlockedIds,
              ongoingScenes: remainingScenes
          };

      } else {
          // 1. Just PAUSE: Save history to ongoingScenes
          newState = {
              ...newState,
              ongoingScenes: {
                  ...newState.ongoingScenes,
                  [sceneId]: history
              }
          };
      }

      setRpgState(newState);
      await handleSaveGameInternal(newState, null); // Save to disk
      setMode('rpg');
  };

  const activeMap = maps.find(m => m.id === rpgState.currentMapId) || maps[0];

  return (
    <div className="min-h-screen bg-gray-900 text-gray-100 font-sans selection:bg-indigo-500 selection:text-white">
      {mode === 'edit' && (
        <Editor 
          characters={characters}
          scenes={scenes}
          maps={maps}
          onUpdateCharacters={setCharacters}
          onUpdateScenes={setScenes}
          onUpdateMaps={setMaps}
          onPlay={handleStartNewGame}
          onQuickSave={handleQuickSave}
          onExportProject={handleExportProject}
          onImportProject={handleImportProject}
          hasSaveGame={hasSaveGame}
          onContinueGame={handleContinueGame}
        />
      )}

      {mode === 'rpg' && (
        <RPGWorld 
          characters={characters}
          mapConfig={activeMap}
          maps={maps}
          scenes={scenes}
          initialState={rpgState}
          onInteraction={handleInteraction}
          onSave={async (updatedRpgState) => {
             setRpgState(updatedRpgState);
             await handleSaveGameInternal(updatedRpgState, null);
             alert("Game Saved!");
          }}
          onExit={() => setMode('edit')}
        />
      )}

      {mode === 'vn' && activeSceneIndex >= 0 && (
        <Player 
          scenes={scenes}
          characters={characters}
          initialState={{
            currentSceneIndex: activeSceneIndex,
            history: vnHistory, // Passed from App state now
            timestamp: 0,
            rpgState: rpgState, 
            vnState: null
          }}
          onExit={handleSceneExit}
          onSave={async (vnState) => {
             await handleSaveGameInternal(rpgState, vnState);
             return true;
          }}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Scene, Character, ChatMessage, GameState, GameSaveData } from '../types';
import { generateGameTurn } from '../services/geminiService';
import { Button } from './ui/Button';
import { ArrowLeft, RefreshCw, Send, Save, Map, CheckCircle, Play } from 'lucide-react';

interface PlayerProps {
  scenes: Scene[];
  characters: Character[];
  initialState: any; // Using any loosely here because we are mixing save data types
  onExit: (success: boolean, history: ChatMessage[]) => void; 
  onSave: (vnState: any) => Promise<boolean>;
}

export const Player: React.FC<PlayerProps> = ({ scenes, characters, initialState, onExit, onSave }) => {
  const [state, setState] = useState<GameState>({
    currentSceneIndex: initialState?.currentSceneIndex || 0,
    history: initialState?.history || [],
    isProcessing: false,
    gameOver: false,
  });
  const [userInput, setUserInput] = useState('');

  // Track goal reached state locally to show UI elements
  const [goalReached, setGoalReached] = useState(false);
  const [goalReason, setGoalReason] = useState<string | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);
  const [isSaving, setIsSaving] = useState(false);

  const currentScene = scenes[state.currentSceneIndex];
  const activeCharacters = currentScene?.characters
    .map(sc => characters.find(c => c.id === sc.characterId))
    .filter((c): c is Character => !!c) || [];

  // Auto-scroll chat
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [state.history]);

  // Initial greeting from System/Narrator when scene starts (only if history is empty)
  useEffect(() => {
    if (!currentScene || state.history.length > 0) return;
    setState(prev => ({
      ...prev,
      history: [{
        sender: 'system',
        text: currentScene.description,
        timestamp: Date.now(),
      }]
    }));
  }, [state.currentSceneIndex, currentScene]);

  const handleSendMessage = async () => {
    if (!userInput.trim() || state.isProcessing || !currentScene) return;

    const newMessage: ChatMessage = {
      sender: 'user',
      text: userInput,
      timestamp: Date.now(),
    };

    // Optimistic update
    setState(prev => ({
      ...prev,
      history: [...prev.history, newMessage],
      isProcessing: true,
    }));
    setUserInput('');

    try {
      const aiResponse = await generateGameTurn(
        newMessage.text,
        state.history, // send previous history
        currentScene,
        characters
      );

      const newMessages: ChatMessage[] = aiResponse.characterResponses.map(resp => ({
        sender: 'model',
        characterId: resp.characterId,
        text: resp.text,
        timestamp: Date.now(),
      }));

      setState(prev => ({
        ...prev,
        history: [...prev.history, ...newMessages],
        isProcessing: false,
      }));

      if (aiResponse.sceneGoalReached) {
        setGoalReached(true);
        setGoalReason(aiResponse.sceneTransitionReason || "Objective Completed.");
      }

    } catch (error) {
      console.error("Turn error", error);
      setState(prev => ({ ...prev, isProcessing: false }));
    }
  };

  const handleManualExit = (complete: boolean) => {
      onExit(complete, state.history);
  };

  const handleSaveGame = async () => {
    if (isSaving) return;
    setIsSaving(true);

    const vnState = {
       currentSceneIndex: state.currentSceneIndex,
       history: state.history,
       isProcessing: false,
       gameOver: false
    };

    const btn = document.getElementById('save-btn');
    if (btn) btn.innerHTML = '...';

    await onSave(vnState);

    if (btn) {
      btn.innerHTML = 'Saved!';
      setTimeout(() => btn.innerHTML = '', 2000); 
      setTimeout(() => setIsSaving(false), 1500);
    } else {
        setIsSaving(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  if (!currentScene) {
    return <div className="flex items-center justify-center h-full">Scene Data Error. <button onClick={() => handleManualExit(false)}>Back</button></div>;
  }

  return (
    <div className="relative w-full h-full bg-black overflow-hidden">

      {/* Top Bar Navigation */}
      <div className="absolute top-4 left-4 right-4 z-50 flex justify-between items-start pointer-events-none">

        {/* Back / Pause Button */}
        <button 
           onClick={() => handleManualExit(false)}
           className="pointer-events-auto flex items-center gap-2 bg-black/50 hover:bg-black/70 text-gray-200 px-4 py-2 rounded-full backdrop-blur-md border border-white/10 transition-all hover:scale-105 shadow-lg group"
        >
           <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" />
           <span className="font-semibold text-sm">Resume Later</span>
        </button>

        {/* Goal Indicator */}
        <div className={`pointer-events-auto flex flex-col items-end gap-2 transition-all duration-500 ${goalReached ? 'translate-y-0 opacity-100' : '-translate-y-4 opacity-0'}`}>
           {goalReached && (
             <>
               <div className="bg-emerald-900/90 text-emerald-100 px-4 py-2 rounded-lg border border-emerald-500/50 shadow-2xl backdrop-blur-md animate-in slide-in-from-top-4">
                  <div className="flex items-center gap-2 font-bold mb-1">
                      <CheckCircle size={18} className="text-emerald-400" /> Goal Reached!
                  </div>
                  <p className="text-xs opacity-90 max-w-[200px]">{goalReason}</p>
               </div>

               <button 
                  onClick={() => handleManualExit(true)}
                  className="bg-emerald-600 hover:bg-emerald-500 text-white px-5 py-3 rounded-full font-bold shadow-lg shadow-emerald-900/50 flex items-center gap-2 animate-pulse hover:animate-none transition-all transform hover:scale-105"
               >
                  Finish Scenario <Play size={16} fill="currentColor" />
               </button>
             </>
           )}
        </div>
      </div>

      {/* Background Layer */}
      <div className="absolute inset-0 z-0">
        {currentScene.backgroundSrc ? (
          <img src={currentScene.backgroundSrc} alt="bg" className="w-full h-full object-cover" />
        ) : (
          <div className="w-full h-full bg-gradient-to-b from-gray-800 to-gray-900" />
        )}
        <div className="absolute inset-0 bg-black/30" />
      </div>

      {/* Character Layer - Positioned above the chat box */}
      <div className="absolute bottom-[36vh] left-0 right-0 z-10 flex justify-center items-end px-10 h-[60vh] pointer-events-none">
        {activeCharacters.map((char, idx) => (
          <div 
             key={char.id} 
             className="relative transition-transform duration-500 transform"
             style={{ 
                zIndex: 10 + idx, 
                marginLeft: idx > 0 ? '-50px' : '0',
                filter: state.isProcessing ? 'brightness(0.7)' : 'brightness(1)' 
             }}
          >
            {char.imageSrc ? (
              <img 
                src={char.imageSrc} 
                alt={char.name} 
                className="max-h-[60vh] w-auto object-contain drop-shadow-2xl"
              />
            ) : (
               // Placeholder Shape
               <div className="w-64 h-96 rounded-t-full border-4 border-white/20 flex items-center justify-center text-white font-bold text-2xl shadow-2xl" style={{ backgroundColor: char.rpgColor || '#4b5563' }}>
                 {char.name[0]}
               </div>
            )}
            <div className="absolute bottom-4 left-0 right-0 text-center">
               <span className="bg-black/60 text-white px-2 py-1 rounded text-sm backdrop-blur-sm">{char.name}</span>
            </div>
          </div>
        ))}
      </div>

      {/* UI Layer - Chat Box */}
      <div className="absolute bottom-0 left-0 right-0 z-20 p-4 md:p-8 bg-gradient-to-t from-black via-black/90 to-transparent pt-24">
        <div className="max-w-4xl mx-auto bg-black/80 border border-gray-700 rounded-xl backdrop-blur-md shadow-2xl overflow-hidden flex flex-col h-[35vh]">

          {/* Chat History */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4">
            {state.history.map((msg, i) => {
              const char = characters.find(c => c.id === msg.characterId);
              const isUser = msg.sender === 'user';
              const isSystem = msg.sender === 'system';

              if (isSystem) return (
                <div key={i} className="text-center text-yellow-500 italic text-sm my-4 px-8">
                  {msg.text}
                </div>
              );

              return (
                <div key={i} className={`flex flex-col ${isUser ? 'items-end' : 'items-start'}`}>
                   <div className="text-xs text-gray-400 mb-1 px-1">
                     {isUser ? 'You' : (char?.name || 'Unknown')}
                   </div>
                   <div className={`px-4 py-2 rounded-lg max-w-[85%] leading-relaxed ${
                     isUser 
                       ? 'bg-indigo-600 text-white rounded-br-none' 
                       : 'bg-gray-800 text-gray-100 rounded-bl-none border border-gray-700'
                   }`}>
                     {msg.text}
                   </div>
                </div>
              );
            })}
            {state.isProcessing && (
              <div className="flex items-center gap-2 text-gray-500 text-sm px-4">
                <RefreshCw className="animate-spin" size={14} /> AI is thinking...
              </div>
            )}

            {/* System Message inside chat when goal reached */}
            {goalReached && (
                <div className="text-center my-4 animate-in fade-in zoom-in duration-300">
                    <span className="bg-emerald-900/50 text-emerald-300 border border-emerald-600/50 px-3 py-1 rounded-full text-xs font-bold">
                        ★ Objective Complete
                    </span>
                </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-4 border-t border-gray-700 bg-gray-900/50 flex gap-3">
             <button 
               id="save-btn"
               onClick={handleSaveGame} 
               disabled={isSaving}
               className="bg-gray-700 hover:bg-gray-600 disabled:opacity-50 text-gray-300 p-3 rounded-lg transition-colors flex items-center justify-center min-w-[50px]"
               title="Save Current Progress"
             >
               {!isSaving && <Save size={20} />}
             </button>

             <input
               type="text"
               className="flex-1 bg-gray-800 border border-gray-600 rounded-lg px-4 py-3 text-white focus:border-indigo-500 outline-none transition-colors"
               placeholder={goalReached ? "You can keep chatting or leave..." : "What do you say/do?"}
               value={userInput}
               onChange={(e) => setUserInput(e.target.value)}
               onKeyDown={handleKeyDown}
               autoFocus
               disabled={state.isProcessing}
             />
             <button 
                onClick={handleSendMessage}
                disabled={!userInput.trim() || state.isProcessing}
                className="bg-indigo-600 hover:bg-indigo-500 disabled:bg-gray-700 disabled:cursor-not-allowed text-white p-3 rounded-lg transition-colors"
             >
               <Send size={20} />
             </button>
          </div>

        </div>

        {/* Current Goal Display (Hide if reached to reduce clutter, or keep?) - Keeping but dimming */}
        {!goalReached && (
            <div className="absolute top-4 right-4 md:right-12 bg-black/60 backdrop-blur text-xs text-green-400 px-3 py-1 rounded border border-green-900 pointer-events-none">
            Objective: {currentScene.goal}
            </div>
        )}
      </div>
    </div>
  );
};

export interface Character {
  id: string;
  name: string;
  defaultDescription: string;
  imageSrc: string | null; // Portrait for VN (Large)
  mapSpriteSrc: string | null; // Sprite for Map (Small/Icon)
  rpgColor: string; // Fallback Hex color
}

export interface SceneCharacterConfig {
  characterId: string;
  roleInScene: string; // Specific behavior/goal for this scene
}

export interface UnlockReward {
  type: 'scene' | 'transition';
  targetId: string; // Scene ID or Target Map ID
}

export interface Scene {
  id: string;
  name: string;
  backgroundSrc: string | null; // Local object URL
  description: string; // The scenario setup
  goal: string; // The win condition to move to next scene
  characters: SceneCharacterConfig[];
  unlocks?: UnlockReward[]; // List of things unlocked when this scene is won

  // New: Visual override for the map
  mapIconSrc?: string | null; 
}

export interface MapSpot {
  id: string;
  x: number; // Percentage 0-100
  y: number; // Percentage 0-100
  type: 'scene' | 'transition';

  // If type === 'scene'
  sceneId?: string; // DIRECT link to a specific scene

  // Legacy/Fallback (optional, can be removed later)
  characterId?: string; 

  // If type === 'transition'
  targetMapId?: string;
}

export interface WorldMap {
  id: string;
  name: string;
  backgroundSrc: string | null;
  spots: MapSpot[];
}

export interface ChatMessage {
  sender: 'user' | 'model' | 'system';
  characterId?: string; // If model, which character?
  text: string;
  timestamp: number;
}

export interface GameState {
  currentSceneIndex: number; // Used inside VN Mode
  history: ChatMessage[];
  isProcessing: boolean;
  gameOver: boolean;
}

export interface AIResponse {
  characterResponses: {
    characterId: string;
    text: string;
  }[];
  sceneGoalReached: boolean;
  sceneTransitionReason?: string;
}

export interface RPGState {
  currentMapId: string;
  completedSceneIds: string[];
  unlockedIds: string[]; // IDs of Scenes or Maps that have been unlocked
  ongoingScenes: Record<string, ChatMessage[]>; // Stores history for incomplete scenes { sceneId: history[] }
}

export interface GameSaveData {
  rpgState: RPGState;
  vnState: GameState | null; // Null if saved while on map
  timestamp: number;
}

import React, { useState, useEffect } from 'react';
import { Editor } from './components/Editor';
import { Player } from './components/Player';
import { RPGWorld } from './components/RPGWorld';
import { Character, Scene, GameSaveData, RPGState, WorldMap, ChatMessage } from './types';
import { getItem, setItem } from './utils/db';

// Default Data for quick start
const DEFAULT_CHARS: Character[] = [
  { 
    id: '1', 
    name: 'Aiko', 
    defaultDescription: 'A cheerful and curious android girl who loves learning about humans.', 
    imageSrc: null,
    mapSpriteSrc: null,
    rpgColor: '#f472b6' // Pink
  },
  { 
    id: '2', 
    name: 'Kael', 
    defaultDescription: 'A grumpy but skilled mechanic who fixes robots.', 
    imageSrc: null,
    mapSpriteSrc: null,
    rpgColor: '#60a5fa' // Blue
  }
];

const DEFAULT_SCENES: Scene[] = [
  {
    id: 's1',
    name: 'The Workshop',
    backgroundSrc: null,
    description: 'A cluttered workshop filled with robot parts. Kael is working on a workbench. Aiko is watching closely.',
    goal: 'Convince Kael to fix your broken radio.',
    characters: [
      { characterId: '1', roleInScene: 'Curious onlooker, wants to help but is clumsy.' },
      { characterId: '2', roleInScene: 'Busy, easily annoyed, does not want to be disturbed.' }
    ],
    unlocks: []
  }
];

const DEFAULT_MAPS: WorldMap[] = [
  {
    id: 'map1',
    name: 'Main City',
    backgroundSrc: null,
    spots: [
      // Updated to use sceneId directly
      { id: 'spot1', type: 'scene', sceneId: 's1', x: 50, y: 50 },
    ]
  }
];

const PROJECT_STORAGE_KEY = 'vn_creator_project';
const GAME_SAVE_KEY = 'vn_creator_savegame';

const App: React.FC = () => {
  const [mode, setMode] = useState<'edit' | 'rpg' | 'vn'>('edit');

  // Data State
  const [characters, setCharacters] = useState<Character[]>(DEFAULT_CHARS);
  const [scenes, setScenes] = useState<Scene[]>(DEFAULT_SCENES);
  const [maps, setMaps] = useState<WorldMap[]>(DEFAULT_MAPS);

  // Game Play State
  const [rpgState, setRpgState] = useState<RPGState>({ 
    currentMapId: 'map1', 
    completedSceneIds: [],
    unlockedIds: [],
    ongoingScenes: {}
  });

  const [activeSceneIndex, setActiveSceneIndex] = useState<number>(-1);
  const [vnHistory, setVnHistory] = useState<ChatMessage[]>([]); 

  const [hasSaveGame, setHasSaveGame] = useState(false);

  // Check for save game on mount and migrate from LocalStorage if needed
  useEffect(() => {
    const initLoad = async () => {
        // 1. Check for Save Game
        const savedGame = await getItem<GameSaveData>(GAME_SAVE_KEY);
        if (savedGame) {
            setHasSaveGame(true);
        } else {
            // Check legacy local storage for save game
            const lsSave = localStorage.getItem(GAME_SAVE_KEY);
            if (lsSave) {
                setHasSaveGame(true);
            }
        }

        // 2. Load Project Data (Try IndexedDB first)
        let data: any = await getItem(PROJECT_STORAGE_KEY);

        // 3. Fallback/Migrate from LocalStorage if IDB is empty
        if (!data) {
            const lsProject = localStorage.getItem(PROJECT_STORAGE_KEY);
            if (lsProject) {
                try {
                    data = JSON.parse(lsProject);
                    await setItem(PROJECT_STORAGE_KEY, data);
                    localStorage.removeItem(PROJECT_STORAGE_KEY);
                } catch (e) {
                    console.error("Failed to parse legacy local storage", e);
                }
            }
        }

        // Apply Data
        if (data) {
            if (data.characters) setCharacters(data.characters);
            if (data.scenes) setScenes(data.scenes);

            // Migration check
            if (data.mapConfig && !data.maps) {
                setMaps([{ ...data.mapConfig, id: 'map1', name: 'Default Map' }]);
            } else if (data.maps) {
                setMaps(data.maps);
            }
        }
    };
    initLoad();
  }, []);

  // 1. Quick Save to Browser Storage (IndexedDB)
  const handleQuickSave = async () => {
    const data = { characters, scenes, maps };
    await setItem(PROJECT_STORAGE_KEY, data);
    return true;
  };

  // 2. Export to File (Download)
  const handleExportProject = () => {
    const data = { characters, scenes, maps };
    const jsonString = JSON.stringify(data, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const href = URL.createObjectURL(blob);

    const link = document.createElement('a');
    link.href = href;
    link.download = `vn-project-${new Date().toISOString().slice(0,10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(href);
  };

  // 3. Import from File (Upload)
  const handleImportProject = (file: File) => {
    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const content = e.target?.result as string;
        const data = JSON.parse(content);

        if (data.characters) setCharacters(data.characters);
        if (data.scenes) setScenes(data.scenes);
        if (data.maps) setMaps(data.maps);
        else if (data.mapConfig) setMaps([{ ...data.mapConfig, id: 'map1', name: 'Default Map' }]);

        // Save to DB immediately
        await setItem(PROJECT_STORAGE_KEY, data);
        alert("Project loaded successfully!");
      } catch (error) {
        console.error("Import failed", error);
        alert("Failed to load project file. Invalid JSON.");
      }
    };
    reader.readAsText(file);
  };

  const handleStartNewGame = () => {
    setRpgState({ 
        currentMapId: maps[0].id, 
        completedSceneIds: [], 
        unlockedIds: [],
        ongoingScenes: {} 
    });
    setVnHistory([]);
    setActiveSceneIndex(-1);
    setMode('rpg');
  };

  const handleContinueGame = async () => {
    // Try IDB first
    let savedGame = await getItem<GameSaveData>(GAME_SAVE_KEY);

    // Fallback to LS
    if (!savedGame) {
        const lsSave = localStorage.getItem(GAME_SAVE_KEY);
        if (lsSave) {
            try {
                savedGame = JSON.parse(lsSave);
            } catch(e) {}
        }
    }

    if (savedGame) {
      try {
        // Ensure map ID exists, fallback to first if deleted
        const safeMapId = maps.find(m => m.id === savedGame!.rpgState.currentMapId) ? savedGame!.rpgState.currentMapId : maps[0].id;

        setRpgState({ 
            ...savedGame.rpgState, 
            currentMapId: safeMapId,
            unlockedIds: savedGame.rpgState.unlockedIds || [], 
            ongoingScenes: savedGame.rpgState.ongoingScenes || {} 
        });

        if (savedGame.vnState) {
          setActiveSceneIndex(savedGame.vnState.currentSceneIndex);
          setVnHistory(savedGame.vnState.history);
          setMode('vn');
        } else {
          setMode('rpg');
        }
      } catch (e) {
        console.error("Corrupt save file");
        handleStartNewGame();
      }
    }
  };

  const handleSaveGameInternal = async (updatedRpgState: RPGState, vnState: any | null) => {
      const saveData: GameSaveData = {
        rpgState: updatedRpgState,
        vnState: vnState,
        timestamp: Date.now()
      };
      await setItem(GAME_SAVE_KEY, saveData);
      setHasSaveGame(true);
      return true;
  };

  const handleInteraction = (type: 'scene'|'transition', id: string) => {
      if (type === 'transition') {
          // Change Map
          if (maps.find(m => m.id === id)) {
              setRpgState(prev => ({ ...prev, currentMapId: id }));
          }
      } else {
          // Trigger Scene Direct Link
          const sceneId = id; 
          const scene = scenes.find(s => s.id === sceneId);

          if (!scene) {
             console.error("Scene not found:", sceneId);
             return;
          }

          const realIndex = scenes.findIndex(s => s.id === scene.id);
          setActiveSceneIndex(realIndex);

          // Resume history if exists, else start fresh
          const existingHistory = rpgState.ongoingScenes?.[scene.id] || [];
          setVnHistory(existingHistory);

          setMode('vn');
      }
  };

  const handleSceneExit = async (completed: boolean, history: ChatMessage[]) => {
      const activeScene = scenes[activeSceneIndex];
      const sceneId = activeScene.id;

      let newState = { ...rpgState };

      if (completed) {
          // 1. Mark as completed
          const newCompletedIds = [...rpgState.completedSceneIds, sceneId];

          // 2. Remove from ongoing scenes (clean up)
          const { [sceneId]: _, ...remainingScenes } = newState.ongoingScenes || {};

          // 3. Process Unlocks
          const newUnlockedIds = [...rpgState.unlockedIds];
          if (activeScene.unlocks) {
              activeScene.unlocks.forEach(reward => {
                  if (!newUnlockedIds.includes(reward.targetId)) {
                      newUnlockedIds.push(reward.targetId);
                  }
              });
          }

          newState = { 
              ...newState, 
              completedSceneIds: newCompletedIds,
              unlockedIds: newUnlockedIds,
              ongoingScenes: remainingScenes
          };

      } else {
          // 1. Just PAUSE: Save history to ongoingScenes
          newState = {
              ...newState,
              ongoingScenes: {
                  ...newState.ongoingScenes,
                  [sceneId]: history
              }
          };
      }

      setRpgState(newState);
      await handleSaveGameInternal(newState, null); // Save to disk
      setMode('rpg');
  };

  const activeMap = maps.find(m => m.id === rpgState.currentMapId) || maps[0];

  return (
    <div className="min-h-screen bg-gray-900 text-gray-100 font-sans selection:bg-indigo-500 selection:text-white">
      {mode === 'edit' && (
        <Editor 
          characters={characters}
          scenes={scenes}
          maps={maps}
          onUpdateCharacters={setCharacters}
          onUpdateScenes={setScenes}
          onUpdateMaps={setMaps}
          onPlay={handleStartNewGame}
          onQuickSave={handleQuickSave}
          onExportProject={handleExportProject}
          onImportProject={handleImportProject}
          hasSaveGame={hasSaveGame}
          onContinueGame={handleContinueGame}
        />
      )}

      {mode === 'rpg' && (
        <RPGWorld 
          characters={characters}
          mapConfig={activeMap}
          maps={maps}
          scenes={scenes}
          initialState={rpgState}
          onInteraction={handleInteraction}
          onSave={async (updatedRpgState) => {
             setRpgState(updatedRpgState);
             await handleSaveGameInternal(updatedRpgState, null);
             alert("Game Saved!");
          }}
          onExit={() => setMode('edit')}
        />
      )}

      {mode === 'vn' && activeSceneIndex >= 0 && (
        <Player 
          scenes={scenes}
          characters={characters}
          initialState={{
            currentSceneIndex: activeSceneIndex,
            history: vnHistory, // Passed from App state now
            timestamp: 0,
            rpgState: rpgState, 
            vnState: null
          }}
          onExit={handleSceneExit}
          onSave={async (vnState) => {
             await handleSaveGameInternal(rpgState, vnState);
             return true;
          }}
        />
      )}
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';
import { Character, RPGState, WorldMap, Scene } from '../types';
import { Save, LogOut, ZoomIn, ZoomOut, Maximize, MapPin } from 'lucide-react';

interface RPGWorldProps {
  characters: Character[];
  mapConfig: WorldMap; // The CURRENT map
  maps: WorldMap[]; // For referencing target map names
  scenes: Scene[]; // Needed to check dependencies
  onInteraction: (type: 'scene'|'transition', id: string) => void;
  initialState?: RPGState;
  onSave: (state: RPGState) => void;
  onExit: () => void;
}

export const RPGWorld: React.FC<RPGWorldProps> = ({ 
  characters, 
  mapConfig,
  maps,
  scenes,
  onInteraction, 
  initialState, 
  onSave,
  onExit
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const [hoveredSpotId, setHoveredSpotId] = useState<string | null>(null);
  const [canvasDims, setCanvasDims] = useState({ width: 1000, height: 750 });

  // Camera / Viewport State
  const [zoom, setZoom] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });

  // Cache for loaded sprite images (Character sprites + Custom Scene Icons)
  const spritesRef = useRef<Record<string, HTMLImageElement>>({});
  const [spritesLoaded, setSpritesLoaded] = useState(false);

  // Preload Sprites
  useEffect(() => {
    let active = true;
    const loadSprites = async () => {
        const promises: Promise<void>[] = [];

        // 1. Character Sprites
        characters.forEach(c => {
            if (!c.mapSpriteSrc) return;
            promises.push(new Promise((resolve) => {
                const img = new Image();
                img.src = c.mapSpriteSrc!;
                img.onload = () => { if(active) spritesRef.current[c.id] = img; resolve(); };
                img.onerror = () => resolve(); 
            }));
        });

        // 2. Custom Scene Icons
        scenes.forEach(s => {
            if (!s.mapIconSrc) return;
            promises.push(new Promise((resolve) => {
                const img = new Image();
                img.src = s.mapIconSrc!;
                img.onload = () => { if(active) spritesRef.current[s.id] = img; resolve(); };
                img.onerror = () => resolve();
            }));
        });

        await Promise.all(promises);
        if (active) setSpritesLoaded(true);
    };
    loadSprites();
    return () => { active = false; };
  }, [characters, scenes]);

  // Adjust canvas dimensions to match background image AND fit to screen
  useEffect(() => {
    const applyFit = (w: number, h: number) => {
        setCanvasDims({ width: w, height: h });

        if (containerRef.current) {
            const { clientWidth, clientHeight } = containerRef.current;
            // Fit to screen with 5% padding
            const scale = Math.min(clientWidth / w, clientHeight / h) * 0.95;
            const newX = (clientWidth - w * scale) / 2;
            const newY = (clientHeight - h * scale) / 2;

            setZoom(scale);
            setOffset({ x: newX, y: newY });
        }
    };

    if (mapConfig.backgroundSrc) {
        const img = new Image();
        img.src = mapConfig.backgroundSrc;
        img.onload = () => {
            applyFit(img.naturalWidth, img.naturalHeight);
        };
    } else {
        applyFit(1000, 750);
    }
  }, [mapConfig.id, mapConfig.backgroundSrc]); // Run when map ID changes

  // --- Visibility Logic ---
  const visibleSpots = mapConfig.spots.filter(spot => {
      if (spot.type === 'transition') {
          const targetMapId = spot.targetMapId;
          if (!targetMapId) return false;

          const isLockedByDependency = scenes.some(s => s.unlocks?.some(u => u.type === 'transition' && u.targetId === targetMapId));
          const isUnlocked = initialState?.unlockedIds.includes(targetMapId);

          return !isLockedByDependency || isUnlocked;

      } else if (spot.type === 'scene') {
          // Direct Link Logic
          const sceneId = spot.sceneId;

          // Legacy Fallback (if old map data exists without sceneId)
          if (!sceneId) return false;

          const scene = scenes.find(s => s.id === sceneId);
          if (!scene) return false; // Scene deleted?

          const isCompleted = initialState?.completedSceneIds.includes(scene.id);
          if (isCompleted) return false; // Hide if done

          const isLockedByDependency = scenes.some(other => other.unlocks?.some(u => u.type === 'scene' && u.targetId === scene.id));
          const isUnlocked = initialState?.unlockedIds.includes(scene.id);

          return !isLockedByDependency || isUnlocked;
      }
      return true;
  });

  // --- Coordinate Systems ---

  const getRawMousePos = (e: React.MouseEvent | React.WheelEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    return {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top
    };
  };

  const getMousePosInWorldPercent = (rawX: number, rawY: number) => {
     const worldX = (rawX - offset.x) / zoom;
     const worldY = (rawY - offset.y) / zoom;
     return {
       x: (worldX / canvasDims.width) * 100,
       y: (worldY / canvasDims.height) * 100
     };
  };

  const checkHit = (xPct: number, yPct: number) => {
    const THRESHOLD = 4; // 4% radius

    return visibleSpots.find(spot => {
       const dx = spot.x - xPct;
       const dy = spot.y - yPct;
       return Math.sqrt(dx*dx + dy*dy) < THRESHOLD;
    });
  };

  // --- Interaction Handlers ---

  const handleWheel = (e: React.WheelEvent<HTMLCanvasElement>) => {
    e.preventDefault();
    const zoomSensitivity = 0.001;
    const delta = -e.deltaY * zoomSensitivity;
    const newZoom = Math.min(Math.max(zoom + delta, 0.1), 5); 

    if (newZoom === zoom) return;

    const mouse = getRawMousePos(e);
    const worldX = (mouse.x - offset.x) / zoom;
    const worldY = (mouse.y - offset.y) / zoom;

    const newOffsetX = mouse.x - worldX * newZoom;
    const newOffsetY = mouse.y - worldY * newZoom;

    setZoom(newZoom);
    setOffset({ x: newOffsetX, y: newOffsetY });
  };

  const handleMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (e.button === 0) {
      setIsDragging(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (isDragging) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return; 
    }

    const raw = getRawMousePos(e);
    const worldPct = getMousePosInWorldPercent(raw.x, raw.y);
    const hit = checkHit(worldPct.x, worldPct.y);

    if (hit) {
      if (hoveredSpotId !== hit.id) setHoveredSpotId(hit.id);
    } else {
      if (hoveredSpotId !== null) setHoveredSpotId(null);
    }
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const handleClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (isDragging) return;

    const raw = getRawMousePos(e);
    const worldPct = getMousePosInWorldPercent(raw.x, raw.y);
    const hit = checkHit(worldPct.x, worldPct.y);
    if (hit) {
      if (hit.type === 'scene' && hit.sceneId) {
          onInteraction('scene', hit.sceneId);
      } else if (hit.type === 'transition' && hit.targetMapId) {
          onInteraction('transition', hit.targetMapId);
      }
    }
  };

  // --- Rendering ---

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.save();

    ctx.fillStyle = '#0f172a'; 
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.translate(offset.x, offset.y);
    ctx.scale(zoom, zoom);

    // Draw World
    const bgImage = new Image();
    if (mapConfig.backgroundSrc) {
       bgImage.src = mapConfig.backgroundSrc;
    }

    const drawScene = () => {
        // Background
        if (mapConfig.backgroundSrc && bgImage.complete) {
            ctx.drawImage(bgImage, 0, 0, canvasDims.width, canvasDims.height);
        } else {
            // Fallback Grid
            ctx.fillStyle = '#1e293b';
            ctx.fillRect(0, 0, canvasDims.width, canvasDims.height);
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 2;
            ctx.strokeRect(0, 0, canvasDims.width, canvasDims.height);
        }

        const toPx = (pct: number, dim: number) => (pct / 100) * dim;

        // Render Spots
        visibleSpots.forEach(spot => {
          const cx = toPx(spot.x, canvasDims.width);
          const cy = toPx(spot.y, canvasDims.height);
          const isHovered = hoveredSpotId === spot.id;

          if (spot.type === 'scene' && spot.sceneId) {
              const scene = scenes.find(s => s.id === spot.sceneId);
              if (!scene) return;

              // Determine Sprite to use:
              // 1. Scene Custom Icon
              // 2. First Character's Icon
              // 3. Fallback

              let spriteImg: HTMLImageElement | undefined;
              let rpgColor = '#ffffff';

              if (scene.mapIconSrc) {
                  spriteImg = spritesRef.current[scene.id];
              } else if (scene.characters.length > 0) {
                  const firstChar = characters.find(c => c.id === scene.characters[0].characterId);
                  if (firstChar) {
                      spriteImg = spritesRef.current[firstChar.id];
                      rpgColor = firstChar.rpgColor;
                  }
              }

              let renderedHeight = 0;

              if (spriteImg) {
                  const ratio = spriteImg.naturalWidth / spriteImg.naturalHeight || 1;
                  const baseScale = Math.max(canvasDims.width / 1000, 0.5); 
                  const targetHeight = (isHovered ? 80 : 70) * baseScale;

                  const drawHeight = targetHeight;
                  const drawWidth = targetHeight * ratio;
                  renderedHeight = drawHeight;

                  ctx.save();
                  ctx.shadowColor = isHovered ? 'white' : 'black';
                  ctx.shadowBlur = isHovered ? 15 : 5;

                  ctx.drawImage(spriteImg, cx - drawWidth/2, cy - drawHeight/2, drawWidth, drawHeight);
                  ctx.restore();
              } else {
                  // Fallback Circle/Icon if no image
                  renderedHeight = 24;
                  ctx.fillStyle = rpgColor;
                  ctx.beginPath();
                  ctx.arc(cx, cy, isHovered ? 14 : 12, 0, Math.PI * 2);
                  ctx.fill();
                  ctx.lineWidth = 2;
                  ctx.strokeStyle = 'white';
                  ctx.stroke();

                  // Simple "?" for event
                  ctx.fillStyle = 'white';
                  ctx.font = 'bold 16px sans-serif';
                  ctx.textAlign = 'center';
                  ctx.textBaseline = 'middle';
                  ctx.fillText('!', cx, cy);
              }

              // Name Tag
              if (isHovered) {
                ctx.save();
                const textScale = Math.max(1 / zoom, 0.5); 
                ctx.translate(cx, cy - (renderedHeight / 2) - 14 * textScale);
                ctx.scale(textScale, textScale);

                ctx.fillStyle = 'rgba(0,0,0,0.8)';
                ctx.font = 'bold 16px sans-serif';
                const textW = ctx.measureText(scene.name).width;

                ctx.fillRect(-textW/2 - 8, -20, textW + 16, 28);
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.fillText(scene.name, 0, 0);
                ctx.restore();
              }

          } else if (spot.type === 'transition') {
              // Visible Waypoint Marker
              const radius = 16;
              const pulseColor = 'rgba(52, 211, 153, 0.6)';

              if (isHovered) {
                  const time = Date.now() / 300;
                  const pulse = Math.sin(time) * 4 + radius + 4;
                  ctx.beginPath();
                  ctx.arc(cx, cy, pulse, 0, Math.PI * 2);
                  ctx.strokeStyle = pulseColor;
                  ctx.lineWidth = 2;
                  ctx.stroke();
              }

              ctx.beginPath();
              ctx.arc(cx, cy, radius, 0, Math.PI * 2);
              ctx.fillStyle = 'rgba(16, 185, 129, 0.9)'; 
              ctx.fill();

              ctx.strokeStyle = '#6ee7b7'; 
              ctx.lineWidth = 2;
              ctx.stroke();

              ctx.beginPath();
              ctx.arc(cx, cy, 6, 0, Math.PI * 2);
              ctx.fillStyle = '#ffffff';
              ctx.fill();

              if (isHovered) {
                  ctx.save();

                  const targetMapName = maps.find(m => m.id === spot.targetMapId)?.name || 'Unknown Area';
                  const text = `Travel to ${targetMapName}`;

                  const textScale = Math.max(1 / zoom, 0.5); 
                  ctx.translate(cx, cy - 30 * textScale);
                  ctx.scale(textScale, textScale);

                  ctx.fillStyle = 'rgba(0,0,0,0.8)';
                  ctx.font = 'bold 14px sans-serif';
                  const textW = ctx.measureText(text).width;

                  ctx.fillRect(-textW/2 - 8, -18, textW + 16, 26);
                  ctx.fillStyle = '#6ee7b7'; 
                  ctx.textAlign = 'center';
                  ctx.fillText(text, 0, 0);

                  ctx.restore();
              }
          }
        });
    }

    if (bgImage.complete || !mapConfig.backgroundSrc) {
        drawScene();
    } else {
        bgImage.onload = drawScene;
    }

    ctx.restore();

  }, [mapConfig, characters, scenes, hoveredSpotId, spritesLoaded, canvasDims, zoom, offset, visibleSpots]);

  const handleManualSave = () => {
    onSave({ 
        currentMapId: mapConfig.id,
        completedSceneIds: initialState?.completedSceneIds || [],
        unlockedIds: initialState?.unlockedIds || [],
        ongoingScenes: initialState?.ongoingScenes || {}
    });
  };

  const handleZoomIn = () => setZoom(z => Math.min(z + 0.2, 5));
  const handleZoomOut = () => setZoom(z => Math.max(z - 0.2, 0.1));
  const handleResetView = () => {
        if (containerRef.current) {
            const { clientWidth, clientHeight } = containerRef.current;
            const w = canvasDims.width;
            const h = canvasDims.height;
            const scale = Math.min(clientWidth / w, clientHeight / h) * 0.95;
            const newX = (clientWidth - w * scale) / 2;
            const newY = (clientHeight - h * scale) / 2;
            setZoom(scale);
            setOffset({ x: newX, y: newY });
        }
  };

  return (
    <div className="relative w-full h-full bg-gray-950 flex flex-col overflow-hidden">
      {/* HUD */}
      <div className="absolute top-4 left-4 z-10 pointer-events-none">
          <div className="bg-gray-900/80 p-3 rounded-xl border border-gray-700 backdrop-blur-sm shadow-xl pointer-events-auto">
            <h1 className="text-xl font-bold text-indigo-400">{mapConfig.name.toUpperCase()}</h1>
            <p className="text-xs text-gray-400 mt-1">Drag to Pan • Wheel to Zoom</p>
          </div>
      </div>

      {/* Main Canvas Container */}
      <div 
        ref={containerRef}
        className="flex-1 w-full h-full relative overflow-hidden bg-[#0f172a] cursor-grab active:cursor-grabbing"
      >
        <canvas 
          ref={canvasRef}
          width={canvasRef.current?.parentElement?.clientWidth || 1000} 
          height={canvasRef.current?.parentElement?.clientHeight || 750}
          className="block w-full h-full"
          onWheel={handleWheel}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
          onClick={handleClick}
          style={{ touchAction: 'none', cursor: hoveredSpotId ? 'pointer' : 'default' }}
        />
      </div>

      {/* Bottom Controls */}
      <div className="absolute bottom-8 right-8 flex gap-3 z-10">
         <div className="bg-gray-800 rounded-full border border-gray-600 flex overflow-hidden shadow-lg mr-4">
            <button onClick={handleZoomOut} className="p-3 hover:bg-gray-700 text-white transition border-r border-gray-600">
                <ZoomOut size={20} />
            </button>
            <button onClick={handleResetView} className="p-3 hover:bg-gray-700 text-white transition border-r border-gray-600" title="Reset View">
                <Maximize size={20} />
            </button>
            <button onClick={handleZoomIn} className="p-3 hover:bg-gray-700 text-white transition">
                <ZoomIn size={20} />
            </button>
         </div>

         <button onClick={handleManualSave} className="bg-indigo-600 p-3 rounded-full hover:bg-indigo-500 text-white shadow-lg transition transform hover:scale-105" title="Save Game">
           <Save size={24} />
         </button>
         <button onClick={onExit} className="bg-gray-800 p-3 rounded-full hover:bg-red-900/80 text-white border border-gray-600 shadow-lg transition transform hover:scale-105" title="Exit to Editor">
           <LogOut size={24} />
         </button>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Plus, Trash2, Image as ImageIcon, User, Target, Save, PlayCircle, RotateCcw, Map as MapIcon, MousePointerClick, FileUp, Download, Upload, Check, Waypoints, Globe, Lock, Unlock, MessageSquare } from 'lucide-react';
import { Character, Scene, SceneCharacterConfig, WorldMap, MapSpot, UnlockReward } from '../types';
import { Button } from './ui/Button';

interface EditorProps {
  characters: Character[];
  scenes: Scene[];
  maps: WorldMap[];
  onUpdateCharacters: (chars: Character[]) => void;
  onUpdateScenes: (scenes: Scene[]) => void;
  onUpdateMaps: (maps: WorldMap[]) => void;
  onPlay: () => void;
  onQuickSave: () => Promise<boolean>;
  onExportProject: () => void;
  onImportProject: (file: File) => void;
  hasSaveGame: boolean;
  onContinueGame: () => void;
}

export const Editor: React.FC<EditorProps> = ({
  characters,
  scenes,
  maps,
  onUpdateCharacters,
  onUpdateScenes,
  onUpdateMaps,
  onPlay,
  onQuickSave,
  onExportProject,
  onImportProject,
  hasSaveGame,
  onContinueGame
}) => {
  const [activeTab, setActiveTab] = useState<'chars' | 'scenes' | 'map'>('chars');

  // Map Editor State
  const [activeMapId, setActiveMapId] = useState<string>(maps[0]?.id || '');
  const [selectedTool, setSelectedTool] = useState<{type: 'scene'|'transition', id: string} | null>(null);

  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const importInputRef = useRef<HTMLInputElement>(null);

  // --- Character Handlers ---
  const addCharacter = () => {
    const newChar: Character = {
      id: crypto.randomUUID(),
      name: 'New Character',
      defaultDescription: 'A friendly helper.',
      imageSrc: null,
      mapSpriteSrc: null,
      rpgColor: '#ef4444', 
    };
    onUpdateCharacters([...characters, newChar]);
  };

  const updateCharacter = (id: string, updates: Partial<Character>) => {
    onUpdateCharacters(characters.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const handleCharImageUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>, field: 'imageSrc' | 'mapSpriteSrc') => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCharacter(id, { [field]: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  // --- Scene Handlers ---
  const addScene = () => {
    const newScene: Scene = {
      id: crypto.randomUUID(),
      name: `Scene ${scenes.length + 1}`,
      backgroundSrc: null,
      description: 'You are in a quiet room.',
      goal: 'Say hello.',
      characters: [],
      unlocks: [],
      mapIconSrc: null
    };
    onUpdateScenes([...scenes, newScene]);
  };

  const updateScene = (id: string, updates: Partial<Scene>) => {
    onUpdateScenes(scenes.map(s => s.id === id ? { ...s, ...updates } : s));
  };

  const handleSceneIconUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { mapIconSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleUnlock = (sceneId: string, type: 'scene' | 'transition', targetId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const currentUnlocks = scene.unlocks || [];
    const exists = currentUnlocks.some(u => u.type === type && u.targetId === targetId);

    let newUnlocks;
    if (exists) {
        newUnlocks = currentUnlocks.filter(u => !(u.type === type && u.targetId === targetId));
    } else {
        newUnlocks = [...currentUnlocks, { type, targetId }];
    }
    updateScene(sceneId, { unlocks: newUnlocks });
  };

  const handleBgUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleCharInScene = (sceneId: string, charId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const exists = scene.characters.find(c => c.characterId === charId);
    let newChars: SceneCharacterConfig[];

    if (exists) {
      newChars = scene.characters.filter(c => c.characterId !== charId);
    } else {
      newChars = [...scene.characters, { characterId: charId, roleInScene: 'Default behavior' }];
    }
    updateScene(sceneId, { characters: newChars });
  };

  const updateSceneCharRole = (sceneId: string, charId: string, role: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;
    const newChars = scene.characters.map(c => c.characterId === charId ? { ...c, roleInScene: role } : c);
    updateScene(sceneId, { characters: newChars });
  };

  // --- Map Handlers ---

  const getCurrentMap = () => maps.find(m => m.id === activeMapId);

  const addMap = () => {
      const newMap: WorldMap = {
          id: crypto.randomUUID(),
          name: `Map ${maps.length + 1}`,
          backgroundSrc: null,
          spots: []
      };
      const newMaps = [...maps, newMap];
      onUpdateMaps(newMaps);
      setActiveMapId(newMap.id);
  };

  const deleteMap = (id: string) => {
      if (maps.length <= 1) {
          alert("You must have at least one map.");
          return;
      }
      const newMaps = maps.filter(m => m.id !== id);
      onUpdateMaps(newMaps);
      if (activeMapId === id) setActiveMapId(newMaps[0].id);
  };

  const updateCurrentMap = (updates: Partial<WorldMap>) => {
      onUpdateMaps(maps.map(m => m.id === activeMapId ? { ...m, ...updates } : m));
  };

  const handleMapBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCurrentMap({ backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const handleMapClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!selectedTool || !mapContainerRef.current) return;

    // Check if clicked on an existing pin
    if ((e.target as HTMLElement).closest('.map-pin')) return;

    const rect = mapContainerRef.current.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;

    const currentMap = getCurrentMap();
    if (!currentMap) return;

    const newSpot: MapSpot = {
      id: crypto.randomUUID(),
      type: selectedTool.type,
      x, 
      y,
      sceneId: selectedTool.type === 'scene' ? selectedTool.id : undefined,
      targetMapId: selectedTool.type === 'transition' ? selectedTool.id : undefined,
    };

    updateCurrentMap({ spots: [...currentMap.spots, newSpot] });
  };

  const removeSpot = (spotId: string) => {
    const currentMap = getCurrentMap();
    if(!currentMap) return;
    updateCurrentMap({
      spots: currentMap.spots.filter(s => s.id !== spotId)
    });
  };

  // --- Toolbar Handlers ---

  const handleQuickSaveClick = async () => {
    setSaveStatus('saving');
    await onQuickSave();
    setSaveStatus('saved');
    setTimeout(() => setSaveStatus('idle'), 2000);
  };

  const handleImportClick = () => {
    importInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if(e.target.files && e.target.files[0]) {
        onImportProject(e.target.files[0]);
    }
    if(e.target.value) e.target.value = ''; 
  };

  const currentMap = getCurrentMap();

  return (
    <div className="flex flex-col h-full max-w-6xl mx-auto p-4 md:p-8">
      {/* Header / Toolbar */}
      <div className="flex flex-col xl:flex-row justify-between items-center mb-8 gap-6">
        <div>
           <h1 className="text-3xl font-bold text-indigo-400">VN Creator Studio</h1>
           <p className="text-gray-400 text-sm mt-1">Design your world, characters, and stories.</p>
        </div>

        <div className="flex flex-wrap gap-3 items-center justify-center">
          {/* File Operations */}
          <div className="flex gap-2 mr-2 bg-gray-800 p-1 rounded-lg border border-gray-700">
             <input type="file" ref={importInputRef} className="hidden" accept=".json" onChange={handleFileChange} />

             <button onClick={handleImportClick} className="flex items-center gap-2 px-3 py-2 text-sm text-gray-300 hover:text-white hover:bg-gray-700 rounded transition" title="Load .json file">
               <Upload size={16} /> Load Project
             </button>

             <div className="w-[1px] bg-gray-600 my-1"></div>

             <button onClick={onExportProject} className="flex items-center gap-2 px-3 py-2 text-sm text-gray-300 hover:text-white hover:bg-gray-700 rounded transition" title="Download .json file">
               <Download size={16} /> Export Project
             </button>
          </div>

          <Button 
            onClick={handleQuickSaveClick} 
            variant="secondary" 
            title="Saves to Browser Storage"
            className="min-w-[140px]"
            disabled={saveStatus === 'saving'}
          >
            {saveStatus === 'saved' ? <><Check size={18} className="text-green-400"/> Saved!</> : (saveStatus === 'saving' ? 'Saving...' : <><Save size={18} /> Quick Save</>)}
          </Button>

          <div className="h-8 w-[1px] bg-gray-700 mx-2 hidden md:block"></div>

          {hasSaveGame && (
            <Button onClick={onContinueGame} className="bg-yellow-600 hover:bg-yellow-500">
              <RotateCcw size={18} /> Continue
            </Button>
          )}

          <Button onClick={onPlay} className="bg-green-600 hover:bg-green-500 px-6 font-bold shadow-green-900/20">
            <PlayCircle size={18} /> PLAY GAME
          </Button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex gap-4 mb-6 border-b border-gray-700 pb-1">
        <button
          onClick={() => setActiveTab('chars')}
          className={`px-4 py-2 font-medium transition-colors ${activeTab === 'chars' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}
        >
          Characters
        </button>
        <button
          onClick={() => setActiveTab('scenes')}
          className={`px-4 py-2 font-medium transition-colors ${activeTab === 'scenes' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}
        >
          Scenarios
        </button>
        <button
          onClick={() => setActiveTab('map')}
          className={`px-4 py-2 font-medium transition-colors ${activeTab === 'map' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}
        >
          World Map
        </button>
      </div>

      <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
        {activeTab === 'chars' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {characters.map(char => (
                <div key={char.id} className="bg-gray-800 p-4 rounded-xl border border-gray-700 flex gap-4 shadow-lg hover:border-gray-600 transition-colors">

                  {/* Portrait (Left) */}
                  <div className="w-24 h-32 bg-gray-900 rounded-lg flex-shrink-0 border border-gray-600 overflow-hidden relative group">
                    {char.imageSrc ? (
                      <img src={char.imageSrc} alt={char.name} className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full flex flex-col items-center justify-center text-gray-600 gap-1">
                        <User size={24} />
                        <span className="text-[10px] text-center px-1">Portrait</span>
                      </div>
                    )}
                    <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity text-xs font-bold">
                      UPLOAD
                      <input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e, 'imageSrc')} />
                    </label>
                  </div>

                  <div className="flex-1 space-y-3">
                    <input
                      className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-1 focus:border-indigo-500 outline-none transition-all"
                      value={char.name}
                      onChange={(e) => updateCharacter(char.id, { name: e.target.value })}
                      placeholder="Character Name"
                    />

                    {/* Map Sprite Uploader */}
                    <div className="flex items-center gap-3">
                       <div className="w-12 h-12 bg-gray-900 rounded border border-gray-600 overflow-hidden relative group shrink-0">
                         {char.mapSpriteSrc ? (
                           <img src={char.mapSpriteSrc} alt="Sprite" className="w-full h-full object-contain" />
                         ) : (
                           <div className="w-full h-full flex items-center justify-center text-gray-600" title="Map Sprite">
                             <MapIcon size={16} />
                           </div>
                         )}
                         <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity">
                            <FileUp size={16} className="text-white"/>
                            <input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e, 'mapSpriteSrc')} />
                         </label>
                       </div>
                       <div className="text-xs text-gray-400">
                         <span className="font-bold block text-gray-300">Map Sprite</span>
                         <span className="text-[10px]">Icon used on the world map.</span>
                       </div>
                    </div>

                    <textarea
                      className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-1 h-20 text-sm focus:border-indigo-500 outline-none resize-none transition-all"
                      value={char.defaultDescription}
                      onChange={(e) => updateCharacter(char.id, { defaultDescription: e.target.value })}
                      placeholder="Core Persona/Description..."
                    />
                  </div>
                  <button onClick={() => onUpdateCharacters(characters.filter(c => c.id !== char.id))} className="text-gray-500 hover:text-red-500 h-fit transition-colors p-1">
                    <Trash2 size={18} />
                  </button>
                </div>
              ))}
            </div>
            <Button onClick={addCharacter} variant="secondary" className="w-full py-4 border-dashed opacity-70 hover:opacity-100">
              <Plus size={20} /> Add Character
            </Button>
          </div>
        )}

        {activeTab === 'scenes' && (
          <div className="space-y-8">
            {scenes.map((scene, idx) => (
              <div key={scene.id} className="bg-gray-800 p-6 rounded-xl border border-gray-700 space-y-4 shadow-lg">
                <div className="flex justify-between items-start">
                  <div className="flex items-center gap-4">
                    <div className="bg-gray-900 px-3 py-1 rounded text-xs font-bold text-indigo-400 border border-gray-700">SCENE {idx + 1}</div>
                    <input
                       className="bg-transparent text-xl font-bold outline-none placeholder-gray-600 focus:text-white transition-colors"
                       value={scene.name}
                       onChange={(e) => updateScene(scene.id, { name: e.target.value })}
                       placeholder="Scene Name"
                    />
                  </div>
                  <button onClick={() => onUpdateScenes(scenes.filter(s => s.id !== scene.id))} className="text-gray-500 hover:text-red-500 transition-colors p-1">
                    <Trash2 size={18} />
                  </button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                  {/* Visuals & Goal */}
                  <div className="space-y-4">
                    <div className="w-full h-40 bg-gray-900 rounded-lg border border-gray-600 overflow-hidden relative group shadow-inner">
                       {scene.backgroundSrc ? (
                          <img src={scene.backgroundSrc} alt="bg" className="w-full h-full object-cover opacity-80" />
                       ) : (
                         <div className="w-full h-full flex items-center justify-center text-gray-500 gap-2">
                           <ImageIcon size={24} /> No Background
                         </div>
                       )}
                       <label className="absolute inset-0 flex items-center justify-center cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity bg-black/40">
                          <span className="bg-black/80 px-4 py-2 rounded hover:bg-black text-sm border border-gray-600">Change Background</span>
                          <input type="file" accept="image/*" className="hidden" onChange={(e) => handleBgUpload(scene.id, e)} />
                       </label>
                    </div>

                    {/* Map Icon Override */}
                    <div className="flex items-center gap-3 bg-gray-900/50 p-2 rounded border border-gray-700">
                       <div className="w-10 h-10 bg-gray-900 rounded border border-gray-600 overflow-hidden relative group shrink-0">
                         {scene.mapIconSrc ? (
                           <img src={scene.mapIconSrc} alt="Icon" className="w-full h-full object-contain" />
                         ) : (
                            // Show first character sprite if available as preview
                            scene.characters.length > 0 && characters.find(c => c.id === scene.characters[0].characterId)?.mapSpriteSrc ? (
                                <img src={characters.find(c => c.id === scene.characters[0].characterId)?.mapSpriteSrc!} className="w-full h-full object-contain opacity-50 grayscale" title="Default: First Character" />
                            ) : (
                                <div className="w-full h-full flex items-center justify-center text-gray-600" title="Map Icon">
                                    <MapIcon size={14} />
                                </div>
                            )
                         )}
                         <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity">
                            <FileUp size={12} className="text-white"/>
                            <input type="file" accept="image/*" className="hidden" onChange={(e) => handleSceneIconUpload(scene.id, e)} />
                         </label>
                       </div>
                       <div className="text-xs text-gray-400">
                         <span className="font-bold block text-gray-300">Map Icon (Optional)</span>
                         <span className="text-[10px]">Overrides character sprite on map.</span>
                       </div>
                    </div>

                    <div>
                      <label className="flex items-center gap-2 text-xs font-bold text-green-400 mb-1">
                        <Target size={14} /> WIN CONDITION
                      </label>
                      <textarea
                        className="w-full bg-gray-900 border border-green-900/50 text-green-100 rounded px-3 py-2 text-sm focus:border-green-500 outline-none resize-none transition-all shadow-inner"
                        value={scene.goal}
                        onChange={(e) => updateScene(scene.id, { goal: e.target.value })}
                        placeholder="e.g. Find the key..."
                        rows={3}
                      />
                    </div>

                    {/* Rewards / Unlocks Configuration */}
                    <div className="bg-gray-900/50 p-3 rounded-lg border border-gray-700">
                        <label className="flex items-center gap-2 text-xs font-bold text-yellow-500 mb-2">
                            <Unlock size={14} /> UNLOCKS ON COMPLETION
                        </label>
                        <p className="text-[10px] text-gray-500 mb-2">Select Scenarios or Maps that become available after this.</p>

                        <div className="space-y-2 max-h-32 overflow-y-auto custom-scrollbar">
                            {/* Other Scenes */}
                            {scenes.filter(s => s.id !== scene.id).map(otherScene => {
                                const isUnlocked = scene.unlocks?.some(u => u.type === 'scene' && u.targetId === otherScene.id);
                                return (
                                    <button 
                                        key={otherScene.id} 
                                        onClick={() => toggleUnlock(scene.id, 'scene', otherScene.id)}
                                        className={`w-full flex items-center gap-2 text-xs p-1.5 rounded border ${isUnlocked ? 'bg-yellow-900/30 border-yellow-600 text-yellow-100' : 'bg-gray-800 border-gray-700 text-gray-400 hover:border-gray-500'}`}
                                    >
                                        {isUnlocked ? <Unlock size={10} /> : <Lock size={10} />}
                                        <span className="truncate">Scene: {otherScene.name}</span>
                                    </button>
                                );
                            })}

                            {/* Maps */}
                            {maps.map(m => {
                                const isUnlocked = scene.unlocks?.some(u => u.type === 'transition' && u.targetId === m.id);
                                return (
                                    <button 
                                        key={m.id} 
                                        onClick={() => toggleUnlock(scene.id, 'transition', m.id)}
                                        className={`w-full flex items-center gap-2 text-xs p-1.5 rounded border ${isUnlocked ? 'bg-emerald-900/30 border-emerald-600 text-emerald-100' : 'bg-gray-800 border-gray-700 text-gray-400 hover:border-gray-500'}`}
                                    >
                                        {isUnlocked ? <Globe size={10} /> : <Lock size={10} />}
                                        <span className="truncate">Travel to: {m.name}</span>
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                  </div>

                  {/* Narrative Setup */}
                  <div className="space-y-2 lg:col-span-2">
                     <label className="block text-xs font-bold text-gray-400">SCENARIO DESCRIPTION (For AI)</label>
                     <textarea
                        className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-2 text-sm focus:border-indigo-500 outline-none resize-none transition-all"
                        value={scene.description}
                        onChange={(e) => updateScene(scene.id, { description: e.target.value })}
                        placeholder="Describe the setting, the mood, and what is happening..."
                        rows={3}
                      />

                      <label className="block text-xs font-bold text-gray-400 mt-4">PARTICIPATING CHARACTERS</label>
                      <div className="bg-gray-900 rounded-lg p-3 border border-gray-700 min-h-[100px] shadow-inner">
                         <div className="flex gap-2 flex-wrap mb-3">
                           {characters.map(char => {
                             const isActive = scene.characters.some(c => c.characterId === char.id);
                             return (
                               <button
                                 key={char.id}
                                 onClick={() => toggleCharInScene(scene.id, char.id)}
                                 className={`text-xs px-3 py-1 rounded-full border transition-all ${isActive ? 'bg-indigo-600 border-indigo-400 text-white shadow-md' : 'bg-gray-800 border-gray-600 text-gray-400 hover:border-gray-400 hover:text-gray-300'}`}
                               >
                                 {char.name}
                               </button>
                             )
                           })}
                           {characters.length === 0 && <span className="text-xs text-gray-600 italic">No characters created yet.</span>}
                         </div>

                         {/* Per-Scene Character Logic */}
                         <div className="space-y-3">
                           {scene.characters.map(sc => {
                             const char = characters.find(c => c.id === sc.characterId);
                             if (!char) return null;
                             return (
                               <div key={sc.characterId} className="flex items-center gap-3 bg-gray-800 p-2 rounded border border-gray-700">
                                 <div className="w-8 h-8 rounded-full bg-gray-700 overflow-hidden flex-shrink-0 border border-gray-600" style={{ backgroundColor: char.rpgColor }}>
                                   {char.imageSrc && <img src={char.imageSrc} className="w-full h-full object-cover" />}
                                 </div>
                                 <div className="flex-1">
                                    <div className="text-xs font-bold text-indigo-300">{char.name} Role</div>
                                    <input 
                                      className="w-full bg-transparent border-b border-gray-600 text-xs py-1 focus:border-indigo-400 outline-none transition-colors"
                                      placeholder="What does this character want in this scene?"
                                      value={sc.roleInScene}
                                      onChange={(e) => updateSceneCharRole(scene.id, sc.characterId, e.target.value)}
                                    />
                                 </div>
                               </div>
                             )
                           })}
                           {scene.characters.length === 0 && <div className="text-xs text-gray-500 text-center py-4">Select characters above to assign roles.</div>}
                         </div>
                      </div>
                  </div>
                </div>
              </div>
            ))}
            <Button onClick={addScene} variant="secondary" className="w-full py-4 border-dashed opacity-70 hover:opacity-100">
              <Plus size={20} /> Add Scenario
            </Button>
          </div>
        )}

        {activeTab === 'map' && (
          <div className="flex flex-col lg:flex-row gap-6 h-full">
            {/* Sidebar Controls */}
            <div className="w-full lg:w-64 flex flex-col gap-6">

              {/* Map Switcher */}
              <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 shadow-lg space-y-3">
                  <div className="flex items-center justify-between mb-2">
                     <h3 className="font-bold text-gray-300 flex items-center gap-2"><Globe size={16}/> Maps</h3>
                     <button onClick={addMap} className="text-indigo-400 hover:text-white p-1 rounded bg-indigo-900/30 hover:bg-indigo-600 transition">
                         <Plus size={14} />
                     </button>
                  </div>

                  <div className="space-y-2 max-h-32 overflow-y-auto custom-scrollbar">
                     {maps.map(m => (
                         <div key={m.id} className={`flex items-center justify-between p-2 rounded cursor-pointer border ${m.id === activeMapId ? 'bg-indigo-900/50 border-indigo-500' : 'bg-gray-900 border-gray-800 hover:border-gray-600'}`} onClick={() => setActiveMapId(m.id)}>
                             <span className="text-xs truncate max-w-[120px]">{m.name}</span>
                             {maps.length > 1 && (
                                 <button onClick={(e) => { e.stopPropagation(); deleteMap(m.id); }} className="text-gray-600 hover:text-red-400">
                                     <Trash2 size={12} />
                                 </button>
                             )}
                         </div>
                     ))}
                  </div>

                  {currentMap && (
                      <div className="pt-2 border-t border-gray-700">
                         <input 
                            className="w-full bg-gray-900 border border-gray-600 rounded px-2 py-1 text-xs text-gray-200 outline-none focus:border-indigo-500"
                            value={currentMap.name}
                            onChange={(e) => updateCurrentMap({ name: e.target.value })}
                            placeholder="Map Name"
                         />
                      </div>
                  )}
              </div>

              {/* Map Background Config */}
              {currentMap && (
                  <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 shadow-lg">
                    <h3 className="font-bold text-gray-300 mb-3 flex items-center gap-2 text-sm"><MapIcon size={14}/> Background</h3>
                    <label className="block w-full cursor-pointer bg-gray-900 border border-gray-600 hover:border-gray-400 hover:bg-gray-800 text-center py-4 rounded-lg border-dashed transition-all group">
                    <span className="text-xs text-gray-400 group-hover:text-white">Change Image</span>
                    <input type="file" accept="image/*" className="hidden" onChange={handleMapBgUpload} />
                    </label>
                </div>
              )}

              {/* Tools: Scenes & Transitions */}
              <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 flex-1 shadow-lg flex flex-col min-h-[300px]">
                 <h3 className="font-bold text-gray-300 mb-3 flex items-center gap-2 text-sm"><User size={14}/> Place Items</h3>
                 <p className="text-xs text-gray-500 mb-4">Select an item, then click on the map to place.</p>

                 <div className="space-y-4 overflow-y-auto custom-scrollbar flex-1">
                    {/* SCENES */}
                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2">Scenarios</div>
                        <div className="space-y-1">
                            {scenes.map(scene => {
                                // Determine icon to show in sidebar
                                let iconSrc = scene.mapIconSrc;
                                let bgColor = '#4b5563';
                                if (!iconSrc && scene.characters.length > 0) {
                                    const char = characters.find(c => c.id === scene.characters[0].characterId);
                                    if(char) {
                                        iconSrc = char.mapSpriteSrc;
                                        bgColor = char.rpgColor;
                                    }
                                }

                                return (
                                <button 
                                    key={scene.id}
                                    onClick={() => setSelectedTool(selectedTool?.id === scene.id ? null : { type: 'scene', id: scene.id })}
                                    className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === scene.id && selectedTool.type === 'scene' ? 'bg-indigo-600/20 border-indigo-500 ring-1 ring-indigo-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}
                                >
                                    <div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 overflow-hidden flex items-center justify-center flex-shrink-0" style={{ backgroundColor: bgColor }}>
                                        {iconSrc ? <img src={iconSrc} className="w-full h-full object-contain" /> : <MessageSquare size={12} className="text-gray-400"/>}
                                    </div>
                                    <span className="text-xs font-medium truncate flex-1 text-left">{scene.name}</span>
                                    {selectedTool?.id === scene.id && selectedTool.type === 'scene' && <MousePointerClick size={12} className="ml-auto text-indigo-400"/>}
                                </button>
                                );
                            })}
                        </div>
                    </div>

                    {/* Transitions */}
                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2">Map Transitions</div>
                        <div className="space-y-1">
                            {maps.filter(m => m.id !== activeMapId).map(targetMap => (
                                <button
                                    key={targetMap.id}
                                    onClick={() => setSelectedTool(selectedTool?.id === targetMap.id ? null : { type: 'transition', id: targetMap.id })}
                                    className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === targetMap.id && selectedTool.type === 'transition' ? 'bg-emerald-600/20 border-emerald-500 ring-1 ring-emerald-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}
                                >
                                    <div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 flex items-center justify-center flex-shrink-0 text-emerald-500">
                                        <Waypoints size={14} />
                                    </div>
                                    <span className="text-xs font-medium truncate flex-1 text-left">To: {targetMap.name}</span>
                                    {selectedTool?.id === targetMap.id && selectedTool.type === 'transition' && <MousePointerClick size={12} className="ml-auto text-emerald-400"/>}
                                </button>
                            ))}
                            {maps.length <= 1 && <div className="text-xs text-gray-600 italic px-2">Create another map to link to.</div>}
                        </div>
                    </div>
                 </div>
              </div>
            </div>

            {/* Map Canvas */}
            <div className="flex-1 bg-gray-900 rounded-xl border-[4px] border-gray-800 shadow-2xl overflow-hidden relative group">
                {currentMap && currentMap.backgroundSrc ? (
                   <div 
                      ref={mapContainerRef}
                      onClick={handleMapClick}
                      className="relative w-full h-full cursor-crosshair"
                   >
                      <img 
                        src={currentMap.backgroundSrc} 
                        alt="World Map" 
                        className="w-full h-full object-contain bg-black select-none pointer-events-none" 
                      />

                      {/* Render Spots */}
                      {currentMap.spots.map(spot => {
                         if (spot.type === 'scene') {
                             // SCENE RENDERING
                             const scene = scenes.find(s => s.id === spot.sceneId);

                             // Resolve visual
                             let iconSrc = scene?.mapIconSrc;
                             let bgColor = '#ffffff';
                             let name = scene?.name || 'Unknown Scene';

                             // Fallback to character icon logic if no override
                             if (scene && !iconSrc && scene.characters.length > 0) {
                                const char = characters.find(c => c.id === scene.characters[0].characterId);
                                if(char) {
                                    iconSrc = char.mapSpriteSrc;
                                    bgColor = char.rpgColor;
                                }
                             }

                             return (
                                <div 
                                  key={spot.id}
                                  className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin"
                                  style={{ left: `${spot.x}%`, top: `${spot.y}%` }}
                                >
                                   {/* Sprite Render */}
                                   <div className="w-12 h-12 relative drop-shadow-lg transition hover:scale-110 flex items-center justify-center">
                                       {iconSrc ? (
                                           <img src={iconSrc} alt={name} className="w-full h-full object-contain" />
                                       ) : (
                                           <div className="w-6 h-6 rounded-full border border-white shadow-sm flex items-center justify-center bg-gray-700 text-white" style={{backgroundColor: bgColor}}>
                                               <MessageSquare size={12} />
                                           </div>
                                       )}
                                   </div>

                                   <span className="bg-black/70 text-[10px] px-2 rounded text-white whitespace-nowrap mt-1 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none backdrop-blur-sm">{name}</span>
                                   <button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110">
                                     <Trash2 size={12} />
                                   </button>
                                </div>
                             )
                         } else {
                             // Transition Spot
                             const target = maps.find(m => m.id === spot.targetMapId);
                             return (
                                <div 
                                  key={spot.id}
                                  className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin"
                                  style={{ left: `${spot.x}%`, top: `${spot.y}%` }}
                                >
                                   {/* Transition Icon */}
                                   <div className="w-8 h-8 rounded-full bg-emerald-500/50 border-2 border-emerald-400 flex items-center justify-center shadow-lg hover:scale-110 transition">
                                       <Waypoints size={16} className="text-white" />
                                   </div>

                                   <span className="bg-emerald-900/90 text-[10px] px-2 rounded text-emerald-100 whitespace-nowrap mt-1 opacity-100 transition-opacity pointer-events-none backdrop-blur-sm border border-emerald-700">Go to: {target?.name || 'Unknown'}</span>
                                   <button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110">
                                     <Trash2 size={12} />
                                   </button>
                                </div>
                             )
                         }
                      })}
                   </div>
                ) : (
                  <div className="w-full h-full flex flex-col items-center justify-center text-gray-600 gap-4">
                    {currentMap ? (
                        <>
                            <MapIcon size={48} opacity={0.5} />
                            <p>Upload a background for {currentMap.name}.</p>
                        </>
                    ) : (
                        <p>No map selected.</p>
                    )}
                  </div>
                )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export interface Character {
  id: string;
  name: string;
  defaultDescription: string;
  imageSrc: string | null; // Portrait for VN (Large)
  mapSpriteSrc: string | null; // Sprite for Map (Small/Icon)
  rpgColor: string; // Fallback Hex color
}

export interface SceneCharacterConfig {
  characterId: string;
  roleInScene: string; // Specific behavior/goal for this scene
}

export interface UnlockReward {
  type: 'scene' | 'transition';
  targetId: string; // Scene ID or Target Map ID
}

export interface Scene {
  id: string;
  name: string;
  backgroundSrc: string | null; // Local object URL
  description: string; // The scenario setup
  goal: string; // The win condition to move to next scene
  characters: SceneCharacterConfig[];
  unlocks?: UnlockReward[]; // List of things unlocked when this scene is won

  // New: Visual override for the map
  mapIconSrc?: string | null; 
}

export interface MapSpot {
  id: string;
  x: number; // Percentage 0-100
  y: number; // Percentage 0-100
  type: 'scene' | 'transition' | 'character';

  // If type === 'scene'
  sceneId?: string; // DIRECT link to a specific scene

  // If type === 'character'
  characterId?: string; // GENERIC link to a character (finds next scene)

  // If type === 'transition'
  targetMapId?: string;
}

export interface WorldMap {
  id: string;
  name: string;
  backgroundSrc: string | null;
  spots: MapSpot[];
}

export interface ChatMessage {
  sender: 'user' | 'model' | 'system';
  characterId?: string; // If model, which character?
  text: string;
  timestamp: number;
}

export interface GameState {
  currentSceneIndex: number; // Used inside VN Mode
  history: ChatMessage[];
  isProcessing: boolean;
  gameOver: boolean;
}

export interface AIResponse {
  characterResponses: {
    characterId: string;
    text: string;
  }[];
  sceneGoalReached: boolean;
  sceneTransitionReason?: string;
}

export interface RPGState {
  currentMapId: string;
  completedSceneIds: string[];
  unlockedIds: string[]; // IDs of Scenes or Maps that have been unlocked
  ongoingScenes: Record<string, ChatMessage[]>; // Stores history for incomplete scenes { sceneId: history[] }
}

export interface GameSaveData {
  rpgState: RPGState;
  vnState: GameState | null; // Null if saved while on map
  timestamp: number;
}

import React, { useState, useEffect } from 'react';
import { Editor } from './components/Editor';
import { Player } from './components/Player';
import { RPGWorld } from './components/RPGWorld';
import { Character, Scene, GameSaveData, RPGState, WorldMap, ChatMessage } from './types';
import { getItem, setItem } from './utils/db';

// Default Data for quick start
const DEFAULT_CHARS: Character[] = [
  { 
    id: '1', 
    name: 'Aiko', 
    defaultDescription: 'A cheerful and curious android girl who loves learning about humans.', 
    imageSrc: null,
    mapSpriteSrc: null,
    rpgColor: '#f472b6' // Pink
  },
  { 
    id: '2', 
    name: 'Kael', 
    defaultDescription: 'A grumpy but skilled mechanic who fixes robots.', 
    imageSrc: null,
    mapSpriteSrc: null,
    rpgColor: '#60a5fa' // Blue
  }
];

const DEFAULT_SCENES: Scene[] = [
  {
    id: 's1',
    name: 'The Workshop',
    backgroundSrc: null,
    description: 'A cluttered workshop filled with robot parts. Kael is working on a workbench. Aiko is watching closely.',
    goal: 'Convince Kael to fix your broken radio.',
    characters: [
      { characterId: '1', roleInScene: 'Curious onlooker, wants to help but is clumsy.' },
      { characterId: '2', roleInScene: 'Busy, easily annoyed, does not want to be disturbed.' }
    ],
    unlocks: []
  }
];

const DEFAULT_MAPS: WorldMap[] = [
  {
    id: 'map1',
    name: 'Main City',
    backgroundSrc: null,
    spots: [
      // Example: A character spot instead of a direct scene spot
      { id: 'spot1', type: 'character', characterId: '1', x: 50, y: 50 },
    ]
  }
];

const PROJECT_STORAGE_KEY = 'vn_creator_project';
const GAME_SAVE_KEY = 'vn_creator_savegame';

const App: React.FC = () => {
  const [mode, setMode] = useState<'edit' | 'rpg' | 'vn'>('edit');

  // Data State
  const [characters, setCharacters] = useState<Character[]>(DEFAULT_CHARS);
  const [scenes, setScenes] = useState<Scene[]>(DEFAULT_SCENES);
  const [maps, setMaps] = useState<WorldMap[]>(DEFAULT_MAPS);

  // Game Play State
  const [rpgState, setRpgState] = useState<RPGState>({ 
    currentMapId: 'map1', 
    completedSceneIds: [],
    unlockedIds: [],
    ongoingScenes: {}
  });

  const [activeSceneIndex, setActiveSceneIndex] = useState<number>(-1);
  const [vnHistory, setVnHistory] = useState<ChatMessage[]>([]); 

  const [hasSaveGame, setHasSaveGame] = useState(false);

  // Check for save game on mount and migrate from LocalStorage if needed
  useEffect(() => {
    const initLoad = async () => {
        // 1. Check for Save Game
        const savedGame = await getItem<GameSaveData>(GAME_SAVE_KEY);
        if (savedGame) {
            setHasSaveGame(true);
        } else {
            // Check legacy local storage for save game
            const lsSave = localStorage.getItem(GAME_SAVE_KEY);
            if (lsSave) {
                setHasSaveGame(true);
            }
        }

        // 2. Load Project Data (Try IndexedDB first)
        let data: any = await getItem(PROJECT_STORAGE_KEY);

        // 3. Fallback/Migrate from LocalStorage if IDB is empty
        if (!data) {
            const lsProject = localStorage.getItem(PROJECT_STORAGE_KEY);
            if (lsProject) {
                try {
                    data = JSON.parse(lsProject);
                    await setItem(PROJECT_STORAGE_KEY, data);
                    localStorage.removeItem(PROJECT_STORAGE_KEY);
                } catch (e) {
                    console.error("Failed to parse legacy local storage", e);
                }
            }
        }

        // Apply Data
        if (data) {
            if (data.characters) setCharacters(data.characters);
            if (data.scenes) setScenes(data.scenes);

            // Migration check
            if (data.mapConfig && !data.maps) {
                setMaps([{ ...data.mapConfig, id: 'map1', name: 'Default Map' }]);
            } else if (data.maps) {
                setMaps(data.maps);
            }
        }
    };
    initLoad();
  }, []);

  // 1. Quick Save to Browser Storage (IndexedDB)
  const handleQuickSave = async () => {
    const data = { characters, scenes, maps };
    await setItem(PROJECT_STORAGE_KEY, data);
    return true;
  };

  // 2. Export to File (Download)
  const handleExportProject = () => {
    const data = { characters, scenes, maps };
    const jsonString = JSON.stringify(data, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const href = URL.createObjectURL(blob);

    const link = document.createElement('a');
    link.href = href;
    link.download = `vn-project-${new Date().toISOString().slice(0,10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(href);
  };

  // 3. Import from File (Upload)
  const handleImportProject = (file: File) => {
    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const content = e.target?.result as string;
        const data = JSON.parse(content);

        if (data.characters) setCharacters(data.characters);
        if (data.scenes) setScenes(data.scenes);
        if (data.maps) setMaps(data.maps);
        else if (data.mapConfig) setMaps([{ ...data.mapConfig, id: 'map1', name: 'Default Map' }]);

        // Save to DB immediately
        await setItem(PROJECT_STORAGE_KEY, data);
        alert("Project loaded successfully!");
      } catch (error) {
        console.error("Import failed", error);
        alert("Failed to load project file. Invalid JSON.");
      }
    };
    reader.readAsText(file);
  };

  const handleStartNewGame = () => {
    setRpgState({ 
        currentMapId: maps[0].id, 
        completedSceneIds: [], 
        unlockedIds: [],
        ongoingScenes: {} 
    });
    setVnHistory([]);
    setActiveSceneIndex(-1);
    setMode('rpg');
  };

  const handleContinueGame = async () => {
    // Try IDB first
    let savedGame = await getItem<GameSaveData>(GAME_SAVE_KEY);

    // Fallback to LS
    if (!savedGame) {
        const lsSave = localStorage.getItem(GAME_SAVE_KEY);
        if (lsSave) {
            try {
                savedGame = JSON.parse(lsSave);
            } catch(e) {}
        }
    }

    if (savedGame) {
      try {
        // Ensure map ID exists, fallback to first if deleted
        const safeMapId = maps.find(m => m.id === savedGame!.rpgState.currentMapId) ? savedGame!.rpgState.currentMapId : maps[0].id;

        setRpgState({ 
            ...savedGame.rpgState, 
            currentMapId: safeMapId,
            unlockedIds: savedGame.rpgState.unlockedIds || [], 
            ongoingScenes: savedGame.rpgState.ongoingScenes || {} 
        });

        if (savedGame.vnState) {
          setActiveSceneIndex(savedGame.vnState.currentSceneIndex);
          setVnHistory(savedGame.vnState.history);
          setMode('vn');
        } else {
          setMode('rpg');
        }
      } catch (e) {
        console.error("Corrupt save file");
        handleStartNewGame();
      }
    }
  };

  const handleSaveGameInternal = async (updatedRpgState: RPGState, vnState: any | null) => {
      const saveData: GameSaveData = {
        rpgState: updatedRpgState,
        vnState: vnState,
        timestamp: Date.now()
      };
      await setItem(GAME_SAVE_KEY, saveData);
      setHasSaveGame(true);
      return true;
  };

  const handleInteraction = (type: 'scene'|'transition'|'character', id: string) => {
      if (type === 'transition') {
          // Change Map
          if (maps.find(m => m.id === id)) {
              setRpgState(prev => ({ ...prev, currentMapId: id }));
          }
      } else if (type === 'character') {
          // Find next available scene for this character
          const charId = id;
          const char = characters.find(c => c.id === charId);
          if (!char) return;

          const availableScenes = scenes.filter(s => s.characters.some(c => c.characterId === charId));

          const playableScene = availableScenes.find(s => {
              const isCompleted = rpgState.completedSceneIds.includes(s.id);
              if (isCompleted) return false;

              // Check dependencies
              const isLockedByOthers = scenes.some(other => other.unlocks?.some(u => u.type === 'scene' && u.targetId === s.id));
              const isUnlocked = rpgState.unlockedIds.includes(s.id);

              return !isLockedByOthers || isUnlocked;
          });

          if (playableScene) {
             startScene(playableScene);
          } else {
             alert(`${char.name} has nothing new to say right now.`);
          }

      } else {
          // Direct Scene Link
          const sceneId = id; 
          const scene = scenes.find(s => s.id === sceneId);
          if (scene) {
             startScene(scene);
          }
      }
  };

  const startScene = (scene: Scene) => {
      const realIndex = scenes.findIndex(s => s.id === scene.id);
      setActiveSceneIndex(realIndex);

      // Resume history if exists, else start fresh
      const existingHistory = rpgState.ongoingScenes?.[scene.id] || [];
      setVnHistory(existingHistory);

      setMode('vn');
  };

  const handleSceneExit = async (completed: boolean, history: ChatMessage[]) => {
      const activeScene = scenes[activeSceneIndex];
      const sceneId = activeScene.id;

      let newState = { ...rpgState };

      if (completed) {
          // 1. Mark as completed
          const newCompletedIds = [...rpgState.completedSceneIds, sceneId];

          // 2. Remove from ongoing scenes (clean up)
          const { [sceneId]: _, ...remainingScenes } = newState.ongoingScenes || {};

          // 3. Process Unlocks
          const newUnlockedIds = [...rpgState.unlockedIds];
          if (activeScene.unlocks) {
              activeScene.unlocks.forEach(reward => {
                  if (!newUnlockedIds.includes(reward.targetId)) {
                      newUnlockedIds.push(reward.targetId);
                  }
              });
          }

          newState = { 
              ...newState, 
              completedSceneIds: newCompletedIds,
              unlockedIds: newUnlockedIds,
              ongoingScenes: remainingScenes
          };

      } else {
          // 1. Just PAUSE: Save history to ongoingScenes
          newState = {
              ...newState,
              ongoingScenes: {
                  ...newState.ongoingScenes,
                  [sceneId]: history
              }
          };
      }

      setRpgState(newState);
      await handleSaveGameInternal(newState, null); // Save to disk
      setMode('rpg');
  };

  const activeMap = maps.find(m => m.id === rpgState.currentMapId) || maps[0];

  return (
    <div className="min-h-screen bg-gray-900 text-gray-100 font-sans selection:bg-indigo-500 selection:text-white">
      {mode === 'edit' && (
        <Editor 
          characters={characters}
          scenes={scenes}
          maps={maps}
          onUpdateCharacters={setCharacters}
          onUpdateScenes={setScenes}
          onUpdateMaps={setMaps}
          onPlay={handleStartNewGame}
          onQuickSave={handleQuickSave}
          onExportProject={handleExportProject}
          onImportProject={handleImportProject}
          hasSaveGame={hasSaveGame}
          onContinueGame={handleContinueGame}
        />
      )}

      {mode === 'rpg' && (
        <RPGWorld 
          characters={characters}
          mapConfig={activeMap}
          maps={maps}
          scenes={scenes}
          initialState={rpgState}
          onInteraction={handleInteraction}
          onSave={async (updatedRpgState) => {
             setRpgState(updatedRpgState);
             await handleSaveGameInternal(updatedRpgState, null);
             alert("Game Saved!");
          }}
          onExit={() => setMode('edit')}
        />
      )}

      {mode === 'vn' && activeSceneIndex >= 0 && (
        <Player 
          scenes={scenes}
          characters={characters}
          initialState={{
            currentSceneIndex: activeSceneIndex,
            history: vnHistory, // Passed from App state now
            timestamp: 0,
            rpgState: rpgState, 
            vnState: null
          }}
          onExit={handleSceneExit}
          onSave={async (vnState) => {
             await handleSaveGameInternal(rpgState, vnState);
             return true;
          }}
        />
      )}
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';
import { Character, RPGState, WorldMap, Scene } from '../types';
import { Save, LogOut, ZoomIn, ZoomOut, Maximize, MapPin } from 'lucide-react';

interface RPGWorldProps {
  characters: Character[];
  mapConfig: WorldMap; // The CURRENT map
  maps: WorldMap[]; // For referencing target map names
  scenes: Scene[]; // Needed to check dependencies
  onInteraction: (type: 'scene'|'transition'|'character', id: string) => void;
  initialState?: RPGState;
  onSave: (state: RPGState) => void;
  onExit: () => void;
}

export const RPGWorld: React.FC<RPGWorldProps> = ({ 
  characters, 
  mapConfig,
  maps,
  scenes,
  onInteraction, 
  initialState, 
  onSave,
  onExit
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const [hoveredSpotId, setHoveredSpotId] = useState<string | null>(null);
  const [canvasDims, setCanvasDims] = useState({ width: 1000, height: 750 });

  // Camera / Viewport State
  const [zoom, setZoom] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });

  // Cache for loaded sprite images (Character sprites + Custom Scene Icons)
  const spritesRef = useRef<Record<string, HTMLImageElement>>({});
  const [spritesLoaded, setSpritesLoaded] = useState(false);

  // Preload Sprites
  useEffect(() => {
    let active = true;
    const loadSprites = async () => {
        const promises: Promise<void>[] = [];

        // 1. Character Sprites
        characters.forEach(c => {
            if (!c.mapSpriteSrc) return;
            promises.push(new Promise((resolve) => {
                const img = new Image();
                img.src = c.mapSpriteSrc!;
                img.onload = () => { if(active) spritesRef.current[c.id] = img; resolve(); };
                img.onerror = () => resolve(); 
            }));
        });

        // 2. Custom Scene Icons
        scenes.forEach(s => {
            if (!s.mapIconSrc) return;
            promises.push(new Promise((resolve) => {
                const img = new Image();
                img.src = s.mapIconSrc!;
                img.onload = () => { if(active) spritesRef.current[s.id] = img; resolve(); };
                img.onerror = () => resolve();
            }));
        });

        await Promise.all(promises);
        if (active) setSpritesLoaded(true);
    };
    loadSprites();
    return () => { active = false; };
  }, [characters, scenes]);

  // Adjust canvas dimensions to match background image AND fit to screen
  useEffect(() => {
    const applyFit = (w: number, h: number) => {
        setCanvasDims({ width: w, height: h });

        if (containerRef.current) {
            const { clientWidth, clientHeight } = containerRef.current;
            // Fit to screen with 5% padding
            const scale = Math.min(clientWidth / w, clientHeight / h) * 0.95;
            const newX = (clientWidth - w * scale) / 2;
            const newY = (clientHeight - h * scale) / 2;

            setZoom(scale);
            setOffset({ x: newX, y: newY });
        }
    };

    if (mapConfig.backgroundSrc) {
        const img = new Image();
        img.src = mapConfig.backgroundSrc;
        img.onload = () => {
            applyFit(img.naturalWidth, img.naturalHeight);
        };
    } else {
        applyFit(1000, 750);
    }
  }, [mapConfig.id, mapConfig.backgroundSrc]); // Run when map ID changes

  // --- Visibility Logic ---
  const visibleSpots = mapConfig.spots.filter(spot => {
      if (spot.type === 'transition') {
          const targetMapId = spot.targetMapId;
          if (!targetMapId) return false;

          const isLockedByDependency = scenes.some(s => s.unlocks?.some(u => u.type === 'transition' && u.targetId === targetMapId));
          const isUnlocked = initialState?.unlockedIds.includes(targetMapId);

          return !isLockedByDependency || isUnlocked;

      } else if (spot.type === 'scene') {
          // Direct Link Logic
          const sceneId = spot.sceneId;
          if (!sceneId) return false;

          const scene = scenes.find(s => s.id === sceneId);
          if (!scene) return false; 

          const isCompleted = initialState?.completedSceneIds.includes(scene.id);
          if (isCompleted) return false; // Hide if done

          const isLockedByDependency = scenes.some(other => other.unlocks?.some(u => u.type === 'scene' && u.targetId === scene.id));
          const isUnlocked = initialState?.unlockedIds.includes(scene.id);

          return !isLockedByDependency || isUnlocked;
      } else if (spot.type === 'character') {
          // Character spots are generally visible unless we add logic to hide them later
          return !!spot.characterId;
      }
      return true;
  });

  // --- Coordinate Systems ---

  const getRawMousePos = (e: React.MouseEvent | React.WheelEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    return {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top
    };
  };

  const getMousePosInWorldPercent = (rawX: number, rawY: number) => {
     const worldX = (rawX - offset.x) / zoom;
     const worldY = (rawY - offset.y) / zoom;
     return {
       x: (worldX / canvasDims.width) * 100,
       y: (worldY / canvasDims.height) * 100
     };
  };

  const checkHit = (xPct: number, yPct: number) => {
    const THRESHOLD = 4; // 4% radius

    return visibleSpots.find(spot => {
       const dx = spot.x - xPct;
       const dy = spot.y - yPct;
       return Math.sqrt(dx*dx + dy*dy) < THRESHOLD;
    });
  };

  // --- Interaction Handlers ---

  const handleWheel = (e: React.WheelEvent<HTMLCanvasElement>) => {
    e.preventDefault();
    const zoomSensitivity = 0.001;
    const delta = -e.deltaY * zoomSensitivity;
    const newZoom = Math.min(Math.max(zoom + delta, 0.1), 5); 

    if (newZoom === zoom) return;

    const mouse = getRawMousePos(e);
    const worldX = (mouse.x - offset.x) / zoom;
    const worldY = (mouse.y - offset.y) / zoom;

    const newOffsetX = mouse.x - worldX * newZoom;
    const newOffsetY = mouse.y - worldY * newZoom;

    setZoom(newZoom);
    setOffset({ x: newOffsetX, y: newOffsetY });
  };

  const handleMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (e.button === 0) {
      setIsDragging(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (isDragging) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return; 
    }

    const raw = getRawMousePos(e);
    const worldPct = getMousePosInWorldPercent(raw.x, raw.y);
    const hit = checkHit(worldPct.x, worldPct.y);

    if (hit) {
      if (hoveredSpotId !== hit.id) setHoveredSpotId(hit.id);
    } else {
      if (hoveredSpotId !== null) setHoveredSpotId(null);
    }
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const handleClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (isDragging) return;

    const raw = getRawMousePos(e);
    const worldPct = getMousePosInWorldPercent(raw.x, raw.y);
    const hit = checkHit(worldPct.x, worldPct.y);
    if (hit) {
      if (hit.type === 'scene' && hit.sceneId) {
          onInteraction('scene', hit.sceneId);
      } else if (hit.type === 'character' && hit.characterId) {
          onInteraction('character', hit.characterId);
      } else if (hit.type === 'transition' && hit.targetMapId) {
          onInteraction('transition', hit.targetMapId);
      }
    }
  };

  // --- Rendering ---

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.save();

    ctx.fillStyle = '#0f172a'; 
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.translate(offset.x, offset.y);
    ctx.scale(zoom, zoom);

    // Draw World
    const bgImage = new Image();
    if (mapConfig.backgroundSrc) {
       bgImage.src = mapConfig.backgroundSrc;
    }

    const drawScene = () => {
        // Background
        if (mapConfig.backgroundSrc && bgImage.complete) {
            ctx.drawImage(bgImage, 0, 0, canvasDims.width, canvasDims.height);
        } else {
            // Fallback Grid
            ctx.fillStyle = '#1e293b';
            ctx.fillRect(0, 0, canvasDims.width, canvasDims.height);
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 2;
            ctx.strokeRect(0, 0, canvasDims.width, canvasDims.height);
        }

        const toPx = (pct: number, dim: number) => (pct / 100) * dim;

        // Render Spots
        visibleSpots.forEach(spot => {
          const cx = toPx(spot.x, canvasDims.width);
          const cy = toPx(spot.y, canvasDims.height);
          const isHovered = hoveredSpotId === spot.id;

          if (spot.type === 'scene' && spot.sceneId) {
              const scene = scenes.find(s => s.id === spot.sceneId);
              if (!scene) return;

              // Scene Logic (Icon or Character Fallback)
              let spriteImg: HTMLImageElement | undefined;
              let rpgColor = '#ffffff';

              if (scene.mapIconSrc) {
                  spriteImg = spritesRef.current[scene.id];
              } else if (scene.characters.length > 0) {
                  const firstChar = characters.find(c => c.id === scene.characters[0].characterId);
                  if (firstChar) {
                      spriteImg = spritesRef.current[firstChar.id];
                      rpgColor = firstChar.rpgColor;
                  }
              }

              const baseScale = Math.max(canvasDims.width / 1000, 0.5); 
              const targetHeight = (isHovered ? 80 : 70) * baseScale;

              if (spriteImg) {
                  const ratio = spriteImg.naturalWidth / spriteImg.naturalHeight || 1;
                  const drawHeight = targetHeight;
                  const drawWidth = targetHeight * ratio;

                  ctx.save();
                  ctx.shadowColor = isHovered ? 'white' : 'black';
                  ctx.shadowBlur = isHovered ? 15 : 5;
                  ctx.drawImage(spriteImg, cx - drawWidth/2, cy - drawHeight/2, drawWidth, drawHeight);
                  ctx.restore();
              } else {
                  // Fallback
                  ctx.fillStyle = rpgColor;
                  ctx.beginPath();
                  ctx.arc(cx, cy, isHovered ? 14 : 12, 0, Math.PI * 2);
                  ctx.fill();
                  ctx.lineWidth = 2;
                  ctx.strokeStyle = 'white';
                  ctx.stroke();
                  ctx.fillStyle = 'white';
                  ctx.font = 'bold 16px sans-serif';
                  ctx.textAlign = 'center';
                  ctx.textBaseline = 'middle';
                  ctx.fillText('!', cx, cy);
              }

              // Name Tag
              if (isHovered) {
                ctx.save();
                const textScale = Math.max(1 / zoom, 0.5); 
                ctx.translate(cx, cy - (targetHeight / 2) - 14 * textScale);
                ctx.scale(textScale, textScale);

                ctx.fillStyle = 'rgba(0,0,0,0.8)';
                ctx.font = 'bold 16px sans-serif';
                const textW = ctx.measureText(scene.name).width;
                ctx.fillRect(-textW/2 - 8, -20, textW + 16, 28);
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.fillText(scene.name, 0, 0);
                ctx.restore();
              }

          } else if (spot.type === 'character' && spot.characterId) {
             const char = characters.find(c => c.id === spot.characterId);
             if(!char) return;

             const spriteImg = spritesRef.current[char.id];
             const baseScale = Math.max(canvasDims.width / 1000, 0.5); 
             const targetHeight = (isHovered ? 80 : 70) * baseScale;

             if (spriteImg) {
                const ratio = spriteImg.naturalWidth / spriteImg.naturalHeight || 1;
                const drawHeight = targetHeight;
                const drawWidth = targetHeight * ratio;

                ctx.save();
                ctx.shadowColor = isHovered ? 'white' : 'black';
                ctx.shadowBlur = isHovered ? 15 : 5;
                ctx.drawImage(spriteImg, cx - drawWidth/2, cy - drawHeight/2, drawWidth, drawHeight);
                ctx.restore();
             } else {
                ctx.fillStyle = char.rpgColor;
                ctx.beginPath();
                ctx.arc(cx, cy, isHovered ? 14 : 12, 0, Math.PI * 2);
                ctx.fill();
                ctx.lineWidth = 2;
                ctx.strokeStyle = 'white';
                ctx.stroke();
             }

             if (isHovered) {
                ctx.save();
                const textScale = Math.max(1 / zoom, 0.5); 
                ctx.translate(cx, cy - (targetHeight / 2) - 14 * textScale);
                ctx.scale(textScale, textScale);

                ctx.fillStyle = 'rgba(0,0,0,0.8)';
                ctx.font = 'bold 16px sans-serif';
                const textW = ctx.measureText(char.name).width;
                ctx.fillRect(-textW/2 - 8, -20, textW + 16, 28);
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.fillText(char.name, 0, 0);
                ctx.restore();
             }

          } else if (spot.type === 'transition') {
              // Visible Waypoint Marker
              const radius = 16;
              const pulseColor = 'rgba(52, 211, 153, 0.6)';

              if (isHovered) {
                  const time = Date.now() / 300;
                  const pulse = Math.sin(time) * 4 + radius + 4;
                  ctx.beginPath();
                  ctx.arc(cx, cy, pulse, 0, Math.PI * 2);
                  ctx.strokeStyle = pulseColor;
                  ctx.lineWidth = 2;
                  ctx.stroke();
              }

              ctx.beginPath();
              ctx.arc(cx, cy, radius, 0, Math.PI * 2);
              ctx.fillStyle = 'rgba(16, 185, 129, 0.9)'; 
              ctx.fill();
              ctx.strokeStyle = '#6ee7b7'; 
              ctx.lineWidth = 2;
              ctx.stroke();
              ctx.beginPath();
              ctx.arc(cx, cy, 6, 0, Math.PI * 2);
              ctx.fillStyle = '#ffffff';
              ctx.fill();

              if (isHovered) {
                  ctx.save();
                  const targetMapName = maps.find(m => m.id === spot.targetMapId)?.name || 'Unknown Area';
                  const text = `Travel to ${targetMapName}`;
                  const textScale = Math.max(1 / zoom, 0.5); 
                  ctx.translate(cx, cy - 30 * textScale);
                  ctx.scale(textScale, textScale);
                  ctx.fillStyle = 'rgba(0,0,0,0.8)';
                  ctx.font = 'bold 14px sans-serif';
                  const textW = ctx.measureText(text).width;
                  ctx.fillRect(-textW/2 - 8, -18, textW + 16, 26);
                  ctx.fillStyle = '#6ee7b7'; 
                  ctx.textAlign = 'center';
                  ctx.fillText(text, 0, 0);
                  ctx.restore();
              }
          }
        });
    }

    if (bgImage.complete || !mapConfig.backgroundSrc) {
        drawScene();
    } else {
        bgImage.onload = drawScene;
    }

    ctx.restore();

  }, [mapConfig, characters, scenes, hoveredSpotId, spritesLoaded, canvasDims, zoom, offset, visibleSpots]);

  const handleManualSave = () => {
    onSave({ 
        currentMapId: mapConfig.id,
        completedSceneIds: initialState?.completedSceneIds || [],
        unlockedIds: initialState?.unlockedIds || [],
        ongoingScenes: initialState?.ongoingScenes || {}
    });
  };

  const handleZoomIn = () => setZoom(z => Math.min(z + 0.2, 5));
  const handleZoomOut = () => setZoom(z => Math.max(z - 0.2, 0.1));
  const handleResetView = () => {
        if (containerRef.current) {
            const { clientWidth, clientHeight } = containerRef.current;
            const w = canvasDims.width;
            const h = canvasDims.height;
            const scale = Math.min(clientWidth / w, clientHeight / h) * 0.95;
            const newX = (clientWidth - w * scale) / 2;
            const newY = (clientHeight - h * scale) / 2;
            setZoom(scale);
            setOffset({ x: newX, y: newY });
        }
  };

  return (
    <div className="relative w-full h-full bg-gray-950 flex flex-col overflow-hidden">
      {/* HUD */}
      <div className="absolute top-4 left-4 z-10 pointer-events-none">
          <div className="bg-gray-900/80 p-3 rounded-xl border border-gray-700 backdrop-blur-sm shadow-xl pointer-events-auto">
            <h1 className="text-xl font-bold text-indigo-400">{mapConfig.name.toUpperCase()}</h1>
            <p className="text-xs text-gray-400 mt-1">Drag to Pan • Wheel to Zoom</p>
          </div>
      </div>

      {/* Main Canvas Container */}
      <div 
        ref={containerRef}
        className="flex-1 w-full h-full relative overflow-hidden bg-[#0f172a] cursor-grab active:cursor-grabbing"
      >
        <canvas 
          ref={canvasRef}
          width={canvasRef.current?.parentElement?.clientWidth || 1000} 
          height={canvasRef.current?.parentElement?.clientHeight || 750}
          className="block w-full h-full"
          onWheel={handleWheel}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
          onClick={handleClick}
          style={{ touchAction: 'none', cursor: hoveredSpotId ? 'pointer' : 'default' }}
        />
      </div>

      {/* Bottom Controls */}
      <div className="absolute bottom-8 right-8 flex gap-3 z-10">
         <div className="bg-gray-800 rounded-full border border-gray-600 flex overflow-hidden shadow-lg mr-4">
            <button onClick={handleZoomOut} className="p-3 hover:bg-gray-700 text-white transition border-r border-gray-600">
                <ZoomOut size={20} />
            </button>
            <button onClick={handleResetView} className="p-3 hover:bg-gray-700 text-white transition border-r border-gray-600" title="Reset View">
                <Maximize size={20} />
            </button>
            <button onClick={handleZoomIn} className="p-3 hover:bg-gray-700 text-white transition">
                <ZoomIn size={20} />
            </button>
         </div>

         <button onClick={handleManualSave} className="bg-indigo-600 p-3 rounded-full hover:bg-indigo-500 text-white shadow-lg transition transform hover:scale-105" title="Save Game">
           <Save size={24} />
         </button>
         <button onClick={onExit} className="bg-gray-800 p-3 rounded-full hover:bg-red-900/80 text-white border border-gray-600 shadow-lg transition transform hover:scale-105" title="Exit to Editor">
           <LogOut size={24} />
         </button>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Plus, Trash2, Image as ImageIcon, User, Target, Save, PlayCircle, RotateCcw, Map as MapIcon, MousePointerClick, FileUp, Download, Upload, Check, Waypoints, Globe, Lock, Unlock, MessageSquare } from 'lucide-react';
import { Character, Scene, SceneCharacterConfig, WorldMap, MapSpot, UnlockReward } from '../types';
import { Button } from './ui/Button';

interface EditorProps {
  characters: Character[];
  scenes: Scene[];
  maps: WorldMap[];
  onUpdateCharacters: (chars: Character[]) => void;
  onUpdateScenes: (scenes: Scene[]) => void;
  onUpdateMaps: (maps: WorldMap[]) => void;
  onPlay: () => void;
  onQuickSave: () => Promise<boolean>;
  onExportProject: () => void;
  onImportProject: (file: File) => void;
  hasSaveGame: boolean;
  onContinueGame: () => void;
}

export const Editor: React.FC<EditorProps> = ({
  characters,
  scenes,
  maps,
  onUpdateCharacters,
  onUpdateScenes,
  onUpdateMaps,
  onPlay,
  onQuickSave,
  onExportProject,
  onImportProject,
  hasSaveGame,
  onContinueGame
}) => {
  const [activeTab, setActiveTab] = useState<'chars' | 'scenes' | 'map'>('chars');

  // Map Editor State
  const [activeMapId, setActiveMapId] = useState<string>(maps[0]?.id || '');
  const [selectedTool, setSelectedTool] = useState<{type: 'scene'|'transition'|'character', id: string} | null>(null);

  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const importInputRef = useRef<HTMLInputElement>(null);

  // --- Character Handlers ---
  const addCharacter = () => {
    const newChar: Character = {
      id: crypto.randomUUID(),
      name: 'New Character',
      defaultDescription: 'A friendly helper.',
      imageSrc: null,
      mapSpriteSrc: null,
      rpgColor: '#ef4444', 
    };
    onUpdateCharacters([...characters, newChar]);
  };

  const updateCharacter = (id: string, updates: Partial<Character>) => {
    onUpdateCharacters(characters.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const handleCharImageUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>, field: 'imageSrc' | 'mapSpriteSrc') => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCharacter(id, { [field]: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  // --- Scene Handlers ---
  const addScene = () => {
    const newScene: Scene = {
      id: crypto.randomUUID(),
      name: `Scene ${scenes.length + 1}`,
      backgroundSrc: null,
      description: 'You are in a quiet room.',
      goal: 'Say hello.',
      characters: [],
      unlocks: [],
      mapIconSrc: null
    };
    onUpdateScenes([...scenes, newScene]);
  };

  const updateScene = (id: string, updates: Partial<Scene>) => {
    onUpdateScenes(scenes.map(s => s.id === id ? { ...s, ...updates } : s));
  };

  const handleSceneIconUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { mapIconSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleUnlock = (sceneId: string, type: 'scene' | 'transition', targetId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const currentUnlocks = scene.unlocks || [];
    const exists = currentUnlocks.some(u => u.type === type && u.targetId === targetId);

    let newUnlocks;
    if (exists) {
        newUnlocks = currentUnlocks.filter(u => !(u.type === type && u.targetId === targetId));
    } else {
        newUnlocks = [...currentUnlocks, { type, targetId }];
    }
    updateScene(sceneId, { unlocks: newUnlocks });
  };

  const handleBgUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleCharInScene = (sceneId: string, charId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const exists = scene.characters.find(c => c.characterId === charId);
    let newChars: SceneCharacterConfig[];

    if (exists) {
      newChars = scene.characters.filter(c => c.characterId !== charId);
    } else {
      newChars = [...scene.characters, { characterId: charId, roleInScene: 'Default behavior' }];
    }
    updateScene(sceneId, { characters: newChars });
  };

  const updateSceneCharRole = (sceneId: string, charId: string, role: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;
    const newChars = scene.characters.map(c => c.characterId === charId ? { ...c, roleInScene: role } : c);
    updateScene(sceneId, { characters: newChars });
  };

  // --- Map Handlers ---

  const getCurrentMap = () => maps.find(m => m.id === activeMapId);

  const addMap = () => {
      const newMap: WorldMap = {
          id: crypto.randomUUID(),
          name: `Map ${maps.length + 1}`,
          backgroundSrc: null,
          spots: []
      };
      const newMaps = [...maps, newMap];
      onUpdateMaps(newMaps);
      setActiveMapId(newMap.id);
  };

  const deleteMap = (id: string) => {
      if (maps.length <= 1) {
          alert("You must have at least one map.");
          return;
      }
      const newMaps = maps.filter(m => m.id !== id);
      onUpdateMaps(newMaps);
      if (activeMapId === id) setActiveMapId(newMaps[0].id);
  };

  const updateCurrentMap = (updates: Partial<WorldMap>) => {
      onUpdateMaps(maps.map(m => m.id === activeMapId ? { ...m, ...updates } : m));
  };

  const handleMapBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCurrentMap({ backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const handleMapClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!selectedTool || !mapContainerRef.current) return;

    // Check if clicked on an existing pin
    if ((e.target as HTMLElement).closest('.map-pin')) return;

    const rect = mapContainerRef.current.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;

    const currentMap = getCurrentMap();
    if (!currentMap) return;

    const newSpot: MapSpot = {
      id: crypto.randomUUID(),
      type: selectedTool.type,
      x, 
      y,
      sceneId: selectedTool.type === 'scene' ? selectedTool.id : undefined,
      targetMapId: selectedTool.type === 'transition' ? selectedTool.id : undefined,
      characterId: selectedTool.type === 'character' ? selectedTool.id : undefined,
    };

    updateCurrentMap({ spots: [...currentMap.spots, newSpot] });
  };

  const removeSpot = (spotId: string) => {
    const currentMap = getCurrentMap();
    if(!currentMap) return;
    updateCurrentMap({
      spots: currentMap.spots.filter(s => s.id !== spotId)
    });
  };

  // --- Toolbar Handlers ---

  const handleQuickSaveClick = async () => {
    setSaveStatus('saving');
    await onQuickSave();
    setSaveStatus('saved');
    setTimeout(() => setSaveStatus('idle'), 2000);
  };

  const handleImportClick = () => {
    importInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if(e.target.files && e.target.files[0]) {
        onImportProject(e.target.files[0]);
    }
    if(e.target.value) e.target.value = ''; 
  };

  const currentMap = getCurrentMap();

  return (
    <div className="flex flex-col h-full max-w-6xl mx-auto p-4 md:p-8">
      {/* Header / Toolbar */}
      <div className="flex flex-col xl:flex-row justify-between items-center mb-8 gap-6">
        <div>
           <h1 className="text-3xl font-bold text-indigo-400">VN Creator Studio</h1>
           <p className="text-gray-400 text-sm mt-1">Design your world, characters, and stories.</p>
        </div>

        <div className="flex flex-wrap gap-3 items-center justify-center">
          {/* File Operations */}
          <div className="flex gap-2 mr-2 bg-gray-800 p-1 rounded-lg border border-gray-700">
             <input type="file" ref={importInputRef} className="hidden" accept=".json" onChange={handleFileChange} />

             <button onClick={handleImportClick} className="flex items-center gap-2 px-3 py-2 text-sm text-gray-300 hover:text-white hover:bg-gray-700 rounded transition" title="Load .json file">
               <Upload size={16} /> Load Project
             </button>

             <div className="w-[1px] bg-gray-600 my-1"></div>

             <button onClick={onExportProject} className="flex items-center gap-2 px-3 py-2 text-sm text-gray-300 hover:text-white hover:bg-gray-700 rounded transition" title="Download .json file">
               <Download size={16} /> Export Project
             </button>
          </div>

          <Button 
            onClick={handleQuickSaveClick} 
            variant="secondary" 
            title="Saves to Browser Storage"
            className="min-w-[140px]"
            disabled={saveStatus === 'saving'}
          >
            {saveStatus === 'saved' ? <><Check size={18} className="text-green-400"/> Saved!</> : (saveStatus === 'saving' ? 'Saving...' : <><Save size={18} /> Quick Save</>)}
          </Button>

          <div className="h-8 w-[1px] bg-gray-700 mx-2 hidden md:block"></div>

          {hasSaveGame && (
            <Button onClick={onContinueGame} className="bg-yellow-600 hover:bg-yellow-500">
              <RotateCcw size={18} /> Continue
            </Button>
          )}

          <Button onClick={onPlay} className="bg-green-600 hover:bg-green-500 px-6 font-bold shadow-green-900/20">
            <PlayCircle size={18} /> PLAY GAME
          </Button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex gap-4 mb-6 border-b border-gray-700 pb-1">
        <button
          onClick={() => setActiveTab('chars')}
          className={`px-4 py-2 font-medium transition-colors ${activeTab === 'chars' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}
        >
          Characters
        </button>
        <button
          onClick={() => setActiveTab('scenes')}
          className={`px-4 py-2 font-medium transition-colors ${activeTab === 'scenes' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}
        >
          Scenarios
        </button>
        <button
          onClick={() => setActiveTab('map')}
          className={`px-4 py-2 font-medium transition-colors ${activeTab === 'map' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}
        >
          World Map
        </button>
      </div>

      <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
        {activeTab === 'chars' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {characters.map(char => (
                <div key={char.id} className="bg-gray-800 p-4 rounded-xl border border-gray-700 flex gap-4 shadow-lg hover:border-gray-600 transition-colors">

                  {/* Portrait (Left) */}
                  <div className="w-24 h-32 bg-gray-900 rounded-lg flex-shrink-0 border border-gray-600 overflow-hidden relative group">
                    {char.imageSrc ? (
                      <img src={char.imageSrc} alt={char.name} className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full flex flex-col items-center justify-center text-gray-600 gap-1">
                        <User size={24} />
                        <span className="text-[10px] text-center px-1">Portrait</span>
                      </div>
                    )}
                    <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity text-xs font-bold">
                      UPLOAD
                      <input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e, 'imageSrc')} />
                    </label>
                  </div>

                  <div className="flex-1 space-y-3">
                    <input
                      className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-1 focus:border-indigo-500 outline-none transition-all"
                      value={char.name}
                      onChange={(e) => updateCharacter(char.id, { name: e.target.value })}
                      placeholder="Character Name"
                    />

                    {/* Map Sprite Uploader */}
                    <div className="flex items-center gap-3">
                       <div className="w-12 h-12 bg-gray-900 rounded border border-gray-600 overflow-hidden relative group shrink-0">
                         {char.mapSpriteSrc ? (
                           <img src={char.mapSpriteSrc} alt="Sprite" className="w-full h-full object-contain" />
                         ) : (
                           <div className="w-full h-full flex items-center justify-center text-gray-600" title="Map Sprite">
                             <MapIcon size={16} />
                           </div>
                         )}
                         <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity">
                            <FileUp size={16} className="text-white"/>
                            <input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e, 'mapSpriteSrc')} />
                         </label>
                       </div>
                       <div className="text-xs text-gray-400">
                         <span className="font-bold block text-gray-300">Map Sprite</span>
                         <span className="text-[10px]">Icon used on the world map.</span>
                       </div>
                    </div>

                    <textarea
                      className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-1 h-20 text-sm focus:border-indigo-500 outline-none resize-none transition-all"
                      value={char.defaultDescription}
                      onChange={(e) => updateCharacter(char.id, { defaultDescription: e.target.value })}
                      placeholder="Core Persona/Description..."
                    />
                  </div>
                  <button onClick={() => onUpdateCharacters(characters.filter(c => c.id !== char.id))} className="text-gray-500 hover:text-red-500 h-fit transition-colors p-1">
                    <Trash2 size={18} />
                  </button>
                </div>
              ))}
            </div>
            <Button onClick={addCharacter} variant="secondary" className="w-full py-4 border-dashed opacity-70 hover:opacity-100">
              <Plus size={20} /> Add Character
            </Button>
          </div>
        )}

        {activeTab === 'scenes' && (
          <div className="space-y-8">
            {scenes.map((scene, idx) => (
              <div key={scene.id} className="bg-gray-800 p-6 rounded-xl border border-gray-700 space-y-4 shadow-lg">
                <div className="flex justify-between items-start">
                  <div className="flex items-center gap-4">
                    <div className="bg-gray-900 px-3 py-1 rounded text-xs font-bold text-indigo-400 border border-gray-700">SCENE {idx + 1}</div>
                    <input
                       className="bg-transparent text-xl font-bold outline-none placeholder-gray-600 focus:text-white transition-colors"
                       value={scene.name}
                       onChange={(e) => updateScene(scene.id, { name: e.target.value })}
                       placeholder="Scene Name"
                    />
                  </div>
                  <button onClick={() => onUpdateScenes(scenes.filter(s => s.id !== scene.id))} className="text-gray-500 hover:text-red-500 transition-colors p-1">
                    <Trash2 size={18} />
                  </button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                  {/* Visuals & Goal */}
                  <div className="space-y-4">
                    <div className="w-full h-40 bg-gray-900 rounded-lg border border-gray-600 overflow-hidden relative group shadow-inner">
                       {scene.backgroundSrc ? (
                          <img src={scene.backgroundSrc} alt="bg" className="w-full h-full object-cover opacity-80" />
                       ) : (
                         <div className="w-full h-full flex items-center justify-center text-gray-500 gap-2">
                           <ImageIcon size={24} /> No Background
                         </div>
                       )}
                       <label className="absolute inset-0 flex items-center justify-center cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity bg-black/40">
                          <span className="bg-black/80 px-4 py-2 rounded hover:bg-black text-sm border border-gray-600">Change Background</span>
                          <input type="file" accept="image/*" className="hidden" onChange={(e) => handleBgUpload(scene.id, e)} />
                       </label>
                    </div>

                    {/* Map Icon Override */}
                    <div className="flex items-center gap-3 bg-gray-900/50 p-2 rounded border border-gray-700">
                       <div className="w-10 h-10 bg-gray-900 rounded border border-gray-600 overflow-hidden relative group shrink-0">
                         {scene.mapIconSrc ? (
                           <img src={scene.mapIconSrc} alt="Icon" className="w-full h-full object-contain" />
                         ) : (
                            // Show first character sprite if available as preview
                            scene.characters.length > 0 && characters.find(c => c.id === scene.characters[0].characterId)?.mapSpriteSrc ? (
                                <img src={characters.find(c => c.id === scene.characters[0].characterId)?.mapSpriteSrc!} className="w-full h-full object-contain opacity-50 grayscale" title="Default: First Character" />
                            ) : (
                                <div className="w-full h-full flex items-center justify-center text-gray-600" title="Map Icon">
                                    <MapIcon size={14} />
                                </div>
                            )
                         )}
                         <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity">
                            <FileUp size={12} className="text-white"/>
                            <input type="file" accept="image/*" className="hidden" onChange={(e) => handleSceneIconUpload(scene.id, e)} />
                         </label>
                       </div>
                       <div className="text-xs text-gray-400">
                         <span className="font-bold block text-gray-300">Map Icon (Optional)</span>
                         <span className="text-[10px]">Overrides character sprite on map.</span>
                       </div>
                    </div>

                    <div>
                      <label className="flex items-center gap-2 text-xs font-bold text-green-400 mb-1">
                        <Target size={14} /> WIN CONDITION
                      </label>
                      <textarea
                        className="w-full bg-gray-900 border border-green-900/50 text-green-100 rounded px-3 py-2 text-sm focus:border-green-500 outline-none resize-none transition-all shadow-inner"
                        value={scene.goal}
                        onChange={(e) => updateScene(scene.id, { goal: e.target.value })}
                        placeholder="e.g. Find the key..."
                        rows={3}
                      />
                    </div>

                    {/* Rewards / Unlocks Configuration */}
                    <div className="bg-gray-900/50 p-3 rounded-lg border border-gray-700">
                        <label className="flex items-center gap-2 text-xs font-bold text-yellow-500 mb-2">
                            <Unlock size={14} /> UNLOCKS ON COMPLETION
                        </label>
                        <p className="text-[10px] text-gray-500 mb-2">Select Scenarios or Maps that become available after this.</p>

                        <div className="space-y-2 max-h-32 overflow-y-auto custom-scrollbar">
                            {/* Other Scenes */}
                            {scenes.filter(s => s.id !== scene.id).map(otherScene => {
                                const isUnlocked = scene.unlocks?.some(u => u.type === 'scene' && u.targetId === otherScene.id);
                                return (
                                    <button 
                                        key={otherScene.id} 
                                        onClick={() => toggleUnlock(scene.id, 'scene', otherScene.id)}
                                        className={`w-full flex items-center gap-2 text-xs p-1.5 rounded border ${isUnlocked ? 'bg-yellow-900/30 border-yellow-600 text-yellow-100' : 'bg-gray-800 border-gray-700 text-gray-400 hover:border-gray-500'}`}
                                    >
                                        {isUnlocked ? <Unlock size={10} /> : <Lock size={10} />}
                                        <span className="truncate">Scene: {otherScene.name}</span>
                                    </button>
                                );
                            })}

                            {/* Maps */}
                            {maps.map(m => {
                                const isUnlocked = scene.unlocks?.some(u => u.type === 'transition' && u.targetId === m.id);
                                return (
                                    <button 
                                        key={m.id} 
                                        onClick={() => toggleUnlock(scene.id, 'transition', m.id)}
                                        className={`w-full flex items-center gap-2 text-xs p-1.5 rounded border ${isUnlocked ? 'bg-emerald-900/30 border-emerald-600 text-emerald-100' : 'bg-gray-800 border-gray-700 text-gray-400 hover:border-gray-500'}`}
                                    >
                                        {isUnlocked ? <Globe size={10} /> : <Lock size={10} />}
                                        <span className="truncate">Travel to: {m.name}</span>
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                  </div>

                  {/* Narrative Setup */}
                  <div className="space-y-2 lg:col-span-2">
                     <label className="block text-xs font-bold text-gray-400">SCENARIO DESCRIPTION (For AI)</label>
                     <textarea
                        className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-2 text-sm focus:border-indigo-500 outline-none resize-none transition-all"
                        value={scene.description}
                        onChange={(e) => updateScene(scene.id, { description: e.target.value })}
                        placeholder="Describe the setting, the mood, and what is happening..."
                        rows={3}
                      />

                      <label className="block text-xs font-bold text-gray-400 mt-4">PARTICIPATING CHARACTERS</label>
                      <div className="bg-gray-900 rounded-lg p-3 border border-gray-700 min-h-[100px] shadow-inner">
                         <div className="flex gap-2 flex-wrap mb-3">
                           {characters.map(char => {
                             const isActive = scene.characters.some(c => c.characterId === char.id);
                             return (
                               <button
                                 key={char.id}
                                 onClick={() => toggleCharInScene(scene.id, char.id)}
                                 className={`text-xs px-3 py-1 rounded-full border transition-all ${isActive ? 'bg-indigo-600 border-indigo-400 text-white shadow-md' : 'bg-gray-800 border-gray-600 text-gray-400 hover:border-gray-400 hover:text-gray-300'}`}
                               >
                                 {char.name}
                               </button>
                             )
                           })}
                           {characters.length === 0 && <span className="text-xs text-gray-600 italic">No characters created yet.</span>}
                         </div>

                         {/* Per-Scene Character Logic */}
                         <div className="space-y-3">
                           {scene.characters.map(sc => {
                             const char = characters.find(c => c.id === sc.characterId);
                             if (!char) return null;
                             return (
                               <div key={sc.characterId} className="flex items-center gap-3 bg-gray-800 p-2 rounded border border-gray-700">
                                 <div className="w-8 h-8 rounded-full bg-gray-700 overflow-hidden flex-shrink-0 border border-gray-600" style={{ backgroundColor: char.rpgColor }}>
                                   {char.imageSrc && <img src={char.imageSrc} className="w-full h-full object-cover" />}
                                 </div>
                                 <div className="flex-1">
                                    <div className="text-xs font-bold text-indigo-300">{char.name} Role</div>
                                    <input 
                                      className="w-full bg-transparent border-b border-gray-600 text-xs py-1 focus:border-indigo-400 outline-none transition-colors"
                                      placeholder="What does this character want in this scene?"
                                      value={sc.roleInScene}
                                      onChange={(e) => updateSceneCharRole(scene.id, sc.characterId, e.target.value)}
                                    />
                                 </div>
                               </div>
                             )
                           })}
                           {scene.characters.length === 0 && <div className="text-xs text-gray-500 text-center py-4">Select characters above to assign roles.</div>}
                         </div>
                      </div>
                  </div>
                </div>
              </div>
            ))}
            <Button onClick={addScene} variant="secondary" className="w-full py-4 border-dashed opacity-70 hover:opacity-100">
              <Plus size={20} /> Add Scenario
            </Button>
          </div>
        )}

        {activeTab === 'map' && (
          <div className="flex flex-col lg:flex-row gap-6 h-full">
            {/* Sidebar Controls */}
            <div className="w-full lg:w-64 flex flex-col gap-6">

              {/* Map Switcher */}
              <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 shadow-lg space-y-3">
                  <div className="flex items-center justify-between mb-2">
                     <h3 className="font-bold text-gray-300 flex items-center gap-2"><Globe size={16}/> Maps</h3>
                     <button onClick={addMap} className="text-indigo-400 hover:text-white p-1 rounded bg-indigo-900/30 hover:bg-indigo-600 transition">
                         <Plus size={14} />
                     </button>
                  </div>

                  <div className="space-y-2 max-h-32 overflow-y-auto custom-scrollbar">
                     {maps.map(m => (
                         <div key={m.id} className={`flex items-center justify-between p-2 rounded cursor-pointer border ${m.id === activeMapId ? 'bg-indigo-900/50 border-indigo-500' : 'bg-gray-900 border-gray-800 hover:border-gray-600'}`} onClick={() => setActiveMapId(m.id)}>
                             <span className="text-xs truncate max-w-[120px]">{m.name}</span>
                             {maps.length > 1 && (
                                 <button onClick={(e) => { e.stopPropagation(); deleteMap(m.id); }} className="text-gray-600 hover:text-red-400">
                                     <Trash2 size={12} />
                                 </button>
                             )}
                         </div>
                     ))}
                  </div>

                  {currentMap && (
                      <div className="pt-2 border-t border-gray-700">
                         <input 
                            className="w-full bg-gray-900 border border-gray-600 rounded px-2 py-1 text-xs text-gray-200 outline-none focus:border-indigo-500"
                            value={currentMap.name}
                            onChange={(e) => updateCurrentMap({ name: e.target.value })}
                            placeholder="Map Name"
                         />
                      </div>
                  )}
              </div>

              {/* Map Background Config */}
              {currentMap && (
                  <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 shadow-lg">
                    <h3 className="font-bold text-gray-300 mb-3 flex items-center gap-2 text-sm"><MapIcon size={14}/> Background</h3>
                    <label className="block w-full cursor-pointer bg-gray-900 border border-gray-600 hover:border-gray-400 hover:bg-gray-800 text-center py-4 rounded-lg border-dashed transition-all group">
                    <span className="text-xs text-gray-400 group-hover:text-white">Change Image</span>
                    <input type="file" accept="image/*" className="hidden" onChange={handleMapBgUpload} />
                    </label>
                </div>
              )}

              {/* Tools: Scenes & Transitions */}
              <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 flex-1 shadow-lg flex flex-col min-h-[300px]">
                 <h3 className="font-bold text-gray-300 mb-3 flex items-center gap-2 text-sm"><User size={14}/> Place Items</h3>
                 <p className="text-xs text-gray-500 mb-4">Select an item, then click on the map to place.</p>

                 <div className="space-y-4 overflow-y-auto custom-scrollbar flex-1">
                    {/* SCENES */}
                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2">Scenarios</div>
                        <div className="space-y-1">
                            {scenes.map(scene => {
                                // Determine icon to show in sidebar
                                let iconSrc = scene.mapIconSrc;
                                let bgColor = '#4b5563';
                                if (!iconSrc && scene.characters.length > 0) {
                                    const char = characters.find(c => c.id === scene.characters[0].characterId);
                                    if(char) {
                                        iconSrc = char.mapSpriteSrc;
                                        bgColor = char.rpgColor;
                                    }
                                }

                                return (
                                <button 
                                    key={scene.id}
                                    onClick={() => setSelectedTool(selectedTool?.id === scene.id ? null : { type: 'scene', id: scene.id })}
                                    className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === scene.id && selectedTool.type === 'scene' ? 'bg-indigo-600/20 border-indigo-500 ring-1 ring-indigo-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}
                                >
                                    <div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 overflow-hidden flex items-center justify-center flex-shrink-0" style={{ backgroundColor: bgColor }}>
                                        {iconSrc ? <img src={iconSrc} className="w-full h-full object-contain" /> : <MessageSquare size={12} className="text-gray-400"/>}
                                    </div>
                                    <span className="text-xs font-medium truncate flex-1 text-left">{scene.name}</span>
                                    {selectedTool?.id === scene.id && selectedTool.type === 'scene' && <MousePointerClick size={12} className="ml-auto text-indigo-400"/>}
                                </button>
                                );
                            })}
                        </div>
                    </div>

                    {/* CHARACTERS (Generic) */}
                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2 mt-4">Characters</div>
                        <div className="space-y-1">
                            {characters.map(char => (
                                <button 
                                    key={char.id}
                                    onClick={() => setSelectedTool(selectedTool?.id === char.id ? null : { type: 'character', id: char.id })}
                                    className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === char.id && selectedTool.type === 'character' ? 'bg-indigo-600/20 border-indigo-500 ring-1 ring-indigo-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}
                                >
                                    <div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 overflow-hidden flex items-center justify-center flex-shrink-0" style={{ backgroundColor: char.rpgColor }}>
                                        {char.mapSpriteSrc ? <img src={char.mapSpriteSrc} className="w-full h-full object-contain" /> : null}
                                    </div>
                                    <span className="text-xs font-medium truncate flex-1 text-left">{char.name}</span>
                                    {selectedTool?.id === char.id && selectedTool.type === 'character' && <MousePointerClick size={12} className="ml-auto text-indigo-400"/>}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Transitions */}
                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2 mt-4">Map Transitions</div>
                        <div className="space-y-1">
                            {maps.filter(m => m.id !== activeMapId).map(targetMap => (
                                <button
                                    key={targetMap.id}
                                    onClick={() => setSelectedTool(selectedTool?.id === targetMap.id ? null : { type: 'transition', id: targetMap.id })}
                                    className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === targetMap.id && selectedTool.type === 'transition' ? 'bg-emerald-600/20 border-emerald-500 ring-1 ring-emerald-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}
                                >
                                    <div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 flex items-center justify-center flex-shrink-0 text-emerald-500">
                                        <Waypoints size={14} />
                                    </div>
                                    <span className="text-xs font-medium truncate flex-1 text-left">To: {targetMap.name}</span>
                                    {selectedTool?.id === targetMap.id && selectedTool.type === 'transition' && <MousePointerClick size={12} className="ml-auto text-emerald-400"/>}
                                </button>
                            ))}
                            {maps.length <= 1 && <div className="text-xs text-gray-600 italic px-2">Create another map to link to.</div>}
                        </div>
                    </div>
                 </div>
              </div>
            </div>

            {/* Map Canvas */}
            <div className="flex-1 bg-gray-900 rounded-xl border-[4px] border-gray-800 shadow-2xl overflow-hidden relative group">
                {currentMap && currentMap.backgroundSrc ? (
                   <div 
                      ref={mapContainerRef}
                      onClick={handleMapClick}
                      className="relative w-full h-full cursor-crosshair"
                   >
                      <img 
                        src={currentMap.backgroundSrc} 
                        alt="World Map" 
                        className="w-full h-full object-contain bg-black select-none pointer-events-none" 
                      />

                      {/* Render Spots */}
                      {currentMap.spots.map(spot => {
                         if (spot.type === 'scene') {
                             // SCENE RENDERING
                             const scene = scenes.find(s => s.id === spot.sceneId);

                             // Resolve visual
                             let iconSrc = scene?.mapIconSrc;
                             let bgColor = '#ffffff';
                             let name = scene?.name || 'Unknown Scene';

                             // Fallback to character icon logic if no override
                             if (scene && !iconSrc && scene.characters.length > 0) {
                                const char = characters.find(c => c.id === scene.characters[0].characterId);
                                if(char) {
                                    iconSrc = char.mapSpriteSrc;
                                    bgColor = char.rpgColor;
                                }
                             }

                             return (
                                <div 
                                  key={spot.id}
                                  className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin"
                                  style={{ left: `${spot.x}%`, top: `${spot.y}%` }}
                                >
                                   {/* Sprite Render */}
                                   <div className="w-12 h-12 relative drop-shadow-lg transition hover:scale-110 flex items-center justify-center">
                                       {iconSrc ? (
                                           <img src={iconSrc} alt={name} className="w-full h-full object-contain" />
                                       ) : (
                                           <div className="w-6 h-6 rounded-full border border-white shadow-sm flex items-center justify-center bg-gray-700 text-white" style={{backgroundColor: bgColor}}>
                                               <MessageSquare size={12} />
                                           </div>
                                       )}
                                   </div>

                                   <span className="bg-black/70 text-[10px] px-2 rounded text-white whitespace-nowrap mt-1 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none backdrop-blur-sm">{name}</span>
                                   <button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110">
                                     <Trash2 size={12} />
                                   </button>
                                </div>
                             )
                         } else if (spot.type === 'character') {
                             // CHARACTER RENDERING
                             const char = characters.find(c => c.id === spot.characterId);
                             const name = char?.name || 'Unknown';

                             return (
                                <div 
                                  key={spot.id}
                                  className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin"
                                  style={{ left: `${spot.x}%`, top: `${spot.y}%` }}
                                >
                                   <div className="w-12 h-12 relative drop-shadow-lg transition hover:scale-110 flex items-center justify-center">
                                       {char?.mapSpriteSrc ? (
                                           <img src={char.mapSpriteSrc} alt={name} className="w-full h-full object-contain" />
                                       ) : (
                                           <div className="w-4 h-4 rounded-full border border-white shadow-sm mb-1" style={{ backgroundColor: char?.rpgColor }} />
                                       )}
                                   </div>

                                   <span className="bg-black/70 text-[10px] px-2 rounded text-white whitespace-nowrap mt-1 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none backdrop-blur-sm">{name}</span>
                                   <button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110">
                                     <Trash2 size={12} />
                                   </button>
                                </div>
                             )
                         } else {
                             // Transition Spot
                             const target = maps.find(m => m.id === spot.targetMapId);
                             return (
                                <div 
                                  key={spot.id}
                                  className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin"
                                  style={{ left: `${spot.x}%`, top: `${spot.y}%` }}
                                >
                                   {/* Transition Icon */}
                                   <div className="w-8 h-8 rounded-full bg-emerald-500/50 border-2 border-emerald-400 flex items-center justify-center shadow-lg hover:scale-110 transition">
                                       <Waypoints size={16} className="text-white" />
                                   </div>

                                   <span className="bg-emerald-900/90 text-[10px] px-2 rounded text-emerald-100 whitespace-nowrap mt-1 opacity-100 transition-opacity pointer-events-none backdrop-blur-sm border border-emerald-700">Go to: {target?.name || 'Unknown'}</span>
                                   <button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110">
                                     <Trash2 size={12} />
                                   </button>
                                </div>
                             )
                         }
                      })}
                   </div>
                ) : (
                  <div className="w-full h-full flex flex-col items-center justify-center text-gray-600 gap-4">
                    {currentMap ? (
                        <>
                            <MapIcon size={48} opacity={0.5} />
                            <p>Upload a background for {currentMap.name}.</p>
                        </>
                    ) : (
                        <p>No map selected.</p>
                    )}
                  </div>
                )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export interface Character {
  id: string;
  name: string;
  defaultDescription: string;
  imageSrc: string | null; // Portrait for VN (Large)
  mapSpriteSrc: string | null; // Sprite for Map (Small/Icon)
  rpgColor: string; // Fallback Hex color
}

export interface SceneCharacterConfig {
  characterId: string;
  roleInScene: string; // Specific behavior/goal for this scene
}

export interface SceneEffect {
  type: 'scene' | 'transition';
  targetId: string; // Scene ID or Target Map ID
  action: 'unlock' | 'lock'; // New: Choose whether to enable or disable the target
}

export interface Scene {
  id: string;
  name: string;
  backgroundSrc: string | null; // Local object URL
  description: string; // The scenario setup
  goal: string; // The win condition to move to next scene
  characters: SceneCharacterConfig[];
  effects?: SceneEffect[]; // Renamed from 'unlocks' to 'effects' to handle locking too

  // New: Visual override for the map
  mapIconSrc?: string | null; 
}

export interface MapSpot {
  id: string;
  x: number; // Percentage 0-100
  y: number; // Percentage 0-100
  type: 'scene' | 'transition' | 'character';

  // If type === 'scene'
  sceneId?: string; // DIRECT link to a specific scene

  // If type === 'character'
  characterId?: string; // GENERIC link to a character (finds next scene)

  // If type === 'transition'
  targetMapId?: string;
}

export interface WorldMap {
  id: string;
  name: string;
  backgroundSrc: string | null;
  spots: MapSpot[];
}

export interface ChatMessage {
  sender: 'user' | 'model' | 'system';
  characterId?: string; // If model, which character?
  text: string;
  timestamp: number;
}

export interface GameState {
  currentSceneIndex: number; // Used inside VN Mode
  history: ChatMessage[];
  isProcessing: boolean;
  gameOver: boolean;
}

export interface AIResponse {
  characterResponses: {
    characterId: string;
    text: string;
  }[];
  sceneGoalReached: boolean;
  sceneTransitionReason?: string;
}

export interface RPGState {
  currentMapId: string;
  completedSceneIds: string[];
  unlockedIds: string[]; // IDs of Scenes or Maps that have been unlocked
  hiddenIds: string[]; // New: IDs of Scenes or Maps that have been locked/hidden
  ongoingScenes: Record<string, ChatMessage[]>; // Stores history for incomplete scenes { sceneId: history[] }
}

export interface GameSaveData {
  rpgState: RPGState;
  vnState: GameState | null; // Null if saved while on map
  timestamp: number;
}

import React, { useState, useEffect } from 'react';
import { Editor } from './components/Editor';
import { Player } from './components/Player';
import { RPGWorld } from './components/RPGWorld';
import { Character, Scene, GameSaveData, RPGState, WorldMap, ChatMessage } from './types';
import { getItem, setItem } from './utils/db';

// Default Data for quick start
const DEFAULT_CHARS: Character[] = [
  { 
    id: '1', 
    name: 'Aiko', 
    defaultDescription: 'A cheerful and curious android girl who loves learning about humans.', 
    imageSrc: null,
    mapSpriteSrc: null,
    rpgColor: '#f472b6' // Pink
  },
  { 
    id: '2', 
    name: 'Kael', 
    defaultDescription: 'A grumpy but skilled mechanic who fixes robots.', 
    imageSrc: null,
    mapSpriteSrc: null,
    rpgColor: '#60a5fa' // Blue
  }
];

const DEFAULT_SCENES: Scene[] = [
  {
    id: 's1',
    name: 'The Workshop',
    backgroundSrc: null,
    description: 'A cluttered workshop filled with robot parts. Kael is working on a workbench. Aiko is watching closely.',
    goal: 'Convince Kael to fix your broken radio.',
    characters: [
      { characterId: '1', roleInScene: 'Curious onlooker, wants to help but is clumsy.' },
      { characterId: '2', roleInScene: 'Busy, easily annoyed, does not want to be disturbed.' }
    ],
    effects: []
  }
];

const DEFAULT_MAPS: WorldMap[] = [
  {
    id: 'map1',
    name: 'Main City',
    backgroundSrc: null,
    spots: [
      { id: 'spot1', type: 'character', characterId: '1', x: 50, y: 50 },
    ]
  }
];

const PROJECT_STORAGE_KEY = 'vn_creator_project';
const GAME_SAVE_KEY = 'vn_creator_savegame';

const App: React.FC = () => {
  const [mode, setMode] = useState<'edit' | 'rpg' | 'vn'>('edit');

  // Data State
  const [characters, setCharacters] = useState<Character[]>(DEFAULT_CHARS);
  const [scenes, setScenes] = useState<Scene[]>(DEFAULT_SCENES);
  const [maps, setMaps] = useState<WorldMap[]>(DEFAULT_MAPS);

  // Game Play State
  const [rpgState, setRpgState] = useState<RPGState>({ 
    currentMapId: 'map1', 
    completedSceneIds: [],
    unlockedIds: [],
    hiddenIds: [],
    ongoingScenes: {}
  });

  const [activeSceneIndex, setActiveSceneIndex] = useState<number>(-1);
  const [vnHistory, setVnHistory] = useState<ChatMessage[]>([]); 

  const [hasSaveGame, setHasSaveGame] = useState(false);

  // Check for save game on mount and migrate from LocalStorage if needed
  useEffect(() => {
    const initLoad = async () => {
        // 1. Check for Save Game
        const savedGame = await getItem<GameSaveData>(GAME_SAVE_KEY);
        if (savedGame) {
            setHasSaveGame(true);
        } else {
            const lsSave = localStorage.getItem(GAME_SAVE_KEY);
            if (lsSave) {
                setHasSaveGame(true);
            }
        }

        // 2. Load Project Data
        let data: any = await getItem(PROJECT_STORAGE_KEY);

        if (!data) {
            const lsProject = localStorage.getItem(PROJECT_STORAGE_KEY);
            if (lsProject) {
                try {
                    data = JSON.parse(lsProject);
                    await setItem(PROJECT_STORAGE_KEY, data);
                    localStorage.removeItem(PROJECT_STORAGE_KEY);
                } catch (e) {
                    console.error("Failed to parse legacy local storage", e);
                }
            }
        }

        // Apply Data
        if (data) {
            if (data.characters) setCharacters(data.characters);

            // Migration: rename unlocks -> effects if needed
            if (data.scenes) {
                const migratedScenes = data.scenes.map((s: any) => ({
                    ...s,
                    effects: s.effects || s.unlocks || [] // handle legacy 'unlocks' key
                }));
                setScenes(migratedScenes);
            }

            if (data.mapConfig && !data.maps) {
                setMaps([{ ...data.mapConfig, id: 'map1', name: 'Default Map' }]);
            } else if (data.maps) {
                setMaps(data.maps);
            }
        }
    };
    initLoad();
  }, []);

  const handleQuickSave = async () => {
    const data = { characters, scenes, maps };
    await setItem(PROJECT_STORAGE_KEY, data);
    return true;
  };

  const handleExportProject = () => {
    const data = { characters, scenes, maps };
    const jsonString = JSON.stringify(data, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const href = URL.createObjectURL(blob);

    const link = document.createElement('a');
    link.href = href;
    link.download = `vn-project-${new Date().toISOString().slice(0,10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(href);
  };

  const handleImportProject = (file: File) => {
    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const content = e.target?.result as string;
        const data = JSON.parse(content);

        if (data.characters) setCharacters(data.characters);
        if (data.scenes) {
            // Migration for import
            setScenes(data.scenes.map((s: any) => ({
                ...s,
                effects: s.effects || s.unlocks || []
            })));
        }
        if (data.maps) setMaps(data.maps);
        else if (data.mapConfig) setMaps([{ ...data.mapConfig, id: 'map1', name: 'Default Map' }]);

        await setItem(PROJECT_STORAGE_KEY, data);
        alert("Project loaded successfully!");
      } catch (error) {
        console.error("Import failed", error);
        alert("Failed to load project file. Invalid JSON.");
      }
    };
    reader.readAsText(file);
  };

  const handleStartNewGame = () => {
    setRpgState({ 
        currentMapId: maps[0].id, 
        completedSceneIds: [], 
        unlockedIds: [],
        hiddenIds: [],
        ongoingScenes: {} 
    });
    setVnHistory([]);
    setActiveSceneIndex(-1);
    setMode('rpg');
  };

  const handleContinueGame = async () => {
    let savedGame = await getItem<GameSaveData>(GAME_SAVE_KEY);

    if (!savedGame) {
        const lsSave = localStorage.getItem(GAME_SAVE_KEY);
        if (lsSave) {
            try { savedGame = JSON.parse(lsSave); } catch(e) {}
        }
    }

    if (savedGame) {
      try {
        const safeMapId = maps.find(m => m.id === savedGame!.rpgState.currentMapId) ? savedGame!.rpgState.currentMapId : maps[0].id;

        setRpgState({ 
            ...savedGame.rpgState, 
            currentMapId: safeMapId,
            unlockedIds: savedGame.rpgState.unlockedIds || [], 
            hiddenIds: savedGame.rpgState.hiddenIds || [], // Migration
            ongoingScenes: savedGame.rpgState.ongoingScenes || {} 
        });

        if (savedGame.vnState) {
          setActiveSceneIndex(savedGame.vnState.currentSceneIndex);
          setVnHistory(savedGame.vnState.history);
          setMode('vn');
        } else {
          setMode('rpg');
        }
      } catch (e) {
        console.error("Corrupt save file");
        handleStartNewGame();
      }
    }
  };

  const handleSaveGameInternal = async (updatedRpgState: RPGState, vnState: any | null) => {
      const saveData: GameSaveData = {
        rpgState: updatedRpgState,
        vnState: vnState,
        timestamp: Date.now()
      };
      await setItem(GAME_SAVE_KEY, saveData);
      setHasSaveGame(true);
      return true;
  };

  const handleInteraction = (type: 'scene'|'transition'|'character', id: string) => {
      // Check if locked/hidden first
      if (rpgState.hiddenIds.includes(id)) return;

      if (type === 'transition') {
          if (maps.find(m => m.id === id)) {
              setRpgState(prev => ({ ...prev, currentMapId: id }));
          }
      } else if (type === 'character') {
          const charId = id;
          const char = characters.find(c => c.id === charId);
          if (!char) return;

          const availableScenes = scenes.filter(s => s.characters.some(c => c.characterId === charId));

          const playableScene = availableScenes.find(s => {
              // 1. Check completion
              const isCompleted = rpgState.completedSceneIds.includes(s.id);
              if (isCompleted) return false;

              // 2. Check if explicitly hidden/locked
              if (rpgState.hiddenIds.includes(s.id)) return false;

              // 3. Check dependencies (unlocks)
              // Logic: If a scene is referenced as an 'unlock' target by ANY other scene, 
              // it is "Locked by default" UNLESS it is in unlockedIds.
              const isLockedByOthers = scenes.some(other => other.effects?.some(u => u.type === 'scene' && u.targetId === s.id && u.action === 'unlock'));
              const isUnlocked = rpgState.unlockedIds.includes(s.id);

              return !isLockedByOthers || isUnlocked;
          });

          if (playableScene) {
             startScene(playableScene);
          } else {
             alert(`${char.name} has nothing new to say right now.`);
          }

      } else {
          const sceneId = id; 
          const scene = scenes.find(s => s.id === sceneId);
          if (scene) {
             startScene(scene);
          }
      }
  };

  const startScene = (scene: Scene) => {
      const realIndex = scenes.findIndex(s => s.id === scene.id);
      setActiveSceneIndex(realIndex);

      const existingHistory = rpgState.ongoingScenes?.[scene.id] || [];
      setVnHistory(existingHistory);

      setMode('vn');
  };

  const handleSceneExit = async (completed: boolean, history: ChatMessage[]) => {
      const activeScene = scenes[activeSceneIndex];
      const sceneId = activeScene.id;

      let newState = { ...rpgState };

      if (completed) {
          // 1. Mark as completed
          const newCompletedIds = [...rpgState.completedSceneIds, sceneId];

          // 2. Remove from ongoing scenes
          const { [sceneId]: _, ...remainingScenes } = newState.ongoingScenes || {};

          // 3. Process Effects (Unlocks / Locks)
          const newUnlockedIds = [...rpgState.unlockedIds];
          const newHiddenIds = [...rpgState.hiddenIds];

          if (activeScene.effects) {
              activeScene.effects.forEach(effect => {
                  const targetId = effect.targetId;
                  const action = effect.action || 'unlock'; // Default to unlock for legacy data

                  if (action === 'unlock') {
                      if (!newUnlockedIds.includes(targetId)) {
                          newUnlockedIds.push(targetId);
                      }
                      // If it was hidden, unhide it? Probably safer to remove from hiddenIds
                      const hideIdx = newHiddenIds.indexOf(targetId);
                      if (hideIdx > -1) newHiddenIds.splice(hideIdx, 1);

                  } else if (action === 'lock') {
                      if (!newHiddenIds.includes(targetId)) {
                          newHiddenIds.push(targetId);
                      }
                  }
              });
          }

          newState = { 
              ...newState, 
              completedSceneIds: newCompletedIds,
              unlockedIds: newUnlockedIds,
              hiddenIds: newHiddenIds,
              ongoingScenes: remainingScenes
          };

      } else {
          // Just PAUSE
          newState = {
              ...newState,
              ongoingScenes: {
                  ...newState.ongoingScenes,
                  [sceneId]: history
              }
          };
      }

      setRpgState(newState);
      await handleSaveGameInternal(newState, null);
      setMode('rpg');
  };

  const activeMap = maps.find(m => m.id === rpgState.currentMapId) || maps[0];

  return (
    <div className="min-h-screen bg-gray-900 text-gray-100 font-sans selection:bg-indigo-500 selection:text-white">
      {mode === 'edit' && (
        <Editor 
          characters={characters}
          scenes={scenes}
          maps={maps}
          onUpdateCharacters={setCharacters}
          onUpdateScenes={setScenes}
          onUpdateMaps={setMaps}
          onPlay={handleStartNewGame}
          onQuickSave={handleQuickSave}
          onExportProject={handleExportProject}
          onImportProject={handleImportProject}
          hasSaveGame={hasSaveGame}
          onContinueGame={handleContinueGame}
        />
      )}

      {mode === 'rpg' && (
        <RPGWorld 
          characters={characters}
          mapConfig={activeMap}
          maps={maps}
          scenes={scenes}
          initialState={rpgState}
          onInteraction={handleInteraction}
          onSave={async (updatedRpgState) => {
             setRpgState(updatedRpgState);
             await handleSaveGameInternal(updatedRpgState, null);
             alert("Game Saved!");
          }}
          onExit={() => setMode('edit')}
        />
      )}

      {mode === 'vn' && activeSceneIndex >= 0 && (
        <Player 
          scenes={scenes}
          characters={characters}
          initialState={{
            currentSceneIndex: activeSceneIndex,
            history: vnHistory, 
            timestamp: 0,
            rpgState: rpgState, 
            vnState: null
          }}
          onExit={handleSceneExit}
          onSave={async (vnState) => {
             await handleSaveGameInternal(rpgState, vnState);
             return true;
          }}
        />
      )}
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';
import { Character, RPGState, WorldMap, Scene } from '../types';
import { Save, LogOut, ZoomIn, ZoomOut, Maximize, MapPin } from 'lucide-react';

interface RPGWorldProps {
  characters: Character[];
  mapConfig: WorldMap; // The CURRENT map
  maps: WorldMap[]; // For referencing target map names
  scenes: Scene[]; // Needed to check dependencies
  onInteraction: (type: 'scene'|'transition'|'character', id: string) => void;
  initialState?: RPGState;
  onSave: (state: RPGState) => void;
  onExit: () => void;
}

export const RPGWorld: React.FC<RPGWorldProps> = ({ 
  characters, 
  mapConfig,
  maps,
  scenes,
  onInteraction, 
  initialState, 
  onSave,
  onExit
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const [hoveredSpotId, setHoveredSpotId] = useState<string | null>(null);
  const [canvasDims, setCanvasDims] = useState({ width: 1000, height: 750 });

  // Camera / Viewport State
  const [zoom, setZoom] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });

  // Cache for loaded sprite images
  const spritesRef = useRef<Record<string, HTMLImageElement>>({});
  const [spritesLoaded, setSpritesLoaded] = useState(false);

  useEffect(() => {
    let active = true;
    const loadSprites = async () => {
        const promises: Promise<void>[] = [];
        characters.forEach(c => {
            if (!c.mapSpriteSrc) return;
            promises.push(new Promise((resolve) => {
                const img = new Image();
                img.src = c.mapSpriteSrc!;
                img.onload = () => { if(active) spritesRef.current[c.id] = img; resolve(); };
                img.onerror = () => resolve(); 
            }));
        });
        scenes.forEach(s => {
            if (!s.mapIconSrc) return;
            promises.push(new Promise((resolve) => {
                const img = new Image();
                img.src = s.mapIconSrc!;
                img.onload = () => { if(active) spritesRef.current[s.id] = img; resolve(); };
                img.onerror = () => resolve();
            }));
        });
        await Promise.all(promises);
        if (active) setSpritesLoaded(true);
    };
    loadSprites();
    return () => { active = false; };
  }, [characters, scenes]);

  useEffect(() => {
    const applyFit = (w: number, h: number) => {
        setCanvasDims({ width: w, height: h });
        if (containerRef.current) {
            const { clientWidth, clientHeight } = containerRef.current;
            const scale = Math.min(clientWidth / w, clientHeight / h) * 0.95;
            const newX = (clientWidth - w * scale) / 2;
            const newY = (clientHeight - h * scale) / 2;
            setZoom(scale);
            setOffset({ x: newX, y: newY });
        }
    };

    if (mapConfig.backgroundSrc) {
        const img = new Image();
        img.src = mapConfig.backgroundSrc;
        img.onload = () => applyFit(img.naturalWidth, img.naturalHeight);
    } else {
        applyFit(1000, 750);
    }
  }, [mapConfig.id, mapConfig.backgroundSrc]); 

  // --- Visibility Logic ---
  const visibleSpots = mapConfig.spots.filter(spot => {
      // 1. Check if explicitly hidden (Locked via game logic)
      if (initialState?.hiddenIds.includes(spot.id)) return false; 
      // Note: spot.id is unique to the spot, but logic might lock sceneId or targetMapId.
      // We should check those too.
      if (spot.sceneId && initialState?.hiddenIds.includes(spot.sceneId)) return false;
      if (spot.targetMapId && initialState?.hiddenIds.includes(spot.targetMapId)) return false;
      if (spot.characterId && initialState?.hiddenIds.includes(spot.characterId)) return false;


      if (spot.type === 'transition') {
          const targetMapId = spot.targetMapId;
          if (!targetMapId) return false;

          // Check dependency (Unlock logic)
          // Look for any scene that has this transition as an 'unlock' effect
          const isLockedByDependency = scenes.some(s => s.effects?.some(u => u.type === 'transition' && u.targetId === targetMapId && (u.action === 'unlock' || !u.action)));
          const isUnlocked = initialState?.unlockedIds.includes(targetMapId);

          return !isLockedByDependency || isUnlocked;

      } else if (spot.type === 'scene') {
          const sceneId = spot.sceneId;
          if (!sceneId) return false;

          const scene = scenes.find(s => s.id === sceneId);
          if (!scene) return false; 

          const isCompleted = initialState?.completedSceneIds.includes(scene.id);
          if (isCompleted) return false; 

          // Check dependency (Unlock logic)
          const isLockedByDependency = scenes.some(other => other.effects?.some(u => u.type === 'scene' && u.targetId === scene.id && (u.action === 'unlock' || !u.action)));
          const isUnlocked = initialState?.unlockedIds.includes(scene.id);

          return !isLockedByDependency || isUnlocked;
      } else if (spot.type === 'character') {
          return !!spot.characterId;
      }
      return true;
  });

  // --- Interaction / Render ---

  const getRawMousePos = (e: React.MouseEvent | React.WheelEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    return { x: e.clientX - rect.left, y: e.clientY - rect.top };
  };

  const getMousePosInWorldPercent = (rawX: number, rawY: number) => {
     const worldX = (rawX - offset.x) / zoom;
     const worldY = (rawY - offset.y) / zoom;
     return { x: (worldX / canvasDims.width) * 100, y: (worldY / canvasDims.height) * 100 };
  };

  const checkHit = (xPct: number, yPct: number) => {
    const THRESHOLD = 4; 
    return visibleSpots.find(spot => {
       const dx = spot.x - xPct;
       const dy = spot.y - yPct;
       return Math.sqrt(dx*dx + dy*dy) < THRESHOLD;
    });
  };

  const handleWheel = (e: React.WheelEvent<HTMLCanvasElement>) => {
    e.preventDefault();
    const zoomSensitivity = 0.001;
    const delta = -e.deltaY * zoomSensitivity;
    const newZoom = Math.min(Math.max(zoom + delta, 0.1), 5); 
    if (newZoom === zoom) return;

    const mouse = getRawMousePos(e);
    const worldX = (mouse.x - offset.x) / zoom;
    const worldY = (mouse.y - offset.y) / zoom;
    const newOffsetX = mouse.x - worldX * newZoom;
    const newOffsetY = mouse.y - worldY * newZoom;

    setZoom(newZoom);
    setOffset({ x: newOffsetX, y: newOffsetY });
  };

  const handleMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (e.button === 0) {
      setIsDragging(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (isDragging) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return; 
    }
    const raw = getRawMousePos(e);
    const worldPct = getMousePosInWorldPercent(raw.x, raw.y);
    const hit = checkHit(worldPct.x, worldPct.y);

    if (hit) {
      if (hoveredSpotId !== hit.id) setHoveredSpotId(hit.id);
    } else {
      if (hoveredSpotId !== null) setHoveredSpotId(null);
    }
  };

  const handleMouseUp = () => setIsDragging(false);

  const handleClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (isDragging) return;
    const raw = getRawMousePos(e);
    const worldPct = getMousePosInWorldPercent(raw.x, raw.y);
    const hit = checkHit(worldPct.x, worldPct.y);
    if (hit) {
      if (hit.type === 'scene' && hit.sceneId) onInteraction('scene', hit.sceneId);
      else if (hit.type === 'character' && hit.characterId) onInteraction('character', hit.characterId);
      else if (hit.type === 'transition' && hit.targetMapId) onInteraction('transition', hit.targetMapId);
    }
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();
    ctx.fillStyle = '#0f172a'; 
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.translate(offset.x, offset.y);
    ctx.scale(zoom, zoom);

    const bgImage = new Image();
    if (mapConfig.backgroundSrc) bgImage.src = mapConfig.backgroundSrc;

    const drawScene = () => {
        if (mapConfig.backgroundSrc && bgImage.complete) {
            ctx.drawImage(bgImage, 0, 0, canvasDims.width, canvasDims.height);
        } else {
            ctx.fillStyle = '#1e293b';
            ctx.fillRect(0, 0, canvasDims.width, canvasDims.height);
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 2;
            ctx.strokeRect(0, 0, canvasDims.width, canvasDims.height);
        }

        const toPx = (pct: number, dim: number) => (pct / 100) * dim;

        visibleSpots.forEach(spot => {
          const cx = toPx(spot.x, canvasDims.width);
          const cy = toPx(spot.y, canvasDims.height);
          const isHovered = hoveredSpotId === spot.id;

          if (spot.type === 'scene' && spot.sceneId) {
              const scene = scenes.find(s => s.id === spot.sceneId);
              if (!scene) return;
              let spriteImg: HTMLImageElement | undefined;
              let rpgColor = '#ffffff';
              if (scene.mapIconSrc) {
                  spriteImg = spritesRef.current[scene.id];
              } else if (scene.characters.length > 0) {
                  const firstChar = characters.find(c => c.id === scene.characters[0].characterId);
                  if (firstChar) {
                      spriteImg = spritesRef.current[firstChar.id];
                      rpgColor = firstChar.rpgColor;
                  }
              }

              const baseScale = Math.max(canvasDims.width / 1000, 0.5); 
              const targetHeight = (isHovered ? 80 : 70) * baseScale;

              if (spriteImg) {
                  const ratio = spriteImg.naturalWidth / spriteImg.naturalHeight || 1;
                  const drawHeight = targetHeight;
                  const drawWidth = targetHeight * ratio;
                  ctx.save();
                  ctx.shadowColor = isHovered ? 'white' : 'black';
                  ctx.shadowBlur = isHovered ? 15 : 5;
                  ctx.drawImage(spriteImg, cx - drawWidth/2, cy - drawHeight/2, drawWidth, drawHeight);
                  ctx.restore();
              } else {
                  ctx.fillStyle = rpgColor;
                  ctx.beginPath();
                  ctx.arc(cx, cy, isHovered ? 14 : 12, 0, Math.PI * 2);
                  ctx.fill();
                  ctx.lineWidth = 2;
                  ctx.strokeStyle = 'white';
                  ctx.stroke();
                  ctx.fillStyle = 'white';
                  ctx.font = 'bold 16px sans-serif';
                  ctx.textAlign = 'center';
                  ctx.textBaseline = 'middle';
                  ctx.fillText('!', cx, cy);
              }

              if (isHovered) {
                ctx.save();
                const textScale = Math.max(1 / zoom, 0.5); 
                ctx.translate(cx, cy - (targetHeight / 2) - 14 * textScale);
                ctx.scale(textScale, textScale);
                ctx.fillStyle = 'rgba(0,0,0,0.8)';
                ctx.font = 'bold 16px sans-serif';
                const textW = ctx.measureText(scene.name).width;
                ctx.fillRect(-textW/2 - 8, -20, textW + 16, 28);
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.fillText(scene.name, 0, 0);
                ctx.restore();
              }
          } else if (spot.type === 'character' && spot.characterId) {
             const char = characters.find(c => c.id === spot.characterId);
             if(!char) return;
             const spriteImg = spritesRef.current[char.id];
             const baseScale = Math.max(canvasDims.width / 1000, 0.5); 
             const targetHeight = (isHovered ? 80 : 70) * baseScale;

             if (spriteImg) {
                const ratio = spriteImg.naturalWidth / spriteImg.naturalHeight || 1;
                const drawHeight = targetHeight;
                const drawWidth = targetHeight * ratio;
                ctx.save();
                ctx.shadowColor = isHovered ? 'white' : 'black';
                ctx.shadowBlur = isHovered ? 15 : 5;
                ctx.drawImage(spriteImg, cx - drawWidth/2, cy - drawHeight/2, drawWidth, drawHeight);
                ctx.restore();
             } else {
                ctx.fillStyle = char.rpgColor;
                ctx.beginPath();
                ctx.arc(cx, cy, isHovered ? 14 : 12, 0, Math.PI * 2);
                ctx.fill();
                ctx.lineWidth = 2;
                ctx.strokeStyle = 'white';
                ctx.stroke();
             }
             if (isHovered) {
                ctx.save();
                const textScale = Math.max(1 / zoom, 0.5); 
                ctx.translate(cx, cy - (targetHeight / 2) - 14 * textScale);
                ctx.scale(textScale, textScale);
                ctx.fillStyle = 'rgba(0,0,0,0.8)';
                ctx.font = 'bold 16px sans-serif';
                const textW = ctx.measureText(char.name).width;
                ctx.fillRect(-textW/2 - 8, -20, textW + 16, 28);
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.fillText(char.name, 0, 0);
                ctx.restore();
             }
          } else if (spot.type === 'transition') {
              const radius = 16;
              const pulseColor = 'rgba(52, 211, 153, 0.6)';
              if (isHovered) {
                  const time = Date.now() / 300;
                  const pulse = Math.sin(time) * 4 + radius + 4;
                  ctx.beginPath();
                  ctx.arc(cx, cy, pulse, 0, Math.PI * 2);
                  ctx.strokeStyle = pulseColor;
                  ctx.lineWidth = 2;
                  ctx.stroke();
              }
              ctx.beginPath();
              ctx.arc(cx, cy, radius, 0, Math.PI * 2);
              ctx.fillStyle = 'rgba(16, 185, 129, 0.9)'; 
              ctx.fill();
              ctx.strokeStyle = '#6ee7b7'; 
              ctx.lineWidth = 2;
              ctx.stroke();
              ctx.beginPath();
              ctx.arc(cx, cy, 6, 0, Math.PI * 2);
              ctx.fillStyle = '#ffffff';
              ctx.fill();
              if (isHovered) {
                  ctx.save();
                  const targetMapName = maps.find(m => m.id === spot.targetMapId)?.name || 'Unknown Area';
                  const text = `Travel to ${targetMapName}`;
                  const textScale = Math.max(1 / zoom, 0.5); 
                  ctx.translate(cx, cy - 30 * textScale);
                  ctx.scale(textScale, textScale);
                  ctx.fillStyle = 'rgba(0,0,0,0.8)';
                  ctx.font = 'bold 14px sans-serif';
                  const textW = ctx.measureText(text).width;
                  ctx.fillRect(-textW/2 - 8, -18, textW + 16, 26);
                  ctx.fillStyle = '#6ee7b7'; 
                  ctx.textAlign = 'center';
                  ctx.fillText(text, 0, 0);
                  ctx.restore();
              }
          }
        });
    }

    if (bgImage.complete || !mapConfig.backgroundSrc) {
        drawScene();
    } else {
        bgImage.onload = drawScene;
    }
    ctx.restore();
  }, [mapConfig, characters, scenes, hoveredSpotId, spritesLoaded, canvasDims, zoom, offset, visibleSpots]);

  const handleManualSave = () => {
    onSave({ 
        currentMapId: mapConfig.id,
        completedSceneIds: initialState?.completedSceneIds || [],
        unlockedIds: initialState?.unlockedIds || [],
        hiddenIds: initialState?.hiddenIds || [],
        ongoingScenes: initialState?.ongoingScenes || {}
    });
  };

  const handleZoomIn = () => setZoom(z => Math.min(z + 0.2, 5));
  const handleZoomOut = () => setZoom(z => Math.max(z - 0.2, 0.1));
  const handleResetView = () => {
        if (containerRef.current) {
            const { clientWidth, clientHeight } = containerRef.current;
            const w = canvasDims.width;
            const h = canvasDims.height;
            const scale = Math.min(clientWidth / w, clientHeight / h) * 0.95;
            const newX = (clientWidth - w * scale) / 2;
            const newY = (clientHeight - h * scale) / 2;
            setZoom(scale);
            setOffset({ x: newX, y: newY });
        }
  };

  return (
    <div className="relative w-full h-full bg-gray-950 flex flex-col overflow-hidden">
      <div className="absolute top-4 left-4 z-10 pointer-events-none">
          <div className="bg-gray-900/80 p-3 rounded-xl border border-gray-700 backdrop-blur-sm shadow-xl pointer-events-auto">
            <h1 className="text-xl font-bold text-indigo-400">{mapConfig.name.toUpperCase()}</h1>
            <p className="text-xs text-gray-400 mt-1">Drag to Pan • Wheel to Zoom</p>
          </div>
      </div>
      <div 
        ref={containerRef}
        className="flex-1 w-full h-full relative overflow-hidden bg-[#0f172a] cursor-grab active:cursor-grabbing"
      >
        <canvas 
          ref={canvasRef}
          width={canvasRef.current?.parentElement?.clientWidth || 1000} 
          height={canvasRef.current?.parentElement?.clientHeight || 750}
          className="block w-full h-full"
          onWheel={handleWheel}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
          onClick={handleClick}
          style={{ touchAction: 'none', cursor: hoveredSpotId ? 'pointer' : 'default' }}
        />
      </div>
      <div className="absolute bottom-8 right-8 flex gap-3 z-10">
         <div className="bg-gray-800 rounded-full border border-gray-600 flex overflow-hidden shadow-lg mr-4">
            <button onClick={handleZoomOut} className="p-3 hover:bg-gray-700 text-white transition border-r border-gray-600"><ZoomOut size={20} /></button>
            <button onClick={handleResetView} className="p-3 hover:bg-gray-700 text-white transition border-r border-gray-600" title="Reset View"><Maximize size={20} /></button>
            <button onClick={handleZoomIn} className="p-3 hover:bg-gray-700 text-white transition"><ZoomIn size={20} /></button>
         </div>
         <button onClick={handleManualSave} className="bg-indigo-600 p-3 rounded-full hover:bg-indigo-500 text-white shadow-lg transition transform hover:scale-105" title="Save Game"><Save size={24} /></button>
         <button onClick={onExit} className="bg-gray-800 p-3 rounded-full hover:bg-red-900/80 text-white border border-gray-600 shadow-lg transition transform hover:scale-105" title="Exit to Editor"><LogOut size={24} /></button>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Plus, Trash2, Image as ImageIcon, User, Target, Save, PlayCircle, RotateCcw, Map as MapIcon, MousePointerClick, FileUp, Download, Upload, Check, Waypoints, Globe, Lock, Unlock, MessageSquare, Ban } from 'lucide-react';
import { Character, Scene, SceneCharacterConfig, WorldMap, MapSpot, SceneEffect } from '../types';
import { Button } from './ui/Button';

interface EditorProps {
  characters: Character[];
  scenes: Scene[];
  maps: WorldMap[];
  onUpdateCharacters: (chars: Character[]) => void;
  onUpdateScenes: (scenes: Scene[]) => void;
  onUpdateMaps: (maps: WorldMap[]) => void;
  onPlay: () => void;
  onQuickSave: () => Promise<boolean>;
  onExportProject: () => void;
  onImportProject: (file: File) => void;
  hasSaveGame: boolean;
  onContinueGame: () => void;
}

export const Editor: React.FC<EditorProps> = ({
  characters,
  scenes,
  maps,
  onUpdateCharacters,
  onUpdateScenes,
  onUpdateMaps,
  onPlay,
  onQuickSave,
  onExportProject,
  onImportProject,
  hasSaveGame,
  onContinueGame
}) => {
  const [activeTab, setActiveTab] = useState<'chars' | 'scenes' | 'map'>('chars');

  // Map Editor State
  const [activeMapId, setActiveMapId] = useState<string>(maps[0]?.id || '');
  const [selectedTool, setSelectedTool] = useState<{type: 'scene'|'transition'|'character', id: string} | null>(null);

  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const importInputRef = useRef<HTMLInputElement>(null);

  // --- Character Handlers ---
  const addCharacter = () => {
    const newChar: Character = {
      id: crypto.randomUUID(),
      name: 'New Character',
      defaultDescription: 'A friendly helper.',
      imageSrc: null,
      mapSpriteSrc: null,
      rpgColor: '#ef4444', 
    };
    onUpdateCharacters([...characters, newChar]);
  };

  const updateCharacter = (id: string, updates: Partial<Character>) => {
    onUpdateCharacters(characters.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const handleCharImageUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>, field: 'imageSrc' | 'mapSpriteSrc') => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCharacter(id, { [field]: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  // --- Scene Handlers ---
  const addScene = () => {
    const newScene: Scene = {
      id: crypto.randomUUID(),
      name: `Scene ${scenes.length + 1}`,
      backgroundSrc: null,
      description: 'You are in a quiet room.',
      goal: 'Say hello.',
      characters: [],
      effects: [],
      mapIconSrc: null
    };
    onUpdateScenes([...scenes, newScene]);
  };

  const updateScene = (id: string, updates: Partial<Scene>) => {
    onUpdateScenes(scenes.map(s => s.id === id ? { ...s, ...updates } : s));
  };

  const handleSceneIconUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { mapIconSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleEffect = (sceneId: string, type: 'scene' | 'transition', targetId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const currentEffects = scene.effects || [];
    const existingEffect = currentEffects.find(u => u.type === type && u.targetId === targetId);

    let newEffects: SceneEffect[];

    // Cycle: None -> Unlock -> Lock -> None
    if (!existingEffect) {
        // Add as Unlock
        newEffects = [...currentEffects, { type, targetId, action: 'unlock' }];
    } else if (existingEffect.action === 'unlock' || !existingEffect.action) {
        // Change to Lock
        newEffects = currentEffects.map(eff => 
            (eff.type === type && eff.targetId === targetId) ? { ...eff, action: 'lock' } : eff
        );
    } else {
        // Remove
        newEffects = currentEffects.filter(u => !(u.type === type && u.targetId === targetId));
    }

    updateScene(sceneId, { effects: newEffects });
  };

  const handleBgUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleCharInScene = (sceneId: string, charId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const exists = scene.characters.find(c => c.characterId === charId);
    let newChars: SceneCharacterConfig[];

    if (exists) {
      newChars = scene.characters.filter(c => c.characterId !== charId);
    } else {
      newChars = [...scene.characters, { characterId: charId, roleInScene: 'Default behavior' }];
    }
    updateScene(sceneId, { characters: newChars });
  };

  const updateSceneCharRole = (sceneId: string, charId: string, role: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;
    const newChars = scene.characters.map(c => c.characterId === charId ? { ...c, roleInScene: role } : c);
    updateScene(sceneId, { characters: newChars });
  };

  // --- Map Handlers ---

  const getCurrentMap = () => maps.find(m => m.id === activeMapId);

  const addMap = () => {
      const newMap: WorldMap = {
          id: crypto.randomUUID(),
          name: `Map ${maps.length + 1}`,
          backgroundSrc: null,
          spots: []
      };
      const newMaps = [...maps, newMap];
      onUpdateMaps(newMaps);
      setActiveMapId(newMap.id);
  };

  const deleteMap = (id: string) => {
      if (maps.length <= 1) {
          alert("You must have at least one map.");
          return;
      }
      const newMaps = maps.filter(m => m.id !== id);
      onUpdateMaps(newMaps);
      if (activeMapId === id) setActiveMapId(newMaps[0].id);
  };

  const updateCurrentMap = (updates: Partial<WorldMap>) => {
      onUpdateMaps(maps.map(m => m.id === activeMapId ? { ...m, ...updates } : m));
  };

  const handleMapBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCurrentMap({ backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const handleMapClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!selectedTool || !mapContainerRef.current) return;

    // Check if clicked on an existing pin
    if ((e.target as HTMLElement).closest('.map-pin')) return;

    const rect = mapContainerRef.current.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;

    const currentMap = getCurrentMap();
    if (!currentMap) return;

    const newSpot: MapSpot = {
      id: crypto.randomUUID(),
      type: selectedTool.type,
      x, 
      y,
      sceneId: selectedTool.type === 'scene' ? selectedTool.id : undefined,
      targetMapId: selectedTool.type === 'transition' ? selectedTool.id : undefined,
      characterId: selectedTool.type === 'character' ? selectedTool.id : undefined,
    };

    updateCurrentMap({ spots: [...currentMap.spots, newSpot] });
  };

  const removeSpot = (spotId: string) => {
    const currentMap = getCurrentMap();
    if(!currentMap) return;
    updateCurrentMap({
      spots: currentMap.spots.filter(s => s.id !== spotId)
    });
  };

  // --- Toolbar Handlers ---

  const handleQuickSaveClick = async () => {
    setSaveStatus('saving');
    await onQuickSave();
    setSaveStatus('saved');
    setTimeout(() => setSaveStatus('idle'), 2000);
  };

  const handleImportClick = () => {
    importInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if(e.target.files && e.target.files[0]) {
        onImportProject(e.target.files[0]);
    }
    if(e.target.value) e.target.value = ''; 
  };

  const currentMap = getCurrentMap();

  return (
    <div className="flex flex-col h-full max-w-6xl mx-auto p-4 md:p-8">
      {/* Header / Toolbar */}
      <div className="flex flex-col xl:flex-row justify-between items-center mb-8 gap-6">
        <div>
           <h1 className="text-3xl font-bold text-indigo-400">VN Creator Studio</h1>
           <p className="text-gray-400 text-sm mt-1">Design your world, characters, and stories.</p>
        </div>

        <div className="flex flex-wrap gap-3 items-center justify-center">
          {/* File Operations */}
          <div className="flex gap-2 mr-2 bg-gray-800 p-1 rounded-lg border border-gray-700">
             <input type="file" ref={importInputRef} className="hidden" accept=".json" onChange={handleFileChange} />

             <button onClick={handleImportClick} className="flex items-center gap-2 px-3 py-2 text-sm text-gray-300 hover:text-white hover:bg-gray-700 rounded transition" title="Load .json file">
               <Upload size={16} /> Load Project
             </button>

             <div className="w-[1px] bg-gray-600 my-1"></div>

             <button onClick={onExportProject} className="flex items-center gap-2 px-3 py-2 text-sm text-gray-300 hover:text-white hover:bg-gray-700 rounded transition" title="Download .json file">
               <Download size={16} /> Export Project
             </button>
          </div>

          <Button 
            onClick={handleQuickSaveClick} 
            variant="secondary" 
            title="Saves to Browser Storage"
            className="min-w-[140px]"
            disabled={saveStatus === 'saving'}
          >
            {saveStatus === 'saved' ? <><Check size={18} className="text-green-400"/> Saved!</> : (saveStatus === 'saving' ? 'Saving...' : <><Save size={18} /> Quick Save</>)}
          </Button>

          <div className="h-8 w-[1px] bg-gray-700 mx-2 hidden md:block"></div>

          {hasSaveGame && (
            <Button onClick={onContinueGame} className="bg-yellow-600 hover:bg-yellow-500">
              <RotateCcw size={18} /> Continue
            </Button>
          )}

          <Button onClick={onPlay} className="bg-green-600 hover:bg-green-500 px-6 font-bold shadow-green-900/20">
            <PlayCircle size={18} /> PLAY GAME
          </Button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex gap-4 mb-6 border-b border-gray-700 pb-1">
        <button
          onClick={() => setActiveTab('chars')}
          className={`px-4 py-2 font-medium transition-colors ${activeTab === 'chars' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}
        >
          Characters
        </button>
        <button
          onClick={() => setActiveTab('scenes')}
          className={`px-4 py-2 font-medium transition-colors ${activeTab === 'scenes' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}
        >
          Scenarios
        </button>
        <button
          onClick={() => setActiveTab('map')}
          className={`px-4 py-2 font-medium transition-colors ${activeTab === 'map' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}
        >
          World Map
        </button>
      </div>

      <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
        {activeTab === 'chars' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {characters.map(char => (
                <div key={char.id} className="bg-gray-800 p-4 rounded-xl border border-gray-700 flex gap-4 shadow-lg hover:border-gray-600 transition-colors">

                  {/* Portrait (Left) */}
                  <div className="w-24 h-32 bg-gray-900 rounded-lg flex-shrink-0 border border-gray-600 overflow-hidden relative group">
                    {char.imageSrc ? (
                      <img src={char.imageSrc} alt={char.name} className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full flex flex-col items-center justify-center text-gray-600 gap-1">
                        <User size={24} />
                        <span className="text-[10px] text-center px-1">Portrait</span>
                      </div>
                    )}
                    <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity text-xs font-bold">
                      UPLOAD
                      <input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e, 'imageSrc')} />
                    </label>
                  </div>

                  <div className="flex-1 space-y-3">
                    <input
                      className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-1 focus:border-indigo-500 outline-none transition-all"
                      value={char.name}
                      onChange={(e) => updateCharacter(char.id, { name: e.target.value })}
                      placeholder="Character Name"
                    />

                    {/* Map Sprite Uploader */}
                    <div className="flex items-center gap-3">
                       <div className="w-12 h-12 bg-gray-900 rounded border border-gray-600 overflow-hidden relative group shrink-0">
                         {char.mapSpriteSrc ? (
                           <img src={char.mapSpriteSrc} alt="Sprite" className="w-full h-full object-contain" />
                         ) : (
                           <div className="w-full h-full flex items-center justify-center text-gray-600" title="Map Sprite">
                             <MapIcon size={16} />
                           </div>
                         )}
                         <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity">
                            <FileUp size={16} className="text-white"/>
                            <input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e, 'mapSpriteSrc')} />
                         </label>
                       </div>
                       <div className="text-xs text-gray-400">
                         <span className="font-bold block text-gray-300">Map Sprite</span>
                         <span className="text-[10px]">Icon used on the world map.</span>
