                      placeholder="Core Persona/Description..."
                    />
                  </div>
                  <button onClick={() => onUpdateCharacters(characters.filter(c => c.id !== char.id))} className="text-gray-500 hover:text-red-500 h-fit transition-colors p-1">
                    <Trash2 size={18} />
                  </button>
                </div>
              ))}
            </div>
            <Button onClick={addCharacter} variant="secondary" className="w-full py-4 border-dashed opacity-70 hover:opacity-100">
              <Plus size={20} /> Add Character
            </Button>
          </div>
        )}

        {activeTab === 'scenes' && (
          <div className="space-y-8">
            {scenes.map((scene, idx) => (
              <div key={scene.id} className="bg-gray-800 p-6 rounded-xl border border-gray-700 space-y-4 shadow-lg">
                <div className="flex justify-between items-start">
                  <div className="flex items-center gap-4">
                    <div className="bg-gray-900 px-3 py-1 rounded text-xs font-bold text-indigo-400 border border-gray-700">SCENE {idx + 1}</div>
                    <input
                       className="bg-transparent text-xl font-bold outline-none placeholder-gray-600 focus:text-white transition-colors"
                       value={scene.name}
                       onChange={(e) => updateScene(scene.id, { name: e.target.value })}
                       placeholder="Scene Name"
                    />
                  </div>
                  <button onClick={() => onUpdateScenes(scenes.filter(s => s.id !== scene.id))} className="text-gray-500 hover:text-red-500 transition-colors p-1">
                    <Trash2 size={18} />
                  </button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                  {/* Visuals & Goal */}
                  <div className="space-y-4">
                    <div className="w-full h-40 bg-gray-900 rounded-lg border border-gray-600 overflow-hidden relative group shadow-inner">
                       {scene.backgroundSrc ? (
                          <img src={scene.backgroundSrc} alt="bg" className="w-full h-full object-cover opacity-80" />
                       ) : (
                         <div className="w-full h-full flex items-center justify-center text-gray-500 gap-2">
                           <ImageIcon size={24} /> No Background
                         </div>
                       )}
                       <label className="absolute inset-0 flex items-center justify-center cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity bg-black/40">
                          <span className="bg-black/80 px-4 py-2 rounded hover:bg-black text-sm border border-gray-600">Change Background</span>
                          <input type="file" accept="image/*" className="hidden" onChange={(e) => handleBgUpload(scene.id, e)} />
                       </label>
                    </div>

                    {/* Map Icon Override */}
                    <div className="flex items-center gap-3 bg-gray-900/50 p-2 rounded border border-gray-700">
                       <div className="w-10 h-10 bg-gray-900 rounded border border-gray-600 overflow-hidden relative group shrink-0">
                         {scene.mapIconSrc ? (
                           <img src={scene.mapIconSrc} alt="Icon" className="w-full h-full object-contain" />
                         ) : (
                            // Show first character sprite if available as preview
                            scene.characters.length > 0 && characters.find(c => c.id === scene.characters[0].characterId)?.mapSpriteSrc ? (
                                <img src={characters.find(c => c.id === scene.characters[0].characterId)?.mapSpriteSrc!} className="w-full h-full object-contain opacity-50 grayscale" title="Default: First Character" />
                            ) : (
                                <div className="w-full h-full flex items-center justify-center text-gray-600" title="Map Icon">
                                    <MapIcon size={14} />
                                </div>
                            )
                         )}
                         <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity">
                            <FileUp size={12} className="text-white"/>
                            <input type="file" accept="image/*" className="hidden" onChange={(e) => handleSceneIconUpload(scene.id, e)} />
                         </label>
                       </div>
                       <div className="text-xs text-gray-400">
                         <span className="font-bold block text-gray-300">Map Icon (Optional)</span>
                         <span className="text-[10px]">Overrides character sprite on map.</span>
                       </div>
                    </div>

                    <div>
                      <label className="flex items-center gap-2 text-xs font-bold text-green-400 mb-1">
                        <Target size={14} /> WIN CONDITION
                      </label>
                      <textarea
                        className="w-full bg-gray-900 border border-green-900/50 text-green-100 rounded px-3 py-2 text-sm focus:border-green-500 outline-none resize-none transition-all shadow-inner"
                        value={scene.goal}
                        onChange={(e) => updateScene(scene.id, { goal: e.target.value })}
                        placeholder="e.g. Find the key..."
                        rows={3}
                      />
                    </div>

                    {/* Rewards / Unlocks Configuration */}
                    <div className="bg-gray-900/50 p-3 rounded-lg border border-gray-700">
                        <label className="flex items-center gap-2 text-xs font-bold text-yellow-500 mb-2">
                            <Unlock size={14} /> COMPLETION EFFECTS
                        </label>
                        <p className="text-[10px] text-gray-500 mb-2">Cycle to Unlock (Green) or Lock/Hide (Red).</p>

                        <div className="space-y-2 max-h-32 overflow-y-auto custom-scrollbar">
                            {/* Other Scenes */}
                            {scenes.filter(s => s.id !== scene.id).map(otherScene => {
                                const effect = scene.effects?.find(u => u.type === 'scene' && u.targetId === otherScene.id);
                                let stateClass = 'bg-gray-800 border-gray-700 text-gray-500';
                                let Icon = Lock;

                                if (effect?.action === 'unlock' || (effect && !effect.action)) {
                                    stateClass = 'bg-emerald-900/30 border-emerald-600 text-emerald-200';
                                    Icon = Unlock;
                                } else if (effect?.action === 'lock') {
                                    stateClass = 'bg-red-900/30 border-red-600 text-red-200';
                                    Icon = Ban;
                                }

                                return (
                                    <button 
                                        key={otherScene.id} 
                                        onClick={() => toggleEffect(scene.id, 'scene', otherScene.id)}
                                        className={`w-full flex items-center gap-2 text-xs p-1.5 rounded border transition-colors ${stateClass} hover:border-gray-400`}
                                    >
                                        <Icon size={12} />
                                        <span className="truncate flex-1 text-left">Scene: {otherScene.name}</span>
                                        {effect?.action === 'unlock' && <span className="text-[10px] uppercase font-bold">Unlocks</span>}
                                        {effect?.action === 'lock' && <span className="text-[10px] uppercase font-bold">Locks</span>}
                                    </button>
                                );
                            })}

                            {/* Maps */}
                            {maps.map(m => {
                                const effect = scene.effects?.find(u => u.type === 'transition' && u.targetId === m.id);
                                let stateClass = 'bg-gray-800 border-gray-700 text-gray-500';
                                let Icon = Lock;

                                if (effect?.action === 'unlock' || (effect && !effect.action)) {
                                    stateClass = 'bg-emerald-900/30 border-emerald-600 text-emerald-200';
                                    Icon = Globe;
                                } else if (effect?.action === 'lock') {
                                    stateClass = 'bg-red-900/30 border-red-600 text-red-200';
                                    Icon = Ban;
                                }

                                return (
                                    <button 
                                        key={m.id} 
                                        onClick={() => toggleEffect(scene.id, 'transition', m.id)}
                                        className={`w-full flex items-center gap-2 text-xs p-1.5 rounded border transition-colors ${stateClass} hover:border-gray-400`}
                                    >
                                        <Icon size={12} />
                                        <span className="truncate flex-1 text-left">Travel to: {m.name}</span>
                                        {effect?.action === 'unlock' && <span className="text-[10px] uppercase font-bold">Unlocks</span>}
                                        {effect?.action === 'lock' && <span className="text-[10px] uppercase font-bold">Locks</span>}
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                  </div>

                  {/* Narrative Setup */}
                  <div className="space-y-2 lg:col-span-2">
                     <label className="block text-xs font-bold text-gray-400">SCENARIO DESCRIPTION (For AI)</label>
                     <textarea
                        className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-2 text-sm focus:border-indigo-500 outline-none resize-none transition-all"
                        value={scene.description}
                        onChange={(e) => updateScene(scene.id, { description: e.target.value })}
                        placeholder="Describe the setting, the mood, and what is happening..."
                        rows={3}
                      />

                      <label className="block text-xs font-bold text-gray-400 mt-4">PARTICIPATING CHARACTERS</label>
                      <div className="bg-gray-900 rounded-lg p-3 border border-gray-700 min-h-[100px] shadow-inner">
                         <div className="flex gap-2 flex-wrap mb-3">
                           {characters.map(char => {
                             const isActive = scene.characters.some(c => c.characterId === char.id);
                             return (
                               <button
                                 key={char.id}
                                 onClick={() => toggleCharInScene(scene.id, char.id)}
                                 className={`text-xs px-3 py-1 rounded-full border transition-all ${isActive ? 'bg-indigo-600 border-indigo-400 text-white shadow-md' : 'bg-gray-800 border-gray-600 text-gray-400 hover:border-gray-400 hover:text-gray-300'}`}
                               >
                                 {char.name}
                               </button>
                             )
                           })}
                           {characters.length === 0 && <span className="text-xs text-gray-600 italic">No characters created yet.</span>}
                         </div>

                         {/* Per-Scene Character Logic */}
                         <div className="space-y-3">
                           {scene.characters.map(sc => {
                             const char = characters.find(c => c.id === sc.characterId);
                             if (!char) return null;
                             return (
                               <div key={sc.characterId} className="flex items-center gap-3 bg-gray-800 p-2 rounded border border-gray-700">
                                 <div className="w-8 h-8 rounded-full bg-gray-700 overflow-hidden flex-shrink-0 border border-gray-600" style={{ backgroundColor: char.rpgColor }}>
                                   {char.imageSrc && <img src={char.imageSrc} className="w-full h-full object-cover" />}
                                 </div>
                                 <div className="flex-1">
                                    <div className="text-xs font-bold text-indigo-300">{char.name} Role</div>
