                             <span className="text-xs truncate max-w-[120px]">{m.name}</span>
                             {maps.length > 1 && (
                                 <button onClick={(e) => { e.stopPropagation(); deleteMap(m.id); }} className="text-gray-600 hover:text-red-400">
                                     <Trash2 size={12} />
                                 </button>
                             )}
                         </div>
                     ))}
                  </div>

                  {currentMap && (
                      <div className="pt-2 border-t border-gray-700">
