        <button
          onClick={() => setActiveTab('scenes')}
          className={`px-4 py-2 font-medium transition-colors ${activeTab === 'scenes' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}
