                                    key={targetMap.id}
                                    onClick={() => setSelectedTool(selectedTool?.id === targetMap.id ? null : { type: 'transition', id: targetMap.id })}
                                    className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === targetMap.id && selectedTool.type === 'transition' ? 'bg-emerald-600/20 border-emerald-500 ring-1 ring-emerald-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}
                                >
                                    <div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 flex items-center justify-center flex-shrink-0 text-emerald-500">
                                        <Waypoints size={14} />
                                    </div>
                                    <span className="text-xs font-medium truncate flex-1 text-left">To: {targetMap.name}</span>
                                    {selectedTool?.id === targetMap.id && selectedTool.type === 'transition' && <MousePointerClick size={12} className="ml-auto text-emerald-400"/>}
                                </button>
                            ))}
                            {maps.length <= 1 && <div className="text-xs text-gray-600 italic px-2">Create another map to link to.</div>}
                        </div>
                    </div>
                 </div>
              </div>
            </div>

            {/* Map Canvas */}
            <div className="flex-1 bg-gray-900 rounded-xl border-[4px] border-gray-800 shadow-2xl overflow-hidden relative group">
                {currentMap && currentMap.backgroundSrc ? (
                   <div 
                      ref={mapContainerRef}
                      onClick={handleMapClick}
                      className="relative w-full h-full cursor-crosshair"
                   >
                      <img 
                        src={currentMap.backgroundSrc} 
                        alt="World Map" 
                        className="w-full h-full object-contain bg-black select-none pointer-events-none" 
                      />

                      {/* Render Spots */}
                      {currentMap.spots.map(spot => {
                         if (spot.type === 'scene') {
                             // SCENE RENDERING
                             const scene = scenes.find(s => s.id === spot.sceneId);

                             // Resolve visual
                             let iconSrc = scene?.mapIconSrc;
                             let bgColor = '#ffffff';
                             let name = scene?.name || 'Unknown Scene';

                             // Fallback to character icon logic if no override
                             if (scene && !iconSrc && scene.characters.length > 0) {
                                const char = characters.find(c => c.id === scene.characters[0].characterId);
                                if(char) {
                                    iconSrc = char.mapSpriteSrc;
                                    bgColor = char.rpgColor;
                                }
                             }

                             return (
                                <div 
                                  key={spot.id}
                                  className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin"
                                  style={{ left: `${spot.x}%`, top: `${spot.y}%` }}
                                >
                                   {/* Sprite Render */}
                                   <div className="w-12 h-12 relative drop-shadow-lg transition hover:scale-110 flex items-center justify-center">
                                       {iconSrc ? (
                                           <img src={iconSrc} alt={name} className="w-full h-full object-contain" />
                                       ) : (
                                           <div className="w-6 h-6 rounded-full border border-white shadow-sm flex items-center justify-center bg-gray-700 text-white" style={{backgroundColor: bgColor}}>
                                               <MessageSquare size={12} />
                                           </div>
                                       )}
                                   </div>

                                   <span className="bg-black/70 text-[10px] px-2 rounded text-white whitespace-nowrap mt-1 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none backdrop-blur-sm">{name}</span>
                                   <button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110">
                                     <Trash2 size={12} />
                                   </button>
                                </div>
                             )
                         } else if (spot.type === 'character') {
                             // CHARACTER RENDERING
                             const char = characters.find(c => c.id === spot.characterId);
                             const name = char?.name || 'Unknown';

                             return (
                                <div 
                                  key={spot.id}
                                  className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin"
                                  style={{ left: `${spot.x}%`, top: `${spot.y}%` }}
                                >
                                   <div className="w-12 h-12 relative drop-shadow-lg transition hover:scale-110 flex items-center justify-center">
                                       {char?.mapSpriteSrc ? (
                                           <img src={char.mapSpriteSrc} alt={name} className="w-full h-full object-contain" />
                                       ) : (
                                           <div className="w-4 h-4 rounded-full border border-white shadow-sm mb-1" style={{ backgroundColor: char?.rpgColor }} />
                                       )}
                                   </div>

                                   <span className="bg-black/70 text-[10px] px-2 rounded text-white whitespace-nowrap mt-1 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none backdrop-blur-sm">{name}</span>
                                   <button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110">
                                     <Trash2 size={12} />
                                   </button>
                                </div>
                             )
                         } else {
                             // Transition Spot
                             const target = maps.find(m => m.id === spot.targetMapId);
                             return (
                                <div 
                                  key={spot.id}
                                  className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin"
                                  style={{ left: `${spot.x}%`, top: `${spot.y}%` }}
                                >
                                   {/* Transition Icon */}
                                   <div className="w-8 h-8 rounded-full bg-emerald-500/50 border-2 border-emerald-400 flex items-center justify-center shadow-lg hover:scale-110 transition">
                                       <Waypoints size={16} className="text-white" />
                                   </div>

                                   <span className="bg-emerald-900/90 text-[10px] px-2 rounded text-emerald-100 whitespace-nowrap mt-1 opacity-100 transition-opacity pointer-events-none backdrop-blur-sm border border-emerald-700">Go to: {target?.name || 'Unknown'}</span>
                                   <button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110">
                                     <Trash2 size={12} />
                                   </button>
                                </div>
                             )
                         }
                      })}
                   </div>
                ) : (
                  <div className="w-full h-full flex flex-col items-center justify-center text-gray-600 gap-4">
                    {currentMap ? (
                        <>
                            <MapIcon size={48} opacity={0.5} />
                            <p>Upload a background for {currentMap.name}.</p>
                        </>
                    ) : (
                        <p>No map selected.</p>
                    )}
                  </div>
                )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Character, RPGState, WorldMap, Scene } from '../types';
import { Save, LogOut, ZoomIn, ZoomOut, Maximize, MapPin } from 'lucide-react';

interface RPGWorldProps {
  characters: Character[];
  mapConfig: WorldMap; // The CURRENT map
  maps: WorldMap[]; // For referencing target map names
  scenes: Scene[]; // Needed to check dependencies
  onInteraction: (type: 'scene'|'transition'|'character', id: string) => void;
  initialState?: RPGState;
  onSave: (state: RPGState) => void;
  onExit: () => void;
}

export const RPGWorld: React.FC<RPGWorldProps> = ({ 
  characters, 
  mapConfig,
  maps,
  scenes,
  onInteraction, 
  initialState, 
  onSave,
  onExit
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const [hoveredSpotId, setHoveredSpotId] = useState<string | null>(null);
  const [canvasDims, setCanvasDims] = useState({ width: 1000, height: 750 });

  // Camera / Viewport State
  const [zoom, setZoom] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });

  // Cache for loaded sprite images
  const spritesRef = useRef<Record<string, HTMLImageElement>>({});
  const [spritesLoaded, setSpritesLoaded] = useState(false);

  useEffect(() => {
    let active = true;
    const loadSprites = async () => {
        const promises: Promise<void>[] = [];
        characters.forEach(c => {
            if (!c.mapSpriteSrc) return;
            promises.push(new Promise((resolve) => {
                const img = new Image();
                img.src = c.mapSpriteSrc!;
                img.onload = () => { if(active) spritesRef.current[c.id] = img; resolve(); };
                img.onerror = () => resolve(); 
            }));
        });
        scenes.forEach(s => {
            if (!s.mapIconSrc) return;
            promises.push(new Promise((resolve) => {
                const img = new Image();
                img.src = s.mapIconSrc!;
                img.onload = () => { if(active) spritesRef.current[s.id] = img; resolve(); };
                img.onerror = () => resolve();
            }));
        });
        await Promise.all(promises);
        if (active) setSpritesLoaded(true);
    };
    loadSprites();
    return () => { active = false; };
  }, [characters, scenes]);

  useEffect(() => {
    const applyFit = (w: number, h: number) => {
        setCanvasDims({ width: w, height: h });
        if (containerRef.current) {
            const { clientWidth, clientHeight } = containerRef.current;
            const scale = Math.min(clientWidth / w, clientHeight / h) * 0.95;
            const newX = (clientWidth - w * scale) / 2;
            const newY = (clientHeight - h * scale) / 2;
            setZoom(scale);
            setOffset({ x: newX, y: newY });
        }
    };

    if (mapConfig.backgroundSrc) {
        const img = new Image();
        img.src = mapConfig.backgroundSrc;
        img.onload = () => applyFit(img.naturalWidth, img.naturalHeight);
    } else {
        applyFit(1000, 750);
    }
  }, [mapConfig.id, mapConfig.backgroundSrc]); 

  // --- Visibility Logic ---
  const visibleSpots = mapConfig.spots.filter(spot => {
      // 1. Check if explicitly hidden (Locked via game logic)
      if (initialState?.hiddenIds.includes(spot.id)) return false; 

      if (spot.sceneId && initialState?.hiddenIds.includes(spot.sceneId)) return false;
      if (spot.targetMapId && initialState?.hiddenIds.includes(spot.targetMapId)) return false;
      if (spot.characterId && initialState?.hiddenIds.includes(spot.characterId)) return false;


      if (spot.type === 'transition') {
          const targetMapId = spot.targetMapId;
          if (!targetMapId) return false;

          // Check dependency (Unlock logic)
          // Look for any scene that has this transition as an 'unlock' effect
          const isLockedByDependency = scenes.some(s => s.effects?.some(u => u.type === 'transition' && u.targetId === targetMapId && (u.action === 'unlock' || !u.action)));
          const isUnlocked = initialState?.unlockedIds.includes(targetMapId);

          return !isLockedByDependency || isUnlocked;

      } else if (spot.type === 'scene') {
          const sceneId = spot.sceneId;
          if (!sceneId) return false;

          const scene = scenes.find(s => s.id === sceneId);
          if (!scene) return false; 

          const isCompleted = initialState?.completedSceneIds.includes(scene.id);

          // NEW LOGIC: If completed, only hide if it is NOT repeatable
          if (isCompleted && !scene.isRepeatable) return false; 

          // Check dependency (Unlock logic)
          const isLockedByDependency = scenes.some(other => other.effects?.some(u => u.type === 'scene' && u.targetId === scene.id && (u.action === 'unlock' || !u.action)));
          const isUnlocked = initialState?.unlockedIds.includes(scene.id);

          return !isLockedByDependency || isUnlocked;
      } else if (spot.type === 'character') {
          return !!spot.characterId;
      }
      return true;
  });

  // --- Interaction / Render ---

  const getRawMousePos = (e: React.MouseEvent | React.WheelEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    return { x: e.clientX - rect.left, y: e.clientY - rect.top };
  };

  const getMousePosInWorldPercent = (rawX: number, rawY: number) => {
     const worldX = (rawX - offset.x) / zoom;
     const worldY = (rawY - offset.y) / zoom;
     return { x: (worldX / canvasDims.width) * 100, y: (worldY / canvasDims.height) * 100 };
  };

  const checkHit = (xPct: number, yPct: number) => {
    const THRESHOLD = 4; 
    return visibleSpots.find(spot => {
       const dx = spot.x - xPct;
       const dy = spot.y - yPct;
       return Math.sqrt(dx*dx + dy*dy) < THRESHOLD;
    });
  };

  const handleWheel = (e: React.WheelEvent<HTMLCanvasElement>) => {
    e.preventDefault();
    const zoomSensitivity = 0.001;
    const delta = -e.deltaY * zoomSensitivity;
    const newZoom = Math.min(Math.max(zoom + delta, 0.1), 5); 
    if (newZoom === zoom) return;

    const mouse = getRawMousePos(e);
    const worldX = (mouse.x - offset.x) / zoom;
    const worldY = (mouse.y - offset.y) / zoom;
    const newOffsetX = mouse.x - worldX * newZoom;
    const newOffsetY = mouse.y - worldY * newZoom;

    setZoom(newZoom);
    setOffset({ x: newOffsetX, y: newOffsetY });
  };

  const handleMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (e.button === 0) {
      setIsDragging(true);
      setLastMousePos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (isDragging) {
      const dx = e.clientX - lastMousePos.x;
      const dy = e.clientY - lastMousePos.y;
      setOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      setLastMousePos({ x: e.clientX, y: e.clientY });
      return; 
    }
    const raw = getRawMousePos(e);
    const worldPct = getMousePosInWorldPercent(raw.x, raw.y);
    const hit = checkHit(worldPct.x, worldPct.y);

    if (hit) {
      if (hoveredSpotId !== hit.id) setHoveredSpotId(hit.id);
    } else {
      if (hoveredSpotId !== null) setHoveredSpotId(null);
    }
  };

  const handleMouseUp = () => setIsDragging(false);

  const handleClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (isDragging) return;
    const raw = getRawMousePos(e);
    const worldPct = getMousePosInWorldPercent(raw.x, raw.y);
    const hit = checkHit(worldPct.x, worldPct.y);
    if (hit) {
      if (hit.type === 'scene' && hit.sceneId) onInteraction('scene', hit.sceneId);
      else if (hit.type === 'character' && hit.characterId) onInteraction('character', hit.characterId);
      else if (hit.type === 'transition' && hit.targetMapId) onInteraction('transition', hit.targetMapId);
    }
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();
    ctx.fillStyle = '#0f172a'; 
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.translate(offset.x, offset.y);
    ctx.scale(zoom, zoom);

    const bgImage = new Image();
    if (mapConfig.backgroundSrc) bgImage.src = mapConfig.backgroundSrc;

    const drawScene = () => {
        if (mapConfig.backgroundSrc && bgImage.complete) {
            ctx.drawImage(bgImage, 0, 0, canvasDims.width, canvasDims.height);
        } else {
            ctx.fillStyle = '#1e293b';
            ctx.fillRect(0, 0, canvasDims.width, canvasDims.height);
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 2;
            ctx.strokeRect(0, 0, canvasDims.width, canvasDims.height);
        }

        const toPx = (pct: number, dim: number) => (pct / 100) * dim;

        visibleSpots.forEach(spot => {
          const cx = toPx(spot.x, canvasDims.width);
          const cy = toPx(spot.y, canvasDims.height);
          const isHovered = hoveredSpotId === spot.id;

          if (spot.type === 'scene' && spot.sceneId) {
              const scene = scenes.find(s => s.id === spot.sceneId);
              if (!scene) return;
              let spriteImg: HTMLImageElement | undefined;
              let rpgColor = '#ffffff';
              if (scene.mapIconSrc) {
                  spriteImg = spritesRef.current[scene.id];
              } else if (scene.characters.length > 0) {
                  const firstChar = characters.find(c => c.id === scene.characters[0].characterId);
                  if (firstChar) {
                      spriteImg = spritesRef.current[firstChar.id];
                      rpgColor = firstChar.rpgColor;
                  }
              }

              const baseScale = Math.max(canvasDims.width / 1000, 0.5); 
              const targetHeight = (isHovered ? 80 : 70) * baseScale;

              if (spriteImg) {
                  const ratio = spriteImg.naturalWidth / spriteImg.naturalHeight || 1;
                  const drawHeight = targetHeight;
                  const drawWidth = targetHeight * ratio;
                  ctx.save();
                  ctx.shadowColor = isHovered ? 'white' : 'black';
                  ctx.shadowBlur = isHovered ? 15 : 5;
                  ctx.drawImage(spriteImg, cx - drawWidth/2, cy - drawHeight/2, drawWidth, drawHeight);
                  ctx.restore();
              } else {
                  ctx.fillStyle = rpgColor;
                  ctx.beginPath();
                  ctx.arc(cx, cy, isHovered ? 14 : 12, 0, Math.PI * 2);
                  ctx.fill();
                  ctx.lineWidth = 2;
                  ctx.strokeStyle = 'white';
                  ctx.stroke();
                  ctx.fillStyle = 'white';
                  ctx.font = 'bold 16px sans-serif';
                  ctx.textAlign = 'center';
                  ctx.textBaseline = 'middle';
                  ctx.fillText('!', cx, cy);
              }

              if (isHovered) {
                ctx.save();
                const textScale = Math.max(1 / zoom, 0.5); 
                ctx.translate(cx, cy - (targetHeight / 2) - 14 * textScale);
                ctx.scale(textScale, textScale);
                ctx.fillStyle = 'rgba(0,0,0,0.8)';
                ctx.font = 'bold 16px sans-serif';
                const textW = ctx.measureText(scene.name).width;
                ctx.fillRect(-textW/2 - 8, -20, textW + 16, 28);
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.fillText(scene.name, 0, 0);
                ctx.restore();
              }
          } else if (spot.type === 'character' && spot.characterId) {
             const char = characters.find(c => c.id === spot.characterId);
             if(!char) return;
             const spriteImg = spritesRef.current[char.id];
             const baseScale = Math.max(canvasDims.width / 1000, 0.5); 
             const targetHeight = (isHovered ? 80 : 70) * baseScale;

             if (spriteImg) {
                const ratio = spriteImg.naturalWidth / spriteImg.naturalHeight || 1;
                const drawHeight = targetHeight;
                const drawWidth = targetHeight * ratio;
                ctx.save();
                ctx.shadowColor = isHovered ? 'white' : 'black';
                ctx.shadowBlur = isHovered ? 15 : 5;
                ctx.drawImage(spriteImg, cx - drawWidth/2, cy - drawHeight/2, drawWidth, drawHeight);
                ctx.restore();
             } else {
                ctx.fillStyle = char.rpgColor;
                ctx.beginPath();
                ctx.arc(cx, cy, isHovered ? 14 : 12, 0, Math.PI * 2);
                ctx.fill();
                ctx.lineWidth = 2;
                ctx.strokeStyle = 'white';
                ctx.stroke();
             }
             if (isHovered) {
                ctx.save();
                const textScale = Math.max(1 / zoom, 0.5); 
                ctx.translate(cx, cy - (targetHeight / 2) - 14 * textScale);
                ctx.scale(textScale, textScale);
                ctx.fillStyle = 'rgba(0,0,0,0.8)';
                ctx.font = 'bold 16px sans-serif';
                const textW = ctx.measureText(char.name).width;
                ctx.fillRect(-textW/2 - 8, -20, textW + 16, 28);
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.fillText(char.name, 0, 0);
                ctx.restore();
             }
          } else if (spot.type === 'transition') {
              const radius = 16;
              const pulseColor = 'rgba(52, 211, 153, 0.6)';
              if (isHovered) {
                  const time = Date.now() / 300;
                  const pulse = Math.sin(time) * 4 + radius + 4;
                  ctx.beginPath();
                  ctx.arc(cx, cy, pulse, 0, Math.PI * 2);
                  ctx.strokeStyle = pulseColor;
                  ctx.lineWidth = 2;
                  ctx.stroke();
              }
              ctx.beginPath();
              ctx.arc(cx, cy, radius, 0, Math.PI * 2);
              ctx.fillStyle = 'rgba(16, 185, 129, 0.9)'; 
              ctx.fill();
              ctx.strokeStyle = '#6ee7b7'; 
              ctx.lineWidth = 2;
              ctx.stroke();
              ctx.beginPath();
              ctx.arc(cx, cy, 6, 0, Math.PI * 2);
              ctx.fillStyle = '#ffffff';
              ctx.fill();
              if (isHovered) {
                  ctx.save();
                  const targetMapName = maps.find(m => m.id === spot.targetMapId)?.name || 'Unknown Area';
                  const text = `Travel to ${targetMapName}`;
                  const textScale = Math.max(1 / zoom, 0.5); 
                  ctx.translate(cx, cy - 30 * textScale);
                  ctx.scale(textScale, textScale);
                  ctx.fillStyle = 'rgba(0,0,0,0.8)';
                  ctx.font = 'bold 14px sans-serif';
                  const textW = ctx.measureText(text).width;
                  ctx.fillRect(-textW/2 - 8, -18, textW + 16, 26);
                  ctx.fillStyle = '#6ee7b7'; 
                  ctx.textAlign = 'center';
                  ctx.fillText(text, 0, 0);
                  ctx.restore();
              }
          }
        });
    }

    if (bgImage.complete || !mapConfig.backgroundSrc) {
        drawScene();
    } else {
        bgImage.onload = drawScene;
    }
    ctx.restore();
  }, [mapConfig, characters, scenes, hoveredSpotId, spritesLoaded, canvasDims, zoom, offset, visibleSpots]);

  const handleManualSave = () => {
    onSave({ 
        currentMapId: mapConfig.id,
        completedSceneIds: initialState?.completedSceneIds || [],
        unlockedIds: initialState?.unlockedIds || [],
        hiddenIds: initialState?.hiddenIds || [],
        ongoingScenes: initialState?.ongoingScenes || {}
    });
  };

  const handleZoomIn = () => setZoom(z => Math.min(z + 0.2, 5));
  const handleZoomOut = () => setZoom(z => Math.max(z - 0.2, 0.1));
  const handleResetView = () => {
        if (containerRef.current) {
            const { clientWidth, clientHeight } = containerRef.current;
            const w = canvasDims.width;
            const h = canvasDims.height;
            const scale = Math.min(clientWidth / w, clientHeight / h) * 0.95;
            const newX = (clientWidth - w * scale) / 2;
            const newY = (clientHeight - h * scale) / 2;
            setZoom(scale);
            setOffset({ x: newX, y: newY });
        }
  };

  return (
    <div className="relative w-full h-full bg-gray-950 flex flex-col overflow-hidden">
      <div className="absolute top-4 left-4 z-10 pointer-events-none">
          <div className="bg-gray-900/80 p-3 rounded-xl border border-gray-700 backdrop-blur-sm shadow-xl pointer-events-auto">
            <h1 className="text-xl font-bold text-indigo-400">{mapConfig.name.toUpperCase()}</h1>
            <p className="text-xs text-gray-400 mt-1">Drag to Pan • Wheel to Zoom</p>
          </div>
      </div>
      <div 
        ref={containerRef}
        className="flex-1 w-full h-full relative overflow-hidden bg-[#0f172a] cursor-grab active:cursor-grabbing"
      >
        <canvas 
          ref={canvasRef}
          width={canvasRef.current?.parentElement?.clientWidth || 1000} 
          height={canvasRef.current?.parentElement?.clientHeight || 750}
          className="block w-full h-full"
          onWheel={handleWheel}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
          onClick={handleClick}
          style={{ touchAction: 'none', cursor: hoveredSpotId ? 'pointer' : 'default' }}
        />
      </div>
      <div className="absolute bottom-8 right-8 flex gap-3 z-10">
         <div className="bg-gray-800 rounded-full border border-gray-600 flex overflow-hidden shadow-lg mr-4">
            <button onClick={handleZoomOut} className="p-3 hover:bg-gray-700 text-white transition border-r border-gray-600"><ZoomOut size={20} /></button>
            <button onClick={handleResetView} className="p-3 hover:bg-gray-700 text-white transition border-r border-gray-600" title="Reset View"><Maximize size={20} /></button>
            <button onClick={handleZoomIn} className="p-3 hover:bg-gray-700 text-white transition"><ZoomIn size={20} /></button>
         </div>
         <button onClick={handleManualSave} className="bg-indigo-600 p-3 rounded-full hover:bg-indigo-500 text-white shadow-lg transition transform hover:scale-105" title="Save Game"><Save size={24} /></button>
         <button onClick={onExit} className="bg-gray-800 p-3 rounded-full hover:bg-red-900/80 text-white border border-gray-600 shadow-lg transition transform hover:scale-105" title="Exit to Editor"><LogOut size={24} /></button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Editor } from './components/Editor';
