import { GoogleGenAI, Type, Schema } from "@google/genai";
import { Scene, Character, ChatMessage, AIResponse } from "../types";

// Defines the structure the AI must return to drive the engine
const RESPONSE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    characterResponses: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          characterId: { type: Type.STRING, description: "The ID of the character speaking." },
          text: { type: Type.STRING, description: "The dialogue line." },
        },
        required: ["characterId", "text"],
      },
      description: "List of responses from characters in the scene. Can be empty if only narrator speaks or no one speaks.",
    },
    sceneGoalReached: {
      type: Type.BOOLEAN,
      description: "True ONLY if the specific win condition is met. If no win condition is provided, this MUST be false.",
    },
    sceneTransitionReason: {
      type: Type.STRING,
      description: "Brief explanation if the scene is ending.",
    },
  },
  required: ["characterResponses", "sceneGoalReached"],
};

export const generateGameTurn = async (
  currentInput: string,
  history: ChatMessage[],
  scene: Scene,
  allCharacters: Character[]
): Promise<AIResponse> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key not found");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // 1. Construct the Context
  const activeChars = scene.characters.map(sc => {
    const baseChar = allCharacters.find(c => c.id === sc.characterId);
    return baseChar ? {
      name: baseChar.name,
      id: baseChar.id,
      basePersona: baseChar.defaultDescription,
      sceneRole: sc.roleInScene
    } : null;
  }).filter(Boolean);

  // Handle Logic for empty goals
  const hasSpecificGoal = scene.goal && scene.goal.trim().length > 0;

  const goalInstruction = hasSpecificGoal 
    ? `WIN CONDITION / GOAL: ${scene.goal}
       CRITICAL: Evaluate if this specific "WIN CONDITION" has been met by the user's actions or words. If yes, set 'sceneGoalReached' to true.`
    : `WIN CONDITION: NONE / SANDBOX. 
       CRITICAL: This is an open-ended roleplay. Do NOT set 'sceneGoalReached' to true under any circumstances. The player will exit manually when they are done.`;

  const aiHiddenInstructions = scene.aiInstructions 
    ? `HIDDEN GAME MASTER INSTRUCTIONS (Do not reveal to player): 
       ${scene.aiInstructions}` 
    : '';

  const systemPrompt = `
    You are the Game Master and Engine for a Visual Novel.

    CURRENT SCENARIO CONFIGURATION:
    - Scene Name: ${scene.name}
    - Location: ${scene.locationName || 'Unknown Location'}
    - Visible Description (Player Context): ${scene.description}

    ${aiHiddenInstructions}

    ${goalInstruction}

    ACTIVE CHARACTERS IN SCENE:
    ${activeChars.map(c => `- ID: ${c?.id}, Name: ${c?.name}
       Base Persona: ${c?.basePersona}
       CURRENT ROLE/GOAL: ${c?.sceneRole}`).join('\n')}

    INSTRUCTIONS:
    1. Analyze the user's input and the chat history.
    2. Determine which character(s) should respond based on their personas and the conversation flow. Multiple characters can speak in sequence.
    3. Respond strictly in JSON.
  `;

  // 2. Format History for Gemini
  // We only take the last 10 turns to keep context tight and efficient
  const recentHistory = history.slice(-10).map(msg => 
    `${msg.sender === 'user' ? 'Player' : (allCharacters.find(c => c.id === msg.characterId)?.name || 'Narrator')}: ${msg.text}`
  ).join('\n');

  const fullPrompt = `
    ${systemPrompt}

    RECENT CHAT HISTORY:
    ${recentHistory}

    CURRENT PLAYER INPUT:
    "${currentInput}"
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: fullPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: RESPONSE_SCHEMA,
        temperature: 1, // Allow for creative dialogue
      },
    });

    const jsonText = response.text;
    if (!jsonText) throw new Error("Empty response from AI");

    return JSON.parse(jsonText) as AIResponse;

  } catch (error) {
    console.error("Gemini Error:", error);
    // Fallback in case of error to prevent crash
    return {
      characterResponses: [{ characterId: "system", text: "An error occurred communicating with the AI engine." }],
      sceneGoalReached: false
    };
  }
};

import React, { useState, useRef } from 'react';
import { Plus, Trash2, Image as ImageIcon, User, Target, Save, PlayCircle, RotateCcw, Map as MapIcon, MousePointerClick, FileUp, Download, Upload, Check, Waypoints, Globe, Lock, Unlock, MessageSquare, Ban, RefreshCcw, Eye, EyeOff } from 'lucide-react';
import { Character, Scene, SceneCharacterConfig, WorldMap, MapSpot, SceneEffect } from '../types';
import { Button } from './ui/Button';

interface EditorProps {
  characters: Character[];
  scenes: Scene[];
  maps: WorldMap[];
  onUpdateCharacters: (chars: Character[]) => void;
  onUpdateScenes: (scenes: Scene[]) => void;
  onUpdateMaps: (maps: WorldMap[]) => void;
  onPlay: () => void;
  onQuickSave: () => Promise<boolean>;
  onExportProject: () => void;
  onImportProject: (file: File) => void;
  hasSaveGame: boolean;
  onContinueGame: () => void;
}

export const Editor: React.FC<EditorProps> = ({
  characters,
  scenes,
  maps,
  onUpdateCharacters,
  onUpdateScenes,
  onUpdateMaps,
  onPlay,
  onQuickSave,
  onExportProject,
  onImportProject,
  hasSaveGame,
  onContinueGame
}) => {
  const [activeTab, setActiveTab] = useState<'chars' | 'scenes' | 'map'>('chars');

  // Map Editor State
  const [activeMapId, setActiveMapId] = useState<string>(maps[0]?.id || '');
  const [selectedTool, setSelectedTool] = useState<{type: 'scene'|'transition'|'character', id: string} | null>(null);

  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const importInputRef = useRef<HTMLInputElement>(null);

  // --- Character Handlers ---
  const addCharacter = () => {
    const newChar: Character = {
      id: crypto.randomUUID(),
      name: 'New Character',
      defaultDescription: 'A friendly helper.',
      imageSrc: null,
      mapSpriteSrc: null,
      rpgColor: '#ef4444', 
    };
    onUpdateCharacters([...characters, newChar]);
  };

  const updateCharacter = (id: string, updates: Partial<Character>) => {
    onUpdateCharacters(characters.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const handleCharImageUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>, field: 'imageSrc' | 'mapSpriteSrc') => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCharacter(id, { [field]: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  // --- Scene Handlers ---
  const addScene = () => {
    const newScene: Scene = {
      id: crypto.randomUUID(),
      name: `Scene ${scenes.length + 1}`,
      locationName: 'Unknown Location',
      backgroundSrc: null,
      description: 'You are in a quiet room.',
      aiInstructions: '',
      goal: 'Say hello.',
      characters: [],
      effects: [],
      mapIconSrc: null,
      isRepeatable: false
    };
    onUpdateScenes([...scenes, newScene]);
  };

  const updateScene = (id: string, updates: Partial<Scene>) => {
    onUpdateScenes(scenes.map(s => s.id === id ? { ...s, ...updates } : s));
  };

  const handleSceneIconUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { mapIconSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleEffect = (sceneId: string, type: 'scene' | 'transition', targetId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const currentEffects = scene.effects || [];
    const existingEffect = currentEffects.find(u => u.type === type && u.targetId === targetId);

    let newEffects: SceneEffect[];

    if (!existingEffect) {
        newEffects = [...currentEffects, { type, targetId, action: 'unlock' }];
    } else if (existingEffect.action === 'unlock' || !existingEffect.action) {
        newEffects = currentEffects.map(eff => 
            (eff.type === type && eff.targetId === targetId) ? { ...eff, action: 'lock' } : eff
        );
    } else {
        newEffects = currentEffects.filter(u => !(u.type === type && u.targetId === targetId));
    }

    updateScene(sceneId, { effects: newEffects });
  };

  const handleBgUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleCharInScene = (sceneId: string, charId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const exists = scene.characters.find(c => c.characterId === charId);
    let newChars: SceneCharacterConfig[];

    if (exists) {
      newChars = scene.characters.filter(c => c.characterId !== charId);
    } else {
      newChars = [...scene.characters, { characterId: charId, roleInScene: 'Default behavior' }];
    }
    updateScene(sceneId, { characters: newChars });
  };

  const updateSceneCharRole = (sceneId: string, charId: string, role: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;
    const newChars = scene.characters.map(c => c.characterId === charId ? { ...c, roleInScene: role } : c);
    updateScene(sceneId, { characters: newChars });
