  {
    id: 'map1',
    name: 'Main City',
    backgroundSrc: null,
    spots: [
      { id: 'spot1', type: 'character', characterId: '1', x: 50, y: 50 },
    ]
  }
];

const PROJECT_STORAGE_KEY = 'vn_creator_project';
const GAME_SAVE_KEY = 'vn_creator_savegame';

const App: React.FC = () => {
  const [mode, setMode] = useState<'edit' | 'rpg' | 'vn'>('edit');

  // Data State
  const [characters, setCharacters] = useState<Character[]>(DEFAULT_CHARS);
  const [scenes, setScenes] = useState<Scene[]>(DEFAULT_SCENES);
  const [maps, setMaps] = useState<WorldMap[]>(DEFAULT_MAPS);

  // Game Play State
  const [rpgState, setRpgState] = useState<RPGState>({ 
    currentMapId: 'map1', 
    completedSceneIds: [],
    unlockedIds: [],
    hiddenIds: [],
    ongoingScenes: {}
  });

  const [activeSceneIndex, setActiveSceneIndex] = useState<number>(-1);
  const [vnHistory, setVnHistory] = useState<ChatMessage[]>([]); 

  const [hasSaveGame, setHasSaveGame] = useState(false);

  // Check for save game on mount and migrate from LocalStorage if needed
  useEffect(() => {
    const initLoad = async () => {
        // 1. Check for Save Game
        const savedGame = await getItem<GameSaveData>(GAME_SAVE_KEY);
        if (savedGame) {
            setHasSaveGame(true);
        } else {
            const lsSave = localStorage.getItem(GAME_SAVE_KEY);
            if (lsSave) {
                setHasSaveGame(true);
            }
        }

        // 2. Load Project Data
        let data: any = await getItem(PROJECT_STORAGE_KEY);

        if (!data) {
            const lsProject = localStorage.getItem(PROJECT_STORAGE_KEY);
            if (lsProject) {
                try {
                    data = JSON.parse(lsProject);
                    await setItem(PROJECT_STORAGE_KEY, data);
                    localStorage.removeItem(PROJECT_STORAGE_KEY);
                } catch (e) {
                    console.error("Failed to parse legacy local storage", e);
                }
            }
        }

        // Apply Data
        if (data) {
            if (data.characters) setCharacters(data.characters);

            // Migration: rename unlocks -> effects if needed
            if (data.scenes) {
                const migratedScenes = data.scenes.map((s: any) => ({
                    ...s,
                    effects: s.effects || s.unlocks || [], // handle legacy 'unlocks' key
                    isRepeatable: s.isRepeatable || false,
                    locationName: s.locationName || s.name || 'Unknown Location',
                    aiInstructions: s.aiInstructions || ''
                }));
                setScenes(migratedScenes);
            }

            if (data.mapConfig && !data.maps) {
                setMaps([{ ...data.mapConfig, id: 'map1', name: 'Default Map' }]);
            } else if (data.maps) {
                setMaps(data.maps);
            }
        }
    };
    initLoad();
  }, []);

  const handleQuickSave = async () => {
    const data = { characters, scenes, maps };
    await setItem(PROJECT_STORAGE_KEY, data);
    return true;
  };

  const handleExportProject = () => {
    const data = { characters, scenes, maps };
    const jsonString = JSON.stringify(data, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const href = URL.createObjectURL(blob);

    const link = document.createElement('a');
    link.href = href;
    link.download = `vn-project-${new Date().toISOString().slice(0,10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(href);
  };

  const handleImportProject = (file: File) => {
    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const content = e.target?.result as string;
        const data = JSON.parse(content);

        if (data.characters) setCharacters(data.characters);
        if (data.scenes) {
            // Migration for import
            setScenes(data.scenes.map((s: any) => ({
                ...s,
                effects: s.effects || s.unlocks || [],
                isRepeatable: s.isRepeatable || false,
                locationName: s.locationName || s.name || 'Unknown Location',
                aiInstructions: s.aiInstructions || ''
            })));
        }
        if (data.maps) setMaps(data.maps);
        else if (data.mapConfig) setMaps([{ ...data.mapConfig, id: 'map1', name: 'Default Map' }]);

        await setItem(PROJECT_STORAGE_KEY, data);
        alert("Project loaded successfully!");
      } catch (error) {
        console.error("Import failed", error);
        alert("Failed to load project file. Invalid JSON.");
      }
    };
    reader.readAsText(file);
  };

  const handleStartNewGame = () => {
    setRpgState({ 
        currentMapId: maps[0].id, 
        completedSceneIds: [], 
        unlockedIds: [],
        hiddenIds: [],
        ongoingScenes: {} 
    });
    setVnHistory([]);
    setActiveSceneIndex(-1);
    setMode('rpg');
  };

  const handleContinueGame = async () => {
    let savedGame = await getItem<GameSaveData>(GAME_SAVE_KEY);

    if (!savedGame) {
        const lsSave = localStorage.getItem(GAME_SAVE_KEY);
        if (lsSave) {
            try { savedGame = JSON.parse(lsSave); } catch(e) {}
        }
    }

    if (savedGame) {
      try {
        const safeMapId = maps.find(m => m.id === savedGame!.rpgState.currentMapId) ? savedGame!.rpgState.currentMapId : maps[0].id;

        setRpgState({ 
            ...savedGame.rpgState, 
            currentMapId: safeMapId,
            unlockedIds: savedGame.rpgState.unlockedIds || [], 
            hiddenIds: savedGame.rpgState.hiddenIds || [], 
            ongoingScenes: savedGame.rpgState.ongoingScenes || {} 
        });

        if (savedGame.vnState) {
          setActiveSceneIndex(savedGame.vnState.currentSceneIndex);
          setVnHistory(savedGame.vnState.history);
          setMode('vn');
        } else {
          setMode('rpg');
        }
      } catch (e) {
        console.error("Corrupt save file");
        handleStartNewGame();
      }
    }
  };

  const handleSaveGameInternal = async (updatedRpgState: RPGState, vnState: any | null) => {
      const saveData: GameSaveData = {
        rpgState: updatedRpgState,
        vnState: vnState,
        timestamp: Date.now()
      };
      await setItem(GAME_SAVE_KEY, saveData);
      setHasSaveGame(true);
      return true;
  };

  const handleInteraction = (type: 'scene'|'transition'|'character', id: string) => {
      // Check if locked/hidden first
      if (rpgState.hiddenIds.includes(id)) return;

      if (type === 'transition') {
          if (maps.find(m => m.id === id)) {
              setRpgState(prev => ({ ...prev, currentMapId: id }));
          }
      } else if (type === 'character') {
          const charId = id;
          const char = characters.find(c => c.id === charId);
          if (!char) return;

          const availableScenes = scenes.filter(s => s.characters.some(c => c.characterId === charId));

          const playableScene = availableScenes.find(s => {
              // 1. Check completion
              const isCompleted = rpgState.completedSceneIds.includes(s.id);
              if (isCompleted && !s.isRepeatable) return false;

              // 2. Check if explicitly hidden/locked
              if (rpgState.hiddenIds.includes(s.id)) return false;

              // 3. Check dependencies (unlocks)
              const isLockedByOthers = scenes.some(other => other.effects?.some(u => u.type === 'scene' && u.targetId === s.id && u.action === 'unlock'));
              const isUnlocked = rpgState.unlockedIds.includes(s.id);

              return !isLockedByOthers || isUnlocked;
          });

          if (playableScene) {
             startScene(playableScene);
          } else {
             alert(`${char.name} has nothing new to say right now.`);
          }

      } else {
          const sceneId = id; 
          const scene = scenes.find(s => s.id === sceneId);
          if (scene) {
             startScene(scene);
          }
      }
  };

  const startScene = (scene: Scene) => {
      const realIndex = scenes.findIndex(s => s.id === scene.id);
      setActiveSceneIndex(realIndex);

      const existingHistory = rpgState.ongoingScenes?.[scene.id] || [];
      setVnHistory(existingHistory);

      setMode('vn');
  };

  const handleSceneExit = async (completed: boolean, history: ChatMessage[]) => {
      const activeScene = scenes[activeSceneIndex];
      const sceneId = activeScene.id;

      let newState = { ...rpgState };

      if (completed) {
          // 1. Mark as completed
          const newCompletedIds = [...rpgState.completedSceneIds];
          if (!newCompletedIds.includes(sceneId)) {
             newCompletedIds.push(sceneId);
          }

          // 2. Remove from ongoing scenes
          const { [sceneId]: _, ...remainingScenes } = newState.ongoingScenes || {};

          // 3. Process Effects (Unlocks / Locks)
          const newUnlockedIds = [...rpgState.unlockedIds];
          const newHiddenIds = [...rpgState.hiddenIds];

          if (activeScene.effects) {
              activeScene.effects.forEach(effect => {
                  const targetId = effect.targetId;
                  const action = effect.action || 'unlock'; 

                  if (action === 'unlock') {
                      if (!newUnlockedIds.includes(targetId)) {
                          newUnlockedIds.push(targetId);
                      }
                      // If it was hidden, unhide it
                      const hideIdx = newHiddenIds.indexOf(targetId);
                      if (hideIdx > -1) newHiddenIds.splice(hideIdx, 1);

                  } else if (action === 'lock') {
                      if (!newHiddenIds.includes(targetId)) {
                          newHiddenIds.push(targetId);
                      }
                  }
              });
          }

          newState = { 
              ...newState, 
              completedSceneIds: newCompletedIds,
              unlockedIds: newUnlockedIds,
              hiddenIds: newHiddenIds,
              ongoingScenes: remainingScenes
          };

      } else {
          // Just PAUSE
          newState = {
              ...newState,
              ongoingScenes: {
                  ...newState.ongoingScenes,
                  [sceneId]: history
              }
          };
      }

      setRpgState(newState);
      await handleSaveGameInternal(newState, null);
      setMode('rpg');
  };

  const activeMap = maps.find(m => m.id === rpgState.currentMapId) || maps[0];

  return (
    <div className="min-h-screen bg-gray-900 text-gray-100 font-sans selection:bg-indigo-500 selection:text-white">
      {mode === 'edit' && (
        <Editor 
          characters={characters}
          scenes={scenes}
          maps={maps}
          onUpdateCharacters={setCharacters}
          onUpdateScenes={setScenes}
          onUpdateMaps={setMaps}
          onPlay={handleStartNewGame}
          onQuickSave={handleQuickSave}
          onExportProject={handleExportProject}
          onImportProject={handleImportProject}
          hasSaveGame={hasSaveGame}
          onContinueGame={handleContinueGame}
        />
      )}

      {mode === 'rpg' && (
        <RPGWorld 
          characters={characters}
          mapConfig={activeMap}
          maps={maps}
          scenes={scenes}
          initialState={rpgState}
          onInteraction={handleInteraction}
          onSave={async (updatedRpgState) => {
             setRpgState(updatedRpgState);
             await handleSaveGameInternal(updatedRpgState, null);
             alert("Game Saved!");
          }}
          onExit={() => setMode('edit')}
        />
      )}

      {mode === 'vn' && activeSceneIndex >= 0 && (
        <Player 
          scenes={scenes}
          characters={characters}
          initialState={{
            currentSceneIndex: activeSceneIndex,
            history: vnHistory, 
            timestamp: 0,
            rpgState: rpgState, 
            vnState: null
          }}
          onExit={handleSceneExit}
          onSave={async (vnState) => {
             await handleSaveGameInternal(rpgState, vnState);
             return true;
          }}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Plus, Trash2, Image as ImageIcon, User, Target, Save, PlayCircle, RotateCcw, Map as MapIcon, MousePointerClick, FileUp, Download, Upload, Check, Waypoints, Globe, Lock, Unlock, MessageSquare, Ban, RefreshCcw, Eye, EyeOff, Italic, Palette } from 'lucide-react';
import { Character, Scene, SceneCharacterConfig, WorldMap, MapSpot, SceneEffect } from '../types';
import { Button } from './ui/Button';

interface EditorProps {
  characters: Character[];
  scenes: Scene[];
  maps: WorldMap[];
  onUpdateCharacters: (chars: Character[]) => void;
  onUpdateScenes: (scenes: Scene[]) => void;
  onUpdateMaps: (maps: WorldMap[]) => void;
  onPlay: () => void;
  onQuickSave: () => Promise<boolean>;
  onExportProject: () => void;
  onImportProject: (file: File) => void;
  hasSaveGame: boolean;
  onContinueGame: () => void;
}

export const Editor: React.FC<EditorProps> = ({
  characters,
  scenes,
  maps,
  onUpdateCharacters,
  onUpdateScenes,
  onUpdateMaps,
  onPlay,
  onQuickSave,
  onExportProject,
  onImportProject,
  hasSaveGame,
  onContinueGame
}) => {
  const [activeTab, setActiveTab] = useState<'chars' | 'scenes' | 'map'>('chars');

  // Map Editor State
  const [activeMapId, setActiveMapId] = useState<string>(maps[0]?.id || '');
  const [selectedTool, setSelectedTool] = useState<{type: 'scene'|'transition'|'character', id: string} | null>(null);

  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const importInputRef = useRef<HTMLInputElement>(null);

  // --- Character Handlers ---
  const addCharacter = () => {
    const newChar: Character = {
      id: crypto.randomUUID(),
      name: 'New Character',
      defaultDescription: 'A friendly helper.',
      imageSrc: null,
      mapSpriteSrc: null,
      rpgColor: '#ef4444',
      textColor: '#ffffff',
      isItalic: false 
    };
    onUpdateCharacters([...characters, newChar]);
  };

  const updateCharacter = (id: string, updates: Partial<Character>) => {
    onUpdateCharacters(characters.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const handleCharImageUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>, field: 'imageSrc' | 'mapSpriteSrc') => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCharacter(id, { [field]: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  // --- Scene Handlers ---
  const addScene = () => {
    const newScene: Scene = {
      id: crypto.randomUUID(),
      name: `Scene ${scenes.length + 1}`,
      locationName: 'Unknown Location',
      backgroundSrc: null,
      description: 'You are in a quiet room.',
      aiInstructions: '',
      goal: 'Say hello.',
      characters: [],
      effects: [],
      mapIconSrc: null,
      isRepeatable: false
    };
    onUpdateScenes([...scenes, newScene]);
  };

  const updateScene = (id: string, updates: Partial<Scene>) => {
    onUpdateScenes(scenes.map(s => s.id === id ? { ...s, ...updates } : s));
  };

  const handleSceneIconUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { mapIconSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleEffect = (sceneId: string, type: 'scene' | 'transition', targetId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const currentEffects = scene.effects || [];
    const existingEffect = currentEffects.find(u => u.type === type && u.targetId === targetId);

    let newEffects: SceneEffect[];

    if (!existingEffect) {
        newEffects = [...currentEffects, { type, targetId, action: 'unlock' }];
    } else if (existingEffect.action === 'unlock' || !existingEffect.action) {
        newEffects = currentEffects.map(eff => 
            (eff.type === type && eff.targetId === targetId) ? { ...eff, action: 'lock' } : eff
        );
    } else {
        newEffects = currentEffects.filter(u => !(u.type === type && u.targetId === targetId));
    }

    updateScene(sceneId, { effects: newEffects });
  };

  const handleBgUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleCharInScene = (sceneId: string, charId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const exists = scene.characters.find(c => c.characterId === charId);
    let newChars: SceneCharacterConfig[];

    if (exists) {
      newChars = scene.characters.filter(c => c.characterId !== charId);
    } else {
      newChars = [...scene.characters, { characterId: charId, roleInScene: 'Default behavior' }];
    }
    updateScene(sceneId, { characters: newChars });
  };

  const updateSceneCharRole = (sceneId: string, charId: string, role: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;
    const newChars = scene.characters.map(c => c.characterId === charId ? { ...c, roleInScene: role } : c);
    updateScene(sceneId, { characters: newChars });
  };

  // --- Map Handlers ---

  const getCurrentMap = () => maps.find(m => m.id === activeMapId);

  const addMap = () => {
      const newMap: WorldMap = {
          id: crypto.randomUUID(),
          name: `Map ${maps.length + 1}`,
          backgroundSrc: null,
          spots: []
      };
      const newMaps = [...maps, newMap];
      onUpdateMaps(newMaps);
      setActiveMapId(newMap.id);
  };

  const deleteMap = (id: string) => {
      if (maps.length <= 1) {
          alert("You must have at least one map.");
          return;
      }
      const newMaps = maps.filter(m => m.id !== id);
      onUpdateMaps(newMaps);
      if (activeMapId === id) setActiveMapId(newMaps[0].id);
  };

  const updateCurrentMap = (updates: Partial<WorldMap>) => {
      onUpdateMaps(maps.map(m => m.id === activeMapId ? { ...m, ...updates } : m));
  };

  const handleMapBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCurrentMap({ backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const handleMapClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!selectedTool || !mapContainerRef.current) return;
    if ((e.target as HTMLElement).closest('.map-pin')) return;

    const rect = mapContainerRef.current.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;

    const currentMap = getCurrentMap();
    if (!currentMap) return;

    const newSpot: MapSpot = {
      id: crypto.randomUUID(),
      type: selectedTool.type,
      x, 
      y,
      sceneId: selectedTool.type === 'scene' ? selectedTool.id : undefined,
      targetMapId: selectedTool.type === 'transition' ? selectedTool.id : undefined,
      characterId: selectedTool.type === 'character' ? selectedTool.id : undefined,
    };

    updateCurrentMap({ spots: [...currentMap.spots, newSpot] });
  };

  const removeSpot = (spotId: string) => {
    const currentMap = getCurrentMap();
    if(!currentMap) return;
    updateCurrentMap({
      spots: currentMap.spots.filter(s => s.id !== spotId)
    });
  };

  // --- Toolbar Handlers ---

  const handleQuickSaveClick = async () => {
    setSaveStatus('saving');
    await onQuickSave();
    setSaveStatus('saved');
    setTimeout(() => setSaveStatus('idle'), 2000);
  };

  const handleImportClick = () => {
    importInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if(e.target.files && e.target.files[0]) {
        onImportProject(e.target.files[0]);
    }
    if(e.target.value) e.target.value = ''; 
  };

  const currentMap = getCurrentMap();

  return (
    <div className="flex flex-col h-full max-w-6xl mx-auto p-4 md:p-8">
      {/* Header / Toolbar */}
      <div className="flex flex-col xl:flex-row justify-between items-center mb-8 gap-6">
        <div>
           <h1 className="text-3xl font-bold text-indigo-400">VN Creator Studio</h1>
           <p className="text-gray-400 text-sm mt-1">Design your world, characters, and stories.</p>
        </div>

        <div className="flex flex-wrap gap-3 items-center justify-center">
          {/* File Operations */}
          <div className="flex gap-2 mr-2 bg-gray-800 p-1 rounded-lg border border-gray-700">
             <input type="file" ref={importInputRef} className="hidden" accept=".json" onChange={handleFileChange} />
             <button onClick={handleImportClick} className="flex items-center gap-2 px-3 py-2 text-sm text-gray-300 hover:text-white hover:bg-gray-700 rounded transition" title="Load .json file">
               <Upload size={16} /> Load Project
             </button>
             <div className="w-[1px] bg-gray-600 my-1"></div>
             <button onClick={onExportProject} className="flex items-center gap-2 px-3 py-2 text-sm text-gray-300 hover:text-white hover:bg-gray-700 rounded transition" title="Download .json file">
               <Download size={16} /> Export Project
             </button>
          </div>

          <Button onClick={handleQuickSaveClick} variant="secondary" title="Saves to Browser Storage" className="min-w-[140px]" disabled={saveStatus === 'saving'}>
            {saveStatus === 'saved' ? <><Check size={18} className="text-green-400"/> Saved!</> : (saveStatus === 'saving' ? 'Saving...' : <><Save size={18} /> Quick Save</>)}
          </Button>

          <div className="h-8 w-[1px] bg-gray-700 mx-2 hidden md:block"></div>

          {hasSaveGame && (
            <Button onClick={onContinueGame} className="bg-yellow-600 hover:bg-yellow-500">
              <RotateCcw size={18} /> Continue
            </Button>
          )}

          <Button onClick={onPlay} className="bg-green-600 hover:bg-green-500 px-6 font-bold shadow-green-900/20">
            <PlayCircle size={18} /> PLAY GAME
          </Button>
        </div>
      </div>

      <div className="flex gap-4 mb-6 border-b border-gray-700 pb-1">
        <button onClick={() => setActiveTab('chars')} className={`px-4 py-2 font-medium transition-colors ${activeTab === 'chars' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}>Characters</button>
        <button onClick={() => setActiveTab('scenes')} className={`px-4 py-2 font-medium transition-colors ${activeTab === 'scenes' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}>Scenarios</button>
        <button onClick={() => setActiveTab('map')} className={`px-4 py-2 font-medium transition-colors ${activeTab === 'map' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}>World Map</button>
      </div>

      <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
        {activeTab === 'chars' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {characters.map(char => (
                <div key={char.id} className="bg-gray-800 p-4 rounded-xl border border-gray-700 flex gap-4 shadow-lg hover:border-gray-600 transition-colors">
                  <div className="w-24 h-32 bg-gray-900 rounded-lg flex-shrink-0 border border-gray-600 overflow-hidden relative group">
                    {char.imageSrc ? (
                      <img src={char.imageSrc} alt={char.name} className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full flex flex-col items-center justify-center text-gray-600 gap-1"><User size={24} /><span className="text-[10px] text-center px-1">Portrait</span></div>
                    )}
                    <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity text-xs font-bold">
                      UPLOAD
                      <input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e, 'imageSrc')} />
                    </label>
                  </div>
                  <div className="flex-1 space-y-3">
                    <input className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-1 focus:border-indigo-500 outline-none transition-all" value={char.name} onChange={(e) => updateCharacter(char.id, { name: e.target.value })} placeholder="Character Name" />

                    <div className="grid grid-cols-2 gap-3">
                       {/* Map Sprite & Color */}
                       <div className="flex items-center gap-2">
                           <div className="w-10 h-10 bg-gray-900 rounded border border-gray-600 overflow-hidden relative group shrink-0">
                             {char.mapSpriteSrc ? <img src={char.mapSpriteSrc} alt="Sprite" className="w-full h-full object-contain" /> : <div className="w-full h-full flex items-center justify-center text-gray-600" title="Map Sprite"><MapIcon size={16} /></div>}
                             <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity">
                                <FileUp size={16} className="text-white"/>
                                <input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e, 'mapSpriteSrc')} />
                             </label>
                           </div>
                           <div className="text-xs text-gray-400">Map Sprite</div>
                       </div>

                       {/* Text Settings */}
                       <div className="flex flex-col gap-2">
                          <label className="flex items-center gap-2 text-xs text-gray-400 cursor-pointer" title="Chat Text Color">
                             <input type="color" className="w-6 h-6 rounded bg-transparent cursor-pointer border-none p-0" value={char.textColor || '#ffffff'} onChange={(e) => updateCharacter(char.id, { textColor: e.target.value })} />
                             <span>Text Color</span>
                          </label>
                          <label className="flex items-center gap-2 text-xs text-gray-400 cursor-pointer">
                             <input type="checkbox" className="accent-indigo-500 rounded" checked={char.isItalic || false} onChange={(e) => updateCharacter(char.id, { isItalic: e.target.checked })} />
                             <span className={char.isItalic ? 'italic' : ''}>Italic Text</span>
                          </label>
                       </div>
                    </div>

                    <textarea className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-1 h-20 text-sm focus:border-indigo-500 outline-none resize-none transition-all" value={char.defaultDescription} onChange={(e) => updateCharacter(char.id, { defaultDescription: e.target.value })} placeholder="Core Persona/Description..." />
                  </div>
                  <button onClick={() => onUpdateCharacters(characters.filter(c => c.id !== char.id))} className="text-gray-500 hover:text-red-500 h-fit transition-colors p-1"><Trash2 size={18} /></button>
                </div>
              ))}
            </div>
            <Button onClick={addCharacter} variant="secondary" className="w-full py-4 border-dashed opacity-70 hover:opacity-100"><Plus size={20} /> Add Character</Button>
          </div>
        )}

        {activeTab === 'scenes' && (
          <div className="space-y-8">
            {scenes.map((scene, idx) => (
              <div key={scene.id} className="bg-gray-800 p-6 rounded-xl border border-gray-700 space-y-4 shadow-lg">
                <div className="flex justify-between items-start">
                  <div className="flex-1 space-y-2 mr-4">
                     <div className="flex items-center gap-4">
                        <div className="bg-gray-900 px-3 py-1 rounded text-xs font-bold text-indigo-400 border border-gray-700">SCENE {idx + 1}</div>
                        <input className="bg-transparent text-xl font-bold outline-none placeholder-gray-600 focus:text-white transition-colors" value={scene.name} onChange={(e) => updateScene(scene.id, { name: e.target.value })} placeholder="Scene Name (e.g. Chapter 1)" />
                     </div>
                     <input className="w-full bg-gray-900/50 border-b border-gray-700 text-sm py-1 px-2 focus:border-indigo-500 outline-none transition-colors text-indigo-200" value={scene.locationName || ''} onChange={(e) => updateScene(scene.id, { locationName: e.target.value })} placeholder="Location Name (Visible to Player, e.g. 'Old Library')" />
                  </div>
                  <button onClick={() => onUpdateScenes(scenes.filter(s => s.id !== scene.id))} className="text-gray-500 hover:text-red-500 transition-colors p-1"><Trash2 size={18} /></button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                  {/* Visuals & Goal */}
                  <div className="space-y-4">
                    <div className="w-full h-40 bg-gray-900 rounded-lg border border-gray-600 overflow-hidden relative group shadow-inner">
                       {scene.backgroundSrc ? (
                          <img src={scene.backgroundSrc} alt="bg" className="w-full h-full object-cover opacity-80" />
                       ) : (
                         <div className="w-full h-full flex items-center justify-center text-gray-500 gap-2"><ImageIcon size={24} /> No Background</div>
                       )}
                       <label className="absolute inset-0 flex items-center justify-center cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity bg-black/40">
                          <span className="bg-black/80 px-4 py-2 rounded hover:bg-black text-sm border border-gray-600">Change Background</span>
                          <input type="file" accept="image/*" className="hidden" onChange={(e) => handleBgUpload(scene.id, e)} />
                       </label>
                    </div>

                    <div className="flex items-center gap-3 bg-gray-900/50 p-2 rounded border border-gray-700">
                       <div className="w-10 h-10 bg-gray-900 rounded border border-gray-600 overflow-hidden relative group shrink-0">
                         {scene.mapIconSrc ? <img src={scene.mapIconSrc} alt="Icon" className="w-full h-full object-contain" /> : (scene.characters.length > 0 && characters.find(c => c.id === scene.characters[0].characterId)?.mapSpriteSrc ? <img src={characters.find(c => c.id === scene.characters[0].characterId)?.mapSpriteSrc!} className="w-full h-full object-contain opacity-50 grayscale" /> : <div className="w-full h-full flex items-center justify-center text-gray-600"><MapIcon size={14} /></div>)}
                         <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity"><FileUp size={12} className="text-white"/><input type="file" accept="image/*" className="hidden" onChange={(e) => handleSceneIconUpload(scene.id, e)} /></label>
                       </div>
                       <div className="text-xs text-gray-400"><span className="font-bold block text-gray-300">Map Icon</span><span className="text-[10px]">Overrides char sprite.</span></div>
                    </div>

                    <div className="space-y-2">
                      <div className="flex justify-between items-center">
                          <label className="flex items-center gap-2 text-xs font-bold text-green-400"><Target size={14} /> WIN CONDITION</label>
                          <label className="flex items-center gap-2 text-[10px] text-gray-400 cursor-pointer select-none">
                            <input type="checkbox" className="accent-indigo-500" checked={scene.isRepeatable || false} onChange={(e) => updateScene(scene.id, { isRepeatable: e.target.checked })} />
                            <span className={scene.isRepeatable ? 'text-indigo-300 font-bold' : ''}>Repeatable?</span>
                          </label>
                      </div>
                      <textarea className="w-full bg-gray-900 border border-green-900/50 text-green-100 rounded px-3 py-2 text-sm focus:border-green-500 outline-none resize-none transition-all shadow-inner placeholder-gray-600" value={scene.goal} onChange={(e) => updateScene(scene.id, { goal: e.target.value })} placeholder="e.g. Find the key... (LEAVE EMPTY for endless conversation)" rows={3} />
                    </div>

                    <div className="bg-gray-900/50 p-3 rounded-lg border border-gray-700">
                        <label className="flex items-center gap-2 text-xs font-bold text-yellow-500 mb-2"><Unlock size={14} /> COMPLETION EFFECTS</label>
                        <div className="space-y-2 max-h-32 overflow-y-auto custom-scrollbar">
                            {scenes.filter(s => s.id !== scene.id).map(otherScene => {
                                const effect = scene.effects?.find(u => u.type === 'scene' && u.targetId === otherScene.id);
                                let stateClass = 'bg-gray-800 border-gray-700 text-gray-500';
                                let Icon = Lock;
                                if (effect?.action === 'unlock' || (effect && !effect.action)) { stateClass = 'bg-emerald-900/30 border-emerald-600 text-emerald-200'; Icon = Unlock; } else if (effect?.action === 'lock') { stateClass = 'bg-red-900/30 border-red-600 text-red-200'; Icon = Ban; }
                                return (<button key={otherScene.id} onClick={() => toggleEffect(scene.id, 'scene', otherScene.id)} className={`w-full flex items-center gap-2 text-xs p-1.5 rounded border transition-colors ${stateClass} hover:border-gray-400`}><Icon size={12} /><span className="truncate flex-1 text-left">Scene: {otherScene.name}</span>{effect?.action === 'unlock' && <span className="text-[10px] uppercase font-bold">Unlocks</span>}{effect?.action === 'lock' && <span className="text-[10px] uppercase font-bold">Locks</span>}</button>);
                            })}
                            {maps.map(m => {
                                const effect = scene.effects?.find(u => u.type === 'transition' && u.targetId === m.id);
                                let stateClass = 'bg-gray-800 border-gray-700 text-gray-500';
                                let Icon = Lock;
                                if (effect?.action === 'unlock' || (effect && !effect.action)) { stateClass = 'bg-emerald-900/30 border-emerald-600 text-emerald-200'; Icon = Globe; } else if (effect?.action === 'lock') { stateClass = 'bg-red-900/30 border-red-600 text-red-200'; Icon = Ban; }
                                return (<button key={m.id} onClick={() => toggleEffect(scene.id, 'transition', m.id)} className={`w-full flex items-center gap-2 text-xs p-1.5 rounded border transition-colors ${stateClass} hover:border-gray-400`}><Icon size={12} /><span className="truncate flex-1 text-left">Travel to: {m.name}</span>{effect?.action === 'unlock' && <span className="text-[10px] uppercase font-bold">Unlocks</span>}{effect?.action === 'lock' && <span className="text-[10px] uppercase font-bold">Locks</span>}</button>);
                            })}
                        </div>
                    </div>
                  </div>

                  {/* Narrative Setup */}
                  <div className="space-y-2 lg:col-span-2 flex flex-col h-full">
                     <label className="block text-xs font-bold text-gray-400 flex items-center gap-2"><Eye size={14}/> VISIBLE DESCRIPTION (Intro text for Player & AI)</label>
                     <textarea
                        className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-2 text-sm focus:border-indigo-500 outline-none resize-none transition-all"
                        value={scene.description}
                        onChange={(e) => updateScene(scene.id, { description: e.target.value })}
                        placeholder="Describe the setting, the mood, and what is happening initially..."
                        rows={4}
                      />

                     <label className="block text-xs font-bold text-rose-400 mt-4 flex items-center gap-2"><EyeOff size={14}/> HIDDEN AI INSTRUCTIONS (God Mode)</label>
                     <p className="text-[10px] text-gray-500 mb-1">Secrets, plot twists, or specific behavior instructions the player cannot see.</p>
                     <textarea
                        className="w-full bg-gray-900 border border-rose-900/50 text-rose-100 rounded px-3 py-2 text-sm focus:border-rose-500 outline-none resize-none transition-all shadow-inner placeholder-rose-900/50"
                        value={scene.aiInstructions || ''}
                        onChange={(e) => updateScene(scene.id, { aiInstructions: e.target.value })}
                        placeholder="e.g. 'The character is secretly a ghost', 'It is raining heavily', 'Character X is lying about the key'..."
                        rows={3}
                      />

                      <label className="block text-xs font-bold text-gray-400 mt-4">PARTICIPATING CHARACTERS</label>
                      <div className="bg-gray-900 rounded-lg p-3 border border-gray-700 min-h-[100px] shadow-inner flex-1">
                         <div className="flex gap-2 flex-wrap mb-3">
                           {characters.map(char => {
                             const isActive = scene.characters.some(c => c.characterId === char.id);
                             return (<button key={char.id} onClick={() => toggleCharInScene(scene.id, char.id)} className={`text-xs px-3 py-1 rounded-full border transition-all ${isActive ? 'bg-indigo-600 border-indigo-400 text-white shadow-md' : 'bg-gray-800 border-gray-600 text-gray-400 hover:border-gray-400 hover:text-gray-300'}`}>{char.name}</button>)
                           })}
                           {characters.length === 0 && <span className="text-xs text-gray-600 italic">No characters created yet.</span>}
                         </div>
                         <div className="space-y-3">
                           {scene.characters.map(sc => {
                             const char = characters.find(c => c.id === sc.characterId);
                             if (!char) return null;
                             return (
                               <div key={sc.characterId} className="flex items-center gap-3 bg-gray-800 p-2 rounded border border-gray-700">
                                 <div className="w-8 h-8 rounded-full bg-gray-700 overflow-hidden flex-shrink-0 border border-gray-600" style={{ backgroundColor: char.rpgColor }}>{char.imageSrc && <img src={char.imageSrc} className="w-full h-full object-cover" />}</div>
                                 <div className="flex-1"><div className="text-xs font-bold text-indigo-300">{char.name} Role</div><input className="w-full bg-transparent border-b border-gray-600 text-xs py-1 focus:border-indigo-400 outline-none transition-colors" placeholder="What does this character want in this scene?" value={sc.roleInScene} onChange={(e) => updateSceneCharRole(scene.id, sc.characterId, e.target.value)} /></div>
                               </div>
                             )
                           })}
                         </div>
                      </div>
                  </div>
                </div>
              </div>
            ))}
            <Button onClick={addScene} variant="secondary" className="w-full py-4 border-dashed opacity-70 hover:opacity-100"><Plus size={20} /> Add Scenario</Button>
          </div>
        )}

        {/* MAP TAB */}
        {activeTab === 'map' && (
          <div className="flex flex-col lg:flex-row gap-6 h-full">
            <div className="w-full lg:w-64 flex flex-col gap-6">
              <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 shadow-lg space-y-3">
                  <div className="flex items-center justify-between mb-2"><h3 className="font-bold text-gray-300 flex items-center gap-2"><Globe size={16}/> Maps</h3><button onClick={addMap} className="text-indigo-400 hover:text-white p-1 rounded bg-indigo-900/30 hover:bg-indigo-600 transition"><Plus size={14} /></button></div>
                  <div className="space-y-2 max-h-32 overflow-y-auto custom-scrollbar">{maps.map(m => (<div key={m.id} className={`flex items-center justify-between p-2 rounded cursor-pointer border ${m.id === activeMapId ? 'bg-indigo-900/50 border-indigo-500' : 'bg-gray-900 border-gray-800 hover:border-gray-600'}`} onClick={() => setActiveMapId(m.id)}><span className="text-xs truncate max-w-[120px]">{m.name}</span>{maps.length > 1 && (<button onClick={(e) => { e.stopPropagation(); deleteMap(m.id); }} className="text-gray-600 hover:text-red-400"><Trash2 size={12} /></button>)}</div>))}</div>
                  {currentMap && (<div className="pt-2 border-t border-gray-700"><input className="w-full bg-gray-900 border border-gray-600 rounded px-2 py-1 text-xs text-gray-200 outline-none focus:border-indigo-500" value={currentMap.name} onChange={(e) => updateCurrentMap({ name: e.target.value })} placeholder="Map Name" /></div>)}
              </div>
              {currentMap && (<div className="bg-gray-800 p-4 rounded-xl border border-gray-700 shadow-lg"><h3 className="font-bold text-gray-300 mb-3 flex items-center gap-2 text-sm"><MapIcon size={14}/> Background</h3><label className="block w-full cursor-pointer bg-gray-900 border border-gray-600 hover:border-gray-400 hover:bg-gray-800 text-center py-4 rounded-lg border-dashed transition-all group"><span className="text-xs text-gray-400 group-hover:text-white">Change Image</span><input type="file" accept="image/*" className="hidden" onChange={handleMapBgUpload} /></label></div>)}
              <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 flex-1 shadow-lg flex flex-col min-h-[300px]">
                 <h3 className="font-bold text-gray-300 mb-3 flex items-center gap-2 text-sm"><User size={14}/> Place Items</h3>
                 <div className="space-y-4 overflow-y-auto custom-scrollbar flex-1">
                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2">Scenarios</div>
                        <div className="space-y-1">{scenes.map(scene => { let iconSrc = scene.mapIconSrc; let bgColor = '#4b5563'; if (!iconSrc && scene.characters.length > 0) { const char = characters.find(c => c.id === scene.characters[0].characterId); if(char) { iconSrc = char.mapSpriteSrc; bgColor = char.rpgColor; } } return (<button key={scene.id} onClick={() => setSelectedTool(selectedTool?.id === scene.id ? null : { type: 'scene', id: scene.id })} className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === scene.id && selectedTool.type === 'scene' ? 'bg-indigo-600/20 border-indigo-500 ring-1 ring-indigo-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}><div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 overflow-hidden flex items-center justify-center flex-shrink-0" style={{ backgroundColor: bgColor }}>{iconSrc ? <img src={iconSrc} className="w-full h-full object-contain" /> : <MessageSquare size={12} className="text-gray-400"/>}</div><span className="text-xs font-medium truncate flex-1 text-left">{scene.name}</span>{selectedTool?.id === scene.id && selectedTool.type === 'scene' && <MousePointerClick size={12} className="ml-auto text-indigo-400"/>}</button>); })}</div>
                    </div>
                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2 mt-4">Characters</div>
                        <div className="space-y-1">{characters.map(char => (<button key={char.id} onClick={() => setSelectedTool(selectedTool?.id === char.id ? null : { type: 'character', id: char.id })} className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === char.id && selectedTool.type === 'character' ? 'bg-indigo-600/20 border-indigo-500 ring-1 ring-indigo-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}><div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 overflow-hidden flex items-center justify-center flex-shrink-0" style={{ backgroundColor: char.rpgColor }}>{char.mapSpriteSrc ? <img src={char.mapSpriteSrc} className="w-full h-full object-contain" /> : null}</div><span className="text-xs font-medium truncate flex-1 text-left">{char.name}</span>{selectedTool?.id === char.id && selectedTool.type === 'character' && <MousePointerClick size={12} className="ml-auto text-indigo-400"/>}</button>))}</div>
                    </div>
                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2 mt-4">Map Transitions</div>
                        <div className="space-y-1">{maps.filter(m => m.id !== activeMapId).map(targetMap => (<button key={targetMap.id} onClick={() => setSelectedTool(selectedTool?.id === targetMap.id ? null : { type: 'transition', id: targetMap.id })} className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === targetMap.id && selectedTool.type === 'transition' ? 'bg-emerald-600/20 border-emerald-500 ring-1 ring-emerald-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}><div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 flex items-center justify-center flex-shrink-0 text-emerald-500"><Waypoints size={14} /></div><span className="text-xs font-medium truncate flex-1 text-left">To: {targetMap.name}</span>{selectedTool?.id === targetMap.id && selectedTool.type === 'transition' && <MousePointerClick size={12} className="ml-auto text-emerald-400"/>}</button>))}</div>
                    </div>
                 </div>
              </div>
            </div>
            <div className="flex-1 bg-gray-900 rounded-xl border-[4px] border-gray-800 shadow-2xl overflow-hidden relative group">
                {currentMap && currentMap.backgroundSrc ? (<div ref={mapContainerRef} onClick={handleMapClick} className="relative w-full h-full cursor-crosshair"><img src={currentMap.backgroundSrc} alt="World Map" className="w-full h-full object-contain bg-black select-none pointer-events-none" />{currentMap.spots.map(spot => { 
                    if (spot.type === 'scene') { 
                        const scene = scenes.find(s => s.id === spot.sceneId); 
                        let iconSrc = scene?.mapIconSrc; let bgColor = '#ffffff'; let name = scene?.name || 'Unknown Scene'; 
                        if (scene && !iconSrc && scene.characters.length > 0) { const char = characters.find(c => c.id === scene.characters[0].characterId); if(char) { iconSrc = char.mapSpriteSrc; bgColor = char.rpgColor; } } 

                        return (
                          <div key={spot.id} className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin" style={{ left: `${spot.x}%`, top: `${spot.y}%` }}>
                            <div className="relative drop-shadow-lg transition hover:scale-110 flex items-center justify-center">
                              {iconSrc ? (
                                <div className="w-12 h-12"><img src={iconSrc} alt={name} className="w-full h-full object-contain" /></div>
                              ) : (
                                <div className="w-10 h-10 rounded-lg border-2 border-white shadow-md flex items-center justify-center bg-indigo-600 text-white" title={name}>
                                   <MessageSquare size={20} fill="currentColor" />
                                </div>
                              )}
                            </div>
                            <span className="bg-black/70 text-[10px] px-2 rounded text-white whitespace-nowrap mt-1 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none backdrop-blur-sm">{name}</span>
                            <button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110"><Trash2 size={12} /></button>
                          </div>
                        ) 
                    } else if (spot.type === 'character') { 
                        const char = characters.find(c => c.id === spot.characterId); const name = char?.name || 'Unknown'; 
                        return (<div key={spot.id} className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin" style={{ left: `${spot.x}%`, top: `${spot.y}%` }}><div className="w-12 h-12 relative drop-shadow-lg transition hover:scale-110 flex items-center justify-center">{char?.mapSpriteSrc ? (<img src={char.mapSpriteSrc} alt={name} className="w-full h-full object-contain" />) : (<div className="w-4 h-4 rounded-full border border-white shadow-sm mb-1" style={{ backgroundColor: char?.rpgColor }} />)}</div><span className="bg-black/70 text-[10px] px-2 rounded text-white whitespace-nowrap mt-1 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none backdrop-blur-sm">{name}</span><button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110"><Trash2 size={12} /></button></div>) 
                    } else { 
                        const target = maps.find(m => m.id === spot.targetMapId); 
                        return (<div key={spot.id} className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin" style={{ left: `${spot.x}%`, top: `${spot.y}%` }}><div className="w-8 h-8 rounded-full bg-emerald-500/50 border-2 border-emerald-400 flex items-center justify-center shadow-lg hover:scale-110 transition"><Waypoints size={16} className="text-white" /></div><span className="bg-emerald-900/90 text-[10px] px-2 rounded text-emerald-100 whitespace-nowrap mt-1 opacity-100 transition-opacity pointer-events-none backdrop-blur-sm border border-emerald-700">Go to: {target?.name || 'Unknown'}</span><button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110"><Trash2 size={12} /></button></div>) 
                    } 
                })}</div>) : (<div className="w-full h-full flex flex-col items-center justify-center text-gray-600 gap-4"><MapIcon size={48} opacity={0.5} /><p>Upload a background for {currentMap ? currentMap.name : 'Unknown'}.</p></div>)}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Scene, Character, ChatMessage, GameState, GameSaveData } from '../types';
import { generateGameTurn } from '../services/geminiService';
import { Button } from './ui/Button';
import { ArrowLeft, RefreshCw, Send, Save, Map, CheckCircle, Play, MapPin } from 'lucide-react';

interface PlayerProps {
  scenes: Scene[];
  characters: Character[];
  initialState: any; // Using any loosely here because we are mixing save data types
  onExit: (success: boolean, history: ChatMessage[]) => void; 
  onSave: (vnState: any) => Promise<boolean>;
}

export const Player: React.FC<PlayerProps> = ({ scenes, characters, initialState, onExit, onSave }) => {
  const [state, setState] = useState<GameState>({
    currentSceneIndex: initialState?.currentSceneIndex || 0,
    history: initialState?.history || [],
    isProcessing: false,
    gameOver: false,
  });
  const [userInput, setUserInput] = useState('');

  // Track goal reached state locally to show UI elements
  const [goalReached, setGoalReached] = useState(false);
  const [goalReason, setGoalReason] = useState<string | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);
  const [isSaving, setIsSaving] = useState(false);

  const currentScene = scenes[state.currentSceneIndex];

  // Logic: Active characters are those present in the scene logic (for AI context)
  const activeCharacters = currentScene?.characters
    .map(sc => characters.find(c => c.id === sc.characterId))
    .filter((c): c is Character => !!c) || [];

  // Logic: Visible characters are strictly those with an imageSrc. 
  // Characters without images (Narrators, etc.) are invisible on screen but present in chat.
  const visibleCharacters = activeCharacters.filter(c => !!c.imageSrc);

  // Auto-scroll chat
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [state.history]);

  // Initial greeting from System/Narrator when scene starts (only if history is empty)
  useEffect(() => {
    if (!currentScene || state.history.length > 0) return;
    setState(prev => ({
      ...prev,
      history: [{
        sender: 'system',
        text: currentScene.description,
        timestamp: Date.now(),
      }]
    }));
  }, [state.currentSceneIndex, currentScene]);

  const handleSendMessage = async () => {
    if (!userInput.trim() || state.isProcessing || !currentScene) return;

    const newMessage: ChatMessage = {
      sender: 'user',
      text: userInput,
      timestamp: Date.now(),
    };

    // Optimistic update
    setState(prev => ({
      ...prev,
      history: [...prev.history, newMessage],
      isProcessing: true,
    }));
    setUserInput('');

    try {
      const aiResponse = await generateGameTurn(
        newMessage.text,
        state.history, // send previous history
        currentScene,
        characters
      );

      const newMessages: ChatMessage[] = aiResponse.characterResponses.map(resp => ({
        sender: 'model',
        characterId: resp.characterId,
        text: resp.text,
        timestamp: Date.now(),
      }));

      setState(prev => ({
        ...prev,
        history: [...prev.history, ...newMessages],
        isProcessing: false,
      }));

      if (aiResponse.sceneGoalReached) {
        setGoalReached(true);
        setGoalReason(aiResponse.sceneTransitionReason || "Objective Completed.");
      }

    } catch (error) {
      console.error("Turn error", error);
      setState(prev => ({ ...prev, isProcessing: false }));
    }
  };

  const handleManualExit = (complete: boolean) => {
      onExit(complete, state.history);
  };

  const handleSaveGame = async () => {
    if (isSaving) return;
    setIsSaving(true);

    const vnState = {
       currentSceneIndex: state.currentSceneIndex,
       history: state.history,
       isProcessing: false,
       gameOver: false
    };

    const btn = document.getElementById('save-btn');
    if (btn) btn.innerHTML = '...';

    await onSave(vnState);

    if (btn) {
      btn.innerHTML = 'Saved!';
      setTimeout(() => btn.innerHTML = '', 2000); 
      setTimeout(() => setIsSaving(false), 1500);
    } else {
        setIsSaving(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  if (!currentScene) {
    return <div className="flex items-center justify-center h-full">Scene Data Error. <button onClick={() => handleManualExit(false)}>Back</button></div>;
  }

  return (
    // Fixed container filling the screen
    <div className="fixed inset-0 z-[100] bg-black overflow-hidden flex flex-col">

      {/* Background Layer - Original Full Screen Cover Mode */}
      <div className="absolute inset-0 z-0 bg-gray-950">
        {currentScene.backgroundSrc ? (
             <img 
                src={currentScene.backgroundSrc} 
                alt="bg" 
                className="w-full h-full object-cover"
             />
        ) : (
          <div className="w-full h-full bg-gradient-to-b from-gray-800 to-gray-900" />
        )}
        {/* Dark Overlay for UI readability */}
        <div className="absolute inset-0 bg-black/20 z-10 pointer-events-none" />
      </div>

      {/* Top Bar Navigation */}
      <div className="absolute top-4 left-4 right-4 z-50 flex justify-between items-start pointer-events-none">

        {/* Back / Pause Button */}
        <button 
           onClick={() => handleManualExit(false)}
           className="pointer-events-auto flex items-center gap-2 bg-black/50 hover:bg-black/70 text-gray-200 px-4 py-2 rounded-full backdrop-blur-md border border-white/10 transition-all hover:scale-105 shadow-lg group"
        >
           <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" />
           <span className="font-semibold text-sm">Resume Later</span>
        </button>

        {/* Location Display */}
        <div className="bg-black/50 backdrop-blur-md border border-white/10 px-4 py-2 rounded-full text-indigo-200 font-bold text-sm shadow-lg flex items-center gap-2">
            <MapPin size={14} className="text-indigo-400" />
            {currentScene.locationName || 'Unknown Location'}
        </div>

        {/* Goal Indicator */}
        <div className={`pointer-events-auto flex flex-col items-end gap-2 transition-all duration-500 ${goalReached ? 'translate-y-0 opacity-100' : '-translate-y-4 opacity-0'}`}>
           {goalReached && (
             <>
               <div className="bg-emerald-900/90 text-emerald-100 px-4 py-2 rounded-lg border border-emerald-500/50 shadow-2xl backdrop-blur-md animate-in slide-in-from-top-4">
                  <div className="flex items-center gap-2 font-bold mb-1">
                      <CheckCircle size={18} className="text-emerald-400" /> Goal Reached!
                  </div>
                  <p className="text-xs opacity-90 max-w-[200px]">{goalReason}</p>
               </div>

               <button 
                  onClick={() => handleManualExit(true)}
                  className="bg-emerald-600 hover:bg-emerald-500 text-white px-5 py-3 rounded-full font-bold shadow-lg shadow-emerald-900/50 flex items-center gap-2 animate-pulse hover:animate-none transition-all transform hover:scale-105"
               >
                  Finish Scenario <Play size={16} fill="currentColor" />
               </button>
             </>
           )}
        </div>
      </div>

      {/* Character Layer - Positioned above the background, below UI */}
      {/* We use visibleCharacters map to ensure characters without portraits don't take up layout space */}
      <div className="absolute bottom-[36vh] left-0 right-0 z-20 flex justify-center items-end px-10 h-[60vh] pointer-events-none">
        {visibleCharacters.map((char, idx) => (
          <div 
             key={char.id} 
             className="relative transition-transform duration-500 transform"
             style={{ 
                zIndex: 20 + idx, 
                marginLeft: idx > 0 ? '-50px' : '0',
                filter: state.isProcessing ? 'brightness(0.7)' : 'brightness(1)' 
             }}
          >
             {/* Only render if image exists (redundant check due to filter, but safe) */}
             {char.imageSrc && (
               <img 
                 src={char.imageSrc} 
                 alt={char.name} 
                 className="max-h-[60vh] w-auto object-contain drop-shadow-2xl"
               />
             )}
            <div className="absolute bottom-4 left-0 right-0 text-center">
               <span className="bg-black/60 text-white px-2 py-1 rounded text-sm backdrop-blur-sm">{char.name}</span>
            </div>
          </div>
        ))}
      </div>

      {/* UI Layer - Chat Box */}
      <div className="absolute bottom-0 left-0 right-0 z-30 p-4 md:p-8 bg-gradient-to-t from-black via-black/90 to-transparent pt-24">
        <div className="max-w-4xl mx-auto bg-black/80 border border-gray-700 rounded-xl backdrop-blur-md shadow-2xl overflow-hidden flex flex-col h-[35vh]">

          {/* Chat History */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4">
            {state.history.map((msg, i) => {
              const char = characters.find(c => c.id === msg.characterId);
              const isUser = msg.sender === 'user';
              const isSystem = msg.sender === 'system';

              if (isSystem) return (
                <div key={i} className="text-center text-yellow-500 italic text-sm my-4 px-8">
                  {msg.text}
                </div>
              );

              // Apply custom styles if available for this character
              const textStyle: React.CSSProperties = {};
              if (!isUser && char) {
                  if (char.textColor) textStyle.color = char.textColor;
                  if (char.isItalic) textStyle.fontStyle = 'italic';
              }

              return (
                <div key={i} className={`flex flex-col ${isUser ? 'items-end' : 'items-start'}`}>
                   <div className="text-xs text-gray-400 mb-1 px-1">
                     {isUser ? 'You' : (char?.name || 'Unknown')}
                   </div>
                   <div 
                      className={`px-4 py-2 rounded-lg max-w-[85%] leading-relaxed ${
                        isUser 
                          ? 'bg-indigo-600 text-white rounded-br-none' 
                          : 'bg-gray-800 rounded-bl-none border border-gray-700'
                      }`}
                      style={!isUser ? textStyle : undefined}
                   >
                     {msg.text}
                   </div>
                </div>
              );
            })}
            {state.isProcessing && (
              <div className="flex items-center gap-2 text-gray-500 text-sm px-4">
                <RefreshCw className="animate-spin" size={14} /> AI is thinking...
              </div>
            )}

            {/* System Message inside chat when goal reached */}
            {goalReached && (
                <div className="text-center my-4 animate-in fade-in zoom-in duration-300">
                    <span className="bg-emerald-900/50 text-emerald-300 border border-emerald-600/50 px-3 py-1 rounded-full text-xs font-bold">
                        ★ Objective Complete
                    </span>
                </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-4 border-t border-gray-700 bg-gray-900/50 flex gap-3">
             <button 
               id="save-btn"
               onClick={handleSaveGame} 
               disabled={isSaving}
               className="bg-gray-700 hover:bg-gray-600 disabled:opacity-50 text-gray-300 p-3 rounded-lg transition-colors flex items-center justify-center min-w-[50px]"
               title="Save Current Progress"
             >
               {!isSaving && <Save size={20} />}
             </button>

             <input
               type="text"
               className="flex-1 bg-gray-800 border border-gray-600 rounded-lg px-4 py-3 text-white focus:border-indigo-500 outline-none transition-colors"
               placeholder={goalReached ? "You can keep chatting or leave..." : "What do you say/do?"}
               value={userInput}
               onChange={(e) => setUserInput(e.target.value)}
               onKeyDown={handleKeyDown}
               autoFocus
               disabled={state.isProcessing}
             />
             <button 
                onClick={handleSendMessage}
                disabled={!userInput.trim() || state.isProcessing}
                className="bg-indigo-600 hover:bg-indigo-500 disabled:bg-gray-700 disabled:cursor-not-allowed text-white p-3 rounded-lg transition-colors"
             >
               <Send size={20} />
             </button>
          </div>

        </div>

        {/* Current Goal Display (Hide if reached to reduce clutter, or keep?) - Keeping but dimming */}
        {!goalReached && (
            <div className="absolute top-4 right-4 md:right-12 bg-black/60 backdrop-blur text-xs text-green-400 px-3 py-1 rounded border border-green-900 pointer-events-none hidden md:block">
            Objective: {currentScene.goal}
            </div>
        )}
      </div>
    </div>
  );
};

export interface Character {
  id: string;
  name: string;
  defaultDescription: string;
  imageSrc: string | null; // Portrait for VN (Large)
  mapSpriteSrc: string | null; // Sprite for Map (Small/Icon)
  rpgColor: string; // Fallback Hex color for Map dots

  // New visual settings for Chat
  bubbleColor?: string; // Hex color for the chat bubble background
  isItalic?: boolean; // If true, text renders in italics (good for narrators/thoughts)
}

export interface SceneCharacterConfig {
  characterId: string;
  roleInScene: string; // Specific behavior/goal for this scene
}

export interface SceneEffect {
  type: 'scene' | 'transition';
  targetId: string; // Scene ID or Target Map ID
  action: 'unlock' | 'lock'; // New: Choose whether to enable or disable the target
}

export interface Scene {
  id: string;
  name: string;

  // New: Specific location name shown to player (e.g. "Main Street - Night")
  locationName?: string; 

  backgroundSrc: string | null; // Local object URL

  description: string; // Visible Intro text for Player AND AI context

  // New: Specific instructions ONLY for the AI (e.g. "Char X is secretly lying", "It is raining heavily")
  aiInstructions?: string; 

  goal: string; // The win condition to move to next scene
  characters: SceneCharacterConfig[];
  effects?: SceneEffect[]; // Renamed from 'unlocks' to 'effects' to handle locking too

  // Visual override for the map
  mapIconSrc?: string | null; 

  // If true, the scene remains on the map after completion and can be played again
  isRepeatable?: boolean;
}

export interface MapSpot {
  id: string;
  x: number; // Percentage 0-100
  y: number; // Percentage 0-100
  type: 'scene' | 'transition' | 'character';

  // If type === 'scene'
  sceneId?: string; // DIRECT link to a specific scene

  // If type === 'character'
  characterId?: string; // GENERIC link to a character (finds next scene)

  // If type === 'transition'
  targetMapId?: string;
}

export interface WorldMap {
  id: string;
  name: string;
  backgroundSrc: string | null;
  spots: MapSpot[];
}

export interface ChatMessage {
  sender: 'user' | 'model' | 'system';
  characterId?: string; // If model, which character?
  text: string;
  timestamp: number;
}

export interface GameState {
  currentSceneIndex: number; // Used inside VN Mode
  history: ChatMessage[];
  isProcessing: boolean;
  gameOver: boolean;
}

export interface AIResponse {
  characterResponses: {
    characterId: string;
    text: string;
  }[];
  sceneGoalReached: boolean;
  sceneTransitionReason?: string;
}

export interface RPGState {
  currentMapId: string;
  completedSceneIds: string[];
  unlockedIds: string[]; // IDs of Scenes or Maps that have been unlocked
  hiddenIds: string[]; // New: IDs of Scenes or Maps that have been locked/hidden
  ongoingScenes: Record<string, ChatMessage[]>; // Stores history for incomplete scenes { sceneId: history[] }
}

export interface GameSaveData {
  rpgState: RPGState;
  vnState: GameState | null; // Null if saved while on map
  timestamp: number;
}

import React, { useState, useEffect } from 'react';
import { Editor } from './components/Editor';
import { Player } from './components/Player';
import { RPGWorld } from './components/RPGWorld';
import { Character, Scene, GameSaveData, RPGState, WorldMap, ChatMessage } from './types';
import { getItem, setItem } from './utils/db';

