    bubbleColor: '#2563eb', // Darker Blue (Bubble)
    isItalic: false
  },
  {
    id: 'narrator',
    name: 'Chronicler',
    defaultDescription: 'The narrator of the story. Observes all but intervenes rarely.',
    imageSrc: null,
