const DEFAULT_MAPS: WorldMap[] = [
  {
    id: 'map1',
    name: 'Main City',
    backgroundSrc: null,
    spots: [
      { id: 'spot1', type: 'character', characterId: '1', x: 50, y: 50 },
    ]
  }
