import React, { useState, useEffect, useRef } from 'react';
import { Battle, Character, Zone, CombatStats, Weapon } from '../types';
import { ActiveCombatant, rollTeamInitiative, performShockTest, resolveAttack, CombatLog, d20 } from '../utils/combat';
import { Button } from './ui/Button';
import { Skull, Shield, Sword, Heart, Activity, Target, Zap } from 'lucide-react';

interface BattleArenaProps {
  battle: Battle;
  characters: Character[]; // All chars to pull data from
  onWin: () => void;
  onLose: () => void;
  onExit: () => void; // Escape/Quit
}

type BattlePhase = 'INIT' | 'COMMAND' | 'EXECUTION' | 'VICTORY' | 'DEFEAT';

export const BattleArena: React.FC<BattleArenaProps> = ({ battle, characters, onWin, onLose, onExit }) => {
  const [phase, setPhase] = useState<BattlePhase>('INIT');
  const [combatants, setCombatants] = useState<ActiveCombatant[]>([]);
  const [turnQueue, setTurnQueue] = useState<string[]>([]); // IDs of whose turn it is
  const [logs, setLogs] = useState<CombatLog[]>([]);

  // Command State
  const [selectedTargetId, setSelectedTargetId] = useState<string | null>(null);
  const [selectedZone, setSelectedZone] = useState<Zone>('torso');

  // Queued Commands for Execution Phase
  const [commands, setCommands] = useState<Record<string, { targetId: string, zone: Zone }>>({});

  const scrollRef = useRef<HTMLDivElement>(null);

  // Initialize Combat
  useEffect(() => {
    let mounted = true;

    const init = () => {
      const parts: ActiveCombatant[] = [];

      // Setup Players
      battle.playerCharacterIds.forEach(id => {
        const c = characters.find(char => char.id === id);
        if (c) {
          parts.push({
            ...c,
            currentHp: c.stats?.hp || 20,
            isShocked: false,
            tempDefenseBonus: 0,
            team: 'player',
            // Ensure stats exist if missing
            stats: c.stats || {
                pra: 3, str: 3, wid: 3, ges: 3, wil: 3,
                hp: 20, maxHp: 20, limit: 10,
                weapon: { name: 'Fists', at: 3, mod: 0, dmg: 1, cap: null }
            }
          });
        }
      });

      // Setup Enemies
      battle.enemyCharacterIds.forEach(id => {
        const c = characters.find(char => char.id === id);
        if (c) {
          parts.push({
            ...c,
            currentHp: c.stats?.hp || 15,
            isShocked: false,
            tempDefenseBonus: 0,
            team: 'enemy',
            stats: c.stats || {
                pra: 2, str: 3, wid: 2, ges: 2, wil: 2,
                hp: 15, maxHp: 15, limit: 6,
                weapon: { name: 'Claws', at: 4, mod: 1, dmg: 2, cap: 4 }
            }
          });
        }
      });

      if (!mounted) return;

      setCombatants(parts);
      addLog("Battle Started! Rolling Initiative...", 'info');

      // Roll Init
      const playerTeam = parts.filter(c => c.team === 'player');
      const enemyTeam = parts.filter(c => c.team === 'enemy');

      const pInit = rollTeamInitiative(playerTeam);
      const eInit = rollTeamInitiative(enemyTeam);

      addLog(`Players: ${pInit} | Enemies: ${eInit}`, 'info');

      // CRITICAL FIX: Pass 'parts' directly to avoid stale state in closures if enemy starts immediately
      if (pInit >= eInit) {
          addLog("Player Team takes the initiative!", 'info');
          startCommandPhase('player', parts);
      } else {
          addLog("Enemy Team takes the initiative!", 'info');
          startCommandPhase('enemy', parts);
      }
    };

    init();
    return () => { mounted = false; };
  }, [battle]);

  useEffect(() => {
      if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [logs]);

  const addLog = (text: string, type: CombatLog['type']) => {
    setLogs(prev => [...prev, { text, type }]);
  };

  const startCommandPhase = (activeTeam: 'player' | 'enemy', currentCombatants: ActiveCombatant[]) => {
      setPhase('COMMAND');
      // Filter alive members of the active team
      const teamMembers = currentCombatants.filter(c => c.team === activeTeam && c.currentHp > 0);
      setTurnQueue(teamMembers.map(c => c.id));
      setCommands({}); // Reset commands

      // If Enemy turn, AI Logic immediately triggers
      if (activeTeam === 'enemy') {
          setTimeout(() => runEnemyAI(teamMembers, currentCombatants), 1000);
      }
  };

  const runEnemyAI = (enemies: ActiveCombatant[], allCombatants: ActiveCombatant[]) => {
     // Simple AI: Hit random alive player
     const alivePlayers = allCombatants.filter(c => c.team === 'player' && c.currentHp > 0);

     // CRITICAL FIX: Ensure we have targets. If not, ExecutePhase will handle the Win Condition check.
     if (alivePlayers.length === 0) {
         executePhase(enemies, {}, allCombatants);
         return;
     }

     const aiCommands: Record<string, { targetId: string, zone: Zone }> = {};

     enemies.forEach(e => {
         const target = alivePlayers[Math.floor(Math.random() * alivePlayers.length)];
         aiCommands[e.id] = { targetId: target.id, zone: 'torso' }; // AI always hits torso for now
     });

     setCommands(aiCommands); // Update UI state
     // Pass explicit data to next phase
     setTimeout(() => executePhase(enemies, aiCommands, allCombatants), 1000);
  };

  const handlePlayerCommand = (attackerId: string) => {
      if (!selectedTargetId) return;

      const newCommands = {
          ...commands,
          [attackerId]: { targetId: selectedTargetId, zone: selectedZone }
      };

      setCommands(newCommands);

      // Remove from queue
      const nextQueue = turnQueue.filter(id => id !== attackerId);
      setTurnQueue(nextQueue);

      // Reset selection
      setSelectedTargetId(null);
      setSelectedZone('torso');

      if (nextQueue.length === 0) {
          // All commands issued, execute!
          executePhase(combatants.filter(c => c.team === 'player'), newCommands, combatants);
      }
  };

  // CRITICAL FIX: Added currentCombatants argument to prevent stale state usage
  const executePhase = async (
      actingTeam: ActiveCombatant[], 
      activeCommands: Record<string, { targetId: string, zone: Zone }>,
      currentCombatants: ActiveCombatant[]
  ) => {
      setPhase('EXECUTION');

      let workingState = [...currentCombatants]; 

      for (const actor of actingTeam) {
          // 1. Check Death (based on working state)
          const freshActor = workingState.find(c => c.id === actor.id);
          if (!freshActor || freshActor.currentHp <= 0) continue;

          // 2. Shock Test
          const shockResult = performShockTest(freshActor);
          if (shockResult.log) addLog(shockResult.log, 'info');

          if (freshActor.currentHp < (freshActor.stats!.maxHp * 0.25)) {
               // Update shocked state
               workingState = workingState.map(c => c.id === actor.id ? { ...c, isShocked: shockResult.shocked } : c);
          }

          if (shockResult.shocked) continue; // Skip turn

          // 3. Attack
          const cmd = activeCommands[actor.id];
          if (!cmd) continue;

          const target = workingState.find(c => c.id === cmd.targetId);
          if (!target || target.currentHp <= 0) {
              addLog(`${actor.name} has no valid target.`, 'info');
              continue;
          }

          const result = resolveAttack(freshActor, target, cmd.zone);

          // Add Logs
          result.logs.forEach(l => addLog(l.text, l.type));

          // Apply Damage
          if (result.damage > 0) {
              workingState = workingState.map(c => c.id === target.id ? { ...c, currentHp: Math.max(0, c.currentHp - result.damage) } : c);
          }

          // Visual Update (Intermediate)
          setCombatants(workingState); 
          await new Promise(r => setTimeout(r, 1500));
      }

      // End of Phase Checks
      // We pass the team that JUST ACTED to toggle correctly
      const justActedTeam = actingTeam.length > 0 ? actingTeam[0].team : 'player'; 
      checkWinCondition(workingState, justActedTeam);
  };

  const checkWinCondition = (currentCombs: ActiveCombatant[], lastActiveTeam: 'player' | 'enemy') => {
      const playersAlive = currentCombs.some(c => c.team === 'player' && c.currentHp > 0);
      const enemiesAlive = currentCombs.some(c => c.team === 'enemy' && c.currentHp > 0);

      if (!playersAlive) {
          setPhase('DEFEAT');
          return;
      }
      if (!enemiesAlive) {
          setPhase('VICTORY');
          return;
      }

      // CRITICAL FIX: Explicitly toggle based on who just finished
      if (lastActiveTeam === 'player') {
          startCommandPhase('enemy', currentCombs);
      } else {
          startCommandPhase('player', currentCombs);
      }
  };

  // --- Rendering Helpers ---

  const renderCombatant = (c: ActiveCombatant) => {
      const isDead = c.currentHp <= 0;
      const isTurn = turnQueue.includes(c.id);
      const isSelected = selectedTargetId === c.id;

      const maxHp = c.stats?.maxHp || 1;
      const hpPct = (c.currentHp / maxHp) * 100;

      return (
          <div 
             key={c.id} 
             onClick={() => {
                 if (phase === 'COMMAND' && turnQueue.length > 0) {
                     // Check if current actor is player
                     const actorId = turnQueue[0];
                     const actor = combatants.find(a => a.id === actorId);
                     if (actor?.team === 'player' && c.team === 'enemy' && !isDead) {
                         setSelectedTargetId(c.id);
                     }
                 }
             }}
             className={`relative w-32 md:w-40 flex flex-col items-center transition-all duration-300
                ${isDead ? 'opacity-50 grayscale blur-[2px]' : ''}
                ${isTurn ? 'scale-110 drop-shadow-[0_0_15px_rgba(255,255,255,0.5)]' : ''}
                ${isSelected ? 'ring-2 ring-red-500 rounded-xl bg-red-900/20 scale-105' : ''}
                ${!isDead && c.team === 'enemy' && phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(x => x.id === turnQueue[0])?.team === 'player' ? 'cursor-pointer hover:bg-white/5 rounded-xl' : ''}
             `}
          >
              {/* HP Bar */}
              <div className="w-full h-2 bg-gray-700 rounded-full mb-2 overflow-hidden border border-gray-600">
                  <div className={`h-full transition-all duration-500 ${hpPct < 25 ? 'bg-red-600' : 'bg-green-500'}`} style={{ width: `${hpPct}%` }} />
              </div>

              {/* Sprite */}
              <div className="w-24 h-24 md:w-32 md:h-32 relative">
                  {c.imageSrc || c.mapSpriteSrc ? (
                      <img src={c.imageSrc || c.mapSpriteSrc!} className="w-full h-full object-contain" />
                  ) : (
                      <div className="w-full h-full bg-gray-700 rounded-full flex items-center justify-center text-xs text-center p-2 border-2 border-gray-500">
                          {c.name}
                      </div>
                  )}
                  {c.isShocked && <div className="absolute top-0 right-0 text-yellow-400 bg-black/80 rounded-full p-1"><Zap size={16}/></div>}
              </div>

              {/* Info */}
              <div className="bg-black/70 px-2 py-1 rounded text-xs mt-1 text-center min-w-[80px]">
                  <div className="font-bold text-gray-200">{c.name}</div>
                  <div className="text-gray-400">{c.currentHp}/{maxHp} HP</div>
              </div>
          </div>
      );
  };

  return (
    <div className="fixed inset-0 z-[100] bg-black text-white flex flex-col">
       {/* Background */}
       <div className="absolute inset-0 z-0 opacity-50">
           {battle.backgroundSrc ? (
               <img src={battle.backgroundSrc} className="w-full h-full object-cover" />
           ) : (
               <div className="w-full h-full bg-red-950/40 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-gray-800 to-black" />
           )}
       </div>

       {/* Header */}
       <div className="relative z-10 p-4 flex justify-between items-center bg-gradient-to-b from-black/80 to-transparent">
           <h2 className="text-2xl font-bold flex items-center gap-2 text-red-500"><Sword size={24}/> {battle.name}</h2>
           <Button onClick={onExit} variant="secondary" className="text-xs py-1">Flee</Button>
       </div>

       {/* Battle Area */}
       <div className="relative z-10 flex-1 flex flex-col md:flex-row items-center justify-between px-4 md:px-20 py-4 gap-8 overflow-y-auto">
           {/* Players */}
           <div className="flex flex-col gap-8">
              {combatants.filter(c => c.team === 'player').map(renderCombatant)}
           </div>

           {/* Center UI (Phase Info) */}
           <div className="flex flex-col items-center justify-center">
              {phase === 'VICTORY' && (
                  <div className="text-center animate-bounce">
                      <h1 className="text-5xl font-bold text-yellow-400 mb-4">VICTORY</h1>
                      <Button onClick={onWin} className="bg-yellow-600 hover:bg-yellow-500 text-xl px-8 py-4">Continue</Button>
                  </div>
              )}
              {phase === 'DEFEAT' && (
                  <div className="text-center">
                      <h1 className="text-5xl font-bold text-red-600 mb-4">DEFEAT</h1>
                      <Button onClick={onLose} variant="danger" className="text-xl px-8 py-4">Retry</Button>
                  </div>
              )}
              {phase === 'INIT' && <div className="text-xl font-bold animate-pulse text-blue-300">Rolling Initiative...</div>}
              {phase === 'EXECUTION' && <div className="text-xl font-bold text-orange-400 flex items-center gap-2"><Activity className="animate-spin"/> Resolving Actions...</div>}
           </div>

           {/* Enemies */}
           <div className="flex flex-col gap-8">
              {combatants.filter(c => c.team === 'enemy').map(renderCombatant)}
           </div>
       </div>

       {/* Bottom Control / Log Panel */}
       <div className="relative z-20 h-1/3 min-h-[250px] bg-black/90 border-t border-gray-700 flex flex-col md:flex-row">

           {/* Controls (Only visible during Player Command) */}
           <div className="flex-1 p-6 border-b md:border-b-0 md:border-r border-gray-700 flex flex-col items-center justify-center gap-4">
              {phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(c => c.id === turnQueue[0])?.team === 'player' ? (
                  <>
                     <div className="text-lg font-bold text-indigo-300 mb-2">
                         Command: {combatants.find(c => c.id === turnQueue[0])?.name}
                     </div>

                     {!selectedTargetId ? (
                         <div className="text-gray-400 animate-pulse flex items-center gap-2"><Target size={16}/> Select an enemy to attack</div>
                     ) : (
                         <div className="flex flex-col gap-3 w-full max-w-sm animate-in fade-in slide-in-from-bottom-4">
                            <div className="text-sm text-center text-gray-400">Select Hit Zone</div>
                            <div className="grid grid-cols-2 gap-2">
                                <Button variant={selectedZone === 'torso' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('torso')} className="text-xs">Torso (0)</Button>
                                <Button variant={selectedZone === 'head' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('head')} className="text-xs">Head (-6 / Stun)</Button>
                                <Button variant={selectedZone === 'arm' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('arm')} className="text-xs">Arm (-4 / Disarm)</Button>
                                <Button variant={selectedZone === 'leg' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('leg')} className="text-xs">Leg (-3 / Slow)</Button>
                            </div>
                            <Button onClick={() => handlePlayerCommand(turnQueue[0])} className="w-full mt-2 bg-red-600 hover:bg-red-500 shadow-red-900/20">
                                <Sword size={16}/> ATTACK
                            </Button>
                         </div>
                     )}
                  </>
              ) : (
                  <div className="text-gray-500 italic text-sm p-4 text-center">
                      {phase === 'COMMAND' ? "Enemy is thinking..." : (phase === 'EXECUTION' ? "Watching combat..." : "")}
                  </div>
              )}
           </div>

           {/* Logs */}
           <div ref={scrollRef} className="flex-[2] p-4 overflow-y-auto font-mono text-xs md:text-sm space-y-1 bg-gray-950/50">
               {logs.length === 0 && <div className="text-gray-600">Combat Log initialized...</div>}
               {logs.map((log, i) => (
                   <div key={i} className={`
                      ${log.type === 'attack' ? 'text-blue-300' : ''}
                      ${log.type === 'damage' ? 'text-red-400 font-bold' : ''}
                      ${log.type === 'crit' ? 'text-yellow-400 font-bold text-lg' : ''}
                      ${log.type === 'info' ? 'text-gray-400' : ''}
                   `}>
                       <span className="opacity-50 mr-2">[{i+1}]</span>{log.text}
                   </div>
               ))}
           </div>
       </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Plus, Trash2, Image as ImageIcon, User, Target, Save, PlayCircle, RotateCcw, Map as MapIcon, MousePointerClick, FileUp, Download, Upload, Check, Waypoints, Globe, Lock, Unlock, MessageSquare, Ban, RefreshCcw, Eye, EyeOff, Italic, Palette, Ear, Wind, Layout, Sword, Shield, Skull } from 'lucide-react';
import { Character, Scene, SceneCharacterConfig, WorldMap, MapSpot, SceneEffect, Battle, CombatStats, Weapon } from '../types';
import { Button } from './ui/Button';

interface EditorProps {
  characters: Character[];
  scenes: Scene[];
  maps: WorldMap[];
  battles?: Battle[]; // New
  onUpdateCharacters: (chars: Character[]) => void;
  onUpdateScenes: (scenes: Scene[]) => void;
  onUpdateMaps: (maps: WorldMap[]) => void;
  onUpdateBattles?: (battles: Battle[]) => void; // New
  onPlay: () => void;
  onQuickSave: () => Promise<boolean>;
  onExportProject: () => void;
  onImportProject: (file: File) => void;
  hasSaveGame: boolean;
  onContinueGame: () => void;
}

// Default Stats for new chars
const DEFAULT_STATS: CombatStats = {
  pra: 3, str: 3, wid: 3, ges: 3, wil: 3,
  hp: 20, maxHp: 20, limit: 10,
  weapon: { name: 'Basic Weapon', at: 3, mod: 0, dmg: 1, cap: null }
};

export const Editor: React.FC<EditorProps> = ({
  characters,
  scenes,
  maps,
  battles = [],
  onUpdateCharacters,
  onUpdateScenes,
  onUpdateMaps,
  onUpdateBattles = (_: Battle[]) => {},
  onPlay,
  onQuickSave,
  onExportProject,
  onImportProject,
  hasSaveGame,
  onContinueGame
}) => {
  const [activeTab, setActiveTab] = useState<'chars' | 'scenes' | 'battles' | 'map'>('chars');

  // Map Editor State
  const [activeMapId, setActiveMapId] = useState<string>(maps[0]?.id || '');
  const [selectedTool, setSelectedTool] = useState<{type: 'scene'|'transition'|'character'|'battle', id: string} | null>(null);

  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const importInputRef = useRef<HTMLInputElement>(null);

  // --- Character Handlers ---
  const addCharacter = () => {
    const newChar: Character = {
      id: crypto.randomUUID(),
      name: 'New Character',
      defaultDescription: 'A friendly helper.',
      imageSrc: null,
      mapSpriteSrc: null,
      rpgColor: '#ef4444',
      bubbleColor: '#4b5563', 
      isItalic: false,
      stats: { ...DEFAULT_STATS }
    };
    onUpdateCharacters([...characters, newChar]);
  };

  const updateCharacter = (id: string, updates: Partial<Character>) => {
    onUpdateCharacters(characters.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const updateCharStats = (id: string, statUpdates: Partial<CombatStats>) => {
      onUpdateCharacters(characters.map(c => {
          if (c.id !== id) return c;
          return {
              ...c,
              stats: { ...(c.stats || DEFAULT_STATS), ...statUpdates }
          };
      }));
  };

  const updateCharWeapon = (id: string, weaponUpdates: Partial<Weapon>) => {
      onUpdateCharacters(characters.map(c => {
          if (c.id !== id) return c;
          const currentStats = c.stats || DEFAULT_STATS;
          return {
              ...c,
              stats: { 
                  ...currentStats, 
                  weapon: { ...currentStats.weapon, ...weaponUpdates }
              }
          };
      }));
  };

  const handleCharImageUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>, field: 'imageSrc' | 'mapSpriteSrc') => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCharacter(id, { [field]: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  // --- Battle Handlers ---
  const addBattle = () => {
      const newBattle: Battle = {
          id: crypto.randomUUID(),
          name: `Battle ${battles.length + 1}`,
          backgroundSrc: null,
          playerCharacterIds: [],
          enemyCharacterIds: [],
          isRepeatable: false,
          onWinEffect: []
      };
      onUpdateBattles([...battles, newBattle]);
  };

  const updateBattle = (id: string, updates: Partial<Battle>) => {
      onUpdateBattles(battles.map(b => b.id === id ? { ...b, ...updates } : b));
  };

  const handleBattleBgUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateBattle(id, { backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleCharInBattle = (battleId: string, charId: string, side: 'player' | 'enemy') => {
      const battle = battles.find(b => b.id === battleId);
      if (!battle) return;

      const listKey = side === 'player' ? 'playerCharacterIds' : 'enemyCharacterIds';
      const list = battle[listKey];

      if (list.includes(charId)) {
          updateBattle(battleId, { [listKey]: list.filter(id => id !== charId) });
      } else {
          updateBattle(battleId, { [listKey]: [...list, charId] });
      }
  };

  // --- Scene Handlers ---
  const addScene = () => {
    const newScene: Scene = {
      id: crypto.randomUUID(),
      name: `Scene ${scenes.length + 1}`,
      locationName: 'Unknown Location',
      backgroundSrc: null,
      description: 'You are in a quiet room.',
      aiInstructions: '',
      sensoryDetails: '',
      environmentDetails: '',
      goal: 'Say hello.',
      characters: [],
      effects: [],
      mapIconSrc: null,
      isRepeatable: false
    };
    onUpdateScenes([...scenes, newScene]);
  };

  const updateScene = (id: string, updates: Partial<Scene>) => {
    onUpdateScenes(scenes.map(s => s.id === id ? { ...s, ...updates } : s));
  };

  const handleSceneIconUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { mapIconSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleEffect = (sceneId: string, type: 'scene' | 'transition' | 'battle', targetId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const currentEffects = scene.effects || [];
    const existingEffect = currentEffects.find(u => u.type === type && u.targetId === targetId);

    let newEffects: SceneEffect[];

    if (!existingEffect) {
        newEffects = [...currentEffects, { type, targetId, action: 'unlock' }];
    } else if (existingEffect.action === 'unlock' || !existingEffect.action) {
        newEffects = currentEffects.map(eff => 
            (eff.type === type && eff.targetId === targetId) ? { ...eff, action: 'lock' } : eff
        );
    } else {
        newEffects = currentEffects.filter(u => !(u.type === type && u.targetId === targetId));
    }

    updateScene(sceneId, { effects: newEffects });
  };

  const handleBgUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleCharInScene = (sceneId: string, charId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const exists = scene.characters.find(c => c.characterId === charId);
    let newChars: SceneCharacterConfig[];

    if (exists) {
      newChars = scene.characters.filter(c => c.characterId !== charId);
    } else {
      newChars = [...scene.characters, { characterId: charId, roleInScene: 'Default behavior' }];
    }
    updateScene(sceneId, { characters: newChars });
  };

  const updateSceneCharRole = (sceneId: string, charId: string, role: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;
    const newChars = scene.characters.map(c => c.characterId === charId ? { ...c, roleInScene: role } : c);
    updateScene(sceneId, { characters: newChars });
  };

  // --- Map Handlers ---

  const getCurrentMap = () => maps.find(m => m.id === activeMapId);

  const addMap = () => {
      const newMap: WorldMap = {
          id: crypto.randomUUID(),
          name: `Map ${maps.length + 1}`,
          backgroundSrc: null,
          spots: []
      };
      const newMaps = [...maps, newMap];
      onUpdateMaps(newMaps);
      setActiveMapId(newMap.id);
  };

  const deleteMap = (id: string) => {
      if (maps.length <= 1) {
          alert("You must have at least one map.");
          return;
      }
      const newMaps = maps.filter(m => m.id !== id);
      onUpdateMaps(newMaps);
      if (activeMapId === id) setActiveMapId(newMaps[0].id);
  };

  const updateCurrentMap = (updates: Partial<WorldMap>) => {
      onUpdateMaps(maps.map(m => m.id === activeMapId ? { ...m, ...updates } : m));
  };

  const handleMapBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCurrentMap({ backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const handleMapClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!selectedTool || !mapContainerRef.current) return;
    if ((e.target as HTMLElement).closest('.map-pin')) return;

    const rect = mapContainerRef.current.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;

    const currentMap = getCurrentMap();
    if (!currentMap) return;

    const newSpot: MapSpot = {
      id: crypto.randomUUID(),
      type: selectedTool.type,
      x, 
      y,
      sceneId: selectedTool.type === 'scene' ? selectedTool.id : undefined,
      targetMapId: selectedTool.type === 'transition' ? selectedTool.id : undefined,
      characterId: selectedTool.type === 'character' ? selectedTool.id : undefined,
      battleId: selectedTool.type === 'battle' ? selectedTool.id : undefined
    };

    updateCurrentMap({ spots: [...currentMap.spots, newSpot] });
  };

  const removeSpot = (spotId: string) => {
    const currentMap = getCurrentMap();
    if(!currentMap) return;
    updateCurrentMap({
      spots: currentMap.spots.filter(s => s.id !== spotId)
    });
  };

  // --- Toolbar Handlers ---

  const handleQuickSaveClick = async () => {
    setSaveStatus('saving');
    await onQuickSave();
    setSaveStatus('saved');
    setTimeout(() => setSaveStatus('idle'), 2000);
  };

  const handleImportClick = () => {
    importInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if(e.target.files && e.target.files[0]) {
        onImportProject(e.target.files[0]);
    }
    if(e.target.value) e.target.value = ''; 
  };

  const currentMap = getCurrentMap();

  return (
    <div className="flex flex-col h-full max-w-6xl mx-auto p-4 md:p-8">
      {/* Header / Toolbar */}
      <div className="flex flex-col xl:flex-row justify-between items-center mb-8 gap-6">
        <div>
           <h1 className="text-3xl font-bold text-indigo-400">VN Creator Studio</h1>
           <p className="text-gray-400 text-sm mt-1">Design your world, characters, and stories.</p>
        </div>

        <div className="flex flex-wrap gap-3 items-center justify-center">
          {/* File Operations */}
          <div className="flex gap-2 mr-2 bg-gray-800 p-1 rounded-lg border border-gray-700">
             <input type="file" ref={importInputRef} className="hidden" accept=".json" onChange={handleFileChange} />
             <button onClick={handleImportClick} className="flex items-center gap-2 px-3 py-2 text-sm text-gray-300 hover:text-white hover:bg-gray-700 rounded transition" title="Load .json file">
               <Upload size={16} /> Load Project
             </button>
             <div className="w-[1px] bg-gray-600 my-1"></div>
             <button onClick={onExportProject} className="flex items-center gap-2 px-3 py-2 text-sm text-gray-300 hover:text-white hover:bg-gray-700 rounded transition" title="Download .json file">
               <Download size={16} /> Export Project
             </button>
          </div>

          <Button onClick={handleQuickSaveClick} variant="secondary" title="Saves to Browser Storage" className="min-w-[140px]" disabled={saveStatus === 'saving'}>
            {saveStatus === 'saved' ? <><Check size={18} className="text-green-400"/> Saved!</> : (saveStatus === 'saving' ? 'Saving...' : <><Save size={18} /> Quick Save</>)}
          </Button>

          <div className="h-8 w-[1px] bg-gray-700 mx-2 hidden md:block"></div>

          {hasSaveGame && (
            <Button onClick={onContinueGame} className="bg-yellow-600 hover:bg-yellow-500">
              <RotateCcw size={18} /> Continue
            </Button>
          )}

          <Button onClick={onPlay} className="bg-green-600 hover:bg-green-500 px-6 font-bold shadow-green-900/20">
            <PlayCircle size={18} /> PLAY GAME
          </Button>
        </div>
      </div>

      <div className="flex gap-4 mb-6 border-b border-gray-700 pb-1 overflow-x-auto">
        <button onClick={() => setActiveTab('chars')} className={`px-4 py-2 font-medium transition-colors whitespace-nowrap ${activeTab === 'chars' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}>Characters</button>
        <button onClick={() => setActiveTab('scenes')} className={`px-4 py-2 font-medium transition-colors whitespace-nowrap ${activeTab === 'scenes' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}>Scenarios</button>
        <button onClick={() => setActiveTab('battles')} className={`px-4 py-2 font-medium transition-colors whitespace-nowrap ${activeTab === 'battles' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}>Battles</button>
        <button onClick={() => setActiveTab('map')} className={`px-4 py-2 font-medium transition-colors whitespace-nowrap ${activeTab === 'map' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}>World Map</button>
      </div>

      <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
        {activeTab === 'chars' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {characters.map(char => (
                <div key={char.id} className="bg-gray-800 p-4 rounded-xl border border-gray-700 flex flex-col gap-4 shadow-lg hover:border-gray-600 transition-colors">
                  <div className="flex gap-4">
                      <div className="w-24 h-32 bg-gray-900 rounded-lg flex-shrink-0 border border-gray-600 overflow-hidden relative group">
                        {char.imageSrc ? (
                          <img src={char.imageSrc} alt={char.name} className="w-full h-full object-cover" />
                        ) : (
                          <div className="w-full h-full flex flex-col items-center justify-center text-gray-600 gap-1"><User size={24} /><span className="text-[10px] text-center px-1">Portrait</span></div>
                        )}
                        <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity text-xs font-bold">
                          UPLOAD
                          <input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e, 'imageSrc')} />
                        </label>
                      </div>
                      <div className="flex-1 space-y-3">
                        <input className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-1 focus:border-indigo-500 outline-none transition-all" value={char.name} onChange={(e) => updateCharacter(char.id, { name: e.target.value })} placeholder="Character Name" />

                        <div className="grid grid-cols-2 gap-3">
                          {/* Map Sprite & Color */}
                          <div className="flex items-center gap-2">
                              <div className="w-10 h-10 bg-gray-900 rounded border border-gray-600 overflow-hidden relative group shrink-0">
                                {char.mapSpriteSrc ? <img src={char.mapSpriteSrc} alt="Sprite" className="w-full h-full object-contain" /> : <div className="w-full h-full flex items-center justify-center text-gray-600" title="Map Sprite"><MapIcon size={16} /></div>}
                                <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity">
                                    <FileUp size={16} className="text-white"/>
