  );
};

import { Character, Zone } from "../types";

export interface CombatLog {
  text: string;
  type: 'info' | 'attack' | 'damage' | 'crit' | 'error';
}

export interface ActiveCombatant extends Character {
  currentHp: number;
  isShocked: boolean;
  tempDefenseBonus: number; // From Momentum-Check failure of opponent
  team: 'player' | 'enemy';
}

export interface AttackResult {
  damage: number;
  logs: CombatLog[];
  defenderBonusNextTurn: number;
  // Visual Data
  rolls: number[]; // All dice rolls including mods
  hits: boolean[]; // True if the corresponding index hit TN
  isCrit: boolean;
  isHeadshot: boolean;
}

// D20 Helper
export const d20 = () => Math.floor(Math.random() * 20) + 1;

// 1. Initiative
export const rollTeamInitiative = (combatants: ActiveCombatant[]): number => {
  const maxDex = Math.max(...combatants.map(c => c.stats?.ges || 0));
  return maxDex + d20();
};

// Phase 1: Shock Test
export const performShockTest = (c: ActiveCombatant): { shocked: boolean, log: string } => {
  const maxHp = c.stats?.maxHp || 10;
  const hpThreshold = maxHp * 0.25;

  if (c.currentHp < hpThreshold) {
    const roll = d20();
    const wil = c.stats?.wil || 0;
    const total = roll + wil;

    if (total >= 15) {
      return { shocked: false, log: `${c.name} fights through the pain (Roll ${total} vs 15). -2 Penalty applies.` };
    } else {
      return { shocked: true, log: `${c.name} goes into SHOCK (Roll ${total} vs 15)! Cannot act.` };
    }
  }
  return { shocked: false, log: '' };
};

// Phase 2: Execution Algorithm
export const resolveAttack = (
  attacker: ActiveCombatant, 
  defender: ActiveCombatant, 
  zone: Zone
): AttackResult => {

  const logs: CombatLog[] = [];
  const stats = attacker.stats!;
  const defStats = defender.stats!;
  const weapon = stats.weapon;

  // Zone Mods
  let zoneMalus = 0;
  let isHeadshot = false;

  switch(zone) {
    case 'head': zoneMalus = 6; isHeadshot = true; break;
    case 'arm': zoneMalus = 4; break;
    case 'leg': zoneMalus = 3; break;
    default: zoneMalus = 0; // Torso
  }

  // --- Step 1: Target Number (TN) ---
  const defRoll = d20();
  const tn = defRoll + (defender.isShocked ? 0 : defStats.ges); 
  logs.push({ text: `${defender.name} tries to evade: TN ${tn} (Roll ${defRoll} + ${defender.isShocked ? 0 : defStats.ges} GES)`, type: 'info' });

  // --- Step 2: The Salve (Hit Roll) ---
  const diceCount = weapon.at;
  const hits: number[] = [];
  let bestRoll = 0;
  let nat20 = false;

  const shockPenalty = attacker.currentHp < (stats.maxHp * 0.25) && !attacker.isShocked ? 2 : 0; 

  const rollDetails: number[] = [];
  const hitDetails: boolean[] = [];

  for(let i=0; i < diceCount; i++) {
    const roll = d20();
    if (roll === 20) nat20 = true;

    const total = roll + stats.pra + weapon.mod - zoneMalus - shockPenalty;
    rollDetails.push(total);

    if (total > tn) {
      hits.push(total);
      hitDetails.push(true);
    } else {
      hitDetails.push(false);
    }
    if (total > bestRoll) bestRoll = total;
  }

  logs.push({ text: `${attacker.name} attacks ${zone.toUpperCase()} with ${weapon.name}: [${rollDetails.join(', ')}] vs TN ${tn}`, type: 'attack' });

  // Momentum Check (Counter Advantage)
  let defenderBonusNextTurn = 0;
  if (hits.length === 0 && bestRoll < (tn - 10)) {
    defenderBonusNextTurn = 4;
    logs.push({ text: `Attack missed badly! ${defender.name} gains Counter Advantage (+4 next def).`, type: 'info' });
  }

  if (hits.length === 0) {
    return { 
        damage: 0, logs, defenderBonusNextTurn,
        rolls: rollDetails, hits: hitDetails, isCrit: false, isHeadshot: false
    };
  }

  // --- Step 3: Wound Roll (Durchschlag) ---
  const threshold = 10 - (stats.str - defStats.wid);
  let confirmedWounds = 0;
  const woundRolls: number[] = [];

  for(let i=0; i < hits.length; i++) {
    const r = d20();
    woundRolls.push(r);
    if (r > threshold) {
      confirmedWounds++;
    }
  }

  logs.push({ text: `Wound Check (Threshold ${threshold}): [${woundRolls.join(', ')}] -> ${confirmedWounds} Wounds.`, type: 'info' });

  if (confirmedWounds === 0) {
    logs.push({ text: `Hit but no penetration! Armor/Body absorbed the blow.`, type: 'info' });
    return { 
        damage: 0, logs, defenderBonusNextTurn,
        rolls: rollDetails, hits: hitDetails, isCrit: false, isHeadshot: false
    };
  }

  // --- Step 4: Damage Calculation ---
  let rawDamage = 0;

  for (let i = 0; i < confirmedWounds; i++) {
    let woundDmg = weapon.dmg; 

    // Crit Effect: Headshot +50%
    if (nat20 && isHeadshot) {
      woundDmg = Math.ceil(woundDmg * 1.5);
    }

    // Weapon Cap Check
    if (weapon.cap !== null && woundDmg > weapon.cap) {
      woundDmg = weapon.cap;
    }

    rawDamage += woundDmg;
  }

  // Defender Limit Check
  const finalDamage = Math.min(rawDamage, defStats.limit);

  if (finalDamage < rawDamage) {
     logs.push({ text: `Damage limited by body mass! Reduced from ${rawDamage} to ${finalDamage}.`, type: 'info' });
  }

  logs.push({ text: `${attacker.name} deals ${finalDamage} DAMAGE to ${defender.name}!`, type: 'damage' });

  // --- Step 5: Critical Effects ---
  if (nat20) {
    if (zone === 'head') logs.push({ text: `CRITICAL HEADSHOT! ${defender.name} is stunned!`, type: 'crit' }); 
    if (zone === 'arm') logs.push({ text: `CRITICAL HIT TO ARM! Disarmed!`, type: 'crit' });
    if (zone === 'leg') logs.push({ text: `CRITICAL HIT TO LEG! Crippled!`, type: 'crit' });
  }

  return { 
      damage: finalDamage, logs, defenderBonusNextTurn,
      rolls: rollDetails, hits: hitDetails, isCrit: nat20, isHeadshot: isHeadshot
  };
};

import React, { useState, useEffect, useRef } from 'react';
import { Battle, Character, Zone, CombatStats, Weapon } from '../types';
import { ActiveCombatant, rollTeamInitiative, performShockTest, resolveAttack, CombatLog, d20 } from '../utils/combat';
import { Button } from './ui/Button';
import { Skull, Shield, Sword, Heart, Activity, Target, Zap, Dice5 } from 'lucide-react';

interface BattleArenaProps {
  battle: Battle;
  characters: Character[]; // All chars to pull data from
  onWin: () => void;
  onLose: () => void;
  onExit: () => void; // Escape/Quit
}

type BattlePhase = 'INIT' | 'COMMAND' | 'EXECUTION' | 'VICTORY' | 'DEFEAT';

// Visual Types
interface FloatingText {
    id: string;
    text: string;
    type: 'damage' | 'heal' | 'miss' | 'crit';
    combatantId: string;
}

interface DiceVisual {
    value: number;
    isHit: boolean;
}

export const BattleArena: React.FC<BattleArenaProps> = ({ battle, characters, onWin, onLose, onExit }) => {
  const [phase, setPhase] = useState<BattlePhase>('INIT');
  const [combatants, setCombatants] = useState<ActiveCombatant[]>([]);
  const [turnQueue, setTurnQueue] = useState<string[]>([]); 
  const [logs, setLogs] = useState<CombatLog[]>([]);

  // Command State
  const [selectedTargetId, setSelectedTargetId] = useState<string | null>(null);
  const [selectedZone, setSelectedZone] = useState<Zone>('torso');

  // Queued Commands
  const [commands, setCommands] = useState<Record<string, { targetId: string, zone: Zone }>>({});

  // --- Visual States ---
  const [floatingTexts, setFloatingTexts] = useState<FloatingText[]>([]);
  const [animatingAttackerId, setAnimatingAttackerId] = useState<string | null>(null); // For "Lunge"
  const [animatingTargetId, setAnimatingTargetId] = useState<string | null>(null); // For "Shake"
  const [activeDice, setActiveDice] = useState<DiceVisual[]>([]);
  const [showDice, setShowDice] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);

  // Helper for adding floating text
  const addFloatingText = (combatantId: string, text: string, type: FloatingText['type']) => {
      const id = crypto.randomUUID();
      setFloatingTexts(prev => [...prev, { id, text, type, combatantId }]);
      setTimeout(() => {
          setFloatingTexts(prev => prev.filter(ft => ft.id !== id));
      }, 1500); // Remove after animation
  };

  // Initialize Combat
  useEffect(() => {
    let mounted = true;

    const init = () => {
      const parts: ActiveCombatant[] = [];
      // Setup Players
      battle.playerCharacterIds.forEach(id => {
        const c = characters.find(char => char.id === id);
        if (c) {
          parts.push({
            ...c,
            currentHp: c.stats?.hp || 20,
            isShocked: false,
            tempDefenseBonus: 0,
            team: 'player',
            stats: c.stats || {
                pra: 3, str: 3, wid: 3, ges: 3, wil: 3,
                hp: 20, maxHp: 20, limit: 10,
                weapon: { name: 'Fists', at: 3, mod: 0, dmg: 1, cap: null }
            }
          });
        }
      });

      // Setup Enemies
      battle.enemyCharacterIds.forEach(id => {
        const c = characters.find(char => char.id === id);
        if (c) {
          parts.push({
            ...c,
            currentHp: c.stats?.hp || 15,
            isShocked: false,
            tempDefenseBonus: 0,
            team: 'enemy',
            stats: c.stats || {
                pra: 2, str: 3, wid: 2, ges: 2, wil: 2,
                hp: 15, maxHp: 15, limit: 6,
                weapon: { name: 'Claws', at: 4, mod: 1, dmg: 2, cap: 4 }
            }
          });
        }
      });

      if (!mounted) return;

      setCombatants(parts);
      addLog("Battle Started! Rolling Initiative...", 'info');

      const playerTeam = parts.filter(c => c.team === 'player');
      const enemyTeam = parts.filter(c => c.team === 'enemy');

      const pInit = rollTeamInitiative(playerTeam);
      const eInit = rollTeamInitiative(enemyTeam);

      addLog(`Players: ${pInit} | Enemies: ${eInit}`, 'info');

      if (pInit >= eInit) {
          addLog("Player Team takes the initiative!", 'info');
          startCommandPhase('player', parts);
      } else {
          addLog("Enemy Team takes the initiative!", 'info');
          startCommandPhase('enemy', parts);
      }
    };

    init();
    return () => { mounted = false; };
  }, [battle]);

  useEffect(() => {
      if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [logs]);

  const addLog = (text: string, type: CombatLog['type']) => {
    setLogs(prev => [...prev, { text, type }]);
  };

  const startCommandPhase = (activeTeam: 'player' | 'enemy', currentCombatants: ActiveCombatant[]) => {
      setPhase('COMMAND');
      const teamMembers = currentCombatants.filter(c => c.team === activeTeam && c.currentHp > 0);
      setTurnQueue(teamMembers.map(c => c.id));
      setCommands({}); 

      if (activeTeam === 'enemy') {
          setTimeout(() => runEnemyAI(teamMembers, currentCombatants), 1000);
      }
  };

  const runEnemyAI = (enemies: ActiveCombatant[], allCombatants: ActiveCombatant[]) => {
     const alivePlayers = allCombatants.filter(c => c.team === 'player' && c.currentHp > 0);

     if (alivePlayers.length === 0) {
         executePhase(enemies, {}, allCombatants);
         return;
     }

     const aiCommands: Record<string, { targetId: string, zone: Zone }> = {};
     enemies.forEach(e => {
         const target = alivePlayers[Math.floor(Math.random() * alivePlayers.length)];
         aiCommands[e.id] = { targetId: target.id, zone: 'torso' }; 
     });

     setCommands(aiCommands); 
     setTimeout(() => executePhase(enemies, aiCommands, allCombatants), 1000);
  };

  const handlePlayerCommand = (attackerId: string) => {
      if (!selectedTargetId) return;

      const newCommands = {
          ...commands,
          [attackerId]: { targetId: selectedTargetId, zone: selectedZone }
      };

      setCommands(newCommands);

      const nextQueue = turnQueue.filter(id => id !== attackerId);
      setTurnQueue(nextQueue);
      setSelectedTargetId(null);
      setSelectedZone('torso');

      if (nextQueue.length === 0) {
          executePhase(combatants.filter(c => c.team === 'player'), newCommands, combatants);
      }
  };

  const executePhase = async (
      actingTeam: ActiveCombatant[], 
      activeCommands: Record<string, { targetId: string, zone: Zone }>,
      currentCombatants: ActiveCombatant[]
  ) => {
      setPhase('EXECUTION');

      let workingState = [...currentCombatants]; 

      for (const actor of actingTeam) {
          // 1. Check Death
          const freshActor = workingState.find(c => c.id === actor.id);
          if (!freshActor || freshActor.currentHp <= 0) continue;

          // 2. Shock Test
          const shockResult = performShockTest(freshActor);
          if (shockResult.log) addLog(shockResult.log, 'info');

          if (freshActor.currentHp < (freshActor.stats!.maxHp * 0.25)) {
               workingState = workingState.map(c => c.id === actor.id ? { ...c, isShocked: shockResult.shocked } : c);
          }

          if (shockResult.shocked) {
             addFloatingText(actor.id, "SHOCKED", "miss");
             await new Promise(r => setTimeout(r, 800));
             continue; 
          }

          // 3. Attack Setup
          const cmd = activeCommands[actor.id];
          if (!cmd) continue;

          const target = workingState.find(c => c.id === cmd.targetId);
          if (!target || target.currentHp <= 0) {
              addLog(`${actor.name} has no valid target.`, 'info');
              continue;
          }

          // --- VISUAL: Attack Start ---
          setAnimatingAttackerId(actor.id); // Triggers Lunge
          await new Promise(r => setTimeout(r, 400)); // Wait for lunge forward

          // Calculate
          const result = resolveAttack(freshActor, target, cmd.zone);
          result.logs.forEach(l => addLog(l.text, l.type));

          // --- VISUAL: Dice Roll ---
          const visuals: DiceVisual[] = result.rolls.map((val, idx) => ({
              value: val,
              isHit: result.hits[idx]
          }));
          setActiveDice(visuals);
          setShowDice(true);

          await new Promise(r => setTimeout(r, 1000)); // Watch Dice
          setShowDice(false);

          // --- VISUAL: Impact ---
          setAnimatingAttackerId(null); // Reset Lunge

          if (result.damage > 0) {
              // HIT
              setAnimatingTargetId(target.id); // Trigger Shake/Flash
              addFloatingText(target.id, `-${result.damage}`, result.isCrit ? "crit" : "damage");

              // Update HP
              workingState = workingState.map(c => c.id === target.id ? { ...c, currentHp: Math.max(0, c.currentHp - result.damage) } : c);
              setCombatants(workingState); 

              // Short delay for impact perception
              await new Promise(r => setTimeout(r, 600));
              setAnimatingTargetId(null);
          } else {
              // MISS
              addFloatingText(target.id, "MISS", "miss");
              await new Promise(r => setTimeout(r, 500));
          }

          // Between turns delay
          await new Promise(r => setTimeout(r, 200));
      }

      const justActedTeam = actingTeam.length > 0 ? actingTeam[0].team : 'player'; 
      checkWinCondition(workingState, justActedTeam);
  };

  const checkWinCondition = (currentCombs: ActiveCombatant[], lastActiveTeam: 'player' | 'enemy') => {
      const playersAlive = currentCombs.some(c => c.team === 'player' && c.currentHp > 0);
      const enemiesAlive = currentCombs.some(c => c.team === 'enemy' && c.currentHp > 0);

      if (!playersAlive) {
          setPhase('DEFEAT');
          return;
      }
      if (!enemiesAlive) {
          setPhase('VICTORY');
          return;
      }

      if (lastActiveTeam === 'player') {
          startCommandPhase('enemy', currentCombs);
      } else {
          startCommandPhase('player', currentCombs);
      }
  };

  // --- Rendering Helpers ---

  const renderCombatant = (c: ActiveCombatant) => {
      const isDead = c.currentHp <= 0;
      const isTurn = turnQueue.includes(c.id);
      const isSelected = selectedTargetId === c.id;

      const maxHp = c.stats?.maxHp || 1;
      const hpPct = (c.currentHp / maxHp) * 100;

      // Animation Classes
      const isAttacking = animatingAttackerId === c.id;
      const isHit = animatingTargetId === c.id;

      // Floating Texts for this char
      const myFloatingTexts = floatingTexts.filter(ft => ft.combatantId === c.id);

      // Directions
      const isPlayer = c.team === 'player';
      const lungeClass = isAttacking 
          ? (isPlayer ? 'translate-x-12' : '-translate-x-12') 
          : 'translate-x-0';

      const shakeClass = isHit ? 'animate-[shake_0.5s_ease-in-out]' : '';

      return (
          <div 
             key={c.id} 
             onClick={() => {
                 if (phase === 'COMMAND' && turnQueue.length > 0) {
                     const actorId = turnQueue[0];
                     const actor = combatants.find(a => a.id === actorId);
                     if (actor?.team === 'player' && c.team === 'enemy' && !isDead) {
                         setSelectedTargetId(c.id);
                     }
                 }
             }}
             className={`relative w-32 md:w-40 flex flex-col items-center transition-all duration-300 transform ${lungeClass} ${shakeClass}
                ${isDead ? 'opacity-50 grayscale blur-[1px]' : ''}
                ${isTurn ? 'scale-110 drop-shadow-[0_0_15px_rgba(255,255,255,0.4)]' : ''}
                ${isSelected ? 'ring-2 ring-red-500 rounded-xl bg-red-900/20 scale-105' : ''}
                ${!isDead && c.team === 'enemy' && phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(x => x.id === turnQueue[0])?.team === 'player' ? 'cursor-pointer hover:bg-white/5 rounded-xl' : ''}
             `}
          >
              {/* Floating Texts */}
              <div className="absolute top-10 left-0 right-0 z-50 pointer-events-none flex flex-col items-center">
                  {myFloatingTexts.map(ft => (
                      <div key={ft.id} className={`
                          text-2xl font-black animate-[floatUp_1s_ease-out_forwards] stroke-black drop-shadow-md
                          ${ft.type === 'damage' ? 'text-red-500' : ''}
                          ${ft.type === 'crit' ? 'text-yellow-400 text-3xl' : ''}
                          ${ft.type === 'miss' ? 'text-gray-400' : ''}
                          ${ft.type === 'heal' ? 'text-green-500' : ''}
                      `}>
                          {ft.text}
                      </div>
                  ))}
              </div>

              {/* HP Bar */}
              <div className="w-full h-3 bg-gray-800 rounded-full mb-2 overflow-hidden border border-gray-600 shadow-inner relative">
                  <div 
                    className={`h-full transition-all duration-500 ease-out ${hpPct < 25 ? 'bg-red-600' : (hpPct < 50 ? 'bg-yellow-500' : 'bg-green-500')}`} 
                    style={{ width: `${hpPct}%` }} 
                  />
                  {/* HP Text Overlay */}
                  <div className="absolute inset-0 flex items-center justify-center text-[8px] font-bold text-white drop-shadow-md">
                      {c.currentHp} / {maxHp}
                  </div>
              </div>

              {/* Sprite */}
              <div className={`w-24 h-24 md:w-32 md:h-32 relative transition-all ${isHit ? 'brightness-150 saturate-0 sepia' : ''}`}>
                  {c.imageSrc || c.mapSpriteSrc ? (
                      <img src={c.imageSrc || c.mapSpriteSrc!} className="w-full h-full object-contain filter drop-shadow-lg" />
                  ) : (
                      <div className="w-full h-full bg-gray-700 rounded-full flex items-center justify-center text-xs text-center p-2 border-2 border-gray-500 shadow-xl">
                          {c.name}
                      </div>
                  )}
                  {c.isShocked && <div className="absolute top-0 right-0 text-yellow-400 bg-black/80 rounded-full p-1 animate-pulse"><Zap size={16}/></div>}
              </div>

              {/* Info */}
              <div className="bg-black/70 px-3 py-1 rounded text-xs mt-1 text-center min-w-[90px] backdrop-blur-sm border border-gray-700/50">
                  <div className="font-bold text-gray-200 truncate max-w-[100px]">{c.name}</div>
              </div>
          </div>
      );
  };

  return (
    <div className="fixed inset-0 z-[100] bg-black text-white flex flex-col font-sans select-none">
       <style>{`
          @keyframes shake {
            0%, 100% { transform: translateX(0); }
            25% { transform: translateX(-5px) rotate(-5deg); }
            75% { transform: translateX(5px) rotate(5deg); }
          }
          @keyframes floatUp {
            0% { transform: translateY(0) scale(1); opacity: 1; }
            100% { transform: translateY(-40px) scale(1.2); opacity: 0; }
          }
       `}</style>

       {/* Background */}
       <div className="absolute inset-0 z-0 opacity-40">
           {battle.backgroundSrc ? (
               <img src={battle.backgroundSrc} className="w-full h-full object-cover" />
           ) : (
               <div className="w-full h-full bg-red-950/40 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-gray-800 to-black" />
           )}
       </div>

       {/* DICE OVERLAY */}
       {showDice && (
           <div className="absolute inset-0 z-50 flex items-center justify-center pointer-events-none">
               <div className="bg-black/60 backdrop-blur-sm p-8 rounded-2xl flex gap-4 animate-in zoom-in duration-300 border border-white/10 shadow-2xl">
                   {activeDice.map((d, i) => (
                       <div key={i} className={`
                           w-16 h-16 flex items-center justify-center rounded-lg border-2 text-2xl font-bold shadow-lg
                           ${d.isHit ? 'bg-green-900 border-green-500 text-green-100' : 'bg-gray-800 border-gray-600 text-gray-400'}
                           ${d.value === 20 ? 'animate-bounce border-yellow-400 text-yellow-300 bg-yellow-900/50' : ''}
                       `}>
                           {d.value}
                       </div>
                   ))}
                   <div className="absolute -top-4 left-0 right-0 text-center text-sm font-bold uppercase tracking-widest text-white drop-shadow-md">Rolling...</div>
               </div>
           </div>
       )}

       {/* Header */}
       <div className="relative z-10 p-4 flex justify-between items-center bg-gradient-to-b from-black/90 to-transparent">
           <h2 className="text-2xl font-bold flex items-center gap-2 text-red-500 drop-shadow-md"><Sword size={24}/> {battle.name}</h2>
           <Button onClick={onExit} variant="secondary" className="text-xs py-1 border-red-900 text-red-200 hover:bg-red-900/20">Flee Battle</Button>
       </div>

       {/* Battle Area */}
       <div className="relative z-10 flex-1 flex flex-col md:flex-row items-center justify-between px-4 md:px-20 py-4 gap-8 overflow-y-auto">
           {/* Players */}
           <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">
              {combatants.filter(c => c.team === 'player').map(renderCombatant)}
           </div>

           {/* Center UI (Phase Info) */}
           <div className="flex flex-col items-center justify-center pointer-events-none">
              {phase === 'VICTORY' && (
                  <div className="text-center animate-bounce pointer-events-auto bg-black/50 p-6 rounded-xl backdrop-blur-md">
                      <h1 className="text-5xl font-bold text-yellow-400 mb-4 drop-shadow-[0_0_10px_rgba(250,204,21,0.5)]">VICTORY</h1>
                      <Button onClick={onWin} className="bg-yellow-600 hover:bg-yellow-500 text-xl px-8 py-4 shadow-yellow-900/50">Continue</Button>
                  </div>
              )}
              {phase === 'DEFEAT' && (
                  <div className="text-center pointer-events-auto bg-black/50 p-6 rounded-xl backdrop-blur-md">
                      <h1 className="text-5xl font-bold text-red-600 mb-4 drop-shadow-[0_0_10px_rgba(220,38,38,0.5)]">DEFEAT</h1>
                      <Button onClick={onLose} variant="danger" className="text-xl px-8 py-4">Retry</Button>
                  </div>
              )}
              {phase === 'INIT' && <div className="text-xl font-bold animate-pulse text-blue-300 tracking-widest uppercase">Rolling Initiative...</div>}
              {phase === 'EXECUTION' && !showDice && (
                 <div className="text-orange-400 font-bold bg-black/40 px-4 py-2 rounded-full backdrop-blur-sm border border-orange-500/30">
                     Resolving Actions...
                 </div>
              )}
           </div>

           {/* Enemies */}
           <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">
              {combatants.filter(c => c.team === 'enemy').map(renderCombatant)}
           </div>
       </div>

       {/* Bottom Control / Log Panel */}
       <div className="relative z-20 h-[30%] min-h-[220px] bg-black/95 border-t border-gray-800 flex flex-col md:flex-row shadow-[0_-5px_20px_rgba(0,0,0,0.5)]">

           {/* Controls (Only visible during Player Command) */}
           <div className="flex-1 p-6 border-b md:border-b-0 md:border-r border-gray-800 flex flex-col items-center justify-center gap-4 bg-gray-900/50">
              {phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(c => c.id === turnQueue[0])?.team === 'player' ? (
                  <>
                     <div className="text-lg font-bold text-indigo-300 mb-1 flex items-center gap-2">
                         <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse"></div>
                         Command: {combatants.find(c => c.id === turnQueue[0])?.name}
                     </div>

                     {!selectedTargetId ? (
                         <div className="text-gray-400 animate-pulse flex items-center gap-2 bg-gray-800/50 px-4 py-2 rounded-lg border border-dashed border-gray-600">
                            <Target size={16}/> Select an enemy to attack
                         </div>
                     ) : (
                         <div className="flex flex-col gap-3 w-full max-w-sm animate-in fade-in slide-in-from-bottom-4">
                            <div className="text-xs font-bold text-center text-gray-500 uppercase tracking-wide">Target Hit Zone</div>
                            <div className="grid grid-cols-2 gap-2">
                                <Button variant={selectedZone === 'torso' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('torso')} className="text-xs relative">Torso <span className="absolute right-2 text-[10px] opacity-50">0</span></Button>
                                <Button variant={selectedZone === 'head' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('head')} className="text-xs relative">Head <span className="absolute right-2 text-[10px] opacity-50 text-red-300">-6</span></Button>
                                <Button variant={selectedZone === 'arm' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('arm')} className="text-xs relative">Arm <span className="absolute right-2 text-[10px] opacity-50">-4</span></Button>
                                <Button variant={selectedZone === 'leg' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('leg')} className="text-xs relative">Leg <span className="absolute right-2 text-[10px] opacity-50">-3</span></Button>
                            </div>
                            <Button onClick={() => handlePlayerCommand(turnQueue[0])} className="w-full mt-2 bg-red-600 hover:bg-red-500 shadow-red-900/20 py-3 text-sm font-bold tracking-wider">
                                <Sword size={16}/> EXECUTE ATTACK
                            </Button>
                         </div>
                     )}
                  </>
              ) : (
                  <div className="text-gray-500 italic text-sm p-4 text-center flex flex-col items-center gap-2">
                      {phase === 'COMMAND' ? (
                          <><Activity className="animate-spin text-gray-600"/> Enemy is planning...</>
                      ) : (phase === 'EXECUTION' ? "Watching combat..." : "")}
                  </div>
              )}
           </div>

           {/* Logs */}
           <div ref={scrollRef} className="flex-[2] p-4 overflow-y-auto font-mono text-xs md:text-sm space-y-1 bg-gray-950">
               {logs.length === 0 && <div className="text-gray-700 italic">Combat Log initialized...</div>}
               {logs.map((log, i) => (
                   <div key={i} className={`
                      py-0.5 border-b border-white/5
                      ${log.type === 'attack' ? 'text-blue-300' : ''}
                      ${log.type === 'damage' ? 'text-red-400 font-bold' : ''}
                      ${log.type === 'crit' ? 'text-yellow-400 font-bold text-lg' : ''}
                      ${log.type === 'info' ? 'text-gray-500' : ''}
                   `}>
                       <span className="opacity-30 mr-2 text-[10px] w-6 inline-block text-right">[{i+1}]</span>
                       {log.text}
                   </div>
               ))}
           </div>
       </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Battle, Character, Zone, CombatStats, Weapon } from '../types';
import { ActiveCombatant, rollTeamInitiative, performShockTest, resolveAttack, CombatLog, d20 } from '../utils/combat';
import { Button } from './ui/Button';
import { Skull, Shield, Sword, Heart, Activity, Target, Zap, Dice5, Play, Pause, MousePointerClick } from 'lucide-react';

interface BattleArenaProps {
  battle: Battle;
  characters: Character[]; // All chars to pull data from
  onWin: () => void;
  onLose: () => void;
  onExit: () => void; // Escape/Quit
}

type BattlePhase = 'INIT' | 'COMMAND' | 'EXECUTION' | 'VICTORY' | 'DEFEAT';

// Visual Types
interface FloatingText {
    id: string;
    text: string;
    type: 'damage' | 'heal' | 'miss' | 'crit';
    combatantId: string;
}

interface DiceVisual {
    value: number;
    isHit: boolean;
}

export const BattleArena: React.FC<BattleArenaProps> = ({ battle, characters, onWin, onLose, onExit }) => {
  const [phase, setPhase] = useState<BattlePhase>('INIT');
  const [combatants, setCombatants] = useState<ActiveCombatant[]>([]);
  const [turnQueue, setTurnQueue] = useState<string[]>([]); 
  const [logs, setLogs] = useState<CombatLog[]>([]);

  // Settings
  const [autoMode, setAutoMode] = useState(false); // Default to Manual for more control

  // Command State
  const [selectedTargetId, setSelectedTargetId] = useState<string | null>(null);
  const [selectedZone, setSelectedZone] = useState<Zone>('torso');

  // Queued Commands
  const [commands, setCommands] = useState<Record<string, { targetId: string, zone: Zone }>>({});

  // --- Visual States ---
  const [floatingTexts, setFloatingTexts] = useState<FloatingText[]>([]);
  const [animatingAttackerId, setAnimatingAttackerId] = useState<string | null>(null); // For "Lunge"
  const [animatingTargetId, setAnimatingTargetId] = useState<string | null>(null); // For "Shake"
  const [activeDice, setActiveDice] = useState<DiceVisual[]>([]);
  const [showDice, setShowDice] = useState(false);
  const [diceLabel, setDiceLabel] = useState("");

  // Control Flow State
  const [waitingForClick, setWaitingForClick] = useState(false);
  const resolveClickRef = useRef<(() => void) | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);

  // Helper for adding floating text
  const addFloatingText = (combatantId: string, text: string, type: FloatingText['type']) => {
      const id = crypto.randomUUID();
      setFloatingTexts(prev => [...prev, { id, text, type, combatantId }]);
      setTimeout(() => {
          setFloatingTexts(prev => prev.filter(ft => ft.id !== id));
      }, 1500); // Remove after animation
  };

  // --- Flow Control Helper ---
  // Returns a promise that resolves immediately (Auto) or waits for user click (Manual)
  const waitForInput = async (autoDelayMs: number = 1000) => {
      if (autoMode) {
          return new Promise<void>(resolve => setTimeout(resolve, autoDelayMs));
      } else {
          setWaitingForClick(true);
          return new Promise<void>(resolve => {
              resolveClickRef.current = resolve;
          });
      }
  };

  const handleScreenClick = () => {
      if (waitingForClick && resolveClickRef.current) {
          setWaitingForClick(false);
          const resolver = resolveClickRef.current;
          resolveClickRef.current = null;
          resolver();
      }
  };

  // Initialize Combat
  useEffect(() => {
    let mounted = true;

    const init = () => {
      const parts: ActiveCombatant[] = [];
      // Setup Players
      battle.playerCharacterIds.forEach(id => {
        const c = characters.find(char => char.id === id);
        if (c) {
          parts.push({
            ...c,
            currentHp: c.stats?.hp || 20,
            isShocked: false,
            tempDefenseBonus: 0,
            team: 'player',
            stats: c.stats || {
                pra: 3, str: 3, wid: 3, ges: 3, wil: 3,
                hp: 20, maxHp: 20, limit: 10,
                weapon: { name: 'Fists', at: 3, mod: 0, dmg: 1, cap: null }
            }
          });
        }
      });

      // Setup Enemies
      battle.enemyCharacterIds.forEach(id => {
        const c = characters.find(char => char.id === id);
        if (c) {
          parts.push({
            ...c,
            currentHp: c.stats?.hp || 15,
            isShocked: false,
            tempDefenseBonus: 0,
            team: 'enemy',
            stats: c.stats || {
                pra: 2, str: 3, wid: 2, ges: 2, wil: 2,
                hp: 15, maxHp: 15, limit: 6,
                weapon: { name: 'Claws', at: 4, mod: 1, dmg: 2, cap: 4 }
            }
          });
        }
      });

      if (!mounted) return;

      setCombatants(parts);
      addLog("Battle Started! Rolling Initiative...", 'info');

      const playerTeam = parts.filter(c => c.team === 'player');
      const enemyTeam = parts.filter(c => c.team === 'enemy');

      const pInit = rollTeamInitiative(playerTeam);
      const eInit = rollTeamInitiative(enemyTeam);

      addLog(`Players: ${pInit} | Enemies: ${eInit}`, 'info');

      if (pInit >= eInit) {
          addLog("Player Team takes the initiative!", 'info');
          startCommandPhase('player', parts);
      } else {
          addLog("Enemy Team takes the initiative!", 'info');
          startCommandPhase('enemy', parts);
      }
    };

    init();
    return () => { mounted = false; };
  }, [battle]);

  useEffect(() => {
      if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [logs]);

  const addLog = (text: string, type: CombatLog['type']) => {
    setLogs(prev => [...prev, { text, type }]);
  };

  const startCommandPhase = (activeTeam: 'player' | 'enemy', currentCombatants: ActiveCombatant[]) => {
      setPhase('COMMAND');
      const teamMembers = currentCombatants.filter(c => c.team === activeTeam && c.currentHp > 0);
      setTurnQueue(teamMembers.map(c => c.id));
      setCommands({}); 

      if (activeTeam === 'enemy') {
          setTimeout(() => runEnemyAI(teamMembers, currentCombatants), 1000);
      }
  };

  const runEnemyAI = (enemies: ActiveCombatant[], allCombatants: ActiveCombatant[]) => {
     const alivePlayers = allCombatants.filter(c => c.team === 'player' && c.currentHp > 0);

     if (alivePlayers.length === 0) {
         executePhase(enemies, {}, allCombatants);
         return;
     }

     const aiCommands: Record<string, { targetId: string, zone: Zone }> = {};
     enemies.forEach(e => {
         const target = alivePlayers[Math.floor(Math.random() * alivePlayers.length)];
         aiCommands[e.id] = { targetId: target.id, zone: 'torso' }; 
     });

     setCommands(aiCommands); 
     setTimeout(() => executePhase(enemies, aiCommands, allCombatants), 1000);
  };

  const handlePlayerCommand = (attackerId: string) => {
      if (!selectedTargetId) return;

      const newCommands = {
          ...commands,
          [attackerId]: { targetId: selectedTargetId, zone: selectedZone }
      };

      setCommands(newCommands);

      const nextQueue = turnQueue.filter(id => id !== attackerId);
      setTurnQueue(nextQueue);
      setSelectedTargetId(null);
      setSelectedZone('torso');

      if (nextQueue.length === 0) {
          executePhase(combatants.filter(c => c.team === 'player'), newCommands, combatants);
      }
  };

  const executePhase = async (
      actingTeam: ActiveCombatant[], 
      activeCommands: Record<string, { targetId: string, zone: Zone }>,
      currentCombatants: ActiveCombatant[]
  ) => {
      setPhase('EXECUTION');

      let workingState = [...currentCombatants]; 

      for (const actor of actingTeam) {
          // 1. Check Death
          const freshActor = workingState.find(c => c.id === actor.id);
          if (!freshActor || freshActor.currentHp <= 0) continue;

          // 2. Shock Test
          const shockResult = performShockTest(freshActor);
          if (shockResult.log) addLog(shockResult.log, 'info');

          if (freshActor.currentHp < (freshActor.stats!.maxHp * 0.25)) {
               workingState = workingState.map(c => c.id === actor.id ? { ...c, isShocked: shockResult.shocked } : c);
          }

          if (shockResult.shocked) {
             addFloatingText(actor.id, "SHOCKED", "miss");
             await waitForInput(800);
             continue; 
          }

          // 3. Attack Setup
          const cmd = activeCommands[actor.id];
          if (!cmd) continue;

          const target = workingState.find(c => c.id === cmd.targetId);
          if (!target || target.currentHp <= 0) {
              addLog(`${actor.name} has no valid target.`, 'info');
              continue;
          }

          // --- VISUAL: Attack Start ---
          setAnimatingAttackerId(actor.id); // Triggers Lunge
          await waitForInput(400); // Wait for lunge forward

          // Calculate
          const result = resolveAttack(freshActor, target, cmd.zone);
          result.logs.forEach(l => addLog(l.text, l.type));

          // --- VISUAL: Dice Roll PREPARE ---
          setDiceLabel("Ready to Roll...");
          setActiveDice([]); // Clear old dice
          setShowDice(true);

          // Wait for player to click to ROLL the dice
          await waitForInput(500); 

          // --- VISUAL: Dice Roll REVEAL ---
          const visuals: DiceVisual[] = result.rolls.map((val, idx) => ({
              value: val,
              isHit: result.hits[idx]
          }));
          setActiveDice(visuals);
          setDiceLabel(result.damage > 0 ? "HIT!" : "MISS");

          // Wait for player to click to CONFIRM the result
          await waitForInput(1500); 

          setShowDice(false);

          // --- VISUAL: Impact ---
          setAnimatingAttackerId(null); // Reset Lunge

          if (result.damage > 0) {
              // HIT
              setAnimatingTargetId(target.id); // Trigger Shake/Flash
              addFloatingText(target.id, `-${result.damage}`, result.isCrit ? "crit" : "damage");

              // Update HP
              workingState = workingState.map(c => c.id === target.id ? { ...c, currentHp: Math.max(0, c.currentHp - result.damage) } : c);
              setCombatants(workingState); 

              // Short delay for impact perception
              await waitForInput(600);
              setAnimatingTargetId(null);
          } else {
              // MISS
              addFloatingText(target.id, "MISS", "miss");
              await waitForInput(500);
          }

          // Between turns delay
          await waitForInput(200);
      }

      const justActedTeam = actingTeam.length > 0 ? actingTeam[0].team : 'player'; 
      checkWinCondition(workingState, justActedTeam);
  };

  const checkWinCondition = (currentCombs: ActiveCombatant[], lastActiveTeam: 'player' | 'enemy') => {
      const playersAlive = currentCombs.some(c => c.team === 'player' && c.currentHp > 0);
      const enemiesAlive = currentCombs.some(c => c.team === 'enemy' && c.currentHp > 0);

      if (!playersAlive) {
          setPhase('DEFEAT');
          return;
      }
      if (!enemiesAlive) {
          setPhase('VICTORY');
          return;
      }

      if (lastActiveTeam === 'player') {
          startCommandPhase('enemy', currentCombs);
      } else {
          startCommandPhase('player', currentCombs);
      }
  };

  // --- Rendering Helpers ---

  const renderCombatant = (c: ActiveCombatant) => {
      const isDead = c.currentHp <= 0;
      const isTurn = turnQueue.includes(c.id);
      const isSelected = selectedTargetId === c.id;

      const maxHp = c.stats?.maxHp || 1;
      const hpPct = (c.currentHp / maxHp) * 100;

      // Animation Classes
      const isAttacking = animatingAttackerId === c.id;
      const isHit = animatingTargetId === c.id;

      // Floating Texts for this char
      const myFloatingTexts = floatingTexts.filter(ft => ft.combatantId === c.id);

      // Directions
      const isPlayer = c.team === 'player';
      const lungeClass = isAttacking 
          ? (isPlayer ? 'translate-x-12' : '-translate-x-12') 
          : 'translate-x-0';

      const shakeClass = isHit ? 'animate-[shake_0.5s_ease-in-out]' : '';

      return (
          <div 
             key={c.id} 
             onClick={() => {
                 if (phase === 'COMMAND' && turnQueue.length > 0) {
                     const actorId = turnQueue[0];
                     const actor = combatants.find(a => a.id === actorId);
                     if (actor?.team === 'player' && c.team === 'enemy' && !isDead) {
                         setSelectedTargetId(c.id);
                     }
                 }
             }}
             className={`relative w-32 md:w-40 flex flex-col items-center transition-all duration-300 transform ${lungeClass} ${shakeClass}
                ${isDead ? 'opacity-50 grayscale blur-[1px]' : ''}
                ${isTurn ? 'scale-110 drop-shadow-[0_0_15px_rgba(255,255,255,0.4)]' : ''}
                ${isSelected ? 'ring-2 ring-red-500 rounded-xl bg-red-900/20 scale-105' : ''}
                ${!isDead && c.team === 'enemy' && phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(x => x.id === turnQueue[0])?.team === 'player' ? 'cursor-pointer hover:bg-white/5 rounded-xl' : ''}
             `}
          >
              {/* Floating Texts */}
              <div className="absolute top-10 left-0 right-0 z-50 pointer-events-none flex flex-col items-center">
                  {myFloatingTexts.map(ft => (
                      <div key={ft.id} className={`
                          text-2xl font-black animate-[floatUp_1s_ease-out_forwards] stroke-black drop-shadow-md
                          ${ft.type === 'damage' ? 'text-red-500' : ''}
                          ${ft.type === 'crit' ? 'text-yellow-400 text-3xl' : ''}
                          ${ft.type === 'miss' ? 'text-gray-400' : ''}
                          ${ft.type === 'heal' ? 'text-green-500' : ''}
                      `}>
                          {ft.text}
                      </div>
                  ))}
              </div>

              {/* HP Bar */}
              <div className="w-full h-3 bg-gray-800 rounded-full mb-2 overflow-hidden border border-gray-600 shadow-inner relative">
                  <div 
                    className={`h-full transition-all duration-500 ease-out ${hpPct < 25 ? 'bg-red-600' : (hpPct < 50 ? 'bg-yellow-500' : 'bg-green-500')}`} 
                    style={{ width: `${hpPct}%` }} 
                  />
                  {/* HP Text Overlay */}
                  <div className="absolute inset-0 flex items-center justify-center text-[8px] font-bold text-white drop-shadow-md">
                      {c.currentHp} / {maxHp}
                  </div>
              </div>

              {/* Sprite */}
              <div className={`w-24 h-24 md:w-32 md:h-32 relative transition-all ${isHit ? 'brightness-150 saturate-0 sepia' : ''}`}>
                  {c.imageSrc || c.mapSpriteSrc ? (
                      <img src={c.imageSrc || c.mapSpriteSrc!} className="w-full h-full object-contain filter drop-shadow-lg" />
                  ) : (
                      <div className="w-full h-full bg-gray-700 rounded-full flex items-center justify-center text-xs text-center p-2 border-2 border-gray-500 shadow-xl">
                          {c.name}
                      </div>
                  )}
                  {c.isShocked && <div className="absolute top-0 right-0 text-yellow-400 bg-black/80 rounded-full p-1 animate-pulse"><Zap size={16}/></div>}
              </div>

              {/* Info */}
              <div className="bg-black/70 px-3 py-1 rounded text-xs mt-1 text-center min-w-[90px] backdrop-blur-sm border border-gray-700/50">
                  <div className="font-bold text-gray-200 truncate max-w-[100px]">{c.name}</div>
              </div>
          </div>
      );
  };

  return (
    <div className="fixed inset-0 z-[100] bg-black text-white flex flex-col font-sans select-none">
       <style>{`
          @keyframes shake {
            0%, 100% { transform: translateX(0); }
            25% { transform: translateX(-5px) rotate(-5deg); }
            75% { transform: translateX(5px) rotate(5deg); }
          }
          @keyframes floatUp {
            0% { transform: translateY(0) scale(1); opacity: 1; }
            100% { transform: translateY(-40px) scale(1.2); opacity: 0; }
          }
       `}</style>

       {/* CLICK TO CONTINUE OVERLAY */}
       {waitingForClick && (
           <div 
              onClick={handleScreenClick}
              className="absolute inset-0 z-[60] cursor-pointer flex items-end justify-center pb-32 hover:bg-white/5 transition-colors"
           >
               <div className="bg-black/80 text-white border border-gray-500 px-6 py-3 rounded-full animate-bounce flex items-center gap-2 shadow-[0_0_20px_rgba(255,255,255,0.2)] font-bold tracking-widest uppercase">
                   <MousePointerClick size={20} /> Click to Continue
               </div>
           </div>
       )}

       {/* Background */}
       <div className="absolute inset-0 z-0 opacity-40">
           {battle.backgroundSrc ? (
               <img src={battle.backgroundSrc} className="w-full h-full object-cover" />
           ) : (
               <div className="w-full h-full bg-red-950/40 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-gray-800 to-black" />
           )}
       </div>

       {/* DICE OVERLAY */}
       {showDice && (
           <div className="absolute inset-0 z-50 flex items-center justify-center pointer-events-none">
               <div className="bg-black/80 backdrop-blur-md p-8 rounded-2xl flex flex-col items-center gap-6 animate-in zoom-in duration-300 border border-white/20 shadow-2xl min-w-[300px]">

                   <div className="text-xl font-bold uppercase tracking-widest text-white drop-shadow-md border-b border-gray-600 pb-2 w-full text-center">
                       {diceLabel}
                   </div>

                   <div className="flex gap-4">
                       {activeDice.length === 0 ? (
                           <div className="flex gap-4 animate-pulse">
                               <div className="w-16 h-16 rounded-lg bg-gray-700 border-2 border-gray-500 flex items-center justify-center"><Dice5 size={32} className="animate-spin text-gray-500"/></div>
                               <div className="w-16 h-16 rounded-lg bg-gray-700 border-2 border-gray-500 flex items-center justify-center"><Dice5 size={32} className="animate-spin text-gray-500"/></div>
                               <div className="w-16 h-16 rounded-lg bg-gray-700 border-2 border-gray-500 flex items-center justify-center"><Dice5 size={32} className="animate-spin text-gray-500"/></div>
                           </div>
                       ) : (
                           activeDice.map((d, i) => (
                               <div key={i} className={`
                                   w-16 h-16 flex items-center justify-center rounded-lg border-2 text-2xl font-bold shadow-lg animate-in slide-in-from-top-4
                                   ${d.isHit ? 'bg-green-900 border-green-500 text-green-100' : 'bg-gray-800 border-gray-600 text-gray-400'}
                                   ${d.value === 20 ? 'animate-bounce border-yellow-400 text-yellow-300 bg-yellow-900/50' : ''}
                               `}>
                                   {d.value}
                               </div>
                           ))
                       )}
                   </div>

                   {waitingForClick && (
                       <div className="text-xs text-gray-400 animate-pulse mt-2">Click to proceed</div>
                   )}
               </div>
           </div>
       )}

       {/* Header */}
       <div className="relative z-10 p-4 flex justify-between items-center bg-gradient-to-b from-black/90 to-transparent">
           <h2 className="text-2xl font-bold flex items-center gap-2 text-red-500 drop-shadow-md"><Sword size={24}/> {battle.name}</h2>

           <div className="flex items-center gap-4">
               {/* Auto Mode Toggle */}
               <button 
                  onClick={() => setAutoMode(!autoMode)}
                  className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold border transition-all ${autoMode ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}
               >
                   {autoMode ? <Play size={14} fill="currentColor"/> : <Pause size={14} fill="currentColor"/>}
                   {autoMode ? 'AUTO MODE' : 'MANUAL MODE'}
               </button>

               <Button onClick={onExit} variant="secondary" className="text-xs py-1 border-red-900 text-red-200 hover:bg-red-900/20">Flee Battle</Button>
           </div>
       </div>

       {/* Battle Area */}
       <div className="relative z-10 flex-1 flex flex-col md:flex-row items-center justify-between px-4 md:px-20 py-4 gap-8 overflow-y-auto">
           {/* Players */}
           <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">
              {combatants.filter(c => c.team === 'player').map(renderCombatant)}
           </div>

           {/* Center UI (Phase Info) */}
           <div className="flex flex-col items-center justify-center pointer-events-none">
              {phase === 'VICTORY' && (
                  <div className="text-center animate-bounce pointer-events-auto bg-black/50 p-6 rounded-xl backdrop-blur-md">
                      <h1 className="text-5xl font-bold text-yellow-400 mb-4 drop-shadow-[0_0_10px_rgba(250,204,21,0.5)]">VICTORY</h1>
                      <Button onClick={onWin} className="bg-yellow-600 hover:bg-yellow-500 text-xl px-8 py-4 shadow-yellow-900/50">Continue</Button>
                  </div>
              )}
              {phase === 'DEFEAT' && (
                  <div className="text-center pointer-events-auto bg-black/50 p-6 rounded-xl backdrop-blur-md">
                      <h1 className="text-5xl font-bold text-red-600 mb-4 drop-shadow-[0_0_10px_rgba(220,38,38,0.5)]">DEFEAT</h1>
                      <Button onClick={onLose} variant="danger" className="text-xl px-8 py-4">Retry</Button>
                  </div>
              )}
              {phase === 'INIT' && <div className="text-xl font-bold animate-pulse text-blue-300 tracking-widest uppercase">Rolling Initiative...</div>}
              {phase === 'EXECUTION' && !showDice && (
                 <div className="text-orange-400 font-bold bg-black/40 px-4 py-2 rounded-full backdrop-blur-sm border border-orange-500/30">
                     Resolving Actions...
                 </div>
              )}
           </div>

           {/* Enemies */}
           <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">
              {combatants.filter(c => c.team === 'enemy').map(renderCombatant)}
           </div>
       </div>

       {/* Bottom Control / Log Panel */}
       <div className="relative z-20 h-[30%] min-h-[220px] bg-black/95 border-t border-gray-800 flex flex-col md:flex-row shadow-[0_-5px_20px_rgba(0,0,0,0.5)]">

           {/* Controls (Only visible during Player Command) */}
           <div className="flex-1 p-6 border-b md:border-b-0 md:border-r border-gray-800 flex flex-col items-center justify-center gap-4 bg-gray-900/50">
              {phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(c => c.id === turnQueue[0])?.team === 'player' ? (
                  <>
                     <div className="text-lg font-bold text-indigo-300 mb-1 flex items-center gap-2">
                         <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse"></div>
                         Command: {combatants.find(c => c.id === turnQueue[0])?.name}
                     </div>

                     {!selectedTargetId ? (
                         <div className="text-gray-400 animate-pulse flex items-center gap-2 bg-gray-800/50 px-4 py-2 rounded-lg border border-dashed border-gray-600">
                            <Target size={16}/> Select an enemy to attack
                         </div>
                     ) : (
                         <div className="flex flex-col gap-3 w-full max-w-sm animate-in fade-in slide-in-from-bottom-4">
                            <div className="text-xs font-bold text-center text-gray-500 uppercase tracking-wide">Target Hit Zone</div>
                            <div className="grid grid-cols-2 gap-2">
                                <Button variant={selectedZone === 'torso' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('torso')} className="text-xs relative">Torso <span className="absolute right-2 text-[10px] opacity-50">0</span></Button>
                                <Button variant={selectedZone === 'head' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('head')} className="text-xs relative">Head <span className="absolute right-2 text-[10px] opacity-50 text-red-300">-6</span></Button>
                                <Button variant={selectedZone === 'arm' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('arm')} className="text-xs relative">Arm <span className="absolute right-2 text-[10px] opacity-50">-4</span></Button>
                                <Button variant={selectedZone === 'leg' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('leg')} className="text-xs relative">Leg <span className="absolute right-2 text-[10px] opacity-50">-3</span></Button>
                            </div>
                            <Button onClick={() => handlePlayerCommand(turnQueue[0])} className="w-full mt-2 bg-red-600 hover:bg-red-500 shadow-red-900/20 py-3 text-sm font-bold tracking-wider">
                                <Sword size={16}/> EXECUTE ATTACK
                            </Button>
                         </div>
                     )}
                  </>
              ) : (
                  <div className="text-gray-500 italic text-sm p-4 text-center flex flex-col items-center gap-2">
                      {phase === 'COMMAND' ? (
                          <><Activity className="animate-spin text-gray-600"/> Enemy is planning...</>
                      ) : (phase === 'EXECUTION' ? "Watching combat..." : "")}
                  </div>
              )}
           </div>

           {/* Logs */}
           <div ref={scrollRef} className="flex-[2] p-4 overflow-y-auto font-mono text-xs md:text-sm space-y-1 bg-gray-950">
               {logs.length === 0 && <div className="text-gray-700 italic">Combat Log initialized...</div>}
               {logs.map((log, i) => (
                   <div key={i} className={`
                      py-0.5 border-b border-white/5
                      ${log.type === 'attack' ? 'text-blue-300' : ''}
                      ${log.type === 'damage' ? 'text-red-400 font-bold' : ''}
                      ${log.type === 'crit' ? 'text-yellow-400 font-bold text-lg' : ''}
                      ${log.type === 'info' ? 'text-gray-500' : ''}
                   `}>
                       <span className="opacity-30 mr-2 text-[10px] w-6 inline-block text-right">[{i+1}]</span>
                       {log.text}
                   </div>
               ))}
           </div>
       </div>
    </div>
  );
};

import { Character, Zone } from "../types";

export interface CombatLog {
  text: string;
  type: 'info' | 'attack' | 'damage' | 'crit' | 'error';
}

export interface ActiveCombatant extends Character {
  currentHp: number;
  isShocked: boolean;
  tempDefenseBonus: number; // From Momentum-Check failure of opponent
  team: 'player' | 'enemy';
}

export interface DetailedRoll {
    roll: number; // The D20 result
    total: number; // Result + Modifiers
    isSuccess?: boolean;
    label?: string;
}

export interface AttackResult {
  damage: number;
  logs: CombatLog[];
  defenderBonusNextTurn: number;

  // Detailed Steps for Visualization
  defenseRoll: DetailedRoll;
  attackRolls: DetailedRoll[];
  woundRolls: DetailedRoll[];

  isCrit: boolean;
  isHeadshot: boolean;
}

// D20 Helper
export const d20 = () => Math.floor(Math.random() * 20) + 1;

// 1. Initiative
export const rollTeamInitiative = (combatants: ActiveCombatant[]): { total: number, roll: number, bestChar: string } => {
  const sorted = [...combatants].sort((a,b) => (b.stats?.ges || 0) - (a.stats?.ges || 0));
  const bestChar = sorted[0];
  const maxDex = bestChar.stats?.ges || 0;
  const roll = d20();
  return { total: maxDex + roll, roll, bestChar: bestChar.name };
};

// Phase 1: Shock Test
export const performShockTest = (c: ActiveCombatant): { shocked: boolean, log: string, rollData?: DetailedRoll } => {
  const maxHp = c.stats?.maxHp || 10;
  const hpThreshold = maxHp * 0.25;

  if (c.currentHp < hpThreshold) {
    const roll = d20();
    const wil = c.stats?.wil || 0;
    const total = roll + wil;
    const threshold = 15;
    const success = total >= threshold;

    const rollData: DetailedRoll = { roll, total, isSuccess: success, label: `Shock Check (TN 15)` };

    if (success) {
      return { shocked: false, log: `${c.name} fights through the pain.`, rollData };
    } else {
      return { shocked: true, log: `${c.name} goes into SHOCK!`, rollData };
    }
  }
  return { shocked: false, log: '' };
};

// Phase 2: Execution Algorithm
export const resolveAttack = (
  attacker: ActiveCombatant, 
  defender: ActiveCombatant, 
  zone: Zone
): AttackResult => {

  const logs: CombatLog[] = [];
  const stats = attacker.stats!;
  const defStats = defender.stats!;
  const weapon = stats.weapon;

  // Zone Mods
  let zoneMalus = 0;
  let isHeadshot = false;

  switch(zone) {
    case 'head': zoneMalus = 6; isHeadshot = true; break;
    case 'arm': zoneMalus = 4; break;
    case 'leg': zoneMalus = 3; break;
    default: zoneMalus = 0; // Torso
  }

  // --- Step 1: Target Number (TN) - Defense Roll ---
  const defRollVal = d20();
  const tn = defRollVal + (defender.isShocked ? 0 : defStats.ges); 
  const defenseRoll: DetailedRoll = { roll: defRollVal, total: tn, label: `Evasion (GES ${defStats.ges})` };

  logs.push({ text: `${defender.name} evades: TN ${tn} (Roll ${defRollVal})`, type: 'info' });

  // --- Step 2: The Salve (Hit Roll) ---
  const diceCount = weapon.at;
  const attackRolls: DetailedRoll[] = [];

  const hits: number[] = [];
  let bestRoll = 0;
  let nat20 = false;

  const shockPenalty = attacker.currentHp < (stats.maxHp * 0.25) && !attacker.isShocked ? 2 : 0; 

  for(let i=0; i < diceCount; i++) {
    const roll = d20();
    if (roll === 20) nat20 = true;

    const total = roll + stats.pra + weapon.mod - zoneMalus - shockPenalty;
    const isHit = total > tn;

    attackRolls.push({ roll, total, isSuccess: isHit });

    if (isHit) {
      hits.push(total);
    }
    if (total > bestRoll) bestRoll = total;
  }

  logs.push({ text: `${attacker.name} attacks: [${attackRolls.map(r => r.total).join(', ')}] vs TN ${tn}`, type: 'attack' });

  // Momentum Check (Counter Advantage)
  let defenderBonusNextTurn = 0;
  if (hits.length === 0 && bestRoll < (tn - 10)) {
    defenderBonusNextTurn = 4;
    logs.push({ text: `Attack missed badly! ${defender.name} gains Counter Advantage.`, type: 'info' });
  }

  if (hits.length === 0) {
    return { 
        damage: 0, logs, defenderBonusNextTurn,
        defenseRoll, attackRolls, woundRolls: [],
        isCrit: false, isHeadshot: false
    };
  }

  // --- Step 3: Wound Roll (Durchschlag) ---
  const threshold = 10 - (stats.str - defStats.wid);
  let confirmedWounds = 0;
  const woundRolls: DetailedRoll[] = [];

  for(let i=0; i < hits.length; i++) {
    const r = d20();
    const isWound = r > threshold;
    woundRolls.push({ roll: r, total: r, isSuccess: isWound, label: `Wound Check (> ${threshold})` });

    if (isWound) {
      confirmedWounds++;
    }
  }

  logs.push({ text: `${confirmedWounds} Wounds confirmed.`, type: 'info' });

  if (confirmedWounds === 0) {
    logs.push({ text: `Hit but no penetration!`, type: 'info' });
    return { 
        damage: 0, logs, defenderBonusNextTurn,
        defenseRoll, attackRolls, woundRolls,
        isCrit: false, isHeadshot: false
    };
  }

  // --- Step 4: Damage Calculation ---
  let rawDamage = 0;

  for (let i = 0; i < confirmedWounds; i++) {
    let woundDmg = weapon.dmg; 

    // Crit Effect: Headshot +50%
    if (nat20 && isHeadshot) {
      woundDmg = Math.ceil(woundDmg * 1.5);
    }

    // Weapon Cap Check
    if (weapon.cap !== null && woundDmg > weapon.cap) {
      woundDmg = weapon.cap;
    }

    rawDamage += woundDmg;
  }

  // Defender Limit Check
  const finalDamage = Math.min(rawDamage, defStats.limit);

  logs.push({ text: `${attacker.name} deals ${finalDamage} DAMAGE to ${defender.name}!`, type: 'damage' });

  // --- Step 5: Critical Effects ---
  if (nat20) {
    if (zone === 'head') logs.push({ text: `CRITICAL HEADSHOT! ${defender.name} is stunned!`, type: 'crit' }); 
    if (zone === 'arm') logs.push({ text: `CRITICAL HIT TO ARM! Disarmed!`, type: 'crit' });
    if (zone === 'leg') logs.push({ text: `CRITICAL HIT TO LEG! Crippled!`, type: 'crit' });
  }

  return { 
      damage: finalDamage, logs, defenderBonusNextTurn,
      defenseRoll, attackRolls, woundRolls,
      isCrit: nat20, isHeadshot: isHeadshot
  };
};

import React, { useState, useEffect, useRef } from 'react';
import { Battle, Character, Zone } from '../types';
import { ActiveCombatant, rollTeamInitiative, performShockTest, resolveAttack, CombatLog, DetailedRoll } from '../utils/combat';
import { Button } from './ui/Button';
import { Sword, Target, Zap, Dice5, Play, Pause, Activity } from 'lucide-react';

interface BattleArenaProps {
  battle: Battle;
  characters: Character[]; 
  onWin: () => void;
  onLose: () => void;
  onExit: () => void;
}

type BattlePhase = 'INIT' | 'COMMAND' | 'EXECUTION' | 'VICTORY' | 'DEFEAT';

interface FloatingText {
    id: string;
    text: string;
    type: 'damage' | 'heal' | 'miss' | 'crit';
    combatantId: string;
}

export const BattleArena: React.FC<BattleArenaProps> = ({ battle, characters, onWin, onLose, onExit }) => {
  const [phase, setPhase] = useState<BattlePhase>('INIT');
  const [combatants, setCombatants] = useState<ActiveCombatant[]>([]);
  const [turnQueue, setTurnQueue] = useState<string[]>([]); 
  const [logs, setLogs] = useState<CombatLog[]>([]);

  // Settings
  const [autoMode, setAutoMode] = useState(false); 

  // Command State
  const [selectedTargetId, setSelectedTargetId] = useState<string | null>(null);
  const [selectedZone, setSelectedZone] = useState<Zone>('torso');
  const [commands, setCommands] = useState<Record<string, { targetId: string, zone: Zone }>>({});

  // --- Visual States ---
  const [floatingTexts, setFloatingTexts] = useState<FloatingText[]>([]);
  const [animatingAttackerId, setAnimatingAttackerId] = useState<string | null>(null);
  const [animatingTargetId, setAnimatingTargetId] = useState<string | null>(null);

  // DICE VISUALS
  const [activeDice, setActiveDice] = useState<DetailedRoll[]>([]);
  const [showDice, setShowDice] = useState(false);
  const [diceLabel, setDiceLabel] = useState("");
  const [diceSubLabel, setDiceSubLabel] = useState(""); // For small details like "vs TN 15"

  // Control Flow State
  const [waitingForClick, setWaitingForClick] = useState(false);
  const resolveClickRef = useRef<(() => void) | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);

  const addFloatingText = (combatantId: string, text: string, type: FloatingText['type']) => {
      const id = crypto.randomUUID();
      setFloatingTexts(prev => [...prev, { id, text, type, combatantId }]);
      setTimeout(() => setFloatingTexts(prev => prev.filter(ft => ft.id !== id)), 1500);
  };

  const addLog = (text: string, type: CombatLog['type']) => {
    setLogs(prev => [...prev, { text, type }]);
  };

  // --- WAIT LOGIC ---
  const waitForInput = async (autoDelayMs: number = 800) => {
      if (autoMode) {
          return new Promise<void>(resolve => setTimeout(resolve, autoDelayMs));
      } else {
          setWaitingForClick(true);
          return new Promise<void>(resolve => {
              resolveClickRef.current = resolve;
          });
      }
  };

  const handleScreenClick = () => {
      if (waitingForClick && resolveClickRef.current) {
          setWaitingForClick(false);
          const resolver = resolveClickRef.current;
          resolveClickRef.current = null;
          resolver();
      }
  };

  // --- DICE ANIMATION HELPER ---
  const visualizeRolls = async (
      label: string, 
      subLabel: string, 
      rolls: DetailedRoll[], 
      isManualTrigger: boolean // If true, player must click to START the roll
  ) => {
      setDiceLabel(label);
      setDiceSubLabel(subLabel);
      setActiveDice([]); 
      setShowDice(true);

      // 1. Wait for Start (if Manual)
      if (isManualTrigger && !autoMode) {
          setDiceLabel(`Ready to ${label}`);
          await waitForInput(0); // Infinite wait until click
      }

      setDiceLabel(label); // Restore label

      // 2. Animate "Rolling" (Fake numbers)
      const duration = 600;
      const interval = 50;
      const steps = duration / interval;

      for(let i=0; i<steps; i++) {
          const fakeRolls = rolls.map(() => ({ roll: Math.floor(Math.random()*20)+1, total: 0 }));
          setActiveDice(fakeRolls);
          await new Promise(r => setTimeout(r, interval));
      }

      // 3. Show Final Result
      setActiveDice(rolls);

      // 4. Wait for Acknowledgement
      await waitForInput(1500);

      setShowDice(false);
  };

  // Initialize Combat
  useEffect(() => {
    let mounted = true;

    const init = async () => {
      const parts: ActiveCombatant[] = [];
      // Hydrate characters from IDs
      [...battle.playerCharacterIds, ...battle.enemyCharacterIds].forEach(id => {
          const c = characters.find(char => char.id === id);
          if (c) {
              const team = battle.playerCharacterIds.includes(id) ? 'player' : 'enemy';
              parts.push({
                  ...c,
                  currentHp: c.stats?.hp || 20,
                  isShocked: false,
                  tempDefenseBonus: 0,
                  team,
                  stats: c.stats || { pra: 3, str: 3, wid: 3, ges: 3, wil: 3, hp: 20, maxHp: 20, limit: 10, weapon: { name: 'Hands', at: 3, mod: 0, dmg: 1, cap: null } }
              });
          }
      });

      if (!mounted) return;
      setCombatants(parts);

      // --- VISUAL: INITIATIVE ---
      const playerTeam = parts.filter(c => c.team === 'player');
      const enemyTeam = parts.filter(c => c.team === 'enemy');

      const pInit = rollTeamInitiative(playerTeam);
      const eInit = rollTeamInitiative(enemyTeam);

      // Determine who rolls visually based on which side contains the player (usually always player side)
      // We'll show both rolls sequentially

      await visualizeRolls("Player Initiative", `Best DEX: ${pInit.total - pInit.roll}`, [{ roll: pInit.roll, total: pInit.total }], true);
      await visualizeRolls("Enemy Initiative", `Best DEX: ${eInit.total - eInit.roll}`, [{ roll: eInit.roll, total: eInit.total }], false);

      addLog(`Initiative: Player ${pInit.total} vs Enemy ${eInit.total}`, 'info');

      if (pInit.total >= eInit.total) {
          startCommandPhase('player', parts);
      } else {
          startCommandPhase('enemy', parts);
      }
    };

    init();
    return () => { mounted = false; };
  }, [battle]);

  // Scroll to bottom of logs
  useEffect(() => {
      if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [logs]);

  const startCommandPhase = (activeTeam: 'player' | 'enemy', currentCombatants: ActiveCombatant[]) => {
      setPhase('COMMAND');
      const teamMembers = currentCombatants.filter(c => c.team === activeTeam && c.currentHp > 0);
      setTurnQueue(teamMembers.map(c => c.id));
      setCommands({}); 

      if (activeTeam === 'enemy') {
          setTimeout(() => runEnemyAI(teamMembers, currentCombatants), 500);
      }
  };

  const runEnemyAI = (enemies: ActiveCombatant[], allCombatants: ActiveCombatant[]) => {
     const alivePlayers = allCombatants.filter(c => c.team === 'player' && c.currentHp > 0);
     if (alivePlayers.length === 0) {
         executePhase(enemies, {}, allCombatants);
         return;
     }
     const aiCommands: Record<string, { targetId: string, zone: Zone }> = {};
     enemies.forEach(e => {
         const target = alivePlayers[Math.floor(Math.random() * alivePlayers.length)];
         aiCommands[e.id] = { targetId: target.id, zone: 'torso' }; 
     });
     setCommands(aiCommands); 
     setTimeout(() => executePhase(enemies, aiCommands, allCombatants), 1000);
  };

  const handlePlayerCommand = (attackerId: string) => {
      if (!selectedTargetId) return;
      const newCommands = { ...commands, [attackerId]: { targetId: selectedTargetId, zone: selectedZone } };
      setCommands(newCommands);
      const nextQueue = turnQueue.filter(id => id !== attackerId);
      setTurnQueue(nextQueue);
      setSelectedTargetId(null);
      setSelectedZone('torso');
      if (nextQueue.length === 0) executePhase(combatants.filter(c => c.team === 'player'), newCommands, combatants);
  };

  const executePhase = async (
      actingTeam: ActiveCombatant[], 
      activeCommands: Record<string, { targetId: string, zone: Zone }>,
      currentCombatants: ActiveCombatant[]
  ) => {
      setPhase('EXECUTION');
      let workingState = [...currentCombatants]; 

      for (const actor of actingTeam) {
          const freshActor = workingState.find(c => c.id === actor.id);
          if (!freshActor || freshActor.currentHp <= 0) continue;
          const isPlayer = actor.team === 'player';

          // 1. Shock Test
          const shockResult = performShockTest(freshActor);
          if (shockResult.rollData) {
             await visualizeRolls("Shock Test", `Target Number: 15`, [shockResult.rollData], isPlayer);
             if (shockResult.log) addLog(shockResult.log, 'info');
             if (freshActor.currentHp < (freshActor.stats!.maxHp * 0.25)) {
                  workingState = workingState.map(c => c.id === actor.id ? { ...c, isShocked: shockResult.shocked } : c);
             }
             if (shockResult.shocked) {
                addFloatingText(actor.id, "SHOCKED", "miss");
                continue; 
             }
          }

          // 2. Attack Setup
          const cmd = activeCommands[actor.id];
          if (!cmd) continue;
          const target = workingState.find(c => c.id === cmd.targetId);
          if (!target || target.currentHp <= 0) continue;

          // Animation: Lunge
          setAnimatingAttackerId(actor.id);
          await waitForInput(400);

          // Calculate
          const result = resolveAttack(freshActor, target, cmd.zone);

          // --- VISUALIZE: DEFENSE ROLL (TN) ---
          // Always auto for defense, as it's a reaction, or manual if we want player to roll defense?
          // Let's keep consistency: If Target is Player, Player clicks. If Target is Enemy, auto.
          const targetIsPlayer = target.team === 'player';
          await visualizeRolls(`${target.name} Evades`, `Base TN (GES): ${target.stats!.ges}`, [result.defenseRoll], targetIsPlayer);

          // --- VISUALIZE: ATTACK ROLL ---
          await visualizeRolls(`${actor.name} Attacks`, `Target Number: ${result.defenseRoll.total}`, result.attackRolls, isPlayer);

          // Logs
          result.logs.forEach(l => {
              if(l.type !== 'info') addLog(l.text, l.type); // Filter repetitive info
          });

          // --- VISUALIZE: WOUND ROLL (If Hits > 0) ---
          if (result.woundRolls.length > 0) {
              const threshold = 10 - (freshActor.stats!.str - target.stats!.wid);
              await visualizeRolls("Penetration Check", `Threshold: ${threshold}`, result.woundRolls, isPlayer);
          }

          // Apply Impact
          setAnimatingAttackerId(null);
          if (result.damage > 0) {
              setAnimatingTargetId(target.id);
              addFloatingText(target.id, `-${result.damage}`, result.isCrit ? "crit" : "damage");
              workingState = workingState.map(c => c.id === target.id ? { ...c, currentHp: Math.max(0, c.currentHp - result.damage) } : c);
              setCombatants(workingState); 
              await waitForInput(600);
              setAnimatingTargetId(null);
          } else {
              addFloatingText(target.id, "MISS", "miss");
              await waitForInput(500);
          }
      }

      const justActedTeam = actingTeam.length > 0 ? actingTeam[0].team : 'player'; 
      checkWinCondition(workingState, justActedTeam);
  };

  const checkWinCondition = (currentCombs: ActiveCombatant[], lastActiveTeam: 'player' | 'enemy') => {
      const playersAlive = currentCombs.some(c => c.team === 'player' && c.currentHp > 0);
      const enemiesAlive = currentCombs.some(c => c.team === 'enemy' && c.currentHp > 0);

      if (!playersAlive) {
          setPhase('DEFEAT');
          return;
      }
      if (!enemiesAlive) {
          setPhase('VICTORY');
          return;
      }
      if (lastActiveTeam === 'player') startCommandPhase('enemy', currentCombs);
      else startCommandPhase('player', currentCombs);
  };

  const renderCombatant = (c: ActiveCombatant) => {
      const isDead = c.currentHp <= 0;
      const isTurn = turnQueue.includes(c.id);
      const isSelected = selectedTargetId === c.id;
      const maxHp = c.stats?.maxHp || 1;
      const hpPct = (c.currentHp / maxHp) * 100;
      const isAttacking = animatingAttackerId === c.id;
      const isHit = animatingTargetId === c.id;
      const myFloatingTexts = floatingTexts.filter(ft => ft.combatantId === c.id);
      const lungeClass = isAttacking ? (c.team === 'player' ? 'translate-x-12' : '-translate-x-12') : 'translate-x-0';
      const shakeClass = isHit ? 'animate-[shake_0.5s_ease-in-out]' : '';

      return (
          <div 
             key={c.id} 
             onClick={() => {
                 if (phase === 'COMMAND' && turnQueue.length > 0) {
                     const actorId = turnQueue[0];
                     const actor = combatants.find(a => a.id === actorId);
                     if (actor?.team === 'player' && c.team === 'enemy' && !isDead) {
                         setSelectedTargetId(c.id);
                     }
                 }
             }}
             className={`relative w-32 md:w-40 flex flex-col items-center transition-all duration-300 transform ${lungeClass} ${shakeClass}
                ${isDead ? 'opacity-50 grayscale blur-[1px]' : ''}
                ${isTurn ? 'scale-110 drop-shadow-[0_0_15px_rgba(255,255,255,0.4)]' : ''}
                ${isSelected ? 'ring-2 ring-red-500 rounded-xl bg-red-900/20 scale-105' : ''}
                ${!isDead && c.team === 'enemy' && phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(x => x.id === turnQueue[0])?.team === 'player' ? 'cursor-pointer hover:bg-white/5 rounded-xl' : ''}
             `}
          >
              <div className="absolute top-10 left-0 right-0 z-50 pointer-events-none flex flex-col items-center">
                  {myFloatingTexts.map(ft => (
                      <div key={ft.id} className={`text-2xl font-black animate-[floatUp_1s_ease-out_forwards] stroke-black drop-shadow-md ${ft.type === 'damage' ? 'text-red-500' : ''} ${ft.type === 'crit' ? 'text-yellow-400 text-3xl' : ''} ${ft.type === 'miss' ? 'text-gray-400' : ''} ${ft.type === 'heal' ? 'text-green-500' : ''}`}>{ft.text}</div>
                  ))}
              </div>
              <div className="w-full h-3 bg-gray-800 rounded-full mb-2 overflow-hidden border border-gray-600 shadow-inner relative">
                  <div className={`h-full transition-all duration-500 ease-out ${hpPct < 25 ? 'bg-red-600' : (hpPct < 50 ? 'bg-yellow-500' : 'bg-green-500')}`} style={{ width: `${hpPct}%` }} />
                  <div className="absolute inset-0 flex items-center justify-center text-[8px] font-bold text-white drop-shadow-md">{c.currentHp} / {maxHp}</div>
              </div>
              <div className={`w-24 h-24 md:w-32 md:h-32 relative transition-all ${isHit ? 'brightness-150 saturate-0 sepia' : ''}`}>
                  {c.imageSrc || c.mapSpriteSrc ? (
                      <img src={c.imageSrc || c.mapSpriteSrc!} className="w-full h-full object-contain filter drop-shadow-lg" />
                  ) : (
                      <div className="w-full h-full bg-gray-700 rounded-full flex items-center justify-center text-xs text-center p-2 border-2 border-gray-500 shadow-xl">{c.name}</div>
                  )}
                  {c.isShocked && <div className="absolute top-0 right-0 text-yellow-400 bg-black/80 rounded-full p-1 animate-pulse"><Zap size={16}/></div>}
              </div>
              <div className="bg-black/70 px-3 py-1 rounded text-xs mt-1 text-center min-w-[90px] backdrop-blur-sm border border-gray-700/50">
                  <div className="font-bold text-gray-200 truncate max-w-[100px]">{c.name}</div>
              </div>
          </div>
      );
  };

  return (
    <div 
      className="fixed inset-0 z-[100] bg-black text-white flex flex-col font-sans select-none"
      onClick={handleScreenClick} // Global click handler for pacing
    >
       <style>{`
          @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-5px) rotate(-5deg); } 75% { transform: translateX(5px) rotate(5deg); } }
          @keyframes floatUp { 0% { transform: translateY(0) scale(1); opacity: 1; } 100% { transform: translateY(-40px) scale(1.2); opacity: 0; } }
       `}</style>
       <div className="absolute inset-0 z-0 opacity-40">
           {battle.backgroundSrc ? <img src={battle.backgroundSrc} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-red-950/40 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-gray-800 to-black" />}
       </div>

       {/* DICE OVERLAY */}
       {showDice && (
           <div className="absolute inset-0 z-50 flex items-center justify-center pointer-events-none">
               <div className="bg-black/80 backdrop-blur-md p-8 rounded-2xl flex flex-col items-center gap-4 animate-in zoom-in duration-300 border border-white/20 shadow-2xl min-w-[320px]">
                   <div className="text-xl font-bold uppercase tracking-widest text-white drop-shadow-md w-full text-center border-b border-gray-600 pb-2">{diceLabel}</div>
                   {diceSubLabel && <div className="text-sm text-gray-400 -mt-2">{diceSubLabel}</div>}
                   <div className="flex gap-4 flex-wrap justify-center">
                       {activeDice.length === 0 ? (
                           // Pending state (Waiting for click or loading)
                           <div className="flex gap-2">
                             <div className="w-16 h-16 rounded-lg bg-gray-800/50 border-2 border-dashed border-gray-500 flex items-center justify-center text-gray-500 font-bold">?</div>
                           </div>
                       ) : (
                           activeDice.map((d, i) => (
                               <div key={i} className={`w-16 h-16 flex items-center justify-center rounded-lg border-2 text-2xl font-bold shadow-lg animate-in slide-in-from-top-4 ${d.isSuccess ? 'bg-green-900 border-green-500 text-green-100' : 'bg-gray-800 border-gray-600 text-gray-400'} ${d.roll === 20 ? 'animate-bounce border-yellow-400 text-yellow-300 bg-yellow-900/50' : ''}`}>
                                   {d.total}
                                   {d.roll !== d.total && <span className="absolute bottom-1 right-1 text-[8px] opacity-60">raw:{d.roll}</span>}
                               </div>
                           ))
                       )}
                   </div>
                   {waitingForClick && <div className="text-xs text-gray-400 animate-pulse mt-2">[ Click to Continue ]</div>}
                   {!waitingForClick && !autoMode && activeDice.length === 0 && <div className="text-xs text-yellow-400 animate-pulse mt-2">[ Click to Roll ]</div>}
               </div>
           </div>
       )}

       {/* Header */}
       <div className="relative z-10 p-4 flex justify-between items-center bg-gradient-to-b from-black/90 to-transparent">
           <h2 className="text-2xl font-bold flex items-center gap-2 text-red-500 drop-shadow-md"><Sword size={24}/> {battle.name}</h2>
           <div className="flex items-center gap-4">
               <button onClick={(e) => { e.stopPropagation(); setAutoMode(!autoMode); }} className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold border transition-all ${autoMode ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                   {autoMode ? <Play size={14} fill="currentColor"/> : <Pause size={14} fill="currentColor"/>} {autoMode ? 'AUTO' : 'MANUAL'}
               </button>
               <Button onClick={onExit} variant="secondary" className="text-xs py-1 border-red-900 text-red-200 hover:bg-red-900/20">Flee</Button>
           </div>
       </div>

       {/* Battle Area */}
       <div className="relative z-10 flex-1 flex flex-col md:flex-row items-center justify-between px-4 md:px-20 py-4 gap-8 overflow-y-auto">
           <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'player').map(renderCombatant)}</div>
           <div className="flex flex-col items-center justify-center pointer-events-none">
              {phase === 'VICTORY' && <div className="text-center animate-bounce pointer-events-auto bg-black/50 p-6 rounded-xl backdrop-blur-md"><h1 className="text-5xl font-bold text-yellow-400 mb-4">VICTORY</h1><Button onClick={onWin} className="bg-yellow-600 hover:bg-yellow-500 text-xl px-8 py-4">Continue</Button></div>}
              {phase === 'DEFEAT' && <div className="text-center pointer-events-auto bg-black/50 p-6 rounded-xl backdrop-blur-md"><h1 className="text-5xl font-bold text-red-600 mb-4">DEFEAT</h1><Button onClick={onLose} variant="danger" className="text-xl px-8 py-4">Retry</Button></div>}
           </div>
           <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'enemy').map(renderCombatant)}</div>
       </div>

       {/* Bottom Control / Log Panel */}
       <div className="relative z-20 h-[30%] min-h-[220px] bg-black/95 border-t border-gray-800 flex flex-col md:flex-row shadow-[0_-5px_20px_rgba(0,0,0,0.5)]" onClick={(e) => e.stopPropagation()}>
           <div className="flex-1 p-6 border-b md:border-b-0 md:border-r border-gray-800 flex flex-col items-center justify-center gap-4 bg-gray-900/50">
              {phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(c => c.id === turnQueue[0])?.team === 'player' ? (
                  <>
                     <div className="text-lg font-bold text-indigo-300 mb-1 flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse"></div> Command: {combatants.find(c => c.id === turnQueue[0])?.name}</div>
                     {!selectedTargetId ? (
                         <div className="text-gray-400 animate-pulse flex items-center gap-2 bg-gray-800/50 px-4 py-2 rounded-lg border border-dashed border-gray-600"><Target size={16}/> Select an enemy to attack</div>
                     ) : (
                         <div className="flex flex-col gap-3 w-full max-w-sm animate-in fade-in slide-in-from-bottom-4">
                            <div className="text-xs font-bold text-center text-gray-500 uppercase tracking-wide">Target Hit Zone</div>
                            <div className="grid grid-cols-2 gap-2">
                                <Button variant={selectedZone === 'torso' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('torso')} className="text-xs relative">Torso <span className="absolute right-2 text-[10px] opacity-50">0</span></Button>
                                <Button variant={selectedZone === 'head' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('head')} className="text-xs relative">Head <span className="absolute right-2 text-[10px] opacity-50 text-red-300">-6</span></Button>
                                <Button variant={selectedZone === 'arm' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('arm')} className="text-xs relative">Arm <span className="absolute right-2 text-[10px] opacity-50">-4</span></Button>
                                <Button variant={selectedZone === 'leg' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('leg')} className="text-xs relative">Leg <span className="absolute right-2 text-[10px] opacity-50">-3</span></Button>
                            </div>
                            <Button onClick={() => handlePlayerCommand(turnQueue[0])} className="w-full mt-2 bg-red-600 hover:bg-red-500 shadow-red-900/20 py-3 text-sm font-bold tracking-wider"><Sword size={16}/> EXECUTE ATTACK</Button>
                         </div>
                     )}
                  </>
              ) : (
                  <div className="text-gray-500 italic text-sm p-4 text-center flex flex-col items-center gap-2">
                      {phase === 'COMMAND' ? <><Activity className="animate-spin text-gray-600"/> Enemy is planning...</> : (phase === 'EXECUTION' ? "Watching combat..." : "")}
                  </div>
              )}
           </div>
           <div ref={scrollRef} className="flex-[2] p-4 overflow-y-auto font-mono text-xs md:text-sm space-y-1 bg-gray-950">
               {logs.length === 0 && <div className="text-gray-700 italic">Combat Log initialized...</div>}
               {logs.map((log, i) => (
                   <div key={i} className={`py-0.5 border-b border-white/5 ${log.type === 'attack' ? 'text-blue-300' : ''} ${log.type === 'damage' ? 'text-red-400 font-bold' : ''} ${log.type === 'crit' ? 'text-yellow-400 font-bold text-lg' : ''} ${log.type === 'info' ? 'text-gray-500' : ''}`}>
                       <span className="opacity-30 mr-2 text-[10px] w-6 inline-block text-right">[{i+1}]</span>{log.text}
                   </div>
               ))}
           </div>
       </div>
    </div>
  );
};

import { Character, Zone } from "../types";

export interface CombatLog {
  text: string;
  type: 'info' | 'attack' | 'damage' | 'crit' | 'error';
}

export interface ActiveCombatant extends Character {
  currentHp: number;
  isShocked: boolean;
  tempDefenseBonus: number; // From Momentum-Check failure of opponent
  team: 'player' | 'enemy';
}

export interface DetailedRoll {
    roll: number; // The D20 result
    total: number; // Result + Modifiers
    isSuccess?: boolean;
    label?: string;
}

export interface AttackResult {
  damage: number;
  logs: CombatLog[];
  defenderBonusNextTurn: number;

  // Detailed Steps for Visualization
  defenseRoll: DetailedRoll;
  attackRolls: DetailedRoll[];
  woundRolls: DetailedRoll[];

  isCrit: boolean;
  isHeadshot: boolean;
}

// D20 Helper
export const d20 = () => Math.floor(Math.random() * 20) + 1;

// 1. Initiative
export const rollTeamInitiative = (combatants: ActiveCombatant[]): { total: number, roll: number, bestChar: string } => {
  const sorted = [...combatants].sort((a,b) => (b.stats?.ges || 0) - (a.stats?.ges || 0));
  const bestChar = sorted[0];
  const maxDex = bestChar.stats?.ges || 0;
  const roll = d20();
  return { total: maxDex + roll, roll, bestChar: bestChar.name };
};

// Phase 1: Shock Test
export const performShockTest = (c: ActiveCombatant): { shocked: boolean, log: string, rollData?: DetailedRoll } => {
  const maxHp = c.stats?.maxHp || 10;
  const hpThreshold = maxHp * 0.25;

  if (c.currentHp < hpThreshold) {
    const roll = d20();
    const wil = c.stats?.wil || 0;
    const total = roll + wil;
    const threshold = 15;
    const success = total >= threshold;

    const rollData: DetailedRoll = { roll, total, isSuccess: success, label: `Shock Check (TN 15)` };

    if (success) {
      return { shocked: false, log: `${c.name} fights through the pain.`, rollData };
    } else {
      return { shocked: true, log: `${c.name} goes into SHOCK!`, rollData };
    }
  }
  return { shocked: false, log: '' };
};

// Phase 2: Execution Algorithm
export const resolveAttack = (
  attacker: ActiveCombatant, 
  defender: ActiveCombatant, 
  zone: Zone
): AttackResult => {

  const logs: CombatLog[] = [];
  const stats = attacker.stats!;
  const defStats = defender.stats!;
  const weapon = stats.weapon;

  // Zone Mods
  let zoneMalus = 0;
  let isHeadshot = false;

  switch(zone) {
    case 'head': zoneMalus = 6; isHeadshot = true; break;
    case 'arm': zoneMalus = 4; break;
    case 'leg': zoneMalus = 3; break;
    default: zoneMalus = 0; // Torso
  }

  // --- Step 1: Target Number (TN) - Defense Roll ---
  const defRollVal = d20();
  const tn = defRollVal + (defender.isShocked ? 0 : defStats.ges); 
  const defenseRoll: DetailedRoll = { roll: defRollVal, total: tn, label: `Evasion (GES ${defStats.ges})` };

  logs.push({ text: `${defender.name} evades: TN ${tn} (Roll ${defRollVal})`, type: 'info' });

  // --- Step 2: The Salve (Hit Roll) ---
  const diceCount = weapon.at;
  const attackRolls: DetailedRoll[] = [];

  const hits: number[] = [];
  let bestRoll = 0;
  let nat20 = false;

  const shockPenalty = attacker.currentHp < (stats.maxHp * 0.25) && !attacker.isShocked ? 2 : 0; 

  for(let i=0; i < diceCount; i++) {
    const roll = d20();
    if (roll === 20) nat20 = true;

    const total = roll + stats.pra + weapon.mod - zoneMalus - shockPenalty;
    const isHit = total > tn;

    attackRolls.push({ roll, total, isSuccess: isHit });

    if (isHit) {
      hits.push(total);
    }
    if (total > bestRoll) bestRoll = total;
  }

  logs.push({ text: `${attacker.name} attacks: [${attackRolls.map(r => r.total).join(', ')}] vs TN ${tn}`, type: 'attack' });

  // Momentum Check (Counter Advantage)
  let defenderBonusNextTurn = 0;
  if (hits.length === 0 && bestRoll < (tn - 10)) {
    defenderBonusNextTurn = 4;
    logs.push({ text: `Attack missed badly! ${defender.name} gains Counter Advantage.`, type: 'info' });
  }

  if (hits.length === 0) {
    return { 
        damage: 0, logs, defenderBonusNextTurn,
        defenseRoll, attackRolls, woundRolls: [],
        isCrit: false, isHeadshot: false
    };
  }

  // --- Step 3: Wound Roll (Durchschlag) ---
  const threshold = 10 - (stats.str - defStats.wid);
  let confirmedWounds = 0;
  const woundRolls: DetailedRoll[] = [];

  for(let i=0; i < hits.length; i++) {
    const r = d20();
    const isWound = r > threshold;
    woundRolls.push({ roll: r, total: r, isSuccess: isWound, label: `Wound Check (> ${threshold})` });

    if (isWound) {
      confirmedWounds++;
    }
  }

  logs.push({ text: `Wound Rolls (Need > ${threshold}): [${woundRolls.map(r => r.total).join(', ')}]`, type: 'info' });
  logs.push({ text: `${confirmedWounds} Wounds confirmed.`, type: 'info' });

  if (confirmedWounds === 0) {
    logs.push({ text: `Hit but no penetration!`, type: 'info' });
    return { 
        damage: 0, logs, defenderBonusNextTurn,
        defenseRoll, attackRolls, woundRolls,
        isCrit: false, isHeadshot: false
    };
  }

  // --- Step 4: Damage Calculation ---
  let rawDamage = 0;

  for (let i = 0; i < confirmedWounds; i++) {
    let woundDmg = weapon.dmg; 

    // Crit Effect: Headshot +50%
    if (nat20 && isHeadshot) {
      woundDmg = Math.ceil(woundDmg * 1.5);
    }

    // Weapon Cap Check
    if (weapon.cap !== null && woundDmg > weapon.cap) {
      woundDmg = weapon.cap;
    }

    rawDamage += woundDmg;
  }

  // Defender Limit Check
  const finalDamage = Math.min(rawDamage, defStats.limit);

  logs.push({ text: `${attacker.name} deals ${finalDamage} DAMAGE to ${defender.name}!`, type: 'damage' });

  // --- Step 5: Critical Effects ---
  if (nat20) {
    if (zone === 'head') logs.push({ text: `CRITICAL HEADSHOT! ${defender.name} is stunned!`, type: 'crit' }); 
    if (zone === 'arm') logs.push({ text: `CRITICAL HIT TO ARM! Disarmed!`, type: 'crit' });
    if (zone === 'leg') logs.push({ text: `CRITICAL HIT TO LEG! Crippled!`, type: 'crit' });
  }

  return { 
      damage: finalDamage, logs, defenderBonusNextTurn,
      defenseRoll, attackRolls, woundRolls,
      isCrit: nat20, isHeadshot: isHeadshot
  };
};

import React, { useState, useEffect, useRef } from 'react';
import { Battle, Character, Zone } from '../types';
import { ActiveCombatant, rollTeamInitiative, performShockTest, resolveAttack, CombatLog, DetailedRoll } from '../utils/combat';
import { Button } from './ui/Button';
import { Sword, Target, Zap, Dice5, Play, Pause, Activity } from 'lucide-react';

interface BattleArenaProps {
  battle: Battle;
  characters: Character[]; 
  onWin: () => void;
  onLose: () => void;
  onExit: () => void;
}

type BattlePhase = 'INIT' | 'COMMAND' | 'EXECUTION' | 'VICTORY' | 'DEFEAT';

interface FloatingText {
    id: string;
    text: string;
    type: 'damage' | 'heal' | 'miss' | 'crit';
    combatantId: string;
}

export const BattleArena: React.FC<BattleArenaProps> = ({ battle, characters, onWin, onLose, onExit }) => {
  const [phase, setPhase] = useState<BattlePhase>('INIT');
  const [combatants, setCombatants] = useState<ActiveCombatant[]>([]);
  const [turnQueue, setTurnQueue] = useState<string[]>([]); 
  const [logs, setLogs] = useState<CombatLog[]>([]);

  // Settings
  const [autoMode, setAutoMode] = useState(false); 

  // Command State
  const [selectedTargetId, setSelectedTargetId] = useState<string | null>(null);
  const [selectedZone, setSelectedZone] = useState<Zone>('torso');
  const [commands, setCommands] = useState<Record<string, { targetId: string, zone: Zone }>>({});

  // --- Visual States ---
  const [floatingTexts, setFloatingTexts] = useState<FloatingText[]>([]);
  const [animatingAttackerId, setAnimatingAttackerId] = useState<string | null>(null);
  const [animatingTargetId, setAnimatingTargetId] = useState<string | null>(null);

  // DICE VISUALS
  const [activeDice, setActiveDice] = useState<DetailedRoll[]>([]);
  const [showDice, setShowDice] = useState(false);
  const [diceLabel, setDiceLabel] = useState("");
  const [diceSubLabel, setDiceSubLabel] = useState(""); // For small details like "vs TN 15"

  // Control Flow State
  const [waitingForClick, setWaitingForClick] = useState(false);
  const resolveClickRef = useRef<(() => void) | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);

  const addFloatingText = (combatantId: string, text: string, type: FloatingText['type']) => {
      const id = crypto.randomUUID();
      setFloatingTexts(prev => [...prev, { id, text, type, combatantId }]);
      setTimeout(() => setFloatingTexts(prev => prev.filter(ft => ft.id !== id)), 1500);
  };

  const addLog = (text: string, type: CombatLog['type']) => {
    setLogs(prev => [...prev, { text, type }]);
  };

  // --- WAIT LOGIC ---
  const waitForInput = async (autoDelayMs: number = 800) => {
      if (autoMode) {
          return new Promise<void>(resolve => setTimeout(resolve, autoDelayMs));
      } else {
          setWaitingForClick(true);
          return new Promise<void>(resolve => {
              resolveClickRef.current = resolve;
          });
      }
  };

  const handleScreenClick = () => {
      if (waitingForClick && resolveClickRef.current) {
          setWaitingForClick(false);
          const resolver = resolveClickRef.current;
          resolveClickRef.current = null;
          resolver();
      }
  };

  // --- DICE ANIMATION HELPER ---
  const visualizeRolls = async (
      label: string, 
      subLabel: string, 
      rolls: DetailedRoll[], 
      isManualTrigger: boolean // If true, player must click to START the roll
  ) => {
      setDiceLabel(label);
      setDiceSubLabel(subLabel);
      setActiveDice([]); 
      setShowDice(true);

      // 1. Wait for Start (if Manual)
      if (isManualTrigger && !autoMode) {
          setDiceLabel(`Ready to ${label}`);
          await waitForInput(0); // Infinite wait until click
      }

      setDiceLabel(label); // Restore label

      // 2. Animate "Rolling" (Fake numbers)
      const duration = 600;
      const interval = 50;
      const steps = duration / interval;

      for(let i=0; i<steps; i++) {
          const fakeRolls = rolls.map(() => ({ roll: Math.floor(Math.random()*20)+1, total: 0 }));
          setActiveDice(fakeRolls);
          await new Promise(r => setTimeout(r, interval));
      }

      // 3. Show Final Result
      setActiveDice(rolls);

      // 4. Wait for Acknowledgement
      await waitForInput(1500);

      setShowDice(false);
  };

  // Initialize Combat
  useEffect(() => {
    let mounted = true;

    const init = async () => {
      const parts: ActiveCombatant[] = [];
      // Hydrate characters from IDs
      [...battle.playerCharacterIds, ...battle.enemyCharacterIds].forEach(id => {
          const c = characters.find(char => char.id === id);
          if (c) {
              const team = battle.playerCharacterIds.includes(id) ? 'player' : 'enemy';
              parts.push({
                  ...c,
                  currentHp: c.stats?.hp || 20,
                  isShocked: false,
                  tempDefenseBonus: 0,
                  team,
                  stats: c.stats || { pra: 3, str: 3, wid: 3, ges: 3, wil: 3, hp: 20, maxHp: 20, limit: 10, weapon: { name: 'Hands', at: 3, mod: 0, dmg: 1, cap: null } }
              });
          }
      });

      if (!mounted) return;
      setCombatants(parts);

      // --- VISUAL: INITIATIVE ---
      const playerTeam = parts.filter(c => c.team === 'player');
      const enemyTeam = parts.filter(c => c.team === 'enemy');

      const pInit = rollTeamInitiative(playerTeam);
      const eInit = rollTeamInitiative(enemyTeam);

      // Determine who rolls visually based on which side contains the player (usually always player side)
      // We'll show both rolls sequentially

      await visualizeRolls("Player Initiative", `Best DEX: ${pInit.total - pInit.roll}`, [{ roll: pInit.roll, total: pInit.total }], true);
      await visualizeRolls("Enemy Initiative", `Best DEX: ${eInit.total - eInit.roll}`, [{ roll: eInit.roll, total: eInit.total }], false);

      addLog(`Initiative: Player ${pInit.total} vs Enemy ${eInit.total}`, 'info');

      if (pInit.total >= eInit.total) {
          startCommandPhase('player', parts);
      } else {
          startCommandPhase('enemy', parts);
      }
    };

    init();
    return () => { mounted = false; };
  }, [battle]);

  // Scroll to bottom of logs
  useEffect(() => {
      if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [logs]);

  const startCommandPhase = (activeTeam: 'player' | 'enemy', currentCombatants: ActiveCombatant[]) => {
      setPhase('COMMAND');
      const teamMembers = currentCombatants.filter(c => c.team === activeTeam && c.currentHp > 0);
      setTurnQueue(teamMembers.map(c => c.id));
      setCommands({}); 

      if (activeTeam === 'enemy') {
          setTimeout(() => runEnemyAI(teamMembers, currentCombatants), 500);
      }
  };

  const runEnemyAI = (enemies: ActiveCombatant[], allCombatants: ActiveCombatant[]) => {
     const alivePlayers = allCombatants.filter(c => c.team === 'player' && c.currentHp > 0);
     if (alivePlayers.length === 0) {
         executePhase(enemies, {}, allCombatants);
         return;
     }
     const aiCommands: Record<string, { targetId: string, zone: Zone }> = {};
     enemies.forEach(e => {
         const target = alivePlayers[Math.floor(Math.random() * alivePlayers.length)];
         aiCommands[e.id] = { targetId: target.id, zone: 'torso' }; 
     });
     setCommands(aiCommands); 
     setTimeout(() => executePhase(enemies, aiCommands, allCombatants), 1000);
  };

  const handlePlayerCommand = (attackerId: string) => {
      if (!selectedTargetId) return;
      const newCommands = { ...commands, [attackerId]: { targetId: selectedTargetId, zone: selectedZone } };
      setCommands(newCommands);
      const nextQueue = turnQueue.filter(id => id !== attackerId);
      setTurnQueue(nextQueue);
      setSelectedTargetId(null);
      setSelectedZone('torso');
      if (nextQueue.length === 0) executePhase(combatants.filter(c => c.team === 'player'), newCommands, combatants);
  };

  const executePhase = async (
      actingTeam: ActiveCombatant[], 
      activeCommands: Record<string, { targetId: string, zone: Zone }>,
      currentCombatants: ActiveCombatant[]
  ) => {
      setPhase('EXECUTION');
      let workingState = [...currentCombatants]; 

      for (const actor of actingTeam) {
          const freshActor = workingState.find(c => c.id === actor.id);
          if (!freshActor || freshActor.currentHp <= 0) continue;
          const isPlayer = actor.team === 'player';

          // 1. Shock Test
          const shockResult = performShockTest(freshActor);
          if (shockResult.rollData) {
             await visualizeRolls("Shock Test", `Target Number: 15`, [shockResult.rollData], isPlayer);
             if (shockResult.log) addLog(shockResult.log, 'info');
             if (freshActor.currentHp < (freshActor.stats!.maxHp * 0.25)) {
                  workingState = workingState.map(c => c.id === actor.id ? { ...c, isShocked: shockResult.shocked } : c);
             }
             if (shockResult.shocked) {
                addFloatingText(actor.id, "SHOCKED", "miss");
                continue; 
             }
          }

          // 2. Attack Setup
          const cmd = activeCommands[actor.id];
          if (!cmd) continue;
          const target = workingState.find(c => c.id === cmd.targetId);
          if (!target || target.currentHp <= 0) continue;

          // Animation: Lunge
          setAnimatingAttackerId(actor.id);
          await waitForInput(400);

          // Calculate
          const result = resolveAttack(freshActor, target, cmd.zone);

          // --- VISUALIZE: DEFENSE ROLL (TN) ---
          // Always auto for defense, as it's a reaction, or manual if we want player to roll defense?
          // Let's keep consistency: If Target is Player, Player clicks. If Target is Enemy, auto.
          const targetIsPlayer = target.team === 'player';
          await visualizeRolls(`${target.name} Evades`, `Base TN (GES): ${target.stats!.ges}`, [result.defenseRoll], targetIsPlayer);

          // --- VISUALIZE: ATTACK ROLL ---
          await visualizeRolls(`${actor.name} Attacks`, `Target Number: ${result.defenseRoll.total}`, result.attackRolls, isPlayer);

          // Logs
          result.logs.forEach(l => {
              addLog(l.text, l.type); 
          });

          // --- VISUALIZE: WOUND ROLL (If Hits > 0) ---
          if (result.woundRolls.length > 0) {
              const threshold = 10 - (freshActor.stats!.str - target.stats!.wid);
              await visualizeRolls("Penetration Check", `Threshold: ${threshold}`, result.woundRolls, isPlayer);
          }

          // Apply Impact
          setAnimatingAttackerId(null);
          if (result.damage > 0) {
              setAnimatingTargetId(target.id);
              addFloatingText(target.id, `-${result.damage}`, result.isCrit ? "crit" : "damage");
              workingState = workingState.map(c => c.id === target.id ? { ...c, currentHp: Math.max(0, c.currentHp - result.damage) } : c);
              setCombatants(workingState); 
              await waitForInput(600);
              setAnimatingTargetId(null);
          } else {
              addFloatingText(target.id, "MISS", "miss");
              await waitForInput(500);
          }
      }

      const justActedTeam = actingTeam.length > 0 ? actingTeam[0].team : 'player'; 
      checkWinCondition(workingState, justActedTeam);
  };

  const checkWinCondition = (currentCombs: ActiveCombatant[], lastActiveTeam: 'player' | 'enemy') => {
      const playersAlive = currentCombs.some(c => c.team === 'player' && c.currentHp > 0);
      const enemiesAlive = currentCombs.some(c => c.team === 'enemy' && c.currentHp > 0);

      if (!playersAlive) {
          setPhase('DEFEAT');
          return;
      }
      if (!enemiesAlive) {
          setPhase('VICTORY');
          return;
      }
      if (lastActiveTeam === 'player') startCommandPhase('enemy', currentCombs);
      else startCommandPhase('player', currentCombs);
  };

  const renderCombatant = (c: ActiveCombatant) => {
      const isDead = c.currentHp <= 0;
      const isTurn = turnQueue.includes(c.id);
      const isSelected = selectedTargetId === c.id;
      const maxHp = c.stats?.maxHp || 1;
      const hpPct = (c.currentHp / maxHp) * 100;
      const isAttacking = animatingAttackerId === c.id;
      const isHit = animatingTargetId === c.id;
      const myFloatingTexts = floatingTexts.filter(ft => ft.combatantId === c.id);
      const lungeClass = isAttacking ? (c.team === 'player' ? 'translate-x-12' : '-translate-x-12') : 'translate-x-0';
      const shakeClass = isHit ? 'animate-[shake_0.5s_ease-in-out]' : '';

      return (
          <div 
             key={c.id} 
             onClick={() => {
                 if (phase === 'COMMAND' && turnQueue.length > 0) {
                     const actorId = turnQueue[0];
                     const actor = combatants.find(a => a.id === actorId);
                     if (actor?.team === 'player' && c.team === 'enemy' && !isDead) {
                         setSelectedTargetId(c.id);
                     }
                 }
             }}
             className={`relative w-32 md:w-40 flex flex-col items-center transition-all duration-300 transform ${lungeClass} ${shakeClass}
                ${isDead ? 'opacity-50 grayscale blur-[1px]' : ''}
                ${isTurn ? 'scale-110 drop-shadow-[0_0_15px_rgba(255,255,255,0.4)]' : ''}
                ${isSelected ? 'ring-2 ring-red-500 rounded-xl bg-red-900/20 scale-105' : ''}
                ${!isDead && c.team === 'enemy' && phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(x => x.id === turnQueue[0])?.team === 'player' ? 'cursor-pointer hover:bg-white/5 rounded-xl' : ''}
             `}
          >
              <div className="absolute top-10 left-0 right-0 z-50 pointer-events-none flex flex-col items-center">
                  {myFloatingTexts.map(ft => (
                      <div key={ft.id} className={`text-2xl font-black animate-[floatUp_1s_ease-out_forwards] stroke-black drop-shadow-md ${ft.type === 'damage' ? 'text-red-500' : ''} ${ft.type === 'crit' ? 'text-yellow-400 text-3xl' : ''} ${ft.type === 'miss' ? 'text-gray-400' : ''} ${ft.type === 'heal' ? 'text-green-500' : ''}`}>{ft.text}</div>
                  ))}
              </div>
              <div className="w-full h-3 bg-gray-800 rounded-full mb-2 overflow-hidden border border-gray-600 shadow-inner relative">
                  <div className={`h-full transition-all duration-500 ease-out ${hpPct < 25 ? 'bg-red-600' : (hpPct < 50 ? 'bg-yellow-500' : 'bg-green-500')}`} style={{ width: `${hpPct}%` }} />
                  <div className="absolute inset-0 flex items-center justify-center text-[8px] font-bold text-white drop-shadow-md">{c.currentHp} / {maxHp}</div>
              </div>
              <div className={`w-24 h-24 md:w-32 md:h-32 relative transition-all ${isHit ? 'brightness-150 saturate-0 sepia' : ''}`}>
                  {c.imageSrc || c.mapSpriteSrc ? (
                      <img src={c.imageSrc || c.mapSpriteSrc!} className="w-full h-full object-contain filter drop-shadow-lg" />
                  ) : (
                      <div className="w-full h-full bg-gray-700 rounded-full flex items-center justify-center text-xs text-center p-2 border-2 border-gray-500 shadow-xl">{c.name}</div>
                  )}
                  {c.isShocked && <div className="absolute top-0 right-0 text-yellow-400 bg-black/80 rounded-full p-1 animate-pulse"><Zap size={16}/></div>}
              </div>
              <div className="bg-black/70 px-3 py-1 rounded text-xs mt-1 text-center min-w-[90px] backdrop-blur-sm border border-gray-700/50">
                  <div className="font-bold text-gray-200 truncate max-w-[100px]">{c.name}</div>
              </div>
          </div>
      );
  };

  return (
    <div 
      className="fixed inset-0 z-[100] bg-black text-white flex flex-col font-sans select-none"
      onClick={handleScreenClick} // Global click handler for pacing
    >
       <style>{`
          @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-5px) rotate(-5deg); } 75% { transform: translateX(5px) rotate(5deg); } }
          @keyframes floatUp { 0% { transform: translateY(0) scale(1); opacity: 1; } 100% { transform: translateY(-40px) scale(1.2); opacity: 0; } }
       `}</style>
       <div className="absolute inset-0 z-0 opacity-40">
           {battle.backgroundSrc ? <img src={battle.backgroundSrc} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-red-950/40 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-gray-800 to-black" />}
       </div>

       {/* DICE OVERLAY */}
       {showDice && (
           <div className="absolute inset-0 z-50 flex items-center justify-center pointer-events-none">
               <div className="bg-black/80 backdrop-blur-md p-8 rounded-2xl flex flex-col items-center gap-4 animate-in zoom-in duration-300 border border-white/20 shadow-2xl min-w-[320px]">
                   <div className="text-xl font-bold uppercase tracking-widest text-white drop-shadow-md w-full text-center border-b border-gray-600 pb-2">{diceLabel}</div>
                   {diceSubLabel && <div className="text-sm text-gray-400 -mt-2">{diceSubLabel}</div>}
                   <div className="flex gap-4 flex-wrap justify-center">
                       {activeDice.length === 0 ? (
                           // Pending state (Waiting for click or loading)
                           <div className="flex gap-2">
                             <div className="w-16 h-16 rounded-lg bg-gray-800/50 border-2 border-dashed border-gray-500 flex items-center justify-center text-gray-500 font-bold">?</div>
                           </div>
                       ) : (
                           activeDice.map((d, i) => (
                               <div key={i} className={`w-16 h-16 flex items-center justify-center rounded-lg border-2 text-2xl font-bold shadow-lg animate-in slide-in-from-top-4 ${d.isSuccess ? 'bg-green-900 border-green-500 text-green-100' : 'bg-gray-800 border-gray-600 text-gray-400'} ${d.roll === 20 ? 'animate-bounce border-yellow-400 text-yellow-300 bg-yellow-900/50' : ''}`}>
                                   {d.total}
                                   {d.roll !== d.total && <span className="absolute bottom-1 right-1 text-[8px] opacity-60">raw:{d.roll}</span>}
                               </div>
                           ))
                       )}
                   </div>
                   {waitingForClick && <div className="text-xs text-gray-400 animate-pulse mt-2">[ Click to Continue ]</div>}
                   {!waitingForClick && !autoMode && activeDice.length === 0 && <div className="text-xs text-yellow-400 animate-pulse mt-2">[ Click to Roll ]</div>}
               </div>
           </div>
       )}

       {/* Header */}
       <div className="relative z-10 p-4 flex justify-between items-center bg-gradient-to-b from-black/90 to-transparent">
           <h2 className="text-2xl font-bold flex items-center gap-2 text-red-500 drop-shadow-md"><Sword size={24}/> {battle.name}</h2>
           <div className="flex items-center gap-4">
               <button onClick={(e) => { e.stopPropagation(); setAutoMode(!autoMode); }} className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold border transition-all ${autoMode ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                   {autoMode ? <Play size={14} fill="currentColor"/> : <Pause size={14} fill="currentColor"/>} {autoMode ? 'AUTO' : 'MANUAL'}
               </button>
               <Button onClick={onExit} variant="secondary" className="text-xs py-1 border-red-900 text-red-200 hover:bg-red-900/20">Flee</Button>
           </div>
       </div>

       {/* Battle Area */}
       <div className="relative z-10 flex-1 flex flex-col md:flex-row items-center justify-between px-4 md:px-20 py-4 gap-8 overflow-y-auto">
           <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'player').map(renderCombatant)}</div>
           <div className="flex flex-col items-center justify-center pointer-events-none">
              {phase === 'VICTORY' && <div className="text-center animate-bounce pointer-events-auto bg-black/50 p-6 rounded-xl backdrop-blur-md"><h1 className="text-5xl font-bold text-yellow-400 mb-4">VICTORY</h1><Button onClick={onWin} className="bg-yellow-600 hover:bg-yellow-500 text-xl px-8 py-4">Continue</Button></div>}
              {phase === 'DEFEAT' && <div className="text-center pointer-events-auto bg-black/50 p-6 rounded-xl backdrop-blur-md"><h1 className="text-5xl font-bold text-red-600 mb-4">DEFEAT</h1><Button onClick={onLose} variant="danger" className="text-xl px-8 py-4">Retry</Button></div>}
           </div>
           <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'enemy').map(renderCombatant)}</div>
       </div>

       {/* Bottom Control / Log Panel */}
       <div className="relative z-20 h-[30%] min-h-[220px] bg-black/95 border-t border-gray-800 flex flex-col md:flex-row shadow-[0_-5px_20px_rgba(0,0,0,0.5)]" onClick={(e) => e.stopPropagation()}>
           <div className="flex-1 p-6 border-b md:border-b-0 md:border-r border-gray-800 flex flex-col items-center justify-center gap-4 bg-gray-900/50">
              {phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(c => c.id === turnQueue[0])?.team === 'player' ? (
                  <>
                     <div className="text-lg font-bold text-indigo-300 mb-1 flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse"></div> Command: {combatants.find(c => c.id === turnQueue[0])?.name}</div>
                     {!selectedTargetId ? (
                         <div className="text-gray-400 animate-pulse flex items-center gap-2 bg-gray-800/50 px-4 py-2 rounded-lg border border-dashed border-gray-600"><Target size={16}/> Select an enemy to attack</div>
                     ) : (
                         <div className="flex flex-col gap-3 w-full max-w-sm animate-in fade-in slide-in-from-bottom-4">
                            <div className="text-xs font-bold text-center text-gray-500 uppercase tracking-wide">Target Hit Zone</div>
                            <div className="grid grid-cols-2 gap-2">
                                <Button variant={selectedZone === 'torso' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('torso')} className="text-xs relative">Torso <span className="absolute right-2 text-[10px] opacity-50">0</span></Button>
                                <Button variant={selectedZone === 'head' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('head')} className="text-xs relative">Head <span className="absolute right-2 text-[10px] opacity-50 text-red-300">-6</span></Button>
                                <Button variant={selectedZone === 'arm' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('arm')} className="text-xs relative">Arm <span className="absolute right-2 text-[10px] opacity-50">-4</span></Button>
                                <Button variant={selectedZone === 'leg' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('leg')} className="text-xs relative">Leg <span className="absolute right-2 text-[10px] opacity-50">-3</span></Button>
                            </div>
                            <Button onClick={() => handlePlayerCommand(turnQueue[0])} className="w-full mt-2 bg-red-600 hover:bg-red-500 shadow-red-900/20 py-3 text-sm font-bold tracking-wider"><Sword size={16}/> EXECUTE ATTACK</Button>
                         </div>
                     )}
                  </>
              ) : (
                  <div className="text-gray-500 italic text-sm p-4 text-center flex flex-col items-center gap-2">
                      {phase === 'COMMAND' ? <><Activity className="animate-spin text-gray-600"/> Enemy is planning...</> : (phase === 'EXECUTION' ? "Watching combat..." : "")}
                  </div>
              )}
           </div>
           <div ref={scrollRef} className="flex-[2] p-4 overflow-y-auto font-mono text-xs md:text-sm space-y-1 bg-gray-950">
               {logs.length === 0 && <div className="text-gray-700 italic">Combat Log initialized...</div>}
               {logs.map((log, i) => (
                   <div key={i} className={`py-0.5 border-b border-white/5 ${log.type === 'attack' ? 'text-blue-300' : ''} ${log.type === 'damage' ? 'text-red-400 font-bold' : ''} ${log.type === 'crit' ? 'text-yellow-400 font-bold text-lg' : ''} ${log.type === 'info' ? 'text-gray-500' : ''}`}>
                       <span className="opacity-30 mr-2 text-[10px] w-6 inline-block text-right">[{i+1}]</span>{log.text}
                   </div>
               ))}
           </div>
       </div>
    </div>
  );
};

export type Zone = 'torso' | 'head' | 'arm' | 'leg';

export interface Weapon {
  name: string;
  at: number; // Angriffs-Tempo (Würfel-Pool)
  mod: number; // Modifikator (Präzision)
  dmg: number; // Schaden pro Wunde (Flat für V1, später Dice möglich)
  cap: number | null; // Max Schaden pro Treffer (null = unbegrenzt)
}

export interface CombatStats {
  // Attributes
  pra: number; // Präzision
  str: number; // Stärke
  wid: number; // Widerstand
  ges: number; // Geschick
  wil: number; // Willenskraft

  // Vitals
  hp: number;
  maxHp: number;
  limit: number; // Verwundungs-Limit (Körpermasse/Rüstung)

  // Equipment
  weapon: Weapon;
}

export interface Character {
  id: string;
  name: string;
  defaultDescription: string;

  // Standard Images
  imageSrc: string | null; // Portrait for VN (Large)
  mapSpriteSrc: string | null; // Sprite for Map (Small/Icon)

  // Battle Images
  battleIdleSrc?: string | null; // Standing still in battle
  battlePrepSrc?: string | null; // Winding up / Casting / Running forward
  battleHitSrc?: string | null;  // The moment of impact / Release

  rpgColor: string; // Fallback Hex color for Map dots

  // New visual settings for Chat
  bubbleColor?: string; // Hex color for the chat bubble background
  isItalic?: boolean; // If true, text renders in italics (good for narrators/thoughts)

  // RPG Combat Stats
  stats?: CombatStats;
}

export interface SceneCharacterConfig {
  characterId: string;
  roleInScene: string; // Specific behavior/goal for this scene
}

export interface SceneEffect {
  type: 'scene' | 'transition' | 'battle'; // Added battle
  targetId: string; // Scene ID, Target Map ID, or Battle ID
  action: 'unlock' | 'lock'; 
}

export interface Battle {
  id: string;
  name: string;
  backgroundSrc: string | null;
  playerCharacterIds: string[]; // Who fights from the player side?
  enemyCharacterIds: string[]; // Who are the enemies?
  isRepeatable: boolean;
  onWinEffect?: SceneEffect[]; // Unlock something on win
}

export interface Scene {
  id: string;
  name: string;

  locationName?: string; 
  backgroundSrc: string | null; 
  description: string; 
  aiInstructions?: string; 
  sensoryDetails?: string; 
  environmentDetails?: string;

  goal: string; 
  characters: SceneCharacterConfig[];
  effects?: SceneEffect[]; 

  mapIconSrc?: string | null; 
  isRepeatable?: boolean;
}

export interface MapSpot {
  id: string;
  x: number; 
  y: number; 
  type: 'scene' | 'transition' | 'character' | 'battle'; // Added battle

  sceneId?: string; 
  characterId?: string; 
  targetMapId?: string;
  battleId?: string; // New
}

export interface WorldMap {
  id: string;
  name: string;
  backgroundSrc: string | null;
  spots: MapSpot[];
}

export interface ChatMessage {
  sender: 'user' | 'model' | 'system';
  characterId?: string; 
  text: string;
  timestamp: number;
}

export interface GameState {
  currentSceneIndex: number; 
  history: ChatMessage[];
  isProcessing: boolean;
  gameOver: boolean;
}

export interface AIResponse {
  characterResponses: {
    characterId: string;
    text: string;
  }[];
  sceneGoalReached: boolean;
  sceneTransitionReason?: string;
}

export interface RPGState {
  currentMapId: string;
  completedSceneIds: string[];
  completedBattleIds: string[]; // New
  unlockedIds: string[]; 
  hiddenIds: string[]; 
  ongoingScenes: Record<string, ChatMessage[]>; 
}

export interface GameSaveData {
  rpgState: RPGState;
  vnState: GameState | null; 
  timestamp: number;
}

import React, { useState, useRef } from 'react';
import { Plus, Trash2, Image as ImageIcon, User, Target, Save, PlayCircle, RotateCcw, Map as MapIcon, MousePointerClick, FileUp, Download, Upload, Check, Waypoints, Globe, Lock, Unlock, MessageSquare, Ban, RefreshCcw, Eye, EyeOff, Italic, Palette, Ear, Wind, Layout, Sword, Shield, Skull, Zap, Crosshair } from 'lucide-react';
import { Character, Scene, SceneCharacterConfig, WorldMap, MapSpot, SceneEffect, Battle, CombatStats, Weapon } from '../types';
import { Button } from './ui/Button';

interface EditorProps {
  characters: Character[];
  scenes: Scene[];
  maps: WorldMap[];
  battles?: Battle[]; // New
  onUpdateCharacters: (chars: Character[]) => void;
  onUpdateScenes: (scenes: Scene[]) => void;
  onUpdateMaps: (maps: WorldMap[]) => void;
  onUpdateBattles?: (battles: Battle[]) => void; // New
  onPlay: () => void;
  onQuickSave: () => Promise<boolean>;
  onExportProject: () => void;
  onImportProject: (file: File) => void;
  hasSaveGame: boolean;
  onContinueGame: () => void;
}

// Default Stats for new chars
const DEFAULT_STATS: CombatStats = {
  pra: 3, str: 3, wid: 3, ges: 3, wil: 3,
  hp: 20, maxHp: 20, limit: 10,
  weapon: { name: 'Basic Weapon', at: 3, mod: 0, dmg: 1, cap: null }
};

export const Editor: React.FC<EditorProps> = ({
  characters,
  scenes,
  maps,
  battles = [],
  onUpdateCharacters,
  onUpdateScenes,
  onUpdateMaps,
  onUpdateBattles = (_: Battle[]) => {},
  onPlay,
  onQuickSave,
  onExportProject,
  onImportProject,
  hasSaveGame,
  onContinueGame
}) => {
  const [activeTab, setActiveTab] = useState<'chars' | 'scenes' | 'battles' | 'map'>('chars');

  // Map Editor State
  const [activeMapId, setActiveMapId] = useState<string>(maps[0]?.id || '');
  const [selectedTool, setSelectedTool] = useState<{type: 'scene'|'transition'|'character'|'battle', id: string} | null>(null);

  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const importInputRef = useRef<HTMLInputElement>(null);

  // --- Character Handlers ---
  const addCharacter = () => {
    const newChar: Character = {
      id: crypto.randomUUID(),
      name: 'New Character',
      defaultDescription: 'A friendly helper.',
      imageSrc: null,
      mapSpriteSrc: null,
      battleIdleSrc: null,
      battlePrepSrc: null,
      battleHitSrc: null,
      rpgColor: '#ef4444',
      bubbleColor: '#4b5563', 
      isItalic: false,
      stats: { ...DEFAULT_STATS }
    };
    onUpdateCharacters([...characters, newChar]);
  };

  const updateCharacter = (id: string, updates: Partial<Character>) => {
    onUpdateCharacters(characters.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const updateCharStats = (id: string, statUpdates: Partial<CombatStats>) => {
      onUpdateCharacters(characters.map(c => {
          if (c.id !== id) return c;
          return {
              ...c,
              stats: { ...(c.stats || DEFAULT_STATS), ...statUpdates }
          };
      }));
  };

  const updateCharWeapon = (id: string, weaponUpdates: Partial<Weapon>) => {
      onUpdateCharacters(characters.map(c => {
          if (c.id !== id) return c;
          const currentStats = c.stats || DEFAULT_STATS;
          return {
              ...c,
              stats: { 
                  ...currentStats, 
                  weapon: { ...currentStats.weapon, ...weaponUpdates }
              }
          };
      }));
  };

  const handleCharImageUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>, field: 'imageSrc' | 'mapSpriteSrc' | 'battleIdleSrc' | 'battlePrepSrc' | 'battleHitSrc') => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCharacter(id, { [field]: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  // --- Battle Handlers ---
  const addBattle = () => {
      const newBattle: Battle = {
          id: crypto.randomUUID(),
          name: `Battle ${battles.length + 1}`,
          backgroundSrc: null,
          playerCharacterIds: [],
          enemyCharacterIds: [],
          isRepeatable: false,
          onWinEffect: []
      };
      onUpdateBattles([...battles, newBattle]);
  };

  const updateBattle = (id: string, updates: Partial<Battle>) => {
      onUpdateBattles(battles.map(b => b.id === id ? { ...b, ...updates } : b));
  };

  const handleBattleBgUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateBattle(id, { backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleCharInBattle = (battleId: string, charId: string, side: 'player' | 'enemy') => {
      const battle = battles.find(b => b.id === battleId);
      if (!battle) return;

      const listKey = side === 'player' ? 'playerCharacterIds' : 'enemyCharacterIds';
      const list = battle[listKey];

      if (list.includes(charId)) {
          updateBattle(battleId, { [listKey]: list.filter(id => id !== charId) });
      } else {
          updateBattle(battleId, { [listKey]: [...list, charId] });
      }
  };

  // --- Scene Handlers ---
  const addScene = () => {
    const newScene: Scene = {
      id: crypto.randomUUID(),
      name: `Scene ${scenes.length + 1}`,
      locationName: 'Unknown Location',
      backgroundSrc: null,
      description: 'You are in a quiet room.',
      aiInstructions: '',
      sensoryDetails: '',
      environmentDetails: '',
      goal: 'Say hello.',
      characters: [],
      effects: [],
      mapIconSrc: null,
      isRepeatable: false
    };
    onUpdateScenes([...scenes, newScene]);
  };

  const updateScene = (id: string, updates: Partial<Scene>) => {
    onUpdateScenes(scenes.map(s => s.id === id ? { ...s, ...updates } : s));
  };

  const handleSceneIconUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { mapIconSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleEffect = (sceneId: string, type: 'scene' | 'transition' | 'battle', targetId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const currentEffects = scene.effects || [];
    const existingEffect = currentEffects.find(u => u.type === type && u.targetId === targetId);

    let newEffects: SceneEffect[];

    if (!existingEffect) {
        newEffects = [...currentEffects, { type, targetId, action: 'unlock' }];
    } else if (existingEffect.action === 'unlock' || !existingEffect.action) {
        newEffects = currentEffects.map(eff => 
            (eff.type === type && eff.targetId === targetId) ? { ...eff, action: 'lock' } : eff
        );
    } else {
        newEffects = currentEffects.filter(u => !(u.type === type && u.targetId === targetId));
    }

    updateScene(sceneId, { effects: newEffects });
  };

  const handleBgUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleCharInScene = (sceneId: string, charId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const exists = scene.characters.find(c => c.characterId === charId);
    let newChars: SceneCharacterConfig[];

    if (exists) {
      newChars = scene.characters.filter(c => c.characterId !== charId);
    } else {
      newChars = [...scene.characters, { characterId: charId, roleInScene: 'Default behavior' }];
    }
    updateScene(sceneId, { characters: newChars });
  };

  const updateSceneCharRole = (sceneId: string, charId: string, role: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;
    const newChars = scene.characters.map(c => c.characterId === charId ? { ...c, roleInScene: role } : c);
    updateScene(sceneId, { characters: newChars });
  };

  // --- Map Handlers ---

  const getCurrentMap = () => maps.find(m => m.id === activeMapId);

  const addMap = () => {
      const newMap: WorldMap = {
          id: crypto.randomUUID(),
          name: `Map ${maps.length + 1}`,
          backgroundSrc: null,
          spots: []
      };
      const newMaps = [...maps, newMap];
      onUpdateMaps(newMaps);
      setActiveMapId(newMap.id);
  };

  const deleteMap = (id: string) => {
      if (maps.length <= 1) {
          alert("You must have at least one map.");
          return;
      }
      const newMaps = maps.filter(m => m.id !== id);
      onUpdateMaps(newMaps);
      if (activeMapId === id) setActiveMapId(newMaps[0].id);
  };

  const updateCurrentMap = (updates: Partial<WorldMap>) => {
      onUpdateMaps(maps.map(m => m.id === activeMapId ? { ...m, ...updates } : m));
  };

  const handleMapBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCurrentMap({ backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const handleMapClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!selectedTool || !mapContainerRef.current) return;
    if ((e.target as HTMLElement).closest('.map-pin')) return;

    const rect = mapContainerRef.current.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;

    const currentMap = getCurrentMap();
    if (!currentMap) return;

    const newSpot: MapSpot = {
      id: crypto.randomUUID(),
      type: selectedTool.type,
      x, 
      y,
      sceneId: selectedTool.type === 'scene' ? selectedTool.id : undefined,
      targetMapId: selectedTool.type === 'transition' ? selectedTool.id : undefined,
      characterId: selectedTool.type === 'character' ? selectedTool.id : undefined,
      battleId: selectedTool.type === 'battle' ? selectedTool.id : undefined
    };

    updateCurrentMap({ spots: [...currentMap.spots, newSpot] });
  };

  const removeSpot = (spotId: string) => {
    const currentMap = getCurrentMap();
    if(!currentMap) return;
    updateCurrentMap({
      spots: currentMap.spots.filter(s => s.id !== spotId)
    });
  };

  // --- Toolbar Handlers ---

  const handleQuickSaveClick = async () => {
    setSaveStatus('saving');
    await onQuickSave();
    setSaveStatus('saved');
    setTimeout(() => setSaveStatus('idle'), 2000);
  };

  const handleImportClick = () => {
    importInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if(e.target.files && e.target.files[0]) {
        onImportProject(e.target.files[0]);
    }
    if(e.target.value) e.target.value = ''; 
  };

  const currentMap = getCurrentMap();

  return (
    <div className="flex flex-col h-full max-w-6xl mx-auto p-4 md:p-8">
      {/* Header / Toolbar */}
      <div className="flex flex-col xl:flex-row justify-between items-center mb-8 gap-6">
        <div>
           <h1 className="text-3xl font-bold text-indigo-400">VN Creator Studio</h1>
           <p className="text-gray-400 text-sm mt-1">Design your world, characters, and stories.</p>
        </div>

        <div className="flex flex-wrap gap-3 items-center justify-center">
          {/* File Operations */}
          <div className="flex gap-2 mr-2 bg-gray-800 p-1 rounded-lg border border-gray-700">
             <input type="file" ref={importInputRef} className="hidden" accept=".json" onChange={handleFileChange} />
             <button onClick={handleImportClick} className="flex items-center gap-2 px-3 py-2 text-sm text-gray-300 hover:text-white hover:bg-gray-700 rounded transition" title="Load .json file">
               <Upload size={16} /> Load Project
             </button>
             <div className="w-[1px] bg-gray-600 my-1"></div>
             <button onClick={onExportProject} className="flex items-center gap-2 px-3 py-2 text-sm text-gray-300 hover:text-white hover:bg-gray-700 rounded transition" title="Download .json file">
               <Download size={16} /> Export Project
             </button>
          </div>

          <Button onClick={handleQuickSaveClick} variant="secondary" title="Saves to Browser Storage" className="min-w-[140px]" disabled={saveStatus === 'saving'}>
            {saveStatus === 'saved' ? <><Check size={18} className="text-green-400"/> Saved!</> : (saveStatus === 'saving' ? 'Saving...' : <><Save size={18} /> Quick Save</>)}
          </Button>

          <div className="h-8 w-[1px] bg-gray-700 mx-2 hidden md:block"></div>

          {hasSaveGame && (
            <Button onClick={onContinueGame} className="bg-yellow-600 hover:bg-yellow-500">
              <RotateCcw size={18} /> Continue
            </Button>
          )}

          <Button onClick={onPlay} className="bg-green-600 hover:bg-green-500 px-6 font-bold shadow-green-900/20">
            <PlayCircle size={18} /> PLAY GAME
          </Button>
        </div>
      </div>

      <div className="flex gap-4 mb-6 border-b border-gray-700 pb-1 overflow-x-auto">
        <button onClick={() => setActiveTab('chars')} className={`px-4 py-2 font-medium transition-colors whitespace-nowrap ${activeTab === 'chars' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}>Characters</button>
        <button onClick={() => setActiveTab('scenes')} className={`px-4 py-2 font-medium transition-colors whitespace-nowrap ${activeTab === 'scenes' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}>Scenarios</button>
        <button onClick={() => setActiveTab('battles')} className={`px-4 py-2 font-medium transition-colors whitespace-nowrap ${activeTab === 'battles' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}>Battles</button>
        <button onClick={() => setActiveTab('map')} className={`px-4 py-2 font-medium transition-colors whitespace-nowrap ${activeTab === 'map' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}>World Map</button>
      </div>

      <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
        {activeTab === 'chars' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {characters.map(char => (
                <div key={char.id} className="bg-gray-800 p-4 rounded-xl border border-gray-700 flex flex-col gap-4 shadow-lg hover:border-gray-600 transition-colors">
                  <div className="flex gap-4">
                      <div className="w-24 h-32 bg-gray-900 rounded-lg flex-shrink-0 border border-gray-600 overflow-hidden relative group">
                        {char.imageSrc ? (
                          <img src={char.imageSrc} alt={char.name} className="w-full h-full object-cover" />
                        ) : (
                          <div className="w-full h-full flex flex-col items-center justify-center text-gray-600 gap-1"><User size={24} /><span className="text-[10px] text-center px-1">Portrait</span></div>
                        )}
                        <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity text-xs font-bold">
                          UPLOAD
                          <input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e, 'imageSrc')} />
                        </label>
                      </div>
                      <div className="flex-1 space-y-3">
                        <input className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-1 focus:border-indigo-500 outline-none transition-all" value={char.name} onChange={(e) => updateCharacter(char.id, { name: e.target.value })} placeholder="Character Name" />

                        <div className="grid grid-cols-2 gap-3">
                          {/* Map Sprite & Color */}
