                                 <div className="flex-1"><div className="text-xs font-bold text-indigo-300">{char.name} Role</div><input className="w-full bg-transparent border-b border-gray-600 text-xs py-1 focus:border-indigo-400 outline-none transition-colors" placeholder="What does this character want in this scene?" value={sc.roleInScene} onChange={(e) => updateSceneCharRole(scene.id, sc.characterId, e.target.value)} /></div>
                               </div>
                             )
                           })}
                         </div>
                      </div>
                  </div>
                </div>
              </div>
            ))}
            <Button onClick={addScene} variant="secondary" className="w-full py-4 border-dashed opacity-70 hover:opacity-100"><Plus size={20} /> Add Scenario</Button>
          </div>
        )}

        {/* MAP TAB */}
        {activeTab === 'map' && (
          <div className="flex flex-col lg:flex-row gap-6 h-full">
            <div className="w-full lg:w-64 flex flex-col gap-6">
              <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 shadow-lg space-y-3">
                  <div className="flex items-center justify-between mb-2"><h3 className="font-bold text-gray-300 flex items-center gap-2"><Globe size={16}/> Maps</h3><button onClick={addMap} className="text-indigo-400 hover:text-white p-1 rounded bg-indigo-900/30 hover:bg-indigo-600 transition"><Plus size={14} /></button></div>
                  <div className="space-y-2 max-h-32 overflow-y-auto custom-scrollbar">{maps.map(m => (<div key={m.id} className={`flex items-center justify-between p-2 rounded cursor-pointer border ${m.id === activeMapId ? 'bg-indigo-900/50 border-indigo-500' : 'bg-gray-900 border-gray-800 hover:border-gray-600'}`} onClick={() => setActiveMapId(m.id)}><span className="text-xs truncate max-w-[120px]">{m.name}</span>{maps.length > 1 && (<button onClick={(e) => { e.stopPropagation(); deleteMap(m.id); }} className="text-gray-600 hover:text-red-400"><Trash2 size={12} /></button>)}</div>))}</div>
                  {currentMap && (<div className="pt-2 border-t border-gray-700"><input className="w-full bg-gray-900 border border-gray-600 rounded px-2 py-1 text-xs text-gray-200 outline-none focus:border-indigo-500" value={currentMap.name} onChange={(e) => updateCurrentMap({ name: e.target.value })} placeholder="Map Name" /></div>)}
              </div>
              {currentMap && (<div className="bg-gray-800 p-4 rounded-xl border border-gray-700 shadow-lg"><h3 className="font-bold text-gray-300 mb-3 flex items-center gap-2 text-sm"><MapIcon size={14}/> Background</h3><label className="block w-full cursor-pointer bg-gray-900 border border-gray-600 hover:border-gray-400 hover:bg-gray-800 text-center py-4 rounded-lg border-dashed transition-all group"><span className="text-xs text-gray-400 group-hover:text-white">Change Image</span><input type="file" accept="image/*" className="hidden" onChange={handleMapBgUpload} /></label></div>)}
              <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 flex-1 shadow-lg flex flex-col min-h-[300px]">
                 <h3 className="font-bold text-gray-300 mb-3 flex items-center gap-2 text-sm"><User size={14}/> Place Items</h3>
                 <div className="space-y-4 overflow-y-auto custom-scrollbar flex-1">
                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2">Scenarios</div>
                        <div className="space-y-1">{scenes.map(scene => { let iconSrc = scene.mapIconSrc; let bgColor = '#4b5563'; if (!iconSrc && scene.characters.length > 0) { const char = characters.find(c => c.id === scene.characters[0].characterId); if(char) { iconSrc = char.mapSpriteSrc; bgColor = char.rpgColor; } } return (<button key={scene.id} onClick={() => setSelectedTool(selectedTool?.id === scene.id ? null : { type: 'scene', id: scene.id })} className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === scene.id && selectedTool.type === 'scene' ? 'bg-indigo-600/20 border-indigo-500 ring-1 ring-indigo-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}><div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 overflow-hidden flex items-center justify-center flex-shrink-0" style={{ backgroundColor: bgColor }}>{iconSrc ? <img src={iconSrc} className="w-full h-full object-contain" /> : <MessageSquare size={12} className="text-gray-400"/>}</div><span className="text-xs font-medium truncate flex-1 text-left">{scene.name}</span>{selectedTool?.id === scene.id && selectedTool.type === 'scene' && <MousePointerClick size={12} className="ml-auto text-indigo-400"/>}</button>); })}</div>
                    </div>
                    {/* BATTLES TOOL LIST */}
                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2 mt-4">Battles</div>
                        <div className="space-y-1">{battles.map(battle => (<button key={battle.id} onClick={() => setSelectedTool(selectedTool?.id === battle.id ? null : { type: 'battle', id: battle.id })} className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === battle.id && selectedTool.type === 'battle' ? 'bg-red-600/20 border-red-500 ring-1 ring-red-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}><div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 overflow-hidden flex items-center justify-center flex-shrink-0 text-red-500"><Sword size={14}/></div><span className="text-xs font-medium truncate flex-1 text-left">{battle.name}</span>{selectedTool?.id === battle.id && selectedTool.type === 'battle' && <MousePointerClick size={12} className="ml-auto text-red-400"/>}</button>))}</div>
                    </div>

                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2 mt-4">Characters</div>
                        <div className="space-y-1">{characters.map(char => (<button key={char.id} onClick={() => setSelectedTool(selectedTool?.id === char.id ? null : { type: 'character', id: char.id })} className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === char.id && selectedTool.type === 'character' ? 'bg-indigo-600/20 border-indigo-500 ring-1 ring-indigo-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}><div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 overflow-hidden flex items-center justify-center flex-shrink-0" style={{ backgroundColor: char.rpgColor }}>{char.mapSpriteSrc ? <img src={char.mapSpriteSrc} className="w-full h-full object-contain" /> : null}</div><span className="text-xs font-medium truncate flex-1 text-left">{char.name}</span>{selectedTool?.id === char.id && selectedTool.type === 'character' && <MousePointerClick size={12} className="ml-auto text-indigo-400"/>}</button>))}</div>
                    </div>
                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2 mt-4">Map Transitions</div>
                        <div className="space-y-1">{maps.filter(m => m.id !== activeMapId).map(targetMap => (<button key={targetMap.id} onClick={() => setSelectedTool(selectedTool?.id === targetMap.id ? null : { type: 'transition', id: targetMap.id })} className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === targetMap.id && selectedTool.type === 'transition' ? 'bg-emerald-600/20 border-emerald-500 ring-1 ring-emerald-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}><div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 flex items-center justify-center flex-shrink-0 text-emerald-500"><Waypoints size={14} /></div><span className="text-xs font-medium truncate flex-1 text-left">To: {targetMap.name}</span>{selectedTool?.id === targetMap.id && selectedTool.type === 'transition' && <MousePointerClick size={12} className="ml-auto text-emerald-400"/>}</button>))}</div>
                    </div>
                 </div>
              </div>
            </div>
            <div className="flex-1 bg-gray-900 rounded-xl border-[4px] border-gray-800 shadow-2xl overflow-hidden relative group">
                {currentMap && currentMap.backgroundSrc ? (<div ref={mapContainerRef} onClick={handleMapClick} className="relative w-full h-full cursor-crosshair"><img src={currentMap.backgroundSrc} alt="World Map" className="w-full h-full object-contain bg-black select-none pointer-events-none" />{currentMap.spots.map(spot => { 
                    if (spot.type === 'scene') { 
                        // ... existing scene logic ...
                        const scene = scenes.find(s => s.id === spot.sceneId); 
                        let iconSrc = scene?.mapIconSrc; let bgColor = '#ffffff'; let name = scene?.name || 'Unknown Scene'; 
                        if (scene && !iconSrc && scene.characters.length > 0) { const char = characters.find(c => c.id === scene.characters[0].characterId); if(char) { iconSrc = char.mapSpriteSrc; bgColor = char.rpgColor; } } 
                        return (
                          <div key={spot.id} className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin" style={{ left: `${spot.x}%`, top: `${spot.y}%` }}>
                            <div className="relative drop-shadow-lg transition hover:scale-110 flex items-center justify-center">
                              {iconSrc ? (<div className="w-12 h-12"><img src={iconSrc} alt={name} className="w-full h-full object-contain" /></div>) : (<div className="w-10 h-10 rounded-lg border-2 border-white shadow-md flex items-center justify-center bg-indigo-600 text-white" title={name}><MessageSquare size={20} fill="currentColor" /></div>)}
                            </div>
                            <span className="bg-black/70 text-[10px] px-2 rounded text-white whitespace-nowrap mt-1 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none backdrop-blur-sm">{name}</span>
                            <button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110"><Trash2 size={12} /></button>
                          </div>
                        ) 
                    } else if (spot.type === 'battle') {
                        const battle = battles.find(b => b.id === spot.battleId);
                        const name = battle?.name || 'Unknown Battle';
                        return (
                          <div key={spot.id} className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin" style={{ left: `${spot.x}%`, top: `${spot.y}%` }}>
                            <div className="relative drop-shadow-lg transition hover:scale-110 flex items-center justify-center animate-pulse">
                              <div className="w-10 h-10 rounded-lg border-2 border-red-400 shadow-md flex items-center justify-center bg-red-900 text-white" title={name}><Sword size={20} /></div>
                            </div>
                            <span className="bg-red-900/90 border border-red-500 text-[10px] px-2 rounded text-white whitespace-nowrap mt-1 opacity-100 pointer-events-none backdrop-blur-sm font-bold tracking-wider">BATTLE</span>
                            <button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110"><Trash2 size={12} /></button>
                          </div>
                        )
                    } else if (spot.type === 'character') { 
                        // ... existing char logic ...
                        const char = characters.find(c => c.id === spot.characterId); const name = char?.name || 'Unknown'; 
                        return (<div key={spot.id} className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin" style={{ left: `${spot.x}%`, top: `${spot.y}%` }}><div className="w-12 h-12 relative drop-shadow-lg transition hover:scale-110 flex items-center justify-center">{char?.mapSpriteSrc ? (<img src={char.mapSpriteSrc} alt={name} className="w-full h-full object-contain" />) : (<div className="w-4 h-4 rounded-full border border-white shadow-sm mb-1" style={{ backgroundColor: char?.rpgColor }} />)}</div><span className="bg-black/70 text-[10px] px-2 rounded text-white whitespace-nowrap mt-1 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none backdrop-blur-sm">{name}</span><button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110"><Trash2 size={12} /></button></div>) 
                    } else { 
                        // ... existing transition logic ...
                        const target = maps.find(m => m.id === spot.targetMapId); 
                        return (<div key={spot.id} className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin" style={{ left: `${spot.x}%`, top: `${spot.y}%` }}><div className="w-8 h-8 rounded-full bg-emerald-500/50 border-2 border-emerald-400 flex items-center justify-center shadow-lg hover:scale-110 transition"><Waypoints size={16} className="text-white" /></div><span className="bg-emerald-900/90 text-[10px] px-2 rounded text-emerald-100 whitespace-nowrap mt-1 opacity-100 transition-opacity pointer-events-none backdrop-blur-sm border border-emerald-700">Go to: {target?.name || 'Unknown'}</span><button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110"><Trash2 size={12} /></button></div>) 
                    } 
                })}</div>) : (<div className="w-full h-full flex flex-col items-center justify-center text-gray-600 gap-4"><MapIcon size={48} opacity={0.5} /><p>Upload a background for {currentMap ? currentMap.name : 'Unknown'}.</p></div>)}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Battle, Character, Zone } from '../types';
import { ActiveCombatant, rollTeamInitiative, performShockTest, resolveAttack, CombatLog, DetailedRoll } from '../utils/combat';
import { Button } from './ui/Button';
import { Sword, Target, Zap, Dice5, Play, Pause, Activity } from 'lucide-react';

interface BattleArenaProps {
  battle: Battle;
  characters: Character[]; 
  onWin: () => void;
  onLose: () => void;
  onExit: () => void;
}

type BattlePhase = 'INIT' | 'COMMAND' | 'EXECUTION' | 'VICTORY' | 'DEFEAT';
type VisualState = 'idle' | 'prep' | 'hit';

interface FloatingText {
    id: string;
    text: string;
    type: 'damage' | 'heal' | 'miss' | 'crit';
    combatantId: string;
}

export const BattleArena: React.FC<BattleArenaProps> = ({ battle, characters, onWin, onLose, onExit }) => {
  const [phase, setPhase] = useState<BattlePhase>('INIT');
  const [combatants, setCombatants] = useState<ActiveCombatant[]>([]);
  const [turnQueue, setTurnQueue] = useState<string[]>([]); 
  const [logs, setLogs] = useState<CombatLog[]>([]);

  // Settings
  const [autoMode, setAutoMode] = useState(false); 

  // Command State
  const [selectedTargetId, setSelectedTargetId] = useState<string | null>(null);
  const [selectedZone, setSelectedZone] = useState<Zone>('torso');
  const [commands, setCommands] = useState<Record<string, { targetId: string, zone: Zone }>>({});

  // --- Visual States ---
  const [floatingTexts, setFloatingTexts] = useState<FloatingText[]>([]);

  // New: Track sprite state per combatant
  const [combatantVisuals, setCombatantVisuals] = useState<Record<string, VisualState>>({});

  const [animatingAttackerId, setAnimatingAttackerId] = useState<string | null>(null); // Still used for slide logic?
  const [animatingTargetId, setAnimatingTargetId] = useState<string | null>(null);

  // DICE VISUALS
  const [activeDice, setActiveDice] = useState<DetailedRoll[]>([]);
  const [showDice, setShowDice] = useState(false);
  const [diceLabel, setDiceLabel] = useState("");
  const [diceSubLabel, setDiceSubLabel] = useState(""); 

  // Control Flow State
  const [waitingForClick, setWaitingForClick] = useState(false);
  const resolveClickRef = useRef<(() => void) | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);

  const setVisualState = (id: string, state: VisualState) => {
      setCombatantVisuals(prev => ({ ...prev, [id]: state }));
  };

  const addFloatingText = (combatantId: string, text: string, type: FloatingText['type']) => {
      const id = crypto.randomUUID();
      setFloatingTexts(prev => [...prev, { id, text, type, combatantId }]);
      setTimeout(() => setFloatingTexts(prev => prev.filter(ft => ft.id !== id)), 1500);
  };

  const addLog = (text: string, type: CombatLog['type']) => {
    setLogs(prev => [...prev, { text, type }]);
  };

  // --- WAIT LOGIC ---
  const waitForInput = async (autoDelayMs: number = 800) => {
      if (autoMode) {
          return new Promise<void>(resolve => setTimeout(resolve, autoDelayMs));
      } else {
          setWaitingForClick(true);
          return new Promise<void>(resolve => {
              resolveClickRef.current = resolve;
          });
      }
  };

  const handleScreenClick = () => {
      if (waitingForClick && resolveClickRef.current) {
          setWaitingForClick(false);
          const resolver = resolveClickRef.current;
          resolveClickRef.current = null;
          resolver();
      }
  };

  // --- DICE ANIMATION HELPER ---
  const visualizeRolls = async (
      label: string, 
      subLabel: string, 
      rolls: DetailedRoll[], 
      isManualTrigger: boolean 
  ) => {
      setDiceLabel(label);
      setDiceSubLabel(subLabel);
      setActiveDice([]); 
      setShowDice(true);

      if (isManualTrigger && !autoMode) {
          setDiceLabel(`Ready to ${label}`);
          await waitForInput(0); 
      }

      setDiceLabel(label); 

      const duration = 600;
      const interval = 50;
      const steps = duration / interval;

      for(let i=0; i<steps; i++) {
          const fakeRolls = rolls.map(() => ({ roll: Math.floor(Math.random()*20)+1, total: 0 }));
          setActiveDice(fakeRolls);
          await new Promise(r => setTimeout(r, interval));
      }

      setActiveDice(rolls);
      await waitForInput(1500);
      setShowDice(false);
  };

  // Initialize Combat
  useEffect(() => {
    let mounted = true;

    const init = async () => {
      const parts: ActiveCombatant[] = [];
      [...battle.playerCharacterIds, ...battle.enemyCharacterIds].forEach(id => {
          const c = characters.find(char => char.id === id);
          if (c) {
              const team = battle.playerCharacterIds.includes(id) ? 'player' : 'enemy';
              parts.push({
                  ...c,
                  currentHp: c.stats?.hp || 20,
                  isShocked: false,
                  tempDefenseBonus: 0,
                  team,
                  stats: c.stats || { pra: 3, str: 3, wid: 3, ges: 3, wil: 3, hp: 20, maxHp: 20, limit: 10, weapon: { name: 'Hands', at: 3, mod: 0, dmg: 1, cap: null } }
              });
          }
      });

      if (!mounted) return;
      setCombatants(parts);

      const playerTeam = parts.filter(c => c.team === 'player');
      const enemyTeam = parts.filter(c => c.team === 'enemy');

      const pInit = rollTeamInitiative(playerTeam);
      const eInit = rollTeamInitiative(enemyTeam);

      await visualizeRolls("Player Initiative", `Best DEX: ${pInit.total - pInit.roll}`, [{ roll: pInit.roll, total: pInit.total }], true);
      await visualizeRolls("Enemy Initiative", `Best DEX: ${eInit.total - eInit.roll}`, [{ roll: eInit.roll, total: eInit.total }], false);

      addLog(`Initiative: Player ${pInit.total} vs Enemy ${eInit.total}`, 'info');

      if (pInit.total >= eInit.total) {
          startCommandPhase('player', parts);
      } else {
          startCommandPhase('enemy', parts);
      }
    };

    init();
    return () => { mounted = false; };
  }, [battle]);

  useEffect(() => {
      if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [logs]);

  const startCommandPhase = (activeTeam: 'player' | 'enemy', currentCombatants: ActiveCombatant[]) => {
      setPhase('COMMAND');
      const teamMembers = currentCombatants.filter(c => c.team === activeTeam && c.currentHp > 0);
      setTurnQueue(teamMembers.map(c => c.id));
      setCommands({}); 

      if (activeTeam === 'enemy') {
          setTimeout(() => runEnemyAI(teamMembers, currentCombatants), 500);
      }
  };

  const runEnemyAI = (enemies: ActiveCombatant[], allCombatants: ActiveCombatant[]) => {
     const alivePlayers = allCombatants.filter(c => c.team === 'player' && c.currentHp > 0);
     if (alivePlayers.length === 0) {
         executePhase(enemies, {}, allCombatants);
         return;
     }
     const aiCommands: Record<string, { targetId: string, zone: Zone }> = {};
     enemies.forEach(e => {
         const target = alivePlayers[Math.floor(Math.random() * alivePlayers.length)];
         aiCommands[e.id] = { targetId: target.id, zone: 'torso' }; 
     });
     setCommands(aiCommands); 
     setTimeout(() => executePhase(enemies, aiCommands, allCombatants), 1000);
  };

  const handlePlayerCommand = (attackerId: string) => {
      if (!selectedTargetId) return;
      const newCommands = { ...commands, [attackerId]: { targetId: selectedTargetId, zone: selectedZone } };
      setCommands(newCommands);
      const nextQueue = turnQueue.filter(id => id !== attackerId);
      setTurnQueue(nextQueue);
      setSelectedTargetId(null);
      setSelectedZone('torso');
      if (nextQueue.length === 0) executePhase(combatants.filter(c => c.team === 'player'), newCommands, combatants);
  };

  const executePhase = async (
      actingTeam: ActiveCombatant[], 
      activeCommands: Record<string, { targetId: string, zone: Zone }>,
      currentCombatants: ActiveCombatant[]
  ) => {
      setPhase('EXECUTION');
      let workingState = [...currentCombatants]; 

      for (const actor of actingTeam) {
          const freshActor = workingState.find(c => c.id === actor.id);
          if (!freshActor || freshActor.currentHp <= 0) continue;
          const isPlayer = actor.team === 'player';

          // 1. Shock Test
          const shockResult = performShockTest(freshActor);
          if (shockResult.rollData) {
             await visualizeRolls("Shock Test", `Target Number: 15`, [shockResult.rollData], isPlayer);
             if (shockResult.log) addLog(shockResult.log, 'info');
             if (freshActor.currentHp < (freshActor.stats!.maxHp * 0.25)) {
                  workingState = workingState.map(c => c.id === actor.id ? { ...c, isShocked: shockResult.shocked } : c);
             }
             if (shockResult.shocked) {
                addFloatingText(actor.id, "SHOCKED", "miss");
                continue; 
             }
          }

          // 2. Attack Setup
          const cmd = activeCommands[actor.id];
          if (!cmd) continue;
          const target = workingState.find(c => c.id === cmd.targetId);
          if (!target || target.currentHp <= 0) continue;

          // --- VISUAL: PREPARE ATTACK (Frame Change + Slide) ---
          setVisualState(actor.id, 'prep');
          // For melee slide effect
          setAnimatingAttackerId(actor.id);
          await waitForInput(400); // Wait for the "Charge" visual

          // Calculate
          const result = resolveAttack(freshActor, target, cmd.zone);

          // --- VISUALIZE: ROLLS ---
          const targetIsPlayer = target.team === 'player';
          await visualizeRolls(`${target.name} Evades`, `Base TN (GES): ${target.stats!.ges}`, [result.defenseRoll], targetIsPlayer);
          await visualizeRolls(`${actor.name} Attacks`, `Target Number: ${result.defenseRoll.total}`, result.attackRolls, isPlayer);

          result.logs.forEach(l => {
              addLog(l.text, l.type); 
          });

          if (result.woundRolls.length > 0) {
              const threshold = 10 - (freshActor.stats!.str - target.stats!.wid);
              await visualizeRolls("Penetration Check", `Threshold: ${threshold}`, result.woundRolls, isPlayer);
          }

          // --- VISUAL: EXECUTE HIT (Frame Change) ---
          setVisualState(actor.id, 'hit');
          // Important: Damage text comes AFTER the hit frame is established

          if (result.damage > 0) {
              setAnimatingTargetId(target.id);
              addFloatingText(target.id, `-${result.damage}`, result.isCrit ? "crit" : "damage");
              workingState = workingState.map(c => c.id === target.id ? { ...c, currentHp: Math.max(0, c.currentHp - result.damage) } : c);
              setCombatants(workingState); 
              await waitForInput(600);
              setAnimatingTargetId(null);
          } else {
              addFloatingText(target.id, "MISS", "miss");
              await waitForInput(500);
          }

          // --- VISUAL: RETURN TO IDLE ---
          setVisualState(actor.id, 'idle');
          setAnimatingAttackerId(null); // Slide back
          await waitForInput(200); // Wait for slide back
      }

      const justActedTeam = actingTeam.length > 0 ? actingTeam[0].team : 'player'; 
      checkWinCondition(workingState, justActedTeam);
  };

  const checkWinCondition = (currentCombs: ActiveCombatant[], lastActiveTeam: 'player' | 'enemy') => {
      const playersAlive = currentCombs.some(c => c.team === 'player' && c.currentHp > 0);
      const enemiesAlive = currentCombs.some(c => c.team === 'enemy' && c.currentHp > 0);

      if (!playersAlive) {
          setPhase('DEFEAT');
          return;
      }
      if (!enemiesAlive) {
          setPhase('VICTORY');
          return;
      }
      if (lastActiveTeam === 'player') startCommandPhase('enemy', currentCombs);
      else startCommandPhase('player', currentCombs);
  };

  const renderCombatant = (c: ActiveCombatant) => {
      const isDead = c.currentHp <= 0;
      const isTurn = turnQueue.includes(c.id);
      const isSelected = selectedTargetId === c.id;
      const maxHp = c.stats?.maxHp || 1;
      const hpPct = (c.currentHp / maxHp) * 100;

      // Animation Logic
      const visualState = combatantVisuals[c.id] || 'idle';
      const isAttacking = animatingAttackerId === c.id; // Used for CSS Transform Slide
      const isHit = animatingTargetId === c.id;

      const myFloatingTexts = floatingTexts.filter(ft => ft.combatantId === c.id);

      // Determine Image Source based on State hierarchy
      let displaySrc = c.battleIdleSrc || c.imageSrc || c.mapSpriteSrc;
      if (visualState === 'prep' && c.battlePrepSrc) displaySrc = c.battlePrepSrc;
      if (visualState === 'hit' && c.battleHitSrc) displaySrc = c.battleHitSrc;

      // Scaling logic
      const scale = c.battleScale || 1;

      // CSS Classes
      const lungeClass = isAttacking 
         ? (c.team === 'player' ? 'translate-x-12' : '-translate-x-12') 
         : 'translate-x-0';
      const shakeClass = isHit ? 'animate-[shake_0.5s_ease-in-out]' : '';

      return (
          <div 
             key={c.id} 
             onClick={() => {
                 if (phase === 'COMMAND' && turnQueue.length > 0) {
                     const actorId = turnQueue[0];
                     const actor = combatants.find(a => a.id === actorId);
                     if (actor?.team === 'player' && c.team === 'enemy' && !isDead) {
                         setSelectedTargetId(c.id);
                     }
                 }
             }}
             className={`relative w-48 md:w-64 flex flex-col items-center transition-transform duration-300 ease-out transform ${lungeClass} ${shakeClass}
                ${isDead ? 'opacity-50 grayscale blur-[1px]' : ''}
                ${isTurn ? 'drop-shadow-[0_0_15px_rgba(255,255,255,0.4)]' : ''}
                ${isSelected ? 'ring-2 ring-red-500 rounded-xl bg-red-900/20' : ''}
                ${!isDead && c.team === 'enemy' && phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(x => x.id === turnQueue[0])?.team === 'player' ? 'cursor-pointer hover:bg-white/5 rounded-xl' : ''}
             `}
          >
              <div className="absolute top-10 left-0 right-0 z-50 pointer-events-none flex flex-col items-center">
                  {myFloatingTexts.map(ft => (
                      <div key={ft.id} className={`text-3xl font-black animate-[floatUp_1s_ease-out_forwards] stroke-black drop-shadow-md ${ft.type === 'damage' ? 'text-red-500' : ''} ${ft.type === 'crit' ? 'text-yellow-400 text-4xl' : ''} ${ft.type === 'miss' ? 'text-gray-400' : ''} ${ft.type === 'heal' ? 'text-green-500' : ''}`}>{ft.text}</div>
                  ))}
              </div>
              <div className="w-full max-w-[120px] h-3 bg-gray-800 rounded-full mb-2 overflow-hidden border border-gray-600 shadow-inner relative z-20">
                  <div className={`h-full transition-all duration-500 ease-out ${hpPct < 25 ? 'bg-red-600' : (hpPct < 50 ? 'bg-yellow-500' : 'bg-green-500')}`} style={{ width: `${hpPct}%` }} />
                  <div className="absolute inset-0 flex items-center justify-center text-[8px] font-bold text-white drop-shadow-md">{c.currentHp} / {maxHp}</div>
              </div>

              {/* Character Image Container - Much Larger Base Size */}
              <div className={`w-40 h-40 md:w-56 md:h-56 relative transition-all ${isHit ? 'brightness-150 saturate-0 sepia' : ''}`}>
                  {displaySrc ? (
                      <img 
                        src={displaySrc} 
                        className="w-full h-full object-contain filter drop-shadow-lg transition-transform duration-300 origin-bottom" 
                        style={{ transform: `scale(${scale})` }}
                      />
                  ) : (
                      <div className="w-full h-full bg-gray-700 rounded-full flex items-center justify-center text-xs text-center p-2 border-2 border-gray-500 shadow-xl">{c.name}</div>
                  )}
                  {c.isShocked && <div className="absolute top-0 right-0 text-yellow-400 bg-black/80 rounded-full p-2 animate-pulse z-30"><Zap size={24}/></div>}
              </div>

              <div className="bg-black/70 px-3 py-1 rounded text-xs mt-1 text-center min-w-[90px] backdrop-blur-sm border border-gray-700/50 relative z-20">
                  <div className="font-bold text-gray-200 truncate max-w-[120px]">{c.name}</div>
              </div>
          </div>
      );
  };

  return (
    <div 
      className="fixed inset-0 z-[100] bg-black text-white flex flex-col font-sans select-none"
      onClick={handleScreenClick} // Global click handler for pacing
    >
       <style>{`
          @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-5px) rotate(-5deg); } 75% { transform: translateX(5px) rotate(5deg); } }
          @keyframes floatUp { 0% { transform: translateY(0) scale(1); opacity: 1; } 100% { transform: translateY(-40px) scale(1.2); opacity: 0; } }
       `}</style>
       <div className="absolute inset-0 z-0 opacity-40">
           {battle.backgroundSrc ? <img src={battle.backgroundSrc} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-red-950/40 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-gray-800 to-black" />}
       </div>

       {/* DICE OVERLAY */}
       {showDice && (
           <div className="absolute inset-0 z-50 flex items-center justify-center pointer-events-none">
               <div className="bg-black/80 backdrop-blur-md p-8 rounded-2xl flex flex-col items-center gap-4 animate-in zoom-in duration-300 border border-white/20 shadow-2xl min-w-[320px]">
                   <div className="text-xl font-bold uppercase tracking-widest text-white drop-shadow-md w-full text-center border-b border-gray-600 pb-2">{diceLabel}</div>
                   {diceSubLabel && <div className="text-sm text-gray-400 -mt-2">{diceSubLabel}</div>}
                   <div className="flex gap-4 flex-wrap justify-center">
                       {activeDice.length === 0 ? (
                           // Pending state (Waiting for click or loading)
                           <div className="flex gap-2">
                             <div className="w-16 h-16 rounded-lg bg-gray-800/50 border-2 border-dashed border-gray-500 flex items-center justify-center text-gray-500 font-bold">?</div>
                           </div>
                       ) : (
                           activeDice.map((d, i) => (
                               <div key={i} className={`w-16 h-16 flex items-center justify-center rounded-lg border-2 text-2xl font-bold shadow-lg animate-in slide-in-from-top-4 ${d.isSuccess ? 'bg-green-900 border-green-500 text-green-100' : 'bg-gray-800 border-gray-600 text-gray-400'} ${d.roll === 20 ? 'animate-bounce border-yellow-400 text-yellow-300 bg-yellow-900/50' : ''}`}>
                                   {d.total}
                                   {d.roll !== d.total && <span className="absolute bottom-1 right-1 text-[8px] opacity-60">raw:{d.roll}</span>}
                               </div>
                           ))
                       )}
                   </div>
                   {waitingForClick && <div className="text-xs text-gray-400 animate-pulse mt-2">[ Click to Continue ]</div>}
                   {!waitingForClick && !autoMode && activeDice.length === 0 && <div className="text-xs text-yellow-400 animate-pulse mt-2">[ Click to Roll ]</div>}
               </div>
           </div>
       )}

       {/* Header */}
       <div className="relative z-10 p-4 flex justify-between items-center bg-gradient-to-b from-black/90 to-transparent">
           <h2 className="text-2xl font-bold flex items-center gap-2 text-red-500 drop-shadow-md"><Sword size={24}/> {battle.name}</h2>
           <div className="flex items-center gap-4">
               <button onClick={(e) => { e.stopPropagation(); setAutoMode(!autoMode); }} className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold border transition-all ${autoMode ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                   {autoMode ? <Play size={14} fill="currentColor"/> : <Pause size={14} fill="currentColor"/>} {autoMode ? 'AUTO' : 'MANUAL'}
               </button>
               <Button onClick={onExit} variant="secondary" className="text-xs py-1 border-red-900 text-red-200 hover:bg-red-900/20">Flee</Button>
           </div>
       </div>

       {/* Battle Area */}
       <div className="relative z-10 flex-1 flex flex-col md:flex-row items-center justify-between px-4 md:px-20 py-4 gap-8 overflow-y-auto">
           <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'player').map(renderCombatant)}</div>
           <div className="flex flex-col items-center justify-center pointer-events-none">
              {phase === 'VICTORY' && <div className="text-center animate-bounce pointer-events-auto bg-black/50 p-6 rounded-xl backdrop-blur-md"><h1 className="text-5xl font-bold text-yellow-400 mb-4">VICTORY</h1><Button onClick={onWin} className="bg-yellow-600 hover:bg-yellow-500 text-xl px-8 py-4">Continue</Button></div>}
              {phase === 'DEFEAT' && <div className="text-center pointer-events-auto bg-black/50 p-6 rounded-xl backdrop-blur-md"><h1 className="text-5xl font-bold text-red-600 mb-4">DEFEAT</h1><Button onClick={onLose} variant="danger" className="text-xl px-8 py-4">Retry</Button></div>}
           </div>
           <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'enemy').map(renderCombatant)}</div>
       </div>

       {/* Bottom Control / Log Panel */}
       <div className="relative z-20 h-[30%] min-h-[220px] bg-black/95 border-t border-gray-800 flex flex-col md:flex-row shadow-[0_-5px_20px_rgba(0,0,0,0.5)]" onClick={(e) => e.stopPropagation()}>
           <div className="flex-1 p-6 border-b md:border-b-0 md:border-r border-gray-800 flex flex-col items-center justify-center gap-4 bg-gray-900/50">
              {phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(c => c.id === turnQueue[0])?.team === 'player' ? (
                  <>
                     <div className="text-lg font-bold text-indigo-300 mb-1 flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse"></div> Command: {combatants.find(c => c.id === turnQueue[0])?.name}</div>
                     {!selectedTargetId ? (
                         <div className="text-gray-400 animate-pulse flex items-center gap-2 bg-gray-800/50 px-4 py-2 rounded-lg border border-dashed border-gray-600"><Target size={16}/> Select an enemy to attack</div>
                     ) : (
                         <div className="flex flex-col gap-3 w-full max-w-sm animate-in fade-in slide-in-from-bottom-4">
                            <div className="text-xs font-bold text-center text-gray-500 uppercase tracking-wide">Target Hit Zone</div>
                            <div className="grid grid-cols-2 gap-2">
                                <Button variant={selectedZone === 'torso' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('torso')} className="text-xs relative">Torso <span className="absolute right-2 text-[10px] opacity-50">0</span></Button>
                                <Button variant={selectedZone === 'head' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('head')} className="text-xs relative">Head <span className="absolute right-2 text-[10px] opacity-50 text-red-300">-6</span></Button>
                                <Button variant={selectedZone === 'arm' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('arm')} className="text-xs relative">Arm <span className="absolute right-2 text-[10px] opacity-50">-4</span></Button>
                                <Button variant={selectedZone === 'leg' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('leg')} className="text-xs relative">Leg <span className="absolute right-2 text-[10px] opacity-50">-3</span></Button>
                            </div>
                            <Button onClick={() => handlePlayerCommand(turnQueue[0])} className="w-full mt-2 bg-red-600 hover:bg-red-500 shadow-red-900/20 py-3 text-sm font-bold tracking-wider"><Sword size={16}/> EXECUTE ATTACK</Button>
                         </div>
                     )}
                  </>
              ) : (
                  <div className="text-gray-500 italic text-sm p-4 text-center flex flex-col items-center gap-2">
                      {phase === 'COMMAND' ? <><Activity className="animate-spin text-gray-600"/> Enemy is planning...</> : (phase === 'EXECUTION' ? "Watching combat..." : "")}
                  </div>
              )}
           </div>
           <div ref={scrollRef} className="flex-[2] p-4 overflow-y-auto font-mono text-xs md:text-sm space-y-1 bg-gray-950">
               {logs.length === 0 && <div className="text-gray-700 italic">Combat Log initialized...</div>}
               {logs.map((log, i) => (
                   <div key={i} className={`py-0.5 border-b border-white/5 ${log.type === 'attack' ? 'text-blue-300' : ''} ${log.type === 'damage' ? 'text-red-400 font-bold' : ''} ${log.type === 'crit' ? 'text-yellow-400 font-bold text-lg' : ''} ${log.type === 'info' ? 'text-gray-500' : ''}`}>
                       <span className="opacity-30 mr-2 text-[10px] w-6 inline-block text-right">[{i+1}]</span>{log.text}
                   </div>
               ))}
           </div>
       </div>
    </div>
  );
};

