const DEFAULT_BATTLES: Battle[] = [];

const PROJECT_STORAGE_KEY = 'vn_creator_project';
const GAME_SAVE_KEY = 'vn_creator_savegame';

const App: React.FC = () => {
  const [mode, setMode] = useState<'edit' | 'rpg' | 'vn' | 'battle'>('edit');

  // Data State
  const [characters, setCharacters] = useState<Character[]>(DEFAULT_CHARS);
  const [scenes, setScenes] = useState<Scene[]>(DEFAULT_SCENES);
  const [maps, setMaps] = useState<WorldMap[]>(DEFAULT_MAPS);
  const [battles, setBattles] = useState<Battle[]>(DEFAULT_BATTLES);

  // Game Play State
  const [rpgState, setRpgState] = useState<RPGState>({ 
    currentMapId: 'map1', 
    completedSceneIds: [],
    completedBattleIds: [],
    unlockedIds: [],
    hiddenIds: [],
    ongoingScenes: {}
  });

  const [activeSceneIndex, setActiveSceneIndex] = useState<number>(-1);
  const [activeBattleId, setActiveBattleId] = useState<string | null>(null);
  const [vnHistory, setVnHistory] = useState<ChatMessage[]>([]); 

  const [hasSaveGame, setHasSaveGame] = useState(false);

  // Check for save game on mount and migrate from LocalStorage if needed
  useEffect(() => {
    const initLoad = async () => {
        // 1. Check for Save Game
        const savedGame = await getItem<GameSaveData>(GAME_SAVE_KEY);
        if (savedGame) {
            setHasSaveGame(true);
        }

        // 2. Load Project Data
        let data: any = await getItem(PROJECT_STORAGE_KEY);
        if (!data) {
            const lsProject = localStorage.getItem(PROJECT_STORAGE_KEY);
            if (lsProject) {
                try { data = JSON.parse(lsProject); } catch (e) {}
            }
        }

        // Apply Data
        if (data) {
            if (data.characters) setCharacters(data.characters);

            // Migration logic
            if (data.scenes) {
                const migratedScenes = data.scenes.map((s: any) => ({
                    ...s,
                    effects: s.effects || s.unlocks || [],
                    isRepeatable: s.isRepeatable || false,
                    locationName: s.locationName || s.name || 'Unknown Location',
                    aiInstructions: s.aiInstructions || '',
                    sensoryDetails: s.sensoryDetails || '',
                    environmentDetails: s.environmentDetails || ''
                }));
                setScenes(migratedScenes);
            }
            if (data.maps) setMaps(data.maps);
            else if (data.mapConfig) setMaps([{ ...data.mapConfig, id: 'map1', name: 'Default Map' }]);

            if (data.battles) setBattles(data.battles);
        }
    };
    initLoad();
  }, []);

  const handleQuickSave = async () => {
    const data = { characters, scenes, maps, battles };
    await setItem(PROJECT_STORAGE_KEY, data);
    return true;
  };

  const handleExportProject = () => {
    const data = { characters, scenes, maps, battles };
    const jsonString = JSON.stringify(data, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const href = URL.createObjectURL(blob);

    const link = document.createElement('a');
    link.href = href;
    link.download = `vn-project-${new Date().toISOString().slice(0,10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(href);
  };

  const handleImportProject = (file: File) => {
    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const content = e.target?.result as string;
        const data = JSON.parse(content);

        if (data.characters) setCharacters(data.characters);
        if (data.scenes) {
            // Migration for import
            setScenes(data.scenes.map((s: any) => ({
                ...s,
                effects: s.effects || s.unlocks || [],
                isRepeatable: s.isRepeatable || false,
                locationName: s.locationName || s.name || 'Unknown Location',
                aiInstructions: s.aiInstructions || '',
                sensoryDetails: s.sensoryDetails || '',
                environmentDetails: s.environmentDetails || ''
            })));
        }
        if (data.maps) setMaps(data.maps);
        else if (data.mapConfig) setMaps([{ ...data.mapConfig, id: 'map1', name: 'Default Map' }]);

        if (data.battles) setBattles(data.battles);

        await setItem(PROJECT_STORAGE_KEY, data);
        alert("Project loaded successfully!");
      } catch (error) {
        console.error("Import failed", error);
        alert("Failed to load project file. Invalid JSON.");
      }
    };
    reader.readAsText(file);
  };

  const handleStartNewGame = () => {
    setRpgState({ 
        currentMapId: maps[0].id, 
        completedSceneIds: [], 
        completedBattleIds: [],
        unlockedIds: [],
        hiddenIds: [],
        ongoingScenes: {} 
    });
    setVnHistory([]);
    setActiveSceneIndex(-1);
    setActiveBattleId(null);
    setMode('rpg');
  };

  const handleContinueGame = async () => {
    let savedGame = await getItem<GameSaveData>(GAME_SAVE_KEY);
    if (savedGame) {
      try {
        const safeMapId = maps.find(m => m.id === savedGame!.rpgState.currentMapId) ? savedGame!.rpgState.currentMapId : maps[0].id;

        setRpgState({ 
            ...savedGame.rpgState, 
            currentMapId: safeMapId,
            completedBattleIds: savedGame.rpgState.completedBattleIds || [],
            unlockedIds: savedGame.rpgState.unlockedIds || [], 
            hiddenIds: savedGame.rpgState.hiddenIds || [], 
            ongoingScenes: savedGame.rpgState.ongoingScenes || {} 
        });

        if (savedGame.vnState) {
          setActiveSceneIndex(savedGame.vnState.currentSceneIndex);
          setVnHistory(savedGame.vnState.history);
          setMode('vn');
        } else {
          setMode('rpg');
        }
      } catch (e) {
        console.error("Corrupt save file");
        handleStartNewGame();
      }
    }
  };

  const handleSaveGameInternal = async (updatedRpgState: RPGState, vnState: any | null) => {
      const saveData: GameSaveData = {
        rpgState: updatedRpgState,
        vnState: vnState,
        timestamp: Date.now()
      };
      await setItem(GAME_SAVE_KEY, saveData);
      setHasSaveGame(true);
      return true;
  };

  const handleInteraction = (type: 'scene'|'transition'|'character'|'battle', id: string) => {
      // Check if locked/hidden first
      if (rpgState.hiddenIds.includes(id)) return;

      if (type === 'transition') {
          if (maps.find(m => m.id === id)) {
              setRpgState(prev => ({ ...prev, currentMapId: id }));
          }
      } else if (type === 'character') {
          const charId = id;
          const char = characters.find(c => c.id === charId);
          if (!char) return;

          const availableScenes = scenes.filter(s => s.characters.some(c => c.characterId === charId));

          const playableScene = availableScenes.find(s => {
              // Check visibility/lock logic strictly
              const isCompleted = rpgState.completedSceneIds.includes(s.id);
              if (isCompleted && !s.isRepeatable) return false;
              if (rpgState.hiddenIds.includes(s.id)) return false;

              const isLockedByOthers = scenes.some(other => other.effects?.some(u => u.type === 'scene' && u.targetId === s.id && u.action === 'unlock'));
              const isUnlocked = rpgState.unlockedIds.includes(s.id);

              return !isLockedByOthers || isUnlocked;
          });

          if (playableScene) {
             startScene(playableScene);
          } else {
             alert(`${char.name} has nothing new to say right now.`);
          }

      } else if (type === 'battle') {
         const battle = battles.find(b => b.id === id);
         if (battle) {
             setActiveBattleId(battle.id);
             setMode('battle');
         }
      } else {
          const scene = scenes.find(s => s.id === id);
          if (scene) startScene(scene);
      }
  };

  const startScene = (scene: Scene) => {
      const realIndex = scenes.findIndex(s => s.id === scene.id);
      setActiveSceneIndex(realIndex);

      const existingHistory = rpgState.ongoingScenes?.[scene.id] || [];
      setVnHistory(existingHistory);

      setMode('vn');
  };

  const handleSceneExit = async (completed: boolean, history: ChatMessage[]) => {
      const activeScene = scenes[activeSceneIndex];
      const sceneId = activeScene.id;

      let newState = { ...rpgState };

      if (completed) {
          const newCompletedIds = [...rpgState.completedSceneIds];
          if (!newCompletedIds.includes(sceneId)) newCompletedIds.push(sceneId);

          const { [sceneId]: _, ...remainingScenes } = newState.ongoingScenes || {};

          const newUnlockedIds = [...rpgState.unlockedIds];
          const newHiddenIds = [...rpgState.hiddenIds];

          if (activeScene.effects) {
              activeScene.effects.forEach(effect => {
                  const targetId = effect.targetId;
                  const action = effect.action || 'unlock'; 

                  if (action === 'unlock') {
                      if (!newUnlockedIds.includes(targetId)) newUnlockedIds.push(targetId);
                      const hideIdx = newHiddenIds.indexOf(targetId);
                      if (hideIdx > -1) newHiddenIds.splice(hideIdx, 1);
                  } else if (action === 'lock') {
                      if (!newHiddenIds.includes(targetId)) newHiddenIds.push(targetId);
                  }
              });
          }

          newState = { 
              ...newState, 
              completedSceneIds: newCompletedIds,
              unlockedIds: newUnlockedIds,
              hiddenIds: newHiddenIds,
              ongoingScenes: remainingScenes
          };

      } else {
          newState = {
              ...newState,
              ongoingScenes: { ...newState.ongoingScenes, [sceneId]: history }
          };
      }

      setRpgState(newState);
      await handleSaveGameInternal(newState, null);
      setMode('rpg');
  };

  const handleBattleFinish = (won: boolean) => {
      if (!activeBattleId) return;
      const battle = battles.find(b => b.id === activeBattleId);

      if (won && battle) {
          const newCompleted = [...rpgState.completedBattleIds];
          if (!newCompleted.includes(battle.id)) newCompleted.push(battle.id);

          const newUnlockedIds = [...rpgState.unlockedIds];
          const newHiddenIds = [...rpgState.hiddenIds];

          // Apply Win Effects
          if (battle.onWinEffect) {
              battle.onWinEffect.forEach(effect => {
                  const targetId = effect.targetId;
                  if (effect.action === 'unlock') {
                      if (!newUnlockedIds.includes(targetId)) newUnlockedIds.push(targetId);
                      const hideIdx = newHiddenIds.indexOf(targetId);
                      if (hideIdx > -1) newHiddenIds.splice(hideIdx, 1);
                  } else if (effect.action === 'lock') {
                      if (!newHiddenIds.includes(targetId)) newHiddenIds.push(targetId);
                  }
              });
          }

          setRpgState(prev => ({ 
              ...prev, 
              completedBattleIds: newCompleted,
              unlockedIds: newUnlockedIds,
              hiddenIds: newHiddenIds 
          }));
      }

      setMode('rpg');
      setActiveBattleId(null);
  };

  const activeMap = maps.find(m => m.id === rpgState.currentMapId) || maps[0];
  const activeBattle = battles.find(b => b.id === activeBattleId);

  return (
    <div className="min-h-screen bg-gray-900 text-gray-100 font-sans selection:bg-indigo-500 selection:text-white">
      {mode === 'edit' && (
        <Editor 
          characters={characters}
          scenes={scenes}
          maps={maps}
          battles={battles}
          onUpdateCharacters={setCharacters}
          onUpdateScenes={setScenes}
          onUpdateMaps={setMaps}
          onUpdateBattles={setBattles}
          onPlay={handleStartNewGame}
          onQuickSave={handleQuickSave}
          onExportProject={handleExportProject}
          onImportProject={handleImportProject}
          hasSaveGame={hasSaveGame}
          onContinueGame={handleContinueGame}
        />
      )}

      {mode === 'rpg' && (
        <RPGWorld 
          characters={characters}
          mapConfig={activeMap}
          maps={maps}
          scenes={scenes}
          battles={battles}
          initialState={rpgState}
          onInteraction={handleInteraction}
          onSave={async (updatedRpgState) => {
             setRpgState(updatedRpgState);
             await handleSaveGameInternal(updatedRpgState, null);
             alert("Game Saved!");
          }}
          onExit={() => setMode('edit')}
        />
      )}

      {mode === 'battle' && activeBattle && (
          <BattleArena 
             battle={activeBattle}
             characters={characters}
             onWin={() => handleBattleFinish(true)}
             onLose={() => handleBattleFinish(false)}
             onExit={() => { setActiveBattleId(null); setMode('rpg'); }}
          />
      )}

      {mode === 'vn' && activeSceneIndex >= 0 && (
        <Player 
          scenes={scenes}
          characters={characters}
          initialState={{
            currentSceneIndex: activeSceneIndex,
            history: vnHistory, 
            timestamp: 0,
            rpgState: rpgState, 
            vnState: null
          }}
          onExit={handleSceneExit}
          onSave={async (vnState) => {
             await handleSaveGameInternal(rpgState, vnState);
             return true;
          }}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Battle, Character, Zone } from '../types';
import { ActiveCombatant, rollTeamInitiative, performShockTest, resolveAttack, CombatLog, DetailedRoll } from '../utils/combat';
import { Button } from './ui/Button';
import { Sword, Target, Zap, Dice5, Play, Pause, Activity, ChevronRight, ChevronLeft, ChevronDown, ChevronUp, List } from 'lucide-react';

interface BattleArenaProps {
  battle: Battle;
  characters: Character[]; 
  onWin: () => void;
  onLose: () => void;
  onExit: () => void;
}

type BattlePhase = 'INIT' | 'COMMAND' | 'EXECUTION' | 'VICTORY' | 'DEFEAT';
type VisualState = 'idle' | 'prep' | 'hit';

interface FloatingText {
    id: string;
    text: string;
    type: 'damage' | 'heal' | 'miss' | 'crit';
    combatantId: string;
}

export const BattleArena: React.FC<BattleArenaProps> = ({ battle, characters, onWin, onLose, onExit }) => {
  const [phase, setPhase] = useState<BattlePhase>('INIT');
  const [combatants, setCombatants] = useState<ActiveCombatant[]>([]);
  const [turnQueue, setTurnQueue] = useState<string[]>([]); 
  const [logs, setLogs] = useState<CombatLog[]>([]);

  // Settings
  const [autoMode, setAutoMode] = useState(false); 
  const [isLogCollapsed, setIsLogCollapsed] = useState(false);

  // Command State
  const [selectedTargetId, setSelectedTargetId] = useState<string | null>(null);
  const [selectedZone, setSelectedZone] = useState<Zone>('torso');
  const [commands, setCommands] = useState<Record<string, { targetId: string, zone: Zone }>>({});

  // --- Visual States ---
  const [floatingTexts, setFloatingTexts] = useState<FloatingText[]>([]);

  // New: Track sprite state per combatant
  const [combatantVisuals, setCombatantVisuals] = useState<Record<string, VisualState>>({});

  const [animatingAttackerId, setAnimatingAttackerId] = useState<string | null>(null); // Still used for slide logic?
  const [animatingTargetId, setAnimatingTargetId] = useState<string | null>(null);

  // DICE VISUALS
  const [activeDice, setActiveDice] = useState<DetailedRoll[]>([]);
  const [showDice, setShowDice] = useState(false);
  const [diceLabel, setDiceLabel] = useState("");
  const [diceSubLabel, setDiceSubLabel] = useState(""); 

  // Control Flow State
  const [waitingForClick, setWaitingForClick] = useState(false);
  const resolveClickRef = useRef<(() => void) | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);

  const setVisualState = (id: string, state: VisualState) => {
      setCombatantVisuals(prev => ({ ...prev, [id]: state }));
  };

  const addFloatingText = (combatantId: string, text: string, type: FloatingText['type']) => {
      const id = crypto.randomUUID();
      setFloatingTexts(prev => [...prev, { id, text, type, combatantId }]);
      setTimeout(() => setFloatingTexts(prev => prev.filter(ft => ft.id !== id)), 1500);
  };

  const addLog = (text: string, type: CombatLog['type']) => {
    setLogs(prev => [...prev, { text, type }]);
  };

  // --- WAIT LOGIC ---
  const waitForInput = async (autoDelayMs: number = 800) => {
      if (autoMode) {
          return new Promise<void>(resolve => setTimeout(resolve, autoDelayMs));
      } else {
          setWaitingForClick(true);
          return new Promise<void>(resolve => {
              resolveClickRef.current = resolve;
          });
      }
  };

  const handleScreenClick = () => {
      if (waitingForClick && resolveClickRef.current) {
          setWaitingForClick(false);
          const resolver = resolveClickRef.current;
          resolveClickRef.current = null;
          resolver();
      }
  };

  // --- DICE ANIMATION HELPER ---
  const visualizeRolls = async (
      label: string, 
      subLabel: string, 
      rolls: DetailedRoll[], 
      isManualTrigger: boolean 
  ) => {
      setDiceLabel(label);
      setDiceSubLabel(subLabel);
      setActiveDice([]); 
      setShowDice(true);

      if (isManualTrigger && !autoMode) {
          setDiceLabel(`Ready to ${label}`);
          await waitForInput(0); 
      }

      setDiceLabel(label); 

      const duration = 600;
      const interval = 50;
      const steps = duration / interval;

      for(let i=0; i<steps; i++) {
          const fakeRolls = rolls.map(() => ({ roll: Math.floor(Math.random()*20)+1, total: 0 }));
          setActiveDice(fakeRolls);
          await new Promise(r => setTimeout(r, interval));
      }

      setActiveDice(rolls);
      await waitForInput(1500);
      setShowDice(false);
  };

  // Initialize Combat
  useEffect(() => {
    let mounted = true;

    const init = async () => {
      const parts: ActiveCombatant[] = [];
      [...battle.playerCharacterIds, ...battle.enemyCharacterIds].forEach(id => {
          const c = characters.find(char => char.id === id);
          if (c) {
              const team = battle.playerCharacterIds.includes(id) ? 'player' : 'enemy';
              parts.push({
                  ...c,
                  currentHp: c.stats?.hp || 20,
                  isShocked: false,
                  tempDefenseBonus: 0,
                  team,
                  stats: c.stats || { pra: 3, str: 3, wid: 3, ges: 3, wil: 3, hp: 20, maxHp: 20, limit: 10, weapon: { name: 'Hands', at: 3, mod: 0, dmg: 1, cap: null } }
              });
          }
      });

      if (!mounted) return;
      setCombatants(parts);

      const playerTeam = parts.filter(c => c.team === 'player');
      const enemyTeam = parts.filter(c => c.team === 'enemy');

      const pInit = rollTeamInitiative(playerTeam);
      const eInit = rollTeamInitiative(enemyTeam);

      await visualizeRolls("Player Initiative", `Best DEX: ${pInit.total - pInit.roll}`, [{ roll: pInit.roll, total: pInit.total }], true);
      await visualizeRolls("Enemy Initiative", `Best DEX: ${eInit.total - eInit.roll}`, [{ roll: eInit.roll, total: eInit.total }], false);

      addLog(`Initiative: Player ${pInit.total} vs Enemy ${eInit.total}`, 'info');

      if (pInit.total >= eInit.total) {
          startCommandPhase('player', parts);
      } else {
          startCommandPhase('enemy', parts);
      }
    };

    init();
    return () => { mounted = false; };
  }, [battle]);

  useEffect(() => {
      if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [logs, isLogCollapsed]);

  const startCommandPhase = (activeTeam: 'player' | 'enemy', currentCombatants: ActiveCombatant[]) => {
      setPhase('COMMAND');
      const teamMembers = currentCombatants.filter(c => c.team === activeTeam && c.currentHp > 0);
      setTurnQueue(teamMembers.map(c => c.id));
      setCommands({}); 

      if (activeTeam === 'enemy') {
          setTimeout(() => runEnemyAI(teamMembers, currentCombatants), 500);
      }
  };

  const runEnemyAI = (enemies: ActiveCombatant[], allCombatants: ActiveCombatant[]) => {
     const alivePlayers = allCombatants.filter(c => c.team === 'player' && c.currentHp > 0);
     if (alivePlayers.length === 0) {
         executePhase(enemies, {}, allCombatants);
         return;
     }
     const aiCommands: Record<string, { targetId: string, zone: Zone }> = {};
     enemies.forEach(e => {
         const target = alivePlayers[Math.floor(Math.random() * alivePlayers.length)];
         aiCommands[e.id] = { targetId: target.id, zone: 'torso' }; 
     });
     setCommands(aiCommands); 
     setTimeout(() => executePhase(enemies, aiCommands, allCombatants), 1000);
  };

  const handlePlayerCommand = (attackerId: string) => {
      if (!selectedTargetId) return;
      const newCommands = { ...commands, [attackerId]: { targetId: selectedTargetId, zone: selectedZone } };
      setCommands(newCommands);
      const nextQueue = turnQueue.filter(id => id !== attackerId);
      setTurnQueue(nextQueue);
      setSelectedTargetId(null);
      setSelectedZone('torso');
      if (nextQueue.length === 0) executePhase(combatants.filter(c => c.team === 'player'), newCommands, combatants);
  };

  const executePhase = async (
      actingTeam: ActiveCombatant[], 
      activeCommands: Record<string, { targetId: string, zone: Zone }>,
      currentCombatants: ActiveCombatant[]
  ) => {
      setPhase('EXECUTION');
      let workingState = [...currentCombatants]; 

      for (const actor of actingTeam) {
          const freshActor = workingState.find(c => c.id === actor.id);
          if (!freshActor || freshActor.currentHp <= 0) continue;
          const isPlayer = actor.team === 'player';

          // 1. Shock Test
          const shockResult = performShockTest(freshActor);
          if (shockResult.rollData) {
             await visualizeRolls("Shock Test", `Target Number: 15`, [shockResult.rollData], isPlayer);
             if (shockResult.log) addLog(shockResult.log, 'info');
             if (freshActor.currentHp < (freshActor.stats!.maxHp * 0.25)) {
                  workingState = workingState.map(c => c.id === actor.id ? { ...c, isShocked: shockResult.shocked } : c);
             }
             if (shockResult.shocked) {
                addFloatingText(actor.id, "SHOCKED", "miss");
                continue; 
             }
          }

          // 2. Attack Setup
          const cmd = activeCommands[actor.id];
          if (!cmd) continue;
          const target = workingState.find(c => c.id === cmd.targetId);
          if (!target || target.currentHp <= 0) continue;

          // --- VISUAL: PREPARE ATTACK (Frame Change + Slide) ---
          setVisualState(actor.id, 'prep');
          // For melee slide effect
          setAnimatingAttackerId(actor.id);
          await waitForInput(400); // Wait for the "Charge" visual

          // Calculate
          const result = resolveAttack(freshActor, target, cmd.zone);

          // --- VISUALIZE: ROLLS ---
          const targetIsPlayer = target.team === 'player';
          await visualizeRolls(`${target.name} Evades`, `Base TN (GES): ${target.stats!.ges}`, [result.defenseRoll], targetIsPlayer);
          await visualizeRolls(`${actor.name} Attacks`, `Target Number: ${result.defenseRoll.total}`, result.attackRolls, isPlayer);

          result.logs.forEach(l => {
              addLog(l.text, l.type); 
          });

          if (result.woundRolls.length > 0) {
              const threshold = 10 - (freshActor.stats!.str - target.stats!.wid);
              await visualizeRolls("Penetration Check", `Threshold: ${threshold}`, result.woundRolls, isPlayer);
          }

          // --- VISUAL: EXECUTE HIT (Frame Change) ---
          setVisualState(actor.id, 'hit');
          // Important: Damage text comes AFTER the hit frame is established

          if (result.damage > 0) {
              setAnimatingTargetId(target.id);
              addFloatingText(target.id, `-${result.damage}`, result.isCrit ? "crit" : "damage");
              workingState = workingState.map(c => c.id === target.id ? { ...c, currentHp: Math.max(0, c.currentHp - result.damage) } : c);
              setCombatants(workingState); 
              await waitForInput(600);
              setAnimatingTargetId(null);
          } else {
              addFloatingText(target.id, "MISS", "miss");
              await waitForInput(500);
          }

          // --- VISUAL: RETURN TO IDLE ---
          setVisualState(actor.id, 'idle');
          setAnimatingAttackerId(null); // Slide back
          await waitForInput(200); // Wait for slide back
      }

      const justActedTeam = actingTeam.length > 0 ? actingTeam[0].team : 'player'; 
      checkWinCondition(workingState, justActedTeam);
  };

  const checkWinCondition = (currentCombs: ActiveCombatant[], lastActiveTeam: 'player' | 'enemy') => {
      const playersAlive = currentCombs.some(c => c.team === 'player' && c.currentHp > 0);
      const enemiesAlive = currentCombs.some(c => c.team === 'enemy' && c.currentHp > 0);

      if (!playersAlive) {
          setPhase('DEFEAT');
          return;
      }
      if (!enemiesAlive) {
          setPhase('VICTORY');
          return;
      }
      if (lastActiveTeam === 'player') startCommandPhase('enemy', currentCombs);
      else startCommandPhase('player', currentCombs);
  };

  const renderCombatant = (c: ActiveCombatant) => {
      const isDead = c.currentHp <= 0;
      const isTurn = turnQueue.includes(c.id);
      const isSelected = selectedTargetId === c.id;
      const maxHp = c.stats?.maxHp || 1;
      const hpPct = (c.currentHp / maxHp) * 100;

      // Animation Logic
      const visualState = combatantVisuals[c.id] || 'idle';
      const isAttacking = animatingAttackerId === c.id; // Used for CSS Transform Slide
      const isHit = animatingTargetId === c.id;

      const myFloatingTexts = floatingTexts.filter(ft => ft.combatantId === c.id);

      // Determine Image Source based on State hierarchy
      let displaySrc = c.battleIdleSrc || c.imageSrc || c.mapSpriteSrc;
      if (visualState === 'prep' && c.battlePrepSrc) displaySrc = c.battlePrepSrc;
      if (visualState === 'hit' && c.battleHitSrc) displaySrc = c.battleHitSrc;

      // Scaling logic
      const scale = c.battleScale || 1;

      // CSS Classes
      const lungeClass = isAttacking 
         ? (c.team === 'player' ? 'translate-x-12' : '-translate-x-12') 
         : 'translate-x-0';
      const shakeClass = isHit ? 'animate-[shake_0.5s_ease-in-out]' : '';

      return (
          <div 
             key={c.id} 
             onClick={() => {
                 if (phase === 'COMMAND' && turnQueue.length > 0) {
                     const actorId = turnQueue[0];
                     const actor = combatants.find(a => a.id === actorId);
                     if (actor?.team === 'player' && c.team === 'enemy' && !isDead) {
                         setSelectedTargetId(c.id);
                     }
                 }
             }}
             className={`relative w-48 md:w-64 flex flex-col items-center transition-transform duration-300 ease-out transform ${lungeClass} ${shakeClass}
                ${isDead ? 'opacity-50 grayscale blur-[1px]' : ''}
                ${isTurn ? 'drop-shadow-[0_0_15px_rgba(255,255,255,0.4)]' : ''}
                ${isSelected ? 'ring-2 ring-red-500 rounded-xl bg-red-900/20' : ''}
                ${!isDead && c.team === 'enemy' && phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(x => x.id === turnQueue[0])?.team === 'player' ? 'cursor-pointer hover:bg-white/5 rounded-xl' : ''}
             `}
          >
              <div className="absolute top-10 left-0 right-0 z-50 pointer-events-none flex flex-col items-center">
                  {myFloatingTexts.map(ft => (
                      <div key={ft.id} className={`text-3xl font-black animate-[floatUp_1s_ease-out_forwards] stroke-black drop-shadow-md ${ft.type === 'damage' ? 'text-red-500' : ''} ${ft.type === 'crit' ? 'text-yellow-400 text-4xl' : ''} ${ft.type === 'miss' ? 'text-gray-400' : ''} ${ft.type === 'heal' ? 'text-green-500' : ''}`}>{ft.text}</div>
                  ))}
              </div>
              <div className="w-full max-w-[120px] h-3 bg-gray-800 rounded-full mb-2 overflow-hidden border border-gray-600 shadow-inner relative z-20">
                  <div className={`h-full transition-all duration-500 ease-out ${hpPct < 25 ? 'bg-red-600' : (hpPct < 50 ? 'bg-yellow-500' : 'bg-green-500')}`} style={{ width: `${hpPct}%` }} />
                  <div className="absolute inset-0 flex items-center justify-center text-[8px] font-bold text-white drop-shadow-md">{c.currentHp} / {maxHp}</div>
              </div>

              {/* Character Image Container - Much Larger Base Size */}
              <div className={`w-40 h-40 md:w-56 md:h-56 relative transition-all ${isHit ? 'brightness-150 saturate-0 sepia' : ''}`}>
                  {displaySrc ? (
                      <img 
                        src={displaySrc} 
                        className="w-full h-full object-contain filter drop-shadow-lg transition-transform duration-300 origin-bottom" 
                        style={{ transform: `scale(${scale})` }}
                      />
                  ) : (
                      <div className="w-full h-full bg-gray-700 rounded-full flex items-center justify-center text-xs text-center p-2 border-2 border-gray-500 shadow-xl">{c.name}</div>
                  )}
                  {c.isShocked && <div className="absolute top-0 right-0 text-yellow-400 bg-black/80 rounded-full p-2 animate-pulse z-30"><Zap size={24}/></div>}
              </div>

              <div className="bg-black/70 px-3 py-1 rounded text-xs mt-1 text-center min-w-[90px] backdrop-blur-sm border border-gray-700/50 relative z-20">
                  <div className="font-bold text-gray-200 truncate max-w-[120px]">{c.name}</div>
              </div>
          </div>
      );
  };

  return (
    <div 
      className="fixed inset-0 z-[100] bg-black text-white flex flex-col font-sans select-none"
      onClick={handleScreenClick} // Global click handler for pacing
    >
       <style>{`
          @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-5px) rotate(-5deg); } 75% { transform: translateX(5px) rotate(5deg); } }
          @keyframes floatUp { 0% { transform: translateY(0) scale(1); opacity: 1; } 100% { transform: translateY(-40px) scale(1.2); opacity: 0; } }
       `}</style>
       <div className="absolute inset-0 z-0 opacity-40">
           {battle.backgroundSrc ? <img src={battle.backgroundSrc} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-red-950/40 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-gray-800 to-black" />}
       </div>

       {/* DICE OVERLAY */}
       {showDice && (
           <div className="absolute inset-0 z-50 flex items-center justify-center pointer-events-none">
               <div className="bg-black/80 backdrop-blur-md p-8 rounded-2xl flex flex-col items-center gap-4 animate-in zoom-in duration-300 border border-white/20 shadow-2xl min-w-[320px]">
                   <div className="text-xl font-bold uppercase tracking-widest text-white drop-shadow-md w-full text-center border-b border-gray-600 pb-2">{diceLabel}</div>
                   {diceSubLabel && <div className="text-sm text-gray-400 -mt-2">{diceSubLabel}</div>}
                   <div className="flex gap-4 flex-wrap justify-center">
                       {activeDice.length === 0 ? (
                           // Pending state (Waiting for click or loading)
                           <div className="flex gap-2">
                             <div className="w-16 h-16 rounded-lg bg-gray-800/50 border-2 border-dashed border-gray-500 flex items-center justify-center text-gray-500 font-bold">?</div>
                           </div>
                       ) : (
                           activeDice.map((d, i) => (
                               <div key={i} className={`w-16 h-16 flex items-center justify-center rounded-lg border-2 text-2xl font-bold shadow-lg animate-in slide-in-from-top-4 ${d.isSuccess ? 'bg-green-900 border-green-500 text-green-100' : 'bg-gray-800 border-gray-600 text-gray-400'} ${d.roll === 20 ? 'animate-bounce border-yellow-400 text-yellow-300 bg-yellow-900/50' : ''}`}>
                                   {d.total}
                                   {d.roll !== d.total && <span className="absolute bottom-1 right-1 text-[8px] opacity-60">raw:{d.roll}</span>}
                               </div>
                           ))
                       )}
                   </div>
                   {waitingForClick && <div className="text-xs text-gray-400 animate-pulse mt-2">[ Click to Continue ]</div>}
                   {!waitingForClick && !autoMode && activeDice.length === 0 && <div className="text-xs text-yellow-400 animate-pulse mt-2">[ Click to Roll ]</div>}
               </div>
           </div>
       )}

       {/* Header */}
       <div className="relative z-10 p-4 flex justify-between items-center bg-gradient-to-b from-black/90 to-transparent">
           <h2 className="text-2xl font-bold flex items-center gap-2 text-red-500 drop-shadow-md"><Sword size={24}/> {battle.name}</h2>
           <div className="flex items-center gap-4">
               <button onClick={(e) => { e.stopPropagation(); setAutoMode(!autoMode); }} className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold border transition-all ${autoMode ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                   {autoMode ? <Play size={14} fill="currentColor"/> : <Pause size={14} fill="currentColor"/>} {autoMode ? 'AUTO' : 'MANUAL'}
               </button>
               <Button onClick={onExit} variant="secondary" className="text-xs py-1 border-red-900 text-red-200 hover:bg-red-900/20">Flee</Button>
           </div>
       </div>

       {/* Battle Area */}
       <div className="relative z-10 flex-1 flex flex-col md:flex-row items-center justify-between px-4 md:px-20 py-4 gap-8 overflow-y-auto">
           <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'player').map(renderCombatant)}</div>
           <div className="flex flex-col items-center justify-center pointer-events-none">
              {phase === 'VICTORY' && <div className="text-center animate-bounce pointer-events-auto bg-black/50 p-6 rounded-xl backdrop-blur-md"><h1 className="text-5xl font-bold text-yellow-400 mb-4">VICTORY</h1><Button onClick={onWin} className="bg-yellow-600 hover:bg-yellow-500 text-xl px-8 py-4">Continue</Button></div>}
              {phase === 'DEFEAT' && <div className="text-center pointer-events-auto bg-black/50 p-6 rounded-xl backdrop-blur-md"><h1 className="text-5xl font-bold text-red-600 mb-4">DEFEAT</h1><Button onClick={onLose} variant="danger" className="text-xl px-8 py-4">Retry</Button></div>}
           </div>
           <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'enemy').map(renderCombatant)}</div>
       </div>

       {/* Bottom Control / Log Panel */}
       <div className="relative z-20 h-[30%] min-h-[220px] bg-black/95 border-t border-gray-800 flex flex-col md:flex-row shadow-[0_-5px_20px_rgba(0,0,0,0.5)]" onClick={(e) => e.stopPropagation()}>

           {/* Command Section (Expands if Log is collapsed) */}
           <div className="flex-1 p-6 border-b md:border-b-0 md:border-r border-gray-800 flex flex-col items-center justify-center gap-4 bg-gray-900/50">
              {phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(c => c.id === turnQueue[0])?.team === 'player' ? (
                  <>
                     <div className="text-lg font-bold text-indigo-300 mb-1 flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse"></div> Command: {combatants.find(c => c.id === turnQueue[0])?.name}</div>
                     {!selectedTargetId ? (
                         <div className="text-gray-400 animate-pulse flex items-center gap-2 bg-gray-800/50 px-4 py-2 rounded-lg border border-dashed border-gray-600"><Target size={16}/> Select an enemy to attack</div>
                     ) : (
                         <div className="flex flex-col gap-3 w-full max-w-sm animate-in fade-in slide-in-from-bottom-4">
                            <div className="text-xs font-bold text-center text-gray-500 uppercase tracking-wide">Target Hit Zone</div>
                            <div className="grid grid-cols-2 gap-2">
                                <Button variant={selectedZone === 'torso' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('torso')} className="text-xs relative">Torso <span className="absolute right-2 text-[10px] opacity-50">0</span></Button>
                                <Button variant={selectedZone === 'head' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('head')} className="text-xs relative">Head <span className="absolute right-2 text-[10px] opacity-50 text-red-300">-6</span></Button>
                                <Button variant={selectedZone === 'arm' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('arm')} className="text-xs relative">Arm <span className="absolute right-2 text-[10px] opacity-50">-4</span></Button>
                                <Button variant={selectedZone === 'leg' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('leg')} className="text-xs relative">Leg <span className="absolute right-2 text-[10px] opacity-50">-3</span></Button>
                            </div>
                            <Button onClick={() => handlePlayerCommand(turnQueue[0])} className="w-full mt-2 bg-red-600 hover:bg-red-500 shadow-red-900/20 py-3 text-sm font-bold tracking-wider"><Sword size={16}/> EXECUTE ATTACK</Button>
                         </div>
                     )}
                  </>
              ) : (
                  <div className="text-gray-500 italic text-sm p-4 text-center flex flex-col items-center gap-2">
                      {phase === 'COMMAND' ? <><Activity className="animate-spin text-gray-600"/> Enemy is planning...</> : (phase === 'EXECUTION' ? "Watching combat..." : "")}
                  </div>
              )}
           </div>

           {/* Combat Log Section (Collapsible) */}
           <div 
             className={`
                relative bg-gray-950 transition-all duration-300 ease-in-out border-t md:border-t-0 md:border-l border-gray-800
                ${isLogCollapsed 
                    ? 'h-8 md:h-full md:w-12 flex-none cursor-pointer hover:bg-gray-900' 
                    : 'flex-[2] h-full overflow-hidden'
                }
             `}
             onClick={() => isLogCollapsed && setIsLogCollapsed(false)}
           >
               {/* Toggle Button */}
               <button 
                 onClick={(e) => { e.stopPropagation(); setIsLogCollapsed(!isLogCollapsed); }}
                 className={`
                    absolute z-30 p-1 text-gray-400 hover:text-white bg-gray-800 rounded-bl-lg md:rounded-bl-none md:rounded-br-none md:rounded-bl-lg border-gray-700
                    ${isLogCollapsed ? 'top-0 right-0' : 'top-0 right-0'}
                 `}
                 title={isLogCollapsed ? "Expand Log" : "Collapse Log"}
               >
                   {/* Mobile Icons */}
                   <div className="md:hidden">
                       {isLogCollapsed ? <ChevronUp size={16}/> : <ChevronDown size={16}/>}
                   </div>
                   {/* Desktop Icons */}
                   <div className="hidden md:block">
                       {isLogCollapsed ? <ChevronLeft size={16}/> : <ChevronRight size={16}/>}
                   </div>
               </button>

               {!isLogCollapsed ? (
                   <div ref={scrollRef} className="h-full p-4 overflow-y-auto font-mono text-xs md:text-sm space-y-1 bg-gray-950">
                       {logs.length === 0 && <div className="text-gray-700 italic">Combat Log initialized...</div>}
                       {logs.map((log, i) => (
                           <div key={i} className={`py-0.5 border-b border-white/5 ${log.type === 'attack' ? 'text-blue-300' : ''} ${log.type === 'damage' ? 'text-red-400 font-bold' : ''} ${log.type === 'crit' ? 'text-yellow-400 font-bold text-lg' : ''} ${log.type === 'info' ? 'text-gray-500' : ''}`}>
                               <span className="opacity-30 mr-2 text-[10px] w-6 inline-block text-right">[{i+1}]</span>{log.text}
                           </div>
                       ))}
                   </div>
               ) : (
                   <div className="w-full h-full flex items-center justify-center">
                       {/* Desktop Vertical Text */}
                       <div className="hidden md:flex flex-col items-center gap-2 opacity-50">
                           <List size={16}/>
                           <span className="[writing-mode:vertical-lr] text-xs font-bold tracking-widest">COMBAT LOG</span>
                       </div>
                       {/* Mobile Horizontal Text */}
                       <div className="md:hidden flex items-center gap-2 opacity-50">
                           <List size={14}/>
                           <span className="text-xs font-bold tracking-widest">COMBAT LOG</span>
                       </div>
                   </div>
               )}
           </div>
       </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Battle, Character, Zone } from '../types';
import { ActiveCombatant, rollTeamInitiative, performShockTest, resolveAttack, CombatLog, DetailedRoll } from '../utils/combat';
import { Button } from './ui/Button';
import { Sword, Target, Zap, Dice5, Play, Pause, Activity, ChevronRight, ChevronLeft, ChevronDown, ChevronUp, List } from 'lucide-react';

interface BattleArenaProps {
  battle: Battle;
  characters: Character[]; 
  onWin: () => void;
  onLose: () => void;
  onExit: () => void;
}

type BattlePhase = 'INIT' | 'COMMAND' | 'EXECUTION' | 'VICTORY' | 'DEFEAT';
type VisualState = 'idle' | 'prep' | 'hit';

interface FloatingText {
    id: string;
    text: string;
    type: 'damage' | 'heal' | 'miss' | 'crit';
    combatantId: string;
}

export const BattleArena: React.FC<BattleArenaProps> = ({ battle, characters, onWin, onLose, onExit }) => {
  const [phase, setPhase] = useState<BattlePhase>('INIT');
  const [combatants, setCombatants] = useState<ActiveCombatant[]>([]);
  const [turnQueue, setTurnQueue] = useState<string[]>([]); 
  const [logs, setLogs] = useState<CombatLog[]>([]);

  // Settings
  const [autoMode, setAutoMode] = useState(false); 
  const [isLogCollapsed, setIsLogCollapsed] = useState(false);

  // Command State
  const [selectedTargetId, setSelectedTargetId] = useState<string | null>(null);
  const [selectedZone, setSelectedZone] = useState<Zone>('torso');
  const [commands, setCommands] = useState<Record<string, { targetId: string, zone: Zone }>>({});

  // --- Visual States ---
  const [floatingTexts, setFloatingTexts] = useState<FloatingText[]>([]);

  // New: Track sprite state per combatant
  const [combatantVisuals, setCombatantVisuals] = useState<Record<string, VisualState>>({});

  const [animatingAttackerId, setAnimatingAttackerId] = useState<string | null>(null); // Still used for slide logic?
  const [animatingTargetId, setAnimatingTargetId] = useState<string | null>(null);

  // DICE VISUALS
  const [activeDice, setActiveDice] = useState<DetailedRoll[]>([]);
  const [showDice, setShowDice] = useState(false);
  const [diceLabel, setDiceLabel] = useState("");
  const [diceSubLabel, setDiceSubLabel] = useState(""); 

  // Control Flow State
  const [waitingForClick, setWaitingForClick] = useState(false);
  const resolveClickRef = useRef<(() => void) | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);

  const setVisualState = (id: string, state: VisualState) => {
      setCombatantVisuals(prev => ({ ...prev, [id]: state }));
  };

  const addFloatingText = (combatantId: string, text: string, type: FloatingText['type']) => {
      const id = crypto.randomUUID();
      setFloatingTexts(prev => [...prev, { id, text, type, combatantId }]);
      setTimeout(() => setFloatingTexts(prev => prev.filter(ft => ft.id !== id)), 1500);
  };

  const addLog = (text: string, type: CombatLog['type']) => {
    setLogs(prev => [...prev, { text, type }]);
  };

  // --- WAIT LOGIC ---
  const waitForInput = async (autoDelayMs: number = 800) => {
      if (autoMode) {
          return new Promise<void>(resolve => setTimeout(resolve, autoDelayMs));
      } else {
          setWaitingForClick(true);
          return new Promise<void>(resolve => {
              resolveClickRef.current = resolve;
          });
      }
  };

  const handleScreenClick = () => {
      if (waitingForClick && resolveClickRef.current) {
          setWaitingForClick(false);
          const resolver = resolveClickRef.current;
          resolveClickRef.current = null;
          resolver();
      }
  };

  // --- DICE ANIMATION HELPER ---
  const visualizeRolls = async (
      label: string, 
      subLabel: string, 
      rolls: DetailedRoll[], 
      isManualTrigger: boolean 
  ) => {
      setDiceLabel(label);
      setDiceSubLabel(subLabel);
      setActiveDice([]); 
      setShowDice(true);

      if (isManualTrigger && !autoMode) {
          setDiceLabel(`Ready to ${label}`);
          await waitForInput(0); 
      }

      setDiceLabel(label); 

      const duration = 600;
      const interval = 50;
      const steps = duration / interval;

      for(let i=0; i<steps; i++) {
          const fakeRolls = rolls.map(() => ({ roll: Math.floor(Math.random()*20)+1, total: 0 }));
          setActiveDice(fakeRolls);
          await new Promise(r => setTimeout(r, interval));
      }

      setActiveDice(rolls);
      await waitForInput(1500);
      setShowDice(false);
  };

  // Initialize Combat
  useEffect(() => {
    let mounted = true;

    const init = async () => {
      const parts: ActiveCombatant[] = [];
      [...battle.playerCharacterIds, ...battle.enemyCharacterIds].forEach(id => {
          const c = characters.find(char => char.id === id);
          if (c) {
              const team = battle.playerCharacterIds.includes(id) ? 'player' : 'enemy';
              parts.push({
                  ...c,
                  currentHp: c.stats?.hp || 20,
                  isShocked: false,
                  tempDefenseBonus: 0,
                  team,
                  stats: c.stats || { pra: 3, str: 3, wid: 3, ges: 3, wil: 3, hp: 20, maxHp: 20, limit: 10, weapon: { name: 'Hands', at: 3, mod: 0, dmg: 1, cap: null } }
              });
          }
      });

      if (!mounted) return;
      setCombatants(parts);

      const playerTeam = parts.filter(c => c.team === 'player');
      const enemyTeam = parts.filter(c => c.team === 'enemy');

      const pInit = rollTeamInitiative(playerTeam);
      const eInit = rollTeamInitiative(enemyTeam);

      await visualizeRolls("Player Initiative", `Best DEX: ${pInit.total - pInit.roll}`, [{ roll: pInit.roll, total: pInit.total }], true);
      await visualizeRolls("Enemy Initiative", `Best DEX: ${eInit.total - eInit.roll}`, [{ roll: eInit.roll, total: eInit.total }], false);

      addLog(`Initiative: Player ${pInit.total} vs Enemy ${eInit.total}`, 'info');

      if (pInit.total >= eInit.total) {
          startCommandPhase('player', parts);
      } else {
          startCommandPhase('enemy', parts);
      }
    };

    init();
    return () => { mounted = false; };
  }, [battle]);

  useEffect(() => {
      if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [logs, isLogCollapsed]);

  const startCommandPhase = (activeTeam: 'player' | 'enemy', currentCombatants: ActiveCombatant[]) => {
      setPhase('COMMAND');
      const teamMembers = currentCombatants.filter(c => c.team === activeTeam && c.currentHp > 0);
      setTurnQueue(teamMembers.map(c => c.id));
      setCommands({}); 

      if (activeTeam === 'enemy') {
          setTimeout(() => runEnemyAI(teamMembers, currentCombatants), 500);
      }
  };

  const runEnemyAI = (enemies: ActiveCombatant[], allCombatants: ActiveCombatant[]) => {
     const alivePlayers = allCombatants.filter(c => c.team === 'player' && c.currentHp > 0);
     if (alivePlayers.length === 0) {
         executePhase(enemies, {}, allCombatants);
         return;
     }
     const aiCommands: Record<string, { targetId: string, zone: Zone }> = {};
     enemies.forEach(e => {
         const target = alivePlayers[Math.floor(Math.random() * alivePlayers.length)];
         aiCommands[e.id] = { targetId: target.id, zone: 'torso' }; 
     });
     setCommands(aiCommands); 
     setTimeout(() => executePhase(enemies, aiCommands, allCombatants), 1000);
  };

  const handlePlayerCommand = (attackerId: string) => {
      if (!selectedTargetId) return;
      const newCommands = { ...commands, [attackerId]: { targetId: selectedTargetId, zone: selectedZone } };
      setCommands(newCommands);
      const nextQueue = turnQueue.filter(id => id !== attackerId);
      setTurnQueue(nextQueue);
      setSelectedTargetId(null);
      setSelectedZone('torso');
      if (nextQueue.length === 0) executePhase(combatants.filter(c => c.team === 'player'), newCommands, combatants);
  };

  const executePhase = async (
      actingTeam: ActiveCombatant[], 
      activeCommands: Record<string, { targetId: string, zone: Zone }>,
      currentCombatants: ActiveCombatant[]
  ) => {
      setPhase('EXECUTION');
      let workingState = [...currentCombatants]; 

      for (const actor of actingTeam) {
          const freshActor = workingState.find(c => c.id === actor.id);
          if (!freshActor || freshActor.currentHp <= 0) continue;
          const isPlayer = actor.team === 'player';

          // 1. Shock Test
          const shockResult = performShockTest(freshActor);
          if (shockResult.rollData) {
             await visualizeRolls("Shock Test", `Target Number: 15`, [shockResult.rollData], isPlayer);
             if (shockResult.log) addLog(shockResult.log, 'info');
             if (freshActor.currentHp < (freshActor.stats!.maxHp * 0.25)) {
                  workingState = workingState.map(c => c.id === actor.id ? { ...c, isShocked: shockResult.shocked } : c);
             }
             if (shockResult.shocked) {
                addFloatingText(actor.id, "SHOCKED", "miss");
                continue; 
             }
          }

          // 2. Attack Setup
          const cmd = activeCommands[actor.id];
          if (!cmd) continue;
          const target = workingState.find(c => c.id === cmd.targetId);
          if (!target || target.currentHp <= 0) continue;

          // --- VISUAL: PREPARE ATTACK (Frame Change + Slide) ---
          setVisualState(actor.id, 'prep');
          // For melee slide effect
          setAnimatingAttackerId(actor.id);
          await waitForInput(400); // Wait for the "Charge" visual

          // Calculate
          const result = resolveAttack(freshActor, target, cmd.zone);

          // --- VISUALIZE: ROLLS ---
          const targetIsPlayer = target.team === 'player';
          await visualizeRolls(`${target.name} Evades`, `Base TN (GES): ${target.stats!.ges}`, [result.defenseRoll], targetIsPlayer);
          await visualizeRolls(`${actor.name} Attacks`, `Target Number: ${result.defenseRoll.total}`, result.attackRolls, isPlayer);

          result.logs.forEach(l => {
              addLog(l.text, l.type); 
          });

          if (result.woundRolls.length > 0) {
              const threshold = 10 - (freshActor.stats!.str - target.stats!.wid);
              await visualizeRolls("Penetration Check", `Threshold: ${threshold}`, result.woundRolls, isPlayer);
          }

          // --- VISUAL: EXECUTE HIT (Frame Change) ---
          setVisualState(actor.id, 'hit');
          // Important: Damage text comes AFTER the hit frame is established

          if (result.damage > 0) {
              setAnimatingTargetId(target.id);
              addFloatingText(target.id, `-${result.damage}`, result.isCrit ? "crit" : "damage");
              workingState = workingState.map(c => c.id === target.id ? { ...c, currentHp: Math.max(0, c.currentHp - result.damage) } : c);
              setCombatants(workingState); 
              await waitForInput(600);
              setAnimatingTargetId(null);
          } else {
              addFloatingText(target.id, "MISS", "miss");
              await waitForInput(500);
          }

          // --- VISUAL: RETURN TO IDLE ---
          setVisualState(actor.id, 'idle');
          setAnimatingAttackerId(null); // Slide back
          await waitForInput(200); // Wait for slide back
      }

      const justActedTeam = actingTeam.length > 0 ? actingTeam[0].team : 'player'; 
      checkWinCondition(workingState, justActedTeam);
  };

  const checkWinCondition = (currentCombs: ActiveCombatant[], lastActiveTeam: 'player' | 'enemy') => {
      const playersAlive = currentCombs.some(c => c.team === 'player' && c.currentHp > 0);
      const enemiesAlive = currentCombs.some(c => c.team === 'enemy' && c.currentHp > 0);

      if (!playersAlive) {
          setPhase('DEFEAT');
          return;
      }
      if (!enemiesAlive) {
          setPhase('VICTORY');
          return;
      }
      if (lastActiveTeam === 'player') startCommandPhase('enemy', currentCombs);
      else startCommandPhase('player', currentCombs);
  };

  const renderCombatant = (c: ActiveCombatant) => {
      const isDead = c.currentHp <= 0;
      const isTurn = turnQueue.includes(c.id);
      const isSelected = selectedTargetId === c.id;
      const maxHp = c.stats?.maxHp || 1;
      const hpPct = (c.currentHp / maxHp) * 100;

      // Animation Logic
      const visualState = combatantVisuals[c.id] || 'idle';
      const isAttacking = animatingAttackerId === c.id; // Used for CSS Transform Slide
      const isHit = animatingTargetId === c.id;

      const myFloatingTexts = floatingTexts.filter(ft => ft.combatantId === c.id);

      // Determine Image Source based on State hierarchy
      let displaySrc = c.battleIdleSrc || c.imageSrc || c.mapSpriteSrc;
      if (visualState === 'prep' && c.battlePrepSrc) displaySrc = c.battlePrepSrc;
      if (visualState === 'hit' && c.battleHitSrc) displaySrc = c.battleHitSrc;

      // Scaling logic
      const scale = c.battleScale || 1;

      // CSS Classes
      const lungeClass = isAttacking 
         ? (c.team === 'player' ? 'translate-x-12' : '-translate-x-12') 
         : 'translate-x-0';
      const shakeClass = isHit ? 'animate-[shake_0.5s_ease-in-out]' : '';

      return (
          <div 
             key={c.id} 
             onClick={() => {
                 if (phase === 'COMMAND' && turnQueue.length > 0) {
                     const actorId = turnQueue[0];
                     const actor = combatants.find(a => a.id === actorId);
                     if (actor?.team === 'player' && c.team === 'enemy' && !isDead) {
                         setSelectedTargetId(c.id);
                     }
                 }
             }}
             className={`relative w-48 md:w-64 flex flex-col items-center transition-transform duration-300 ease-out transform ${lungeClass} ${shakeClass}
                ${isDead ? 'opacity-50 grayscale blur-[1px]' : ''}
                ${isTurn ? 'drop-shadow-[0_0_15px_rgba(255,255,255,0.4)]' : ''}
                ${isSelected ? 'ring-2 ring-red-500 rounded-xl bg-red-900/20' : ''}
                ${!isDead && c.team === 'enemy' && phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(x => x.id === turnQueue[0])?.team === 'player' ? 'cursor-pointer hover:bg-white/5 rounded-xl' : ''}
             `}
          >
              <div className="absolute top-10 left-0 right-0 z-50 pointer-events-none flex flex-col items-center">
                  {myFloatingTexts.map(ft => (
                      <div key={ft.id} className={`text-3xl font-black animate-[floatUp_1s_ease-out_forwards] stroke-black drop-shadow-md ${ft.type === 'damage' ? 'text-red-500' : ''} ${ft.type === 'crit' ? 'text-yellow-400 text-4xl' : ''} ${ft.type === 'miss' ? 'text-gray-400' : ''} ${ft.type === 'heal' ? 'text-green-500' : ''}`}>{ft.text}</div>
                  ))}
              </div>
              <div className="w-full max-w-[120px] h-3 bg-gray-800 rounded-full mb-2 overflow-hidden border border-gray-600 shadow-inner relative z-20">
                  <div className={`h-full transition-all duration-500 ease-out ${hpPct < 25 ? 'bg-red-600' : (hpPct < 50 ? 'bg-yellow-500' : 'bg-green-500')}`} style={{ width: `${hpPct}%` }} />
                  <div className="absolute inset-0 flex items-center justify-center text-[8px] font-bold text-white drop-shadow-md">{c.currentHp} / {maxHp}</div>
              </div>

              {/* Character Image Container - Much Larger Base Size */}
              <div className={`w-40 h-40 md:w-56 md:h-56 relative transition-all ${isHit ? 'brightness-150 saturate-0 sepia' : ''}`}>
                  {displaySrc ? (
                      <img 
                        src={displaySrc} 
                        className="w-full h-full object-contain filter drop-shadow-lg transition-transform duration-300 origin-bottom" 
                        style={{ transform: `scale(${scale})` }}
                      />
                  ) : (
                      <div className="w-full h-full bg-gray-700 rounded-full flex items-center justify-center text-xs text-center p-2 border-2 border-gray-500 shadow-xl">{c.name}</div>
                  )}
                  {c.isShocked && <div className="absolute top-0 right-0 text-yellow-400 bg-black/80 rounded-full p-2 animate-pulse z-30"><Zap size={24}/></div>}
              </div>

              <div className="bg-black/70 px-3 py-1 rounded text-xs mt-1 text-center min-w-[90px] backdrop-blur-sm border border-gray-700/50 relative z-20">
                  <div className="font-bold text-gray-200 truncate max-w-[120px]">{c.name}</div>
              </div>
          </div>
      );
  };

  return (
    <div 
      className="fixed inset-0 z-[100] bg-black text-white flex flex-col font-sans select-none"
      onClick={handleScreenClick} // Global click handler for pacing
    >
       <style>{`
          @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-5px) rotate(-5deg); } 75% { transform: translateX(5px) rotate(5deg); } }
          @keyframes floatUp { 0% { transform: translateY(0) scale(1); opacity: 1; } 100% { transform: translateY(-40px) scale(1.2); opacity: 0; } }
       `}</style>
       <div className="absolute inset-0 z-0 opacity-40">
           {battle.backgroundSrc ? <img src={battle.backgroundSrc} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-red-950/40 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-gray-800 to-black" />}
       </div>

       {/* DICE OVERLAY */}
       {showDice && (
           <div className="absolute inset-0 z-50 flex items-center justify-center pointer-events-none">
               <div className="bg-black/80 backdrop-blur-md p-8 rounded-2xl flex flex-col items-center gap-4 animate-in zoom-in duration-300 border border-white/20 shadow-2xl min-w-[320px]">
                   <div className="text-xl font-bold uppercase tracking-widest text-white drop-shadow-md w-full text-center border-b border-gray-600 pb-2">{diceLabel}</div>
                   {diceSubLabel && <div className="text-sm text-gray-400 -mt-2">{diceSubLabel}</div>}
                   <div className="flex gap-4 flex-wrap justify-center">
                       {activeDice.length === 0 ? (
                           // Pending state (Waiting for click or loading)
                           <div className="flex gap-2">
                             <div className="w-16 h-16 rounded-lg bg-gray-800/50 border-2 border-dashed border-gray-500 flex items-center justify-center text-gray-500 font-bold">?</div>
                           </div>
                       ) : (
                           activeDice.map((d, i) => (
                               <div key={i} className={`w-16 h-16 flex items-center justify-center rounded-lg border-2 text-2xl font-bold shadow-lg animate-in slide-in-from-top-4 ${d.isSuccess ? 'bg-green-900 border-green-500 text-green-100' : 'bg-gray-800 border-gray-600 text-gray-400'} ${d.roll === 20 ? 'animate-bounce border-yellow-400 text-yellow-300 bg-yellow-900/50' : ''}`}>
                                   {d.total}
                                   {d.roll !== d.total && <span className="absolute bottom-1 right-1 text-[8px] opacity-60">raw:{d.roll}</span>}
                               </div>
                           ))
                       )}
                   </div>
                   {waitingForClick && <div className="text-xs text-gray-400 animate-pulse mt-2">[ Click to Continue ]</div>}
                   {!waitingForClick && !autoMode && activeDice.length === 0 && <div className="text-xs text-yellow-400 animate-pulse mt-2">[ Click to Roll ]</div>}
               </div>
           </div>
       )}

       {/* Header */}
       <div className="relative z-10 p-4 flex justify-between items-center bg-gradient-to-b from-black/90 to-transparent">
           <h2 className="text-2xl font-bold flex items-center gap-2 text-red-500 drop-shadow-md"><Sword size={24}/> {battle.name}</h2>
           <div className="flex items-center gap-4">
               <button onClick={(e) => { e.stopPropagation(); setAutoMode(!autoMode); }} className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold border transition-all ${autoMode ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                   {autoMode ? <Play size={14} fill="currentColor"/> : <Pause size={14} fill="currentColor"/>} {autoMode ? 'AUTO' : 'MANUAL'}
               </button>
               <Button onClick={onExit} variant="secondary" className="text-xs py-1 border-red-900 text-red-200 hover:bg-red-900/20">Flee</Button>
           </div>
       </div>

       {/* Battle Area */}
       <div className="relative z-10 flex-1 flex flex-col md:flex-row items-center justify-between px-4 md:px-20 py-4 gap-8 overflow-y-auto">
           <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'player').map(renderCombatant)}</div>
           <div className="flex flex-col items-center justify-center pointer-events-none">
              {phase === 'VICTORY' && <div className="text-center animate-bounce pointer-events-auto bg-black/50 p-6 rounded-xl backdrop-blur-md"><h1 className="text-5xl font-bold text-yellow-400 mb-4">VICTORY</h1><Button onClick={onWin} className="bg-yellow-600 hover:bg-yellow-500 text-xl px-8 py-4">Continue</Button></div>}
              {phase === 'DEFEAT' && <div className="text-center pointer-events-auto bg-black/50 p-6 rounded-xl backdrop-blur-md"><h1 className="text-5xl font-bold text-red-600 mb-4">DEFEAT</h1><Button onClick={onLose} variant="danger" className="text-xl px-8 py-4">Retry</Button></div>}
           </div>
           <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'enemy').map(renderCombatant)}</div>
       </div>

       {/* Bottom Control / Log Panel */}
       <div className="relative z-20 h-[30%] min-h-[220px] bg-black/95 border-t border-gray-800 flex flex-col md:flex-row shadow-[0_-5px_20px_rgba(0,0,0,0.5)]" onClick={(e) => e.stopPropagation()}>

           {/* Command Section (Expands if Log is collapsed) */}
           <div className="flex-1 p-6 border-b md:border-b-0 md:border-r border-gray-800 flex flex-col items-center justify-center gap-4 bg-gray-900/50">
              {phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(c => c.id === turnQueue[0])?.team === 'player' ? (
                  <>
                     <div className="text-lg font-bold text-indigo-300 mb-1 flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse"></div> Command: {combatants.find(c => c.id === turnQueue[0])?.name}</div>
                     {!selectedTargetId ? (
                         <div className="text-gray-400 animate-pulse flex items-center gap-2 bg-gray-800/50 px-4 py-2 rounded-lg border border-dashed border-gray-600"><Target size={16}/> Select an enemy to attack</div>
                     ) : (
                         <div className="flex flex-col gap-3 w-full max-w-sm animate-in fade-in slide-in-from-bottom-4">
                            <div className="text-xs font-bold text-center text-gray-500 uppercase tracking-wide">Target Hit Zone</div>
                            <div className="grid grid-cols-2 gap-2">
                                <Button variant={selectedZone === 'torso' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('torso')} className="text-xs relative">Torso <span className="absolute right-2 text-[10px] opacity-50">0</span></Button>
                                <Button variant={selectedZone === 'head' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('head')} className="text-xs relative">Head <span className="absolute right-2 text-[10px] opacity-50 text-red-300">-6</span></Button>
                                <Button variant={selectedZone === 'arm' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('arm')} className="text-xs relative">Arm <span className="absolute right-2 text-[10px] opacity-50">-4</span></Button>
                                <Button variant={selectedZone === 'leg' ? 'primary' : 'secondary'} onClick={() => setSelectedZone('leg')} className="text-xs relative">Leg <span className="absolute right-2 text-[10px] opacity-50">-3</span></Button>
                            </div>
                            <Button onClick={() => handlePlayerCommand(turnQueue[0])} className="w-full mt-2 bg-red-600 hover:bg-red-500 shadow-red-900/20 py-3 text-sm font-bold tracking-wider"><Sword size={16}/> EXECUTE ATTACK</Button>
                         </div>
                     )}
                  </>
              ) : (
                  <div className="text-gray-500 italic text-sm p-4 text-center flex flex-col items-center gap-2">
                      {phase === 'COMMAND' ? <><Activity className="animate-spin text-gray-600"/> Enemy is planning...</> : (phase === 'EXECUTION' ? "Watching combat..." : "")}
                  </div>
              )}
           </div>

           {/* Combat Log Section (Collapsible) */}
           <div 
             className={`
                relative bg-gray-950 transition-all duration-300 ease-in-out border-t md:border-t-0 md:border-l border-gray-800
                ${isLogCollapsed 
                    ? 'h-8 md:h-full md:w-12 flex-none cursor-pointer hover:bg-gray-900' 
                    : 'flex-[2] h-full overflow-hidden'
                }
             `}
             onClick={() => isLogCollapsed && setIsLogCollapsed(false)}
           >
               {/* Toggle Button */}
               <button 
                 onClick={(e) => { e.stopPropagation(); setIsLogCollapsed(!isLogCollapsed); }}
                 className={`
                    absolute z-30 p-1 text-gray-400 hover:text-white bg-gray-800 rounded-bl-lg md:rounded-bl-none md:rounded-br-none md:rounded-bl-lg border-gray-700
                    ${isLogCollapsed ? 'top-0 right-0' : 'top-0 right-0'}
                 `}
                 title={isLogCollapsed ? "Expand Log" : "Collapse Log"}
               >
                   {/* Mobile Icons */}
                   <div className="md:hidden">
                       {isLogCollapsed ? <ChevronUp size={16}/> : <ChevronDown size={16}/>}
                   </div>
                   {/* Desktop Icons */}
                   <div className="hidden md:block">
                       {isLogCollapsed ? <ChevronLeft size={16}/> : <ChevronRight size={16}/>}
                   </div>
               </button>

               {!isLogCollapsed ? (
                   <div ref={scrollRef} className="h-full p-4 overflow-y-auto font-mono text-xs md:text-sm space-y-1 bg-gray-950">
                       {logs.length === 0 && <div className="text-gray-700 italic">Combat Log initialized...</div>}
                       {logs.map((log, i) => (
                           <div key={i} className={`py-0.5 border-b border-white/5 ${log.type === 'attack' ? 'text-blue-300' : ''} ${log.type === 'damage' ? 'text-red-400 font-bold' : ''} ${log.type === 'crit' ? 'text-yellow-400 font-bold text-lg' : ''} ${log.type === 'info' ? 'text-gray-500' : ''}`}>
                               <span className="opacity-30 mr-2 text-[10px] w-6 inline-block text-right">[{i+1}]</span>{log.text}
                           </div>
                       ))}
                   </div>
               ) : (
                   <div className="w-full h-full flex items-center justify-center">
                       {/* Desktop Vertical Text */}
                       <div className="hidden md:flex flex-col items-center gap-2 opacity-50">
                           <List size={16}/>
                           <span className="[writing-mode:vertical-lr] text-xs font-bold tracking-widest">COMBAT LOG</span>
                       </div>
                       {/* Mobile Horizontal Text */}
                       <div className="md:hidden flex items-center gap-2 opacity-50">
                           <List size={14}/>
                           <span className="text-xs font-bold tracking-widest">COMBAT LOG</span>
                       </div>
                   </div>
               )}
           </div>
       </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Battle, Character, Zone } from '../types';
import { ActiveCombatant, rollTeamInitiative, performShockTest, resolveAttack, CombatLog, DetailedRoll } from '../utils/combat';
import { Button } from './ui/Button';
import { Sword, Target, Zap, Dice5, Play, Pause, Activity, ChevronDown, ChevronUp, List, X, Minimize2, Maximize2 } from 'lucide-react';

interface BattleArenaProps {
  battle: Battle;
  characters: Character[]; 
  onWin: () => void;
  onLose: () => void;
  onExit: () => void;
}

type BattlePhase = 'INIT' | 'COMMAND' | 'EXECUTION' | 'VICTORY' | 'DEFEAT';
type VisualState = 'idle' | 'prep' | 'hit';

interface FloatingText {
    id: string;
    text: string;
    type: 'damage' | 'heal' | 'miss' | 'crit';
    combatantId: string;
}

export const BattleArena: React.FC<BattleArenaProps> = ({ battle, characters, onWin, onLose, onExit }) => {
  const [phase, setPhase] = useState<BattlePhase>('INIT');
  const [combatants, setCombatants] = useState<ActiveCombatant[]>([]);
  const [turnQueue, setTurnQueue] = useState<string[]>([]); 
  const [logs, setLogs] = useState<CombatLog[]>([]);

  // Settings
  const [autoMode, setAutoMode] = useState(false); 
  const [isLogCollapsed, setIsLogCollapsed] = useState(false);

  // Command State
  const [selectedTargetId, setSelectedTargetId] = useState<string | null>(null);
  const [selectedZone, setSelectedZone] = useState<Zone>('torso');
  const [commands, setCommands] = useState<Record<string, { targetId: string, zone: Zone }>>({});

  // --- Visual States ---
  const [floatingTexts, setFloatingTexts] = useState<FloatingText[]>([]);

  // New: Track sprite state per combatant
  const [combatantVisuals, setCombatantVisuals] = useState<Record<string, VisualState>>({});

  const [animatingAttackerId, setAnimatingAttackerId] = useState<string | null>(null); // Still used for slide logic?
  const [animatingTargetId, setAnimatingTargetId] = useState<string | null>(null);

  // DICE VISUALS
  const [activeDice, setActiveDice] = useState<DetailedRoll[]>([]);
  const [showDice, setShowDice] = useState(false);
  const [diceLabel, setDiceLabel] = useState("");
  const [diceSubLabel, setDiceSubLabel] = useState(""); 

  // Control Flow State
  const [waitingForClick, setWaitingForClick] = useState(false);
  const resolveClickRef = useRef<(() => void) | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);

  const setVisualState = (id: string, state: VisualState) => {
      setCombatantVisuals(prev => ({ ...prev, [id]: state }));
  };

  const addFloatingText = (combatantId: string, text: string, type: FloatingText['type']) => {
      const id = crypto.randomUUID();
      setFloatingTexts(prev => [...prev, { id, text, type, combatantId }]);
      setTimeout(() => setFloatingTexts(prev => prev.filter(ft => ft.id !== id)), 1500);
  };

  const addLog = (text: string, type: CombatLog['type']) => {
    setLogs(prev => [...prev, { text, type }]);
  };

  // --- WAIT LOGIC ---
  const waitForInput = async (autoDelayMs: number = 800) => {
      if (autoMode) {
          return new Promise<void>(resolve => setTimeout(resolve, autoDelayMs));
      } else {
          setWaitingForClick(true);
          return new Promise<void>(resolve => {
              resolveClickRef.current = resolve;
          });
      }
  };

  const handleScreenClick = () => {
      if (waitingForClick && resolveClickRef.current) {
          setWaitingForClick(false);
          const resolver = resolveClickRef.current;
          resolveClickRef.current = null;
          resolver();
      }
  };

  // --- DICE ANIMATION HELPER ---
  const visualizeRolls = async (
      label: string, 
      subLabel: string, 
      rolls: DetailedRoll[], 
      isManualTrigger: boolean 
  ) => {
      setDiceLabel(label);
      setDiceSubLabel(subLabel);
      setActiveDice([]); 
      setShowDice(true);

      if (isManualTrigger && !autoMode) {
          setDiceLabel(`Ready to ${label}`);
          await waitForInput(0); 
      }

      setDiceLabel(label); 

      const duration = 600;
      const interval = 50;
      const steps = duration / interval;

      for(let i=0; i<steps; i++) {
          const fakeRolls = rolls.map(() => ({ roll: Math.floor(Math.random()*20)+1, total: 0 }));
          setActiveDice(fakeRolls);
          await new Promise(r => setTimeout(r, interval));
      }

      setActiveDice(rolls);
      await waitForInput(1500);
      setShowDice(false);
  };

  // Initialize Combat
  useEffect(() => {
    let mounted = true;

    const init = async () => {
      const parts: ActiveCombatant[] = [];
      [...battle.playerCharacterIds, ...battle.enemyCharacterIds].forEach(id => {
          const c = characters.find(char => char.id === id);
          if (c) {
              const team = battle.playerCharacterIds.includes(id) ? 'player' : 'enemy';
              parts.push({
                  ...c,
                  currentHp: c.stats?.hp || 20,
                  isShocked: false,
                  tempDefenseBonus: 0,
                  team,
                  stats: c.stats || { pra: 3, str: 3, wid: 3, ges: 3, wil: 3, hp: 20, maxHp: 20, limit: 10, weapon: { name: 'Hands', at: 3, mod: 0, dmg: 1, cap: null } }
              });
          }
      });

      if (!mounted) return;
      setCombatants(parts);

      const playerTeam = parts.filter(c => c.team === 'player');
      const enemyTeam = parts.filter(c => c.team === 'enemy');

      const pInit = rollTeamInitiative(playerTeam);
      const eInit = rollTeamInitiative(enemyTeam);

      await visualizeRolls("Player Initiative", `Best DEX: ${pInit.total - pInit.roll}`, [{ roll: pInit.roll, total: pInit.total }], true);
      await visualizeRolls("Enemy Initiative", `Best DEX: ${eInit.total - eInit.roll}`, [{ roll: eInit.roll, total: eInit.total }], false);

      addLog(`Initiative: Player ${pInit.total} vs Enemy ${eInit.total}`, 'info');

      if (pInit.total >= eInit.total) {
          startCommandPhase('player', parts);
      } else {
          startCommandPhase('enemy', parts);
      }
    };

    init();
    return () => { mounted = false; };
  }, [battle]);

  useEffect(() => {
      if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [logs, isLogCollapsed]);

  const startCommandPhase = (activeTeam: 'player' | 'enemy', currentCombatants: ActiveCombatant[]) => {
      setPhase('COMMAND');
      const teamMembers = currentCombatants.filter(c => c.team === activeTeam && c.currentHp > 0);
      setTurnQueue(teamMembers.map(c => c.id));
      setCommands({}); 

      if (activeTeam === 'enemy') {
          setTimeout(() => runEnemyAI(teamMembers, currentCombatants), 500);
      }
  };

  const runEnemyAI = (enemies: ActiveCombatant[], allCombatants: ActiveCombatant[]) => {
     const alivePlayers = allCombatants.filter(c => c.team === 'player' && c.currentHp > 0);
     if (alivePlayers.length === 0) {
         executePhase(enemies, {}, allCombatants);
         return;
     }
     const aiCommands: Record<string, { targetId: string, zone: Zone }> = {};
     enemies.forEach(e => {
         const target = alivePlayers[Math.floor(Math.random() * alivePlayers.length)];
         aiCommands[e.id] = { targetId: target.id, zone: 'torso' }; 
     });
     setCommands(aiCommands); 
     setTimeout(() => executePhase(enemies, aiCommands, allCombatants), 1000);
  };

  const handlePlayerCommand = (attackerId: string) => {
      if (!selectedTargetId) return;
      const newCommands = { ...commands, [attackerId]: { targetId: selectedTargetId, zone: selectedZone } };
      setCommands(newCommands);
      const nextQueue = turnQueue.filter(id => id !== attackerId);
      setTurnQueue(nextQueue);
      setSelectedTargetId(null);
      setSelectedZone('torso');
      if (nextQueue.length === 0) executePhase(combatants.filter(c => c.team === 'player'), newCommands, combatants);
  };

  const executePhase = async (
      actingTeam: ActiveCombatant[], 
      activeCommands: Record<string, { targetId: string, zone: Zone }>,
      currentCombatants: ActiveCombatant[]
  ) => {
      setPhase('EXECUTION');
      let workingState = [...currentCombatants]; 

      for (const actor of actingTeam) {
          const freshActor = workingState.find(c => c.id === actor.id);
          if (!freshActor || freshActor.currentHp <= 0) continue;
          const isPlayer = actor.team === 'player';

          // 1. Shock Test
          const shockResult = performShockTest(freshActor);
          if (shockResult.rollData) {
             await visualizeRolls("Shock Test", `Target Number: 15`, [shockResult.rollData], isPlayer);
             if (shockResult.log) addLog(shockResult.log, 'info');
             if (freshActor.currentHp < (freshActor.stats!.maxHp * 0.25)) {
                  workingState = workingState.map(c => c.id === actor.id ? { ...c, isShocked: shockResult.shocked } : c);
             }
             if (shockResult.shocked) {
                addFloatingText(actor.id, "SHOCKED", "miss");
                continue; 
             }
          }

          // 2. Attack Setup
          const cmd = activeCommands[actor.id];
          if (!cmd) continue;
          const target = workingState.find(c => c.id === cmd.targetId);
          if (!target || target.currentHp <= 0) continue;

          // --- VISUAL: PREPARE ATTACK (Frame Change + Slide) ---
          setVisualState(actor.id, 'prep');
          // For melee slide effect
          setAnimatingAttackerId(actor.id);
          await waitForInput(400); // Wait for the "Charge" visual

          // Calculate
          const result = resolveAttack(freshActor, target, cmd.zone);

          // --- VISUALIZE: ROLLS ---
          const targetIsPlayer = target.team === 'player';
          await visualizeRolls(`${target.name} Evades`, `Base TN (GES): ${target.stats!.ges}`, [result.defenseRoll], targetIsPlayer);
          await visualizeRolls(`${actor.name} Attacks`, `Target Number: ${result.defenseRoll.total}`, result.attackRolls, isPlayer);

          result.logs.forEach(l => {
              addLog(l.text, l.type); 
          });

          if (result.woundRolls.length > 0) {
              const threshold = 10 - (freshActor.stats!.str - target.stats!.wid);
              await visualizeRolls("Penetration Check", `Threshold: ${threshold}`, result.woundRolls, isPlayer);
          }

          // --- VISUAL: EXECUTE HIT (Frame Change) ---
          setVisualState(actor.id, 'hit');
          // Important: Damage text comes AFTER the hit frame is established

          if (result.damage > 0) {
              setAnimatingTargetId(target.id);
              addFloatingText(target.id, `-${result.damage}`, result.isCrit ? "crit" : "damage");
              workingState = workingState.map(c => c.id === target.id ? { ...c, currentHp: Math.max(0, c.currentHp - result.damage) } : c);
              setCombatants(workingState); 
              await waitForInput(600);
              setAnimatingTargetId(null);
          } else {
              addFloatingText(target.id, "MISS", "miss");
              await waitForInput(500);
          }

          // --- VISUAL: RETURN TO IDLE ---
          setVisualState(actor.id, 'idle');
          setAnimatingAttackerId(null); // Slide back
          await waitForInput(200); // Wait for slide back
      }

      const justActedTeam = actingTeam.length > 0 ? actingTeam[0].team : 'player'; 
      checkWinCondition(workingState, justActedTeam);
  };

  const checkWinCondition = (currentCombs: ActiveCombatant[], lastActiveTeam: 'player' | 'enemy') => {
      const playersAlive = currentCombs.some(c => c.team === 'player' && c.currentHp > 0);
      const enemiesAlive = currentCombs.some(c => c.team === 'enemy' && c.currentHp > 0);

      if (!playersAlive) {
          setPhase('DEFEAT');
          return;
      }
      if (!enemiesAlive) {
          setPhase('VICTORY');
          return;
      }
      if (lastActiveTeam === 'player') startCommandPhase('enemy', currentCombs);
      else startCommandPhase('player', currentCombs);
  };

  const renderCombatant = (c: ActiveCombatant) => {
      const isDead = c.currentHp <= 0;
      const isTurn = turnQueue.includes(c.id);
      const isSelected = selectedTargetId === c.id;
      const maxHp = c.stats?.maxHp || 1;
      const hpPct = (c.currentHp / maxHp) * 100;

      // Animation Logic
      const visualState = combatantVisuals[c.id] || 'idle';
      const isAttacking = animatingAttackerId === c.id; // Used for CSS Transform Slide
      const isHit = animatingTargetId === c.id;

      const myFloatingTexts = floatingTexts.filter(ft => ft.combatantId === c.id);

      // Determine Image Source based on State hierarchy
      let displaySrc = c.battleIdleSrc || c.imageSrc || c.mapSpriteSrc;
      if (visualState === 'prep' && c.battlePrepSrc) displaySrc = c.battlePrepSrc;
      if (visualState === 'hit' && c.battleHitSrc) displaySrc = c.battleHitSrc;

      // Scaling logic
      const scale = c.battleScale || 1;

      // CSS Classes
      const lungeClass = isAttacking 
         ? (c.team === 'player' ? 'translate-x-12' : '-translate-x-12') 
         : 'translate-x-0';
      const shakeClass = isHit ? 'animate-[shake_0.5s_ease-in-out]' : '';

      return (
          <div 
             key={c.id} 
             onClick={() => {
                 if (phase === 'COMMAND' && turnQueue.length > 0) {
                     const actorId = turnQueue[0];
                     const actor = combatants.find(a => a.id === actorId);
                     if (actor?.team === 'player' && c.team === 'enemy' && !isDead) {
                         setSelectedTargetId(c.id);
                     }
                 }
             }}
             className={`relative w-48 md:w-64 flex flex-col items-center transition-transform duration-300 ease-out transform ${lungeClass} ${shakeClass}
                ${isDead ? 'opacity-50 grayscale blur-[1px]' : ''}
                ${isTurn ? 'drop-shadow-[0_0_15px_rgba(255,255,255,0.4)]' : ''}
                ${isSelected ? 'ring-2 ring-red-500 rounded-xl bg-red-900/20' : ''}
                ${!isDead && c.team === 'enemy' && phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(x => x.id === turnQueue[0])?.team === 'player' ? 'cursor-pointer hover:bg-white/5 rounded-xl' : ''}
             `}
          >
              <div className="absolute top-10 left-0 right-0 z-50 pointer-events-none flex flex-col items-center">
                  {myFloatingTexts.map(ft => (
                      <div key={ft.id} className={`text-3xl font-black animate-[floatUp_1s_ease-out_forwards] stroke-black drop-shadow-md ${ft.type === 'damage' ? 'text-red-500' : ''} ${ft.type === 'crit' ? 'text-yellow-400 text-4xl' : ''} ${ft.type === 'miss' ? 'text-gray-400' : ''} ${ft.type === 'heal' ? 'text-green-500' : ''}`}>{ft.text}</div>
                  ))}
              </div>
              <div className="w-full max-w-[120px] h-3 bg-gray-800 rounded-full mb-2 overflow-hidden border border-gray-600 shadow-inner relative z-20">
                  <div className={`h-full transition-all duration-500 ease-out ${hpPct < 25 ? 'bg-red-600' : (hpPct < 50 ? 'bg-yellow-500' : 'bg-green-500')}`} style={{ width: `${hpPct}%` }} />
                  <div className="absolute inset-0 flex items-center justify-center text-[8px] font-bold text-white drop-shadow-md">{c.currentHp} / {maxHp}</div>
              </div>

              {/* Character Image Container - Much Larger Base Size */}
              <div className={`w-40 h-40 md:w-56 md:h-56 relative transition-all ${isHit ? 'brightness-150 saturate-0 sepia' : ''}`}>
                  {displaySrc ? (
                      <img 
                        src={displaySrc} 
                        className="w-full h-full object-contain filter drop-shadow-lg transition-transform duration-300 origin-bottom" 
                        style={{ transform: `scale(${scale})` }}
                      />
                  ) : (
                      <div className="w-full h-full bg-gray-700 rounded-full flex items-center justify-center text-xs text-center p-2 border-2 border-gray-500 shadow-xl">{c.name}</div>
                  )}
                  {c.isShocked && <div className="absolute top-0 right-0 text-yellow-400 bg-black/80 rounded-full p-2 animate-pulse z-30"><Zap size={24}/></div>}
              </div>

              <div className="bg-black/70 px-3 py-1 rounded text-xs mt-1 text-center min-w-[90px] backdrop-blur-sm border border-gray-700/50 relative z-20">
                  <div className="font-bold text-gray-200 truncate max-w-[120px]">{c.name}</div>
              </div>
          </div>
      );
  };

  const activePlayerCombatant = turnQueue.length > 0 ? combatants.find(c => c.id === turnQueue[0]) : null;
  const isPlayerTurn = phase === 'COMMAND' && activePlayerCombatant?.team === 'player';

  return (
    <div 
      className="fixed inset-0 z-[100] bg-black text-white flex flex-col font-sans select-none overflow-hidden"
      onClick={handleScreenClick} 
    >
       <style>{`
          @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-5px) rotate(-5deg); } 75% { transform: translateX(5px) rotate(5deg); } }
          @keyframes floatUp { 0% { transform: translateY(0) scale(1); opacity: 1; } 100% { transform: translateY(-40px) scale(1.2); opacity: 0; } }
       `}</style>

       {/* Top Bar / Header */}
       <div className="absolute top-0 left-0 right-0 z-40 p-4 flex justify-between items-center bg-gradient-to-b from-black/90 to-transparent pointer-events-none">
           <h2 className="text-2xl font-bold flex items-center gap-2 text-red-500 drop-shadow-md"><Sword size={24}/> {battle.name}</h2>
           <div className="flex items-center gap-4 pointer-events-auto">
               <button onClick={(e) => { e.stopPropagation(); setAutoMode(!autoMode); }} className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold border transition-all ${autoMode ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                   {autoMode ? <Play size={14} fill="currentColor"/> : <Pause size={14} fill="currentColor"/>} {autoMode ? 'AUTO' : 'MANUAL'}
               </button>
               <Button onClick={onExit} variant="secondary" className="text-xs py-1 border-red-900 text-red-200 hover:bg-red-900/20">Flee</Button>
           </div>
       </div>

       {/* FULL SCREEN BATTLE AREA */}
       <div className="relative w-full h-full flex items-center justify-center overflow-hidden">
           {/* Background */}
           <div className="absolute inset-0 z-0">
               {battle.backgroundSrc ? <img src={battle.backgroundSrc} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-red-950/40 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-gray-800 to-black" />}
               <div className="absolute inset-0 bg-black/20"></div>
           </div>

           {/* Characters Layer */}
           <div className="relative z-10 w-full max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between px-4 md:px-20 gap-8">
               <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'player').map(renderCombatant)}</div>

               {/* Center Status / Victory Messages */}
               <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-20">
                  {phase === 'VICTORY' && <div className="text-center animate-bounce pointer-events-auto bg-black/70 p-8 rounded-2xl backdrop-blur-xl border border-yellow-500/50 shadow-2xl"><h1 className="text-6xl font-black text-yellow-400 mb-4 drop-shadow-lg">VICTORY</h1><Button onClick={onWin} className="bg-yellow-600 hover:bg-yellow-500 text-xl px-12 py-4 font-bold shadow-lg shadow-yellow-900/50">Continue Journey</Button></div>}
                  {phase === 'DEFEAT' && <div className="text-center pointer-events-auto bg-black/70 p-8 rounded-2xl backdrop-blur-xl border border-red-500/50 shadow-2xl"><h1 className="text-6xl font-black text-red-600 mb-4 drop-shadow-lg">DEFEAT</h1><Button onClick={onLose} variant="danger" className="text-xl px-12 py-4 font-bold shadow-lg shadow-red-900/50">Try Again</Button></div>}
               </div>

               <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'enemy').map(renderCombatant)}</div>
           </div>

           {/* --- FLOATING UI LAYER --- */}

           {/* 1. Command Interface (Floating Bottom Center) */}
           {isPlayerTurn && (
              <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 z-30 w-[95%] max-w-2xl">
                 <div className="bg-black/70 backdrop-blur-md border border-indigo-500/30 rounded-2xl p-4 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300">
                    <div className="flex items-center justify-between mb-3 border-b border-white/10 pb-2">
                       <div className="text-lg font-bold text-indigo-300 flex items-center gap-2">
                          <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse shadow-[0_0_10px_#6366f1]"></div> 
                          Command: <span className="text-white">{activePlayerCombatant?.name}</span>
                       </div>
                       {!selectedTargetId && <div className="text-xs text-yellow-400 animate-pulse font-bold uppercase tracking-wider flex items-center gap-2"><Target size={14}/> Select Enemy Target</div>}
                    </div>

                    {selectedTargetId ? (
                        <div className="flex flex-col md:flex-row gap-4 items-center">
                            <div className="flex-1 flex gap-2 w-full overflow-x-auto pb-1 md:pb-0 custom-scrollbar justify-center">
                                {/* Horizontal Zone Selection */}
                                {[
                                    { id: 'torso', label: 'Torso', mod: 0 },
                                    { id: 'head', label: 'Head', mod: -6, color: 'text-red-300' },
                                    { id: 'arm', label: 'Arm', mod: -4 },
                                    { id: 'leg', label: 'Leg', mod: -3 }
                                ].map((z) => (
                                    <button 
                                        key={z.id}
                                        onClick={() => setSelectedZone(z.id as Zone)}
                                        className={`
                                            flex flex-col items-center justify-center px-4 py-2 rounded-lg border transition-all min-w-[80px]
                                            ${selectedZone === z.id 
                                                ? 'bg-indigo-600 border-indigo-400 text-white shadow-lg scale-105' 
                                                : 'bg-gray-800/50 border-gray-600 text-gray-400 hover:bg-gray-700 hover:text-white'
                                            }
                                        `}
                                    >
                                        <span className="font-bold text-sm">{z.label}</span>
                                        <span className={`text-[10px] ${z.color || 'opacity-50'}`}>{z.mod === 0 ? '-' : z.mod}</span>
                                    </button>
                                ))}
                            </div>
                            <Button onClick={() => handlePlayerCommand(turnQueue[0])} className="w-full md:w-auto bg-red-600 hover:bg-red-500 shadow-lg shadow-red-900/40 py-3 px-8 text-sm font-bold tracking-wider whitespace-nowrap h-full flex items-center gap-2">
                                <Sword size={18} className="animate-pulse"/> ATTACK
                            </Button>
                        </div>
                    ) : (
                        <div className="text-center text-gray-400 text-sm py-2 italic">
                            Click on an enemy sprite to target them.
                        </div>
                    )}
                 </div>
              </div>
           )}

           {/* 2. Floating Combat Log (Bottom Right) */}
           <div 
             className={`absolute bottom-4 right-4 z-30 bg-black/80 backdrop-blur-md border border-gray-700 shadow-2xl transition-all duration-300 ease-in-out overflow-hidden flex flex-col
                ${isLogCollapsed ? 'w-10 h-10 rounded-full cursor-pointer hover:bg-gray-800 hover:border-gray-500' : 'w-80 h-64 rounded-xl'}
             `}
             onClick={() => isLogCollapsed && setIsLogCollapsed(false)}
           >
               <div className={`flex items-center justify-between p-2 ${!isLogCollapsed ? 'border-b border-gray-700 bg-black/40' : 'h-full justify-center'}`}>
                   {!isLogCollapsed && <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2"><List size={12}/> Combat Log</span>}
                   <button 
                      onClick={(e) => { e.stopPropagation(); setIsLogCollapsed(!isLogCollapsed); }}
                      className="text-gray-400 hover:text-white transition-colors"
                   >
                       {isLogCollapsed ? <List size={16}/> : <Minimize2 size={14}/>}
                   </button>
               </div>

               {!isLogCollapsed && (
                   <div ref={scrollRef} className="flex-1 overflow-y-auto p-3 font-mono text-[10px] space-y-1 custom-scrollbar bg-black/20">
                       {logs.length === 0 && <div className="text-gray-600 italic text-center mt-4">Battle started...</div>}
                       {logs.map((log, i) => (
                           <div key={i} className={`leading-tight ${log.type === 'attack' ? 'text-blue-300' : ''} ${log.type === 'damage' ? 'text-red-400 font-bold' : ''} ${log.type === 'crit' ? 'text-yellow-400 font-bold' : ''} ${log.type === 'info' ? 'text-gray-500' : ''}`}>
                               {log.text}
                           </div>
                       ))}
                   </div>
               )}
           </div>

           {/* 3. Enemy Turn Indicator (Top Center Toast) */}
           {phase === 'COMMAND' && !isPlayerTurn && (
               <div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-30">
                   <div className="bg-black/60 backdrop-blur border border-red-500/30 text-red-200 px-6 py-2 rounded-full flex items-center gap-3 shadow-xl animate-pulse">
                       <Activity size={16} className="animate-spin"/> Enemy Turn
                   </div>
               </div>
           )}

       </div>

       {/* DICE OVERLAY (Unchanged logic, just ensure z-index is high) */}
       {showDice && (
           <div className="absolute inset-0 z-[60] flex items-center justify-center pointer-events-none">
               <div className="bg-black/80 backdrop-blur-md p-8 rounded-2xl flex flex-col items-center gap-4 animate-in zoom-in duration-300 border border-white/20 shadow-2xl min-w-[320px]">
                   <div className="text-xl font-bold uppercase tracking-widest text-white drop-shadow-md w-full text-center border-b border-gray-600 pb-2">{diceLabel}</div>
                   {diceSubLabel && <div className="text-sm text-gray-400 -mt-2">{diceSubLabel}</div>}
                   <div className="flex gap-4 flex-wrap justify-center">
                       {activeDice.length === 0 ? (
                           <div className="flex gap-2"><div className="w-16 h-16 rounded-lg bg-gray-800/50 border-2 border-dashed border-gray-500 flex items-center justify-center text-gray-500 font-bold">?</div></div>
                       ) : (
                           activeDice.map((d, i) => (
                               <div key={i} className={`w-16 h-16 flex items-center justify-center rounded-lg border-2 text-2xl font-bold shadow-lg animate-in slide-in-from-top-4 ${d.isSuccess ? 'bg-green-900 border-green-500 text-green-100' : 'bg-gray-800 border-gray-600 text-gray-400'} ${d.roll === 20 ? 'animate-bounce border-yellow-400 text-yellow-300 bg-yellow-900/50' : ''}`}>
                                   {d.total}
                                   {d.roll !== d.total && <span className="absolute bottom-1 right-1 text-[8px] opacity-60">raw:{d.roll}</span>}
                               </div>
                           ))
                       )}
                   </div>
               </div>
           </div>
       )}
    </div>
  );
};

export type Zone = 'torso' | 'head' | 'arm' | 'leg';

export interface Weapon {
  name: string;
  at: number; // Angriffs-Tempo (Würfel-Pool)
  mod: number; // Modifikator (Präzision)
  dmg: number; // Schaden pro Wunde (Flat für V1, später Dice möglich)
  cap: number | null; // Max Schaden pro Treffer (null = unbegrenzt)
}

export interface CombatStats {
  // Attributes
  pra: number; // Präzision
  str: number; // Stärke
  wid: number; // Widerstand
  ges: number; // Geschick
  wil: number; // Willenskraft

  // Vitals
  hp: number;
  maxHp: number;
  limit: number; // Verwundungs-Limit (Körpermasse/Rüstung)

  // Equipment
  weapon: Weapon;
}

export interface Character {
  id: string;
  name: string;
  defaultDescription: string;

  // Standard Images
  imageSrc: string | null; // Portrait for VN (Large)
  mapSpriteSrc: string | null; // Sprite for Map (Small/Icon)

  // Battle Images
  battleIdleSrc?: string | null; // Standing still in battle
  battlePrepSrc?: string | null; // Winding up / Casting / Running forward
  battleHitSrc?: string | null;  // The moment of impact / Release

  // Scaling
  battleScale?: number; // Global fallback
  battleIdleScale?: number; 
  battlePrepScale?: number;
  battleHitScale?: number;

  rpgColor: string; // Fallback Hex color for Map dots

  // New visual settings for Chat
  bubbleColor?: string; // Hex color for the chat bubble background
  isItalic?: boolean; // If true, text renders in italics (good for narrators/thoughts)

  // RPG Combat Stats
  stats?: CombatStats;
}

export interface SceneCharacterConfig {
  characterId: string;
  roleInScene: string; // Specific behavior/goal for this scene
}

export interface SceneEffect {
  type: 'scene' | 'transition' | 'battle'; // Added battle
  targetId: string; // Scene ID, Target Map ID, or Battle ID
  action: 'unlock' | 'lock'; 
}

export interface Battle {
  id: string;
  name: string;
  backgroundSrc: string | null;
  playerCharacterIds: string[]; // Who fights from the player side?
  enemyCharacterIds: string[]; // Who are the enemies?
  isRepeatable: boolean;
  onWinEffect?: SceneEffect[]; // Unlock something on win
}

export interface Scene {
  id: string;
  name: string;

  locationName?: string; 
  backgroundSrc: string | null; 
  description: string; 
  aiInstructions?: string; 
  sensoryDetails?: string; 
  environmentDetails?: string;

  goal: string; 
  characters: SceneCharacterConfig[];
  effects?: SceneEffect[]; 

  mapIconSrc?: string | null; 
  isRepeatable?: boolean;
}

export interface MapSpot {
  id: string;
  x: number; 
  y: number; 
  type: 'scene' | 'transition' | 'character' | 'battle'; // Added battle

  sceneId?: string; 
  characterId?: string; 
  targetMapId?: string;
  battleId?: string; // New
}

export interface WorldMap {
  id: string;
  name: string;
  backgroundSrc: string | null;
  spots: MapSpot[];
}

export interface ChatMessage {
  sender: 'user' | 'model' | 'system';
  characterId?: string; 
  text: string;
  timestamp: number;
}

export interface GameState {
  currentSceneIndex: number; 
  history: ChatMessage[];
  isProcessing: boolean;
  gameOver: boolean;
}

export interface AIResponse {
  characterResponses: {
    characterId: string;
    text: string;
  }[];
  sceneGoalReached: boolean;
  sceneTransitionReason?: string;
}

export interface RPGState {
  currentMapId: string;
  completedSceneIds: string[];
  completedBattleIds: string[]; // New
  unlockedIds: string[]; 
  hiddenIds: string[]; 
  ongoingScenes: Record<string, ChatMessage[]>; 
}

export interface GameSaveData {
  rpgState: RPGState;
  vnState: GameState | null; 
  timestamp: number;
}

import React, { useState, useRef } from 'react';
import { Plus, Trash2, Image as ImageIcon, User, Target, Save, PlayCircle, RotateCcw, Map as MapIcon, MousePointerClick, FileUp, Download, Upload, Check, Waypoints, Globe, Lock, Unlock, MessageSquare, Ban, RefreshCcw, Eye, EyeOff, Italic, Palette, Ear, Wind, Layout, Sword, Shield, Skull, Zap, Crosshair, Scaling } from 'lucide-react';
import { Character, Scene, SceneCharacterConfig, WorldMap, MapSpot, SceneEffect, Battle, CombatStats, Weapon } from '../types';
import { Button } from './ui/Button';

interface EditorProps {
  characters: Character[];
  scenes: Scene[];
  maps: WorldMap[];
  battles?: Battle[]; // New
  onUpdateCharacters: (chars: Character[]) => void;
  onUpdateScenes: (scenes: Scene[]) => void;
  onUpdateMaps: (maps: WorldMap[]) => void;
  onUpdateBattles?: (battles: Battle[]) => void; // New
  onPlay: () => void;
  onQuickSave: () => Promise<boolean>;
  onExportProject: () => void;
  onImportProject: (file: File) => void;
  hasSaveGame: boolean;
  onContinueGame: () => void;
}

// Default Stats for new chars
const DEFAULT_STATS: CombatStats = {
  pra: 3, str: 3, wid: 3, ges: 3, wil: 3,
  hp: 20, maxHp: 20, limit: 10,
  weapon: { name: 'Basic Weapon', at: 3, mod: 0, dmg: 1, cap: null }
};

export const Editor: React.FC<EditorProps> = ({
  characters,
  scenes,
  maps,
  battles = [],
  onUpdateCharacters,
  onUpdateScenes,
  onUpdateMaps,
  onUpdateBattles = (_: Battle[]) => {},
  onPlay,
  onQuickSave,
  onExportProject,
  onImportProject,
  hasSaveGame,
  onContinueGame
}) => {
  const [activeTab, setActiveTab] = useState<'chars' | 'scenes' | 'battles' | 'map'>('chars');

  // Map Editor State
  const [activeMapId, setActiveMapId] = useState<string>(maps[0]?.id || '');
  const [selectedTool, setSelectedTool] = useState<{type: 'scene'|'transition'|'character'|'battle', id: string} | null>(null);

  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const importInputRef = useRef<HTMLInputElement>(null);

  // --- Character Handlers ---
  const addCharacter = () => {
    const newChar: Character = {
      id: crypto.randomUUID(),
      name: 'New Character',
      defaultDescription: 'A friendly helper.',
      imageSrc: null,
      mapSpriteSrc: null,
      battleIdleSrc: null,
      battlePrepSrc: null,
      battleHitSrc: null,
      battleScale: 1,
      rpgColor: '#ef4444',
      bubbleColor: '#4b5563', 
      isItalic: false,
      stats: { ...DEFAULT_STATS }
    };
    onUpdateCharacters([...characters, newChar]);
  };

  const updateCharacter = (id: string, updates: Partial<Character>) => {
    onUpdateCharacters(characters.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const updateCharStats = (id: string, statUpdates: Partial<CombatStats>) => {
      onUpdateCharacters(characters.map(c => {
          if (c.id !== id) return c;
          return {
              ...c,
              stats: { ...(c.stats || DEFAULT_STATS), ...statUpdates }
          };
      }));
  };

  const updateCharWeapon = (id: string, weaponUpdates: Partial<Weapon>) => {
      onUpdateCharacters(characters.map(c => {
          if (c.id !== id) return c;
          const currentStats = c.stats || DEFAULT_STATS;
          return {
              ...c,
              stats: { 
                  ...currentStats, 
                  weapon: { ...currentStats.weapon, ...weaponUpdates }
              }
          };
      }));
  };

  const handleCharImageUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>, field: 'imageSrc' | 'mapSpriteSrc' | 'battleIdleSrc' | 'battlePrepSrc' | 'battleHitSrc') => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCharacter(id, { [field]: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  // --- Battle Handlers ---
  const addBattle = () => {
      const newBattle: Battle = {
          id: crypto.randomUUID(),
          name: `Battle ${battles.length + 1}`,
          backgroundSrc: null,
          playerCharacterIds: [],
          enemyCharacterIds: [],
          isRepeatable: false,
          onWinEffect: []
      };
      onUpdateBattles([...battles, newBattle]);
  };

  const updateBattle = (id: string, updates: Partial<Battle>) => {
      onUpdateBattles(battles.map(b => b.id === id ? { ...b, ...updates } : b));
  };

  const handleBattleBgUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateBattle(id, { backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleCharInBattle = (battleId: string, charId: string, side: 'player' | 'enemy') => {
      const battle = battles.find(b => b.id === battleId);
      if (!battle) return;

      const listKey = side === 'player' ? 'playerCharacterIds' : 'enemyCharacterIds';
      const list = battle[listKey];

      if (list.includes(charId)) {
          updateBattle(battleId, { [listKey]: list.filter(id => id !== charId) });
      } else {
          updateBattle(battleId, { [listKey]: [...list, charId] });
      }
  };

  // --- Scene Handlers ---
  const addScene = () => {
    const newScene: Scene = {
      id: crypto.randomUUID(),
      name: `Scene ${scenes.length + 1}`,
      locationName: 'Unknown Location',
      backgroundSrc: null,
      description: 'You are in a quiet room.',
      aiInstructions: '',
      sensoryDetails: '',
      environmentDetails: '',
      goal: 'Say hello.',
      characters: [],
      effects: [],
      mapIconSrc: null,
      isRepeatable: false
    };
    onUpdateScenes([...scenes, newScene]);
  };

  const updateScene = (id: string, updates: Partial<Scene>) => {
    onUpdateScenes(scenes.map(s => s.id === id ? { ...s, ...updates } : s));
  };

  const handleSceneIconUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { mapIconSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleEffect = (sceneId: string, type: 'scene' | 'transition' | 'battle', targetId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const currentEffects = scene.effects || [];
    const existingEffect = currentEffects.find(u => u.type === type && u.targetId === targetId);

    let newEffects: SceneEffect[];

    if (!existingEffect) {
        newEffects = [...currentEffects, { type, targetId, action: 'unlock' }];
    } else if (existingEffect.action === 'unlock' || !existingEffect.action) {
        newEffects = currentEffects.map(eff => 
            (eff.type === type && eff.targetId === targetId) ? { ...eff, action: 'lock' } : eff
        );
    } else {
        newEffects = currentEffects.filter(u => !(u.type === type && u.targetId === targetId));
    }

    updateScene(sceneId, { effects: newEffects });
  };

  const handleBgUpload = (id: string, e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateScene(id, { backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const toggleCharInScene = (sceneId: string, charId: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const exists = scene.characters.find(c => c.characterId === charId);
    let newChars: SceneCharacterConfig[];

    if (exists) {
      newChars = scene.characters.filter(c => c.characterId !== charId);
    } else {
      newChars = [...scene.characters, { characterId: charId, roleInScene: 'Default behavior' }];
    }
    updateScene(sceneId, { characters: newChars });
  };

  const updateSceneCharRole = (sceneId: string, charId: string, role: string) => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;
    const newChars = scene.characters.map(c => c.characterId === charId ? { ...c, roleInScene: role } : c);
    updateScene(sceneId, { characters: newChars });
  };

  // --- Map Handlers ---

  const getCurrentMap = () => maps.find(m => m.id === activeMapId);

  const addMap = () => {
      const newMap: WorldMap = {
          id: crypto.randomUUID(),
          name: `Map ${maps.length + 1}`,
          backgroundSrc: null,
          spots: []
      };
      const newMaps = [...maps, newMap];
      onUpdateMaps(newMaps);
      setActiveMapId(newMap.id);
  };

  const deleteMap = (id: string) => {
      if (maps.length <= 1) {
          alert("You must have at least one map.");
          return;
      }
      const newMaps = maps.filter(m => m.id !== id);
      onUpdateMaps(newMaps);
      if (activeMapId === id) setActiveMapId(newMaps[0].id);
  };

  const updateCurrentMap = (updates: Partial<WorldMap>) => {
      onUpdateMaps(maps.map(m => m.id === activeMapId ? { ...m, ...updates } : m));
  };

  const handleMapBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCurrentMap({ backgroundSrc: reader.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const handleMapClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!selectedTool || !mapContainerRef.current) return;
    if ((e.target as HTMLElement).closest('.map-pin')) return;

    const rect = mapContainerRef.current.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;

    const currentMap = getCurrentMap();
    if (!currentMap) return;

    const newSpot: MapSpot = {
      id: crypto.randomUUID(),
      type: selectedTool.type,
      x, 
      y,
      sceneId: selectedTool.type === 'scene' ? selectedTool.id : undefined,
      targetMapId: selectedTool.type === 'transition' ? selectedTool.id : undefined,
      characterId: selectedTool.type === 'character' ? selectedTool.id : undefined,
      battleId: selectedTool.type === 'battle' ? selectedTool.id : undefined
    };

    updateCurrentMap({ spots: [...currentMap.spots, newSpot] });
  };

  const removeSpot = (spotId: string) => {
    const currentMap = getCurrentMap();
    if(!currentMap) return;
    updateCurrentMap({
      spots: currentMap.spots.filter(s => s.id !== spotId)
    });
  };

  // --- Toolbar Handlers ---

  const handleQuickSaveClick = async () => {
    setSaveStatus('saving');
    await onQuickSave();
    setSaveStatus('saved');
    setTimeout(() => setSaveStatus('idle'), 2000);
  };

  const handleImportClick = () => {
    importInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if(e.target.files && e.target.files[0]) {
        onImportProject(e.target.files[0]);
    }
    if(e.target.value) e.target.value = ''; 
  };

  const currentMap = getCurrentMap();

