                        <input className="bg-transparent text-xl font-bold outline-none placeholder-gray-600 focus:text-white transition-colors" value={scene.name} onChange={(e) => updateScene(scene.id, { name: e.target.value })} placeholder="Scene Name (e.g. Chapter 1)" />
                     </div>
                     <input className="w-full bg-gray-900/50 border-b border-gray-700 text-sm py-1 px-2 focus:border-indigo-500 outline-none transition-colors text-indigo-200" value={scene.locationName || ''} onChange={(e) => updateScene(scene.id, { locationName: e.target.value })} placeholder="Location Name (Visible to Player, e.g. 'Old Library')" />
                  </div>
                  <button onClick={() => onUpdateScenes(scenes.filter(s => s.id !== scene.id))} className="text-gray-500 hover:text-red-500 transition-colors p-1"><Trash2 size={18} /></button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                  {/* Visuals & Goal */}
                  <div className="space-y-4">
                    <div className="w-full h-40 bg-gray-950 rounded-lg border border-gray-600 overflow-hidden relative group shadow-inner">
                       {scene.backgroundSrc ? (
                          <img src={scene.backgroundSrc} alt="bg" className="w-full h-full object-contain bg-black" />
                       ) : (
                         <div className="w-full h-full flex items-center justify-center text-gray-500 gap-2"><ImageIcon size={24} /> No Background</div>
                       )}
                       <label className="absolute inset-0 flex items-center justify-center cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity bg-black/40">
                          <span className="bg-black/80 px-4 py-2 rounded hover:bg-black text-sm border border-gray-600">Change Background</span>
                          <input type="file" accept="image/*" className="hidden" onChange={(e) => handleBgUpload(scene.id, e)} />
                       </label>
                    </div>

                    {/* ... (Existing Map Icon logic unchanged) ... */}

                    <div className="space-y-2">
                      <div className="flex justify-between items-center">
                          <label className="flex items-center gap-2 text-xs font-bold text-green-400"><Target size={14} /> WIN CONDITION</label>
                          <label className="flex items-center gap-2 text-[10px] text-gray-400 cursor-pointer select-none">
                            <input type="checkbox" className="accent-indigo-500" checked={scene.isRepeatable || false} onChange={(e) => updateScene(scene.id, { isRepeatable: e.target.checked })} />
                            <span className={scene.isRepeatable ? 'text-indigo-300 font-bold' : ''}>Repeatable?</span>
                          </label>
                      </div>
                      <textarea className="w-full bg-gray-900 border border-green-900/50 text-green-100 rounded px-3 py-2 text-sm focus:border-green-500 outline-none resize-none transition-all shadow-inner placeholder-gray-600" value={scene.goal} onChange={(e) => updateScene(scene.id, { goal: e.target.value })} placeholder="e.g. Find the key... (LEAVE EMPTY for endless conversation)" rows={3} />
                    </div>

                    <div className="bg-gray-900/50 p-3 rounded-lg border border-gray-700">
                        <label className="flex items-center gap-2 text-xs font-bold text-yellow-500 mb-2"><Unlock size={14} /> COMPLETION EFFECTS</label>
                        <div className="space-y-2 max-h-32 overflow-y-auto custom-scrollbar">
                            {scenes.filter(s => s.id !== scene.id).map(otherScene => {
                                const effect = scene.effects?.find(u => u.type === 'scene' && u.targetId === otherScene.id);
                                let stateClass = 'bg-gray-800 border-gray-700 text-gray-500';
                                let Icon = Lock;
                                if (effect?.action === 'unlock' || (effect && !effect.action)) { stateClass = 'bg-emerald-900/30 border-emerald-600 text-emerald-200'; Icon = Unlock; } else if (effect?.action === 'lock') { stateClass = 'bg-red-900/30 border-red-600 text-red-200'; Icon = Ban; }
                                return (<button key={otherScene.id} onClick={() => toggleEffect(scene.id, 'scene', otherScene.id)} className={`w-full flex items-center gap-2 text-xs p-1.5 rounded border transition-colors ${stateClass} hover:border-gray-400`}><Icon size={12} /><span className="truncate flex-1 text-left">Scene: {otherScene.name}</span>{effect?.action === 'unlock' && <span className="text-[10px] uppercase font-bold">Unlocks</span>}{effect?.action === 'lock' && <span className="text-[10px] uppercase font-bold">Locks</span>}</button>);
                            })}
                            {maps.map(m => {
                                const effect = scene.effects?.find(u => u.type === 'transition' && u.targetId === m.id);
                                let stateClass = 'bg-gray-800 border-gray-700 text-gray-500';
                                let Icon = Lock;
                                if (effect?.action === 'unlock' || (effect && !effect.action)) { stateClass = 'bg-emerald-900/30 border-emerald-600 text-emerald-200'; Icon = Globe; } else if (effect?.action === 'lock') { stateClass = 'bg-red-900/30 border-red-600 text-red-200'; Icon = Ban; }
                                return (<button key={m.id} onClick={() => toggleEffect(scene.id, 'transition', m.id)} className={`w-full flex items-center gap-2 text-xs p-1.5 rounded border transition-colors ${stateClass} hover:border-gray-400`}><Icon size={12} /><span className="truncate flex-1 text-left">Travel to: {m.name}</span>{effect?.action === 'unlock' && <span className="text-[10px] uppercase font-bold">Unlocks</span>}{effect?.action === 'lock' && <span className="text-[10px] uppercase font-bold">Locks</span>}</button>);
                            })}
                            {battles.map(b => {
                                const effect = scene.effects?.find(u => u.type === 'battle' && u.targetId === b.id);
                                let stateClass = 'bg-gray-800 border-gray-700 text-gray-500';
                                let Icon = Lock;
                                if (effect?.action === 'unlock' || (effect && !effect.action)) { stateClass = 'bg-red-900/30 border-red-600 text-red-200'; Icon = Sword; } else if (effect?.action === 'lock') { stateClass = 'bg-gray-800 border-gray-600 text-gray-500'; Icon = Ban; }
                                return (<button key={b.id} onClick={() => toggleEffect(scene.id, 'battle', b.id)} className={`w-full flex items-center gap-2 text-xs p-1.5 rounded border transition-colors ${stateClass} hover:border-gray-400`}><Icon size={12} /><span className="truncate flex-1 text-left">Battle: {b.name}</span>{effect?.action === 'unlock' && <span className="text-[10px] uppercase font-bold">Unlocks</span>}{effect?.action === 'lock' && <span className="text-[10px] uppercase font-bold">Locks</span>}</button>);
                            })}
                        </div>
                    </div>
                  </div>

                  {/* Narrative Setup (Unchanged) ... */}
                  <div className="space-y-2 lg:col-span-2 flex flex-col h-full">
                     <label className="block text-xs font-bold text-gray-400 flex items-center gap-2"><Eye size={14}/> VISIBLE DESCRIPTION (Intro text for Player & AI)</label>
                     <textarea
                        className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-2 text-sm focus:border-indigo-500 outline-none resize-none transition-all"
                        value={scene.description}
                        onChange={(e) => updateScene(scene.id, { description: e.target.value })}
                        placeholder="Describe the setting, the mood, and what is happening initially..."
                        rows={3}
                      />

                     <div className="space-y-4 mt-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <div>
                            <label className="block text-xs font-bold text-rose-400 flex items-center gap-2"><EyeOff size={14}/> HIDDEN AI INSTRUCTIONS</label>
                            <p className="text-[10px] text-gray-500 mb-1">Secrets, plot twists, behavior rules.</p>
                            <textarea
                                className="w-full bg-gray-900 border border-rose-900/50 text-rose-100 rounded px-3 py-2 text-sm focus:border-rose-500 outline-none resize-none transition-all shadow-inner placeholder-rose-900/50"
                                value={scene.aiInstructions || ''}
                                onChange={(e) => updateScene(scene.id, { aiInstructions: e.target.value })}
                                placeholder="e.g. 'Char X is lying about the key'..."
                                rows={2}
                              />
                          </div>
                          <div>
                            <label className="block text-xs font-bold text-sky-400 flex items-center gap-2"><Ear size={14}/> <Wind size={14}/> SENSORY DETAILS (AI Only)</label>
                            <p className="text-[10px] text-gray-500 mb-1">Smells, background sounds, atmosphere.</p>
                            <textarea
                                className="w-full bg-gray-900 border border-sky-900/50 text-sky-100 rounded px-3 py-2 text-sm focus:border-sky-500 outline-none resize-none transition-all shadow-inner placeholder-sky-900/50"
                                value={scene.sensoryDetails || ''}
                                onChange={(e) => updateScene(scene.id, { sensoryDetails: e.target.value })}
                                placeholder="e.g. 'Smell of ozone', 'Soft hum of machines'..."
                                rows={2}
                              />
                          </div>
                        </div>
                        <div>
                          <label className="block text-xs font-bold text-indigo-400 flex items-center gap-2"><Layout size={14}/> INTERNE RAUMBESCHREIBUNG (Ort/Raum/Umgebung)</label>
                          <p className="text-[10px] text-gray-500 mb-1">Layout, Positionen von Türen/Gegenständen, Architektur.</p>
                          <textarea
                              className="w-full bg-gray-900 border border-indigo-900/50 text-indigo-100 rounded px-3 py-2 text-sm focus:border-indigo-500 outline-none resize-none transition-all shadow-inner placeholder-indigo-900/50"
                              value={scene.environmentDetails || ''}
                              onChange={(e) => updateScene(scene.id, { environmentDetails: e.target.value })}
                              placeholder="e.g. 'Kleiner Raum, Tür im Norden, Kisten in der Ecke, Fenster rechts'..."
                              rows={2}
                            />
                        </div>
                     </div>

                      <label className="block text-xs font-bold text-gray-400 mt-4">PARTICIPATING CHARACTERS</label>
                      <div className="bg-gray-900 rounded-lg p-3 border border-gray-700 min-h-[100px] shadow-inner flex-1">
                         <div className="flex gap-2 flex-wrap mb-3">
                           {characters.map(char => {
                             const isActive = scene.characters.some(c => c.characterId === char.id);
                             return (<button key={char.id} onClick={() => toggleCharInScene(scene.id, char.id)} className={`text-xs px-3 py-1 rounded-full border transition-all ${isActive ? 'bg-indigo-600 border-indigo-400 text-white shadow-md' : 'bg-gray-800 border-gray-600 text-gray-400 hover:border-gray-400 hover:text-gray-300'}`}>{char.name}</button>)
                           })}
                           {characters.length === 0 && <span className="text-xs text-gray-600 italic">No characters created yet.</span>}
                         </div>
                         <div className="space-y-3">
                           {scene.characters.map(sc => {
                             const char = characters.find(c => c.id === sc.characterId);
                             if (!char) return null;
                             return (
                               <div key={sc.characterId} className="flex items-center gap-3 bg-gray-800 p-2 rounded border border-gray-700">
                                 <div className="w-8 h-8 rounded-full bg-gray-700 overflow-hidden flex-shrink-0 border border-gray-600" style={{ backgroundColor: char.rpgColor }}>{char.imageSrc && <img src={char.imageSrc} className="w-full h-full object-cover" />}</div>
                                 <div className="flex-1"><div className="text-xs font-bold text-indigo-300">{char.name} Role</div><input className="w-full bg-transparent border-b border-gray-600 text-xs py-1 focus:border-indigo-400 outline-none transition-colors" placeholder="What does this character want in this scene?" value={sc.roleInScene} onChange={(e) => updateSceneCharRole(scene.id, sc.characterId, e.target.value)} /></div>
                               </div>
                             )
                           })}
                         </div>
                      </div>
                  </div>
                </div>
              </div>
            ))}
            <Button onClick={addScene} variant="secondary" className="w-full py-4 border-dashed opacity-70 hover:opacity-100"><Plus size={20} /> Add Scenario</Button>
          </div>
        )}

        {/* MAP TAB */}
        {activeTab === 'map' && (
          <div className="flex flex-col lg:flex-row gap-6 h-full">
            <div className="w-full lg:w-64 flex flex-col gap-6">
              <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 shadow-lg space-y-3">
                  <div className="flex items-center justify-between mb-2"><h3 className="font-bold text-gray-300 flex items-center gap-2"><Globe size={16}/> Maps</h3><button onClick={addMap} className="text-indigo-400 hover:text-white p-1 rounded bg-indigo-900/30 hover:bg-indigo-600 transition"><Plus size={14} /></button></div>
                  <div className="space-y-2 max-h-32 overflow-y-auto custom-scrollbar">{maps.map(m => (<div key={m.id} className={`flex items-center justify-between p-2 rounded cursor-pointer border ${m.id === activeMapId ? 'bg-indigo-900/50 border-indigo-500' : 'bg-gray-900 border-gray-800 hover:border-gray-600'}`} onClick={() => setActiveMapId(m.id)}><span className="text-xs truncate max-w-[120px]">{m.name}</span>{maps.length > 1 && (<button onClick={(e) => { e.stopPropagation(); deleteMap(m.id); }} className="text-gray-600 hover:text-red-400"><Trash2 size={12} /></button>)}</div>))}</div>
                  {currentMap && (<div className="pt-2 border-t border-gray-700"><input className="w-full bg-gray-900 border border-gray-600 rounded px-2 py-1 text-xs text-gray-200 outline-none focus:border-indigo-500" value={currentMap.name} onChange={(e) => updateCurrentMap({ name: e.target.value })} placeholder="Map Name" /></div>)}
              </div>
              {currentMap && (<div className="bg-gray-800 p-4 rounded-xl border border-gray-700 shadow-lg"><h3 className="font-bold text-gray-300 mb-3 flex items-center gap-2 text-sm"><MapIcon size={14}/> Background</h3><label className="block w-full cursor-pointer bg-gray-900 border border-gray-600 hover:border-gray-400 hover:bg-gray-800 text-center py-4 rounded-lg border-dashed transition-all group"><span className="text-xs text-gray-400 group-hover:text-white">Change Image</span><input type="file" accept="image/*" className="hidden" onChange={handleMapBgUpload} /></label></div>)}
              <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 flex-1 shadow-lg flex flex-col min-h-[300px]">
                 <h3 className="font-bold text-gray-300 mb-3 flex items-center gap-2 text-sm"><User size={14}/> Place Items</h3>
                 <div className="space-y-4 overflow-y-auto custom-scrollbar flex-1">
                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2">Scenarios</div>
                        <div className="space-y-1">{scenes.map(scene => { let iconSrc = scene.mapIconSrc; let bgColor = '#4b5563'; if (!iconSrc && scene.characters.length > 0) { const char = characters.find(c => c.id === scene.characters[0].characterId); if(char) { iconSrc = char.mapSpriteSrc; bgColor = char.rpgColor; } } return (<button key={scene.id} onClick={() => setSelectedTool(selectedTool?.id === scene.id ? null : { type: 'scene', id: scene.id })} className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === scene.id && selectedTool.type === 'scene' ? 'bg-indigo-600/20 border-indigo-500 ring-1 ring-indigo-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}><div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 overflow-hidden flex items-center justify-center flex-shrink-0" style={{ backgroundColor: bgColor }}>{iconSrc ? <img src={iconSrc} className="w-full h-full object-contain" /> : <MessageSquare size={12} className="text-gray-400"/>}</div><span className="text-xs font-medium truncate flex-1 text-left">{scene.name}</span>{selectedTool?.id === scene.id && selectedTool.type === 'scene' && <MousePointerClick size={12} className="ml-auto text-indigo-400"/>}</button>); })}</div>
                    </div>
                    {/* BATTLES TOOL LIST */}
                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2 mt-4">Battles</div>
                        <div className="space-y-1">{battles.map(battle => (<button key={battle.id} onClick={() => setSelectedTool(selectedTool?.id === battle.id ? null : { type: 'battle', id: battle.id })} className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === battle.id && selectedTool.type === 'battle' ? 'bg-red-600/20 border-red-500 ring-1 ring-red-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}><div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 overflow-hidden flex items-center justify-center flex-shrink-0 text-red-500"><Sword size={14}/></div><span className="text-xs font-medium truncate flex-1 text-left">{battle.name}</span>{selectedTool?.id === battle.id && selectedTool.type === 'battle' && <MousePointerClick size={12} className="ml-auto text-red-400"/>}</button>))}</div>
                    </div>

                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2 mt-4">Characters</div>
                        <div className="space-y-1">{characters.map(char => (<button key={char.id} onClick={() => setSelectedTool(selectedTool?.id === char.id ? null : { type: 'character', id: char.id })} className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === char.id && selectedTool.type === 'character' ? 'bg-indigo-600/20 border-indigo-500 ring-1 ring-indigo-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}><div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 overflow-hidden flex items-center justify-center flex-shrink-0" style={{ backgroundColor: char.rpgColor }}>{char.mapSpriteSrc ? <img src={char.mapSpriteSrc} className="w-full h-full object-contain" /> : null}</div><span className="text-xs font-medium truncate flex-1 text-left">{char.name}</span>{selectedTool?.id === char.id && selectedTool.type === 'character' && <MousePointerClick size={12} className="ml-auto text-indigo-400"/>}</button>))}</div>
                    </div>
                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2 mt-4">Map Transitions</div>
                        <div className="space-y-1">{maps.filter(m => m.id !== activeMapId).map(targetMap => (<button key={targetMap.id} onClick={() => setSelectedTool(selectedTool?.id === targetMap.id ? null : { type: 'transition', id: targetMap.id })} className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === targetMap.id && selectedTool.type === 'transition' ? 'bg-emerald-600/20 border-emerald-500 ring-1 ring-emerald-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}><div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 flex items-center justify-center flex-shrink-0 text-emerald-500"><Waypoints size={14} /></div><span className="text-xs font-medium truncate flex-1 text-left">To: {targetMap.name}</span>{selectedTool?.id === targetMap.id && selectedTool.type === 'transition' && <MousePointerClick size={12} className="ml-auto text-emerald-400"/>}</button>))}</div>
                    </div>
                 </div>
              </div>
            </div>
            <div className="flex-1 bg-gray-900 rounded-xl border-[4px] border-gray-800 shadow-2xl overflow-hidden relative group">
                {currentMap && currentMap.backgroundSrc ? (<div ref={mapContainerRef} onClick={handleMapClick} className="relative w-full h-full cursor-crosshair"><img src={currentMap.backgroundSrc} alt="World Map" className="w-full h-full object-contain bg-black select-none pointer-events-none" />{currentMap.spots.map(spot => { 
                    if (spot.type === 'scene') { 
                        // ... existing scene logic ...
                        const scene = scenes.find(s => s.id === spot.sceneId); 
                        let iconSrc = scene?.mapIconSrc; let bgColor = '#ffffff'; let name = scene?.name || 'Unknown Scene'; 
                        if (scene && !iconSrc && scene.characters.length > 0) { const char = characters.find(c => c.id === scene.characters[0].characterId); if(char) { iconSrc = char.mapSpriteSrc; bgColor = char.rpgColor; } } 
                        return (
                          <div key={spot.id} className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin" style={{ left: `${spot.x}%`, top: `${spot.y}%` }}>
                            <div className="relative drop-shadow-lg transition hover:scale-110 flex items-center justify-center">
                              {iconSrc ? (<div className="w-12 h-12"><img src={iconSrc} alt={name} className="w-full h-full object-contain" /></div>) : (<div className="w-10 h-10 rounded-lg border-2 border-white shadow-md flex items-center justify-center bg-indigo-600 text-white" title={name}><MessageSquare size={20} fill="currentColor" /></div>)}
                            </div>
                            <span className="bg-black/70 text-[10px] px-2 rounded text-white whitespace-nowrap mt-1 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none backdrop-blur-sm">{name}</span>
                            <button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110"><Trash2 size={12} /></button>
                          </div>
                        ) 
                    } else if (spot.type === 'battle') {
                        const battle = battles.find(b => b.id === spot.battleId);
                        const name = battle?.name || 'Unknown Battle';
                        return (
                          <div key={spot.id} className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin" style={{ left: `${spot.x}%`, top: `${spot.y}%` }}>
                            <div className="relative drop-shadow-lg transition hover:scale-110 flex items-center justify-center animate-pulse">
                              <div className="w-10 h-10 rounded-lg border-2 border-red-400 shadow-md flex items-center justify-center bg-red-900 text-white" title={name}><Sword size={20} /></div>
                            </div>
                            <span className="bg-red-900/90 border border-red-500 text-[10px] px-2 rounded text-white whitespace-nowrap mt-1 opacity-100 pointer-events-none backdrop-blur-sm font-bold tracking-wider">BATTLE</span>
                            <button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110"><Trash2 size={12} /></button>
                          </div>
                        )
                    } else if (spot.type === 'character') { 
                        // ... existing char logic ...
                        const char = characters.find(c => c.id === spot.characterId); const name = char?.name || 'Unknown'; 
                        return (<div key={spot.id} className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin" style={{ left: `${spot.x}%`, top: `${spot.y}%` }}><div className="w-12 h-12 relative drop-shadow-lg transition hover:scale-110 flex items-center justify-center">{char?.mapSpriteSrc ? (<img src={char.mapSpriteSrc} alt={name} className="w-full h-full object-contain" />) : (<div className="w-4 h-4 rounded-full border border-white shadow-sm mb-1" style={{ backgroundColor: char?.rpgColor }} />)}</div><span className="bg-black/70 text-[10px] px-2 rounded text-white whitespace-nowrap mt-1 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none backdrop-blur-sm">{name}</span><button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110"><Trash2 size={12} /></button></div>) 
                    } else { 
                        // ... existing transition logic ...
                        const target = maps.find(m => m.id === spot.targetMapId); 
                        return (<div key={spot.id} className="map-pin absolute transform -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group/pin" style={{ left: `${spot.x}%`, top: `${spot.y}%` }}><div className="w-8 h-8 rounded-full bg-emerald-500/50 border-2 border-emerald-400 flex items-center justify-center shadow-lg hover:scale-110 transition"><Waypoints size={16} className="text-white" /></div><span className="bg-emerald-900/90 text-[10px] px-2 rounded text-emerald-100 whitespace-nowrap mt-1 opacity-100 transition-opacity pointer-events-none backdrop-blur-sm border border-emerald-700">Go to: {target?.name || 'Unknown'}</span><button onClick={(e) => { e.stopPropagation(); removeSpot(spot.id); }} className="absolute -top-4 right-0 text-red-500 opacity-0 group-hover/pin:opacity-100 hover:text-red-400 bg-black/50 rounded-full p-1 z-20 transition-all hover:scale-110"><Trash2 size={12} /></button></div>) 
                    } 
                })}</div>) : (<div className="w-full h-full flex flex-col items-center justify-center text-gray-600 gap-4"><MapIcon size={48} opacity={0.5} /><p>Upload a background for {currentMap ? currentMap.name : 'Unknown'}.</p></div>)}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Battle, Character, Zone } from '../types';
import { ActiveCombatant, rollTeamInitiative, performShockTest, resolveAttack, CombatLog, DetailedRoll } from '../utils/combat';
import { Button } from './ui/Button';
import { Sword, Target, Zap, Dice5, Play, Pause, Activity, ChevronDown, ChevronUp, List, X, Minimize2, Maximize2 } from 'lucide-react';

interface BattleArenaProps {
  battle: Battle;
  characters: Character[]; 
  onWin: () => void;
  onLose: () => void;
  onExit: () => void;
}

type BattlePhase = 'INIT' | 'COMMAND' | 'EXECUTION' | 'VICTORY' | 'DEFEAT';
type VisualState = 'idle' | 'prep' | 'hit';

interface FloatingText {
    id: string;
    text: string;
    type: 'damage' | 'heal' | 'miss' | 'crit';
    combatantId: string;
}

export const BattleArena: React.FC<BattleArenaProps> = ({ battle, characters, onWin, onLose, onExit }) => {
  const [phase, setPhase] = useState<BattlePhase>('INIT');
  const [combatants, setCombatants] = useState<ActiveCombatant[]>([]);
  const [turnQueue, setTurnQueue] = useState<string[]>([]); 
  const [logs, setLogs] = useState<CombatLog[]>([]);

  // Settings
  const [autoMode, setAutoMode] = useState(false); 
  const [isLogCollapsed, setIsLogCollapsed] = useState(false);

  // Command State
  const [selectedTargetId, setSelectedTargetId] = useState<string | null>(null);
  const [selectedZone, setSelectedZone] = useState<Zone>('torso');
  const [commands, setCommands] = useState<Record<string, { targetId: string, zone: Zone }>>({});

  // --- Visual States ---
  const [floatingTexts, setFloatingTexts] = useState<FloatingText[]>([]);

  // New: Track sprite state per combatant
  const [combatantVisuals, setCombatantVisuals] = useState<Record<string, VisualState>>({});

  const [animatingAttackerId, setAnimatingAttackerId] = useState<string | null>(null); // Still used for slide logic?
  const [animatingTargetId, setAnimatingTargetId] = useState<string | null>(null);

  // DICE VISUALS
  const [activeDice, setActiveDice] = useState<DetailedRoll[]>([]);
  const [showDice, setShowDice] = useState(false);
  const [diceLabel, setDiceLabel] = useState("");
  const [diceSubLabel, setDiceSubLabel] = useState(""); 

  // Control Flow State
  const [waitingForClick, setWaitingForClick] = useState(false);
  const resolveClickRef = useRef<(() => void) | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);

  const setVisualState = (id: string, state: VisualState) => {
      setCombatantVisuals(prev => ({ ...prev, [id]: state }));
  };

  const addFloatingText = (combatantId: string, text: string, type: FloatingText['type']) => {
      const id = crypto.randomUUID();
      setFloatingTexts(prev => [...prev, { id, text, type, combatantId }]);
      setTimeout(() => setFloatingTexts(prev => prev.filter(ft => ft.id !== id)), 1500);
  };

  const addLog = (text: string, type: CombatLog['type']) => {
    setLogs(prev => [...prev, { text, type }]);
  };

  // --- WAIT LOGIC ---
  const waitForInput = async (autoDelayMs: number = 800) => {
      if (autoMode) {
          return new Promise<void>(resolve => setTimeout(resolve, autoDelayMs));
      } else {
          setWaitingForClick(true);
          return new Promise<void>(resolve => {
              resolveClickRef.current = resolve;
          });
      }
  };

  const handleScreenClick = () => {
      if (waitingForClick && resolveClickRef.current) {
          setWaitingForClick(false);
          const resolver = resolveClickRef.current;
          resolveClickRef.current = null;
          resolver();
      }
  };

  // --- DICE ANIMATION HELPER ---
  const visualizeRolls = async (
      label: string, 
      subLabel: string, 
      rolls: DetailedRoll[], 
      isManualTrigger: boolean 
  ) => {
      setDiceLabel(label);
      setDiceSubLabel(subLabel);
      setActiveDice([]); 
      setShowDice(true);

      if (isManualTrigger && !autoMode) {
          setDiceLabel(`Ready to ${label}`);
          await waitForInput(0); 
      }

      setDiceLabel(label); 

      const duration = 600;
      const interval = 50;
      const steps = duration / interval;

      for(let i=0; i<steps; i++) {
          const fakeRolls = rolls.map(() => ({ roll: Math.floor(Math.random()*20)+1, total: 0 }));
          setActiveDice(fakeRolls);
          await new Promise(r => setTimeout(r, interval));
      }

      setActiveDice(rolls);
      await waitForInput(1500);
      setShowDice(false);
  };

  // Initialize Combat
  useEffect(() => {
    let mounted = true;

    const init = async () => {
      const parts: ActiveCombatant[] = [];
      [...battle.playerCharacterIds, ...battle.enemyCharacterIds].forEach(id => {
          const c = characters.find(char => char.id === id);
          if (c) {
              const team = battle.playerCharacterIds.includes(id) ? 'player' : 'enemy';
              parts.push({
                  ...c,
                  currentHp: c.stats?.hp || 20,
                  isShocked: false,
                  tempDefenseBonus: 0,
                  team,
                  stats: c.stats || { pra: 3, str: 3, wid: 3, ges: 3, wil: 3, hp: 20, maxHp: 20, limit: 10, weapon: { name: 'Hands', at: 3, mod: 0, dmg: 1, cap: null } }
              });
          }
      });

      if (!mounted) return;
      setCombatants(parts);

      const playerTeam = parts.filter(c => c.team === 'player');
      const enemyTeam = parts.filter(c => c.team === 'enemy');

      const pInit = rollTeamInitiative(playerTeam);
      const eInit = rollTeamInitiative(enemyTeam);

      await visualizeRolls("Player Initiative", `Best DEX: ${pInit.total - pInit.roll}`, [{ roll: pInit.roll, total: pInit.total }], true);
      await visualizeRolls("Enemy Initiative", `Best DEX: ${eInit.total - eInit.roll}`, [{ roll: eInit.roll, total: eInit.total }], false);

      addLog(`Initiative: Player ${pInit.total} vs Enemy ${eInit.total}`, 'info');

      if (pInit.total >= eInit.total) {
          startCommandPhase('player', parts);
      } else {
          startCommandPhase('enemy', parts);
      }
    };

    init();
    return () => { mounted = false; };
  }, [battle]);

  useEffect(() => {
      if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [logs, isLogCollapsed]);

  const startCommandPhase = (activeTeam: 'player' | 'enemy', currentCombatants: ActiveCombatant[]) => {
      setPhase('COMMAND');
      const teamMembers = currentCombatants.filter(c => c.team === activeTeam && c.currentHp > 0);
      setTurnQueue(teamMembers.map(c => c.id));
      setCommands({}); 

      if (activeTeam === 'enemy') {
          setTimeout(() => runEnemyAI(teamMembers, currentCombatants), 500);
      }
  };

  const runEnemyAI = (enemies: ActiveCombatant[], allCombatants: ActiveCombatant[]) => {
     const alivePlayers = allCombatants.filter(c => c.team === 'player' && c.currentHp > 0);
     if (alivePlayers.length === 0) {
         executePhase(enemies, {}, allCombatants);
         return;
     }
     const aiCommands: Record<string, { targetId: string, zone: Zone }> = {};
     enemies.forEach(e => {
         const target = alivePlayers[Math.floor(Math.random() * alivePlayers.length)];
         aiCommands[e.id] = { targetId: target.id, zone: 'torso' }; 
     });
     setCommands(aiCommands); 
     setTimeout(() => executePhase(enemies, aiCommands, allCombatants), 1000);
  };

  const handlePlayerCommand = (attackerId: string) => {
      if (!selectedTargetId) return;
      const newCommands = { ...commands, [attackerId]: { targetId: selectedTargetId, zone: selectedZone } };
      setCommands(newCommands);
      const nextQueue = turnQueue.filter(id => id !== attackerId);
      setTurnQueue(nextQueue);
      setSelectedTargetId(null);
      setSelectedZone('torso');
      if (nextQueue.length === 0) executePhase(combatants.filter(c => c.team === 'player'), newCommands, combatants);
  };

  const executePhase = async (
      actingTeam: ActiveCombatant[], 
      activeCommands: Record<string, { targetId: string, zone: Zone }>,
      currentCombatants: ActiveCombatant[]
  ) => {
      setPhase('EXECUTION');
      let workingState = [...currentCombatants]; 

      for (const actor of actingTeam) {
          const freshActor = workingState.find(c => c.id === actor.id);
          if (!freshActor || freshActor.currentHp <= 0) continue;
          const isPlayer = actor.team === 'player';

          // 1. Shock Test
          const shockResult = performShockTest(freshActor);
          if (shockResult.rollData) {
             await visualizeRolls("Shock Test", `Target Number: 15`, [shockResult.rollData], isPlayer);
             if (shockResult.log) addLog(shockResult.log, 'info');
             if (freshActor.currentHp < (freshActor.stats!.maxHp * 0.25)) {
                  workingState = workingState.map(c => c.id === actor.id ? { ...c, isShocked: shockResult.shocked } : c);
             }
             if (shockResult.shocked) {
                addFloatingText(actor.id, "SHOCKED", "miss");
                continue; 
             }
          }

          // 2. Attack Setup
          const cmd = activeCommands[actor.id];
          if (!cmd) continue;
          const target = workingState.find(c => c.id === cmd.targetId);
          if (!target || target.currentHp <= 0) continue;

          // --- VISUAL: PREPARE ATTACK (Frame Change + Slide) ---
          setVisualState(actor.id, 'prep');
          // For melee slide effect
          setAnimatingAttackerId(actor.id);
          await waitForInput(400); // Wait for the "Charge" visual

          // Calculate
          const result = resolveAttack(freshActor, target, cmd.zone);

          // --- VISUALIZE: ROLLS ---
          const targetIsPlayer = target.team === 'player';
          await visualizeRolls(`${target.name} Evades`, `Base TN (GES): ${target.stats!.ges}`, [result.defenseRoll], targetIsPlayer);
          await visualizeRolls(`${actor.name} Attacks`, `Target Number: ${result.defenseRoll.total}`, result.attackRolls, isPlayer);

          result.logs.forEach(l => {
              addLog(l.text, l.type); 
          });

          if (result.woundRolls.length > 0) {
              const threshold = 10 - (freshActor.stats!.str - target.stats!.wid);
              await visualizeRolls("Penetration Check", `Threshold: ${threshold}`, result.woundRolls, isPlayer);
          }

          // --- VISUAL: EXECUTE HIT (Frame Change) ---
          setVisualState(actor.id, 'hit');
          // Important: Damage text comes AFTER the hit frame is established

          if (result.damage > 0) {
              setAnimatingTargetId(target.id);
              addFloatingText(target.id, `-${result.damage}`, result.isCrit ? "crit" : "damage");
              workingState = workingState.map(c => c.id === target.id ? { ...c, currentHp: Math.max(0, c.currentHp - result.damage) } : c);
              setCombatants(workingState); 
              await waitForInput(600);
              setAnimatingTargetId(null);
          } else {
              addFloatingText(target.id, "MISS", "miss");
              await waitForInput(500);
          }

          // --- VISUAL: RETURN TO IDLE ---
          setVisualState(actor.id, 'idle');
          setAnimatingAttackerId(null); // Slide back
          await waitForInput(200); // Wait for slide back
      }

      const justActedTeam = actingTeam.length > 0 ? actingTeam[0].team : 'player'; 
      checkWinCondition(workingState, justActedTeam);
  };

  const checkWinCondition = (currentCombs: ActiveCombatant[], lastActiveTeam: 'player' | 'enemy') => {
      const playersAlive = currentCombs.some(c => c.team === 'player' && c.currentHp > 0);
      const enemiesAlive = currentCombs.some(c => c.team === 'enemy' && c.currentHp > 0);

      if (!playersAlive) {
          setPhase('DEFEAT');
          return;
      }
      if (!enemiesAlive) {
          setPhase('VICTORY');
          return;
      }
      if (lastActiveTeam === 'player') startCommandPhase('enemy', currentCombs);
      else startCommandPhase('player', currentCombs);
  };

  const renderCombatant = (c: ActiveCombatant) => {
      const isDead = c.currentHp <= 0;
      const isTurn = turnQueue.includes(c.id);
      const isSelected = selectedTargetId === c.id;
      const maxHp = c.stats?.maxHp || 1;
      const hpPct = (c.currentHp / maxHp) * 100;

      // Animation Logic
      const visualState = combatantVisuals[c.id] || 'idle';
      const isAttacking = animatingAttackerId === c.id; // Used for CSS Transform Slide
      const isHit = animatingTargetId === c.id;

      const myFloatingTexts = floatingTexts.filter(ft => ft.combatantId === c.id);

      // Determine Image Source & Scale based on State hierarchy
      let displaySrc = c.battleIdleSrc || c.imageSrc || c.mapSpriteSrc;
      let scale = c.battleIdleScale || c.battleScale || 1;

      if (visualState === 'prep' && c.battlePrepSrc) {
          displaySrc = c.battlePrepSrc;
          scale = c.battlePrepScale || c.battleScale || 1;
      }
      if (visualState === 'hit' && c.battleHitSrc) {
          displaySrc = c.battleHitSrc;
          scale = c.battleHitScale || c.battleScale || 1;
      }

      // CSS Classes
      const lungeClass = isAttacking 
         ? (c.team === 'player' ? 'translate-x-12' : '-translate-x-12') 
         : 'translate-x-0';
      const shakeClass = isHit ? 'animate-[shake_0.5s_ease-in-out]' : '';

      return (
          <div 
             key={c.id} 
             onClick={() => {
                 if (phase === 'COMMAND' && turnQueue.length > 0) {
                     const actorId = turnQueue[0];
                     const actor = combatants.find(a => a.id === actorId);
                     if (actor?.team === 'player' && c.team === 'enemy' && !isDead) {
                         setSelectedTargetId(c.id);
                     }
                 }
             }}
             className={`relative w-48 md:w-64 flex flex-col items-center transition-transform duration-300 ease-out transform ${lungeClass} ${shakeClass}
                ${isDead ? 'opacity-50 grayscale blur-[1px]' : ''}
                ${isTurn ? 'drop-shadow-[0_0_15px_rgba(255,255,255,0.4)]' : ''}
                ${isSelected ? 'ring-2 ring-red-500 rounded-xl bg-red-900/20' : ''}
                ${!isDead && c.team === 'enemy' && phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(x => x.id === turnQueue[0])?.team === 'player' ? 'cursor-pointer hover:bg-white/5 rounded-xl' : ''}
             `}
          >
              <div className="absolute top-10 left-0 right-0 z-50 pointer-events-none flex flex-col items-center">
                  {myFloatingTexts.map(ft => (
                      <div key={ft.id} className={`text-3xl font-black animate-[floatUp_1s_ease-out_forwards] stroke-black drop-shadow-md ${ft.type === 'damage' ? 'text-red-500' : ''} ${ft.type === 'crit' ? 'text-yellow-400 text-4xl' : ''} ${ft.type === 'miss' ? 'text-gray-400' : ''} ${ft.type === 'heal' ? 'text-green-500' : ''}`}>{ft.text}</div>
                  ))}
              </div>
              <div className="w-full max-w-[120px] h-3 bg-gray-800 rounded-full mb-2 overflow-hidden border border-gray-600 shadow-inner relative z-20">
                  <div className={`h-full transition-all duration-500 ease-out ${hpPct < 25 ? 'bg-red-600' : (hpPct < 50 ? 'bg-yellow-500' : 'bg-green-500')}`} style={{ width: `${hpPct}%` }} />
                  <div className="absolute inset-0 flex items-center justify-center text-[8px] font-bold text-white drop-shadow-md">{c.currentHp} / {maxHp}</div>
              </div>

              {/* Character Image Container - Much Larger Base Size */}
              <div className={`w-40 h-40 md:w-56 md:h-56 relative transition-all ${isHit ? 'brightness-150 saturate-0 sepia' : ''}`}>
                  {displaySrc ? (
                      <img 
                        src={displaySrc} 
                        className="w-full h-full object-contain filter drop-shadow-lg transition-transform duration-300 origin-bottom" 
                        style={{ transform: `scale(${scale})` }}
                      />
                  ) : (
                      <div className="w-full h-full bg-gray-700 rounded-full flex items-center justify-center text-xs text-center p-2 border-2 border-gray-500 shadow-xl">{c.name}</div>
                  )}
                  {c.isShocked && <div className="absolute top-0 right-0 text-yellow-400 bg-black/80 rounded-full p-2 animate-pulse z-30"><Zap size={24}/></div>}
              </div>

              <div className="bg-black/70 px-3 py-1 rounded text-xs mt-1 text-center min-w-[90px] backdrop-blur-sm border border-gray-700/50 relative z-20">
                  <div className="font-bold text-gray-200 truncate max-w-[120px]">{c.name}</div>
              </div>
          </div>
      );
  };

  const activePlayerCombatant = turnQueue.length > 0 ? combatants.find(c => c.id === turnQueue[0]) : null;
  const isPlayerTurn = phase === 'COMMAND' && activePlayerCombatant?.team === 'player';

  return (
    <div 
      className="fixed inset-0 z-[100] bg-black text-white flex flex-col font-sans select-none overflow-hidden"
      onClick={handleScreenClick} 
    >
       <style>{`
          @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-5px) rotate(-5deg); } 75% { transform: translateX(5px) rotate(5deg); } }
          @keyframes floatUp { 0% { transform: translateY(0) scale(1); opacity: 1; } 100% { transform: translateY(-40px) scale(1.2); opacity: 0; } }
       `}</style>

       {/* Top Bar / Header */}
       <div className="absolute top-0 left-0 right-0 z-40 p-4 flex justify-between items-center bg-gradient-to-b from-black/90 to-transparent pointer-events-none">
           <h2 className="text-2xl font-bold flex items-center gap-2 text-red-500 drop-shadow-md"><Sword size={24}/> {battle.name}</h2>
           <div className="flex items-center gap-4 pointer-events-auto">
               <button onClick={(e) => { e.stopPropagation(); setAutoMode(!autoMode); }} className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold border transition-all ${autoMode ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                   {autoMode ? <Play size={14} fill="currentColor"/> : <Pause size={14} fill="currentColor"/>} {autoMode ? 'AUTO' : 'MANUAL'}
               </button>
               <Button onClick={onExit} variant="secondary" className="text-xs py-1 border-red-900 text-red-200 hover:bg-red-900/20">Flee</Button>
           </div>
       </div>

       {/* FULL SCREEN BATTLE AREA */}
       <div className="relative w-full h-full flex items-center justify-center overflow-hidden">
           {/* Background */}
           <div className="absolute inset-0 z-0">
               {battle.backgroundSrc ? <img src={battle.backgroundSrc} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-red-950/40 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-gray-800 to-black" />}
               <div className="absolute inset-0 bg-black/20"></div>
           </div>

           {/* Characters Layer */}
           <div className="relative z-10 w-full max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between px-4 md:px-20 gap-8">
               <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'player').map(renderCombatant)}</div>

               {/* Center Status / Victory Messages */}
               <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-20">
                  {phase === 'VICTORY' && <div className="text-center animate-bounce pointer-events-auto bg-black/70 p-8 rounded-2xl backdrop-blur-xl border border-yellow-500/50 shadow-2xl"><h1 className="text-6xl font-black text-yellow-400 mb-4 drop-shadow-lg">VICTORY</h1><Button onClick={onWin} className="bg-yellow-600 hover:bg-yellow-500 text-xl px-12 py-4 font-bold shadow-lg shadow-yellow-900/50">Continue Journey</Button></div>}
                  {phase === 'DEFEAT' && <div className="text-center pointer-events-auto bg-black/70 p-8 rounded-2xl backdrop-blur-xl border border-red-500/50 shadow-2xl"><h1 className="text-6xl font-black text-red-600 mb-4 drop-shadow-lg">DEFEAT</h1><Button onClick={onLose} variant="danger" className="text-xl px-12 py-4 font-bold shadow-lg shadow-red-900/50">Try Again</Button></div>}
               </div>

               <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'enemy').map(renderCombatant)}</div>
           </div>

           {/* --- FLOATING UI LAYER --- */}

           {/* 1. Command Interface (Floating Bottom Center) */}
           {isPlayerTurn && (
              <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 z-30 w-[95%] max-w-2xl">
                 <div className="bg-black/70 backdrop-blur-md border border-indigo-500/30 rounded-2xl p-4 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300">
                    <div className="flex items-center justify-between mb-3 border-b border-white/10 pb-2">
                       <div className="text-lg font-bold text-indigo-300 flex items-center gap-2">
                          <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse shadow-[0_0_10px_#6366f1]"></div> 
                          Command: <span className="text-white">{activePlayerCombatant?.name}</span>
                       </div>
                       {!selectedTargetId && <div className="text-xs text-yellow-400 animate-pulse font-bold uppercase tracking-wider flex items-center gap-2"><Target size={14}/> Select Enemy Target</div>}
                    </div>

                    {selectedTargetId ? (
                        <div className="flex flex-col md:flex-row gap-4 items-center">
                            <div className="flex-1 flex gap-2 w-full overflow-x-auto pb-1 md:pb-0 custom-scrollbar justify-center">
                                {/* Horizontal Zone Selection */}
                                {[
                                    { id: 'torso', label: 'Torso', mod: 0 },
                                    { id: 'head', label: 'Head', mod: -6, color: 'text-red-300' },
                                    { id: 'arm', label: 'Arm', mod: -4 },
                                    { id: 'leg', label: 'Leg', mod: -3 }
                                ].map((z) => (
                                    <button 
                                        key={z.id}
                                        onClick={() => setSelectedZone(z.id as Zone)}
                                        className={`
                                            flex flex-col items-center justify-center px-4 py-2 rounded-lg border transition-all min-w-[80px]
                                            ${selectedZone === z.id 
                                                ? 'bg-indigo-600 border-indigo-400 text-white shadow-lg scale-105' 
                                                : 'bg-gray-800/50 border-gray-600 text-gray-400 hover:bg-gray-700 hover:text-white'
                                            }
                                        `}
                                    >
                                        <span className="font-bold text-sm">{z.label}</span>
                                        <span className={`text-[10px] ${z.color || 'opacity-50'}`}>{z.mod === 0 ? '-' : z.mod}</span>
                                    </button>
                                ))}
                            </div>
                            <Button onClick={() => handlePlayerCommand(turnQueue[0])} className="w-full md:w-auto bg-red-600 hover:bg-red-500 shadow-lg shadow-red-900/40 py-3 px-8 text-sm font-bold tracking-wider whitespace-nowrap h-full flex items-center gap-2">
                                <Sword size={18} className="animate-pulse"/> ATTACK
                            </Button>
                        </div>
                    ) : (
                        <div className="text-center text-gray-400 text-sm py-2 italic">
                            Click on an enemy sprite to target them.
                        </div>
                    )}
                 </div>
              </div>
           )}

           {/* 2. Floating Combat Log (Bottom Right) */}
           <div 
             className={`absolute bottom-4 right-4 z-30 bg-black/80 backdrop-blur-md border border-gray-700 shadow-2xl transition-all duration-300 ease-in-out overflow-hidden flex flex-col
                ${isLogCollapsed ? 'w-10 h-10 rounded-full cursor-pointer hover:bg-gray-800 hover:border-gray-500' : 'w-80 h-64 rounded-xl'}
             `}
             onClick={() => isLogCollapsed && setIsLogCollapsed(false)}
           >
               <div className={`flex items-center justify-between p-2 ${!isLogCollapsed ? 'border-b border-gray-700 bg-black/40' : 'h-full justify-center'}`}>
                   {!isLogCollapsed && <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2"><List size={12}/> Combat Log</span>}
                   <button 
                      onClick={(e) => { e.stopPropagation(); setIsLogCollapsed(!isLogCollapsed); }}
                      className="text-gray-400 hover:text-white transition-colors"
                   >
                       {isLogCollapsed ? <List size={16}/> : <Minimize2 size={14}/>}
                   </button>
               </div>

               {!isLogCollapsed && (
                   <div ref={scrollRef} className="flex-1 overflow-y-auto p-3 font-mono text-[10px] space-y-1 custom-scrollbar bg-black/20">
                       {logs.length === 0 && <div className="text-gray-600 italic text-center mt-4">Battle started...</div>}
                       {logs.map((log, i) => (
                           <div key={i} className={`leading-tight ${log.type === 'attack' ? 'text-blue-300' : ''} ${log.type === 'damage' ? 'text-red-400 font-bold' : ''} ${log.type === 'crit' ? 'text-yellow-400 font-bold' : ''} ${log.type === 'info' ? 'text-gray-500' : ''}`}>
                               {log.text}
                           </div>
                       ))}
                   </div>
               )}
           </div>

           {/* 3. Enemy Turn Indicator (Top Center Toast) */}
           {phase === 'COMMAND' && !isPlayerTurn && (
               <div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-30">
                   <div className="bg-black/60 backdrop-blur border border-red-500/30 text-red-200 px-6 py-2 rounded-full flex items-center gap-3 shadow-xl animate-pulse">
                       <Activity size={16} className="animate-spin"/> Enemy Turn
                   </div>
               </div>
           )}

       </div>

       {/* DICE OVERLAY (Unchanged logic, just ensure z-index is high) */}
       {showDice && (
           <div className="absolute inset-0 z-[60] flex items-center justify-center pointer-events-none">
               <div className="bg-black/80 backdrop-blur-md p-8 rounded-2xl flex flex-col items-center gap-4 animate-in zoom-in duration-300 border border-white/20 shadow-2xl min-w-[320px]">
                   <div className="text-xl font-bold uppercase tracking-widest text-white drop-shadow-md w-full text-center border-b border-gray-600 pb-2">{diceLabel}</div>
                   {diceSubLabel && <div className="text-sm text-gray-400 -mt-2">{diceSubLabel}</div>}
                   <div className="flex gap-4 flex-wrap justify-center">
                       {activeDice.length === 0 ? (
                           <div className="flex gap-2"><div className="w-16 h-16 rounded-lg bg-gray-800/50 border-2 border-dashed border-gray-500 flex items-center justify-center text-gray-500 font-bold">?</div></div>
                       ) : (
                           activeDice.map((d, i) => (
                               <div key={i} className={`w-16 h-16 flex items-center justify-center rounded-lg border-2 text-2xl font-bold shadow-lg animate-in slide-in-from-top-4 ${d.isSuccess ? 'bg-green-900 border-green-500 text-green-100' : 'bg-gray-800 border-gray-600 text-gray-400'} ${d.roll === 20 ? 'animate-bounce border-yellow-400 text-yellow-300 bg-yellow-900/50' : ''}`}>
                                   {d.total}
                                   {d.roll !== d.total && <span className="absolute bottom-1 right-1 text-[8px] opacity-60">raw:{d.roll}</span>}
                               </div>
                           ))
                       )}
                   </div>
               </div>
           </div>
       )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Battle, Character, Zone } from '../types';
import { ActiveCombatant, rollTeamInitiative, performShockTest, resolveAttack, CombatLog, DetailedRoll } from '../utils/combat';
import { Button } from './ui/Button';
import { Sword, Target, Zap, Dice5, Play, Pause, Activity, ChevronDown, ChevronUp, List, X, Minimize2, Maximize2 } from 'lucide-react';

interface BattleArenaProps {
  battle: Battle;
  characters: Character[]; 
  onWin: () => void;
  onLose: () => void;
  onExit: () => void;
}

type BattlePhase = 'INIT' | 'COMMAND' | 'EXECUTION' | 'VICTORY' | 'DEFEAT';
type VisualState = 'idle' | 'prep' | 'hit';

interface FloatingText {
    id: string;
    text: string;
    type: 'damage' | 'heal' | 'miss' | 'crit';
    combatantId: string;
}

export const BattleArena: React.FC<BattleArenaProps> = ({ battle, characters, onWin, onLose, onExit }) => {
  const [phase, setPhase] = useState<BattlePhase>('INIT');
  const [combatants, setCombatants] = useState<ActiveCombatant[]>([]);
  const [turnQueue, setTurnQueue] = useState<string[]>([]); 
  const [logs, setLogs] = useState<CombatLog[]>([]);

  // Settings
  const [autoMode, setAutoMode] = useState(false); 
  const [isLogCollapsed, setIsLogCollapsed] = useState(false);

  // Command State
  const [selectedTargetId, setSelectedTargetId] = useState<string | null>(null);
  const [selectedZone, setSelectedZone] = useState<Zone>('torso');
  const [commands, setCommands] = useState<Record<string, { targetId: string, zone: Zone }>>({});

  // --- Visual States ---
  const [floatingTexts, setFloatingTexts] = useState<FloatingText[]>([]);

  // New: Track sprite state per combatant
  const [combatantVisuals, setCombatantVisuals] = useState<Record<string, VisualState>>({});

  const [animatingAttackerId, setAnimatingAttackerId] = useState<string | null>(null); // Still used for slide logic?
  const [animatingTargetId, setAnimatingTargetId] = useState<string | null>(null);

  // DICE VISUALS
  const [activeDice, setActiveDice] = useState<DetailedRoll[]>([]);
  const [showDice, setShowDice] = useState(false);
  const [diceLabel, setDiceLabel] = useState("");
  const [diceSubLabel, setDiceSubLabel] = useState(""); 

  // Control Flow State
  const [waitingForClick, setWaitingForClick] = useState(false);
  const resolveClickRef = useRef<(() => void) | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);

  const setVisualState = (id: string, state: VisualState) => {
      setCombatantVisuals(prev => ({ ...prev, [id]: state }));
  };

  const addFloatingText = (combatantId: string, text: string, type: FloatingText['type']) => {
      const id = crypto.randomUUID();
      setFloatingTexts(prev => [...prev, { id, text, type, combatantId }]);
      setTimeout(() => setFloatingTexts(prev => prev.filter(ft => ft.id !== id)), 1500);
  };

  const addLog = (text: string, type: CombatLog['type']) => {
    setLogs(prev => [...prev, { text, type }]);
  };

  // --- WAIT LOGIC ---
  const waitForInput = async (autoDelayMs: number = 800) => {
      if (autoMode) {
          return new Promise<void>(resolve => setTimeout(resolve, autoDelayMs));
      } else {
          setWaitingForClick(true);
          return new Promise<void>(resolve => {
              resolveClickRef.current = resolve;
          });
      }
  };

  const handleScreenClick = () => {
      if (waitingForClick && resolveClickRef.current) {
          setWaitingForClick(false);
          const resolver = resolveClickRef.current;
          resolveClickRef.current = null;
          resolver();
      }
  };

  // --- DICE ANIMATION HELPER ---
  const visualizeRolls = async (
      label: string, 
      subLabel: string, 
      rolls: DetailedRoll[], 
      isManualTrigger: boolean 
  ) => {
      setDiceLabel(label);
      setDiceSubLabel(subLabel);
      setActiveDice([]); 
      setShowDice(true);

      if (isManualTrigger && !autoMode) {
          setDiceLabel(`Ready to ${label}`);
          await waitForInput(0); 
      }

      setDiceLabel(label); 

      const duration = 600;
      const interval = 50;
      const steps = duration / interval;

      for(let i=0; i<steps; i++) {
          const fakeRolls = rolls.map(() => ({ roll: Math.floor(Math.random()*20)+1, total: 0 }));
          setActiveDice(fakeRolls);
          await new Promise(r => setTimeout(r, interval));
      }

      setActiveDice(rolls);
      await waitForInput(1500);
      setShowDice(false);
  };

  // Initialize Combat
  useEffect(() => {
    let mounted = true;

    const init = async () => {
      const parts: ActiveCombatant[] = [];
      [...battle.playerCharacterIds, ...battle.enemyCharacterIds].forEach(id => {
          const c = characters.find(char => char.id === id);
          if (c) {
              const team = battle.playerCharacterIds.includes(id) ? 'player' : 'enemy';
              parts.push({
                  ...c,
                  currentHp: c.stats?.hp || 20,
                  isShocked: false,
                  tempDefenseBonus: 0,
                  team,
                  stats: c.stats || { pra: 3, str: 3, wid: 3, ges: 3, wil: 3, hp: 20, maxHp: 20, limit: 10, weapon: { name: 'Hands', at: 3, mod: 0, dmg: 1, cap: null } }
              });
          }
      });

      if (!mounted) return;
      setCombatants(parts);

      const playerTeam = parts.filter(c => c.team === 'player');
      const enemyTeam = parts.filter(c => c.team === 'enemy');

      const pInit = rollTeamInitiative(playerTeam);
      const eInit = rollTeamInitiative(enemyTeam);

      await visualizeRolls("Player Initiative", `Best DEX: ${pInit.total - pInit.roll}`, [{ roll: pInit.roll, total: pInit.total }], true);
      await visualizeRolls("Enemy Initiative", `Best DEX: ${eInit.total - eInit.roll}`, [{ roll: eInit.roll, total: eInit.total }], false);

      addLog(`Initiative: Player ${pInit.total} vs Enemy ${eInit.total}`, 'info');

      if (pInit.total >= eInit.total) {
          startCommandPhase('player', parts);
      } else {
          startCommandPhase('enemy', parts);
      }
    };

    init();
    return () => { mounted = false; };
  }, [battle]);

  useEffect(() => {
      if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [logs, isLogCollapsed]);

  const startCommandPhase = (activeTeam: 'player' | 'enemy', currentCombatants: ActiveCombatant[]) => {
      setPhase('COMMAND');
      const teamMembers = currentCombatants.filter(c => c.team === activeTeam && c.currentHp > 0);
      setTurnQueue(teamMembers.map(c => c.id));
      setCommands({}); 

      if (activeTeam === 'enemy') {
          setTimeout(() => runEnemyAI(teamMembers, currentCombatants), 500);
      }
  };

  const runEnemyAI = (enemies: ActiveCombatant[], allCombatants: ActiveCombatant[]) => {
     const alivePlayers = allCombatants.filter(c => c.team === 'player' && c.currentHp > 0);
     if (alivePlayers.length === 0) {
         executePhase(enemies, {}, allCombatants);
         return;
     }
     const aiCommands: Record<string, { targetId: string, zone: Zone }> = {};
     enemies.forEach(e => {
         const target = alivePlayers[Math.floor(Math.random() * alivePlayers.length)];
         aiCommands[e.id] = { targetId: target.id, zone: 'torso' }; 
     });
     setCommands(aiCommands); 
     setTimeout(() => executePhase(enemies, aiCommands, allCombatants), 1000);
  };

  const handlePlayerCommand = (attackerId: string) => {
      if (!selectedTargetId) return;
      const newCommands = { ...commands, [attackerId]: { targetId: selectedTargetId, zone: selectedZone } };
      setCommands(newCommands);
      const nextQueue = turnQueue.filter(id => id !== attackerId);
      setTurnQueue(nextQueue);
      setSelectedTargetId(null);
      setSelectedZone('torso');
      if (nextQueue.length === 0) executePhase(combatants.filter(c => c.team === 'player'), newCommands, combatants);
  };

  const executePhase = async (
      actingTeam: ActiveCombatant[], 
      activeCommands: Record<string, { targetId: string, zone: Zone }>,
      currentCombatants: ActiveCombatant[]
  ) => {
      setPhase('EXECUTION');
      let workingState = [...currentCombatants]; 

      for (const actor of actingTeam) {
          const freshActor = workingState.find(c => c.id === actor.id);
          if (!freshActor || freshActor.currentHp <= 0) continue;
          const isPlayer = actor.team === 'player';

          // 1. Shock Test
          const shockResult = performShockTest(freshActor);
          if (shockResult.rollData) {
             await visualizeRolls("Shock Test", `Target Number: 15`, [shockResult.rollData], isPlayer);
             if (shockResult.log) addLog(shockResult.log, 'info');
             if (freshActor.currentHp < (freshActor.stats!.maxHp * 0.25)) {
                  workingState = workingState.map(c => c.id === actor.id ? { ...c, isShocked: shockResult.shocked } : c);
             }
             if (shockResult.shocked) {
                addFloatingText(actor.id, "SHOCKED", "miss");
                continue; 
             }
          }

          // 2. Attack Setup
          const cmd = activeCommands[actor.id];
          if (!cmd) continue;
          const target = workingState.find(c => c.id === cmd.targetId);
          if (!target || target.currentHp <= 0) continue;

          // --- VISUAL: PREPARE ATTACK (Frame Change + Slide) ---
          setVisualState(actor.id, 'prep');
          // For melee slide effect (Still keep for prep, but not for hit anymore)
          setAnimatingAttackerId(actor.id);
          await waitForInput(400); // Wait for the "Charge" visual

          // Calculate
          const result = resolveAttack(freshActor, target, cmd.zone);

          // --- VISUALIZE: ROLLS ---
          const targetIsPlayer = target.team === 'player';
          await visualizeRolls(`${target.name} Evades`, `Base TN (GES): ${target.stats!.ges}`, [result.defenseRoll], targetIsPlayer);
          await visualizeRolls(`${actor.name} Attacks`, `Target Number: ${result.defenseRoll.total}`, result.attackRolls, isPlayer);

          result.logs.forEach(l => {
              addLog(l.text, l.type); 
          });

          if (result.woundRolls.length > 0) {
              const threshold = 10 - (freshActor.stats!.str - target.stats!.wid);
              await visualizeRolls("Penetration Check", `Threshold: ${threshold}`, result.woundRolls, isPlayer);
          }

          // --- VISUAL: EXECUTE HIT (Frame Change -> Center Screen) ---
          setVisualState(actor.id, 'hit');

          if (result.damage > 0) {
              setAnimatingTargetId(target.id);
              addFloatingText(target.id, `-${result.damage}`, result.isCrit ? "crit" : "damage");
              workingState = workingState.map(c => c.id === target.id ? { ...c, currentHp: Math.max(0, c.currentHp - result.damage) } : c);
              setCombatants(workingState); 
              await waitForInput(600); // Wait for hit impact
              setAnimatingTargetId(null);
          } else {
              addFloatingText(target.id, "MISS", "miss");
              await waitForInput(500);
          }

          // --- VISUAL: RETURN TO IDLE ---
          setVisualState(actor.id, 'idle');
          setAnimatingAttackerId(null); // Slide back
          await waitForInput(200); // Wait for slide back
      }

      const justActedTeam = actingTeam.length > 0 ? actingTeam[0].team : 'player'; 
      checkWinCondition(workingState, justActedTeam);
  };

  const checkWinCondition = (currentCombs: ActiveCombatant[], lastActiveTeam: 'player' | 'enemy') => {
      const playersAlive = currentCombs.some(c => c.team === 'player' && c.currentHp > 0);
      const enemiesAlive = currentCombs.some(c => c.team === 'enemy' && c.currentHp > 0);

      if (!playersAlive) {
          setPhase('DEFEAT');
          return;
      }
      if (!enemiesAlive) {
          setPhase('VICTORY');
          return;
      }
      if (lastActiveTeam === 'player') startCommandPhase('enemy', currentCombs);
      else startCommandPhase('player', currentCombs);
  };

  const renderCombatant = (c: ActiveCombatant) => {
      const isDead = c.currentHp <= 0;
      const isTurn = turnQueue.includes(c.id);
      const isSelected = selectedTargetId === c.id;
      const maxHp = c.stats?.maxHp || 1;
      const hpPct = (c.currentHp / maxHp) * 100;

      // Animation Logic
      const visualState = combatantVisuals[c.id] || 'idle';
      const isHitState = visualState === 'hit'; // Checking if currently in Center-Screen Mode

      // Lunge logic only applies if NOT hitting (since hitting is now center screen)
      const isAttacking = animatingAttackerId === c.id && visualState !== 'hit'; 
      const isHit = animatingTargetId === c.id;

      const myFloatingTexts = floatingTexts.filter(ft => ft.combatantId === c.id);

      // Determine Image Source & Scale based on State hierarchy
      let displaySrc = c.battleIdleSrc || c.imageSrc || c.mapSpriteSrc;
      let scale = c.battleIdleScale || c.battleScale || 1;

      if (visualState === 'prep' && c.battlePrepSrc) {
          displaySrc = c.battlePrepSrc;
          scale = c.battlePrepScale || c.battleScale || 1;
      }
      // Note: If visualState is 'hit', we STILL calculate src here to have a valid fallback, 
      // but the main rendering logic below will hide this instance.

      // CSS Classes
      const lungeClass = isAttacking 
         ? (c.team === 'player' ? 'translate-x-12' : '-translate-x-12') 
         : 'translate-x-0';
      const shakeClass = isHit ? 'animate-[shake_0.5s_ease-in-out]' : '';

      return (
          <div 
             key={c.id} 
             onClick={() => {
                 if (phase === 'COMMAND' && turnQueue.length > 0) {
                     const actorId = turnQueue[0];
                     const actor = combatants.find(a => a.id === actorId);
                     if (actor?.team === 'player' && c.team === 'enemy' && !isDead) {
                         setSelectedTargetId(c.id);
                     }
                 }
             }}
             className={`relative w-48 md:w-64 flex flex-col items-center transition-transform duration-300 ease-out transform ${lungeClass} ${shakeClass}
                ${isDead ? 'opacity-50 grayscale blur-[1px]' : ''}
                ${isTurn ? 'drop-shadow-[0_0_15px_rgba(255,255,255,0.4)]' : ''}
                ${isSelected ? 'ring-2 ring-red-500 rounded-xl bg-red-900/20' : ''}
                ${!isDead && c.team === 'enemy' && phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(x => x.id === turnQueue[0])?.team === 'player' ? 'cursor-pointer hover:bg-white/5 rounded-xl' : ''}
                ${isHitState ? 'opacity-0 pointer-events-none' : 'opacity-100'} 
             `}
          >
              <div className="absolute top-10 left-0 right-0 z-50 pointer-events-none flex flex-col items-center">
                  {myFloatingTexts.map(ft => (
                      <div key={ft.id} className={`text-3xl font-black animate-[floatUp_1s_ease-out_forwards] stroke-black drop-shadow-md ${ft.type === 'damage' ? 'text-red-500' : ''} ${ft.type === 'crit' ? 'text-yellow-400 text-4xl' : ''} ${ft.type === 'miss' ? 'text-gray-400' : ''} ${ft.type === 'heal' ? 'text-green-500' : ''}`}>{ft.text}</div>
                  ))}
              </div>
              <div className="w-full max-w-[120px] h-3 bg-gray-800 rounded-full mb-2 overflow-hidden border border-gray-600 shadow-inner relative z-20">
                  <div className={`h-full transition-all duration-500 ease-out ${hpPct < 25 ? 'bg-red-600' : (hpPct < 50 ? 'bg-yellow-500' : 'bg-green-500')}`} style={{ width: `${hpPct}%` }} />
                  <div className="absolute inset-0 flex items-center justify-center text-[8px] font-bold text-white drop-shadow-md">{c.currentHp} / {maxHp}</div>
              </div>

              {/* Character Image Container */}
              <div className={`w-40 h-40 md:w-56 md:h-56 relative transition-all ${isHit ? 'brightness-150 saturate-0 sepia' : ''}`}>
                  {displaySrc ? (
                      <img 
                        src={displaySrc} 
                        className="w-full h-full object-contain filter drop-shadow-lg transition-transform duration-300 origin-bottom" 
                        style={{ transform: `scale(${scale})` }}
                      />
                  ) : (
                      <div className="w-full h-full bg-gray-700 rounded-full flex items-center justify-center text-xs text-center p-2 border-2 border-gray-500 shadow-xl">{c.name}</div>
                  )}
                  {c.isShocked && <div className="absolute top-0 right-0 text-yellow-400 bg-black/80 rounded-full p-2 animate-pulse z-30"><Zap size={24}/></div>}
              </div>

              <div className="bg-black/70 px-3 py-1 rounded text-xs mt-1 text-center min-w-[90px] backdrop-blur-sm border border-gray-700/50 relative z-20">
                  <div className="font-bold text-gray-200 truncate max-w-[120px]">{c.name}</div>
              </div>
          </div>
      );
  };

  const activePlayerCombatant = turnQueue.length > 0 ? combatants.find(c => c.id === turnQueue[0]) : null;
  const isPlayerTurn = phase === 'COMMAND' && activePlayerCombatant?.team === 'player';

  // --- SPECIAL RENDERER FOR CENTER HIT SPRITE ---
  const activeHitterId = Object.keys(combatantVisuals).find(id => combatantVisuals[id] === 'hit');
  const activeHitter = activeHitterId ? combatants.find(c => c.id === activeHitterId) : null;

  return (
    <div 
      className="fixed inset-0 z-[100] bg-black text-white flex flex-col font-sans select-none overflow-hidden"
      onClick={handleScreenClick} 
    >
       <style>{`
          @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-5px) rotate(-5deg); } 75% { transform: translateX(5px) rotate(5deg); } }
          @keyframes floatUp { 0% { transform: translateY(0) scale(1); opacity: 1; } 100% { transform: translateY(-40px) scale(1.2); opacity: 0; } }
       `}</style>

       {/* Top Bar / Header */}
       <div className="absolute top-0 left-0 right-0 z-40 p-4 flex justify-between items-center bg-gradient-to-b from-black/90 to-transparent pointer-events-none">
           <h2 className="text-2xl font-bold flex items-center gap-2 text-red-500 drop-shadow-md"><Sword size={24}/> {battle.name}</h2>
           <div className="flex items-center gap-4 pointer-events-auto">
               <button onClick={(e) => { e.stopPropagation(); setAutoMode(!autoMode); }} className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold border transition-all ${autoMode ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                   {autoMode ? <Play size={14} fill="currentColor"/> : <Pause size={14} fill="currentColor"/>} {autoMode ? 'AUTO' : 'MANUAL'}
               </button>
               <Button onClick={onExit} variant="secondary" className="text-xs py-1 border-red-900 text-red-200 hover:bg-red-900/20">Flee</Button>
           </div>
       </div>

       {/* FULL SCREEN BATTLE AREA */}
       <div className="relative w-full h-full flex items-center justify-center overflow-hidden">
           {/* Background */}
           <div className="absolute inset-0 z-0">
               {battle.backgroundSrc ? <img src={battle.backgroundSrc} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-red-950/40 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-gray-800 to-black" />}
               <div className="absolute inset-0 bg-black/20"></div>
           </div>

           {/* Characters Layer (Regular List) */}
           <div className="relative z-10 w-full max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between px-4 md:px-20 gap-8">
               <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'player').map(renderCombatant)}</div>

               {/* Center Status / Victory Messages */}
               <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-20">
                  {phase === 'VICTORY' && <div className="text-center animate-bounce pointer-events-auto bg-black/70 p-8 rounded-2xl backdrop-blur-xl border border-yellow-500/50 shadow-2xl"><h1 className="text-6xl font-black text-yellow-400 mb-4 drop-shadow-lg">VICTORY</h1><Button onClick={onWin} className="bg-yellow-600 hover:bg-yellow-500 text-xl px-12 py-4 font-bold shadow-lg shadow-yellow-900/50">Continue Journey</Button></div>}
                  {phase === 'DEFEAT' && <div className="text-center pointer-events-auto bg-black/70 p-8 rounded-2xl backdrop-blur-xl border border-red-500/50 shadow-2xl"><h1 className="text-6xl font-black text-red-600 mb-4 drop-shadow-lg">DEFEAT</h1><Button onClick={onLose} variant="danger" className="text-xl px-12 py-4 font-bold shadow-lg shadow-red-900/50">Try Again</Button></div>}
               </div>

               <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'enemy').map(renderCombatant)}</div>
           </div>

           {/* --- CENTER HIT SPRITE OVERLAY --- */}
           {activeHitter && (
             <div className="absolute inset-0 z-40 flex items-center justify-center pointer-events-none animate-in zoom-in-75 duration-100">
                <div 
                  className="relative transition-transform" 
                  style={{ transform: `scale(${activeHitter.battleHitScale || activeHitter.battleScale || 1.2})` }}
                >
                    {activeHitter.battleHitSrc ? (
                        <img 
                            src={activeHitter.battleHitSrc} 
                            className="max-h-[80vh] w-auto object-contain drop-shadow-[0_0_50px_rgba(255,255,255,0.3)] filter brightness-110" 
                        />
                    ) : (
                        // Fallback if no hit sprite is defined but logic triggered (using Idle or default)
                        <img 
                            src={activeHitter.battleIdleSrc || activeHitter.imageSrc || activeHitter.mapSpriteSrc} 
                            className="max-h-[80vh] w-auto object-contain drop-shadow-[0_0_50px_rgba(255,255,255,0.3)] filter brightness-110"
                        />
                    )}
                </div>
             </div>
           )}

           {/* --- FLOATING UI LAYER --- */}

           {/* 1. Command Interface (Floating Bottom Center) */}
           {isPlayerTurn && (
              <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 z-30 w-[95%] max-w-2xl">
                 <div className="bg-black/70 backdrop-blur-md border border-indigo-500/30 rounded-2xl p-4 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300">
                    <div className="flex items-center justify-between mb-3 border-b border-white/10 pb-2">
                       <div className="text-lg font-bold text-indigo-300 flex items-center gap-2">
                          <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse shadow-[0_0_10px_#6366f1]"></div> 
                          Command: <span className="text-white">{activePlayerCombatant?.name}</span>
                       </div>
                       {!selectedTargetId && <div className="text-xs text-yellow-400 animate-pulse font-bold uppercase tracking-wider flex items-center gap-2"><Target size={14}/> Select Enemy Target</div>}
                    </div>

                    {selectedTargetId ? (
                        <div className="flex flex-col md:flex-row gap-4 items-center">
                            <div className="flex-1 flex gap-2 w-full overflow-x-auto pb-1 md:pb-0 custom-scrollbar justify-center">
                                {/* Horizontal Zone Selection */}
                                {[
                                    { id: 'torso', label: 'Torso', mod: 0 },
                                    { id: 'head', label: 'Head', mod: -6, color: 'text-red-300' },
                                    { id: 'arm', label: 'Arm', mod: -4 },
                                    { id: 'leg', label: 'Leg', mod: -3 }
                                ].map((z) => (
                                    <button 
                                        key={z.id}
                                        onClick={() => setSelectedZone(z.id as Zone)}
                                        className={`
                                            flex flex-col items-center justify-center px-4 py-2 rounded-lg border transition-all min-w-[80px]
                                            ${selectedZone === z.id 
                                                ? 'bg-indigo-600 border-indigo-400 text-white shadow-lg scale-105' 
                                                : 'bg-gray-800/50 border-gray-600 text-gray-400 hover:bg-gray-700 hover:text-white'
                                            }
                                        `}
                                    >
                                        <span className="font-bold text-sm">{z.label}</span>
                                        <span className={`text-[10px] ${z.color || 'opacity-50'}`}>{z.mod === 0 ? '-' : z.mod}</span>
                                    </button>
                                ))}
                            </div>
                            <Button onClick={() => handlePlayerCommand(turnQueue[0])} className="w-full md:w-auto bg-red-600 hover:bg-red-500 shadow-lg shadow-red-900/40 py-3 px-8 text-sm font-bold tracking-wider whitespace-nowrap h-full flex items-center gap-2">
                                <Sword size={18} className="animate-pulse"/> ATTACK
                            </Button>
                        </div>
                    ) : (
                        <div className="text-center text-gray-400 text-sm py-2 italic">
                            Click on an enemy sprite to target them.
                        </div>
                    )}
                 </div>
              </div>
           )}

           {/* 2. Floating Combat Log (Bottom Right) */}
           <div 
             className={`absolute bottom-4 right-4 z-30 bg-black/80 backdrop-blur-md border border-gray-700 shadow-2xl transition-all duration-300 ease-in-out overflow-hidden flex flex-col
                ${isLogCollapsed ? 'w-10 h-10 rounded-full cursor-pointer hover:bg-gray-800 hover:border-gray-500' : 'w-80 h-64 rounded-xl'}
             `}
             onClick={() => isLogCollapsed && setIsLogCollapsed(false)}
           >
               <div className={`flex items-center justify-between p-2 ${!isLogCollapsed ? 'border-b border-gray-700 bg-black/40' : 'h-full justify-center'}`}>
                   {!isLogCollapsed && <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2"><List size={12}/> Combat Log</span>}
                   <button 
                      onClick={(e) => { e.stopPropagation(); setIsLogCollapsed(!isLogCollapsed); }}
                      className="text-gray-400 hover:text-white transition-colors"
                   >
                       {isLogCollapsed ? <List size={16}/> : <Minimize2 size={14}/>}
                   </button>
               </div>

               {!isLogCollapsed && (
                   <div ref={scrollRef} className="flex-1 overflow-y-auto p-3 font-mono text-[10px] space-y-1 custom-scrollbar bg-black/20">
                       {logs.length === 0 && <div className="text-gray-600 italic text-center mt-4">Battle started...</div>}
                       {logs.map((log, i) => (
                           <div key={i} className={`leading-tight ${log.type === 'attack' ? 'text-blue-300' : ''} ${log.type === 'damage' ? 'text-red-400 font-bold' : ''} ${log.type === 'crit' ? 'text-yellow-400 font-bold' : ''} ${log.type === 'info' ? 'text-gray-500' : ''}`}>
                               {log.text}
                           </div>
                       ))}
                   </div>
               )}
           </div>

           {/* 3. Enemy Turn Indicator (Top Center Toast) */}
           {phase === 'COMMAND' && !isPlayerTurn && (
               <div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-30">
                   <div className="bg-black/60 backdrop-blur border border-red-500/30 text-red-200 px-6 py-2 rounded-full flex items-center gap-3 shadow-xl animate-pulse">
                       <Activity size={16} className="animate-spin"/> Enemy Turn
                   </div>
               </div>
           )}

       </div>

       {/* DICE OVERLAY (Unchanged logic, just ensure z-index is high) */}
       {showDice && (
           <div className="absolute inset-0 z-[60] flex items-center justify-center pointer-events-none">
               <div className="bg-black/80 backdrop-blur-md p-8 rounded-2xl flex flex-col items-center gap-4 animate-in zoom-in duration-300 border border-white/20 shadow-2xl min-w-[320px]">
                   <div className="text-xl font-bold uppercase tracking-widest text-white drop-shadow-md w-full text-center border-b border-gray-600 pb-2">{diceLabel}</div>
                   {diceSubLabel && <div className="text-sm text-gray-400 -mt-2">{diceSubLabel}</div>}
                   <div className="flex gap-4 flex-wrap justify-center">
                       {activeDice.length === 0 ? (
                           <div className="flex gap-2"><div className="w-16 h-16 rounded-lg bg-gray-800/50 border-2 border-dashed border-gray-500 flex items-center justify-center text-gray-500 font-bold">?</div></div>
                       ) : (
                           activeDice.map((d, i) => (
                               <div key={i} className={`w-16 h-16 flex items-center justify-center rounded-lg border-2 text-2xl font-bold shadow-lg animate-in slide-in-from-top-4 ${d.isSuccess ? 'bg-green-900 border-green-500 text-green-100' : 'bg-gray-800 border-gray-600 text-gray-400'} ${d.roll === 20 ? 'animate-bounce border-yellow-400 text-yellow-300 bg-yellow-900/50' : ''}`}>
                                   {d.total}
                                   {d.roll !== d.total && <span className="absolute bottom-1 right-1 text-[8px] opacity-60">raw:{d.roll}</span>}
                               </div>
                           ))
                       )}
                   </div>
               </div>
           </div>
       )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Battle, Character, Zone } from '../types';
import { ActiveCombatant, rollTeamInitiative, performShockTest, resolveAttack, CombatLog, DetailedRoll } from '../utils/combat';
import { Button } from './ui/Button';
import { Sword, Target, Zap, Dice5, Play, Pause, Activity, ChevronDown, ChevronUp, List, X, Minimize2, Maximize2 } from 'lucide-react';

interface BattleArenaProps {
  battle: Battle;
  characters: Character[]; 
  onWin: () => void;
  onLose: () => void;
  onExit: () => void;
}

type BattlePhase = 'INIT' | 'COMMAND' | 'EXECUTION' | 'VICTORY' | 'DEFEAT';
type VisualState = 'idle' | 'prep' | 'hit';

interface FloatingText {
    id: string;
    text: string;
    type: 'damage' | 'heal' | 'miss' | 'crit';
    combatantId: string;
}

export const BattleArena: React.FC<BattleArenaProps> = ({ battle, characters, onWin, onLose, onExit }) => {
  const [phase, setPhase] = useState<BattlePhase>('INIT');
  const [combatants, setCombatants] = useState<ActiveCombatant[]>([]);
  const [turnQueue, setTurnQueue] = useState<string[]>([]); 
  const [logs, setLogs] = useState<CombatLog[]>([]);

  // Settings
  const [autoMode, setAutoMode] = useState(false); 
  const [isLogCollapsed, setIsLogCollapsed] = useState(false);

  // Command State
  const [selectedTargetId, setSelectedTargetId] = useState<string | null>(null);
  const [selectedZone, setSelectedZone] = useState<Zone>('torso');
  const [commands, setCommands] = useState<Record<string, { targetId: string, zone: Zone }>>({});

  // --- Visual States ---
  const [floatingTexts, setFloatingTexts] = useState<FloatingText[]>([]);

  // New: Track sprite state per combatant
  const [combatantVisuals, setCombatantVisuals] = useState<Record<string, VisualState>>({});

  const [animatingAttackerId, setAnimatingAttackerId] = useState<string | null>(null); // Still used for slide logic?
  const [animatingTargetId, setAnimatingTargetId] = useState<string | null>(null);

  // DICE VISUALS
  const [activeDice, setActiveDice] = useState<DetailedRoll[]>([]);
  const [showDice, setShowDice] = useState(false);
  const [diceLabel, setDiceLabel] = useState("");
  const [diceSubLabel, setDiceSubLabel] = useState(""); 

  // Control Flow State
  const [waitingForClick, setWaitingForClick] = useState(false);
  const resolveClickRef = useRef<(() => void) | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);

  const setVisualState = (id: string, state: VisualState) => {
      setCombatantVisuals(prev => ({ ...prev, [id]: state }));
  };

  const addFloatingText = (combatantId: string, text: string, type: FloatingText['type']) => {
      const id = crypto.randomUUID();
      setFloatingTexts(prev => [...prev, { id, text, type, combatantId }]);
      setTimeout(() => setFloatingTexts(prev => prev.filter(ft => ft.id !== id)), 1500);
  };

  const addLog = (text: string, type: CombatLog['type']) => {
    setLogs(prev => [...prev, { text, type }]);
  };

  // --- WAIT LOGIC ---
  const waitForInput = async (autoDelayMs: number = 800) => {
      if (autoMode) {
          return new Promise<void>(resolve => setTimeout(resolve, autoDelayMs));
      } else {
          setWaitingForClick(true);
          return new Promise<void>(resolve => {
              resolveClickRef.current = resolve;
          });
      }
  };

  const handleScreenClick = () => {
      if (waitingForClick && resolveClickRef.current) {
          setWaitingForClick(false);
          const resolver = resolveClickRef.current;
          resolveClickRef.current = null;
          resolver();
      }
  };

  // --- DICE ANIMATION HELPER ---
  const visualizeRolls = async (
      label: string, 
      subLabel: string, 
      rolls: DetailedRoll[], 
      isManualTrigger: boolean 
  ) => {
      setDiceLabel(label);
      setDiceSubLabel(subLabel);
      setActiveDice([]); 
      setShowDice(true);

      if (isManualTrigger && !autoMode) {
          setDiceLabel(`Ready to ${label}`);
          await waitForInput(0); 
      }

      setDiceLabel(label); 

      const duration = 600;
      const interval = 50;
      const steps = duration / interval;

      for(let i=0; i<steps; i++) {
          const fakeRolls = rolls.map(() => ({ roll: Math.floor(Math.random()*20)+1, total: 0 }));
          setActiveDice(fakeRolls);
          await new Promise(r => setTimeout(r, interval));
      }

      setActiveDice(rolls);
      await waitForInput(1500);
      setShowDice(false);
  };

  // Initialize Combat
  useEffect(() => {
    let mounted = true;

    const init = async () => {
      const parts: ActiveCombatant[] = [];
      [...battle.playerCharacterIds, ...battle.enemyCharacterIds].forEach(id => {
          const c = characters.find(char => char.id === id);
          if (c) {
              const team = battle.playerCharacterIds.includes(id) ? 'player' : 'enemy';
              parts.push({
                  ...c,
                  currentHp: c.stats?.hp || 20,
                  isShocked: false,
                  tempDefenseBonus: 0,
                  team,
                  stats: c.stats || { pra: 3, str: 3, wid: 3, ges: 3, wil: 3, hp: 20, maxHp: 20, limit: 10, weapon: { name: 'Hands', at: 3, mod: 0, dmg: 1, cap: null } }
              });
          }
      });

      if (!mounted) return;
      setCombatants(parts);

      const playerTeam = parts.filter(c => c.team === 'player');
      const enemyTeam = parts.filter(c => c.team === 'enemy');

      const pInit = rollTeamInitiative(playerTeam);
      const eInit = rollTeamInitiative(enemyTeam);

      await visualizeRolls("Player Initiative", `Best DEX: ${pInit.total - pInit.roll}`, [{ roll: pInit.roll, total: pInit.total }], true);
      await visualizeRolls("Enemy Initiative", `Best DEX: ${eInit.total - eInit.roll}`, [{ roll: eInit.roll, total: eInit.total }], false);

      addLog(`Initiative: Player ${pInit.total} vs Enemy ${eInit.total}`, 'info');

      if (pInit.total >= eInit.total) {
          startCommandPhase('player', parts);
      } else {
          startCommandPhase('enemy', parts);
      }
    };

    init();
    return () => { mounted = false; };
  }, [battle]);

  useEffect(() => {
      if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [logs, isLogCollapsed]);

  const startCommandPhase = (activeTeam: 'player' | 'enemy', currentCombatants: ActiveCombatant[]) => {
      setPhase('COMMAND');
      const teamMembers = currentCombatants.filter(c => c.team === activeTeam && c.currentHp > 0);
      setTurnQueue(teamMembers.map(c => c.id));
      setCommands({}); 

      if (activeTeam === 'enemy') {
          setTimeout(() => runEnemyAI(teamMembers, currentCombatants), 500);
      }
  };

  const runEnemyAI = (enemies: ActiveCombatant[], allCombatants: ActiveCombatant[]) => {
     const alivePlayers = allCombatants.filter(c => c.team === 'player' && c.currentHp > 0);
     if (alivePlayers.length === 0) {
         executePhase(enemies, {}, allCombatants);
         return;
     }
     const aiCommands: Record<string, { targetId: string, zone: Zone }> = {};
     enemies.forEach(e => {
         const target = alivePlayers[Math.floor(Math.random() * alivePlayers.length)];
         aiCommands[e.id] = { targetId: target.id, zone: 'torso' }; 
     });
     setCommands(aiCommands); 
     setTimeout(() => executePhase(enemies, aiCommands, allCombatants), 1000);
  };

  const handlePlayerCommand = (attackerId: string) => {
      if (!selectedTargetId) return;
      const newCommands = { ...commands, [attackerId]: { targetId: selectedTargetId, zone: selectedZone } };
      setCommands(newCommands);
      const nextQueue = turnQueue.filter(id => id !== attackerId);
      setTurnQueue(nextQueue);
      setSelectedTargetId(null);
      setSelectedZone('torso');
      if (nextQueue.length === 0) executePhase(combatants.filter(c => c.team === 'player'), newCommands, combatants);
  };

  const executePhase = async (
      actingTeam: ActiveCombatant[], 
      activeCommands: Record<string, { targetId: string, zone: Zone }>,
      currentCombatants: ActiveCombatant[]
  ) => {
      setPhase('EXECUTION');
      let workingState = [...currentCombatants]; 

      for (const actor of actingTeam) {
          const freshActor = workingState.find(c => c.id === actor.id);
          if (!freshActor || freshActor.currentHp <= 0) continue;
          const isPlayer = actor.team === 'player';

          // 1. Shock Test
          const shockResult = performShockTest(freshActor);
          if (shockResult.rollData) {
             await visualizeRolls("Shock Test", `Target Number: 15`, [shockResult.rollData], isPlayer);
             if (shockResult.log) addLog(shockResult.log, 'info');
             if (freshActor.currentHp < (freshActor.stats!.maxHp * 0.25)) {
                  workingState = workingState.map(c => c.id === actor.id ? { ...c, isShocked: shockResult.shocked } : c);
             }
             if (shockResult.shocked) {
                addFloatingText(actor.id, "SHOCKED", "miss");
                continue; 
             }
          }

          // 2. Attack Setup
          const cmd = activeCommands[actor.id];
          if (!cmd) continue;
          const target = workingState.find(c => c.id === cmd.targetId);
          if (!target || target.currentHp <= 0) continue;

          // --- VISUAL: PREPARE ATTACK (Frame Change + Slide) ---
          setVisualState(actor.id, 'prep');
          // For melee slide effect (Still keep for prep, but not for hit anymore)
          setAnimatingAttackerId(actor.id);
          await waitForInput(400); // Wait for the "Charge" visual

          // Calculate
          const result = resolveAttack(freshActor, target, cmd.zone);

          // --- VISUALIZE: ROLLS ---
          const targetIsPlayer = target.team === 'player';
          await visualizeRolls(`${target.name} Evades`, `Base TN (GES): ${target.stats!.ges}`, [result.defenseRoll], targetIsPlayer);
          await visualizeRolls(`${actor.name} Attacks`, `Target Number: ${result.defenseRoll.total}`, result.attackRolls, isPlayer);

          result.logs.forEach(l => {
              addLog(l.text, l.type); 
          });

          if (result.woundRolls.length > 0) {
              const threshold = 10 - (freshActor.stats!.str - target.stats!.wid);
              await visualizeRolls("Penetration Check", `Threshold: ${threshold}`, result.woundRolls, isPlayer);
          }

          // --- VISUAL: EXECUTE HIT (Frame Change -> Center Screen) ---
          setVisualState(actor.id, 'hit');

          if (result.damage > 0) {
              setAnimatingTargetId(target.id);
              addFloatingText(target.id, `-${result.damage}`, result.isCrit ? "crit" : "damage");
              workingState = workingState.map(c => c.id === target.id ? { ...c, currentHp: Math.max(0, c.currentHp - result.damage) } : c);
              setCombatants(workingState); 
              await waitForInput(600); // Wait for hit impact
              setAnimatingTargetId(null);
          } else {
              addFloatingText(target.id, "MISS", "miss");
              await waitForInput(500);
          }

          // --- VISUAL: RETURN TO IDLE ---
          setVisualState(actor.id, 'idle');
          setAnimatingAttackerId(null); // Slide back
          await waitForInput(200); // Wait for slide back
      }

      const justActedTeam = actingTeam.length > 0 ? actingTeam[0].team : 'player'; 
      checkWinCondition(workingState, justActedTeam);
  };

  const checkWinCondition = (currentCombs: ActiveCombatant[], lastActiveTeam: 'player' | 'enemy') => {
      const playersAlive = currentCombs.some(c => c.team === 'player' && c.currentHp > 0);
      const enemiesAlive = currentCombs.some(c => c.team === 'enemy' && c.currentHp > 0);

      if (!playersAlive) {
          setPhase('DEFEAT');
          return;
      }
      if (!enemiesAlive) {
          setPhase('VICTORY');
          return;
      }
      if (lastActiveTeam === 'player') startCommandPhase('enemy', currentCombs);
      else startCommandPhase('player', currentCombs);
  };

  const renderCombatant = (c: ActiveCombatant) => {
      const isDead = c.currentHp <= 0;
      const isTurn = turnQueue.includes(c.id);
      const isSelected = selectedTargetId === c.id;
      const maxHp = c.stats?.maxHp || 1;
      const hpPct = (c.currentHp / maxHp) * 100;

      // Animation Logic
      const visualState = combatantVisuals[c.id] || 'idle';
      const isHitState = visualState === 'hit'; // Checking if currently in Center-Screen Mode

      // Lunge logic only applies if NOT hitting (since hitting is now center screen)
      const isAttacking = animatingAttackerId === c.id && visualState !== 'hit'; 
      const isHit = animatingTargetId === c.id;

      const myFloatingTexts = floatingTexts.filter(ft => ft.combatantId === c.id);

      // Determine Image Source & Scale based on State hierarchy
      let displaySrc = c.battleIdleSrc || c.imageSrc || c.mapSpriteSrc;
      let scale = c.battleIdleScale || c.battleScale || 1;

      if (visualState === 'prep' && c.battlePrepSrc) {
          displaySrc = c.battlePrepSrc;
          scale = c.battlePrepScale || c.battleScale || 1;
      }
      // Note: If visualState is 'hit', we STILL calculate src here to have a valid fallback, 
      // but the main rendering logic below will hide this instance.

      // CSS Classes
      const lungeClass = isAttacking 
         ? (c.team === 'player' ? 'translate-x-12' : '-translate-x-12') 
         : 'translate-x-0';
      const shakeClass = isHit ? 'animate-[shake_0.5s_ease-in-out]' : '';

      return (
          <div 
             key={c.id} 
             onClick={() => {
                 if (phase === 'COMMAND' && turnQueue.length > 0) {
                     const actorId = turnQueue[0];
                     const actor = combatants.find(a => a.id === actorId);
                     if (actor?.team === 'player' && c.team === 'enemy' && !isDead) {
                         setSelectedTargetId(c.id);
                     }
                 }
             }}
             className={`relative w-48 md:w-64 flex flex-col items-center transition-transform duration-300 ease-out transform ${lungeClass} ${shakeClass}
                ${isDead ? 'opacity-50 grayscale blur-[1px]' : ''}
                ${isTurn ? 'drop-shadow-[0_0_15px_rgba(255,255,255,0.4)]' : ''}
                ${isSelected ? 'ring-2 ring-red-500 rounded-xl bg-red-900/20' : ''}
                ${!isDead && c.team === 'enemy' && phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(x => x.id === turnQueue[0])?.team === 'player' ? 'cursor-pointer hover:bg-white/5 rounded-xl' : ''}
                ${isHitState ? 'opacity-0 pointer-events-none' : 'opacity-100'} 
             `}
          >
              <div className="absolute top-10 left-0 right-0 z-50 pointer-events-none flex flex-col items-center">
                  {myFloatingTexts.map(ft => (
                      <div key={ft.id} className={`text-3xl font-black animate-[floatUp_1s_ease-out_forwards] stroke-black drop-shadow-md ${ft.type === 'damage' ? 'text-red-500' : ''} ${ft.type === 'crit' ? 'text-yellow-400 text-4xl' : ''} ${ft.type === 'miss' ? 'text-gray-400' : ''} ${ft.type === 'heal' ? 'text-green-500' : ''}`}>{ft.text}</div>
                  ))}
              </div>

              {/* Character Image Container */}
              <div className={`w-40 h-40 md:w-56 md:h-56 relative transition-all ${isHit ? 'brightness-150 saturate-0 sepia' : ''}`}>
                  {displaySrc ? (
                      <img 
                        src={displaySrc} 
                        className="w-full h-full object-contain filter drop-shadow-lg transition-transform duration-300 origin-bottom" 
                        style={{ transform: `scale(${scale})` }}
                      />
                  ) : (
                      <div className="w-full h-full bg-gray-700 rounded-full flex items-center justify-center text-xs text-center p-2 border-2 border-gray-500 shadow-xl">{c.name}</div>
                  )}
                  {c.isShocked && <div className="absolute top-0 right-0 text-yellow-400 bg-black/80 rounded-full p-2 animate-pulse z-30"><Zap size={24}/></div>}
              </div>

              <div className="bg-black/70 px-3 py-1 rounded text-xs mt-1 text-center min-w-[90px] backdrop-blur-sm border border-gray-700/50 relative z-20">
                  <div className="font-bold text-gray-200 truncate max-w-[120px]">{c.name}</div>
              </div>

              {/* HP Bar */}
              <div className="w-full max-w-[120px] h-3 bg-gray-800 rounded-full mt-2 overflow-hidden border border-gray-600 shadow-inner relative z-20">
                  <div className={`h-full transition-all duration-500 ease-out ${hpPct < 25 ? 'bg-red-600' : (hpPct < 50 ? 'bg-yellow-500' : 'bg-green-500')}`} style={{ width: `${hpPct}%` }} />
                  <div className="absolute inset-0 flex items-center justify-center text-[8px] font-bold text-white drop-shadow-md">{c.currentHp} / {maxHp}</div>
              </div>
          </div>
      );
  };

  const activePlayerCombatant = turnQueue.length > 0 ? combatants.find(c => c.id === turnQueue[0]) : null;
  const isPlayerTurn = phase === 'COMMAND' && activePlayerCombatant?.team === 'player';

  // --- SPECIAL RENDERER FOR CENTER HIT SPRITE ---
  const activeHitterId = Object.keys(combatantVisuals).find(id => combatantVisuals[id] === 'hit');
  const activeHitter = activeHitterId ? combatants.find(c => c.id === activeHitterId) : null;

  return (
    <div 
      className="fixed inset-0 z-[100] bg-black text-white flex flex-col font-sans select-none overflow-hidden"
      onClick={handleScreenClick} 
    >
       <style>{`
          @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-5px) rotate(-5deg); } 75% { transform: translateX(5px) rotate(5deg); } }
          @keyframes floatUp { 0% { transform: translateY(0) scale(1); opacity: 1; } 100% { transform: translateY(-40px) scale(1.2); opacity: 0; } }
       `}</style>

       {/* Top Bar / Header */}
       <div className="absolute top-0 left-0 right-0 z-40 p-4 flex justify-between items-center bg-gradient-to-b from-black/90 to-transparent pointer-events-none">
           <h2 className="text-2xl font-bold flex items-center gap-2 text-red-500 drop-shadow-md"><Sword size={24}/> {battle.name}</h2>
           <div className="flex items-center gap-4 pointer-events-auto">
               <button onClick={(e) => { e.stopPropagation(); setAutoMode(!autoMode); }} className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold border transition-all ${autoMode ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                   {autoMode ? <Play size={14} fill="currentColor"/> : <Pause size={14} fill="currentColor"/>} {autoMode ? 'AUTO' : 'MANUAL'}
               </button>
               <Button onClick={onExit} variant="secondary" className="text-xs py-1 border-red-900 text-red-200 hover:bg-red-900/20">Flee</Button>
           </div>
       </div>

       {/* FULL SCREEN BATTLE AREA */}
       <div className="relative w-full h-full flex items-center justify-center overflow-hidden">
           {/* Background */}
           <div className="absolute inset-0 z-0">
               {battle.backgroundSrc ? <img src={battle.backgroundSrc} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-red-950/40 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-gray-800 to-black" />}
               <div className="absolute inset-0 bg-black/20"></div>
           </div>

           {/* Characters Layer (Regular List) */}
           <div className="relative z-10 w-full max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between px-4 md:px-20 gap-8">
               <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'player').map(renderCombatant)}</div>

               {/* Center Status / Victory Messages */}
               <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-20">
                  {phase === 'VICTORY' && <div className="text-center animate-bounce pointer-events-auto bg-black/70 p-8 rounded-2xl backdrop-blur-xl border border-yellow-500/50 shadow-2xl"><h1 className="text-6xl font-black text-yellow-400 mb-4 drop-shadow-lg">VICTORY</h1><Button onClick={onWin} className="bg-yellow-600 hover:bg-yellow-500 text-xl px-12 py-4 font-bold shadow-lg shadow-yellow-900/50">Continue Journey</Button></div>}
                  {phase === 'DEFEAT' && <div className="text-center pointer-events-auto bg-black/70 p-8 rounded-2xl backdrop-blur-xl border border-red-500/50 shadow-2xl"><h1 className="text-6xl font-black text-red-600 mb-4 drop-shadow-lg">DEFEAT</h1><Button onClick={onLose} variant="danger" className="text-xl px-12 py-4 font-bold shadow-lg shadow-red-900/50">Try Again</Button></div>}
               </div>

               <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'enemy').map(renderCombatant)}</div>
           </div>

           {/* --- CENTER HIT SPRITE OVERLAY --- */}
           {activeHitter && (
             <div className="absolute inset-0 z-40 flex items-center justify-center pointer-events-none animate-in zoom-in-75 duration-100">
                <div 
                  className="relative transition-transform" 
                  style={{ transform: `scale(${activeHitter.battleHitScale || activeHitter.battleScale || 1.2})` }}
                >
                    {activeHitter.battleHitSrc ? (
                        <img 
                            src={activeHitter.battleHitSrc} 
                            className="max-h-[80vh] w-auto object-contain drop-shadow-[0_0_50px_rgba(255,255,255,0.3)] filter brightness-110" 
                        />
                    ) : (
                        // Fallback if no hit sprite is defined but logic triggered (using Idle or default)
                        <img 
                            src={activeHitter.battleIdleSrc || activeHitter.imageSrc || activeHitter.mapSpriteSrc} 
                            className="max-h-[80vh] w-auto object-contain drop-shadow-[0_0_50px_rgba(255,255,255,0.3)] filter brightness-110"
                        />
                    )}
                </div>
             </div>
           )}

           {/* --- FLOATING UI LAYER --- */}

           {/* 1. Command Interface (Floating Bottom Center) */}
           {isPlayerTurn && (
              <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 z-30 w-[95%] max-w-2xl">
                 <div className="bg-black/70 backdrop-blur-md border border-indigo-500/30 rounded-2xl p-4 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300">
                    <div className="flex items-center justify-between mb-3 border-b border-white/10 pb-2">
                       <div className="text-lg font-bold text-indigo-300 flex items-center gap-2">
                          <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse shadow-[0_0_10px_#6366f1]"></div> 
                          Command: <span className="text-white">{activePlayerCombatant?.name}</span>
                       </div>
                       {!selectedTargetId && <div className="text-xs text-yellow-400 animate-pulse font-bold uppercase tracking-wider flex items-center gap-2"><Target size={14}/> Select Enemy Target</div>}
                    </div>

                    {selectedTargetId ? (
                        <div className="flex flex-col md:flex-row gap-4 items-center">
                            <div className="flex-1 flex gap-2 w-full overflow-x-auto pb-1 md:pb-0 custom-scrollbar justify-center">
                                {/* Horizontal Zone Selection */}
                                {[
                                    { id: 'torso', label: 'Torso', mod: 0 },
                                    { id: 'head', label: 'Head', mod: -6, color: 'text-red-300' },
                                    { id: 'arm', label: 'Arm', mod: -4 },
                                    { id: 'leg', label: 'Leg', mod: -3 }
                                ].map((z) => (
                                    <button 
                                        key={z.id}
                                        onClick={() => setSelectedZone(z.id as Zone)}
                                        className={`
                                            flex flex-col items-center justify-center px-4 py-2 rounded-lg border transition-all min-w-[80px]
                                            ${selectedZone === z.id 
                                                ? 'bg-indigo-600 border-indigo-400 text-white shadow-lg scale-105' 
                                                : 'bg-gray-800/50 border-gray-600 text-gray-400 hover:bg-gray-700 hover:text-white'
                                            }
                                        `}
                                    >
                                        <span className="font-bold text-sm">{z.label}</span>
                                        <span className={`text-[10px] ${z.color || 'opacity-50'}`}>{z.mod === 0 ? '-' : z.mod}</span>
                                    </button>
                                ))}
                            </div>
                            <Button onClick={() => handlePlayerCommand(turnQueue[0])} className="w-full md:w-auto bg-red-600 hover:bg-red-500 shadow-lg shadow-red-900/40 py-3 px-8 text-sm font-bold tracking-wider whitespace-nowrap h-full flex items-center gap-2">
                                <Sword size={18} className="animate-pulse"/> ATTACK
                            </Button>
                        </div>
                    ) : (
                        <div className="text-center text-gray-400 text-sm py-2 italic">
                            Click on an enemy sprite to target them.
                        </div>
                    )}
                 </div>
              </div>
           )}

           {/* 2. Floating Combat Log (Bottom Right) */}
           <div 
             className={`absolute bottom-4 right-4 z-30 bg-black/80 backdrop-blur-md border border-gray-700 shadow-2xl transition-all duration-300 ease-in-out overflow-hidden flex flex-col
                ${isLogCollapsed ? 'w-10 h-10 rounded-full cursor-pointer hover:bg-gray-800 hover:border-gray-500' : 'w-80 h-64 rounded-xl'}
             `}
             onClick={() => isLogCollapsed && setIsLogCollapsed(false)}
           >
               <div className={`flex items-center justify-between p-2 ${!isLogCollapsed ? 'border-b border-gray-700 bg-black/40' : 'h-full justify-center'}`}>
                   {!isLogCollapsed && <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2"><List size={12}/> Combat Log</span>}
                   <button 
                      onClick={(e) => { e.stopPropagation(); setIsLogCollapsed(!isLogCollapsed); }}
                      className="text-gray-400 hover:text-white transition-colors"
                   >
                       {isLogCollapsed ? <List size={16}/> : <Minimize2 size={14}/>}
                   </button>
               </div>

               {!isLogCollapsed && (
                   <div ref={scrollRef} className="flex-1 overflow-y-auto p-3 font-mono text-[10px] space-y-1 custom-scrollbar bg-black/20">
                       {logs.length === 0 && <div className="text-gray-600 italic text-center mt-4">Battle started...</div>}
                       {logs.map((log, i) => (
                           <div key={i} className={`leading-tight ${log.type === 'attack' ? 'text-blue-300' : ''} ${log.type === 'damage' ? 'text-red-400 font-bold' : ''} ${log.type === 'crit' ? 'text-yellow-400 font-bold' : ''} ${log.type === 'info' ? 'text-gray-500' : ''}`}>
                               {log.text}
                           </div>
                       ))}
                   </div>
               )}
           </div>

           {/* 3. Enemy Turn Indicator (Top Center Toast) */}
           {phase === 'COMMAND' && !isPlayerTurn && (
               <div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-30">
                   <div className="bg-black/60 backdrop-blur border border-red-500/30 text-red-200 px-6 py-2 rounded-full flex items-center gap-3 shadow-xl animate-pulse">
                       <Activity size={16} className="animate-spin"/> Enemy Turn
                   </div>
               </div>
           )}

       </div>

       {/* DICE OVERLAY (Unchanged logic, just ensure z-index is high) */}
       {showDice && (
           <div className="absolute inset-0 z-[60] flex items-center justify-center pointer-events-none">
               <div className="bg-black/80 backdrop-blur-md p-8 rounded-2xl flex flex-col items-center gap-4 animate-in zoom-in duration-300 border border-white/20 shadow-2xl min-w-[320px]">
                   <div className="text-xl font-bold uppercase tracking-widest text-white drop-shadow-md w-full text-center border-b border-gray-600 pb-2">{diceLabel}</div>
                   {diceSubLabel && <div className="text-sm text-gray-400 -mt-2">{diceSubLabel}</div>}
                   <div className="flex gap-4 flex-wrap justify-center">
                       {activeDice.length === 0 ? (
                           <div className="flex gap-2"><div className="w-16 h-16 rounded-lg bg-gray-800/50 border-2 border-dashed border-gray-500 flex items-center justify-center text-gray-500 font-bold">?</div></div>
                       ) : (
                           activeDice.map((d, i) => (
                               <div key={i} className={`w-16 h-16 flex items-center justify-center rounded-lg border-2 text-2xl font-bold shadow-lg animate-in slide-in-from-top-4 ${d.isSuccess ? 'bg-green-900 border-green-500 text-green-100' : 'bg-gray-800 border-gray-600 text-gray-400'} ${d.roll === 20 ? 'animate-bounce border-yellow-400 text-yellow-300 bg-yellow-900/50' : ''}`}>
                                   {d.total}
                                   {d.roll !== d.total && <span className="absolute bottom-1 right-1 text-[8px] opacity-60">raw:{d.roll}</span>}
                               </div>
                           ))
                       )}
                   </div>
               </div>
           </div>
       )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Battle, Character, Zone } from '../types';
import { ActiveCombatant, rollTeamInitiative, performShockTest, resolveAttack, CombatLog, DetailedRoll } from '../utils/combat';
import { Button } from './ui/Button';
import { Sword, Target, Zap, Dice5, Play, Pause, Activity, ChevronDown, ChevronUp, List, X, Minimize2, Maximize2 } from 'lucide-react';

interface BattleArenaProps {
  battle: Battle;
  characters: Character[]; 
  onWin: () => void;
  onLose: () => void;
  onExit: () => void;
}

type BattlePhase = 'INIT' | 'COMMAND' | 'EXECUTION' | 'VICTORY' | 'DEFEAT';
type VisualState = 'idle' | 'prep' | 'hit';

interface FloatingText {
    id: string;
    text: string;
    type: 'damage' | 'heal' | 'miss' | 'crit';
    combatantId: string;
}

export const BattleArena: React.FC<BattleArenaProps> = ({ battle, characters, onWin, onLose, onExit }) => {
  const [phase, setPhase] = useState<BattlePhase>('INIT');
  const [combatants, setCombatants] = useState<ActiveCombatant[]>([]);
  const [turnQueue, setTurnQueue] = useState<string[]>([]); 
  const [logs, setLogs] = useState<CombatLog[]>([]);

  // Settings
  const [autoMode, setAutoMode] = useState(false); 
  const [isLogCollapsed, setIsLogCollapsed] = useState(false);

  // Command State
  const [selectedTargetId, setSelectedTargetId] = useState<string | null>(null);
  const [selectedZone, setSelectedZone] = useState<Zone>('torso');
  const [commands, setCommands] = useState<Record<string, { targetId: string, zone: Zone }>>({});

  // --- Visual States ---
  const [floatingTexts, setFloatingTexts] = useState<FloatingText[]>([]);

  // New: Track sprite state per combatant
  const [combatantVisuals, setCombatantVisuals] = useState<Record<string, VisualState>>({});

  const [animatingAttackerId, setAnimatingAttackerId] = useState<string | null>(null); // Still used for slide logic?
  const [animatingTargetId, setAnimatingTargetId] = useState<string | null>(null);

  // DICE VISUALS
  const [activeDice, setActiveDice] = useState<DetailedRoll[]>([]);
  const [showDice, setShowDice] = useState(false);
  const [diceLabel, setDiceLabel] = useState("");
  const [diceSubLabel, setDiceSubLabel] = useState(""); 

  // Control Flow State
  const [waitingForClick, setWaitingForClick] = useState(false);
  const resolveClickRef = useRef<(() => void) | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);

  const setVisualState = (id: string, state: VisualState) => {
      setCombatantVisuals(prev => ({ ...prev, [id]: state }));
  };

  const addFloatingText = (combatantId: string, text: string, type: FloatingText['type']) => {
      const id = crypto.randomUUID();
      setFloatingTexts(prev => [...prev, { id, text, type, combatantId }]);
      setTimeout(() => setFloatingTexts(prev => prev.filter(ft => ft.id !== id)), 1500);
  };

  const addLog = (text: string, type: CombatLog['type']) => {
    setLogs(prev => [...prev, { text, type }]);
  };

  // --- WAIT LOGIC ---
  const waitForInput = async (autoDelayMs: number = 800) => {
      if (autoMode) {
          return new Promise<void>(resolve => setTimeout(resolve, autoDelayMs));
      } else {
          setWaitingForClick(true);
          return new Promise<void>(resolve => {
              resolveClickRef.current = resolve;
          });
      }
  };

  const handleScreenClick = () => {
      if (waitingForClick && resolveClickRef.current) {
          setWaitingForClick(false);
          const resolver = resolveClickRef.current;
          resolveClickRef.current = null;
          resolver();
      }
  };

  // --- DICE ANIMATION HELPER ---
  const visualizeRolls = async (
      label: string, 
      subLabel: string, 
      rolls: DetailedRoll[], 
      isManualTrigger: boolean 
  ) => {
      setDiceLabel(label);
      setDiceSubLabel(subLabel);
      setActiveDice([]); 
      setShowDice(true);

      if (isManualTrigger && !autoMode) {
          setDiceLabel(`Ready to ${label}`);
          await waitForInput(0); 
      }

      setDiceLabel(label); 

      const duration = 600;
      const interval = 50;
      const steps = duration / interval;

      for(let i=0; i<steps; i++) {
          const fakeRolls = rolls.map(() => ({ roll: Math.floor(Math.random()*20)+1, total: 0 }));
          setActiveDice(fakeRolls);
          await new Promise(r => setTimeout(r, interval));
      }

      setActiveDice(rolls);
      await waitForInput(1500);
      setShowDice(false);
  };

  // Initialize Combat
  useEffect(() => {
    let mounted = true;

    const init = async () => {
      const parts: ActiveCombatant[] = [];
      [...battle.playerCharacterIds, ...battle.enemyCharacterIds].forEach(id => {
          const c = characters.find(char => char.id === id);
          if (c) {
              const team = battle.playerCharacterIds.includes(id) ? 'player' : 'enemy';
              parts.push({
                  ...c,
                  currentHp: c.stats?.hp || 20,
                  isShocked: false,
                  tempDefenseBonus: 0,
                  team,
                  stats: c.stats || { pra: 3, str: 3, wid: 3, ges: 3, wil: 3, hp: 20, maxHp: 20, limit: 10, weapon: { name: 'Hands', at: 3, mod: 0, dmg: 1, cap: null } }
              });
          }
      });

      if (!mounted) return;
      setCombatants(parts);

      const playerTeam = parts.filter(c => c.team === 'player');
      const enemyTeam = parts.filter(c => c.team === 'enemy');

      const pInit = rollTeamInitiative(playerTeam);
      const eInit = rollTeamInitiative(enemyTeam);

      await visualizeRolls("Player Initiative", `Best DEX: ${pInit.total - pInit.roll}`, [{ roll: pInit.roll, total: pInit.total }], true);
      await visualizeRolls("Enemy Initiative", `Best DEX: ${eInit.total - eInit.roll}`, [{ roll: eInit.roll, total: eInit.total }], false);

      addLog(`Initiative: Player ${pInit.total} vs Enemy ${eInit.total}`, 'info');

      if (pInit.total >= eInit.total) {
          startCommandPhase('player', parts);
      } else {
          startCommandPhase('enemy', parts);
      }
    };

    init();
    return () => { mounted = false; };
  }, [battle]);

  useEffect(() => {
      if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [logs, isLogCollapsed]);

  const startCommandPhase = (activeTeam: 'player' | 'enemy', currentCombatants: ActiveCombatant[]) => {
      setPhase('COMMAND');
      const teamMembers = currentCombatants.filter(c => c.team === activeTeam && c.currentHp > 0);
      setTurnQueue(teamMembers.map(c => c.id));
      setCommands({}); 

      if (activeTeam === 'enemy') {
          setTimeout(() => runEnemyAI(teamMembers, currentCombatants), 500);
      }
  };

  const runEnemyAI = (enemies: ActiveCombatant[], allCombatants: ActiveCombatant[]) => {
     const alivePlayers = allCombatants.filter(c => c.team === 'player' && c.currentHp > 0);
     if (alivePlayers.length === 0) {
         executePhase(enemies, {}, allCombatants);
         return;
     }
     const aiCommands: Record<string, { targetId: string, zone: Zone }> = {};
     enemies.forEach(e => {
         const target = alivePlayers[Math.floor(Math.random() * alivePlayers.length)];
         aiCommands[e.id] = { targetId: target.id, zone: 'torso' }; 
     });
     setCommands(aiCommands); 
     setTimeout(() => executePhase(enemies, aiCommands, allCombatants), 1000);
  };

  const handlePlayerCommand = (attackerId: string) => {
      if (!selectedTargetId) return;
      const newCommands = { ...commands, [attackerId]: { targetId: selectedTargetId, zone: selectedZone } };
      setCommands(newCommands);
      const nextQueue = turnQueue.filter(id => id !== attackerId);
      setTurnQueue(nextQueue);
      setSelectedTargetId(null);
      setSelectedZone('torso');
      if (nextQueue.length === 0) executePhase(combatants.filter(c => c.team === 'player'), newCommands, combatants);
  };

  const executePhase = async (
      actingTeam: ActiveCombatant[], 
      activeCommands: Record<string, { targetId: string, zone: Zone }>,
      currentCombatants: ActiveCombatant[]
  ) => {
      setPhase('EXECUTION');
      let workingState = [...currentCombatants]; 

      for (const actor of actingTeam) {
          const freshActor = workingState.find(c => c.id === actor.id);
          if (!freshActor || freshActor.currentHp <= 0) continue;
          const isPlayer = actor.team === 'player';

          // 1. Shock Test
          const shockResult = performShockTest(freshActor);
          if (shockResult.rollData) {
             await visualizeRolls("Shock Test", `Target Number: 15`, [shockResult.rollData], isPlayer);
             if (shockResult.log) addLog(shockResult.log, 'info');
             if (freshActor.currentHp < (freshActor.stats!.maxHp * 0.25)) {
                  workingState = workingState.map(c => c.id === actor.id ? { ...c, isShocked: shockResult.shocked } : c);
             }
             if (shockResult.shocked) {
                addFloatingText(actor.id, "SHOCKED", "miss");
                continue; 
             }
          }

          // 2. Attack Setup
          const cmd = activeCommands[actor.id];
          if (!cmd) continue;
          const target = workingState.find(c => c.id === cmd.targetId);
          if (!target || target.currentHp <= 0) continue;

          // --- VISUAL: PREPARE ATTACK (Frame Change + Slide) ---
          setVisualState(actor.id, 'prep');
          // For melee slide effect (Still keep for prep, but not for hit anymore)
          setAnimatingAttackerId(actor.id);
          await waitForInput(400); // Wait for the "Charge" visual

          // Calculate
          const result = resolveAttack(freshActor, target, cmd.zone);

          // --- VISUALIZE: ROLLS ---
          const targetIsPlayer = target.team === 'player';
          await visualizeRolls(`${target.name} Evades`, `Base TN (GES): ${target.stats!.ges}`, [result.defenseRoll], targetIsPlayer);
          await visualizeRolls(`${actor.name} Attacks`, `Target Number: ${result.defenseRoll.total}`, result.attackRolls, isPlayer);

          result.logs.forEach(l => {
              addLog(l.text, l.type); 
          });

          if (result.woundRolls.length > 0) {
              const threshold = 10 - (freshActor.stats!.str - target.stats!.wid);
              await visualizeRolls("Penetration Check", `Threshold: ${threshold}`, result.woundRolls, isPlayer);
          }

          // --- VISUAL: EXECUTE HIT (Frame Change -> Center Screen) ---
          setVisualState(actor.id, 'hit');

          if (result.damage > 0) {
              setAnimatingTargetId(target.id);
              addFloatingText(target.id, `-${result.damage}`, result.isCrit ? "crit" : "damage");
              workingState = workingState.map(c => c.id === target.id ? { ...c, currentHp: Math.max(0, c.currentHp - result.damage) } : c);
              setCombatants(workingState); 
              await waitForInput(600); // Wait for hit impact
              setAnimatingTargetId(null);
          } else {
              addFloatingText(target.id, "MISS", "miss");
              await waitForInput(500);
          }

          // --- VISUAL: RETURN TO IDLE ---
          setVisualState(actor.id, 'idle');
          setAnimatingAttackerId(null); // Slide back
          await waitForInput(200); // Wait for slide back
      }

      const justActedTeam = actingTeam.length > 0 ? actingTeam[0].team : 'player'; 
      checkWinCondition(workingState, justActedTeam);
  };

  const checkWinCondition = (currentCombs: ActiveCombatant[], lastActiveTeam: 'player' | 'enemy') => {
      const playersAlive = currentCombs.some(c => c.team === 'player' && c.currentHp > 0);
      const enemiesAlive = currentCombs.some(c => c.team === 'enemy' && c.currentHp > 0);

      if (!playersAlive) {
          setPhase('DEFEAT');
          return;
      }
      if (!enemiesAlive) {
          setPhase('VICTORY');
          return;
      }
      if (lastActiveTeam === 'player') startCommandPhase('enemy', currentCombs);
      else startCommandPhase('player', currentCombs);
  };

  const renderCombatant = (c: ActiveCombatant) => {
      const isDead = c.currentHp <= 0;
      const isTurn = turnQueue.includes(c.id);
      const isSelected = selectedTargetId === c.id;
      const maxHp = c.stats?.maxHp || 1;
      const hpPct = (c.currentHp / maxHp) * 100;

      // Animation Logic
      const visualState = combatantVisuals[c.id] || 'idle';
      const isHitState = visualState === 'hit'; // Checking if currently in Center-Screen Mode

      // Lunge logic only applies if NOT hitting (since hitting is now center screen)
      const isAttacking = animatingAttackerId === c.id && visualState !== 'hit'; 
      const isHit = animatingTargetId === c.id;

      const myFloatingTexts = floatingTexts.filter(ft => ft.combatantId === c.id);

      // Determine Image Source & Scale based on State hierarchy
      let displaySrc = c.battleIdleSrc || c.imageSrc || c.mapSpriteSrc;
      let scale = c.battleIdleScale || c.battleScale || 1;

      if (visualState === 'prep' && c.battlePrepSrc) {
          displaySrc = c.battlePrepSrc;
          scale = c.battlePrepScale || c.battleScale || 1;
      }
      // Note: If visualState is 'hit', we STILL calculate src here to have a valid fallback, 
      // but the main rendering logic below will hide this instance.

      // CSS Classes
      const lungeClass = isAttacking 
         ? (c.team === 'player' ? 'translate-x-12' : '-translate-x-12') 
         : 'translate-x-0';
      const shakeClass = isHit ? 'animate-[shake_0.5s_ease-in-out]' : '';

      return (
          <div 
             key={c.id} 
             onClick={() => {
                 if (phase === 'COMMAND' && turnQueue.length > 0) {
                     const actorId = turnQueue[0];
                     const actor = combatants.find(a => a.id === actorId);
                     if (actor?.team === 'player' && c.team === 'enemy' && !isDead) {
                         setSelectedTargetId(c.id);
                     }
                 }
             }}
             className={`relative w-48 md:w-64 flex flex-col items-center transition-transform duration-300 ease-out transform ${lungeClass} ${shakeClass}
                ${isDead ? 'opacity-50 grayscale blur-[1px]' : ''}
                ${isTurn ? 'drop-shadow-[0_0_15px_rgba(255,255,255,0.4)]' : ''}
                ${isSelected ? 'ring-2 ring-red-500 rounded-xl bg-red-900/20' : ''}
                ${!isDead && c.team === 'enemy' && phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(x => x.id === turnQueue[0])?.team === 'player' ? 'cursor-pointer hover:bg-white/5 rounded-xl' : ''}
                ${isHitState ? 'opacity-0 pointer-events-none' : 'opacity-100'} 
             `}
          >
              <div className="absolute top-10 left-0 right-0 z-50 pointer-events-none flex flex-col items-center">
                  {myFloatingTexts.map(ft => (
                      <div key={ft.id} className={`text-3xl font-black animate-[floatUp_1s_ease-out_forwards] stroke-black drop-shadow-md ${ft.type === 'damage' ? 'text-red-500' : ''} ${ft.type === 'crit' ? 'text-yellow-400 text-4xl' : ''} ${ft.type === 'miss' ? 'text-gray-400' : ''} ${ft.type === 'heal' ? 'text-green-500' : ''}`}>{ft.text}</div>
                  ))}
              </div>

              {/* Character Image Container */}
              <div className={`w-40 h-40 md:w-56 md:h-56 relative transition-all ${isHit ? 'brightness-150 saturate-0 sepia' : ''}`}>
                  {displaySrc ? (
                      <img 
                        src={displaySrc} 
                        className="w-full h-full object-contain filter drop-shadow-lg origin-bottom" 
                        style={{ transform: `scale(${scale})` }}
                      />
                  ) : (
                      <div className="w-full h-full bg-gray-700 rounded-full flex items-center justify-center text-xs text-center p-2 border-2 border-gray-500 shadow-xl">{c.name}</div>
                  )}
                  {c.isShocked && <div className="absolute top-0 right-0 text-yellow-400 bg-black/80 rounded-full p-2 animate-pulse z-30"><Zap size={24}/></div>}
              </div>

              <div className="bg-black/70 px-3 py-1 rounded text-xs mt-1 text-center min-w-[90px] backdrop-blur-sm border border-gray-700/50 relative z-20">
                  <div className="font-bold text-gray-200 truncate max-w-[120px]">{c.name}</div>
              </div>

              {/* HP Bar */}
              <div className="w-full max-w-[120px] h-3 bg-gray-800 rounded-full mt-2 overflow-hidden border border-gray-600 shadow-inner relative z-20">
                  <div className={`h-full transition-all duration-500 ease-out ${hpPct < 25 ? 'bg-red-600' : (hpPct < 50 ? 'bg-yellow-500' : 'bg-green-500')}`} style={{ width: `${hpPct}%` }} />
                  <div className="absolute inset-0 flex items-center justify-center text-[8px] font-bold text-white drop-shadow-md">{c.currentHp} / {maxHp}</div>
              </div>
          </div>
      );
  };

  const activePlayerCombatant = turnQueue.length > 0 ? combatants.find(c => c.id === turnQueue[0]) : null;
  const isPlayerTurn = phase === 'COMMAND' && activePlayerCombatant?.team === 'player';

  // --- SPECIAL RENDERER FOR CENTER HIT SPRITE ---
  const activeHitterId = Object.keys(combatantVisuals).find(id => combatantVisuals[id] === 'hit');
  const activeHitter = activeHitterId ? combatants.find(c => c.id === activeHitterId) : null;

  return (
    <div 
      className="fixed inset-0 z-[100] bg-black text-white flex flex-col font-sans select-none overflow-hidden"
      onClick={handleScreenClick} 
    >
       <style>{`
          @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-5px) rotate(-5deg); } 75% { transform: translateX(5px) rotate(5deg); } }
          @keyframes floatUp { 0% { transform: translateY(0) scale(1); opacity: 1; } 100% { transform: translateY(-40px) scale(1.2); opacity: 0; } }
       `}</style>

       {/* Top Bar / Header */}
       <div className="absolute top-0 left-0 right-0 z-40 p-4 flex justify-between items-center bg-gradient-to-b from-black/90 to-transparent pointer-events-none">
           <h2 className="text-2xl font-bold flex items-center gap-2 text-red-500 drop-shadow-md"><Sword size={24}/> {battle.name}</h2>
           <div className="flex items-center gap-4 pointer-events-auto">
               <button onClick={(e) => { e.stopPropagation(); setAutoMode(!autoMode); }} className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold border transition-all ${autoMode ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                   {autoMode ? <Play size={14} fill="currentColor"/> : <Pause size={14} fill="currentColor"/>} {autoMode ? 'AUTO' : 'MANUAL'}
               </button>
               <Button onClick={onExit} variant="secondary" className="text-xs py-1 border-red-900 text-red-200 hover:bg-red-900/20">Flee</Button>
           </div>
       </div>

       {/* FULL SCREEN BATTLE AREA */}
       <div className="relative w-full h-full flex items-center justify-center overflow-hidden">
           {/* Background */}
           <div className="absolute inset-0 z-0">
               {battle.backgroundSrc ? <img src={battle.backgroundSrc} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-red-950/40 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-gray-800 to-black" />}
               <div className="absolute inset-0 bg-black/20"></div>
           </div>

           {/* Characters Layer (Regular List) */}
           <div className="relative z-10 w-full max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between px-4 md:px-20 gap-8">
               <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'player').map(renderCombatant)}</div>

               {/* Center Status / Victory Messages */}
               <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-20">
                  {phase === 'VICTORY' && <div className="text-center animate-bounce pointer-events-auto bg-black/70 p-8 rounded-2xl backdrop-blur-xl border border-yellow-500/50 shadow-2xl"><h1 className="text-6xl font-black text-yellow-400 mb-4 drop-shadow-lg">VICTORY</h1><Button onClick={onWin} className="bg-yellow-600 hover:bg-yellow-500 text-xl px-12 py-4 font-bold shadow-lg shadow-yellow-900/50">Continue Journey</Button></div>}
                  {phase === 'DEFEAT' && <div className="text-center pointer-events-auto bg-black/70 p-8 rounded-2xl backdrop-blur-xl border border-red-500/50 shadow-2xl"><h1 className="text-6xl font-black text-red-600 mb-4 drop-shadow-lg">DEFEAT</h1><Button onClick={onLose} variant="danger" className="text-xl px-12 py-4 font-bold shadow-lg shadow-red-900/50">Try Again</Button></div>}
               </div>

               <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'enemy').map(renderCombatant)}</div>
           </div>

           {/* --- CENTER HIT SPRITE OVERLAY --- */}
           {activeHitter && (
             <div className="absolute inset-0 z-40 flex items-center justify-center pointer-events-none animate-in zoom-in-75 duration-100">
                <div 
                  className="relative transition-transform" 
                  style={{ transform: `scale(${activeHitter.battleHitScale || activeHitter.battleScale || 1.2})` }}
                >
                    {activeHitter.battleHitSrc ? (
                        <img 
                            src={activeHitter.battleHitSrc} 
                            className="max-h-[80vh] w-auto object-contain drop-shadow-[0_0_50px_rgba(255,255,255,0.3)] filter brightness-110" 
                        />
                    ) : (
                        // Fallback if no hit sprite is defined but logic triggered (using Idle or default)
                        <img 
                            src={activeHitter.battleIdleSrc || activeHitter.imageSrc || activeHitter.mapSpriteSrc} 
                            className="max-h-[80vh] w-auto object-contain drop-shadow-[0_0_50px_rgba(255,255,255,0.3)] filter brightness-110"
                        />
                    )}
                </div>
             </div>
           )}

           {/* --- FLOATING UI LAYER --- */}

           {/* 1. Command Interface (Floating Bottom Center) */}
           {isPlayerTurn && (
              <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 z-30 w-[95%] max-w-2xl">
                 <div className="bg-black/70 backdrop-blur-md border border-indigo-500/30 rounded-2xl p-4 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300">
                    <div className="flex items-center justify-between mb-3 border-b border-white/10 pb-2">
                       <div className="text-lg font-bold text-indigo-300 flex items-center gap-2">
                          <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse shadow-[0_0_10px_#6366f1]"></div> 
                          Command: <span className="text-white">{activePlayerCombatant?.name}</span>
                       </div>
                       {!selectedTargetId && <div className="text-xs text-yellow-400 animate-pulse font-bold uppercase tracking-wider flex items-center gap-2"><Target size={14}/> Select Enemy Target</div>}
                    </div>

                    {selectedTargetId ? (
                        <div className="flex flex-col md:flex-row gap-4 items-center">
                            <div className="flex-1 flex gap-2 w-full overflow-x-auto pb-1 md:pb-0 custom-scrollbar justify-center">
                                {/* Horizontal Zone Selection */}
                                {[
                                    { id: 'torso', label: 'Torso', mod: 0 },
                                    { id: 'head', label: 'Head', mod: -6, color: 'text-red-300' },
                                    { id: 'arm', label: 'Arm', mod: -4 },
                                    { id: 'leg', label: 'Leg', mod: -3 }
                                ].map((z) => (
                                    <button 
                                        key={z.id}
                                        onClick={() => setSelectedZone(z.id as Zone)}
                                        className={`
                                            flex flex-col items-center justify-center px-4 py-2 rounded-lg border transition-all min-w-[80px]
                                            ${selectedZone === z.id 
                                                ? 'bg-indigo-600 border-indigo-400 text-white shadow-lg scale-105' 
                                                : 'bg-gray-800/50 border-gray-600 text-gray-400 hover:bg-gray-700 hover:text-white'
                                            }
                                        `}
                                    >
                                        <span className="font-bold text-sm">{z.label}</span>
                                        <span className={`text-[10px] ${z.color || 'opacity-50'}`}>{z.mod === 0 ? '-' : z.mod}</span>
                                    </button>
                                ))}
                            </div>
                            <Button onClick={() => handlePlayerCommand(turnQueue[0])} className="w-full md:w-auto bg-red-600 hover:bg-red-500 shadow-lg shadow-red-900/40 py-3 px-8 text-sm font-bold tracking-wider whitespace-nowrap h-full flex items-center gap-2">
                                <Sword size={18} className="animate-pulse"/> ATTACK
                            </Button>
                        </div>
                    ) : (
                        <div className="text-center text-gray-400 text-sm py-2 italic">
                            Click on an enemy sprite to target them.
                        </div>
                    )}
                 </div>
              </div>
           )}

           {/* 2. Floating Combat Log (Bottom Right) */}
           <div 
             className={`absolute bottom-4 right-4 z-30 bg-black/80 backdrop-blur-md border border-gray-700 shadow-2xl transition-all duration-300 ease-in-out overflow-hidden flex flex-col
                ${isLogCollapsed ? 'w-10 h-10 rounded-full cursor-pointer hover:bg-gray-800 hover:border-gray-500' : 'w-80 h-64 rounded-xl'}
             `}
             onClick={() => isLogCollapsed && setIsLogCollapsed(false)}
           >
               <div className={`flex items-center justify-between p-2 ${!isLogCollapsed ? 'border-b border-gray-700 bg-black/40' : 'h-full justify-center'}`}>
                   {!isLogCollapsed && <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2"><List size={12}/> Combat Log</span>}
                   <button 
                      onClick={(e) => { e.stopPropagation(); setIsLogCollapsed(!isLogCollapsed); }}
                      className="text-gray-400 hover:text-white transition-colors"
                   >
                       {isLogCollapsed ? <List size={16}/> : <Minimize2 size={14}/>}
                   </button>
               </div>

               {!isLogCollapsed && (
                   <div ref={scrollRef} className="flex-1 overflow-y-auto p-3 font-mono text-[10px] space-y-1 custom-scrollbar bg-black/20">
                       {logs.length === 0 && <div className="text-gray-600 italic text-center mt-4">Battle started...</div>}
                       {logs.map((log, i) => (
                           <div key={i} className={`leading-tight ${log.type === 'attack' ? 'text-blue-300' : ''} ${log.type === 'damage' ? 'text-red-400 font-bold' : ''} ${log.type === 'crit' ? 'text-yellow-400 font-bold' : ''} ${log.type === 'info' ? 'text-gray-500' : ''}`}>
                               {log.text}
                           </div>
                       ))}
                   </div>
               )}
           </div>

           {/* 3. Enemy Turn Indicator (Top Center Toast) */}
           {phase === 'COMMAND' && !isPlayerTurn && (
               <div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-30">
                   <div className="bg-black/60 backdrop-blur border border-red-500/30 text-red-200 px-6 py-2 rounded-full flex items-center gap-3 shadow-xl animate-pulse">
                       <Activity size={16} className="animate-spin"/> Enemy Turn
                   </div>
               </div>
           )}

       </div>

       {/* DICE OVERLAY (Unchanged logic, just ensure z-index is high) */}
       {showDice && (
           <div className="absolute inset-0 z-[60] flex items-center justify-center pointer-events-none">
               <div className="bg-black/80 backdrop-blur-md p-8 rounded-2xl flex flex-col items-center gap-4 animate-in zoom-in duration-300 border border-white/20 shadow-2xl min-w-[320px]">
                   <div className="text-xl font-bold uppercase tracking-widest text-white drop-shadow-md w-full text-center border-b border-gray-600 pb-2">{diceLabel}</div>
                   {diceSubLabel && <div className="text-sm text-gray-400 -mt-2">{diceSubLabel}</div>}
                   <div className="flex gap-4 flex-wrap justify-center">
                       {activeDice.length === 0 ? (
                           <div className="flex gap-2"><div className="w-16 h-16 rounded-lg bg-gray-800/50 border-2 border-dashed border-gray-500 flex items-center justify-center text-gray-500 font-bold">?</div></div>
                       ) : (
                           activeDice.map((d, i) => (
                               <div key={i} className={`w-16 h-16 flex items-center justify-center rounded-lg border-2 text-2xl font-bold shadow-lg animate-in slide-in-from-top-4 ${d.isSuccess ? 'bg-green-900 border-green-500 text-green-100' : 'bg-gray-800 border-gray-600 text-gray-400'} ${d.roll === 20 ? 'animate-bounce border-yellow-400 text-yellow-300 bg-yellow-900/50' : ''}`}>
                                   {d.total}
                                   {d.roll !== d.total && <span className="absolute bottom-1 right-1 text-[8px] opacity-60">raw:{d.roll}</span>}
                               </div>
                           ))
                       )}
                   </div>
               </div>
           </div>
       )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Battle, Character, Zone } from '../types';
import { ActiveCombatant, rollTeamInitiative, performShockTest, resolveAttack, CombatLog, DetailedRoll } from '../utils/combat';
import { Button } from './ui/Button';
import { Sword, Target, Zap, Dice5, Play, Pause, Activity, ChevronDown, ChevronUp, List, X, Minimize2, Maximize2, BookOpen, Info } from 'lucide-react';

interface BattleArenaProps {
  battle: Battle;
  characters: Character[]; 
  onWin: () => void;
  onLose: () => void;
  onExit: () => void;
}

type BattlePhase = 'INIT' | 'COMMAND' | 'EXECUTION' | 'VICTORY' | 'DEFEAT';
type VisualState = 'idle' | 'prep' | 'hit';

interface FloatingText {
    id: string;
    text: string;
    type: 'damage' | 'heal' | 'miss' | 'crit';
    combatantId: string;
}

export const BattleArena: React.FC<BattleArenaProps> = ({ battle, characters, onWin, onLose, onExit }) => {
  const [phase, setPhase] = useState<BattlePhase>('INIT');
  const [combatants, setCombatants] = useState<ActiveCombatant[]>([]);
  const [turnQueue, setTurnQueue] = useState<string[]>([]); 
  const [logs, setLogs] = useState<CombatLog[]>([]);

  // Settings
  const [autoMode, setAutoMode] = useState(false); 
  const [isLogCollapsed, setIsLogCollapsed] = useState(false);
  const [isGuideCollapsed, setIsGuideCollapsed] = useState(true); // Default collapsed

  // Command State
  const [selectedTargetId, setSelectedTargetId] = useState<string | null>(null);
  const [selectedZone, setSelectedZone] = useState<Zone>('torso');
  const [commands, setCommands] = useState<Record<string, { targetId: string, zone: Zone }>>({});

  // --- Visual States ---
  const [floatingTexts, setFloatingTexts] = useState<FloatingText[]>([]);

  // New: Track sprite state per combatant
  const [combatantVisuals, setCombatantVisuals] = useState<Record<string, VisualState>>({});

  const [animatingAttackerId, setAnimatingAttackerId] = useState<string | null>(null); // Still used for slide logic?
  const [animatingTargetId, setAnimatingTargetId] = useState<string | null>(null);

  // DICE VISUALS
  const [activeDice, setActiveDice] = useState<DetailedRoll[]>([]);
  const [showDice, setShowDice] = useState(false);
  const [diceLabel, setDiceLabel] = useState("");
  const [diceSubLabel, setDiceSubLabel] = useState(""); 

  // Control Flow State
  const [waitingForClick, setWaitingForClick] = useState(false);
  const resolveClickRef = useRef<(() => void) | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);

  const setVisualState = (id: string, state: VisualState) => {
      setCombatantVisuals(prev => ({ ...prev, [id]: state }));
  };

  const addFloatingText = (combatantId: string, text: string, type: FloatingText['type']) => {
      const id = crypto.randomUUID();
      setFloatingTexts(prev => [...prev, { id, text, type, combatantId }]);
      setTimeout(() => setFloatingTexts(prev => prev.filter(ft => ft.id !== id)), 1500);
  };

  const addLog = (text: string, type: CombatLog['type']) => {
    setLogs(prev => [...prev, { text, type }]);
  };

  // --- WAIT LOGIC ---
  const waitForInput = async (autoDelayMs: number = 800) => {
      if (autoMode) {
          return new Promise<void>(resolve => setTimeout(resolve, autoDelayMs));
      } else {
          setWaitingForClick(true);
          return new Promise<void>(resolve => {
              resolveClickRef.current = resolve;
          });
      }
  };

  const handleScreenClick = () => {
      if (waitingForClick && resolveClickRef.current) {
          setWaitingForClick(false);
          const resolver = resolveClickRef.current;
          resolveClickRef.current = null;
          resolver();
      }
  };

  // --- DICE ANIMATION HELPER ---
  const visualizeRolls = async (
      label: string, 
      subLabel: string, 
      rolls: DetailedRoll[], 
      isManualTrigger: boolean 
  ) => {
      setDiceLabel(label);
      setDiceSubLabel(subLabel);
      setActiveDice([]); 
      setShowDice(true);

      if (isManualTrigger && !autoMode) {
          setDiceLabel(`Ready to ${label}`);
          await waitForInput(0); 
      }

      setDiceLabel(label); 

      const duration = 600;
      const interval = 50;
      const steps = duration / interval;

      for(let i=0; i<steps; i++) {
          const fakeRolls = rolls.map(() => ({ roll: Math.floor(Math.random()*20)+1, total: 0 }));
          setActiveDice(fakeRolls);
          await new Promise(r => setTimeout(r, interval));
      }

      setActiveDice(rolls);
      await waitForInput(1500);
      setShowDice(false);
  };

  // Initialize Combat
  useEffect(() => {
    let mounted = true;

    const init = async () => {
      const parts: ActiveCombatant[] = [];
      [...battle.playerCharacterIds, ...battle.enemyCharacterIds].forEach(id => {
          const c = characters.find(char => char.id === id);
          if (c) {
              const team = battle.playerCharacterIds.includes(id) ? 'player' : 'enemy';
              parts.push({
                  ...c,
                  currentHp: c.stats?.hp || 20,
                  isShocked: false,
                  tempDefenseBonus: 0,
                  team,
                  stats: c.stats || { pra: 3, str: 3, wid: 3, ges: 3, wil: 3, hp: 20, maxHp: 20, limit: 10, weapon: { name: 'Hands', at: 3, mod: 0, dmg: 1, cap: null } }
              });
          }
      });

      if (!mounted) return;
      setCombatants(parts);

      const playerTeam = parts.filter(c => c.team === 'player');
      const enemyTeam = parts.filter(c => c.team === 'enemy');

      const pInit = rollTeamInitiative(playerTeam);
      const eInit = rollTeamInitiative(enemyTeam);

      await visualizeRolls("Player Initiative", `Best DEX: ${pInit.total - pInit.roll}`, [{ roll: pInit.roll, total: pInit.total }], true);
      await visualizeRolls("Enemy Initiative", `Best DEX: ${eInit.total - eInit.roll}`, [{ roll: eInit.roll, total: eInit.total }], false);

      addLog(`Initiative: Player ${pInit.total} vs Enemy ${eInit.total}`, 'info');

      if (pInit.total >= eInit.total) {
          startCommandPhase('player', parts);
      } else {
          startCommandPhase('enemy', parts);
      }
    };

    init();
    return () => { mounted = false; };
  }, [battle]);

  useEffect(() => {
      if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [logs, isLogCollapsed]);

  const startCommandPhase = (activeTeam: 'player' | 'enemy', currentCombatants: ActiveCombatant[]) => {
      setPhase('COMMAND');
      const teamMembers = currentCombatants.filter(c => c.team === activeTeam && c.currentHp > 0);
      setTurnQueue(teamMembers.map(c => c.id));
      setCommands({}); 

      if (activeTeam === 'enemy') {
          setTimeout(() => runEnemyAI(teamMembers, currentCombatants), 500);
      }
  };

  const runEnemyAI = (enemies: ActiveCombatant[], allCombatants: ActiveCombatant[]) => {
     const alivePlayers = allCombatants.filter(c => c.team === 'player' && c.currentHp > 0);
     if (alivePlayers.length === 0) {
         executePhase(enemies, {}, allCombatants);
         return;
     }
     const aiCommands: Record<string, { targetId: string, zone: Zone }> = {};
     enemies.forEach(e => {
         const target = alivePlayers[Math.floor(Math.random() * alivePlayers.length)];
         aiCommands[e.id] = { targetId: target.id, zone: 'torso' }; 
     });
     setCommands(aiCommands); 
     setTimeout(() => executePhase(enemies, aiCommands, allCombatants), 1000);
  };

  const handlePlayerCommand = (attackerId: string) => {
      if (!selectedTargetId) return;
      const newCommands = { ...commands, [attackerId]: { targetId: selectedTargetId, zone: selectedZone } };
      setCommands(newCommands);
      const nextQueue = turnQueue.filter(id => id !== attackerId);
      setTurnQueue(nextQueue);
      setSelectedTargetId(null);
      setSelectedZone('torso');
      if (nextQueue.length === 0) executePhase(combatants.filter(c => c.team === 'player'), newCommands, combatants);
  };

  const executePhase = async (
      actingTeam: ActiveCombatant[], 
      activeCommands: Record<string, { targetId: string, zone: Zone }>,
      currentCombatants: ActiveCombatant[]
  ) => {
      setPhase('EXECUTION');
      let workingState = [...currentCombatants]; 

      for (const actor of actingTeam) {
          const freshActor = workingState.find(c => c.id === actor.id);
          if (!freshActor || freshActor.currentHp <= 0) continue;
          const isPlayer = actor.team === 'player';

          // 1. Shock Test
          const shockResult = performShockTest(freshActor);
          if (shockResult.rollData) {
             await visualizeRolls("Shock Test", `Target Number: 15`, [shockResult.rollData], isPlayer);
             if (shockResult.log) addLog(shockResult.log, 'info');
             if (freshActor.currentHp < (freshActor.stats!.maxHp * 0.25)) {
                  workingState = workingState.map(c => c.id === actor.id ? { ...c, isShocked: shockResult.shocked } : c);
             }
             if (shockResult.shocked) {
                addFloatingText(actor.id, "SHOCKED", "miss");
                continue; 
             }
          }

          // 2. Attack Setup
          const cmd = activeCommands[actor.id];
          if (!cmd) continue;
          const target = workingState.find(c => c.id === cmd.targetId);
          if (!target || target.currentHp <= 0) continue;

          // --- VISUAL: PREPARE ATTACK (Frame Change + Slide) ---
          setVisualState(actor.id, 'prep');
          // For melee slide effect (Still keep for prep, but not for hit anymore)
          setAnimatingAttackerId(actor.id);
          await waitForInput(400); // Wait for the "Charge" visual

          // Calculate
          const result = resolveAttack(freshActor, target, cmd.zone);

          // --- VISUALIZE: ROLLS ---
          const targetIsPlayer = target.team === 'player';
          await visualizeRolls(`${target.name} Evades`, `Base TN (GES): ${target.stats!.ges}`, [result.defenseRoll], targetIsPlayer);
          await visualizeRolls(`${actor.name} Attacks`, `Target Number: ${result.defenseRoll.total}`, result.attackRolls, isPlayer);

          result.logs.forEach(l => {
              addLog(l.text, l.type); 
          });

          if (result.woundRolls.length > 0) {
              const threshold = 10 - (freshActor.stats!.str - target.stats!.wid);
              await visualizeRolls("Penetration Check", `Threshold: ${threshold}`, result.woundRolls, isPlayer);
          }

          // --- VISUAL: EXECUTE HIT (Frame Change -> Center Screen) ---
          setVisualState(actor.id, 'hit');

          if (result.damage > 0) {
              setAnimatingTargetId(target.id);
              addFloatingText(target.id, `-${result.damage}`, result.isCrit ? "crit" : "damage");
              workingState = workingState.map(c => c.id === target.id ? { ...c, currentHp: Math.max(0, c.currentHp - result.damage) } : c);
              setCombatants(workingState); 
              await waitForInput(600); // Wait for hit impact
              setAnimatingTargetId(null);
          } else {
              addFloatingText(target.id, "MISS", "miss");
              await waitForInput(500);
          }

          // --- VISUAL: RETURN TO IDLE ---
          setVisualState(actor.id, 'idle');
          setAnimatingAttackerId(null); // Slide back
          await waitForInput(200); // Wait for slide back
      }

      const justActedTeam = actingTeam.length > 0 ? actingTeam[0].team : 'player'; 
      checkWinCondition(workingState, justActedTeam);
  };

  const checkWinCondition = (currentCombs: ActiveCombatant[], lastActiveTeam: 'player' | 'enemy') => {
      const playersAlive = currentCombs.some(c => c.team === 'player' && c.currentHp > 0);
      const enemiesAlive = currentCombs.some(c => c.team === 'enemy' && c.currentHp > 0);

      if (!playersAlive) {
          setPhase('DEFEAT');
          return;
      }
      if (!enemiesAlive) {
          setPhase('VICTORY');
          return;
      }
      if (lastActiveTeam === 'player') startCommandPhase('enemy', currentCombs);
      else startCommandPhase('player', currentCombs);
  };

  const renderCombatant = (c: ActiveCombatant) => {
      const isDead = c.currentHp <= 0;
      const isTurn = turnQueue.includes(c.id);
      const isSelected = selectedTargetId === c.id;
      const maxHp = c.stats?.maxHp || 1;
      const hpPct = (c.currentHp / maxHp) * 100;

      // Animation Logic
      const visualState = combatantVisuals[c.id] || 'idle';
      const isHitState = visualState === 'hit'; // Checking if currently in Center-Screen Mode

      // Lunge logic only applies if NOT hitting (since hitting is now center screen)
      const isAttacking = animatingAttackerId === c.id && visualState !== 'hit'; 
      const isHit = animatingTargetId === c.id;

      const myFloatingTexts = floatingTexts.filter(ft => ft.combatantId === c.id);

      // Determine Image Source & Scale based on State hierarchy
      let displaySrc = c.battleIdleSrc || c.imageSrc || c.mapSpriteSrc;
      let scale = c.battleIdleScale || c.battleScale || 1;

      if (visualState === 'prep' && c.battlePrepSrc) {
          displaySrc = c.battlePrepSrc;
          scale = c.battlePrepScale || c.battleScale || 1;
      }
      // Note: If visualState is 'hit', we STILL calculate src here to have a valid fallback, 
      // but the main rendering logic below will hide this instance.

      // CSS Classes
      const lungeClass = isAttacking 
         ? (c.team === 'player' ? 'translate-x-12' : '-translate-x-12') 
         : 'translate-x-0';
      const shakeClass = isHit ? 'animate-[shake_0.5s_ease-in-out]' : '';

      return (
          <div 
             key={c.id} 
             onClick={() => {
                 if (phase === 'COMMAND' && turnQueue.length > 0) {
                     const actorId = turnQueue[0];
                     const actor = combatants.find(a => a.id === actorId);
                     if (actor?.team === 'player' && c.team === 'enemy' && !isDead) {
                         setSelectedTargetId(c.id);
                     }
                 }
             }}
             className={`relative w-48 md:w-64 flex flex-col items-center transition-transform duration-300 ease-out transform ${lungeClass} ${shakeClass}
                ${isDead ? 'opacity-50 grayscale blur-[1px]' : ''}
                ${isTurn ? 'drop-shadow-[0_0_15px_rgba(255,255,255,0.4)]' : ''}
                ${isSelected ? 'ring-2 ring-red-500 rounded-xl bg-red-900/20' : ''}
                ${!isDead && c.team === 'enemy' && phase === 'COMMAND' && turnQueue.length > 0 && combatants.find(x => x.id === turnQueue[0])?.team === 'player' ? 'cursor-pointer hover:bg-white/5 rounded-xl' : ''}
                ${isHitState ? 'opacity-0 pointer-events-none' : 'opacity-100'} 
             `}
          >
              <div className="absolute top-10 left-0 right-0 z-50 pointer-events-none flex flex-col items-center">
                  {myFloatingTexts.map(ft => (
                      <div key={ft.id} className={`text-3xl font-black animate-[floatUp_1s_ease-out_forwards] stroke-black drop-shadow-md ${ft.type === 'damage' ? 'text-red-500' : ''} ${ft.type === 'crit' ? 'text-yellow-400 text-4xl' : ''} ${ft.type === 'miss' ? 'text-gray-400' : ''} ${ft.type === 'heal' ? 'text-green-500' : ''}`}>{ft.text}</div>
                  ))}
              </div>

              {/* Character Image Container */}
              <div className={`w-40 h-40 md:w-56 md:h-56 relative transition-all ${isHit ? 'brightness-150 saturate-0 sepia' : ''}`}>
                  {displaySrc ? (
                      <img 
                        src={displaySrc} 
                        className="w-full h-full object-contain filter drop-shadow-lg origin-bottom" 
                        style={{ transform: `scale(${scale})` }}
                      />
                  ) : (
                      <div className="w-full h-full bg-gray-700 rounded-full flex items-center justify-center text-xs text-center p-2 border-2 border-gray-500 shadow-xl">{c.name}</div>
                  )}
                  {c.isShocked && <div className="absolute top-0 right-0 text-yellow-400 bg-black/80 rounded-full p-2 animate-pulse z-30"><Zap size={24}/></div>}
              </div>

              <div className="bg-black/70 px-3 py-1 rounded text-xs mt-1 text-center min-w-[90px] backdrop-blur-sm border border-gray-700/50 relative z-20">
                  <div className="font-bold text-gray-200 truncate max-w-[120px]">{c.name}</div>
              </div>

              {/* HP Bar */}
              <div className="w-full max-w-[120px] h-3 bg-gray-800 rounded-full mt-2 overflow-hidden border border-gray-600 shadow-inner relative z-20">
                  <div className={`h-full transition-all duration-500 ease-out ${hpPct < 25 ? 'bg-red-600' : (hpPct < 50 ? 'bg-yellow-500' : 'bg-green-500')}`} style={{ width: `${hpPct}%` }} />
                  <div className="absolute inset-0 flex items-center justify-center text-[8px] font-bold text-white drop-shadow-md">{c.currentHp} / {maxHp}</div>
              </div>
          </div>
      );
  };

  const activePlayerCombatant = turnQueue.length > 0 ? combatants.find(c => c.id === turnQueue[0]) : null;
  const isPlayerTurn = phase === 'COMMAND' && activePlayerCombatant?.team === 'player';

  // --- SPECIAL RENDERER FOR CENTER HIT SPRITE ---
  const activeHitterId = Object.keys(combatantVisuals).find(id => combatantVisuals[id] === 'hit');
  const activeHitter = activeHitterId ? combatants.find(c => c.id === activeHitterId) : null;

  return (
    <div 
      className="fixed inset-0 z-[100] bg-black text-white flex flex-col font-sans select-none overflow-hidden"
      onClick={handleScreenClick} 
    >
       <style>{`
          @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-5px) rotate(-5deg); } 75% { transform: translateX(5px) rotate(5deg); } }
          @keyframes floatUp { 0% { transform: translateY(0) scale(1); opacity: 1; } 100% { transform: translateY(-40px) scale(1.2); opacity: 0; } }
       `}</style>

       {/* Top Bar / Header */}
       <div className="absolute top-0 left-0 right-0 z-40 p-4 flex justify-between items-center bg-gradient-to-b from-black/90 to-transparent pointer-events-none">
           <h2 className="text-2xl font-bold flex items-center gap-2 text-red-500 drop-shadow-md"><Sword size={24}/> {battle.name}</h2>
           <div className="flex items-center gap-4 pointer-events-auto">
               <button onClick={(e) => { e.stopPropagation(); setAutoMode(!autoMode); }} className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold border transition-all ${autoMode ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                   {autoMode ? <Play size={14} fill="currentColor"/> : <Pause size={14} fill="currentColor"/>} {autoMode ? 'AUTO' : 'MANUAL'}
               </button>
               <Button onClick={onExit} variant="secondary" className="text-xs py-1 border-red-900 text-red-200 hover:bg-red-900/20">Flee</Button>
           </div>
       </div>

       {/* FULL SCREEN BATTLE AREA */}
       <div className="relative w-full h-full flex items-center justify-center overflow-hidden">
           {/* Background */}
           <div className="absolute inset-0 z-0">
               {battle.backgroundSrc ? <img src={battle.backgroundSrc} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-red-950/40 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-gray-800 to-black" />}
               <div className="absolute inset-0 bg-black/20"></div>
           </div>

           {/* Characters Layer (Regular List) */}
           <div className="relative z-10 w-full max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between px-4 md:px-20 gap-8">
               <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'player').map(renderCombatant)}</div>

               {/* Center Status / Victory Messages */}
               <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-20">
                  {phase === 'VICTORY' && <div className="text-center animate-bounce pointer-events-auto bg-black/70 p-8 rounded-2xl backdrop-blur-xl border border-yellow-500/50 shadow-2xl"><h1 className="text-6xl font-black text-yellow-400 mb-4 drop-shadow-lg">VICTORY</h1><Button onClick={onWin} className="bg-yellow-600 hover:bg-yellow-500 text-xl px-12 py-4 font-bold shadow-lg shadow-yellow-900/50">Continue Journey</Button></div>}
                  {phase === 'DEFEAT' && <div className="text-center pointer-events-auto bg-black/70 p-8 rounded-2xl backdrop-blur-xl border border-red-500/50 shadow-2xl"><h1 className="text-6xl font-black text-red-600 mb-4 drop-shadow-lg">DEFEAT</h1><Button onClick={onLose} variant="danger" className="text-xl px-12 py-4 font-bold shadow-lg shadow-red-900/50">Try Again</Button></div>}
               </div>

               <div className="flex flex-col gap-8 items-center justify-center min-w-[150px]">{combatants.filter(c => c.team === 'enemy').map(renderCombatant)}</div>
           </div>

           {/* --- CENTER HIT SPRITE OVERLAY --- */}
           {activeHitter && (
             <div className="absolute inset-0 z-40 flex items-center justify-center pointer-events-none animate-in zoom-in-75 duration-100">
                <div 
                  className="relative transition-transform" 
                  style={{ transform: `scale(${activeHitter.battleHitScale || activeHitter.battleScale || 1.2})` }}
                >
                    {activeHitter.battleHitSrc ? (
                        <img 
                            src={activeHitter.battleHitSrc} 
                            className="max-h-[80vh] w-auto object-contain drop-shadow-[0_0_50px_rgba(255,255,255,0.3)] filter brightness-110" 
                        />
                    ) : (
                        // Fallback if no hit sprite is defined but logic triggered (using Idle or default)
                        <img 
                            src={activeHitter.battleIdleSrc || activeHitter.imageSrc || activeHitter.mapSpriteSrc} 
                            className="max-h-[80vh] w-auto object-contain drop-shadow-[0_0_50px_rgba(255,255,255,0.3)] filter brightness-110"
                        />
                    )}
                </div>
             </div>
           )}

           {/* --- FLOATING UI LAYER --- */}

           {/* 1. Command Interface (Floating Bottom Center) */}
           {isPlayerTurn && (
              <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 z-30 w-[95%] max-w-2xl">
                 <div className="bg-black/70 backdrop-blur-md border border-indigo-500/30 rounded-2xl p-4 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300">
                    <div className="flex items-center justify-between mb-3 border-b border-white/10 pb-2">
                       <div className="text-lg font-bold text-indigo-300 flex items-center gap-2">
                          <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse shadow-[0_0_10px_#6366f1]"></div> 
                          Command: <span className="text-white">{activePlayerCombatant?.name}</span>
                       </div>
                       {!selectedTargetId && <div className="text-xs text-yellow-400 animate-pulse font-bold uppercase tracking-wider flex items-center gap-2"><Target size={14}/> Select Enemy Target</div>}
                    </div>

                    {selectedTargetId ? (
                        <div className="flex flex-col md:flex-row gap-4 items-center">
                            <div className="flex-1 flex gap-2 w-full overflow-x-auto pb-1 md:pb-0 custom-scrollbar justify-center">
                                {/* Horizontal Zone Selection */}
                                {[
                                    { id: 'torso', label: 'Torso', mod: 0 },
                                    { id: 'head', label: 'Head', mod: -6, color: 'text-red-300' },
                                    { id: 'arm', label: 'Arm', mod: -4 },
                                    { id: 'leg', label: 'Leg', mod: -3 }
                                ].map((z) => (
                                    <button 
                                        key={z.id}
                                        onClick={() => setSelectedZone(z.id as Zone)}
                                        className={`
                                            flex flex-col items-center justify-center px-4 py-2 rounded-lg border transition-all min-w-[80px]
                                            ${selectedZone === z.id 
                                                ? 'bg-indigo-600 border-indigo-400 text-white shadow-lg scale-105' 
                                                : 'bg-gray-800/50 border-gray-600 text-gray-400 hover:bg-gray-700 hover:text-white'
                                            }
                                        `}
                                    >
                                        <span className="font-bold text-sm">{z.label}</span>
                                        <span className={`text-[10px] ${z.color || 'opacity-50'}`}>{z.mod === 0 ? '-' : z.mod}</span>
                                    </button>
                                ))}
                            </div>
                            <Button onClick={() => handlePlayerCommand(turnQueue[0])} className="w-full md:w-auto bg-red-600 hover:bg-red-500 shadow-lg shadow-red-900/40 py-3 px-8 text-sm font-bold tracking-wider whitespace-nowrap h-full flex items-center gap-2">
                                <Sword size={18} className="animate-pulse"/> ATTACK
                            </Button>
                        </div>
                    ) : (
                        <div className="text-center text-gray-400 text-sm py-2 italic">
                            Click on an enemy sprite to target them.
                        </div>
                    )}
                 </div>
              </div>
           )}

           {/* 2. Floating Combat Log (Bottom Right) */}
           <div 
             className={`absolute bottom-4 right-4 z-30 bg-black/80 backdrop-blur-md border border-gray-700 shadow-2xl transition-all duration-300 ease-in-out overflow-hidden flex flex-col
                ${isLogCollapsed ? 'w-10 h-10 rounded-full cursor-pointer hover:bg-gray-800 hover:border-gray-500' : 'w-80 h-64 rounded-xl'}
             `}
             onClick={() => isLogCollapsed && setIsLogCollapsed(false)}
           >
               <div className={`flex items-center justify-between p-2 ${!isLogCollapsed ? 'border-b border-gray-700 bg-black/40' : 'h-full justify-center'}`}>
                   {!isLogCollapsed && <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2"><List size={12}/> Combat Log</span>}
                   <button 
                      onClick={(e) => { e.stopPropagation(); setIsLogCollapsed(!isLogCollapsed); }}
                      className="text-gray-400 hover:text-white transition-colors"
                   >
                       {isLogCollapsed ? <List size={16}/> : <Minimize2 size={14}/>}
                   </button>
               </div>

               {!isLogCollapsed && (
                   <div ref={scrollRef} className="flex-1 overflow-y-auto p-3 font-mono text-[10px] space-y-1 custom-scrollbar bg-black/20">
                       {logs.length === 0 && <div className="text-gray-600 italic text-center mt-4">Battle started...</div>}
                       {logs.map((log, i) => (
                           <div key={i} className={`leading-tight ${log.type === 'attack' ? 'text-blue-300' : ''} ${log.type === 'damage' ? 'text-red-400 font-bold' : ''} ${log.type === 'crit' ? 'text-yellow-400 font-bold' : ''} ${log.type === 'info' ? 'text-gray-500' : ''}`}>
                               {log.text}
                           </div>
                       ))}
                   </div>
               )}
           </div>

           {/* 3. NEW: BATTLE GUIDE / MANUAL (Top Left - Mirrored Logic) */}
           <div 
             className={`absolute top-20 left-4 z-30 bg-black/80 backdrop-blur-md border border-gray-700 shadow-2xl transition-all duration-300 ease-in-out overflow-hidden flex flex-col
                ${isGuideCollapsed ? 'w-10 h-10 rounded-full cursor-pointer hover:bg-gray-800 hover:border-gray-500' : 'w-80 h-96 rounded-xl'}
             `}
             onClick={() => isGuideCollapsed && setIsGuideCollapsed(false)}
           >
               <div className={`flex items-center justify-between p-2 ${!isGuideCollapsed ? 'border-b border-gray-700 bg-indigo-900/20' : 'h-full justify-center'}`}>
                   {!isGuideCollapsed && <span className="text-[10px] font-bold text-indigo-300 uppercase tracking-widest flex items-center gap-2"><BookOpen size={12}/> Kampf-Handbuch</span>}
                   <button 
                      onClick={(e) => { e.stopPropagation(); setIsGuideCollapsed(!isGuideCollapsed); }}
                      className="text-indigo-300 hover:text-white transition-colors"
                      title="Battle Guide"
                   >
                       {isGuideCollapsed ? <Info size={16}/> : <Minimize2 size={14}/>}
                   </button>
               </div>

               {!isGuideCollapsed && (
                   <div className="flex-1 overflow-y-auto p-4 font-sans text-xs space-y-4 custom-scrollbar bg-black/20 text-gray-300">
                       <div className="space-y-1">
                          <h4 className="font-bold text-indigo-400 text-sm border-b border-gray-700 pb-1">1. Attribute</h4>
                          <p><span className="text-white font-bold">GES (Geschick):</span> Bestimmt Initiative & Ausweichen (Verteidigungswert).</p>
                          <p><span className="text-white font-bold">PRA (Präzision):</span> Bestimmt Trefferchance.</p>
                          <p><span className="text-white font-bold">STR (Stärke):</span> Erhöht Durchschlag (Wund-Wahrscheinlichkeit).</p>
                          <p><span className="text-white font-bold">WID (Widerstand):</span> Rüstung gegen Wunden.</p>
                          <p><span className="text-white font-bold">WIL (Wille):</span> Schutz gegen Schock.</p>
                       </div>

                       <div className="space-y-1">
                          <h4 className="font-bold text-indigo-400 text-sm border-b border-gray-700 pb-1">2. Schock-Phase</h4>
                          <p>Fällt HP unter 25%, muss ein <span className="text-yellow-400">Schock-Test</span> bestanden werden.</p>
                          <div className="bg-gray-800 p-2 rounded text-[10px] font-mono border border-gray-700">W20 + WIL ≥ 15</div>
                          <p className="italic text-gray-500">Bei Fehlschlag ist der Charakter geschockt und verliert Verteidigungsboni.</p>
                       </div>

                       <div className="space-y-1">
                          <h4 className="font-bold text-indigo-400 text-sm border-b border-gray-700 pb-1">3. Angriff & Treffer</h4>
                          <p>Der Verteidiger würfelt seinen Zielwert (TN):</p>
                          <div className="bg-gray-800 p-2 rounded text-[10px] font-mono border border-gray-700">TN = W20 + GES</div>
                          <p>Der Angreifer würfelt (Anzahl Würfel = Waffen-AT):</p>
                          <div className="bg-gray-800 p-2 rounded text-[10px] font-mono border border-gray-700">ATK = W20 + PRA + Mod</div>
                          <p>Jeder Würfel, der <span className="text-green-400">höher als der TN</span> ist, ist ein potenzieller Treffer.</p>
                       </div>

                       <div className="space-y-1">
                          <h4 className="font-bold text-indigo-400 text-sm border-b border-gray-700 pb-1">4. Durchschlag (Wound)</h4>
                          <p>Ein Treffer macht nur Schaden, wenn er die Rüstung durchdringt.</p>
                          <div className="bg-gray-800 p-2 rounded text-[10px] font-mono border border-gray-700">Schwelle = 10 - (STR - WID)</div>
                          <p>Für jeden Treffer wird erneut gewürfelt. Ist der Wurf <span className="text-red-400">höher als die Schwelle</span>, entsteht eine Wunde.</p>
                       </div>

                       <div className="space-y-1">
                          <h4 className="font-bold text-indigo-400 text-sm border-b border-gray-700 pb-1">5. Schaden</h4>
                          <p>Jede bestätigte Wunde verursacht den Waffenschaden (DMG).</p>
                          <p><span className="text-yellow-400">Kritisch (Nat 20):</span> Kopftreffer +50% Schaden oder Gliedmaßen zerstört.</p>
                       </div>
                   </div>
               )}
           </div>

           {/* 4. Enemy Turn Indicator (Top Center Toast) */}
           {phase === 'COMMAND' && !isPlayerTurn && (
               <div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-30">
                   <div className="bg-black/60 backdrop-blur border border-red-500/30 text-red-200 px-6 py-2 rounded-full flex items-center gap-3 shadow-xl animate-pulse">
                       <Activity size={16} className="animate-spin"/> Enemy Turn
                   </div>
               </div>
           )}

       </div>

       {/* DICE OVERLAY (Unchanged logic, just ensure z-index is high) */}
       {showDice && (
           <div className="absolute inset-0 z-[60] flex items-center justify-center pointer-events-none">
               <div className="bg-black/80 backdrop-blur-md p-8 rounded-2xl flex flex-col items-center gap-4 animate-in zoom-in duration-300 border border-white/20 shadow-2xl min-w-[320px]">
                   <div className="text-xl font-bold uppercase tracking-widest text-white drop-shadow-md w-full text-center border-b border-gray-600 pb-2">{diceLabel}</div>
                   {diceSubLabel && <div className="text-sm text-gray-400 -mt-2">{diceSubLabel}</div>}
                   <div className="flex gap-4 flex-wrap justify-center">
                       {activeDice.length === 0 ? (
                           <div className="flex gap-2"><div className="w-16 h-16 rounded-lg bg-gray-800/50 border-2 border-dashed border-gray-500 flex items-center justify-center text-gray-500 font-bold">?</div></div>
                       ) : (
                           activeDice.map((d, i) => (
                               <div key={i} className={`w-16 h-16 flex items-center justify-center rounded-lg border-2 text-2xl font-bold shadow-lg animate-in slide-in-from-top-4 ${d.isSuccess ? 'bg-green-900 border-green-500 text-green-100' : 'bg-gray-800 border-gray-600 text-gray-400'} ${d.roll === 20 ? 'animate-bounce border-yellow-400 text-yellow-300 bg-yellow-900/50' : ''}`}>
                                   {d.total}
                                   {d.roll !== d.total && <span className="absolute bottom-1 right-1 text-[8px] opacity-60">raw:{d.roll}</span>}
                               </div>
                           ))
                       )}
                   </div>
               </div>
           </div>
       )}
    </div>
  );
};

export type Zone = 'torso' | 'head' | 'arm' | 'leg';

export interface Weapon {
  name: string;
  at: number; // Angriffs-Tempo (Würfel-Pool)
  mod: number; // Modifikator (Präzision)
  dmg: number; // Schaden pro Wunde (Flat für V1, später Dice möglich)
  cap: number | null; // Max Schaden pro Treffer (null = unbegrenzt)
}

export interface CombatStats {
  // Attributes
  pra: number; // Präzision
  str: number; // Stärke
  wid: number; // Widerstand
  ges: number; // Geschick
  wil: number; // Willenskraft

  // Vitals
  hp: number;
  maxHp: number;
  limit: number; // Verwundungs-Limit (Körpermasse/Rüstung)

  // Equipment
