                                         <div className="flex gap-2">
                                             <button onClick={() => addScene(activeChapter.id)} className="flex items-center gap-1 px-2 py-1 bg-indigo-900/40 text-indigo-300 border border-indigo-800 rounded text-xs hover:bg-indigo-800 hover:text-white transition"><MessageSquare size={12}/> + Scenario</button>
                                             <button onClick={() => addBattle(activeChapter.id)} className="flex items-center gap-1 px-2 py-1 bg-red-900/40 text-red-300 border border-red-800 rounded text-xs hover:bg-red-800 hover:text-white transition"><Sword size={12}/> + Battle</button>
