                                                     <button onClick={(e) => { e.stopPropagation(); onUpdateScenes(scenes.filter(x => x.id !== s.id)); }} className="p-1 text-gray-600 hover:text-red-500"><Trash2 size={14}/></button>
                                                 </div>
                                             </div>
                                         ))}

                                         {/* List Battles */}
                                         {chapterBattles.map(b => (
                                             <div key={b.id} onClick={() => setEditingItem({ type: 'battle', id: b.id })} className="flex items-center p-3 rounded bg-gray-900 border border-red-900/30 hover:border-red-500 cursor-pointer group transition-all">
                                                 <div className="w-8 h-8 rounded bg-gray-800 flex items-center justify-center border border-gray-600 mr-3 text-red-500"><Sword size={16}/></div>
                                                 <div className="flex-1">
                                                     <div className="text-sm font-bold text-red-100">{b.name}</div>
                                                     <div className="text-[10px] text-red-900/70 truncate">Player vs Enemy</div>
                                                 </div>
                                                  <div className="opacity-0 group-hover:opacity-100 transition-opacity">
                                                     <button onClick={(e) => { e.stopPropagation(); onUpdateBattles(battles.filter(x => x.id !== b.id)); }} className="p-1 text-gray-600 hover:text-red-500"><Trash2 size={14}/></button>
                                                 </div>
                                             </div>
