                    </div>
                    {/* BATTLES TOOL LIST */}
                    <div>
                        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2 mt-4">Battles</div>
                        <div className="space-y-1">{battles.map(battle => (<button key={battle.id} onClick={() => setSelectedTool(selectedTool?.id === battle.id ? null : { type: 'battle', id: battle.id })} className={`w-full flex items-center gap-2 p-2 rounded-lg border transition-all ${selectedTool?.id === battle.id && selectedTool.type === 'battle' ? 'bg-red-600/20 border-red-500 ring-1 ring-red-500' : 'bg-gray-900 border-gray-700 hover:border-gray-500 hover:bg-gray-800'}`}><div className="w-6 h-6 rounded border border-gray-600 bg-gray-800 overflow-hidden flex items-center justify-center flex-shrink-0 text-red-500"><Sword size={14}/></div><span className="text-xs font-medium truncate flex-1 text-left">{battle.name}</span>{selectedTool?.id === battle.id && selectedTool.type === 'battle' && <MousePointerClick size={12} className="ml-auto text-red-400"/>}</button>))}</div>
                    </div>

