                        // ... existing scene logic ...
                        const scene = scenes.find(s => s.id === spot.sceneId); 
                        let iconSrc = scene?.mapIconSrc; let bgColor = '#ffffff'; let name = scene?.name || 'Unknown Scene'; 
                        if (scene && !iconSrc && scene.characters.length > 0) { const char = characters.find(c => c.id === scene.characters[0].characterId); if(char) { iconSrc = char.mapSpriteSrc; bgColor = char.rpgColor; } } 
