                        <input className="bg-transparent text-xl font-bold outline-none placeholder-gray-600 focus:text-white transition-colors w-full" value={scene.name} onChange={(e) => updateScene(scene.id, { name: e.target.value })} placeholder="Scene Name" />
                     </div>
                     <input className="w-full bg-gray-900/50 border-b border-gray-700 text-sm py-1 px-2 focus:border-indigo-500 outline-none transition-colors text-indigo-200" value={scene.locationName || ''} onChange={(e) => updateScene(scene.id, { locationName: e.target.value })} placeholder="Location Name (Visible)" />
                  </div>
                  <button onClick={() => { onUpdateScenes(scenes.filter(s => s.id !== scene.id)); setEditingItem(null); }} className="text-gray-500 hover:text-red-500 transition-colors p-2 hover:bg-red-900/20 rounded"><Trash2 size={18} /></button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                  {/* Visuals & Goal */}
                  <div className="space-y-4">
                    <div className="w-full h-40 bg-gray-950 rounded-lg border border-gray-600 overflow-hidden relative group shadow-inner">
                       {scene.backgroundSrc ? (
                          <img src={scene.backgroundSrc} alt="bg" className="w-full h-full object-contain bg-black" />
                       ) : (
                         <div className="w-full h-full flex items-center justify-center text-gray-500 gap-2"><ImageIcon size={24} /> No Background</div>
                       )}
                       <label className="absolute inset-0 flex items-center justify-center cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity bg-black/40">
                          <span className="bg-black/80 px-4 py-2 rounded hover:bg-black text-sm border border-gray-600">Change Background</span>
                          <input type="file" accept="image/*" className="hidden" onChange={(e) => handleBgUpload(scene.id, e)} />
                       </label>
                    </div>

                    <div className="space-y-2">
                      <div className="flex justify-between items-center">
                          <label className="flex items-center gap-2 text-xs font-bold text-green-400"><Target size={14} /> WIN CONDITION</label>
                          <label className="flex items-center gap-2 text-[10px] text-gray-400 cursor-pointer select-none">
                            <input type="checkbox" className="accent-indigo-500" checked={scene.isRepeatable || false} onChange={(e) => updateScene(scene.id, { isRepeatable: e.target.checked })} />
                            <span className={scene.isRepeatable ? 'text-indigo-300 font-bold' : ''}>Repeatable?</span>
                          </label>
                      </div>
                      <textarea className="w-full bg-gray-900 border border-green-900/50 text-green-100 rounded px-3 py-2 text-sm focus:border-green-500 outline-none resize-none transition-all shadow-inner placeholder-gray-600" value={scene.goal} onChange={(e) => updateScene(scene.id, { goal: e.target.value })} placeholder="e.g. Find the key... (LEAVE EMPTY for endless conversation)" rows={3} />
                    </div>

                    <div className="bg-gray-900/50 p-3 rounded-lg border border-gray-700">
                        <label className="flex items-center gap-2 text-xs font-bold text-yellow-500 mb-2"><Unlock size={14} /> COMPLETION EFFECTS</label>
                        <div className="space-y-2 max-h-32 overflow-y-auto custom-scrollbar">
                            {/* Filter only useful items to unlock (Scenes/Battles in THIS chapter? or global?) Global is better */}
                            {scenes.filter(s => s.id !== scene.id).map(otherScene => {
                                const effect = scene.effects?.find(u => u.type === 'scene' && u.targetId === otherScene.id);
                                let stateClass = 'bg-gray-800 border-gray-700 text-gray-500';
                                let Icon = Lock;
                                if (effect?.action === 'unlock' || (effect && !effect.action)) { stateClass = 'bg-emerald-900/30 border-emerald-600 text-emerald-200'; Icon = Unlock; } else if (effect?.action === 'lock') { stateClass = 'bg-red-900/30 border-red-600 text-red-200'; Icon = Ban; }
                                return (<button key={otherScene.id} onClick={() => toggleEffect(scene.id, 'scene', otherScene.id)} className={`w-full flex items-center gap-2 text-xs p-1.5 rounded border transition-colors ${stateClass} hover:border-gray-400`}><Icon size={12} /><span className="truncate flex-1 text-left">Scene: {otherScene.name}</span>{effect?.action === 'unlock' && <span className="text-[10px] uppercase font-bold">Unlocks</span>}{effect?.action === 'lock' && <span className="text-[10px] uppercase font-bold">Locks</span>}</button>);
                            })}
                            {battles.map(b => {
                                const effect = scene.effects?.find(u => u.type === 'battle' && u.targetId === b.id);
                                let stateClass = 'bg-gray-800 border-gray-700 text-gray-500';
                                let Icon = Lock;
                                if (effect?.action === 'unlock' || (effect && !effect.action)) { stateClass = 'bg-red-900/30 border-red-600 text-red-200'; Icon = Sword; } else if (effect?.action === 'lock') { stateClass = 'bg-gray-800 border-gray-600 text-gray-500'; Icon = Ban; }
                                return (<button key={b.id} onClick={() => toggleEffect(scene.id, 'battle', b.id)} className={`w-full flex items-center gap-2 text-xs p-1.5 rounded border transition-colors ${stateClass} hover:border-gray-400`}><Icon size={12} /><span className="truncate flex-1 text-left">Battle: {b.name}</span>{effect?.action === 'unlock' && <span className="text-[10px] uppercase font-bold">Unlocks</span>}{effect?.action === 'lock' && <span className="text-[10px] uppercase font-bold">Locks</span>}</button>);
                            })}
                        </div>
                    </div>
                  </div>

                  {/* Narrative Setup */}
                  <div className="space-y-4 flex flex-col h-full">
                     <label className="block text-xs font-bold text-gray-400 flex items-center gap-2"><Eye size={14}/> VISIBLE DESCRIPTION (Intro text for Player & AI)</label>
                     <textarea
                        className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-2 text-sm focus:border-indigo-500 outline-none resize-none transition-all"
                        value={scene.description}
                        onChange={(e) => updateScene(scene.id, { description: e.target.value })}
                        placeholder="Describe the setting, the mood, and what is happening initially..."
                        rows={3}
                      />

                     <div className="space-y-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <div>
                            <label className="block text-xs font-bold text-rose-400 flex items-center gap-2"><EyeOff size={14}/> HIDDEN AI INSTRUCTIONS</label>
                            <textarea
                                className="w-full bg-gray-900 border border-rose-900/50 text-rose-100 rounded px-3 py-2 text-sm focus:border-rose-500 outline-none resize-none transition-all shadow-inner placeholder-rose-900/50"
                                value={scene.aiInstructions || ''}
                                onChange={(e) => updateScene(scene.id, { aiInstructions: e.target.value })}
                                placeholder="e.g. 'Char X is lying about the key'..."
                                rows={2}
                              />
                          </div>
                          <div>
                            <label className="block text-xs font-bold text-sky-400 flex items-center gap-2"><Ear size={14}/> <Wind size={14}/> SENSORY DETAILS</label>
                            <textarea
                                className="w-full bg-gray-900 border border-sky-900/50 text-sky-100 rounded px-3 py-2 text-sm focus:border-sky-500 outline-none resize-none transition-all shadow-inner placeholder-sky-900/50"
                                value={scene.sensoryDetails || ''}
                                onChange={(e) => updateScene(scene.id, { sensoryDetails: e.target.value })}
                                placeholder="Atmosphere, Smells, Sounds..."
                                rows={2}
                              />
                          </div>
                        </div>
                        <div>
                          <label className="block text-xs font-bold text-indigo-400 flex items-center gap-2"><Layout size={14}/> ENVIRONMENT LAYOUT</label>
                          <textarea
                              className="w-full bg-gray-900 border border-indigo-900/50 text-indigo-100 rounded px-3 py-2 text-sm focus:border-indigo-500 outline-none resize-none transition-all shadow-inner placeholder-indigo-900/50"
                              value={scene.environmentDetails || ''}
                              onChange={(e) => updateScene(scene.id, { environmentDetails: e.target.value })}
                              placeholder="Room layout, objects, doors..."
                              rows={2}
                            />
                        </div>
                     </div>

                      <label className="block text-xs font-bold text-gray-400 mt-2">PARTICIPATING CHARACTERS</label>
                      <div className="bg-gray-900 rounded-lg p-3 border border-gray-700 min-h-[100px] shadow-inner flex-1">
                         <div className="flex gap-2 flex-wrap mb-3">
                           {characters.map(char => {
                             const isActive = scene.characters.some(c => c.characterId === char.id);
                             return (<button key={char.id} onClick={() => toggleCharInScene(scene.id, char.id)} className={`text-xs px-3 py-1 rounded-full border transition-all ${isActive ? 'bg-indigo-600 border-indigo-400 text-white shadow-md' : 'bg-gray-800 border-gray-600 text-gray-400 hover:border-gray-400 hover:text-gray-300'}`}>{char.name}</button>)
                           })}
                         </div>
                         <div className="space-y-3">
                           {scene.characters.map(sc => {
                             const char = characters.find(c => c.id === sc.characterId);
                             if (!char) return null;
                             return (
                               <div key={sc.characterId} className="flex items-center gap-3 bg-gray-800 p-2 rounded border border-gray-700">
                                 <div className="w-8 h-8 rounded-full bg-gray-700 overflow-hidden flex-shrink-0 border border-gray-600" style={{ backgroundColor: char.rpgColor }}>{char.imageSrc && <img src={char.imageSrc} className="w-full h-full object-cover" />}</div>
                                 <div className="flex-1"><div className="text-xs font-bold text-indigo-300">{char.name} Role</div><input className="w-full bg-transparent border-b border-gray-600 text-xs py-1 focus:border-indigo-400 outline-none transition-colors" placeholder="What does this character want in this scene?" value={sc.roleInScene} onChange={(e) => updateSceneCharRole(scene.id, sc.characterId, e.target.value)} /></div>
                               </div>
                             )
                           })}
                         </div>
                      </div>
                  </div>
                </div>
             </div>
          );
      } else if (editingItem.type === 'battle') {
          const battle = battles.find(b => b.id === editingItem.id);
          if (!battle) return null;

          return (
             <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
                 <div className="flex justify-between items-center border-b border-gray-700 pb-4">
                     <div className="flex items-center gap-4">
                        <div className="bg-red-900/50 px-3 py-1 rounded text-xs font-bold text-red-400 border border-red-700">BATTLE EDITOR</div>
                        <input className="bg-transparent text-xl font-bold outline-none placeholder-gray-600 focus:text-white transition-colors" value={battle.name} onChange={(e) => updateBattle(battle.id, { name: e.target.value })} placeholder="Battle Name" />
                     </div>
                     <button onClick={() => { onUpdateBattles(battles.filter(b => b.id !== battle.id)); setEditingItem(null); }} className="text-gray-500 hover:text-red-500 transition-colors p-2 hover:bg-red-900/20 rounded"><Trash2 size={18} /></button>
                 </div>

                 <div className="w-full h-48 bg-gray-950 rounded-lg border border-gray-600 overflow-hidden relative group shadow-inner">
                      {battle.backgroundSrc ? (
                          <img src={battle.backgroundSrc} alt="bg" className="w-full h-full object-cover opacity-80" />
                      ) : (
                          <div className="w-full h-full flex items-center justify-center text-gray-500 gap-2"><ImageIcon size={24} /> No Background</div>
                      )}
                      <label className="absolute inset-0 flex items-center justify-center cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity bg-black/40">
                          <span className="bg-black/80 px-4 py-2 rounded hover:bg-black text-sm border border-gray-600">Change Battle Background</span>
                          <input type="file" accept="image/*" className="hidden" onChange={(e) => handleBattleBgUpload(battle.id, e)} />
                      </label>
                 </div>

                 <div className="grid grid-cols-2 gap-6">
                     <div className="bg-gray-900/50 p-4 rounded border border-indigo-900/30">
                         <div className="text-xs font-bold text-indigo-400 mb-2 flex items-center gap-2"><Shield size={14}/> PLAYER TEAM</div>
                         <div className="flex flex-wrap gap-2">
                             {characters.map(char => {
                                 const isAdded = battle.playerCharacterIds.includes(char.id);
                                 return (
                                     <button key={char.id} onClick={() => toggleCharInBattle(battle.id, char.id, 'player')} className={`text-xs px-2 py-1 rounded border ${isAdded ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-gray-800 border-gray-600 text-gray-500'}`}>
                                         {char.name}
                                     </button>
                                 )
                             })}
                         </div>
                     </div>
                     <div className="bg-gray-900/50 p-4 rounded border border-red-900/30">
                         <div className="text-xs font-bold text-red-400 mb-2 flex items-center gap-2"><Skull size={14}/> ENEMY TEAM</div>
                         <div className="flex flex-wrap gap-2">
                             {characters.map(char => {
                                 const isAdded = battle.enemyCharacterIds.includes(char.id);
                                 return (
                                     <button key={char.id} onClick={() => toggleCharInBattle(battle.id, char.id, 'enemy')} className={`text-xs px-2 py-1 rounded border ${isAdded ? 'bg-red-600 border-red-500 text-white' : 'bg-gray-800 border-gray-600 text-gray-500'}`}>
                                         {char.name}
                                     </button>
                                 )
                             })}
                         </div>
                     </div>
                 </div>
             </div>
          )
      }
      return null;
  };

  return (
    <div className="flex flex-col h-full max-w-6xl mx-auto p-4 md:p-8">
      {/* Header / Toolbar */}
      <div className="flex flex-col xl:flex-row justify-between items-center mb-8 gap-6">
        <div>
           <h1 className="text-3xl font-bold text-indigo-400">VN Creator Studio</h1>
           <p className="text-gray-400 text-sm mt-1">Design your world, characters, and stories.</p>
        </div>

        <div className="flex flex-wrap gap-3 items-center justify-center">
          {/* File Operations */}
          <div className="flex gap-2 mr-2 bg-gray-800 p-1 rounded-lg border border-gray-700">
             <input type="file" ref={importInputRef} className="hidden" accept=".json" onChange={handleFileChange} />
             <button onClick={handleImportClick} className="flex items-center gap-2 px-3 py-2 text-sm text-gray-300 hover:text-white hover:bg-gray-700 rounded transition" title="Load .json file">
               <Upload size={16} /> Load Project
             </button>
             <div className="w-[1px] bg-gray-600 my-1"></div>
             <button onClick={onExportProject} className="flex items-center gap-2 px-3 py-2 text-sm text-gray-300 hover:text-white hover:bg-gray-700 rounded transition" title="Download .json file">
               <Download size={16} /> Export Project
             </button>
          </div>

          <Button onClick={handleQuickSaveClick} variant="secondary" title="Saves to Browser Storage" className="min-w-[140px]" disabled={saveStatus === 'saving'}>
            {saveStatus === 'saved' ? <><Check size={18} className="text-green-400"/> Saved!</> : (saveStatus === 'saving' ? 'Saving...' : <><Save size={18} /> Quick Save</>)}
          </Button>

          <div className="h-8 w-[1px] bg-gray-700 mx-2 hidden md:block"></div>

          {hasSaveGame && (
            <Button onClick={onContinueGame} className="bg-yellow-600 hover:bg-yellow-500">
              <RotateCcw size={18} /> Continue
            </Button>
          )}

          <Button onClick={onPlay} className="bg-green-600 hover:bg-green-500 px-6 font-bold shadow-green-900/20">
            <PlayCircle size={18} /> PLAY GAME
          </Button>
        </div>
      </div>

      <div className="flex gap-4 mb-6 border-b border-gray-700 pb-1 overflow-x-auto">
        <button onClick={() => setActiveTab('chars')} className={`px-4 py-2 font-medium transition-colors whitespace-nowrap ${activeTab === 'chars' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}>Characters</button>
        <button onClick={() => setActiveTab('story')} className={`px-4 py-2 font-medium transition-colors whitespace-nowrap ${activeTab === 'story' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}>World & Story</button>
        <button onClick={() => setActiveTab('map')} className={`px-4 py-2 font-medium transition-colors whitespace-nowrap ${activeTab === 'map' ? 'text-indigo-400 border-b-2 border-indigo-400' : 'text-gray-400 hover:text-white'}`}>World Map</button>
      </div>

      <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
        {activeTab === 'chars' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {characters.map(char => (
                <div key={char.id} className="bg-gray-800 p-4 rounded-xl border border-gray-700 flex flex-col gap-4 shadow-lg hover:border-gray-600 transition-colors">
                  <div className="flex gap-4">
                      <div className="w-24 h-32 bg-gray-900 rounded-lg flex-shrink-0 border border-gray-600 overflow-hidden relative group">
                        {char.imageSrc ? (
                          <img src={char.imageSrc} alt={char.name} className="w-full h-full object-cover" />
                        ) : (
                          <div className="w-full h-full flex flex-col items-center justify-center text-gray-600 gap-1"><User size={24} /><span className="text-[10px] text-center px-1">Portrait</span></div>
                        )}
                        <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity text-xs font-bold">
                          UPLOAD
                          <input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e, 'imageSrc')} />
                        </label>
                      </div>
                      <div className="flex-1 space-y-3">
                        <input className="w-full bg-gray-900 border border-gray-700 rounded px-3 py-1 focus:border-indigo-500 outline-none transition-all" value={char.name} onChange={(e) => updateCharacter(char.id, { name: e.target.value })} placeholder="Character Name" />
                        <textarea 
                           className="w-full bg-gray-900 border border-gray-700 rounded px-2 py-1 text-xs focus:border-indigo-500 outline-none resize-none"
                           value={char.defaultDescription}
                           onChange={(e) => updateCharacter(char.id, { defaultDescription: e.target.value })}
                           placeholder="Persona / Behavior"
                           rows={2}
                        />
                        <textarea 
                           className="w-full bg-gray-900 border border-gray-700 rounded px-2 py-1 text-xs focus:border-indigo-500 outline-none resize-none placeholder-indigo-300/30"
                           value={char.lore || ''}
                           onChange={(e) => updateCharacter(char.id, { lore: e.target.value })}
                           placeholder="Lore / Backstory / Secrets (Hidden Context for AI)"
                           rows={2}
                        />

                        <div className="grid grid-cols-2 gap-3">
                          {/* Map Sprite & Color */}
                          <div className="flex items-center gap-2">
                              <div className="w-10 h-10 bg-gray-900 rounded border border-gray-600 overflow-hidden relative group shrink-0">
                                {char.mapSpriteSrc ? <img src={char.mapSpriteSrc} alt="Sprite" className="w-full h-full object-contain" /> : <div className="w-full h-full flex items-center justify-center text-gray-600" title="Map Sprite"><MapIcon size={16} /></div>}
                                <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity">
                                    <FileUp size={16} className="text-white"/>
                                    <input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e, 'mapSpriteSrc')} />
                                </label>
                              </div>
                              <div className="text-xs text-gray-400">Map Sprite</div>
                          </div>

                          {/* Text Settings */}
                          <div className="flex flex-col gap-2">
                              <label className="flex items-center gap-2 text-xs text-gray-400 cursor-pointer" title="Chat Bubble Color">
                                <input type="color" className="w-6 h-6 rounded bg-transparent cursor-pointer border-none p-0" value={char.bubbleColor || '#4b5563'} onChange={(e) => updateCharacter(char.id, { bubbleColor: e.target.value })} />
                                <span>Bubble Color</span>
                              </label>
                              <label className="flex items-center gap-2 text-xs text-gray-400 cursor-pointer">
                                <input type="checkbox" className="accent-indigo-500 rounded" checked={char.isItalic || false} onChange={(e) => updateCharacter(char.id, { isItalic: e.target.checked })} />
                                <span className={char.isItalic ? 'italic' : ''}>Italic Text</span>
                              </label>
                          </div>
                        </div>
                      </div>
                      <button onClick={() => onUpdateCharacters(characters.filter(c => c.id !== char.id))} className="text-gray-500 hover:text-red-500 h-fit transition-colors p-1"><Trash2 size={18} /></button>
                  </div>

                  {/* RPG Stats Section */}
                  <div className="border-t border-gray-700 pt-3">
                      <div className="text-xs font-bold text-red-400 mb-2 flex items-center gap-2"><Sword size={12}/> COMBAT STATS</div>
                      <div className="grid grid-cols-5 gap-2 text-center text-xs mb-3">
                          <label className="flex flex-col"><span className="text-gray-500">STR</span><input type="number" className="bg-gray-900 rounded border border-gray-700 text-center w-full py-1" value={char.stats?.str || 0} onChange={(e) => updateCharStats(char.id, { str: parseInt(e.target.value) })} /></label>
                          <label className="flex flex-col"><span className="text-gray-500">GES</span><input type="number" className="bg-gray-900 rounded border border-gray-700 text-center w-full py-1" value={char.stats?.ges || 0} onChange={(e) => updateCharStats(char.id, { ges: parseInt(e.target.value) })} /></label>
                          <label className="flex flex-col"><span className="text-gray-500">WID</span><input type="number" className="bg-gray-900 rounded border border-gray-700 text-center w-full py-1" value={char.stats?.wid || 0} onChange={(e) => updateCharStats(char.id, { wid: parseInt(e.target.value) })} /></label>
                          <label className="flex flex-col"><span className="text-gray-500">WIL</span><input type="number" className="bg-gray-900 rounded border border-gray-700 text-center w-full py-1" value={char.stats?.wil || 0} onChange={(e) => updateCharStats(char.id, { wil: parseInt(e.target.value) })} /></label>
                          <label className="flex flex-col"><span className="text-gray-500">PRÄ</span><input type="number" className="bg-gray-900 rounded border border-gray-700 text-center w-full py-1" value={char.stats?.pra || 0} onChange={(e) => updateCharStats(char.id, { pra: parseInt(e.target.value) })} /></label>
                      </div>
                      <div className="grid grid-cols-2 gap-4 mb-3">
                           <label className="flex items-center gap-2 text-xs"><span className="text-gray-400 w-16">MAX HP</span><input type="number" className="bg-gray-900 rounded border border-gray-700 w-full py-1 px-2" value={char.stats?.maxHp || 20} onChange={(e) => updateCharStats(char.id, { maxHp: parseInt(e.target.value), hp: parseInt(e.target.value) })} /></label>
                           <label className="flex items-center gap-2 text-xs"><span className="text-gray-400 w-16">LIMIT</span><input type="number" className="bg-gray-900 rounded border border-gray-700 w-full py-1 px-2" value={char.stats?.limit || 10} onChange={(e) => updateCharStats(char.id, { limit: parseInt(e.target.value) })} /></label>
                      </div>

                      {/* Battle Sprites & Scales */}
                      <div className="mb-3">
                          <div className="flex justify-between items-center mb-2">
                            <div className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Battle Sprites</div>
                          </div>
                          <div className="grid grid-cols-3 gap-2">
                             {/* Idle Sprite */}
                             <div className="flex flex-col gap-1">
                                <div className="bg-gray-900 border border-gray-700 rounded p-1 flex flex-col items-center justify-center group relative h-20">
                                    {char.battleIdleSrc ? <img src={char.battleIdleSrc} className="h-full w-full object-contain"/> : <User size={24} className="text-gray-600"/>}
                                    <span className="text-[9px] text-gray-500 absolute bottom-1">Idle</span>
                                    <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity z-10"><Upload size={16}/><input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e, 'battleIdleSrc')} /></label>
                                </div>
                                <div className="flex items-center gap-1 bg-gray-900 rounded px-1 border border-gray-700" title="Idle Scale">
                                    <Scaling size={10} className="text-gray-500"/>
                                    <input type="range" min="0.5" max="3" step="0.1" className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer" value={char.battleIdleScale || char.battleScale || 1} onChange={(e) => updateCharacter(char.id, { battleIdleScale: parseFloat(e.target.value) })} />
                                </div>
                             </div>

                             {/* Prep Sprite */}
