                             <label className="flex items-center gap-1"><span className="text-gray-500">CAP</span><input type="number" className="w-full bg-gray-900 border border-gray-600 rounded px-1" placeholder="-" value={char.stats?.weapon?.cap || ''} onChange={(e) => updateCharWeapon(char.id, { cap: e.target.value ? parseInt(e.target.value) : null })} /></label>
                          </div>
                      </div>
                  </div>
                </div>
              ))}
            </div>
            <Button onClick={addCharacter} variant="secondary" className="w-full py-4 border-dashed opacity-70 hover:opacity-100"><Plus size={20} /> Add Character</Button>
