                                            <input className="bg-transparent border-b border-gray-700 text-lg font-bold text-green-200 focus:border-green-500 outline-none w-full mr-2 pb-1" value={l.name} onChange={(e) => updateLoreLocation(l.id, { name: e.target.value })} placeholder="Location Name" />
