                                <span>Bubble Color</span>
                              </label>
                              <label className="flex items-center gap-2 text-xs text-gray-400 cursor-pointer">
                                <input type="checkbox" className="accent-indigo-500 rounded" checked={char.isItalic || false} onChange={(e) => updateCharacter(char.id, { isItalic: e.target.checked })} />
                                <span className={char.isItalic ? 'italic' : ''}>Italic Text</span>
                              </label>
                          </div>
                        </div>
                      </div>
                      <button onClick={() => onUpdateCharacters(characters.filter(c => c.id !== char.id))} className="text-gray-500 hover:text-red-500 h-fit transition-colors p-1"><Trash2 size={18} /></button>
