                          <div className="grid grid-cols-3 gap-2">
                             {/* Idle Sprite */}
                             <div className="flex flex-col gap-1">
                                <div className="bg-gray-900 border border-gray-700 rounded p-1 flex flex-col items-center justify-center group relative h-20">
                                    {char.battleIdleSrc ? <img src={char.battleIdleSrc} className="h-full w-full object-contain"/> : <User size={24} className="text-gray-600"/>}
