                                    <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity z-10"><Upload size={16}/><input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e, 'battlePrepSrc')} /></label>
                                </div>
                                <div className="flex items-center gap-1 bg-gray-900 rounded px-1 border border-gray-700" title="Prep Scale">
                                    <Scaling size={10} className="text-gray-500"/>
                                    <input type="range" min="0.5" max="3" step="0.1" className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer" value={char.battlePrepScale || char.battleScale || 1} onChange={(e) => updateCharacter(char.id, { battlePrepScale: parseFloat(e.target.value) })} />
                                </div>
                             </div>

                             {/* Hit Sprite */}
                             <div className="flex flex-col gap-1">
                                <div className="bg-gray-900 border border-gray-700 rounded p-1 flex flex-col items-center justify-center group relative h-20">
                                    {char.battleHitSrc ? <img src={char.battleHitSrc} className="h-full w-full object-contain"/> : <Crosshair size={24} className="text-gray-600"/>}
                                    <span className="text-[9px] text-gray-500 absolute bottom-1">Hit</span>
                                    <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center cursor-pointer transition-opacity z-10"><Upload size={16}/><input type="file" accept="image/*" className="hidden" onChange={(e) => handleCharImageUpload(char.id, e, 'battleHitSrc')} /></label>
                                </div>
                                <div className="flex items-center gap-1 bg-gray-900 rounded px-1 border border-gray-700" title="Hit Scale">
                                    <Scaling size={10} className="text-gray-500"/>
                                    <input type="range" min="0.5" max="3" step="0.1" className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer" value={char.battleHitScale || char.battleScale || 1} onChange={(e) => updateCharacter(char.id, { battleHitScale: parseFloat(e.target.value) })} />
                                </div>
                             </div>
                          </div>
                      </div>

                      <div className="bg-black/30 p-2 rounded border border-gray-700">
                          <div className="text-[10px] font-bold text-gray-500 mb-1">EQUIPPED WEAPON</div>
                          <div className="grid grid-cols-2 gap-2 text-xs">
                             <input className="bg-gray-900 border border-gray-600 rounded px-2 py-1 col-span-2" placeholder="Weapon Name" value={char.stats?.weapon?.name || ''} onChange={(e) => updateCharWeapon(char.id, { name: e.target.value })} />
                             <label className="flex items-center gap-1"><span className="text-gray-500">AT</span><input type="number" className="w-full bg-gray-900 border border-gray-600 rounded px-1" value={char.stats?.weapon?.at || 1} onChange={(e) => updateCharWeapon(char.id, { at: parseInt(e.target.value) })} /></label>
                             <label className="flex items-center gap-1"><span className="text-gray-500">MOD</span><input type="number" className="w-full bg-gray-900 border border-gray-600 rounded px-1" value={char.stats?.weapon?.mod || 0} onChange={(e) => updateCharWeapon(char.id, { mod: parseInt(e.target.value) })} /></label>
                             <label className="flex items-center gap-1"><span className="text-gray-500">DMG</span><input type="number" className="w-full bg-gray-900 border border-gray-600 rounded px-1" value={char.stats?.weapon?.dmg || 1} onChange={(e) => updateCharWeapon(char.id, { dmg: parseInt(e.target.value) })} /></label>
                             <label className="flex items-center gap-1"><span className="text-gray-500">CAP</span><input type="number" className="w-full bg-gray-900 border border-gray-600 rounded px-1" placeholder="-" value={char.stats?.weapon?.cap || ''} onChange={(e) => updateCharWeapon(char.id, { cap: e.target.value ? parseInt(e.target.value) : null })} /></label>
                          </div>
                      </div>
                  </div>
                </div>
              ))}
            </div>
            <Button onClick={addCharacter} variant="secondary" className="w-full py-4 border-dashed opacity-70 hover:opacity-100"><Plus size={20} /> Add Character</Button>
          </div>
        )}

        {/* WORLD TAB */}
        {activeTab === 'world' && (
          <div className="space-y-6 h-full flex flex-col">
              <div className="flex-1 bg-gray-800 rounded-xl border border-gray-700 shadow-md flex flex-col overflow-hidden">
                 <div className="bg-gray-900 p-2 flex gap-2 border-b border-gray-700 items-center">
                    <div className="flex items-center gap-2 text-indigo-400 font-bold px-2 text-sm">
                       <Globe size={16} /> WORLD CONFIGURATION
                    </div>
                    <div className="h-4 w-[1px] bg-gray-700 mx-2"></div>
                    <button onClick={() => setActiveWorldSubTab('general')} className={`px-3 py-1 rounded-md text-xs font-bold transition-colors ${activeWorldSubTab === 'general' ? 'bg-indigo-600 text-white' : 'text-gray-400 hover:text-white hover:bg-gray-800'}`}>General</button>
                    <button onClick={() => setActiveWorldSubTab('factions')} className={`px-3 py-1 rounded-md text-xs font-bold transition-colors ${activeWorldSubTab === 'factions' ? 'bg-indigo-600 text-white' : 'text-gray-400 hover:text-white hover:bg-gray-800'}`}>Factions</button>
                    <button onClick={() => setActiveWorldSubTab('locations')} className={`px-3 py-1 rounded-md text-xs font-bold transition-colors ${activeWorldSubTab === 'locations' ? 'bg-indigo-600 text-white' : 'text-gray-400 hover:text-white hover:bg-gray-800'}`}>Lore Locations</button>
                 </div>

                 <div className="p-6 overflow-y-auto custom-scrollbar bg-gray-800/50 flex-1">
                    {activeWorldSubTab === 'general' && (
                        <div className="space-y-2 h-full flex flex-col">
                            <label className="text-sm text-gray-400 font-bold uppercase flex items-center gap-2"><Feather size={16}/> World Overview / History</label>
                            <textarea 
                                className="w-full flex-1 bg-gray-900 border border-gray-600 rounded-xl p-4 text-base text-gray-200 outline-none focus:border-indigo-500 transition-colors placeholder-gray-600 leading-relaxed resize-none"
                                placeholder="Describe the world setting, major lore, history, and atmosphere that applies to EVERYTHING..."
                                value={worldInfo.description}
                                onChange={(e) => onUpdateWorldInfo({ ...worldInfo, description: e.target.value })}
                             />
                        </div>
                    )}

                    {activeWorldSubTab === 'factions' && (
                        <div className="space-y-4">
                            <div className="flex justify-between items-center border-b border-gray-700 pb-2">
                                <span className="text-sm text-gray-400 font-bold uppercase flex items-center gap-2"><Users size={16}/> Major Groups & Politics</span>
                                <button onClick={addFaction} className="flex items-center gap-2 text-sm bg-indigo-600 text-white px-3 py-1.5 rounded hover:bg-indigo-500 shadow-lg"><Plus size={14}/> Add Faction</button>
                            </div>
                            {(!worldInfo.factions || worldInfo.factions.length === 0) && <div className="text-center text-gray-500 italic py-10">No factions defined yet. Add one to describe political groups or gangs.</div>}
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                {worldInfo.factions?.map(f => (
                                    <div key={f.id} className="bg-gray-900 p-4 rounded-xl border border-gray-700 flex flex-col gap-3 shadow-md hover:border-gray-500 transition-colors">
                                        <div className="flex justify-between items-center">
                                            <input className="bg-transparent border-b border-gray-700 text-lg font-bold text-indigo-200 focus:border-indigo-500 outline-none w-full mr-2 pb-1" value={f.name} onChange={(e) => updateFaction(f.id, { name: e.target.value })} placeholder="Faction Name" />
                                            <button onClick={() => deleteFaction(f.id)} className="text-gray-600 hover:text-red-500 p-1 hover:bg-red-900/20 rounded"><Trash2 size={16}/></button>
                                        </div>
                                        <textarea className="bg-gray-800/50 border border-gray-700 rounded-lg p-3 text-sm text-gray-300 outline-none resize-none focus:border-indigo-500/50 h-32" value={f.description} onChange={(e) => updateFaction(f.id, { description: e.target.value })} placeholder="Description & Goals" />
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {activeWorldSubTab === 'locations' && (
                        <div className="space-y-4">
                            <div className="flex justify-between items-center border-b border-gray-700 pb-2">
                                <span className="text-sm text-gray-400 font-bold uppercase flex items-center gap-2"><MapPin size={16}/> Important Places (Lore Only)</span>
                                <button onClick={addLoreLocation} className="flex items-center gap-2 text-sm bg-indigo-600 text-white px-3 py-1.5 rounded hover:bg-indigo-500 shadow-lg"><Plus size={14}/> Add Location</button>
                            </div>
