                                    <div key={l.id} className="bg-gray-900 p-4 rounded-xl border border-gray-700 flex flex-col gap-3 shadow-md hover:border-gray-500 transition-colors">
                                        <div className="flex justify-between items-center">
                                            <input className="bg-transparent border-b border-gray-700 text-lg font-bold text-green-200 focus:border-green-500 outline-none w-full mr-2 pb-1" value={l.name} onChange={(e) => updateLoreLocation(l.id, { name: e.target.value })} placeholder="Location Name" />
                                            <button onClick={() => deleteLoreLocation(l.id)} className="text-gray-600 hover:text-red-500 p-1 hover:bg-red-900/20 rounded"><Trash2 size={16}/></button>
                                        </div>
                                        <textarea className="bg-gray-800/50 border border-gray-700 rounded-lg p-3 text-sm text-gray-300 outline-none resize-none focus:border-green-500/50 h-32" value={l.description} onChange={(e) => updateLoreLocation(l.id, { description: e.target.value })} placeholder="Description & Significance" />
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                 </div>
              </div>
          </div>
        )}

        {/* STORY & CHAPTERS TAB */}
        {activeTab === 'story' && (
          <div className="flex-1 flex gap-6 overflow-hidden h-full">
