                      <span>CHAPTERS</span>
                      <button onClick={addChapter} className="text-indigo-400 hover:text-white p-1 hover:bg-indigo-900 rounded"><Plus size={16} /></button>
                  </div>
                  <div className="flex-1 overflow-y-auto custom-scrollbar space-y-2">
                      {chapters.map(chap => (
                          <button 
                            key={chap.id}
                            onClick={() => { setActiveChapterId(chap.id); setEditingItem(null); }}
                            className={`w-full text-left p-3 rounded-lg text-sm font-medium transition-all border flex items-center gap-2 group relative
                                ${activeChapterId === chap.id ? 'bg-indigo-600 border-indigo-400 text-white shadow-md' : 'bg-gray-900 border-gray-700 text-gray-400 hover:border-gray-500 hover:text-gray-200'}
