                             {characters.map(char => {
                                 const isAdded = battle.playerCharacterIds.includes(char.id);
                                 return (
                                     <button key={char.id} onClick={() => toggleCharInBattle(battle.id, char.id, 'player')} className={`text-xs px-2 py-1 rounded border ${isAdded ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-gray-800 border-gray-600 text-gray-500'}`}>
                                         {char.name}
                                     </button>
                                 )
                             })}
                         </div>
                     </div>
                     <div className="bg-gray-900/50 p-4 rounded border border-red-900/30">
                         <div className="text-xs font-bold text-red-400 mb-2 flex items-center gap-2"><Skull size={14}/> ENEMY TEAM</div>
                         <div className="flex flex-wrap gap-2">
                             {characters.map(char => {
                                 const isAdded = battle.enemyCharacterIds.includes(char.id);
                                 return (
                                     <button key={char.id} onClick={() => toggleCharInBattle(battle.id, char.id, 'enemy')} className={`text-xs px-2 py-1 rounded border ${isAdded ? 'bg-red-600 border-red-500 text-white' : 'bg-gray-800 border-gray-600 text-gray-500'}`}>
                                         {char.name}
                                     </button>
                                 )
