import React, { useState, useEffect, useRef } from 'react';
import { Battle, Character, Zone, WorldInfo, DieData } from '../types';
import { calculateTotalRoll } from '../utils';

interface BattleArenaProps {
    battle: Battle;
    characters: Character[];
    zone: Zone;
    worldInfo: WorldInfo;
    rollDice: (die: number, modifier?: number) => void;
}

const BattleArena: React.FC<BattleArenaProps> = ({ battle, characters, zone, worldInfo, rollDice }) => {
    const [currentTurnIndex, setCurrentTurnIndex] = useState(0);
    const [isBattleOver, setIsBattleOver] = useState(false);
    const [battleLog, setBattleLog] = useState<string[]>([]);
    const [round, setRound] = useState(1);
    const [showRolls, setShowRolls] = useState(false);
    const [rolledDice, setRolledDice] = useState<DieData[]>([]);
    const [d20Rolls, setD20Rolls] = useState<number[]>([]);
    const [selectedCharacterIndex, setSelectedCharacterIndex] = useState<number | null>(null);
    const [hoveredCharacterIndex, setHoveredCharacterIndex] = useState<number | null>(null);
    const [isHovered, setIsHovered] = useState(false);

    const audioRef = useRef<HTMLAudioElement | null>(null);

    useEffect(() => {
        if (!battle || !battle.initiatives) {
            return;
        }

        const audio = new Audio('/sounds/ambient_battle.wav');
        audio.volume = 0.5;
        audio.loop = true;
        audioRef.current = audio;
        audio.play().catch(e => console.error("Audio playback failed: ", e));

        return () => {
