                          >
                              <Book size={16} className={activeChapterId === chap.id ? 'text-indigo-200' : 'text-gray-600'} />
                              <div className="truncate flex-1">{chap.name}</div>
                              {chapters.length > 1 && (
                                  <div onClick={(e) => { e.stopPropagation(); deleteChapter(chap.id); }} className="opacity-0 group-hover:opacity-100 p-1 hover:text-red-300">
                                      <Trash2 size={14} />
                                  </div>
                              )}
                          </button>
                      ))}
                  </div>
              </div>

              {/* Right Column: Chapter Content */}
              <div className="flex-1 bg-gray-800 p-4 rounded-xl border border-gray-700 flex flex-col shadow-lg overflow-hidden h-full">
                  {/* Active Chapter Header */}
                  {activeChapter ? (
                      <div className="flex flex-col h-full">
                         <div className="border-b border-gray-700 pb-4 mb-4 space-y-3">
                             <div className="flex items-center gap-2 text-indigo-400 text-xs font-bold uppercase tracking-wider">
                                Current Chapter
                             </div>
                             <input 
                                className="bg-transparent text-2xl font-bold outline-none text-white w-full placeholder-gray-600"
                                value={activeChapter.name}
                                onChange={(e) => updateChapter(activeChapter.id, { name: e.target.value })}
                                placeholder="Chapter Name"
                             />
                             <textarea
                                className="w-full bg-gray-900/50 border border-gray-600/50 rounded-lg p-3 text-sm text-gray-300 outline-none focus:border-indigo-500/50 transition-colors placeholder-gray-600"
                                placeholder="Chapter Context (e.g. 'The heroes are currently tired after escaping...'). Passed to AI."
                                rows={3}
                                value={activeChapter.description}
                                onChange={(e) => updateChapter(activeChapter.id, { description: e.target.value })}
                             />
                         </div>

                         {/* Content List or Item Editor */}
                         {editingItem ? (
                             <div className="flex-1 overflow-y-auto custom-scrollbar pr-2">
                                 <button onClick={() => setEditingItem(null)} className="flex items-center gap-2 text-sm text-gray-400 hover:text-white mb-6 transition-colors bg-gray-900/50 w-fit px-3 py-2 rounded-lg border border-gray-700"><RotateCcw size={14}/> Back to Chapter List</button>
                                 {renderItemEditor()}
                             </div>
                         ) : (
                             <div className="flex-1 overflow-y-auto custom-scrollbar">
                                 <div className="flex justify-between items-center mb-4">
                                     <h3 className="text-xs font-bold text-gray-500 uppercase tracking-wide">Scenarios & Battles in this Chapter</h3>
                                     <div className="flex gap-2">
                                         <button onClick={() => addScene(activeChapter.id)} className="flex items-center gap-2 px-3 py-2 bg-indigo-900/40 text-indigo-300 border border-indigo-800 rounded-lg text-xs font-bold hover:bg-indigo-800 hover:text-white transition shadow-sm"><MessageSquare size={14}/> + Scenario</button>
                                         <button onClick={() => addBattle(activeChapter.id)} className="flex items-center gap-2 px-3 py-2 bg-red-900/40 text-red-300 border border-red-800 rounded-lg text-xs font-bold hover:bg-red-800 hover:text-white transition shadow-sm"><Sword size={14}/> + Battle</button>
                                     </div>
                                 </div>

                                 <div className="space-y-3">
                                     {/* List Scenes */}
                                     {chapterScenes.map(s => (
                                         <div key={s.id} onClick={() => setEditingItem({ type: 'scene', id: s.id })} className="flex items-center p-4 rounded-xl bg-gray-900 border border-gray-700 hover:border-indigo-500/50 hover:bg-gray-900/80 cursor-pointer group transition-all shadow-sm">
                                             <div className="w-10 h-10 rounded-lg bg-gray-800 flex items-center justify-center border border-gray-600 mr-4 text-indigo-500 group-hover:scale-110 transition-transform"><MessageSquare size={20}/></div>
                                             <div className="flex-1">
                                                 <div className="text-base font-bold text-gray-200 group-hover:text-indigo-300 transition-colors">{s.name}</div>
                                                 <div className="text-xs text-gray-500 truncate">{s.description}</div>
                                             </div>
                                             <div className="opacity-0 group-hover:opacity-100 transition-opacity">
                                                 <button onClick={(e) => { e.stopPropagation(); onUpdateScenes(scenes.filter(x => x.id !== s.id)); }} className="p-2 text-gray-600 hover:text-red-500 hover:bg-red-900/20 rounded"><Trash2 size={16}/></button>
                                             </div>
                                         </div>
                                     ))}

                                     {/* List Battles */}
                                     {chapterBattles.map(b => (
                                         <div key={b.id} onClick={() => setEditingItem({ type: 'battle', id: b.id })} className="flex items-center p-4 rounded-xl bg-gray-900 border border-red-900/30 hover:border-red-500 hover:bg-gray-900/80 cursor-pointer group transition-all shadow-sm">
                                             <div className="w-10 h-10 rounded-lg bg-gray-800 flex items-center justify-center border border-gray-600 mr-4 text-red-500 group-hover:scale-110 transition-transform"><Sword size={20}/></div>
                                             <div className="flex-1">
                                                 <div className="text-base font-bold text-red-100 group-hover:text-red-300 transition-colors">{b.name}</div>
                                                 <div className="text-xs text-red-900/70 truncate">Player vs Enemy</div>
                                             </div>
                                              <div className="opacity-0 group-hover:opacity-100 transition-opacity">
                                                 <button onClick={(e) => { e.stopPropagation(); onUpdateBattles(battles.filter(x => x.id !== b.id)); }} className="p-2 text-gray-600 hover:text-red-500 hover:bg-red-900/20 rounded"><Trash2 size={16}/></button>
                                             </div>
                                         </div>
