                                            <Dice5 className="text-gray-700 opacity-20 w-12 h-12" />
                                        )}

                                        <label className="absolute inset-0 flex items-center justify-center bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer">
                                            <div className="text-xs font-bold text-white flex flex-col items-center">
                                                <Upload size={20} className="mb-1"/>
                                                Upload
                                            </div>
                                            <input type="file" multiple accept="image/*" className="hidden" onChange={(e) => handleDiceUpload(num, e)} />
                                        </label>
                                    </div>
                                    <div className="text-[10px] text-gray-500 text-center">{skins.length} variations</div>
                                </div>
                            );
