                          <label className="flex flex-col"><span className="text-gray-500">GES</span><input type="number" className="bg-gray-900 rounded border border-gray-700 text-center w-full py-1" value={char.stats?.ges || 0} onChange={(e) => updateCharStats(char.id, { ges: parseInt(e.target.value) })} /></label>
                          <label className="flex flex-col"><span className="text-gray-500">WID</span><input type="number" className="bg-gray-900 rounded border border-gray-700 text-center w-full py-1" value={char.stats?.wid || 0} onChange={(e) => updateCharStats(char.id, { wid: parseInt(e.target.value) })} /></label>
                          <label className="flex flex-col"><span className="text-gray-500">WIL</span><input type="number" className="bg-gray-900 rounded border border-gray-700 text-center w-full py-1" value={char.stats?.wil || 0} onChange={(e) => updateCharStats(char.id, { wil: parseInt(e.target.value) })} /></label>
                          <label className="flex flex-col"><span className="text-gray-500">PRÄ</span><input type="number" className="bg-gray-900 rounded border border-gray-700 text-center w-full py-1" value={char.stats?.pra || 0} onChange={(e) => updateCharStats(char.id, { pra: parseInt(e.target.value) })} /></label>
                      </div>
                      <div className="grid grid-cols-2 gap-4 mb-3">
