                           <label className="flex items-center gap-2 text-xs"><span className="text-gray-400 w-16">LIMIT</span><input type="number" className="bg-gray-900 rounded border border-gray-700 w-full py-1 px-2" value={char.stats?.limit || 10} onChange={(e) => updateCharStats(char.id, { limit: parseInt(e.target.value) })} /></label>
