                                            <button onClick={() => deleteLoreLocation(l.id)} className="text-gray-600 hover:text-red-500 p-1 hover:bg-red-900/20 rounded"><Trash2 size={16}/></button>
                                        </div>
                                        <textarea className="bg-gray-800/50 border border-gray-700 rounded-lg p-3 text-sm text-gray-300 outline-none resize-none focus:border-green-500/50 h-32" value={l.description} onChange={(e) => updateLoreLocation(l.id, { description: e.target.value })} placeholder="Description & Significance" />
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                 </div>
              </div>
          </div>
