                );
            })}
            {maps.length <= 1 && <div className="text-xs text-gray-600 italic">Create more maps to add transitions.</div>}
        </div>
    </div>
</div>

import React, { useState } from 'react';
import { WorldInfo, Chapter, Character, Scene, WorldMap, Battle, SceneEffect, MapSpot, SceneCharacterConfig, Zone } from '../types';
import { Button } from './ui/Button';
import { 
  Save, Play, Upload, Download, Plus, Trash, 
  Map as MapIcon, Users, FileText, Globe, Crosshair, 
  Settings, Unlock, Lock, MessageSquare, Sword, Waypoints, BookOpen, Image as ImageIcon
} from 'lucide-react';

interface EditorProps {
  worldInfo: WorldInfo;
  chapters: Chapter[];
  characters: Character[];
  scenes: Scene[];
  maps: WorldMap[];
  battles: Battle[];

  onUpdateWorldInfo: (info: WorldInfo) => void;
  onUpdateChapters: (chapters: Chapter[]) => void;
  onUpdateCharacters: (chars: Character[]) => void;
  onUpdateScenes: (scenes: Scene[]) => void;
  onUpdateMaps: (maps: WorldMap[]) => void;
  onUpdateBattles: (battles: Battle[]) => void;

  onPlay: () => void;
  onQuickSave: () => Promise<boolean>;
  onExportProject: () => void;
  onImportProject: (file: File) => void;

  hasSaveGame: boolean;
  onContinueGame: () => void;
}

export const Editor: React.FC<EditorProps> = ({
  worldInfo, chapters, characters, scenes, maps, battles,
  onUpdateWorldInfo, onUpdateChapters, onUpdateCharacters,
  onUpdateScenes, onUpdateMaps, onUpdateBattles,
  onPlay, onQuickSave, onExportProject, onImportProject,
  hasSaveGame, onContinueGame
}) => {
  const [activeTab, setActiveTab] = useState<'world' | 'chapters' | 'characters' | 'scenes' | 'maps' | 'battles'>('scenes');

  const [selectedCharId, setSelectedCharId] = useState<string | null>(null);
  const [selectedSceneId, setSelectedSceneId] = useState<string | null>(null);
  const [selectedMapId, setSelectedMapId] = useState<string | null>(null);
  const [selectedBattleId, setSelectedBattleId] = useState<string | null>(null);

  // --- CRUD HELPERS ---

  const addItem = <T extends { id: string }>(list: T[], newItem: T, updateFn: (l: T[]) => void) => {
      updateFn([...list, newItem]);
  };

  const updateItem = <T extends { id: string }>(list: T[], id: string, updates: Partial<T>, updateFn: (l: T[]) => void) => {
      updateFn(list.map(item => item.id === id ? { ...item, ...updates } : item));
  };

  const deleteItem = <T extends { id: string }>(list: T[], id: string, updateFn: (l: T[]) => void) => {
      if (window.confirm("Are you sure?")) updateFn(list.filter(item => item.id !== id));
  };

  // --- SCENE EFFECT LOGIC ---
  const toggleEffect = (sceneId: string, type: 'scene' | 'transition' | 'battle', targetId: string, action: 'unlock' | 'lock') => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const effects = scene.effects ? [...scene.effects] : [];
    const index = effects.findIndex(e => e.type === type && e.targetId === targetId);

    if (index >= 0) {
        if (effects[index].action === action) {
            // Toggle off if clicking same action
            effects.splice(index, 1);
        } else {
            // Switch action
            effects[index] = { ...effects[index], action };
        }
    } else {
        // Add new
        effects.push({ type, targetId, action });
    }

    updateItem(scenes, sceneId, { effects }, onUpdateScenes);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-900 text-white">
      {/* Header */}
      <header className="flex items-center justify-between p-4 bg-gray-800 border-b border-gray-700">
         <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-cyan-400">VN/RPG Creator</h1>
         <div className="flex items-center gap-2">
            <input 
              type="file" 
              id="import-file" 
              className="hidden" 
              accept=".json" 
              onChange={(e) => { if(e.target.files?.[0]) onImportProject(e.target.files[0]); }}
            />
            <Button variant="secondary" onClick={() => document.getElementById('import-file')?.click()}><Upload size={16}/> Import</Button>
            <Button variant="secondary" onClick={onExportProject}><Download size={16}/> Export</Button>
            <Button variant="secondary" onClick={onQuickSave}><Save size={16}/> Quick Save</Button>
            <div className="h-6 w-px bg-gray-700 mx-2"></div>
            {hasSaveGame && <Button variant="secondary" onClick={onContinueGame} className="text-emerald-400 border-emerald-900 bg-emerald-900/20">Resume Game</Button>}
            <Button variant="primary" onClick={onPlay}><Play size={16}/> Play New</Button>
         </div>
      </header>

      <div className="flex flex-1 overflow-hidden">
        {/* Sidebar */}
        <aside className="w-64 bg-gray-800 flex flex-col border-r border-gray-700">
           <nav className="flex-1 p-2 space-y-1">
              <NavButton active={activeTab === 'world'} onClick={() => setActiveTab('world')} icon={<Globe size={18}/>} label="World Info" />
              <NavButton active={activeTab === 'chapters'} onClick={() => setActiveTab('chapters')} icon={<BookOpen size={18}/>} label="Chapters" />
              <NavButton active={activeTab === 'characters'} onClick={() => setActiveTab('characters')} icon={<Users size={18}/>} label="Characters" />
              <NavButton active={activeTab === 'scenes'} onClick={() => setActiveTab('scenes')} icon={<MessageSquare size={18}/>} label="Scenes" />
              <NavButton active={activeTab === 'maps'} onClick={() => setActiveTab('maps')} icon={<MapIcon size={18}/>} label="Maps" />
              <NavButton active={activeTab === 'battles'} onClick={() => setActiveTab('battles')} icon={<Sword size={18}/>} label="Battles" />
           </nav>
        </aside>

        {/* Main Content Area */}
        <main className="flex-1 overflow-y-auto p-6 bg-gray-900">
           {activeTab === 'world' && (
               <div className="max-w-4xl mx-auto space-y-6">
                   <h2 className="text-2xl font-bold text-gray-200">World Configuration</h2>
                   <div>
                       <label className="block text-sm font-bold text-gray-400 mb-2">Global Description</label>
                       <textarea 
                          className="w-full bg-gray-800 border border-gray-700 rounded p-3 text-sm min-h-[150px]"
                          value={worldInfo.description}
