                      <div key={ch.id} className="bg-gray-800 p-4 rounded border border-gray-700">
                          <div className="flex gap-2 mb-2">
                              <input className="bg-transparent font-bold flex-1 border-b border-gray-600 focus:border-indigo-500 outline-none" value={ch.name} onChange={(e) => updateItem(chapters, ch.id, { name: e.target.value }, onUpdateChapters)} />
