                          </div>
                          <textarea className="w-full bg-black/20 text-xs p-2 rounded" placeholder="Chapter Context for AI..." value={ch.description} onChange={(e) => updateItem(chapters, ch.id, { description: e.target.value }, onUpdateChapters)} />
