                       }}><Plus size={16}/> New Character</Button>
                       <div className="space-y-2">
                           {characters.map(c => (
                               <div key={c.id} onClick={() => setSelectedCharId(c.id)} className={`p-3 rounded cursor-pointer border ${selectedCharId === c.id ? 'bg-indigo-900/50 border-indigo-500' : 'bg-gray-800 border-gray-700 hover:bg-gray-750'}`}>
                                   <div className="font-bold">{c.name}</div>
                               </div>
                           ))}
                       </div>
                   </div>
                   <div className="flex-1 overflow-y-auto">
                       {selectedCharId && (
                           <CharacterEditor 
                             character={characters.find(c => c.id === selectedCharId)!} 
                             onChange={(u) => updateItem(characters, selectedCharId, u, onUpdateCharacters)}
                             onDelete={() => { deleteItem(characters, selectedCharId, onUpdateCharacters); setSelectedCharId(null); }}
                           />
                       )}
                   </div>
               </div>
           )}

           {activeTab === 'scenes' && (
               <div className="flex h-full gap-4">
                   <div className="w-1/3 border-r border-gray-700 pr-4 overflow-y-auto">
                       <Button className="w-full mb-4" onClick={() => {
                           const newId = crypto.randomUUID();
                           addItem(scenes, { 
                               id: newId, name: 'New Scene', description: '', characters: [], goal: '',
                               backgroundSrc: null, isRepeatable: false, effects: []
                           }, onUpdateScenes);
                           setSelectedSceneId(newId);
                       }}><Plus size={16}/> New Scene</Button>
                       <div className="space-y-2">
                           {scenes.map(s => (
                               <div key={s.id} onClick={() => setSelectedSceneId(s.id)} className={`p-3 rounded cursor-pointer border ${selectedSceneId === s.id ? 'bg-indigo-900/50 border-indigo-500' : 'bg-gray-800 border-gray-700 hover:bg-gray-750'}`}>
                                   <div className="font-bold truncate">{s.name}</div>
                                   <div className="text-xs text-gray-400 truncate">{s.goal || 'No goal'}</div>
                               </div>
                           ))}
                       </div>
                   </div>
                   <div className="flex-1 overflow-y-auto">
                       {selectedSceneId && (
                           <SceneEditor 
                             scene={scenes.find(s => s.id === selectedSceneId)!} 
                             allScenes={scenes}
                             allBattles={battles}
                             allMaps={maps}
                             characters={characters}
                             chapters={chapters}
                             onChange={(u) => updateItem(scenes, selectedSceneId, u, onUpdateScenes)}
                             onDelete={() => { deleteItem(scenes, selectedSceneId, onUpdateScenes); setSelectedSceneId(null); }}
                             toggleEffect={toggleEffect}
                           />
