                           addItem(maps, { id: newId, name: 'New Map', spots: [], backgroundSrc: null }, onUpdateMaps);
                           setSelectedMapId(newId);
                        }}><Plus size={16}/> New Map</Button>
                        <div className="space-y-2">
                            {maps.map(m => (
                                <div key={m.id} onClick={() => setSelectedMapId(m.id)} className={`p-3 rounded cursor-pointer border ${selectedMapId === m.id ? 'bg-indigo-900/50 border-indigo-500' : 'bg-gray-800 border-gray-700'}`}>
                                    {m.name}
                                </div>
                            ))}
                        </div>
                    </div>
                    <div className="flex-1">
                        {selectedMapId && (
                            <MapEditor 
                                map={maps.find(m => m.id === selectedMapId)!}
                                scenes={scenes}
                                characters={characters}
                                battles={battles}
                                allMaps={maps}
                                onChange={(u) => updateItem(maps, selectedMapId, u, onUpdateMaps)}
                                onDelete={() => { deleteItem(maps, selectedMapId, onUpdateMaps); setSelectedMapId(null); }}
                            />
                        )}
                    </div>
               </div>
           )}

           {activeTab === 'battles' && (
               <div className="flex h-full gap-4">
                   <div className="w-1/3 border-r border-gray-700 pr-4">
                        <Button className="w-full mb-4" onClick={() => {
                           const newId = crypto.randomUUID();
                           addItem(battles, { id: newId, name: 'New Battle', playerCharacterIds: [], enemyCharacterIds: [], isRepeatable: false, backgroundSrc: null }, onUpdateBattles);
                           setSelectedBattleId(newId);
                        }}><Plus size={16}/> New Battle</Button>
                        <div className="space-y-2">
                            {battles.map(b => (
                                <div key={b.id} onClick={() => setSelectedBattleId(b.id)} className={`p-3 rounded cursor-pointer border ${selectedBattleId === b.id ? 'bg-indigo-900/50 border-indigo-500' : 'bg-gray-800 border-gray-700'}`}>
                                    {b.name}
                                </div>
                            ))}
                        </div>
                   </div>
                   <div className="flex-1">
                       {selectedBattleId && (
                           <BattleEditor 
                               battle={battles.find(b => b.id === selectedBattleId)!}
                               characters={characters}
                               chapters={chapters}
