const SceneEditor = ({ scene, allScenes, allBattles, allMaps, characters, chapters, onChange, onDelete, toggleEffect }: any) => {
    return (
        <div className="space-y-6 max-w-3xl">
            <div className="flex justify-between items-center">
                <h3 className="text-xl font-bold text-indigo-400">Editing: {scene.name}</h3>
                <div className="flex gap-2">
                    <label className="flex items-center gap-2 text-xs bg-gray-800 px-3 py-1 rounded border border-gray-700">
                        <input type="checkbox" checked={scene.isRepeatable} onChange={e => onChange({ isRepeatable: e.target.checked })} />
                        Repeatable
                    </label>
                    <button onClick={onDelete} className="text-red-500 hover:bg-red-900/20 p-2 rounded"><Trash size={18}/></button>
                </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="text-xs font-bold text-gray-500 uppercase">Scene Name</label>
                    <input className="w-full bg-gray-800 border border-gray-700 rounded p-2" value={scene.name} onChange={e => onChange({ name: e.target.value })} />
                 </div>
                 <div>
                    <label className="text-xs font-bold text-gray-500 uppercase">Chapter</label>
                    <select className="w-full bg-gray-800 border border-gray-700 rounded p-2" value={scene.chapterId || ''} onChange={e => onChange({ chapterId: e.target.value })}>
                        {chapters.map((c: Chapter) => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                 </div>
            </div>

            <div>
                <label className="text-xs font-bold text-gray-500 uppercase">Visible Description (Player)</label>
                <textarea className="w-full bg-gray-800 border border-gray-700 rounded p-2 h-20" value={scene.description} onChange={e => onChange({ description: e.target.value })} />
            </div>

            <div>
                <label className="text-xs font-bold text-gray-500 uppercase">Win Condition / Goal</label>
                <input className="w-full bg-gray-800 border border-gray-700 rounded p-2 text-emerald-400 font-medium" placeholder="e.g. Find the key, Convince the guard..." value={scene.goal} onChange={e => onChange({ goal: e.target.value })} />
            </div>

            {/* Characters in Scene */}
            <div className="bg-gray-800 p-4 rounded-xl border border-gray-700">
                <label className="flex items-center gap-2 text-sm font-bold text-indigo-400 mb-4"><Users size={18} /> CHARACTERS & ROLES</label>
                <div className="space-y-2">
                    {characters.map((c: Character) => {
                        const inScene = scene.characters.find((sc: any) => sc.characterId === c.id);
                        return (
                            <div key={c.id} className={`flex items-center gap-3 p-2 rounded border ${inScene ? 'bg-indigo-900/30 border-indigo-500' : 'bg-gray-900 border-gray-700 opacity-60'}`}>
                                <input 
                                    type="checkbox" 
                                    checked={!!inScene} 
                                    onChange={(e) => {
                                        if (e.target.checked) {
                                            onChange({ characters: [...scene.characters, { characterId: c.id, roleInScene: 'Default' }] });
                                        } else {
                                            onChange({ characters: scene.characters.filter((sc: any) => sc.characterId !== c.id) });
                                        }
                                    }}
                                />
                                <div className="w-24 font-bold truncate">{c.name}</div>
                                <input 
                                    className="flex-1 bg-transparent border-b border-gray-600 text-xs focus:border-indigo-500 outline-none" 
                                    placeholder="Role in this scene..."
                                    disabled={!inScene}
                                    value={inScene?.roleInScene || ''}
                                    onChange={(e) => {
                                        const newChars = scene.characters.map((sc: any) => sc.characterId === c.id ? { ...sc, roleInScene: e.target.value } : sc);
                                        onChange({ characters: newChars });
                                    }}
                                />
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* Unlocks / Locks */}
            <div className="bg-gray-800 p-4 rounded-xl border border-gray-700">
                <label className="flex items-center gap-2 text-sm font-bold text-yellow-500 mb-4"><Unlock size={18} /> SCENE COMPLETION EFFECTS</label>
                <p className="text-xs text-gray-400 mb-4">When this scene is completed (Win Condition met), what happens to other locations?</p>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 max-h-60 overflow-y-auto custom-scrollbar p-1">
                    {/* Scenes List */}
                    <div className="space-y-2">
                        <div className="text-xs font-bold text-gray-500 uppercase sticky top-0 bg-gray-800 py-1 z-10">Other Scenes</div>
                        {allScenes.filter((s: Scene) => s.id !== scene.id).map((otherScene: Scene) => {
                            const effect = scene.effects?.find((u: SceneEffect) => u.type === 'scene' && u.targetId === otherScene.id);
                            const status = effect?.action || 'neutral';

                            return (
                                <div key={otherScene.id} className="flex items-center justify-between bg-gray-900 p-2 rounded border border-gray-700">
                                    <div className="flex items-center gap-2 truncate flex-1">
                                        <MessageSquare size={14} className="text-gray-500"/>
                                        <span className="text-xs text-gray-300 truncate" title={otherScene.name}>{otherScene.name}</span>
                                    </div>
                                    <div className="flex gap-1 ml-2">
                                        <button onClick={() => toggleEffect(scene.id, 'scene', otherScene.id, 'unlock')} className={`p-1 rounded ${status === 'unlock' ? 'bg-emerald-600 text-white' : 'bg-gray-800 text-gray-500 hover:bg-gray-700'}`} title="Unlock"><Unlock size={12}/></button>
                                        <button onClick={() => toggleEffect(scene.id, 'scene', otherScene.id, 'lock')} className={`p-1 rounded ${status === 'lock' ? 'bg-red-600 text-white' : 'bg-gray-800 text-gray-500 hover:bg-gray-700'}`} title="Lock"><Lock size={12}/></button>
                                    </div>
                                </div>
                            );
                        })}
                    </div>

                    {/* Battles List */}
                    <div className="space-y-2">
                        <div className="text-xs font-bold text-gray-500 uppercase sticky top-0 bg-gray-800 py-1 z-10">Battles</div>
                        {allBattles.map((b: Battle) => {
                            const effect = scene.effects?.find((u: SceneEffect) => u.type === 'battle' && u.targetId === b.id);
                            const status = effect?.action || 'neutral';

                            return (
                                <div key={b.id} className="flex items-center justify-between bg-gray-900 p-2 rounded border border-gray-700">
                                    <div className="flex items-center gap-2 truncate flex-1">
                                        <Sword size={14} className="text-red-500"/>
                                        <span className="text-xs text-gray-300 truncate" title={b.name}>{b.name}</span>
                                    </div>
                                    <div className="flex gap-1 ml-2">
                                        <button onClick={() => toggleEffect(scene.id, 'battle', b.id, 'unlock')} className={`p-1 rounded ${status === 'unlock' ? 'bg-emerald-600 text-white' : 'bg-gray-800 text-gray-500 hover:bg-gray-700'}`} title="Unlock"><Unlock size={12}/></button>
                                        <button onClick={() => toggleEffect(scene.id, 'battle', b.id, 'lock')} className={`p-1 rounded ${status === 'lock' ? 'bg-red-600 text-white' : 'bg-gray-800 text-gray-500 hover:bg-gray-700'}`} title="Lock"><Lock size={12}/></button>
                                    </div>
                                </div>
                            );
                        })}
                    </div>

                    {/* Transitions List */}
                    <div className="space-y-2">
                        <div className="text-xs font-bold text-gray-500 uppercase sticky top-0 bg-gray-800 py-1 z-10">Map Transitions</div>
                        {allMaps.map((m: WorldMap) => {
                            const effect = scene.effects?.find((u: SceneEffect) => u.type === 'transition' && u.targetId === m.id);
                            const status = effect?.action || 'neutral';

                            return (
                                <div key={m.id} className="flex items-center justify-between bg-gray-900 p-2 rounded border border-gray-700">
                                    <div className="flex items-center gap-2 truncate flex-1">
                                        <Waypoints size={14} className="text-emerald-500"/>
                                        <span className="text-xs text-gray-300 truncate" title={m.name}>To: {m.name}</span>
                                    </div>
                                    <div className="flex gap-1 ml-2">
                                        <button onClick={() => toggleEffect(scene.id, 'transition', m.id, 'unlock')} className={`p-1 rounded ${status === 'unlock' ? 'bg-emerald-600 text-white' : 'bg-gray-800 text-gray-500 hover:bg-gray-700'}`} title="Unlock"><Unlock size={12}/></button>
                                        <button onClick={() => toggleEffect(scene.id, 'transition', m.id, 'lock')} className={`p-1 rounded ${status === 'lock' ? 'bg-red-600 text-white' : 'bg-gray-800 text-gray-500 hover:bg-gray-700'}`} title="Lock"><Lock size={12}/></button>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>
        </div>
    );
};

const MapEditor = ({ map, scenes, characters, battles, allMaps, onChange, onDelete }: any) => {
    // Simple Spot Editor Logic
    const addSpot = (x: number, y: number) => {
        const newSpot: MapSpot = { id: crypto.randomUUID(), x, y, type: 'scene', sceneId: scenes[0]?.id };
        onChange({ spots: [...map.spots, newSpot] });
    };

    const updateSpot = (id: string, updates: Partial<MapSpot>) => {
        onChange({ spots: map.spots.map((s: MapSpot) => s.id === id ? { ...s, ...updates } : s) });
    };

    const deleteSpot = (id: string) => {
        onChange({ spots: map.spots.filter((s: MapSpot) => s.id !== id) });
    };

    return (
        <div className="flex flex-col h-full">
            <div className="flex justify-between items-center mb-4">
                <input className="bg-transparent text-xl font-bold border-b border-gray-600 focus:border-indigo-500 outline-none" value={map.name} onChange={e => onChange({ name: e.target.value })} />
                <div className="flex gap-2">
                     <div className="flex items-center gap-2 text-xs text-gray-400">
                         <ImageIcon size={14}/>
                         <input className="bg-gray-800 border border-gray-700 rounded p-1 w-48" placeholder="Map Background URL..." value={map.backgroundSrc || ''} onChange={e => onChange({ backgroundSrc: e.target.value })} />
                     </div>
                     <button onClick={onDelete} className="text-red-500"><Trash size={18}/></button>
                </div>
            </div>

            <div className="flex-1 bg-gray-900 border border-gray-700 relative overflow-hidden rounded group">
                 {/* Map Preview Area */}
                 {map.backgroundSrc && <img src={map.backgroundSrc} className="absolute inset-0 w-full h-full object-cover opacity-50 pointer-events-none" />}

                 {/* Click to add spot */}
                 <div 
                    className="absolute inset-0 cursor-crosshair z-0" 
                    onClick={(e) => {
                        const rect = e.currentTarget.getBoundingClientRect();
                        const x = ((e.clientX - rect.left) / rect.width) * 100;
                        const y = ((e.clientY - rect.top) / rect.height) * 100;
                        addSpot(x, y);
                    }}
                 />

                 {/* Render Spots */}
                 {map.spots.map((spot: MapSpot) => (
                     <div 
                        key={spot.id} 
                        className="absolute w-6 h-6 -ml-3 -mt-3 bg-indigo-500 rounded-full border-2 border-white shadow-lg flex items-center justify-center cursor-pointer hover:scale-125 transition-transform z-10 group-hover:z-20"
                        style={{ left: `${spot.x}%`, top: `${spot.y}%` }}
                        onClick={(e) => { e.stopPropagation(); /* select spot? */ }}
                     >
                         <div className="relative group-hover:block hidden bg-black/90 text-white text-xs p-2 rounded absolute bottom-8 min-w-[200px] z-50 pointer-events-auto">
                             <div className="flex justify-between mb-2 border-b border-gray-700 pb-1">
                                 <span className="font-bold uppercase">{spot.type}</span>
