                                     <option value="">Select Battle...</option>
                                     {battles.map((b: Battle) => <option key={b.id} value={b.id}>{b.name}</option>)}
                                 </select>
                             )}
                             {spot.type === 'transition' && (
                                 <select className="w-full bg-gray-800 rounded" value={spot.targetMapId || ''} onChange={e => updateSpot(spot.id, { targetMapId: e.target.value })}>
