            <div className="mb-4">
                 <ImageField label="Map Background" value={map.backgroundSrc} onChange={val => onChange({ backgroundSrc: val })} />
            </div>

            <div className="flex-1 bg-gray-900 border border-gray-700 relative overflow-hidden rounded group">
                 {/* Map Preview Area */}
                 {map.backgroundSrc && <img src={map.backgroundSrc} className="absolute inset-0 w-full h-full object-cover opacity-50 pointer-events-none" />}

                 {/* Click to add spot */}
                 <div 
                    className="absolute inset-0 cursor-crosshair z-0" 
                    onClick={(e) => {
                        const rect = e.currentTarget.getBoundingClientRect();
                        const x = ((e.clientX - rect.left) / rect.width) * 100;
                        const y = ((e.clientY - rect.top) / rect.height) * 100;
                        addSpot(x, y);
                    }}
                 />

                 {/* Render Spots */}
                 {map.spots.map((spot: MapSpot) => (
                     <div 
                        key={spot.id} 
                        className="absolute w-6 h-6 -ml-3 -mt-3 bg-indigo-500 rounded-full border-2 border-white shadow-lg flex items-center justify-center cursor-pointer hover:scale-125 transition-transform z-10 group-hover:z-20"
