// Helper Component to handle Image Inputs without lagging the browser with massive Base64 strings in input values
const ImageField = ({ label, value, onChange }: { label: string, value: string | null, onChange: (val: string | null) => void }) => {
    const handleFile = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const reader = new FileReader();
            reader.onloadend = () => onChange(reader.result as string);
            reader.readAsDataURL(e.target.files[0]);
        }
    };

    const isDataUrl = value?.startsWith('data:');

    return (
        <div>
            <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">{label}</label>
            <div className="flex gap-2 items-center">
                <div className="relative flex-1">
                    <input 
                        className="w-full bg-gray-800 border border-gray-700 rounded p-2 text-xs text-gray-300 focus:border-indigo-500 outline-none" 
                        placeholder={isDataUrl ? "Image stored (Base64)" : "No image set"}
                        value={isDataUrl ? "" : value || ""} 
                        onChange={(e) => onChange(e.target.value)}
                        disabled={!!isDataUrl} // Disable typing if we have a base64 string to prevent lag
                    />
                    {isDataUrl && <div className="absolute inset-0 flex items-center pl-2 text-xs text-indigo-400 font-medium pointer-events-none bg-gray-800/90 rounded">Embedded Image Data</div>}
                </div>

                <label className="cursor-pointer bg-gray-700 hover:bg-gray-600 px-3 py-2 rounded text-white transition-colors" title="Upload Image">
                    <ImageIcon size={14} />
                    <input type="file" accept="image/*" className="hidden" onChange={handleFile} />
                </label>

                {value && (
                    <button onClick={() => onChange(null)} className="text-gray-500 hover:text-red-500 transition-colors" title="Clear Image">
                        <XCircle size={18}/>
                    </button>
                )}
            </div>
            {/* Preview */}
            {value && (
                <div className="mt-2 h-20 w-full bg-gray-950 rounded border border-gray-800 flex items-center justify-center overflow-hidden relative">
                    <img src={value} className="h-full w-full object-contain" alt="Preview"/>
                </div>
            )}
        </div>
    );
};

export const Editor: React.FC<EditorProps> = ({
  worldInfo, chapters, characters, scenes, maps, battles,
  onUpdateWorldInfo, onUpdateChapters, onUpdateCharacters,
  onUpdateScenes, onUpdateMaps, onUpdateBattles,
  onPlay, onQuickSave, onExportProject, onImportProject,
  hasSaveGame, onContinueGame
}) => {
  const [activeTab, setActiveTab] = useState<'world' | 'chapters' | 'characters' | 'scenes' | 'maps' | 'battles'>('scenes');

  const [selectedCharId, setSelectedCharId] = useState<string | null>(null);
  const [selectedSceneId, setSelectedSceneId] = useState<string | null>(null);
  const [selectedMapId, setSelectedMapId] = useState<string | null>(null);
  const [selectedBattleId, setSelectedBattleId] = useState<string | null>(null);

  // --- CRUD HELPERS ---

  const addItem = <T extends { id: string }>(list: T[], newItem: T, updateFn: (l: T[]) => void) => {
      updateFn([...list, newItem]);
  };

  const updateItem = <T extends { id: string }>(list: T[], id: string, updates: Partial<T>, updateFn: (l: T[]) => void) => {
      updateFn(list.map(item => item.id === id ? { ...item, ...updates } : item));
  };

  const deleteItem = <T extends { id: string }>(list: T[], id: string, updateFn: (l: T[]) => void) => {
      if (window.confirm("Are you sure?")) updateFn(list.filter(item => item.id !== id));
  };

  // --- SCENE EFFECT LOGIC ---
  const toggleEffect = (sceneId: string, type: 'scene' | 'transition' | 'battle', targetId: string, action: 'unlock' | 'lock') => {
    const scene = scenes.find(s => s.id === sceneId);
    if (!scene) return;

    const effects = scene.effects ? [...scene.effects] : [];
    const index = effects.findIndex(e => e.type === type && e.targetId === targetId);

    if (index >= 0) {
        if (effects[index].action === action) {
            // Toggle off if clicking same action
            effects.splice(index, 1);
        } else {
            // Switch action
            effects[index] = { ...effects[index], action };
        }
    } else {
        // Add new
        effects.push({ type, targetId, action });
    }

    updateItem<Scene>(scenes, sceneId, { effects }, onUpdateScenes);
  };

  return (
