            <div className="h-6 w-px bg-gray-700 mx-2"></div>
            {hasSaveGame && <Button variant="secondary" onClick={onContinueGame} className="text-emerald-400 border-emerald-900 bg-emerald-900/20">Resume Game</Button>}
            <Button variant="primary" onClick={onPlay}><Play size={16}/> Play New</Button>
         </div>
      </header>

      <div className="flex flex-1 overflow-hidden">
        {/* Sidebar */}
        <aside className="w-64 bg-gray-800 flex flex-col border-r border-gray-700">
           <nav className="flex-1 p-2 space-y-1">
              <NavButton active={activeTab === 'world'} onClick={() => setActiveTab('world')} icon={<Globe size={18}/>} label="World Info" />
              <NavButton active={activeTab === 'chapters'} onClick={() => setActiveTab('chapters')} icon={<BookOpen size={18}/>} label="Chapters" />
              <NavButton active={activeTab === 'characters'} onClick={() => setActiveTab('characters')} icon={<Users size={18}/>} label="Characters" />
