                             onChange={(u) => updateItem(characters, selectedCharId, u, onUpdateCharacters)}
                             onDelete={() => { deleteItem(characters, selectedCharId, onUpdateCharacters); setSelectedCharId(null); }}
                           />
                       )}
                   </div>
               </div>
           )}

           {activeTab === 'scenes' && (
               <div className="flex h-full gap-4">
                   <div className="w-1/3 border-r border-gray-700 pr-4 overflow-y-auto">
                       <Button className="w-full mb-4" onClick={() => {
                           const newId = crypto.randomUUID();
                           addItem(scenes, { 
                               id: newId, name: 'New Scene', description: '', characters: [], goal: '',
                               backgroundSrc: null, isRepeatable: false, effects: []
                           }, onUpdateScenes);
                           setSelectedSceneId(newId);
                       }}><Plus size={16}/> New Scene</Button>
                       <div className="space-y-2">
                           {scenes.map(s => (
                               <div key={s.id} onClick={() => setSelectedSceneId(s.id)} className={`p-3 rounded cursor-pointer border ${selectedSceneId === s.id ? 'bg-indigo-900/50 border-indigo-500' : 'bg-gray-800 border-gray-700 hover:bg-gray-750'}`}>
