const ImageField = ({ label, value, onChange }: { label: string, value: string | null, onChange: (val: string | null) => void }) => {
    const handleFile = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (ev) => onChange(ev.target?.result as string);
            reader.readAsDataURL(file);
        }
    };
    return (
        <div>
            <label className="text-xs font-bold text-gray-500 uppercase">{label}</label>
            <div className="flex gap-2 items-center mt-1">
                {value ? (
                    <div className="relative group">
                        <img src={value} className="w-10 h-10 object-cover rounded bg-gray-700" />
                        <button onClick={() => onChange(null)} className="absolute -top-2 -right-2 bg-red-500 rounded-full p-0.5 text-white opacity-0 group-hover:opacity-100 transition-opacity"><Trash size={10}/></button>
                    </div>
                ) : <div className="w-10 h-10 bg-gray-800 rounded"></div>}
                <input type="file" onChange={handleFile} className="text-xs text-gray-400 file:mr-2 file:py-1 file:px-2 file:rounded file:border-0 file:text-xs file:bg-gray-700 file:text-white hover:file:bg-gray-600"/>
            </div>
        </div>
    );
};

