                                <input type="number" placeholder="DMG" title="Damage" className="bg-gray-900 border border-gray-600 rounded p-1 text-white" value={character.stats.weapon.dmg} onChange={e => onChange({ stats: { ...character.stats!, weapon: { ...character.stats!.weapon, dmg: parseInt(e.target.value) } } })} />
                             </div>
                        </div>
                        <Button variant="danger" className="w-full mt-2 text-xs" onClick={() => onChange({ stats: undefined })}>Disable Combat</Button>
                    </div>
                )}
            </div>
        </div>
    );
};

interface EditorProps {
  worldInfo: WorldInfo;
  chapters: Chapter[];
  characters: Character[];
  scenes: Scene[];
  maps: WorldMap[];
  battles: Battle[];
  onUpdateWorldInfo: (w: WorldInfo) => void;
  onUpdateChapters: (c: Chapter[]) => void;
  onUpdateCharacters: (c: Character[]) => void;
  onUpdateScenes: (s: Scene[]) => void;
  onUpdateMaps: (m: WorldMap[]) => void;
  onUpdateBattles: (b: Battle[]) => void;
  onPlay: () => void;
  onQuickSave: () => Promise<boolean>;
  onExportProject: () => void;
  onImportProject: (file: File) => void;
  hasSaveGame: boolean;
  onContinueGame: () => void;
}

export const Editor: React.FC<EditorProps> = (props) => {
    const [tab, setTab] = useState<'world' | 'chars' | 'scenes' | 'maps' | 'battles'>('chars');

    const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files?.[0]) props.onImportProject(e.target.files[0]);
    };

    return (
        <div className="flex h-screen overflow-hidden">
            {/* Sidebar */}
            <div className="w-64 bg-gray-900 border-r border-gray-800 flex flex-col">
                <div className="p-4 border-b border-gray-800">
                    <h1 className="text-xl font-bold text-indigo-500 flex items-center gap-2"><Layout size={20}/> VN Creator</h1>
                </div>
                <div className="flex-1 overflow-y-auto py-4 space-y-1">
                    <button onClick={() => setTab('world')} className={`w-full text-left px-6 py-3 flex items-center gap-3 ${tab === 'world' ? 'bg-indigo-900/30 text-indigo-400 border-r-2 border-indigo-500' : 'text-gray-400 hover:bg-gray-800'}`}><Book size={18}/> World & Lore</button>
                    <button onClick={() => setTab('chars')} className={`w-full text-left px-6 py-3 flex items-center gap-3 ${tab === 'chars' ? 'bg-indigo-900/30 text-indigo-400 border-r-2 border-indigo-500' : 'text-gray-400 hover:bg-gray-800'}`}><Users size={18}/> Characters</button>
                    <button onClick={() => setTab('scenes')} className={`w-full text-left px-6 py-3 flex items-center gap-3 ${tab === 'scenes' ? 'bg-indigo-900/30 text-indigo-400 border-r-2 border-indigo-500' : 'text-gray-400 hover:bg-gray-800'}`}><Monitor size={18}/> Scenes</button>
                    <button onClick={() => setTab('maps')} className={`w-full text-left px-6 py-3 flex items-center gap-3 ${tab === 'maps' ? 'bg-indigo-900/30 text-indigo-400 border-r-2 border-indigo-500' : 'text-gray-400 hover:bg-gray-800'}`}><MapIcon size={18}/> Maps</button>
                    <button onClick={() => setTab('battles')} className={`w-full text-left px-6 py-3 flex items-center gap-3 ${tab === 'battles' ? 'bg-indigo-900/30 text-indigo-400 border-r-2 border-indigo-500' : 'text-gray-400 hover:bg-gray-800'}`}><Target size={18}/> Battles</button>
                </div>
                <div className="p-4 border-t border-gray-800 space-y-2">
                    <Button onClick={props.onPlay} className="w-full justify-center bg-green-600 hover:bg-green-500"><Play size={16}/> New Game</Button>
                    {props.hasSaveGame && <Button onClick={props.onContinueGame} variant="secondary" className="w-full justify-center"><Play size={16}/> Continue</Button>}
                    <div className="grid grid-cols-3 gap-2 mt-2">
                        <Button variant="secondary" onClick={props.onQuickSave} title="Quick Save"><Save size={16}/></Button>
                        <Button variant="secondary" onClick={props.onExportProject} title="Export JSON"><Download size={16}/></Button>
                        <div className="relative">
                            <Button variant="secondary" className="w-full" title="Import JSON"><Upload size={16}/></Button>
                            <input type="file" onChange={handleImport} className="absolute inset-0 opacity-0 cursor-pointer" accept=".json"/>
                        </div>
                    </div>
                </div>
            </div>

            {/* Main Content */}
            <div className="flex-1 bg-gray-950 overflow-y-auto p-8">
                {tab === 'world' && (
                    <div className="max-w-2xl space-y-6">
                        <h2 className="text-2xl font-bold text-white mb-6">World Settings</h2>
                        <div>
                            <label className="text-xs font-bold text-gray-500 uppercase">World Description</label>
                            <textarea className="w-full bg-gray-900 border border-gray-700 rounded p-2 h-32 text-white" value={props.worldInfo.description} onChange={e => props.onUpdateWorldInfo({ ...props.worldInfo, description: e.target.value })} />
                        </div>
                    </div>
                )}

                {tab === 'chars' && (
                    <div className="space-y-6">
                        <div className="flex justify-between items-center">
                             <h2 className="text-2xl font-bold text-white">Characters</h2>
                             <Button onClick={() => props.onUpdateCharacters([...props.characters, { id: crypto.randomUUID(), name: 'New Character', defaultDescription: '', rpgColor: '#ffffff' }])}><Plus size={16}/> Add Character</Button>
                        </div>
                        <div className="grid xl:grid-cols-2 gap-6">
                            {props.characters.map(c => (
                                <CharacterEditor 
                                    key={c.id} 
                                    character={c} 
                                    onChange={(u) => props.onUpdateCharacters(props.characters.map(x => x.id === c.id ? { ...x, ...u } : x))}
                                    onDelete={() => props.onUpdateCharacters(props.characters.filter(x => x.id !== c.id))}
                                />
                            ))}
                        </div>
                    </div>
                )}

                {tab === 'scenes' && (
                    <div className="space-y-6">
                         <div className="flex justify-between items-center">
                             <h2 className="text-2xl font-bold text-white">Scenes</h2>
                             <Button onClick={() => props.onUpdateScenes([...props.scenes, { id: crypto.randomUUID(), name: 'New Scene', description: '', goal: '', characters: [] }]) as any}><Plus size={16}/> Add Scene</Button>
                        </div>
                         <div className="grid gap-4">
                            {props.scenes.map(s => (
                                <div key={s.id} className="bg-gray-900/50 p-4 rounded border border-gray-800">
                                     <div className="flex justify-between items-center mb-2">
                                        <input className="bg-transparent font-bold text-white text-lg" value={s.name} onChange={e => props.onUpdateScenes(props.scenes.map(x => x.id === s.id ? { ...x, name: e.target.value } : x))} />
                                        <button onClick={() => props.onUpdateScenes(props.scenes.filter(x => x.id !== s.id))} className="text-red-500"><Trash size={16}/></button>
                                     </div>
                                     <textarea className="w-full bg-gray-800 border border-gray-700 rounded p-2 text-sm text-gray-300 h-20" value={s.description} onChange={e => props.onUpdateScenes(props.scenes.map(x => x.id === s.id ? { ...x, description: e.target.value } : x))} />
                                </div>
                            ))}
                         </div>
                    </div>
                )}

                {tab === 'maps' && (
                     <div className="space-y-6">
                         <div className="flex justify-between items-center">
                             <h2 className="text-2xl font-bold text-white">Maps</h2>
                             <Button onClick={() => props.onUpdateMaps([...props.maps, { id: crypto.randomUUID(), name: 'New Map', backgroundSrc: null, spots: [] }])}><Plus size={16}/> Add Map</Button>
                        </div>
                        <div className="space-y-4">
                            {props.maps.map(m => (
                                <div key={m.id} className="bg-gray-900/50 p-4 rounded border border-gray-800 flex justify-between items-center">
                                    <input className="bg-transparent font-bold text-white" value={m.name} onChange={e => props.onUpdateMaps(props.maps.map(x => x.id === m.id ? { ...x, name: e.target.value } : x))} />
                                    <button onClick={() => props.onUpdateMaps(props.maps.filter(x => x.id !== m.id))} className="text-red-500"><Trash size={16}/></button>
                                </div>
                            ))}
                        </div>
                     </div>
                )}

                {tab === 'battles' && (
                     <div className="space-y-6">
                         <div className="flex justify-between items-center">
                             <h2 className="text-2xl font-bold text-white">Battles</h2>
                             <Button onClick={() => props.onUpdateBattles([...props.battles, { id: crypto.randomUUID(), name: 'New Battle', backgroundSrc: null, playerCharacterIds: [], enemyCharacterIds: [], isRepeatable: false }])}><Plus size={16}/> Add Battle</Button>
                        </div>
                        <div className="space-y-4">
                            {props.battles.map(b => (
                                <div key={b.id} className="bg-gray-900/50 p-4 rounded border border-gray-800 flex justify-between items-center">
                                    <input className="bg-transparent font-bold text-white" value={b.name} onChange={e => props.onUpdateBattles(props.battles.map(x => x.id === b.id ? { ...x, name: e.target.value } : x))} />
                                    <button onClick={() => props.onUpdateBattles(props.battles.filter(x => x.id !== b.id))} className="text-red-500"><Trash size={16}/></button>
                                </div>
                            ))}
                        </div>
                     </div>
                )}
            </div>
        </div>
    );
};

