    const { scenes } = useSceneContext();
    const { maps } = useMapContext();
    const { battles } = useBattleContext();
    const [character, setCharacter] = useState<Character | null>(null);
    const [activeTab, setActiveTab] = useState('character'); // 'scene', 'map', 'battle'

