        const updatedChar = { ...character, ...newFields };
        updateCharacter(updatedChar);
        setCharacter(updatedChar);
    };

    return (
        <div className="flex flex-col gap-4 p-4 bg-gray-900 text-white rounded-lg shadow-md w-full max-w-4xl">
