                <button
                    className={`px-4 py-2 ${activeTab === 'map' ? 'bg-blue-500' : 'bg-gray-700'}`}
                    onClick={() => setActiveTab('map')}
                >
                    Map
                </button>
                <button
                    className={`px-4 py-2 rounded-r ${activeTab === 'battle' ? 'bg-blue-500' : 'bg-gray-700'}`}
                    onClick={() => setActiveTab('battle')}
                >
                    Battle
                </button>
            </div>

            {activeTab === 'character' && (
                <>
                    <CharacterEditor character={character} onChange={onChange} />
                    <label className="text-xs font-bold text-gray-500 uppercase">Relation to Player</label>
                    <input
                        className="w-full bg-gray-800 border border-gray-700 rounded p-2 text-sm text-white"
                        placeholder="e.g. Secretly admires them, Suspicious of them..."
                        value={character.playerRelation || ''}
                        onChange={e => onChange({ playerRelation: e.target.value })}
                    />
                </>
            )}
            {activeTab === 'scene' && (
                <SceneEditor character={character} scenes={scenes} updateCharacter={updateCharacter} />
            )}
