                <MapEditor character={character} maps={maps} updateCharacter={updateCharacter} />
            )}
            {activeTab === 'battle' && (
                <BattleEditor character={character} battles={battles} updateCharacter={updateCharacter} />
            )}
        </div>
    );
};

