interface EditorProps {
  worldInfo: WorldInfo;
  chapters: Chapter[];
  characters: Character[];
  scenes: Scene[];
  maps: WorldMap[];
  battles: Battle[];
  onUpdateWorldInfo: (w: WorldInfo) => void;
  onUpdateChapters: (c: Chapter[]) => void;
  onUpdateCharacters: (c: Character[]) => void;
  onUpdateScenes: (s: Scene[]) => void;
  onUpdateMaps: (m: WorldMap[]) => void;
  onUpdateBattles: (b: Battle[]) => void;
  onPlay: () => void;
  onQuickSave: () => Promise<boolean>;
  onExportProject: () => void;
  onImportProject: (file: File) => void;
  hasSaveGame: boolean;
  onContinueGame: () => void;
}

export const Editor: React.FC<EditorProps> = (props) => {
    const [tab, setTab] = useState<'world' | 'chars' | 'scenes' | 'maps' | 'battles'>('chars');
    const [selectedId, setSelectedId] = useState<string | null>(null);

    const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files?.[0]) props.onImportProject(e.target.files[0]);
    };

    return (
        <div className="flex h-screen overflow-hidden">
            {/* Sidebar */}
            <div className="w-64 bg-gray-900 border-r border-gray-800 flex flex-col">
                <div className="p-4 border-b border-gray-800">
                    <h1 className="text-xl font-bold text-indigo-500 flex items-center gap-2"><Layout size={20}/> VN Creator</h1>
                </div>
                <div className="flex-1 overflow-y-auto py-4 space-y-1">
                    <button onClick={() => { setTab('world'); setSelectedId(null); }} className={`w-full text-left px-6 py-3 flex items-center gap-3 ${tab === 'world' ? 'bg-indigo-900/30 text-indigo-400 border-r-2 border-indigo-500' : 'text-gray-400 hover:bg-gray-800'}`}><Book size={18}/> World & Lore</button>
                    <button onClick={() => { setTab('chars'); setSelectedId(null); }} className={`w-full text-left px-6 py-3 flex items-center gap-3 ${tab === 'chars' ? 'bg-indigo-900/30 text-indigo-400 border-r-2 border-indigo-500' : 'text-gray-400 hover:bg-gray-800'}`}><Users size={18}/> Characters</button>
                    <button onClick={() => { setTab('scenes'); setSelectedId(null); }} className={`w-full text-left px-6 py-3 flex items-center gap-3 ${tab === 'scenes' ? 'bg-indigo-900/30 text-indigo-400 border-r-2 border-indigo-500' : 'text-gray-400 hover:bg-gray-800'}`}><Monitor size={18}/> Scenes</button>
                    <button onClick={() => { setTab('maps'); setSelectedId(null); }} className={`w-full text-left px-6 py-3 flex items-center gap-3 ${tab === 'maps' ? 'bg-indigo-900/30 text-indigo-400 border-r-2 border-indigo-500' : 'text-gray-400 hover:bg-gray-800'}`}><MapIcon size={18}/> Maps</button>
                    <button onClick={() => { setTab('battles'); setSelectedId(null); }} className={`w-full text-left px-6 py-3 flex items-center gap-3 ${tab === 'battles' ? 'bg-indigo-900/30 text-indigo-400 border-r-2 border-indigo-500' : 'text-gray-400 hover:bg-gray-800'}`}><Target size={18}/> Battles</button>
                </div>
                <div className="p-4 border-t border-gray-800 space-y-2">
                    <Button onClick={props.onPlay} className="w-full justify-center bg-green-600 hover:bg-green-500"><Play size={16}/> New Game</Button>
                    {props.hasSaveGame && <Button onClick={props.onContinueGame} variant="secondary" className="w-full justify-center"><Play size={16}/> Continue</Button>}
                    <div className="grid grid-cols-3 gap-2 mt-2">
                        <Button variant="secondary" onClick={props.onQuickSave} title="Quick Save"><Save size={16}/></Button>
                        <Button variant="secondary" onClick={props.onExportProject} title="Export JSON"><Download size={16}/></Button>
                        <div className="relative">
                            <Button variant="secondary" className="w-full" title="Import JSON"><Upload size={16}/></Button>
                            <input type="file" onChange={handleImport} className="absolute inset-0 opacity-0 cursor-pointer" accept=".json"/>
                        </div>
                    </div>
                </div>
            </div>

            {/* Main Content */}
            <div className="flex-1 bg-gray-950 overflow-y-auto p-8">
                {tab === 'world' && (
                    <div className="max-w-2xl space-y-6">
                        <h2 className="text-2xl font-bold text-white mb-6">World Settings</h2>
                        <div>
                            <label className="text-xs font-bold text-gray-500 uppercase">World Description</label>
                            <textarea className="w-full bg-gray-900 border border-gray-700 rounded p-2 h-32 text-white" value={props.worldInfo.description} onChange={e => props.onUpdateWorldInfo({ ...props.worldInfo, description: e.target.value })} />
                        </div>
                    </div>
                )}

                {tab === 'chars' && (
                    <div className="flex h-full gap-6">
                        <div className="w-1/3 border-r border-gray-800 pr-4 overflow-y-auto">
                             <Button className="w-full mb-4" onClick={() => {
                                 const id = crypto.randomUUID();
                                 props.onUpdateCharacters([...props.characters, { id, name: 'New Character', defaultDescription: '', rpgColor: '#ffffff' }]);
                                 setSelectedId(id);
                             }}><Plus size={16}/> Add Character</Button>
                             <div className="space-y-2">
                                 {props.characters.map(c => (
                                     <div key={c.id} onClick={() => setSelectedId(c.id)} className={`p-3 rounded cursor-pointer border ${selectedId === c.id ? 'bg-indigo-900/50 border-indigo-500' : 'bg-gray-900 border-gray-800 hover:bg-gray-800'}`}>
                                         <div className="font-bold text-white">{c.name}</div>
                                     </div>
                                 ))}
                             </div>
                        </div>
                        <div className="flex-1 overflow-y-auto">
                             {selectedId && props.characters.find(c => c.id === selectedId) && (
                                 <CharacterEditor 
                                    character={props.characters.find(c => c.id === selectedId)!}
                                    onChange={(u) => props.onUpdateCharacters(props.characters.map(x => x.id === selectedId ? { ...x, ...u } : x))}
                                    onDelete={() => {
                                        props.onUpdateCharacters(props.characters.filter(x => x.id !== selectedId));
                                        setSelectedId(null);
                                    }}
                                 />
                             )}
                        </div>
                    </div>
                )}

                {tab === 'scenes' && (
                    <div className="flex h-full gap-6">
                        <div className="w-1/3 border-r border-gray-800 pr-4 overflow-y-auto">
                             <Button className="w-full mb-4" onClick={() => {
                                 const id = crypto.randomUUID();
                                 props.onUpdateScenes([...props.scenes, { id, name: 'New Scene', description: '', goal: '', characters: [] }]);
                                 setSelectedId(id);
                             }}><Plus size={16}/> Add Scene</Button>
                             <div className="space-y-2">
                                 {props.scenes.map(s => (
                                     <div key={s.id} onClick={() => setSelectedId(s.id)} className={`p-3 rounded cursor-pointer border ${selectedId === s.id ? 'bg-indigo-900/50 border-indigo-500' : 'bg-gray-900 border-gray-800 hover:bg-gray-800'}`}>
                                         <div className="font-bold text-white truncate">{s.name}</div>
                                         <div className="text-xs text-gray-500 truncate">{s.goal || 'No goal'}</div>
                                     </div>
                                 ))}
                             </div>
                        </div>
                        <div className="flex-1 overflow-y-auto">
                             {selectedId && props.scenes.find(s => s.id === selectedId) && (
                                 <SceneEditor 
                                    scene={props.scenes.find(s => s.id === selectedId)!}
                                    allScenes={props.scenes}
                                    allBattles={props.battles}
                                    allMaps={props.maps}
                                    characters={props.characters}
                                    chapters={props.chapters}
                                    onChange={(u) => props.onUpdateScenes(props.scenes.map(x => x.id === selectedId ? { ...x, ...u } : x))}
                                    onDelete={() => {
                                        props.onUpdateScenes(props.scenes.filter(x => x.id !== selectedId));
                                        setSelectedId(null);
                                    }}
                                 />
                             )}
                        </div>
                    </div>
                )}

                {tab === 'maps' && (
                     <div className="flex h-full gap-6">
                        <div className="w-1/3 border-r border-gray-800 pr-4 overflow-y-auto">
                             <Button className="w-full mb-4" onClick={() => {
                                 const id = crypto.randomUUID();
                                 props.onUpdateMaps([...props.maps, { id, name: 'New Map', backgroundSrc: null, spots: [] }]);
                                 setSelectedId(id);
                             }}><Plus size={16}/> Add Map</Button>
                             <div className="space-y-2">
                                 {props.maps.map(m => (
                                     <div key={m.id} onClick={() => setSelectedId(m.id)} className={`p-3 rounded cursor-pointer border ${selectedId === m.id ? 'bg-indigo-900/50 border-indigo-500' : 'bg-gray-900 border-gray-800 hover:bg-gray-800'}`}>
                                         <div className="font-bold text-white">{m.name}</div>
                                     </div>
                                 ))}
                             </div>
                        </div>
                        <div className="flex-1 overflow-y-auto">
                             {selectedId && props.maps.find(m => m.id === selectedId) && (
                                 <MapEditor 
                                    map={props.maps.find(m => m.id === selectedId)!}
                                    scenes={props.scenes}
                                    characters={props.characters}
                                    battles={props.battles}
                                    allMaps={props.maps}
                                    onChange={(u) => props.onUpdateMaps(props.maps.map(x => x.id === selectedId ? { ...x, ...u } : x))}
                                    onDelete={() => {
                                        props.onUpdateMaps(props.maps.filter(x => x.id !== selectedId));
                                        setSelectedId(null);
                                    }}
                                 />
                             )}
                        </div>
                    </div>
                )}

                {tab === 'battles' && (
                     <div className="flex h-full gap-6">
                        <div className="w-1/3 border-r border-gray-800 pr-4 overflow-y-auto">
                             <Button className="w-full mb-4" onClick={() => {
                                 const id = crypto.randomUUID();
                                 props.onUpdateBattles([...props.battles, { id, name: 'New Battle', backgroundSrc: null, playerCharacterIds: [], enemyCharacterIds: [], isRepeatable: false }]);
                                 setSelectedId(id);
                             }}><Plus size={16}/> Add Battle</Button>
                             <div className="space-y-2">
                                 {props.battles.map(b => (
                                     <div key={b.id} onClick={() => setSelectedId(b.id)} className={`p-3 rounded cursor-pointer border ${selectedId === b.id ? 'bg-indigo-900/50 border-indigo-500' : 'bg-gray-900 border-gray-800 hover:bg-gray-800'}`}>
                                         <div className="font-bold text-white">{b.name}</div>
                                     </div>
                                 ))}
                             </div>
                        </div>
                        <div className="flex-1 overflow-y-auto">
                             {selectedId && props.battles.find(b => b.id === selectedId) && (
                                 <BattleEditor 
                                    battle={props.battles.find(b => b.id === selectedId)!}
                                    characters={props.characters}
                                    chapters={props.chapters}
                                    onChange={(u) => props.onUpdateBattles(props.battles.map(x => x.id === selectedId ? { ...x, ...u } : x))}
                                    onDelete={() => {
                                        props.onUpdateBattles(props.battles.filter(x => x.id !== selectedId));
                                        setSelectedId(null);
                                    }}
                                 />
                             )}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};
